window.refreshAdminModifyPricingUI = function() {
  const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(r => r.id === activeResDetailId || String(r.id) === String(activeResDetailId));
  if (!res) return;
  const curPax = (typeof mtPax !== 'undefined' && mtPax > 0) ? mtPax : (parseInt(document.getElementById('edit-ev-pax')?.value) || parseInt(res.pax) || 50);
  const details = computePricingDetails(res, curPax);
  const newBasePrice = details ? details.basePrice : 0;
  const newFinalTotal = details ? details.finalTotal : 0;
  res.amount = newFinalTotal;

  const finAmtEl = document.getElementById('edit-fin-amount');
  if (finAmtEl) finAmtEl.value = newFinalTotal;
  const finAmtDisplay = document.getElementById('edit-fin-amount-display');
  if (finAmtDisplay) finAmtDisplay.textContent = '₱' + newFinalTotal.toLocaleString();

  const totalEl = document.getElementById('edit-fin-total-amount');
  if (totalEl) totalEl.textContent = '₱' + newFinalTotal.toLocaleString();
  const dpValEl = document.getElementById('edit-fin-dp-val');
  if (dpValEl) dpValEl.textContent = '₱' + Math.round(newBasePrice * 0.5).toLocaleString();
  const finalValEl = document.getElementById('edit-fin-final-val');
  if (finalValEl) {
    const _dp = Math.round(newBasePrice * 0.5);
    const _final = (newBasePrice - _dp) + (details ? (details.extraItemsTotal || 0) + (details.otc || 0) + (details.serviceChargeAmt || 0) : 0);
    finalValEl.textContent = '₱' + _final.toLocaleString();
  }

  const totalDisplay = document.getElementById('resd-modify-total-display');
  if (totalDisplay) totalDisplay.textContent = 'Items Subtotal: ₱' + newBasePrice.toLocaleString() + ' | Grand Total: ₱' + newFinalTotal.toLocaleString();
  const extraDisplay = document.getElementById('resd-modify-extra-items-display');
  if (extraDisplay) {
    const extraAmt = details ? (details.extraItemsTotal || 0) : 0;
    const otcAmt = details ? (details.otc || 0) : 0;
    const parts = [];
    if (extraAmt > 0) parts.push('Additional Items: +₱' + extraAmt.toLocaleString());
    if (otcAmt > 0) parts.push('Out-of-Town (5%): +₱' + otcAmt.toLocaleString());
    extraDisplay.textContent = parts.length > 0 ? parts.join(' · ') : 'Out-of-Town Charge: ₱0';
  }

  const pricingCardContainer = document.getElementById('resd-pricing-details-container');
  if (pricingCardContainer) {
    pricingCardContainer.innerHTML = renderPricingDetailsCard(res, curPax, newFinalTotal);
  }
  if (typeof window.updateDynamicModifyOutofTownCharges === 'function') {
    window.updateDynamicModifyOutofTownCharges();
  }
};

window.toggleAdminResdVIP = function(checked) {
  const details = document.getElementById('edit-ev-vip-details');
  if (details) details.style.display = checked ? 'grid' : 'none';
  const errEl = document.getElementById('edit-ev-vip-err');
  if (errEl) errEl.style.display = 'none';
  const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(r => r.id === activeResDetailId || String(r.id) === String(activeResDetailId));
  const curPax = parseInt(document.getElementById('edit-ev-pax')?.value) || (res && parseInt(res.pax)) || 50;
  const vipIn = document.getElementById('edit-ev-vip');
  if (vipIn) {
    vipIn.max = String(curPax);
    if (checked) {
      let v = parseInt(vipIn.value) || 1;
      if (v < 1) v = 1;
      if (v > curPax) v = curPax;
      vipIn.value = String(v);
    }
  }
  if (res) {
    if (!res.vip) res.vip = {};
    res.vip.enabled = checked;
    res.isVIP = checked;
  }
};

window.changeAdminResdEquipmentQty = function(itemIdx, delta) {
  if (!Array.isArray(mtCustomPkgItems) || !mtCustomPkgItems[itemIdx]) return;
  if (typeof getResdOrigin === 'function' && getResdOrigin() !== 'custom') return;
  const item = mtCustomPkgItems[itemIdx];
  const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(r => r.id === activeResDetailId || String(r.id) === String(activeResDetailId));
  const pCount = (typeof mtPax !== 'undefined' && mtPax > 0) ? mtPax : (parseInt(document.getElementById('edit-ev-pax')?.value) || (res && parseInt(res.pax)) || 50);

  let curQ = item.customQty != null ? parseInt(item.customQty) : (item.autoQty != null ? parseInt(item.autoQty) : null);
  if (curQ === null || isNaN(curQ)) {
    const catEntry = typeof CAT !== 'undefined' ? CAT.find(c => c.name.toLowerCase() === (item.name || '').toLowerCase()) : null;
    const resolvedItem = Object.assign({}, catEntry || {}, item);
    curQ = typeof getEquipmentAllocatedQty === 'function' ? getEquipmentAllocatedQty(resolvedItem, pCount, mtCustomPkgItems) : 1;
  }
  const newQ = Math.max(1, Math.min(999, curQ + delta));
  const unitP = parseFloat(item.price) || 0;
  const newSnap = unitP * newQ;

  const budgetVal = parseFloat(document.getElementById('edit-ev-budget')?.value) || 0;
  if (budgetVal > 0 && delta > 0 && res) {
    const prevQ = item.customQty;
    const prevSnap = item.snapshotPrice;
    item.customQty = newQ;
    item.snapshotPrice = newSnap;
    const testPricing = computePricingDetails(res, pCount);
    if (testPricing && testPricing.finalTotal > budgetVal) {
      item.customQty = prevQ;
      item.snapshotPrice = prevSnap;
      if (typeof showToast === 'function') showToast('Increasing this quantity exceeds the Target Budget of ₱' + budgetVal.toLocaleString() + '.', 'warning');
      return;
    }
  }

  item.customQty = newQ;
  item.quantity = newQ;
  item.isCustomized = true;
  item.snapshotPrice = newSnap;
  window.refreshAdminModifyPricingUI();
  if (typeof renderResdCatalog === 'function') renderResdCatalog();
};

window.setAdminResdEquipmentQty = function(itemIdx, rawVal) {
  if (!Array.isArray(mtCustomPkgItems) || !mtCustomPkgItems[itemIdx]) return;
  if (typeof getResdOrigin === 'function' && getResdOrigin() !== 'custom') return;
  const item = mtCustomPkgItems[itemIdx];
  const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(r => r.id === activeResDetailId || String(r.id) === String(activeResDetailId));
  const pCount = (typeof mtPax !== 'undefined' && mtPax > 0) ? mtPax : (parseInt(document.getElementById('edit-ev-pax')?.value) || (res && parseInt(res.pax)) || 50);
  let newQ = parseInt(rawVal);
  if (isNaN(newQ) || newQ < 1) newQ = 1;
  if (newQ > 999) newQ = 999;
  const unitP = parseFloat(item.price) || 0;
  const newSnap = unitP * newQ;

  const budgetVal = parseFloat(document.getElementById('edit-ev-budget')?.value) || 0;
  if (budgetVal > 0 && res) {
    const prevQ = item.customQty;
    const prevSnap = item.snapshotPrice;
    item.customQty = newQ;
    item.snapshotPrice = newSnap;
    const testPricing = computePricingDetails(res, pCount);
    if (testPricing && testPricing.finalTotal > budgetVal) {
      item.customQty = prevQ;
      item.snapshotPrice = prevSnap;
      if (typeof showToast === 'function') showToast('Setting this quantity exceeds the Target Budget of ₱' + budgetVal.toLocaleString() + '.', 'warning');
      if (typeof renderResdCatalog === 'function') renderResdCatalog();
      return;
    }
  }

  item.customQty = newQ;
  item.quantity = newQ;
  item.isCustomized = true;
  item.snapshotPrice = newSnap;
  window.refreshAdminModifyPricingUI();
  if (typeof renderResdCatalog === 'function') renderResdCatalog();
};

window.toggleAdminFoodCustomize = function(itemIdx) {
  if (!Array.isArray(mtCustomPkgItems) || !mtCustomPkgItems[itemIdx]) return;
  const item = mtCustomPkgItems[itemIdx];
  item._showCustomize = !item._showCustomize;
  if (typeof renderResdCatalog === 'function') renderResdCatalog();
};

window.updateAdminFoodPax = function(itemIdx, val) {
  if (!Array.isArray(mtCustomPkgItems) || !mtCustomPkgItems[itemIdx]) return;
  if (typeof getResdOrigin === 'function' && getResdOrigin() !== 'custom') return;
  const item = mtCustomPkgItems[itemIdx];
  const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(r => r.id === activeResDetailId || String(r.id) === String(activeResDetailId));
  const maxPax = parseInt(document.getElementById('edit-ev-pax')?.value) || (typeof mtPax !== 'undefined' && mtPax > 0 ? mtPax : (res && parseInt(res.pax)) || 50);
  let p = parseInt(val);
  if (isNaN(p) || p <= 0) {
    item.customPax = null;
  } else {
    if (p < 1) p = 1;
    // Allow pax customization to go above the base reservation pax up to 3 digits (limit 999)
    if (p > 999) {
      p = 999;
      if (typeof showToast === 'function') showToast('Portion pax cannot exceed 3 digits (999 pax).', 'warning');
    }
    item.customPax = p;
  }
  item.isCustomized = !!(item.customPax || (item.specifications && String(item.specifications).trim()));
  const unitP = parseFloat(item.price) || 0;
  const effPax = item.customPax || maxPax;
  const catEntry = typeof CAT !== 'undefined' ? CAT.find(c => (c.id && String(c.id) === String(item.id)) || (c.name && c.name.toLowerCase() === (item.name || '').toLowerCase())) : null;
  if (item.customPax) {
    item.snapshotPrice = (catEntry && typeof getDynamicPrice === 'function') ? getDynamicPrice(catEntry, effPax) : (unitP * effPax);
  } else {
    item.snapshotPrice = (catEntry && typeof getDynamicPrice === 'function') ? getDynamicPrice(catEntry, maxPax) : (unitP * maxPax);
  }
  window.refreshAdminModifyPricingUI();
  if (typeof renderResdCatalog === 'function') renderResdCatalog();
};

window.resetAdminResdItemCustomization = function(itemIdx) {
  if (!Array.isArray(mtCustomPkgItems) || !mtCustomPkgItems[itemIdx]) return;
  const item = mtCustomPkgItems[itemIdx];
  const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(r => r.id === activeResDetailId || String(r.id) === String(activeResDetailId));
  const curPax = parseInt(document.getElementById('edit-ev-pax')?.value) || (typeof mtPax !== 'undefined' && mtPax > 0 ? mtPax : (res && parseInt(res.pax)) || 50);
  const isEq = (item.cat || item.category || '').toLowerCase() === 'equipment';
  const catEntry = typeof CAT !== 'undefined' ? CAT.find(c => (c.id && String(c.id) === String(item.id)) || (c.name && c.name.toLowerCase() === (item.name || '').toLowerCase())) : null;

  if (isEq) {
    const resolved = Object.assign({}, catEntry || {}, item, { customQty: null });
    const autoQ = typeof getEquipmentAllocatedQty === 'function' ? getEquipmentAllocatedQty(resolved, curPax, mtCustomPkgItems) : 1;
    item.autoQty = autoQ;
    item.customQty = autoQ;
    item.quantity = autoQ;
    item.snapshotPrice = (parseFloat(item.price) || 0) * autoQ;
  } else {
    item.customPax = null;
    item.snapshotPrice = (catEntry && typeof getDynamicPrice === 'function') ? getDynamicPrice(catEntry, curPax) : ((parseFloat(item.price) || 0) * curPax);
  }
  item.specifications = '';
  item.isCustomized = false;
  window.refreshAdminModifyPricingUI();
  if (typeof renderResdCatalog === 'function') renderResdCatalog();
};

window.updateAdminResdItemSpecs = function(itemIdx, val) {
  if (!Array.isArray(mtCustomPkgItems) || !mtCustomPkgItems[itemIdx]) return;
  const item = mtCustomPkgItems[itemIdx];
  item.specifications = val;
  item.isCustomized = !!(item.customPax != null || (val && String(val).trim().length > 0));
};

function getLocalDeviceTimeStr() {
  const d = new Date();
  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}:${String(d.getSeconds()).padStart(2, '0')}`;
}

function getLocalTimeFromIso(isoStr) {
  if (!isoStr) return null;
  try {
    const d = new Date(isoStr);
    if (isNaN(d.getTime())) return null;
    return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
  } catch (e) {
    return null;
  }
}
window.getLocalDeviceTimeStr = getLocalDeviceTimeStr;
window.getLocalTimeFromIso = getLocalTimeFromIso;


