window.HARD_DISABLED_DAYS = [
  { id: 'monday', day_name: 'Monday', day_of_week: 1, is_disabled: false },
  { id: 'tuesday', day_name: 'Tuesday', day_of_week: 2, is_disabled: false },
  { id: 'wednesday', day_name: 'Wednesday', day_of_week: 3, is_disabled: false },
  { id: 'thursday', day_name: 'Thursday', day_of_week: 4, is_disabled: false },
  { id: 'friday', day_name: 'Friday', day_of_week: 5, is_disabled: false },
  { id: 'saturday', day_name: 'Saturday', day_of_week: 6, is_disabled: false },
  { id: 'sunday', day_name: 'Sunday', day_of_week: 0, is_disabled: false }
];

async function loadHardDisabledDays() {
  try {
    const saved = localStorage.getItem('smartserve_hard_disabled_days');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (Array.isArray(parsed) && parsed.length > 0) {
        window.HARD_DISABLED_DAYS = parsed;
      }
    }
  } catch (e) {}

  try {
    const sb = window.supabaseClient || window.supabase;
    if (sb) {
      const { data, error } = await sb.from('hard_disabled_days').select('*').order('day_of_week', { ascending: true });
      if (!error && Array.isArray(data) && data.length > 0) {
        const remoteMap = new Map();
        data.forEach(d => remoteMap.set(d.id, d));
        window.HARD_DISABLED_DAYS = window.HARD_DISABLED_DAYS.map(def => {
          const remote = remoteMap.get(def.id);
          return remote ? { ...def, ...remote, is_disabled: !!remote.is_disabled } : def;
        });
        localStorage.setItem('smartserve_hard_disabled_days', JSON.stringify(window.HARD_DISABLED_DAYS));
      }
    }
  } catch (e) {
    // Supabase table may need to be created via provided SQL migration
  }
  renderAdminHardDisableGrid();
  return window.HARD_DISABLED_DAYS;
}
window.loadHardDisabledDays = loadHardDisabledDays;

function isDayHardDisabled(dateVal) {
  if (!dateVal) return false;
  let d = null;
  if (dateVal instanceof Date) d = dateVal;
  else if (typeof dateVal === 'string') {
    const parts = dateVal.split('-');
    if (parts.length === 3) d = new Date(parseInt(parts[0], 10), parseInt(parts[1], 10) - 1, parseInt(parts[2], 10));
    else d = new Date(dateVal);
  }
  if (!d || isNaN(d.getTime())) return false;
  const dow = d.getDay();
  const list = window.HARD_DISABLED_DAYS;
  if (Array.isArray(list)) {
    const match = list.find(x => x.day_of_week === dow);
    if (match && match.is_disabled) return true;
  }
  try {
    const saved = localStorage.getItem('smartserve_hard_disabled_days');
    if (saved) {
      const parsed = JSON.parse(saved);
      if (Array.isArray(parsed)) {
        const match = parsed.find(x => x.day_of_week === dow);
        if (match && match.is_disabled) return true;
      }
    }
  } catch (e) {}
  return false;
}
window.isDayHardDisabled = isDayHardDisabled;

function renderAdminHardDisableGrid() {
  const gridEl = document.getElementById('admin-hard-disable-grid');
  if (!gridEl) return;
  const daysOrder = [
    { id: 'monday', name: 'Monday', dayIndex: 1 },
    { id: 'tuesday', name: 'Tuesday', dayIndex: 2 },
    { id: 'wednesday', name: 'Wednesday', dayIndex: 3 },
    { id: 'thursday', name: 'Thursday', dayIndex: 4 },
    { id: 'friday', name: 'Friday', dayIndex: 5 },
    { id: 'saturday', name: 'Saturday', dayIndex: 6 },
    { id: 'sunday', name: 'Sunday', dayIndex: 0 }
  ];

  gridEl.innerHTML = daysOrder.map(d => {
    const state = (window.HARD_DISABLED_DAYS || []).find(x => x.id === d.id);
    const isDisabled = state ? !!state.is_disabled : false;

    return `
      <div class="availability-day-card ${isDisabled ? 'disabled-day' : ''}" style="min-height:140px; justify-content:space-between; padding:16px;">
        <div class="availability-day-header" style="margin-bottom:8px; border-bottom:1px solid rgba(196,154,60,0.15); padding-bottom:6px;">
          <span style="font-weight:700; font-size:13px; color:var(--text);">${d.name}</span>
          <span style="font-size:11px; font-weight:700; color:${isDisabled ? '#ef4444' : 'var(--gold, #c49a3c)'}; text-transform:uppercase;">
            ${isDisabled ? 'Hard Disabled' : 'Active'}
          </span>
        </div>
        <div style="font-size:11px; color:var(--text-dim); line-height:1.4; margin-bottom:12px;">
          ${isDisabled ? 'All dates on this day are blocked for bookings and meetings.' : 'Available for event bookings and meetings.'}
        </div>
        <button type="button" class="btn btn-sm ${isDisabled ? 'btn-gold' : 'btn-outline'}" onclick="toggleHardDisableDay('${d.id}')" style="width:100%; padding:7px 0; font-size:12px; font-weight:700; cursor:pointer;">
          ${isDisabled ? 'Enable' : 'Disable'}
        </button>
      </div>
    `;
  }).join('');
}
window.renderAdminHardDisableGrid = renderAdminHardDisableGrid;

async function toggleHardDisableDay(dayId) {
  let day = (window.HARD_DISABLED_DAYS || []).find(d => d.id === dayId);
  if (!day) return;
  day.is_disabled = !day.is_disabled;
  localStorage.setItem('smartserve_hard_disabled_days', JSON.stringify(window.HARD_DISABLED_DAYS));
  renderAdminHardDisableGrid();

  const statusEl = document.getElementById('hard-disable-save-status');
  if (statusEl) statusEl.textContent = 'Saving...';

  try {
    const payload = {
      id: day.id,
      day_name: day.day_name || day.name,
      day_of_week: day.day_of_week,
      is_disabled: day.is_disabled,
      updated_at: new Date().toISOString()
    };
    const sb = window.supabaseClient || window.supabase;
    if (sb) {
      await sb.from('hard_disabled_days').upsert(payload, { onConflict: 'id' });
    }
    if (window.supabaseBackupClient) {
      try {
        await window.supabaseBackupClient.from('hard_disabled_days').upsert(payload, { onConflict: 'id' });
      } catch (e) {}
    }
  } catch (err) {
    console.warn('toggleHardDisableDay error:', err);
  }

  if (statusEl) {
    statusEl.textContent = 'Saved';
    setTimeout(() => { if (statusEl) statusEl.textContent = ''; }, 2000);
  }

  if (typeof refreshCalendarDisabledCells === 'function') refreshCalendarDisabledCells();
  if (typeof renderCustomEventCalendar === 'function') renderCustomEventCalendar();
}
window.toggleHardDisableDay = toggleHardDisableDay;

// ==================== CALENDAR MODAL CONTROLLER (ADMIN) ====================
window._customCalYear = null;
window._customCalMonth = null;

function openCustomEventDateCalendarModal(targetYear, targetMonth) {
  const modal = document.getElementById('custom-event-date-modal');
  const backdrop = document.getElementById('custom-event-date-backdrop');
  if (!modal || !backdrop) return;

  const now = new Date();
  const curVal = document.getElementById('edit-vn-date')?.value || '';
  
  if (typeof targetYear === 'number' && typeof targetMonth === 'number') {
    window._customCalYear = targetYear;
    window._customCalMonth = targetMonth;
  } else if (curVal && /^\d{4}-\d{2}-\d{2}$/.test(curVal)) {
    const parts = curVal.split('-').map(Number);
    window._customCalYear = parts[0];
    window._customCalMonth = parts[1] - 1;
  } else if (window._customCalYear === null) {
    window._customCalYear = now.getFullYear();
    window._customCalMonth = now.getMonth();
  }

  renderCustomEventCalendar();
  backdrop.style.display = 'block';
  modal.style.display = 'block';
}
window.openCustomEventDateCalendarModal = openCustomEventDateCalendarModal;

function closeCustomEventDateCalendarModal() {
  const modal = document.getElementById('custom-event-date-modal');
  const backdrop = document.getElementById('custom-event-date-backdrop');
  if (modal) modal.style.display = 'none';
  if (backdrop) backdrop.style.display = 'none';
}
window.closeCustomEventDateCalendarModal = closeCustomEventDateCalendarModal;

function populateCustomCalYearSelect(selectEl, baseYear, selectedYear) {
  if (!selectEl) return;
  const startY = baseYear || new Date().getFullYear();
  const endY = startY + 50;
  let opts = '';
  for (let yr = startY; yr <= endY; yr++) {
    const sel = (selectedYear && parseInt(selectedYear, 10) === yr) ? ' selected' : '';
    opts += `<option value="${yr}"${sel}>${yr}</option>`;
  }
  selectEl.innerHTML = opts;
  if (selectedYear) {
    selectEl.value = String(selectedYear);
  }
}
window.populateCustomCalYearSelect = populateCustomCalYearSelect;

function onCustomCalSelectChange() {
  const mSel = document.getElementById('custom-cal-month-select');
  const ySel = document.getElementById('custom-cal-year-select');
  if (!mSel || !ySel) return;
  const now = new Date();
  let y = parseInt(ySel.value, 10);
  let m = parseInt(mSel.value, 10);
  if (isNaN(y)) y = now.getFullYear();
  if (isNaN(m)) m = now.getMonth();

  const maxLimitYear = now.getFullYear() + 50;
  if (y > maxLimitYear) {
    y = maxLimitYear;
    ySel.value = String(y);
  } else if (y < now.getFullYear()) {
    y = now.getFullYear();
    ySel.value = String(y);
  }

  window._customCalYear = y;
  window._customCalMonth = m;
  renderCustomEventCalendar();
}
window.onCustomCalSelectChange = onCustomCalSelectChange;

function renderCustomEventCalendar() {
  const y = window._customCalYear;
  const m = window._customCalMonth;
  const now = new Date();
  const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  
  const gridEl = document.getElementById('custom-cal-days-grid');
  const prevBtn = document.getElementById('btn-custom-cal-prev');
  const nextBtn = document.getElementById('btn-custom-cal-next');

  const mSel = document.getElementById('custom-cal-month-select');
  const ySel = document.getElementById('custom-cal-year-select');

  if (mSel && ySel) {
    if (!ySel.options || ySel.options.length === 0 || !ySel.querySelector(`option[value="${y}"]`)) {
      populateCustomCalYearSelect(ySel, now.getFullYear(), y);
    }
    ySel.value = String(y);
    Array.from(mSel.options).forEach(opt => { opt.disabled = false; });
    mSel.value = String(m);
  }

  if (prevBtn) {
    prevBtn.disabled = (y <= now.getFullYear() && m <= 0);
  }
  if (nextBtn) {
    const maxLimitYear2 = now.getFullYear() + 50;
    nextBtn.disabled = (y >= maxLimitYear2 && m >= 11);
  }

  if (!gridEl) return;

  const resCountMap = {};
  const allRes = (Array.isArray(window.RESERVATIONS) ? window.RESERVATIONS : []);
  allRes.forEach(r => {
    const st = String(r.status || '').toLowerCase().trim();
    if (st === 'cancelled' || st === 'rejected') return;
    const dKey = (r.date ? String(r.date).split('T')[0] : null);
    if (dKey) {
      resCountMap[dKey] = (resCountMap[dKey] || 0) + 1;
    }
  });

  const selectedDateVal = document.getElementById('edit-vn-date')?.value || '';
  const firstDay = new Date(y, m, 1).getDay();
  const daysInMonth = new Date(y, m + 1, 0).getDate();

  let html = '';
  for (let i = 0; i < firstDay; i++) {
    html += '<div class="custom-cal-day-cell cal-day-empty"></div>';
  }

  const minEventDateObj = new Date(now.getFullYear(), now.getMonth(), now.getDate() + 14);
  const minEventDateStr = `${minEventDateObj.getFullYear()}-${String(minEventDateObj.getMonth() + 1).padStart(2, '0')}-${String(minEventDateObj.getDate()).padStart(2, '0')}`;
  const maxEventDateObj = new Date(now.getFullYear() + 50, now.getMonth(), now.getDate());
  const maxEventDateStr = `${maxEventDateObj.getFullYear()}-${String(maxEventDateObj.getMonth() + 1).padStart(2, '0')}-${String(maxEventDateObj.getDate()).padStart(2, '0')}`;

  for (let dayNum = 1; dayNum <= daysInMonth; dayNum++) {
    const dateKey = `${y}-${String(m + 1).padStart(2, '0')}-${String(dayNum).padStart(2, '0')}`;
    const isPast = (dateKey < todayStr);
    const isWithin14Days = (!isPast && dateKey < minEventDateStr);
    const isBeyond50Years = (!isPast && dateKey > maxEventDateStr);
    const count = resCountMap[dateKey] || 0;
    const isDisabledByAdmin = (window.DISABLED_CALENDAR_DATES && window.DISABLED_CALENDAR_DATES.has(dateKey));
    const isHardDisabled = (typeof isDayHardDisabled === 'function' && isDayHardDisabled(dateKey));
    const isLockedFull = (count >= 3);
    const isSelected = (selectedDateVal === dateKey);

    let cellClasses = ['custom-cal-day-cell'];
    let badgeText = '';

    if (isPast) {
      cellClasses.push('cal-day-past');
      badgeText = '<span class="custom-cal-day-badge">Past</span>';
    } else if (isWithin14Days) {
      cellClasses.push('cal-day-locked cal-day-near');
      badgeText = '<span class="custom-cal-day-badge">Within 14 Days</span>';
    } else if (isBeyond50Years) {
      cellClasses.push('cal-day-disabled');
      badgeText = '<span class="custom-cal-day-badge">Beyond 50 Yrs</span>';
    } else if (isHardDisabled) {
      cellClasses.push('cal-day-disabled');
      badgeText = '<span class="custom-cal-day-badge">Hard Disabled</span>';
    } else if (isDisabledByAdmin) {
      cellClasses.push('cal-day-disabled');
      badgeText = '<span class="custom-cal-day-badge">Unavailable</span>';
    } else if (isLockedFull) {
      cellClasses.push('cal-day-locked');
      badgeText = '<span class="custom-cal-day-badge">Locked (3/3)</span>';
    } else if (count === 2) {
      cellClasses.push('cal-day-2events');
      badgeText = '<span class="custom-cal-day-badge">2 events</span>';
    } else if (count === 1) {
      cellClasses.push('cal-day-1event');
      badgeText = '<span class="custom-cal-day-badge">1 event</span>';
    } else {
      cellClasses.push('cal-day-avail');
      badgeText = '<span class="custom-cal-day-badge">Available</span>';
    }

    if (isSelected) {
      cellClasses.push('cal-day-selected');
    }

    const clickAttr = (!isPast && !isWithin14Days && !isBeyond50Years && !isHardDisabled && !isDisabledByAdmin && !isLockedFull)
      ? `onclick="selectCustomEventDate('${dateKey}')"`
      : '';

    html += `
      <div class="${cellClasses.join(' ')}" ${clickAttr} title="${dateKey}: ${count} reservation(s)">
        <span class="custom-cal-day-num">${dayNum}</span>
        ${badgeText}
      </div>
    `;
  }

  gridEl.innerHTML = html;
}
window.renderCustomEventCalendar = renderCustomEventCalendar;

function selectCustomEventDate(dateKey) {
  if (typeof isDayHardDisabled === 'function' && isDayHardDisabled(dateKey)) {
    alert('This day of the week has been hard disabled for bookings and meetings.');
    return;
  }
  const dateInput = document.getElementById('edit-vn-date');
  if (dateInput) {
    dateInput.value = dateKey;
    const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(r => r.id === activeResDetailId);
    if (res) res.date = dateKey;
  }
  closeCustomEventDateCalendarModal();
}
window.selectCustomEventDate = selectCustomEventDate;

window.navCustomCal = function(dir) {
  if (window._customCalYear === null) {
    const now = new Date();
    window._customCalYear = now.getFullYear();
    window._customCalMonth = now.getMonth();
  }
  let m = window._customCalMonth + dir;
  let y = window._customCalYear;
  if (m < 0) { m = 11; y--; }
  else if (m > 11) { m = 0; y++; }
  window._customCalYear = y;
  window._customCalMonth = m;
  renderCustomEventCalendar();
};

async function saveAdminAvailabilityDay(day) {
  try {
    localStorage.setItem('halden_admin_meeting_availability', JSON.stringify(window.ADMIN_AVAILABILITY));
    const statusEl = document.getElementById('availability-save-status');
    if (statusEl) statusEl.textContent = 'Saving...';
    const payload = {
      id: day.id,
      day_name: day.day_name,
      day_of_week: day.day_of_week,
      is_disabled: day.is_disabled,
      time_slots: day.time_slots,
      updated_at: new Date().toISOString()
    };
    const sb = window.supabaseClient || window.supabase;
    if (sb) {
      const { error } = await sb.from('admin_meeting_availability').upsert(payload, { onConflict: 'id' });
      if (error) console.warn('[Admin Availability] Primary Supabase save warning:', error.message);
    }
    if (window.supabaseBackupClient) {
      try {
        await window.supabaseBackupClient.from('admin_meeting_availability').upsert(payload, { onConflict: 'id' });
      } catch (e) {}
    }
    if (statusEl) {
      statusEl.textContent = 'Saved';
      setTimeout(() => { if (statusEl) statusEl.textContent = ''; }, 2000);
    }
  } catch (e) {
    console.warn('[Admin Availability] Save error:', e);
  }
}

function adminTime24ToAMPM(val24) {
  if (!val24) return '';
  const parts = val24.split(':');
  let h = parseInt(parts[0], 10);
  const m = parts[1] || '00';
  if (isNaN(h)) return val24;
  const ampm = h >= 12 ? 'PM' : 'AM';
  h = h % 12;
  if (h === 0) h = 12;
  return `${h}:${m} ${ampm}`;
}

function adminTimeAMPMTo24(ampmStr) {
  if (!ampmStr) return '09:00';
  const match = ampmStr.trim().match(/^(\d{1,2}):(\d{2})\s*(AM|PM)?$/i);
  if (!match) {
    if (/^\d{1,2}:\d{2}$/.test(ampmStr.trim())) return ampmStr.trim().padStart(5, '0');
    return '09:00';
  }
  let h = parseInt(match[1], 10);
  const m = match[2];
  const ampm = (match[3] || 'AM').toUpperCase();
  if (ampm === 'PM' && h < 12) h += 12;
  if (ampm === 'AM' && h === 12) h = 0;
  return `${String(h).padStart(2, '0')}:${m}`;
}

function adminTimeToMinutes(str) {
  if (!str) return 0;
  const t24 = adminTimeAMPMTo24(str);
  const parts = t24.split(':');
  return parseInt(parts[0], 10) * 60 + parseInt(parts[1] || 0, 10);
}

function parseAdminTimeSlotRange(slotStr) {
  if (!slotStr) return null;
  let startStr = '', endStr = '';
  if (slotStr.includes(' to ')) {
    const p = slotStr.split(' to ');
    startStr = p[0].trim();
    endStr = p[1].trim();
  } else if (slotStr.includes(' - ')) {
    const p = slotStr.split(' - ');
    startStr = p[0].trim();
    endStr = p[1].trim();
  }
  if (!startStr || !endStr) return null;
  return {
    startStr,
    endStr,
    startMin: adminTimeToMinutes(startStr),
    endMin: adminTimeToMinutes(endStr)
  };
}

function isTimeRangeCrossing(s1, e1, s2, e2) {
  return Math.max(s1, s2) < Math.min(e1, e2);
}

function renderAdminAvailabilityGrid() {
  const container = document.getElementById('admin-availability-grid');
  if (!container) return;
  const days = window.ADMIN_AVAILABILITY || window.DEFAULT_ADMIN_AVAILABILITY;
  
  container.innerHTML = days.map(day => {
    const isDis = !!day.is_disabled;
    const slots = Array.isArray(day.time_slots) ? day.time_slots : [];
    
    let slotsHtml = '';
    if (isDis) {
      slotsHtml = '<div style="font-size:11px;color:#ef4444;font-style:italic;padding:8px 0;">Day disabled for meetings</div>';
    } else if (slots.length === 0) {
      slotsHtml = '<div style="font-size:11px;color:var(--text-dim);font-style:italic;padding:8px 0;">No time slots added</div>';
    } else {
      slotsHtml = slots.map((slot, idx) => `
        <div class="time-slot-item">
          <span>${slot}</span>
          <div style="display:flex; align-items:center; gap:6px;">
            <button type="button" class="btn-edit-slot" onclick="openAdminEditTimeModal('${day.id}', ${idx})" title="Edit time">
              <i class="fas fa-pencil-alt" style="font-size:11px;"></i>
            </button>
            <button type="button" class="btn-remove-slot" onclick="removeAdminTimeSlot('${day.id}', ${idx})" title="Remove time">&times;</button>
          </div>
        </div>
      `).join('');
    }

    const actionBtnHtml = isDis ? '' : `
      <button type="button" class="btn-add-time-slot" onclick="openAdminAddTimeModal('${day.id}')">
        ${slots.length === 0 ? '+ Add Time' : '+ Add Another'}
      </button>
    `;

    return `
      <div class="availability-day-card ${isDis ? 'disabled-day' : ''}" id="avail-card-${day.id}">
        <div class="availability-day-header">
          <div class="availability-day-name">${day.day_name}</div>
          <button type="button" class="btn-toggle-day ${isDis ? 'btn-enable' : 'btn-disable'}" onclick="toggleDayAvailability('${day.id}')">
            ${isDis ? 'Enable' : 'Disable'}
          </button>
        </div>
        <div class="time-slot-list">
          ${slotsHtml}
        </div>
        ${actionBtnHtml}
      </div>
    `;
  }).join('');
}

function toggleDayAvailability(dayId) {
  const day = (window.ADMIN_AVAILABILITY || []).find(d => d.id === dayId);
  if (!day) return;
  day.is_disabled = !day.is_disabled;
  saveAdminAvailabilityDay(day);
  renderAdminAvailabilityGrid();
}

function removeAdminTimeSlot(dayId, slotIdx) {
  const day = (window.ADMIN_AVAILABILITY || []).find(d => d.id === dayId);
  if (!day || !Array.isArray(day.time_slots)) return;
  day.time_slots.splice(slotIdx, 1);
  saveAdminAvailabilityDay(day);
  renderAdminAvailabilityGrid();
}

function updateAdminTimePreview() {
  const startVal = document.getElementById('admin-time-start')?.value;
  const endVal = document.getElementById('admin-time-end')?.value;
  const startPrev = document.getElementById('admin-time-start-preview');
  const endPrev = document.getElementById('admin-time-end-preview');
  if (startPrev) startPrev.textContent = startVal ? adminTime24ToAMPM(startVal) : '';
  if (endPrev) endPrev.textContent = endVal ? adminTime24ToAMPM(endVal) : '';
}

function openAdminAddTimeModal(dayId) {
  const day = (window.ADMIN_AVAILABILITY || []).find(d => d.id === dayId);
  if (!day) return;
  const modal = document.getElementById('admin-time-modal');
  const overlay = document.getElementById('admin-time-modal-overlay');
  const title = document.getElementById('admin-time-modal-title');
  const dayInput = document.getElementById('admin-time-day-id');
  const editIdxInput = document.getElementById('admin-time-edit-index');
  const startInput = document.getElementById('admin-time-start');
  const endInput = document.getElementById('admin-time-end');
  const errEl = document.getElementById('admin-time-modal-error');
  const saveBtn = document.getElementById('admin-time-modal-save-btn');
  if (!modal || !overlay) return;
  
  if (title) title.textContent = 'Add Time for ' + day.day_name;
  if (saveBtn) saveBtn.textContent = 'Save Time';
  if (dayInput) dayInput.value = day.id;
  if (editIdxInput) editIdxInput.value = '';
  if (startInput) startInput.value = '13:00';
  if (endInput) endInput.value = '17:00';
  updateAdminTimePreview();
  if (errEl) { errEl.style.display = 'none'; errEl.textContent = ''; }
  
  overlay.classList.add('on');
  modal.classList.add('open');
}

function openAdminEditTimeModal(dayId, slotIdx) {
  const day = (window.ADMIN_AVAILABILITY || []).find(d => d.id === dayId);
  if (!day || !Array.isArray(day.time_slots) || !day.time_slots[slotIdx]) return;
  const slotStr = day.time_slots[slotIdx];
  const parsed = parseAdminTimeSlotRange(slotStr);
  
  const modal = document.getElementById('admin-time-modal');
  const overlay = document.getElementById('admin-time-modal-overlay');
  const title = document.getElementById('admin-time-modal-title');
  const dayInput = document.getElementById('admin-time-day-id');
  const editIdxInput = document.getElementById('admin-time-edit-index');
  const startInput = document.getElementById('admin-time-start');
  const endInput = document.getElementById('admin-time-end');
  const errEl = document.getElementById('admin-time-modal-error');
  const saveBtn = document.getElementById('admin-time-modal-save-btn');
  if (!modal || !overlay) return;
  
  if (title) title.textContent = 'Edit Time for ' + day.day_name;
  if (saveBtn) saveBtn.textContent = 'Update Time';
  if (dayInput) dayInput.value = day.id;
  if (editIdxInput) editIdxInput.value = String(slotIdx);
  if (startInput) startInput.value = parsed ? adminTimeAMPMTo24(parsed.startStr) : '13:00';
  if (endInput) endInput.value = parsed ? adminTimeAMPMTo24(parsed.endStr) : '17:00';
  updateAdminTimePreview();
  if (errEl) { errEl.style.display = 'none'; errEl.textContent = ''; }
  
  overlay.classList.add('on');
  modal.classList.add('open');
}

function closeAdminAddTimeModal() {
  const modal = document.getElementById('admin-time-modal');
  const overlay = document.getElementById('admin-time-modal-overlay');
  if (overlay) overlay.classList.remove('on');
  if (modal) modal.classList.remove('open');
}

function setAdminTimePreset(start24, end24) {
  const startInput = document.getElementById('admin-time-start');
  const endInput = document.getElementById('admin-time-end');
  if (startInput) startInput.value = start24;
  if (endInput) endInput.value = end24;
  updateAdminTimePreview();
}

function saveAdminAddTimeSlot() {
  const dayId = document.getElementById('admin-time-day-id')?.value;
  const editIdxStr = document.getElementById('admin-time-edit-index')?.value;
  const startVal = document.getElementById('admin-time-start')?.value.trim();
  const endVal = document.getElementById('admin-time-end')?.value.trim();
  const errEl = document.getElementById('admin-time-modal-error');
  
  if (!dayId) return;
  const day = (window.ADMIN_AVAILABILITY || []).find(d => d.id === dayId);
  if (!day) return;
  
  if (!startVal || !endVal) {
    if (errEl) { errEl.textContent = 'Please choose both start and end times.'; errEl.style.display = 'block'; }
    return;
  }
  
  const startMin = adminTimeToMinutes(startVal);
  const endMin = adminTimeToMinutes(endVal);
  
  if (startMin >= endMin) {
    if (errEl) { errEl.textContent = 'End time must be later than start time.'; errEl.style.display = 'block'; }
    return;
  }
  
  const startAMPM = adminTime24ToAMPM(startVal);
  const endAMPM = adminTime24ToAMPM(endVal);
  const slotStr = `${startAMPM} to ${endAMPM}`;
  
  if (!Array.isArray(day.time_slots)) day.time_slots = [];
  const editIdx = (editIdxStr !== '' && !isNaN(parseInt(editIdxStr, 10))) ? parseInt(editIdxStr, 10) : -1;
  
  // Overlap and Crossing Validation against other slots of this day
  for (let i = 0; i < day.time_slots.length; i++) {
    if (i === editIdx) continue;
    const existing = parseAdminTimeSlotRange(day.time_slots[i]);
    if (existing) {
      if (isTimeRangeCrossing(startMin, endMin, existing.startMin, existing.endMin)) {
        if (errEl) {
          errEl.textContent = `This time range crosses with an existing slot (${day.time_slots[i]}). Time slots are not allowed to cross or overlap.`;
          errEl.style.display = 'block';
        }
        return;
      }
    }
  }
  
  if (editIdx >= 0 && editIdx < day.time_slots.length) {
    day.time_slots[editIdx] = slotStr;
  } else {
    day.time_slots.push(slotStr);
  }
  
  saveAdminAvailabilityDay(day);
  renderAdminAvailabilityGrid();
  closeAdminAddTimeModal();
}

function refreshCalendarDisabledCells() {
  const calEls = [document.getElementById('dash-calendar'), document.getElementById('calendar')].filter(Boolean);
  if (calEls.length === 0) return;
  const now = new Date();
  const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;

  calEls.forEach(calEl => {
    const cells = calEl.querySelectorAll('.fc-daygrid-day[data-date]');
    cells.forEach(c => {
      const dateKey = c.getAttribute('data-date');
      if (!dateKey || !/^\d{4}-\d{2}-\d{2}$/.test(dateKey)) return;
      const isPast = (dateKey < todayStr);
      const isDis = !isPast && window.DISABLED_CALENDAR_DATES && window.DISABLED_CALENDAR_DATES.has(dateKey);
      c.classList.toggle('fc-day-disabled', !!isDis);

      // Always remove previous label to avoid stale dates or handlers after month navigation
      const oldLbls = c.querySelectorAll('.fc-day-disable-label');
      oldLbls.forEach(l => l.remove());

      if (!isPast) {
        const topEl = c.querySelector('.fc-daygrid-day-top') || c.querySelector('.fc-daygrid-day-frame') || c;
        const lbl = document.createElement('label');
        lbl.className = 'fc-day-disable-label';
        lbl.title = 'Disable booking and meetings for ' + dateKey;
        lbl.onclick = function(e) {
          if (e.target && e.target.tagName !== 'INPUT') {
            e.preventDefault();
            e.stopPropagation();
            const input = lbl.querySelector('.fc-disable-chk');
            if (input) {
              input.checked = !input.checked;
              toggleAdminCalendarDateDisabled(dateKey, input.checked);
            }
          } else {
            e.stopPropagation();
          }
        };
        lbl.innerHTML = `<input type="checkbox" class="fc-disable-chk" data-date="${dateKey}" ${isDis ? 'checked' : ''} onclick="event.stopPropagation()" onchange="event.stopPropagation(); toggleAdminCalendarDateDisabled('${dateKey}', this.checked)" /> <span>Disable</span>`;
        topEl.insertBefore(lbl, topEl.firstChild);
      }
    });
  });
}
window.refreshCalendarDisabledCells = refreshCalendarDisabledCells;

async function loadDisabledCalendarDates() {
  try {
    const now = new Date();
    const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
    const cached = localStorage.getItem('halden_disabled_calendar_dates');
    if (cached) {
      try {
        const parsed = JSON.parse(cached);
        if (Array.isArray(parsed)) {
          window.DISABLED_CALENDAR_DATES = new Set(parsed.map(d => String(d).trim()).filter(d => /^\d{4}-\d{2}-\d{2}$/.test(d) && d >= todayStr));
        }
      } catch (e) {}
    }
    refreshCalendarDisabledCells();

    const sb = window.supabaseClient || window.supabase || window.supabaseBackupClient;
    if (sb) {
      let { data, error } = await sb.from('disabled_calendar_dates').select('date, is_disabled');
      if (error && window.supabaseBackupClient) {
        const resB = await window.supabaseBackupClient.from('disabled_calendar_dates').select('date, is_disabled');
        data = resB.data;
        error = resB.error;
      }
      if (!error && Array.isArray(data)) {
        const validDates = data
          .filter(d => d.is_disabled !== false && String(d.date).trim() >= todayStr)
          .map(d => String(d.date).trim())
          .filter(d => /^\d{4}-\d{2}-\d{2}$/.test(d));
        window.DISABLED_CALENDAR_DATES = new Set(validDates);
        localStorage.setItem('halden_disabled_calendar_dates', JSON.stringify([...window.DISABLED_CALENDAR_DATES]));
      }
    }
    refreshCalendarDisabledCells();
  } catch (e) {
    console.warn('[Disabled Dates] Load error:', e);
  }
}

async function toggleAdminCalendarDateDisabled(dateStr, isChecked) {
  const cleanDate = String(dateStr || '').trim();
  if (!cleanDate || !/^\d{4}-\d{2}-\d{2}$/.test(cleanDate)) {
    console.warn('[Disabled Dates] Ignored invalid date string:', dateStr);
    return;
  }
  const now = new Date();
  const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  if (cleanDate < todayStr) return;

  if (!window.DISABLED_CALENDAR_DATES) window.DISABLED_CALENDAR_DATES = new Set();
  
  if (isChecked) {
    window.DISABLED_CALENDAR_DATES.add(cleanDate);
  } else {
    window.DISABLED_CALENDAR_DATES.delete(cleanDate);
  }
  try {
    const dateArray = [...window.DISABLED_CALENDAR_DATES];
    localStorage.setItem('halden_disabled_calendar_dates', JSON.stringify(dateArray));
    sessionStorage.setItem('halden_disabled_calendar_dates', JSON.stringify(dateArray));
  } catch(e) {}
  
  // Update UI cells immediately
  refreshCalendarDisabledCells();
  
  // Persist to primary Supabase with fallback to avoid 400 Bad Request
  try {
    const sb = window.supabaseClient || window.supabase;
    if (sb) {
      if (isChecked) {
        const payload = { date: cleanDate, is_disabled: true, reason: 'Disabled by admin', updated_at: new Date().toISOString() };
        const { error: upsertErr } = await sb.from('disabled_calendar_dates').upsert(payload, { onConflict: 'date' });
        if (upsertErr) {
          // If onConflict fails or table is configured differently, try update then insert
          const { error: updErr, count } = await sb.from('disabled_calendar_dates').update({ is_disabled: true, reason: 'Disabled by admin', updated_at: new Date().toISOString() }).eq('date', cleanDate);
          if (updErr || !count) {
            await sb.from('disabled_calendar_dates').insert(payload);
          }
        }
      } else {
        await sb.from('disabled_calendar_dates').delete().eq('date', cleanDate);
      }
    }
  } catch (err) {
    console.warn('[Disabled Dates] Supabase sync notice:', err);
  }

  // Persist to backup Supabase
  try {
    const sbBackup = window.supabaseBackupClient;
    if (sbBackup) {
      if (isChecked) {
        const payloadB = { date: cleanDate, is_disabled: true, reason: 'Disabled by admin', updated_at: new Date().toISOString() };
        await sbBackup.from('disabled_calendar_dates').upsert(payloadB, { onConflict: 'date' }).catch(() => {});
      } else {
        await sbBackup.from('disabled_calendar_dates').delete().eq('date', cleanDate).catch(() => {});
      }
    }
  } catch(e) {}
}

function subscribeToAdminAvailabilityRealtime() {
  try {
    const sb = window.supabaseClient || window.supabase;
    if (!sb || !sb.channel) return;
    sb.channel('admin_availability_sync')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'admin_meeting_availability' }, () => {
        loadAdminAvailability();
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'disabled_calendar_dates' }, () => {
        loadDisabledCalendarDates();
      })
      .subscribe();
  } catch (e) { }
}

