function safeNum(val) {
  if (typeof val === 'number') return isNaN(val) ? 0 : val;
  if (!val) return 0;
  const clean = String(val).replace(/[₱$,]/g, '');
  const n = parseFloat(clean);
  return isNaN(n) ? 0 : n;
}

function isDownpaymentPaid(res, combinedData) {
  if (!res) return false;
  const cd = combinedData || {};
  if (res.downpaymentStatus === 'paid' || res.downpayment_status === 'paid' || res.downpayment_paid === true || res.downpaymentPaid === true) return true;
  if (cd.downpaymentStatus === 'paid' || cd.downpayment_status === 'paid' || cd.downpayment_paid === true || cd.downpaymentPaid === true) return true;

  if (Array.isArray(res.payments) && res.payments.some(p => {
    const label = String(p.label || p.name || p.type || '').toLowerCase();
    return (label.includes('downpayment') || label.includes('down payment')) && (p.status === 'paid' || p.paid === true);
  })) return true;

  return false;
}
window.isDownpaymentPaid = isDownpaymentPaid;

function isFinalPaymentSettled(res, combinedData) {
  if (!res) return false;
  const cd = combinedData || {};
  if (res.finalPaymentStatus === 'paid' || res.final_payment_status === 'paid' || res.settled === true || res.final_paid === true || res.finalPaid === true) return true;
  if (cd.finalPaymentStatus === 'paid' || cd.final_payment_status === 'paid' || cd.settled === true || cd.final_paid === true || cd.finalPaid === true) return true;

  if (Array.isArray(res.payments) && res.payments.some(p => {
    const label = String(p.label || p.name || p.type || '').toLowerCase();
    return (label.includes('final') || label.includes('settlement')) && (p.status === 'paid' || p.paid === true);
  })) return true;

  return false;
}
window.isFinalPaymentSettled = isFinalPaymentSettled;

function getDynamicPrice(item, pax) {
  if (!item) return 0;
  if (item.isFree) return 0;
  if (item.cat === 'drink' && item.identify !== 'drinks_package' && item.identify !== 'mobile_bar') return 0;
  if (item.identify === 'mobile_bar_option' || item.identify === 'ice_cream_option') return 0;

  const p = parseInt(pax) || 0;
  const baseP = parseFloat(item.price) || 0;
  if (!Number.isFinite(baseP) || baseP <= 0) return 0;
  if (p <= 0) return baseP;

  if (item.isIndividual) return baseP * p;
  if (item.batchSize) return Math.ceil(p / item.batchSize) * baseP;

  const alloc = item.allocationType || item.pricingType;
  if (alloc === 'included') return 0;
  if (alloc === 'per_pax') return baseP * p;
  if (alloc === 'per_5_pax') return Math.ceil(p / 5) * baseP;
  if (alloc === 'per_10_pax') return Math.ceil(p / 10) * baseP;
  if (alloc === 'per_20_pax') return Math.ceil(p / 20) * baseP;
  if (alloc === 'per_character') return baseP * (p > 0 ? p : 1);
  if (alloc === 'per_menu_item') {
    // Count non-auto food/dessert items in the current package
    const src = (typeof mtCustomPkgItems !== 'undefined' ? mtCustomPkgItems : []);
    const menuCount = src.filter(i => !i.isAutoAdded && (i.cat === 'food' || i.cat === 'dessert')).length;
    return baseP * (menuCount > 0 ? menuCount : 1);
  }

  if (item.cat === 'food' || item.cat === 'dessert' || item.identify === 'meals' || (item.category && ['chicken','beef','pork','fish','seafood','pasta','noodle','vegetable','vegetables','dessert','appetizer','salad','soup','rice','food'].includes(String(item.category).toLowerCase())) || (item.subcategory && ['chicken','beef','pork','fish','seafood','pasta','noodle','vegetable','vegetables','dessert','appetizer','salad','soup','rice','food'].includes(String(item.subcategory).toLowerCase()))) {
    return baseP * p;
  }

  return baseP;
}

