const SG_GROUPS = ['reservations', 'event-handling', 'equipment-inv', 'users', 'analytics', 'packages', 'support'];
const SG_MAP = {
  dashboard: 'reservations', reservations: 'reservations', 'res-details': 'reservations',
  'activity-logs': 'reservations',
  events: 'event-handling', 'event-details': 'event-handling', seating: 'event-handling',
  equipment: 'equipment-inv', rentals: 'equipment-inv',
  availability: 'equipment-inv', 'routine-check': 'equipment-inv',
  allocation: 'equipment-inv', scheduling: 'equipment-inv',
  maintenance: 'equipment-inv', resupply: 'equipment-inv',
  disposed: 'equipment-inv',
  users: 'users',
  insights: 'analytics', packages: 'packages', chat: 'support', meetings: 'reservations'
};

function toggleSidebarGroup(group) {
  const content = document.getElementById('sg-' + group);
  const toggle = document.getElementById('sgt-' + group);
  if (!content) return;
  const isOpen = content.classList.contains('open');
  SG_GROUPS.forEach(g => {
    document.getElementById('sg-' + g)?.classList.remove('open');
    document.getElementById('sgt-' + g)?.classList.remove('open');
  });
  if (!isOpen) {
    content.classList.add('open');
    toggle?.classList.add('open');
  }
}

function openGroupFor(name) {
  const group = SG_MAP[name];
  if (!group) return;
  SG_GROUPS.forEach(g => {
    document.getElementById('sg-' + g)?.classList.remove('open');
    document.getElementById('sgt-' + g)?.classList.remove('open');
  });
  document.getElementById('sg-' + group)?.classList.add('open');
  document.getElementById('sgt-' + group)?.classList.add('open');
}

// ----- SMART ADMIN ALERTS -----
async function closeAdminAlert(meetingId) {
  const el = document.getElementById(`admin-alert-${meetingId}`);
  if (el) el.style.display = 'none';
  try {
    let seen = JSON.parse(localStorage.getItem('haldenAdminSeenAlerts') || '[]');
    if (!seen.includes(meetingId)) {
      seen.push(meetingId);
      localStorage.setItem('haldenAdminSeenAlerts', JSON.stringify(seen));
    }
  } catch (e) { console.warn('Failed to dismiss alert', e); }
}

async function markAdminAlertsSeen() {
  if (typeof MEETINGS === 'undefined') return;
  const container = document.getElementById('dash-admin-alerts');
  if (!container || !container.innerHTML.trim()) return;

  try {
    let seen = JSON.parse(localStorage.getItem('haldenAdminSeenAlerts') || '[]');
    let changed = false;
    MEETINGS.forEach(m => {
      const isAutoExpired = m.status === 'expired' && m.updatedAt;
      const isCustomerConfirmed = m.status === 'scheduled' && m.timeType === 'customer_selected';
      if ((isAutoExpired || isCustomerConfirmed) && !seen.includes(m.id)) {
        seen.push(m.id);
        changed = true;
      }
    });
    if (changed) {
      localStorage.setItem('haldenAdminSeenAlerts', JSON.stringify(seen));
    }
    container.innerHTML = '';
  } catch (e) { console.warn('Failed to mark alerts seen', e); }
}

function renderAdminAlerts() {
  const container = document.getElementById('dash-admin-alerts');
  if (!container || typeof MEETINGS === 'undefined') return;

  let seen = [];
  try { seen = JSON.parse(localStorage.getItem('haldenAdminSeenAlerts') || '[]'); } catch (e) { }

  const alerts = MEETINGS.map(m => {
    if (seen.includes(m.id)) return null;
    if (m.status === 'scheduled' && m.timeType === 'customer_selected') {
      return { id: m.id, type: 'success', text: `Customer successfully chose a meeting time for ${m.date}` };
    }
    // Action Required cancellation alerts removed as requested
    return null;
  }).filter(Boolean);

  if (alerts.length === 0) {
    container.innerHTML = '';
    return;
  }

  container.innerHTML = alerts.map(a => {
    const isGreen = a.type === 'success';
    const cls = isGreen ? 'admin-alert-green' : 'admin-alert-red';
    const icon = isGreen ? '✓' : '⚠️';
    return `
      <div id="admin-alert-${a.id}" class="${cls}">
        <div style="display:flex; align-items:center; gap:12px;">
          <div style="width:8px; height:8px; border-radius:50%; background:${isGreen ? '#2ea043' : '#e74c3c'}; flex-shrink:0; margin-top:2px;"></div>
          <div>
            <div class="admin-alert-title">${isGreen ? 'Meeting Confirmed' : 'Action Required'}</div>
            <div class="admin-alert-msg">${a.text}</div>
          </div>
        </div>
        <button class="admin-alert-close" onclick="closeAdminAlert('${a.id}')">✖</button>
      </div>
    `;
  }).join('');
}
window.closeAdminAlert = closeAdminAlert;

function showSection(name, el) {
  try {
    sessionStorage.setItem('admin_active_section', name);
    localStorage.setItem('admin_active_section', name);
  } catch (e) { }
  document.querySelectorAll('.section').forEach(s => s.classList.remove('active'));
  document.querySelectorAll('.sidebar-item').forEach(s => s.classList.remove('active'));
  const sec = document.getElementById('section-' + name);
  if (sec) sec.classList.add('active');
  if (el) el.classList.add('active');
  openGroupFor(name);

  // Toggle Execution Day floating QR camera button on mobile only (hidden on desktop views)
  const adminQrFab = document.getElementById('admin-qr-scan-fab');
  if (adminQrFab) {
    const isMobile = window.innerWidth <= 768;
    adminQrFab.style.display = (name === 'execution-day' && isMobile) ? 'flex' : 'none';
  }

  if (name !== 'dashboard') {
    if (typeof markAdminAlertsSeen === 'function') markAdminAlertsSeen();
  }

  if (name === 'dashboard') {
    setTimeout(() => {
      if (window.dashCalendar) {
        window.dashCalendar.render();
        if (typeof refreshCalendarDisabledCells === 'function') refreshCalendarDisabledCells();
      }
    }, 10);
  }
  if (name === 'events' && window.calendar) {
    setTimeout(() => window.calendar.render(), 10);
  }
  if (name === 'chat') initAdminChat();
  if (name === 'reservations') {
    renderReservations(currentFilter);
    renderReservationDetailsHandling();
  }
  if (name === 'res-details') renderReservationDetailsHandling();
  if (name === 'execution-day') renderExecutionDayReservations();
  if (name === 'activity-logs') renderActivityLogsSection();
  if (name === 'seating') renderSeating();
  if (name === 'equipment') renderEIMTable();
  if (name === 'rentals') renderRentalCards();
  if (name === 'allocation') renderAllocationSection();
  if (name === 'scheduling') renderSchedulingSection();
  if (name === 'availability') renderAvailabilitySection();
  if (name === 'routine-check') renderRoutineCheckSection();
  if (name === 'lifecycle') renderLifecycleSection();
  if (name === 'equip-cycle') {
    if (typeof populateEqcDropdown === 'function') populateEqcDropdown();
    const allocPanel = document.getElementById('eqc-panel-allocation');
    const allocSource = document.getElementById('section-allocation');
    if (allocPanel && allocSource && (!allocPanel.dataset.loaded || !allocPanel.innerHTML.trim())) {
      allocPanel.innerHTML = allocSource.innerHTML;
      allocPanel.dataset.loaded = 'true';
    }
    const allocBtn = document.getElementById('eqc-tab-allocation') || document.querySelector('.eq-cycle-tab');
    if (allocBtn) {
      document.querySelectorAll('.eq-cycle-tab').forEach(t => {
        t.classList.remove('active');
        t.style.borderBottomColor = 'transparent';
        t.style.color = 'var(--text-mid)';
      });
      allocBtn.classList.add('active');
      allocBtn.style.borderBottomColor = 'var(--gold)';
      allocBtn.style.color = 'var(--gold)';
    }
    document.querySelectorAll('.eqc-panel').forEach(p => p.style.display = 'none');
    if (allocPanel) allocPanel.style.display = 'block';

    if (!currentEqcReservationId) {
      const sel = document.getElementById('eqc-reservation-select');
      if (sel && sel.options.length > 1) {
        sel.selectedIndex = 1;
        if (typeof onEqcReservationChange === 'function') onEqcReservationChange();
      }
    } else {
      if (typeof onEqcReservationChange === 'function') onEqcReservationChange();
    }
  }
  if (name === 'equip-issues') renderEquipIssues();
  if (name === 'resupply') renderResupplySection();
  if (name === 'maintenance') renderMaintenanceSection();
  if (name === 'disposed') renderDisposedSection();
  if (name === 'qr-compile') renderQrCompileSection();
  if (name === 'meetings') {
    renderMeetingsSection();
    if (typeof initAdminMeetingsHubRealtime === 'function') initAdminMeetingsHubRealtime();
  }
  if (name === 'insights') { if(typeof window.triggerAdminAnalyticsUpdate === 'function') window.triggerAdminAnalyticsUpdate(); else renderInsights(); }
  if (name === 'users') renderUsersSection();
}
window.toggleSidebarGroup = toggleSidebarGroup;

function restoreAdminActiveSection() {
  try {
    const hash = window.location.hash;
    let targetSec = null;
    if (hash === '#execution-day' || hash === '#exec-day' || hash.startsWith('#exec-day/')) {
      targetSec = 'execution-day';
    } else {
      targetSec = sessionStorage.getItem('admin_active_section') || localStorage.getItem('admin_active_section');
    }
    if (targetSec && targetSec !== 'dashboard') {
      const navEl = document.getElementById('nav-' + targetSec) || document.querySelector(`[onclick*="showSection('${targetSec}'"]`);
      showSection(targetSec, navEl);
    }
  } catch (e) {
    console.warn('[restoreAdminActiveSection] error:', e);
  }
}
