async function handleMtFileUpload(e) {
  const files = Array.from(e.target.files);
  if (!files.length) return;

  // We'll upload each file immediately
  for (const file of files) {
    await uploadMtFile(file);
  }

  // Clear input so same file can be uploaded again if removed
  e.target.value = '';
}

async function uploadMtFile(file) {
  const progressWrap = document.getElementById('mt-cl-progress-wrap');
  const progressBar = document.getElementById('mt-cl-progress-bar');
  const progressPct = document.getElementById('mt-cl-progress-pct');
  const progressText = document.getElementById('mt-cl-progress-text');
  const dropZone = document.getElementById('mt-cl-drop-zone');

  dropZone.style.display = 'none';
  progressWrap.classList.add('on');
  progressBar.style.width = '0%';
  progressPct.textContent = '0%';
  progressText.textContent = 'Uploading ' + file.name + '...';

  const formData = new FormData();
  formData.append('file', file);
  formData.append('upload_preset', CLOUDINARY_UPLOAD_PRESET);
  formData.append('folder', 'catering');

  const url = `https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/auto/upload`;

  try {
    const data = await new Promise((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      xhr.open('POST', url);

      xhr.upload.addEventListener('progress', event => {
        if (event.lengthComputable) {
          const pct = Math.round((event.loaded / event.total) * 100);
          progressBar.style.width = pct + '%';
          progressPct.textContent = pct + '%';
        }
      });

      xhr.addEventListener('load', () => {
        if (xhr.status >= 200 && xhr.status < 300) {
          resolve(JSON.parse(xhr.responseText));
        } else {
          reject(new Error('Upload failed'));
        }
      });
      xhr.addEventListener('error', () => reject(new Error('Network error')));
      xhr.send(formData);
    });

    mtUploadedUrls.push({
      url: data.secure_url,
      name: file.name,
      type: file.type,
      delete_token: data.delete_token,
      agenda: window.activeMtTab || 'res'
    });

    syncMtDocsToSupabase();

    progressWrap.classList.remove('on');
    dropZone.style.display = 'block';
    renderMtUploadList();
  } catch (err) {
    alert('Upload failed: ' + err.message);
    dropZone.style.display = 'block';
    progressWrap.classList.remove('on');
  }
}

function renderMtUploadList() {
  const list = document.getElementById('mt-upload-list');
  if (!list) return;

  const _activeTab = window.activeMtTab || 'res';
  const _filteredForTab = mtUploadedUrls
    .map((f, realIdx) => ({ ...f, _realIdx: realIdx }))
    .filter(f => (f.agenda || 'res') === _activeTab);

  if (_filteredForTab.length === 0) {
    list.innerHTML = '';
    return;
  }

  list.innerHTML = _filteredForTab.map((file, idx) => {
    const isPDF = file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf');
    const isImg = file.type && file.type.startsWith('image/');
    let previewHtml = '';

    if (isImg || isPDF) {
      const displayUrl = isPDF ? file.url.replace('/upload/', '/upload/pg_1,f_jpg,w_400,c_limit/') : file.url;
      previewHtml = `<img src="${displayUrl}" style="width:60px; height:60px; object-fit:cover; border-radius:4px; border:1px solid var(--border);" />`;
    } else {
      previewHtml = `<div style="width:60px; height:60px; background:var(--bg3); display:flex; align-items:center; justify-content:center; font-size:24px; border-radius:4px;"></div>`;
    }

    return `
      <div class="cl-viewer-wrap on" style="margin-bottom:0; border:1px solid var(--border); background:var(--bg3);">
        <div class="cl-viewer-header" style="padding:8px 12px;">
          <span class="cl-viewer-title" style="font-size:12px;">${file.name}</span>
          <button style="font-size:10px; padding:3px 8px; background:#dc2626; color:#ffffff; border:none; border-radius:4px; font-weight:700; cursor:pointer;" onclick="removeMtFile(${file._realIdx})">✖ Remove</button>
        </div>
        <div style="padding:10px; display:flex; align-items:center; gap:12px;">
          ${previewHtml}
          <div style="flex:1;">
             <a href="${file.url}" target="_blank" style="font-size:11px; color:var(--gold); text-decoration:none;">View Full Document </a>
          </div>
        </div>
      </div>
    `;
  }).join('');
}

function syncMtDocsToSupabase() {
  if (activeMeeting && activeMeeting.id && activeMeeting.id !== 'demo') {
    try {
      const syncDocs = mtUploadedUrls.map(f => ({ url: f.url, name: f.name, type: f.type, agenda: f.agenda || 'res' }));
      // Update Firebase (legacy realtime)
      const { doc: _fd, updateDoc: _fu } = window.firebaseFns;
      _fu(_fd(window.firebaseDB, 'meetings', activeMeeting.id), { sharedDocuments: syncDocs }).catch(e => console.warn('Doc sync (Firebase) failed:', e));
      // Update Supabase so customer realtime listener picks up the change
      if (window.supabaseClient) {
        window.supabaseClient.from('meetings').update({ shared_documents: syncDocs }).eq('id', activeMeeting.id)
          .then(({ error }) => { if (error) console.warn('Doc sync (Supabase) failed:', error.message); });
      }
    } catch (syncErr) { console.warn('Doc sync error:', syncErr); }
  }
}

async function saveMtDesignNote(itemName, noteValue) {
  if (!activeMeeting || !activeMeeting.id || activeMeeting.id === 'demo') return;
  const sb = window.supabaseClient;
  if (!sb) return;
  // Update local cache
  if (!activeMeeting.design_notes) activeMeeting.design_notes = {};
  activeMeeting.design_notes[itemName] = noteValue;
  // Push to Supabase : customer's realtime listener will pick this up immediately
  const { error } = await sb.from('meetings').update({ design_notes: { ...activeMeeting.design_notes } }).eq('id', activeMeeting.id);
  if (error) console.warn('[saveMtDesignNote] Supabase error:', error.message);
}

function removeMtFile(idx) {
  const removed = mtUploadedUrls.splice(idx, 1)[0];
  if (removed && removed.delete_token) {
    const fd = new FormData();
    fd.append('token', removed.delete_token);
    fetch(`https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/delete_by_token`, { method: 'POST', body: fd }).catch(e => console.warn('Cloudinary delete failed:', e));
  }
  renderMtUploadList();
  syncMtDocsToSupabase();
}

function clearMtFile() {
  mtUploadedUrls.forEach(f => {
    if (f.delete_token) {
      const fd = new FormData();
      fd.append('token', f.delete_token);
      fetch(`https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/delete_by_token`, { method: 'POST', body: fd }).catch(e => console.warn(e));
    }
  });
  mtUploadedUrls = [];
  renderMtUploadList();
  syncMtDocsToSupabase();
}

async function saveMeeting() {
  // saveMeeting handles Path A: admin picks from customer's proposed times
  // Path B (admin proposes) is handled by submitAdminProposedTimes()
  const proposeOpen = document.getElementById('mt-admin-propose-section')?.style.display !== 'none';
  if (proposeOpen) {
    // Redirect to propose flow if propose section is open
    submitAdminProposedTimes();
    return;
  }

  const selectedRadio = document.querySelector('input[name="mt_time_selection"]:checked');
  if (!selectedRadio) {
    const _res = RESERVATIONS.find(r => r.id === activeMtResId);
    const isFollowUp = String(_res ? (_res['mandatory-meeting concluded'] || '') : '').toLowerCase().includes('contract finalization');
    const hasCustomerTimes = !isFollowUp && _res && _res.proposedMeetingTimes && _res.proposedMeetingTimes.length > 0;

    if (!hasCustomerTimes) {
      // No customer times : auto-open propose panel for the admin
      const propSec = document.getElementById('mt-admin-propose-section');
      const toggleBtn = document.getElementById('mt-propose-toggle-btn');
      if (propSec && propSec.style.display === 'none') {
        propSec.style.display = 'block';
        if (toggleBtn) toggleBtn.textContent = '\u2715 Close Propose Times';
        if (typeof renderAdminProposeSlots === 'function') renderAdminProposeSlots();
      }
      alert('No customer proposed times available. Use "Propose Meeting Times to Customer" above to suggest time slots.');
    } else {
      alert('Please select one of the customer\'s proposed times, or use "Propose Meeting Times" to send your own.');
    }
    return;
  }

  const idx = parseInt(selectedRadio.value);
  const res = RESERVATIONS.find(r => r.id === activeMtResId);
  if (!res || !res.proposedMeetingTimes || !res.proposedMeetingTimes[idx]) {
    alert('Could not find the selected time slot. Please try again.');
    return;
  }
  const selectedTime = { ...res.proposedMeetingTimes[idx] };

  const agendas = Array.from(document.querySelectorAll('.mt-agenda-cb:checked')).map(cb => cb.value);
  const otherAgenda = document.getElementById('mt-input-agenda-other').value.trim();
  if (otherAgenda) agendas.push(otherAgenda);
  if (agendas.length === 0) { alert('Please select at least one agenda.'); return; }

  try {
    const { collection, addDoc, updateDoc, doc } = window.firebaseFns;
    const db = window.firebaseDB;

    const videoCb = document.getElementById('mt-video-call-cb');
    const isVideoEnabled = !!(videoCb && videoCb.checked && !videoCb.disabled);
    let roomId = null;
    if (isVideoEnabled) {
      roomId = 'VC-' + Math.random().toString(36).substr(2, 9).toUpperCase();
    }

    const mtData = {
      reservationId: activeMtResId,
      clientId: res.clientId || 'unknown',
      clientName: res.client,
      customerEmail: res.customerEmail || res.email || '',
      customerName: res.client,
      date: selectedTime.date,
      time: selectedTime.start,
      timeEnd: selectedTime.end || '',
      timeType: 'customer_proposed',
      agenda: agendas.join(', '),
      status: 'pending',
      roomId: roomId,
      isVideoEnabled: isVideoEnabled,
      updatedAt: new Date().toISOString()
    };

    if (activeMtId) {
      await updateDoc(doc(db, 'meetings', activeMtId), mtData);
    } else {
      await addDoc(collection(db, 'meetings'), { ...mtData, createdAt: new Date().toISOString() });
    }

    // Automated EmailJS Notification to customer
    if (window.SmartServeNotifications && typeof window.SmartServeNotifications.notifyCustomerMeetingScheduled === 'function') {
      const custEmail = res.customerEmail || res.email || res.client_email || mtData.customerEmail;
      window.SmartServeNotifications.notifyCustomerMeetingScheduled({
        customerEmail: custEmail,
        customerName: res.client || mtData.clientName,
        date: selectedTime.date,
        time: selectedTime.start,
        agenda: agendas.join(', '),
        roomId: roomId,
        reservationId: activeMtResId
      });
    }

    alert(`Meeting scheduled for ${selectedTime.date} at ${selectedTime.start}!`);

    // Comprehensive Admin Activity Logging for scheduled meeting
    try {
      if (typeof window.logAdminActivity === 'function') {
        window.logAdminActivity(
          'Scheduled Meeting',
          `Scheduled meeting for reservation #${activeMtResId} (${res.client || 'Client'}) on ${selectedTime.date} at ${selectedTime.start} with agenda: ${agendas.join(', ')}.`,
          { category: 'Meetings', reservation_id: activeMtResId, client_name: res.client }
        );
      }
    } catch (_logErr) {
      console.warn('Logging saveMeeting failed:', _logErr);
    }

    closeMtModal();
    if (mtCalendar) mtCalendar.refetchEvents();
    renderPendingMeetings();
    renderWeeklyMeetings();
  } catch (e) {
    console.error('saveMeeting error:', e);
    alert('Failed to save meeting: ' + (e.message || e));
  }
}

// ─── Admin Propose Slots (Path B) ───────────────────────────────────────
let adminProposeSlots = [];

function openAdminSlotModal() {
  document.getElementById('mt-admin-slot-overlay').classList.add('on');
  document.getElementById('mt-admin-slot-modal').classList.add('open');
  // Set min date to 14 days from today
  const minD = new Date();
  minD.setDate(minD.getDate() + 14);
  const minStr = minD.toISOString().split('T')[0];
  const dateInput = document.getElementById('mt-admin-slot-date');
  dateInput.value = '';
  dateInput.min = minStr;
  document.getElementById('mt-admin-slot-start').value = '';
  document.getElementById('mt-admin-slot-end').value = '';
}
window.openAdminSlotModal = openAdminSlotModal;

function closeAdminSlotModal() {
  document.getElementById('mt-admin-slot-overlay').classList.remove('on');
  document.getElementById('mt-admin-slot-modal').classList.remove('open');
}
window.closeAdminSlotModal = closeAdminSlotModal;

function addAdminProposeSlot() {
  const dateVal = document.getElementById('mt-admin-slot-date').value;
  const start = document.getElementById('mt-admin-slot-start').value;
  const end = document.getElementById('mt-admin-slot-end').value;
  const errors = [];

  if (!dateVal) { errors.push('Please select a date.'); }
  if (!start) { errors.push('Please select a start time.'); }
  if (!end) { errors.push('Please select an end time.'); }

  if (dateVal) {
    const now = new Date();
    const todayStr = now.toISOString().split('T')[0];

    // Min allowed date = today + 14 days
    const minD = new Date();
    minD.setDate(minD.getDate() + 14);
    const minStr = minD.toISOString().split('T')[0];

    if (dateVal < todayStr) {
      errors.push('The date has already passed. Select a future date.');
    } else if (dateVal < minStr) {
      errors.push('Proposed meeting date must be at least 14 days from today.');
    }
  }

  if (start && end) {
    const toMin = t => { const [h, m] = t.split(':').map(Number); return (isNaN(h) || isNaN(m)) ? null : h * 60 + m; };
    const sMin = toMin(start), eMin = toMin(end);
    if (sMin !== null && eMin !== null && (eMin - sMin) < 120) {
      errors.push('Meeting window must be at least 2 hours.');
    }
  }

  const isDuplicate = adminProposeSlots.some(s => s.date === dateVal && s.start === start && s.end === end);
  if (isDuplicate) errors.push('This exact slot has already been added.');

  if (adminProposeSlots.length >= 3) {
    errors.push('You can only propose a maximum of 3 meeting times.');
  }

  if (errors.length > 0) { alert(errors.join('\n')); return; }

  adminProposeSlots.push({ date: dateVal, start, end });
  renderAdminProposeSlots();
  closeAdminSlotModal();
}
window.addAdminProposeSlot = addAdminProposeSlot;

function removeAdminProposeSlot(idx) {
  adminProposeSlots.splice(idx, 1);
  renderAdminProposeSlots();
}
window.removeAdminProposeSlot = removeAdminProposeSlot;

function renderAdminProposeSlots() {
  const list = document.getElementById('mt-admin-propose-list');
  if (!list) return;
  if (adminProposeSlots.length === 0) {
    list.innerHTML = '<div style="font-size:11px; color:var(--text-dim); font-style:italic;">No slots added yet.</div>';
    return;
  }
  list.innerHTML = adminProposeSlots.map((s, idx) => `
    <div style="display:flex; align-items:center; justify-content:space-between; padding:7px 10px; background:var(--bg2); border-radius:6px; border:1px solid var(--border); font-size:12px;">
      <span style="font-weight:600; color:var(--text);">${s.date}</span>
      <span style="color:var(--text-dim);">${s.start} &ndash; ${s.end}</span>
      <button onclick="removeAdminProposeSlot(${idx})" style="background:#dc2626; border:none; color:#ffffff; font-weight:700; width:22px; height:22px; border-radius:4px; cursor:pointer; font-size:14px; display:flex; align-items:center; justify-content:center;">&times;</button>
    </div>
  `).join('');
}
window.renderAdminProposeSlots = renderAdminProposeSlots;

async function submitAdminProposedTimes() {
  if (adminProposeSlots.length === 0) { alert('Please add at least one proposed time slot.'); return; }

  const agendas = Array.from(document.querySelectorAll('.mt-agenda-cb:checked')).map(cb => cb.value);
  const otherAgenda = document.getElementById('mt-input-agenda-other').value.trim();
  if (otherAgenda) agendas.push(otherAgenda);
  if (agendas.length === 0) { alert('Please select at least one agenda.'); return; }

  const res = RESERVATIONS.find(r => r.id === activeMtResId);
  if (!res) { alert('Reservation not found.'); return; }

  try {
    const { collection, addDoc, updateDoc, doc } = window.firebaseFns;
    const db = window.firebaseDB;

    const videoCb = document.getElementById('mt-video-call-cb');
    const isVideoEnabled = !!(videoCb && videoCb.checked && !videoCb.disabled);
    let roomId = null;
    if (isVideoEnabled) {
      roomId = 'VC-' + Math.random().toString(36).substr(2, 9).toUpperCase();
    }

    const mtData = {
      reservationId: activeMtResId,
      clientId: res.clientId || 'unknown',
      clientName: res.client,
      customerEmail: res.customerEmail || res.email || '',
      customerName: res.client,
      agenda: agendas.join(', '),
      status: 'awaiting_customer',
      adminProposedTimes: adminProposeSlots,
      date: null,
      time: null,
      timeEnd: null,
      timeType: 'admin_proposed',
      roomId: roomId,
      isVideoEnabled: isVideoEnabled,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    if (activeMtId) {
      await updateDoc(doc(db, 'meetings', activeMtId), mtData);
    } else {
      await addDoc(collection(db, 'meetings'), mtData);
    }

    // Automated EmailJS Notification to customer for proposed meeting times
    if (window.SmartServeNotifications && typeof window.SmartServeNotifications.notifyCustomerProposedTimes === 'function') {
      const custEmail = res.customerEmail || res.email || res.client_email || mtData.customerEmail;
      window.SmartServeNotifications.notifyCustomerProposedTimes({
        customerEmail: custEmail,
        customerName: res.client || mtData.clientName,
        proposedSlots: adminProposeSlots.slice(),
        agenda: agendas.join(', '),
        reservationId: activeMtResId,
        deadlineHours: 24
      });
    }

    alert(`Proposed times sent to ${res.client}. They have 24 hours to select one, or their reservation will be automatically cancelled.`);

    // Comprehensive Admin Activity Logging for proposed meeting times
    try {
      if (typeof window.logAdminActivity === 'function') {
        window.logAdminActivity(
          'Proposed Meeting Times',
          `Admin proposed ${adminProposeSlots.length} meeting time slot(s) to customer for reservation #${activeMtResId} (${res.client || 'Client'}).`,
          { category: 'Meetings', reservation_id: activeMtResId, client_name: res.client }
        );
      }
    } catch (_logErr) {
      console.warn('Logging submitAdminProposedTimes failed:', _logErr);
    }

    closeMtModal();
    adminProposeSlots = [];
    closeMtModal();
    if (mtCalendar) mtCalendar.refetchEvents();
    renderPendingMeetings();
    renderWeeklyMeetings();
  } catch (e) {
    console.error('submitAdminProposedTimes error:', e);
    alert('Failed to send proposed times: ' + (e.message || e));
  }
}
window.submitAdminProposedTimes = submitAdminProposedTimes;

async function forceMeetingMode() {
  // Demo Mode: Bypassing Firestore requirement to ensure it "always works" for the user.
  // We simulate a robust meeting session with mock details.
  console.log("Demo Mode: Launching simulated meeting session...");
  initiateMeetingMode('demo');
}

async function loadMeetingToForm(mtId) {
  try {
    const { doc, getDoc } = window.firebaseFns;
    const snap = await getDoc(doc(window.firebaseDB, 'meetings', mtId));
    if (!snap.exists()) return;
    const mt = snap.data();
    activeMtId = mtId;
    activeMtResId = mt.reservationId || activeMtResId;

    const dateEl = document.getElementById('mt-input-date');
    const timeEl = document.getElementById('mt-input-time');
    const agendaEl = document.getElementById('mt-input-agenda');
    if (dateEl) dateEl.value = mt.date || '';
    if (timeEl) timeEl.value = mt.time || '';
    if (agendaEl) agendaEl.value = mt.agenda || 'Initial Consultation';

    const linkedRes = RESERVATIONS.find(r => r.id === activeMtResId);
    if (linkedRes) {
      document.getElementById('mt-chat-title').textContent = `Chat with ${linkedRes.client}`;
      initMtChat(linkedRes.id, linkedRes.client);
    } else if (mt.clientName) {
      document.getElementById('mt-chat-title').textContent = `Chat with ${mt.clientName}`;
    }
  } catch (e) {
    console.error('Failed to load meeting details:', e);
  }
}

// MEETING MODE LOGIC
let activeMeeting = null;

async function initiateMeetingMode(mtId) {
  // Always reset modify mode to default when entering any meeting room.
  // Do this via direct DOM manipulation : safe to run before activeMeeting is set.
  mtModifyMode = false;
  mtSnapshot = null;
  if (typeof _resetGcashProofPanel === 'function') _resetGcashProofPanel();
  const _modBtn = document.getElementById('mt-mode-modify-btn');
  const _rightStd = document.getElementById('mt-mode-standard-right');
  const _rightCat = document.getElementById('mt-mode-catalog-right');
  if (_modBtn) { _modBtn.textContent = 'Modify Package'; _modBtn.style.color = ''; _modBtn.style.borderColor = ''; }
  if (_rightStd) _rightStd.style.display = '';
  if (_rightCat) _rightCat.style.display = 'none';
  try {

    let res;
    if (mtId === 'demo') {
      activeMeeting = {
        id: 'demo',
        reservationId: 'demo-res-123',
        clientName: 'Julianne Cruz (VIP Demo)',
        agenda: 'Contract Finalization, Food Tasting, Venue Layout',
        date: new Date().toISOString().split('T')[0],
        time: '02:30 PM',
        status: 'scheduled'
      };
      res = {
        id: 'demo-res-123',
        client: 'Julianne Cruz',
        type: 'Grand Wedding Reception',
        date: '2026-06-15',
        pax: 250,
        packageName: 'Diamond Royale Package',
        packageItems: ['Prime Rib Buffet', 'Open Bar (Premium)', 'Floor-to-Ceiling Floral Decor', '8-piece String Ensemble', 'Multi-tier Custom Cake']
      };
    } else {
      let foundMeeting = null;
      if (window.firebaseFns && window.firebaseDB) {
        try {
          const { doc, getDoc } = window.firebaseFns;
          const snap = await getDoc(doc(window.firebaseDB, 'meetings', mtId));
          if (snap.exists()) {
            foundMeeting = { id: snap.id, ...snap.data() };
          }
        } catch (e) { console.warn('Firebase meeting fetch notice:', e); }
      }
      if (!foundMeeting && typeof MEETINGS !== 'undefined' && Array.isArray(MEETINGS)) {
        foundMeeting = MEETINGS.find(m => m.id === mtId);
      }
      if (window.supabaseClient && mtId && mtId !== 'demo') {
        try {
          let { data: sbMt } = await window.supabaseClient.from('meetings').select('*').eq('id', mtId).maybeSingle();
          if (!sbMt) {
            const { data: altMts } = await window.supabaseClient.from('meetings').select('*').or(`meetingRoomId.eq.${mtId},room_id.eq.${mtId},roomId.eq.${mtId}`);
            if (altMts && altMts.length > 0) sbMt = altMts[0];
          }
          if (sbMt) {
            foundMeeting = Object.assign({}, foundMeeting || {}, sbMt, { id: sbMt.id, meetingRoomId: sbMt.meetingRoomId || sbMt.room_id });
            if (sbMt.live_draft && sbMt.live_draft.cancellation_pay) {
              Object.assign(foundMeeting, sbMt.live_draft.cancellation_pay);
            } else if (sbMt.cancellationNote && typeof sbMt.cancellationNote === 'string' && sbMt.cancellationNote.trim().startsWith('{')) {
              try { Object.assign(foundMeeting, JSON.parse(sbMt.cancellationNote)); } catch (e) {}
            }
          }
        } catch (e) {}
      }

      if (!foundMeeting) {
        console.error('Cannot initiate meeting: meeting not found:', mtId);
        alert('Could not find meeting details for ID: ' + mtId);
        return;
      }

      activeMeeting = { ...foundMeeting };
      const resId = activeMeeting.reservationId || activeMeeting.reservation_id;
      activeMeeting.reservationId = resId;
      activeMeeting.reservation_id = resId;

      res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(r => r.id === resId);
      if (!res && resId && window.supabaseClient) {
        try {
          const { data: sbRes } = await window.supabaseClient.from('reservations').select('*').eq('id', resId).maybeSingle();
          if (sbRes) {
            res = { id: sbRes.id, ...sbRes };
            RESERVATIONS.push(res);
          }
        } catch (e) {}
      }
      if (!res && resId && window.firebaseFns && window.firebaseDB) {
        try {
          const { doc, getDoc } = window.firebaseFns;
          const rSnap = await getDoc(doc(window.firebaseDB, 'reservations', resId));
          if (rSnap.exists()) { res = { id: rSnap.id, ...rSnap.data() }; RESERVATIONS.push(res); }
        } catch (e) {}
      }

      // Force status to 'live' and ensure identification fields are present for customer sync
      const syncData = { status: 'live' };
      if (res) {
        if (res.customerEmail || res.email) syncData.customerEmail = res.customerEmail || res.email;
        if (res.customerName || res.client) syncData.customerName = res.customerName || res.client;
      }

      console.log("Broadcasting Live Meeting Status for MT:", mtId, syncData);
      if (window.supabaseClient && mtId && mtId !== 'demo') {
        try {
          // Await Supabase update to set status to live without calling invalid .catch()
          await window.supabaseClient.from('meetings').update({ status: 'live' }).eq('id', mtId);
        } catch (e) {
          console.warn('Supabase live update notice:', e);
        }
      }
      if (window.firebaseFns && window.firebaseDB) {
        try {
          const { doc, updateDoc } = window.firebaseFns;
          updateDoc(doc(window.firebaseDB, 'meetings', mtId), syncData).catch(e => console.error("Firebase live sync failed:", e));
        } catch(e) {}
      }
    }

    // Ensure admin upload list correctly matches what's stored in Supabase
    mtUploadedUrls = activeMeeting.sharedDocuments ? [...activeMeeting.sharedDocuments] : [];

    if (window.supabaseClient && res) {
      window.supabaseClient.from('meetings')
        .select('shared_documents')
        .or(`reservationId.eq.${res.id},reservation_id.eq.${res.id}`)
        .neq('id', mtId)
        .then(({ data, error }) => {
          if (!error && data) {
            let hasNew = false;
            data.forEach(m => {
              const docs = m.shared_documents || [];
              docs.forEach(d => {
                if (d && d.url && (d.agenda === 'design' || d.agenda === 'food' || d.agenda === 'res') && !mtUploadedUrls.some(existing => existing.url === d.url)) {
                  mtUploadedUrls.push(d);
                  hasNew = true;
                }
              });
            });
            if (hasNew) renderMtUploadList();
          }
        });
    }

    renderMtUploadList();

    if (!res) {
      alert("Linked reservation not found.");
      return;
    }

    activeResDetailId = res.id;
    activeMeetingResCache = res;
    window.mtServiceChargePct = parseFloat(res.service_charge_pct || res.serviceChargePct || 0);
    mtPax = parseInt(res.pax) || 0;
    // mtDate needs to be YYYY-MM-DD for <input type="date">
    mtDate = normalizeDateKey(res.date) || '';

    // Handle time range - support both "H:MM AM - H:MM PM" and "H:MM AM to H:MM PM" formats
    const _parseResTime12hTo24h = (str) => {
      if (!str) return '';
      str = str.trim();
      // Already in HH:MM 24h format
      if (/^\d{1,2}:\d{2}$/.test(str)) return str;
      const match = str.match(/(\d{1,2}):?(\d{2})?\s*(AM|PM|am|pm)?/i);
      if (!match) return '';
      let h = parseInt(match[1]);
      const m = match[2] || '00';
      const ap = (match[3] || '').toUpperCase();
      if (ap === 'PM' && h < 12) h += 12;
      if (ap === 'AM' && h === 12) h = 0;
      return `${h.toString().padStart(2, '0')}:${m}`;
    };
    if (res.time) {
      // Support both " to " and " - " as separators
      const _sep = res.time.toLowerCase().includes(' to ') ? / to /i : /-/;
      const parts = res.time.split(_sep).map(p => p.trim());
      if (parts.length >= 2) {
        mtTimeStart = _parseResTime12hTo24h(parts[0]);
        mtTimeEnd = _parseResTime12hTo24h(parts[parts.length - 1]);
      } else {
        mtTimeStart = _parseResTime12hTo24h(res.time);
        mtTimeEnd = '';
      }
    } else {
      mtTimeStart = '';
      mtTimeEnd = '';
    }

    mtType = res.type || '';
    mtTheme = res.theme || '';
    mtVip = parseInt(res.vipCount != null ? res.vipCount : (res.vip && typeof res.vip === 'object' ? res.vip.count : res.vip)) || 0;
    mtVipService = res.vipService || 'properly catered';
    mtVenueLocation = res.city || res.venueLocation || res.venue_location || res.venueCity || '';
    mtVenue = res.venueName || res.venue || res.venue_name || '';
    mtVenueAddr = res.venueAddress || res.fullAddress || res.gpsVenueAddress || res.venueAddr || res.venue || '';
    mtVenueInfo = res.venue_info || res.venueInfo || '';

    const _isMalabonInit = (typeof window.isReservationMalabon === 'function')
      ? window.isReservationMalabon(res, { venueLocation: mtVenueLocation, venue: mtVenue, venueAddr: mtVenueAddr })
      : false;
    if (_isMalabonInit) {
      res.outOfTownCharge = 0;
      res.out_of_town_charge = 0;
      if (activeMeetingResCache) {
        activeMeetingResCache.outOfTownCharge = 0;
        activeMeetingResCache.out_of_town_charge = 0;
      }
    }
    mtNotes = res.notes || '';
    mtEventDescription = res.description || res.eventDescription || res.packageDescription || '';
    mtCallTime = res.callTime || mtTimeStart || '';
    mtCustomPkgItems = [];
    const _mtBaseNames = typeof window.getPremadeBaseItemNames === 'function' ? window.getPremadeBaseItemNames(res) : [];
    (res.packageItems || []).forEach(rawRi => {
      let ri = rawRi;
      if (typeof ri === 'string' && ri.trim().startsWith('{') && ri.trim().endsWith('}')) {
        try { ri = JSON.parse(ri); } catch(e) {}
      }
      const rawName = typeof ri === 'string' ? ri : (ri && ri.name ? ri.name : '');
      const isExtra = typeof window.isReservationExtraPackageItem === 'function'
        ? window.isReservationExtraPackageItem(res, ri, _mtBaseNames)
        : (typeof ri === 'object' && ri !== null && (ri.isAdditional || ri.addedAsExtra || ri.isExtra));
      const found = CAT.find(c => c.name === rawName || (ri && ri.id && c.id === ri.id));
      if (found) {
        const itemObj = Object.assign({}, found, typeof ri === 'object' && ri !== null ? ri : {});
        if (isExtra) {
          itemObj.isAdditional = true;
          itemObj.addedAsExtra = true;
        }
        if (res.freeChoiceFoodItem && itemObj.name === res.freeChoiceFoodItem) {
          itemObj.isFreeChoiceApplied = true;
          itemObj.isFree = true;
        }
        mtCustomPkgItems.push(itemObj);
      } else if (rawName) {
        mtCustomPkgItems.push({
          id: (typeof ri === 'object' && ri && ri.id) ? ri.id : ('custom-' + Math.random()),
          name: rawName,
          cat: (typeof ri === 'object' && ri && ri.cat) ? ri.cat : 'other',
          price: (typeof ri === 'object' && ri && ri.price != null) ? ri.price : 0,
          isAdditional: !!isExtra,
          addedAsExtra: !!isExtra
        });
      }
    });

    document.getElementById('mt-mode-subtitle').textContent = `${activeMeeting.agenda || 'Meeting'} with ${res.client}`;

    // ===== MEETING ROOM ID (MTG-) : SmartServe Hub Join =====
    if (mtId === 'demo') {
      activeMeeting.meetingRoomId = activeMeeting.meetingRoomId || 'MTG-DEMO0001';
    } else if (!activeMeeting.meetingRoomId) {
      activeMeeting.meetingRoomId = 'MTG-' + Math.random().toString(36).substr(2, 8).toUpperCase();
      if (window.supabaseClient && mtId && mtId !== 'demo') {
        try {
          await window.supabaseClient.from('meetings').update({ meetingRoomId: activeMeeting.meetingRoomId }).eq('id', mtId);
        } catch (e) { console.warn('Supabase MTG ID sync err:', e); }
      }
      if (window.firebaseFns && window.firebaseFns.doc && window.firebaseFns.updateDoc && window.firebaseDB) {
        try {
          const { doc: _d, updateDoc: _u } = window.firebaseFns;
          _u(_d(window.firebaseDB, 'meetings', mtId), { meetingRoomId: activeMeeting.meetingRoomId }).catch(e => console.error('MTG ID sync err:', e));
        } catch(e) {}
      }
    }
    const mtgChip = document.getElementById('mt-meeting-room-id-chip');
    if (mtgChip) {
      mtgChip.textContent = ' ' + activeMeeting.meetingRoomId;
      mtgChip.style.display = 'inline-flex';
    }

    const videoBtn = document.getElementById('mt-mode-video-btn');
    const roomIdDisplay = document.getElementById('mt-mode-room-id-display');
    if (videoBtn) {
      if (activeMeeting.isVideoEnabled && !activeMeeting.roomId) {
        // Auto-generate roomId if missing but video is enabled
        activeMeeting.roomId = 'VC-' + Math.random().toString(36).substr(2, 9).toUpperCase();
        if (mtId !== 'demo') {
          if (window.supabaseClient) {
            try {
              await window.supabaseClient.from('meetings').update({ roomId: activeMeeting.roomId }).eq('id', mtId);
            } catch (e) { console.warn('Supabase Room ID sync err:', e); }
          }
          if (window.firebaseFns && window.firebaseFns.doc && window.firebaseFns.updateDoc && window.firebaseDB) {
            try {
              const { doc: _d, updateDoc: _u } = window.firebaseFns;
              _u(_d(window.firebaseDB, 'meetings', mtId), { roomId: activeMeeting.roomId }).catch(e => console.error('Room ID sync err:', e));
            } catch(e) {}
          }
        }
      }

      // Show Join button ONLY if the meeting was scheduled with video conference enabled
      const meetingHasVideo = !!(activeMeeting.isVideoEnabled && activeMeeting.roomId);
      if (meetingHasVideo) {
        videoBtn.style.display = 'flex';
        videoBtn.dataset.roomId = activeMeeting.roomId;
        if (roomIdDisplay) {
          roomIdDisplay.textContent = activeMeeting.roomId;
          roomIdDisplay.style.display = 'flex';
        }
      } else {
        videoBtn.style.display = 'none';
        videoBtn.dataset.roomId = '';
        if (roomIdDisplay) roomIdDisplay.style.display = 'none';
      }
    }

    // Render Agenda as Checklist
    const agendaContainer = document.getElementById('mt-mode-agenda');
    const topics = (activeMeeting.agenda || "").split(',').map(t => t.trim()).filter(t => t);
    agendaContainer.innerHTML = topics.map((t, idx) => `
      <label style="display:flex; align-items:center; gap:12px; padding:12px; background:rgba(255,255,255,0.03); border-radius:10px; cursor:pointer; border:1px solid rgba(255,255,255,0.05);">
        <input type="checkbox" class="agenda-chk" value="${t}" style="width:18px; height:18px; accent-color:var(--gold);">
        <span style="font-size:14px; color:var(--text);">${t}</span>
      </label>
    `).join('') || '<div style="color:var(--text-dim); font-size:13px;">No specific agenda items listed.</div>';

    // Live Notes Sync
    const notesArea = document.getElementById('mt-mode-notes');
    if (notesArea) {
      notesArea.value = activeMeeting.notes || '';
      notesArea.oninput = () => {
        if (activeMeeting && activeMeeting.id !== 'demo') {
          const { updateDoc, doc } = window.firebaseFns;
          // Simple debounce could be added here, but direct sync is more "live"
          updateDoc(doc(window.firebaseDB, 'meetings', activeMeeting.id), { notes: notesArea.value }).catch(e => { });
        }
      };
    }

    // Auto-populate the Review area immediately
    renderMtModeResDetails(res);

    document.getElementById('mt-mode-overlay').classList.add('open');

    const isInitial = (activeMeeting.agenda || "").toUpperCase().includes('INITIAL RESERVATION');
    const _initPayEl = document.getElementById('mt-mode-initial-res-payment');
    if (_initPayEl) _initPayEl.style.display = isInitial ? 'block' : 'none';


    const agendaStr = (activeMeeting.agenda || "").toUpperCase();
    const isFinal = agendaStr.includes('CONTRACT');
    const isDesign = agendaStr.includes('DESIGN');

    const isFood = agendaStr.includes('FOOD TASTING');
    const isRundown = agendaStr.includes('FINAL PROGRAM RUNDOWN');
    const isPayment = agendaStr.includes('PAYMENT ASSESSMENT');
    const isLogistics = agendaStr.includes('ADDITIONAL RESERVATION DISCUSSION');

    // Reset dynamic agendas for this new meeting session
    dynamicAgendas = [];

    const contractBtnContainer = document.getElementById('mt-mode-contract-btn-container');
    if (contractBtnContainer) contractBtnContainer.style.display = isFinal ? 'block' : 'none';

    const designBtnContainer = document.getElementById('mt-mode-design-btn-container');
    if (designBtnContainer) designBtnContainer.style.display = isDesign ? 'block' : 'none';

    const isCancellation = agendaStr.includes('CANCEL') || (activeMeeting && (activeMeeting.type === 'cancellation' || activeMeeting.isCancellation));

    // Show/Hide Meeting Mode Navigation Buttons
    document.getElementById('btn-mt-nav-food').style.display = isFood ? 'block' : 'none';
    document.getElementById('btn-mt-nav-design').style.display = isDesign ? 'block' : 'none';
    document.getElementById('btn-mt-nav-rundown').style.display = isRundown ? 'block' : 'none';
    document.getElementById('btn-mt-nav-payment').style.display = isPayment ? 'block' : 'none';
    document.getElementById('btn-mt-nav-logistics').style.display = isLogistics ? 'block' : 'none';
    const btnMtCancel = document.getElementById('btn-mt-nav-cancellation');
    if (btnMtCancel) btnMtCancel.style.display = isCancellation ? 'block' : 'none';

    if (isLogistics && res && window.supabaseClient) {
      try {
        const { data, error } = await window.supabaseClient
          .from('additional_reservation_details')
          .select('event_flow, guest_list, seating_elements')
          .eq('reservation_id', res.id)
          .maybeSingle();
        if (!error && data) {
          if (Array.isArray(data.event_flow) && data.event_flow.length > 0) {
            if (!res.executionPlan) res.executionPlan = { phases: [] };
            if (!res.executionPlan.phases) res.executionPlan.phases = [];
            if (data.event_flow[0] && data.event_flow[0].id) {
              res.executionPlan.phases = data.event_flow;
            } else {
              let execPhase = res.executionPlan.phases.find(p => p.id === 'execution');
              if (!execPhase) {
                execPhase = { id: 'execution', name: 'Execution Day', agenda: [] };
                res.executionPlan.phases.push(execPhase);
              }
              execPhase.agenda = data.event_flow;
            }
          }
          if (!reservationExtraDetails[res.id]) getActiveReservationExtra(res.id);
          const cache = reservationExtraDetails[res.id];
          if (cache) {
            if (Array.isArray(data.guest_list) && data.guest_list.length > 0) cache.guests = data.guest_list;
            if (Array.isArray(data.seating_elements) && data.seating_elements.length > 0) cache.seatingElements = data.seating_elements;
          }
        }
      } catch (e) {
        console.error('Error auto-loading additional_reservation_details for meeting:', e);
      }
    }
    // Show the "Add Agenda" dropdown (strictly hide if cancellation meeting)
    const addWrap = document.getElementById('mt-add-agenda-wrap');
    if (addWrap) addWrap.style.display = isCancellation ? 'none' : 'block';
    if (!isCancellation) updateDynamicAgendaDropdown();

    // Reset to Reservation panel (or Cancellation panel if cancellation agenda)
    if (isCancellation) {
      toggleMtModePanel('cancellation');
      if (typeof renderMtModeCancellationPanel === 'function') renderMtModeCancellationPanel(res);
    } else {
      toggleMtModePanel('res');
    }

    const uploadLabel = document.getElementById('mt-mode-upload-label');
    if (uploadLabel) {
      if (isDesign) uploadLabel.textContent = "Upload reference photos for the design of the reservation";
      else if (isFood) uploadLabel.textContent = "Upload food presentation or feedback documents";
      else uploadLabel.textContent = "Finalize Contract / Document / Photos";
    }

    if (isFood) renderMtModeFoodPanel(res);

    if (isDesign) renderMtModeDesignPanel(res);
    if (isRundown) renderMtModeRundownPanel(res);
    if (isPayment) renderPaymentAssessmentPanel(res);
    if (isCancellation && typeof renderMtModeCancellationPanel === 'function') renderMtModeCancellationPanel(res);

    function updateBillingUI(resData) {
      // 1. Resolve linked reservation object first before evaluating cancellation state to avoid TDZ ReferenceError
      const res = (resData && resData.id)
        ? resData
        : (RESERVATIONS.find(r => r.id === (activeMeeting && (activeMeeting.reservationId || activeMeeting.reservation_id))) || activeMeetingResCache || resData || {});
      const initialSection = document.getElementById('mt-mode-billing-section');
      const dpSection = document.getElementById('mt-mode-downpayment-section');
      const finalSection = document.getElementById('mt-mode-final-payment-section');
      const cancelSection = document.getElementById('mt-mode-cancellation-billing-section');

      const agendaStr = (activeMeeting.agenda || "").toUpperCase();
      const isFinal = agendaStr.includes('CONTRACT');
      const isInitial = agendaStr.includes('INITIAL RESERVATION');
      const isRundownAgenda = agendaStr.includes('RUNDOWN');
      const isCancelledRes = isReservationCancelled(resData) || isReservationCancelled(res);
      const isCancel = agendaStr.includes('CANCELLATION') || isCancelledRes;

      if (cancelSection) cancelSection.style.display = isCancel ? 'block' : 'none';
      if (isCancel && typeof updateCancellationBillingUI === 'function') {
        updateCancellationBillingUI(resData || res);
      }

      // Initial Billing should only show for Contract Finalization or Initial Reservation
      if (initialSection) {
        initialSection.style.display = (!isCancel && (isFinal || isInitial)) ? 'block' : 'none';
      }

      // Display the Downpayment Schedule, Final Payment Schedule, and Cancellation Window panels for ANY agenda selected aside from Final Rundown or Cancellation
      if (dpSection) dpSection.style.display = (!isRundownAgenda && !isCancel) ? 'block' : 'none';
      if (finalSection) finalSection.style.display = (!isRundownAgenda && !isCancel) ? 'block' : 'none';
      const cancelWindowSection = document.getElementById('mt-mode-cancellation-window-section');
      if (cancelWindowSection) cancelWindowSection.style.display = (!isRundownAgenda && !isCancel) ? 'block' : 'none';

      // 1. Downpayment Section (SCHEDULING - Metadata)
      const _dpRes = res || activeMeetingResCache || {};

      const _details = computePricingDetails(_dpRes, mtPax);
      const total = _details.finalTotal;
      const downpayment = Math.round(_details.basePrice * 0.5) || 0;

      // Ensure surcharge is saved if present
      if (res && mtVenueSurcharge > 0) res.venueSurcharge = mtVenueSurcharge;

      const dpAmtInput = document.getElementById('mt-downpayment-amount');
      const dpDueInput = document.getElementById('mt-downpayment-due');
      const dpBtn = document.getElementById('btn-save-downpayment');

      // Always lock amount to auto-calculated 50%
      dpAmtInput.value = downpayment;
      dpAmtInput.readOnly = true;
      dpAmtInput.disabled = false;

      // ── Render Pricing Details into mt-downpayment-pricing-details ──
      const _dpPricingEl = document.getElementById('mt-downpayment-pricing-details');
      if (_dpPricingEl) {
        let _html = `<div style="font-size:10px; color:var(--gold); font-weight:700; text-transform:uppercase; letter-spacing:1px; margin-bottom:10px;">Pricing Details</div>`;

        if (_details.isMajorlySet) {
          const _paxLabel = _details.pax > 0 ? ` (${_details.pax} pax)` : '';
          _html += `<div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px;"><span style="color:var(--text-dim);">Pricing Rule${_paxLabel}</span><span style="color:var(--cream);font-weight:600;">&#8369;${_details.basePrice.toLocaleString()}</span></div>`;
        } else if (_details.isDynamic) {
          _html += `<div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px;"><span style="color:var(--text-dim);">Pricing Rule (${_details.pax} pax &#8369;${_details.perHead.toLocaleString()}/head)</span><span style="color:var(--cream);font-weight:600;">&#8369;${_details.basePrice.toLocaleString()}</span></div>`;
        } else {
          // custom
          _html += `<div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px;"><span style="color:var(--text-dim);">Items Subtotal</span><span style="color:var(--cream);font-weight:600;">&#8369;${_details.basePrice.toLocaleString()}</span></div>`;
        }

        if (_details.extraItemsBreakdown && _details.extraItemsBreakdown.length > 0) {
          _details.extraItemsBreakdown.forEach(ei => {
            _html += `<div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px;"><span style="color:var(--gold);">${ei.name} (Extra)</span><span style="color:var(--gold);font-weight:600;">+&#8369;${ei.price.toLocaleString()}</span></div>`;
          });
        } else if (_details.extraItemsTotal > 0) {
          _html += `<div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px;"><span style="color:var(--gold);">Additional Items</span><span style="color:var(--gold);font-weight:600;">+&#8369;${_details.extraItemsTotal.toLocaleString()}</span></div>`;
        }
        if (_details.otc > 0) {
          _html += `<div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px;"><span style="color:var(--gold);">Out of Town Charge (+5%)</span><span style="color:var(--gold);font-weight:600;">+&#8369;${_details.otc.toLocaleString()}</span></div>`;
        }
        if (_details.serviceChargeAmt > 0) {
          _html += `<div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px;"><span style="color:var(--gold);">Service Charge (+${_details.serviceChargePct}%)</span><span style="color:var(--gold);font-weight:600;">+&#8369;${_details.serviceChargeAmt.toLocaleString()}</span></div>`;
        }

        _html += `<div style="display:flex;justify-content:space-between;font-size:13px;margin-top:8px;padding-top:8px;border-top:1px solid rgba(255,255,255,0.08);"><span style="color:var(--cream);font-weight:700;">Total Amount</span><span style="color:var(--gold);font-weight:800;">&#8369;${_details.finalTotal.toLocaleString()}</span></div>`;
        _html += `<div style="display:flex;justify-content:space-between;font-size:12px;margin-top:5px;"><span style="color:var(--text-dim);">Downpayment (50% without charges)</span><span style="color:var(--cream);font-weight:600;">&#8369;${downpayment.toLocaleString()}</span></div>`;

        _dpPricingEl.innerHTML = _html;
      }

      // Compute date constraints: min = today, max = halfway between today and event date
      const todayStr = new Date().toISOString().split('T')[0];
      dpDueInput.min = todayStr;
      // Try to set max = halfway between today and event date
      // Fall back to activeMeetingResCache.date if res is stale/null
      const rawEventDate = mtDate || (res && (res.date || res.eventDate || res.event_date)) || (activeMeetingResCache && (activeMeetingResCache.date || activeMeetingResCache.eventDate || activeMeetingResCache.event_date)) || (resData && (resData.date || resData.eventDate || resData.event_date)) || (activeMeeting && (activeMeeting.date || activeMeeting.eventDate)) || '';
      if (rawEventDate) {
        const evtMs = new Date(rawEventDate).getTime();
        const todayMs = new Date(todayStr).getTime();
        if (evtMs > todayMs) {
          const halfMs = Math.floor((todayMs + evtMs) / 2);
          dpDueInput.max = new Date(halfMs).toISOString().split('T')[0];
        }
      }

      if (document.activeElement !== dpDueInput) {
        dpDueInput.value = resData.downpaymentDueDate || '';
      }
      dpDueInput.disabled = false;
      dpBtn.disabled = false;
      dpBtn.textContent = 'Save Downpayment Schedule';

      const cancelBtn = document.getElementById('btn-cancel-downpayment');
      if (cancelBtn) {
        cancelBtn.disabled = !resData.downpaymentDueDate;
      }

      // 1.5 Final Payment Section (SCHEDULING - Metadata)
      const finalAmtInput = document.getElementById('mt-final-payment-amount');
      const finalDueInput = document.getElementById('mt-final-payment-due');
      const finalBtn = document.getElementById('btn-save-final-payment');
      const cancelFinalBtn = document.getElementById('btn-cancel-final-payment');

      const remainingBase = (_details.basePrice - downpayment);
      const finalPaymentAmount = remainingBase + (_details.extraItemsTotal || 0) + _details.otc + _details.serviceChargeAmt;

      if (finalAmtInput) {
        finalAmtInput.value = finalPaymentAmount;
        finalAmtInput.readOnly = true;
        finalAmtInput.disabled = false;
      }

      const _finalPricingEl = document.getElementById('mt-final-payment-pricing-details');
      if (_finalPricingEl) {
        let _fhtml = `<div style="font-size:10px; color:var(--gold); font-weight:700; text-transform:uppercase; letter-spacing:1px; margin-bottom:10px;">Final Payment Calculation</div>`;
        _fhtml += `<div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px;"><span style="color:var(--text-dim);">Remaining Base Balance (50%)</span><span style="color:var(--cream);font-weight:600;">&#8369;${remainingBase.toLocaleString()}</span></div>`;
        if (_details.extraItemsBreakdown && _details.extraItemsBreakdown.length > 0) {
          _fhtml += `<div style="margin-top:6px; margin-bottom:4px; font-size:10px; font-weight:700; color:var(--gold); text-transform:uppercase;">Additional Charges Included:</div>`;
          _details.extraItemsBreakdown.forEach(ei => {
            _fhtml += `<div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px;"><span style="color:var(--gold);">${ei.name}</span><span style="color:var(--gold);font-weight:600;">+&#8369;${ei.price.toLocaleString()}</span></div>`;
          });
        } else if (_details.extraItemsTotal > 0) {
          _fhtml += `<div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px;"><span style="color:var(--gold);">Additional Items</span><span style="color:var(--gold);font-weight:600;">+&#8369;${_details.extraItemsTotal.toLocaleString()}</span></div>`;
        }
        if (_details.otc > 0) {
          _fhtml += `<div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px;"><span style="color:var(--gold);">Out of Town Charge (+5%)</span><span style="color:var(--gold);font-weight:600;">+&#8369;${_details.otc.toLocaleString()}</span></div>`;
        }
        if (_details.serviceChargeAmt > 0) {
          _fhtml += `<div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px;"><span style="color:var(--gold);">Service Charge (+${_details.serviceChargePct}%)</span><span style="color:var(--gold);font-weight:600;">+&#8369;${_details.serviceChargeAmt.toLocaleString()}</span></div>`;
        }
        _fhtml += `<div style="display:flex;justify-content:space-between;font-size:13px;margin-top:8px;padding-top:8px;border-top:1px solid rgba(255,255,255,0.08);"><span style="color:var(--cream);font-weight:700;">Total Final Payment</span><span style="color:var(--gold);font-weight:800;">&#8369;${finalPaymentAmount.toLocaleString()}</span></div>`;
        _finalPricingEl.innerHTML = _fhtml;
      }

      // Safe date normalization helper to ensure 3 days prior is always computed accurately
      function _safeNormDate(raw) {
        if (!raw) return '';
        if (typeof normalizeDateKey === 'function') return normalizeDateKey(raw);
        if (typeof raw === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(raw)) return raw;
        const d = new Date(raw);
        if (isNaN(d.getTime())) return '';
        const y = d.getFullYear();
        const m = String(d.getMonth() + 1).padStart(2, '0');
        const day = String(d.getDate()).padStart(2, '0');
        return `${y}-${m}-${day}`;
      }

      let lockedDueDate = '';
      const _rawEvtVal = rawEventDate || mtDate || (res && (res.date || res.eventDate || res.event_date)) || (resData && (resData.date || resData.eventDate || resData.event_date)) || '';
      const eventDateVal = _safeNormDate(_rawEvtVal);
      if (eventDateVal) {
        const evtD = new Date(eventDateVal + 'T00:00:00');
        if (!isNaN(evtD.getTime())) {
          const d = new Date(evtD);
          d.setDate(d.getDate() - 3);
          lockedDueDate = d.toISOString().split('T')[0];
        }
      }

      if (finalDueInput) {
        // Auto-select exactly 3 days prior to event date, never empty if event date exists
        const targetDueDate = lockedDueDate || (resData && (resData.finalPaymentDueDate || resData.final_payment_due_date)) || (res && (res.finalPaymentDueDate || res.final_payment_due_date)) || '';
        finalDueInput.value = targetDueDate;
        finalDueInput.readOnly = true;
        finalDueInput.style.cursor = 'not-allowed';
        finalDueInput.style.background = 'rgba(255,255,255,0.05)';
        if (lockedDueDate) {
          finalDueInput.min = lockedDueDate;
          finalDueInput.max = lockedDueDate;
        }
        finalDueInput.disabled = false;

        let lockNotice = document.getElementById('mt-final-lock-notice');
        if (!lockNotice && finalDueInput.parentNode) {
          lockNotice = document.createElement('div');
          lockNotice.id = 'mt-final-lock-notice';
          lockNotice.style.cssText = 'font-size:11px; color:var(--gold); margin-top:4px; font-weight:600; display:flex; align-items:center; gap:5px;';
          lockNotice.innerHTML = 'Auto-locked: Exactly 3 days prior to event date';
          finalDueInput.parentNode.appendChild(lockNotice);
        }
      }
      if (finalBtn) {
        finalBtn.disabled = false;
        finalBtn.textContent = 'Save Final Payment Schedule';
      }
      if (cancelFinalBtn) {
        cancelFinalBtn.disabled = !((resData && (resData.finalPaymentDueDate || resData.final_payment_due_date)) || (res && (res.finalPaymentDueDate || res.final_payment_due_date)));
      }

      // Cancellation Window input & button initialization
      const cwInput = document.getElementById('mt-cancellation-window-date');
      const cwCancelBtn = document.getElementById('btn-cancel-cancellation-window');
      if (cwInput) {
        const todayStr = new Date().toISOString().split('T')[0];
        cwInput.min = todayStr;
        if (eventDateVal) cwInput.max = eventDateVal;
        const savedCw = (resData && (resData.cancellation_window || resData.cancellationWindow)) || (res && (res.cancellation_window || res.cancellationWindow)) || (activeMeeting && activeMeeting.cancellation_window) || '';
        cwInput.value = savedCw ? _safeNormDate(savedCw) : '';
        if (cwCancelBtn) cwCancelBtn.disabled = !cwInput.value;
      }

      // Initial Fee due date input initialization
      const initDueInput = document.getElementById('mt-initial-fee-due');
      if (initDueInput) {
        const todayStr = new Date().toISOString().split('T')[0];
        initDueInput.min = todayStr;
        if (eventDateVal) initDueInput.max = eventDateVal;
        const savedInitDue = (resData && (resData.initial_fee_due_date || resData.initialFeeDueDate)) || (res && (res.initial_fee_due_date || res.initialFeeDueDate)) || (activeMeeting && activeMeeting.initial_fee_due_date) || '';
        initDueInput.value = savedInitDue ? _safeNormDate(savedInitDue) : '';
      }

      // 2. Initial Fee Section (BILLING - Gateway)
      const initialBtn = document.getElementById('btn-pay-initial');
      const cancelInitialBtn = document.getElementById('btn-cancel-pay-initial');
      const paidBadge = document.getElementById('mt-billing-paid-badge');
      const paidMethod = document.getElementById('mt-billing-paid-method');
      const declinedNotice = document.getElementById('mt-billing-declined-notice');

      if (initialBtn && paidBadge && declinedNotice && activeMeeting) {
        const feeStatus = activeMeeting.initial_fee_status;

        // Reset display
        initialBtn.style.display = 'flex';
        initialBtn.disabled = false;
        initialBtn.textContent = 'Commence Initial Fee Payment';
        initialBtn.style.background = 'var(--gold)';
        initialBtn.style.color = '#000';

        if (cancelInitialBtn) {
          cancelInitialBtn.style.display = 'none';
          cancelInitialBtn.disabled = false;
          cancelInitialBtn.textContent = 'Cancel Request';
        }

        paidBadge.style.display = 'none';
        declinedNotice.style.display = 'none';
        const posSummary = document.getElementById('mt-billing-pos-summary');
        if (posSummary) posSummary.style.display = 'none';

        // Reset GCash proof panel state by default so stale proof from another meeting doesn't carry over
        if (typeof _resetGcashProofPanel === 'function') _resetGcashProofPanel();

        if (feeStatus !== 'cash_pending') {
          window._posAutoOpened = false;
        }

        const cantPayBtn = document.getElementById('btn-customer-cant-pay');
        if (cantPayBtn) cantPayBtn.style.display = 'flex';

        if (feeStatus === 'triggered') {
          if (typeof startAdminPaymongoPoll === 'function') startAdminPaymongoPoll();
          initialBtn.textContent = 'Waiting for Customer...';
          initialBtn.disabled = true;
          initialBtn.style.background = '#4b5563';
          initialBtn.style.color = '#ffffff';
          initialBtn.style.border = 'none';
          if (cantPayBtn) cantPayBtn.style.display = 'flex';
          if (cancelInitialBtn) cancelInitialBtn.style.display = 'flex';
        } else if (feeStatus === 'cash_pending') {
          if (typeof stopAdminPaymongoPoll === 'function') stopAdminPaymongoPoll();
          initialBtn.style.display = 'none';
          if (cantPayBtn) cantPayBtn.style.display = 'none';

          if (!window._posAutoOpened) {
            window._posAutoOpened = true;
            window.openPosModal();
          }
        } else if (feeStatus === 'paid') {
          if (typeof stopAdminPaymongoPoll === 'function') stopAdminPaymongoPoll();
          initialBtn.style.display = 'none';
          if (cancelInitialBtn) cancelInitialBtn.style.display = 'none';
          if (cantPayBtn) cantPayBtn.style.display = 'none';
          paidBadge.style.display = 'flex';
          const isGcash = activeMeeting.initial_fee_method === 'gcash' || activeMeeting.initial_fee_method === 'paymongo';
          paidMethod.textContent = activeMeeting.initial_fee_method === 'cash' ? '(Cash)' : (isGcash ? '(GCash)' : '(Online)');

          if (posSummary && (activeMeeting.initial_fee_received || activeMeeting.initial_fee_method)) {
            const parseDT = (dt) => { try { return new Date(dt).toLocaleString('en-US', { dateStyle: 'medium', timeStyle: 'short' }); } catch (e) { return dt; } };
            posSummary.style.display = 'block';
            const mInitPaymongoId = activeMeeting.initial_fee_paymongo_id || activeMeeting.initial_fee_paymongo_payment_id || (activeMeeting.initial_fee_ref_id && String(activeMeeting.initial_fee_ref_id).startsWith('pay_') ? activeMeeting.initial_fee_ref_id : null) || (activeMeetingResCache && activeMeetingResCache.initial_fee_paymongo_id);
            const mInitRef = mInitPaymongoId || activeMeeting.initial_fee_ref_id || activeMeeting.initialFeeRefId || ('PAY-INIT-' + String(activeMeeting.reservation_id || activeMeeting.reservationId || currentMeetingResId || '000000').slice(-6).toUpperCase());
            const isCash = activeMeeting.initial_fee_method === 'cash';
            const receiptTitle = isCash ? 'POS Transaction Receipt' : 'GCash / Online Transaction Receipt';
            const methodLabel = isCash ? 'Cash' : (isGcash ? 'GCash (PayMongo)' : 'Online Payment');
            const amtPaid = parseFloat(activeMeeting.initial_fee_received || 5000);
            const amtChg = parseFloat(activeMeeting.initial_fee_change || 0);
            const receivedBy = activeMeeting.initial_fee_received_by || (isCash ? 'Admin' : 'PayMongo Gateway (GCash)');
            const paidAt = parseDT(activeMeeting.initial_fee_paid_at || new Date().toISOString());

            posSummary.innerHTML = `
              <div style="background:rgba(255,255,255,0.03); border:1px dashed var(--border); border-radius:8px; padding:12px; font-size:12px;">
                <div style="font-weight:700; color:var(--gold); margin-bottom:8px; text-transform:uppercase; letter-spacing:1px; font-size:10px;">${receiptTitle}</div>
                <div style="display:flex; justify-content:space-between; margin-bottom:4px;"><span style="color:var(--text-dim);">Reference ID</span><span style="font-family:monospace; font-weight:700; color:var(--gold);">${mInitRef}</span></div>
                ${mInitPaymongoId ? `
                <div style="display:flex; justify-content:space-between; margin-bottom:4px;"><span style="color:var(--text-dim); font-size:11px;">PayMongo Receipt ID</span><span style="font-family:monospace; font-weight:700; color:#3898ec; font-size:11.5px;">${mInitPaymongoId}</span></div>
                ` : ''}
                <div style="display:flex; justify-content:space-between; margin-bottom:4px;"><span style="color:var(--text-dim);">Amount Due</span><span>&#8369;5,000.00</span></div>
                <div style="display:flex; justify-content:space-between; margin-bottom:4px;"><span style="color:var(--text-dim);">${isCash ? 'Cash Received' : 'Amount Paid'}</span><span>&#8369;${amtPaid.toLocaleString('en-US', { minimumFractionDigits: 2 })}</span></div>
                ${isCash ? `<div style="display:flex; justify-content:space-between; margin-bottom:4px;"><span style="color:var(--text-dim);">Change Given</span><span>&#8369;${amtChg.toLocaleString('en-US', { minimumFractionDigits: 2 })}</span></div>` : ''}
                <div style="display:flex; justify-content:space-between; margin-bottom:4px;"><span style="color:var(--text-dim);">Payment Method</span><span>${methodLabel}</span></div>
                <div style="display:flex; justify-content:space-between; margin-bottom:4px;"><span style="color:var(--text-dim);">Received By</span><span>${receivedBy}</span></div>
                <div style="display:flex; justify-content:space-between; margin-bottom:4px;"><span style="color:var(--text-dim);">Received At</span><span>${paidAt}</span></div>
                <div style="display:flex; justify-content:space-between; font-weight:700; color:var(--green);"><span style="color:var(--text-dim);">Status</span><span>Paid</span></div>
              </div>
            `;
          }
        } else if (feeStatus === 'declined_24h' || feeStatus === 'pending_schedule' || (activeMeeting && activeMeeting.initial_fee_due_date) || (activeMeetingResCache && (activeMeetingResCache.initial_fee_due_date || activeMeetingResCache.initialFeeDueDate))) {
          if (typeof stopAdminPaymongoPoll === 'function') stopAdminPaymongoPoll();
          initialBtn.style.display = 'none';
          if (cantPayBtn) cantPayBtn.style.display = 'none';
          declinedNotice.style.display = 'block';
          if (cancelInitialBtn) cancelInitialBtn.style.display = 'flex';
          const initDueVal = (activeMeeting && activeMeeting.initial_fee_due_date) || (activeMeetingResCache && (activeMeetingResCache.initial_fee_due_date || activeMeetingResCache.initialFeeDueDate)) || '';
          const schedTextEl = document.getElementById('mt-billing-scheduled-text');
          if (schedTextEl) {
            schedTextEl.textContent = initDueVal ? ('Customer to settle initial reservation fee by: ' + initDueVal) : 'Customer to settle initial reservation fee by scheduled due date.';
          }
        } else if (feeStatus === 'gcash_pending' || feeStatus === 'gcash_dismissed') {
          if (typeof stopAdminPaymongoPoll === 'function') stopAdminPaymongoPoll();
          // Customer chose GCash, waiting for them to upload screenshot
          initialBtn.textContent = 'Waiting for GCash Proof...';
          initialBtn.disabled = true;
          initialBtn.style.background = 'rgba(255,255,255,0.1)';
          initialBtn.style.color = 'var(--text-dim)';
          if (cantPayBtn) cantPayBtn.style.display = 'none';
          const proofPanel = document.getElementById('mt-gcash-proof-panel');
          if (proofPanel) proofPanel.style.display = 'none';
        } else if (feeStatus === 'gcash_proof_uploaded') {
          if (typeof stopAdminPaymongoPoll === 'function') stopAdminPaymongoPoll();
          // Customer uploaded screenshot - show the proof panel
          initialBtn.style.display = 'none';
          if (cancelInitialBtn) cancelInitialBtn.style.display = 'none';
          if (cantPayBtn) cantPayBtn.style.display = 'none';
          const proofPanel = document.getElementById('mt-gcash-proof-panel');
          const proofImg = document.getElementById('mt-gcash-proof-img');
          const proofLink = document.getElementById('mt-gcash-proof-link');
          if (proofPanel) {
            // Always wipe stale inputs/buttons before showing so a re-upload is always clean
            const _amtInput  = document.getElementById('gcash-confirm-amount');
            const _chgEl     = document.getElementById('gcash-confirm-change');
            const _errEl     = document.getElementById('gcash-confirm-error');
            const _cfmBtn    = document.getElementById('btn-confirm-gcash-payment');
            const _dismBtn   = document.getElementById('btn-dismiss-gcash-payment');
            if (_amtInput) _amtInput.value = '';
            if (_chgEl)  _chgEl.innerHTML = '&#8369;0.00';
            if (_errEl)  _errEl.style.display = 'none';
            if (_cfmBtn) {
              _cfmBtn.disabled = true;
              _cfmBtn.innerHTML = 'Confirm Payment';
              _cfmBtn.style.background = 'var(--green,#2ea043)';
              _cfmBtn.style.color = '#fff';
              _cfmBtn.style.border = 'none';
              _cfmBtn.style.opacity = '0.5';
              _cfmBtn.style.cursor = 'not-allowed';
            }
            if (_dismBtn) {
              _dismBtn.disabled = false;
              _dismBtn.innerHTML = 'Dismiss';
              _dismBtn.style.opacity = '1';
              _dismBtn.style.cursor = 'pointer';
            }
            proofPanel.style.display = 'block';
            const proofUrl = activeMeeting.initial_fee_proof || activeMeeting.initial_fee_proof_url || activeMeeting.initial_fee_received_by || '';
            if (proofImg) proofImg.src = proofUrl;
            if (proofLink) proofLink.href = proofUrl;
          }
        }
      }
    }
    // Expose for external calls (post-modification refresh)
    window.updateBillingUI = updateBillingUI;

    let _adminPaymongoPollTimer = null;
    let _isAdminCheckingPaymongo = false;

    function startAdminPaymongoPoll() {
      if (_adminPaymongoPollTimer) return;
      if (!activeMeeting || !activeMeeting.id || activeMeeting.id === 'demo') return;

      const mtId = activeMeeting.id;
      const pollFn = async () => {
        if (!activeMeeting || activeMeeting.id !== mtId) {
          stopAdminPaymongoPoll();
          return;
        }
        if (activeMeeting.initial_fee_status === 'paid') {
          stopAdminPaymongoPoll();
          return;
        }
        if (_isAdminCheckingPaymongo) return;
        _isAdminCheckingPaymongo = true;
        try {
          const resId = activeMeeting.reservationId || activeMeeting.reservation_id || '';
          const resp = await fetch(`/api/paymongo?action=check&meetingId=${encodeURIComponent(mtId)}&resId=${encodeURIComponent(resId)}`, {
            headers: { 'Accept': 'application/json' }
          });
          if (!resp.ok) return;
          const data = await resp.json();
          if (data && data.paid) {
            stopAdminPaymongoPoll();
            if (activeMeeting && activeMeeting.id === mtId) {
              activeMeeting.initial_fee_status = 'paid';
              activeMeeting.initial_fee_method = data.method || 'gcash';
              activeMeeting.initial_fee_received = data.amount || 5000;
              activeMeeting.initial_fee_change = 0;
              activeMeeting.initial_fee_paid_at = new Date().toISOString();
              activeMeeting.initial_fee_received_by = `PayMongo Gateway (${(data.method || 'gcash').toUpperCase()})`;
              activeMeeting.initial_fee_ref_id = data.paymentId || data.refId || ('PAY-INIT-' + String(resId || '000000').slice(-6).toUpperCase());
              activeMeeting.initial_fee_paymongo_id = data.paymentId || data.paymongoPaymentId || (data.refId && String(data.refId).startsWith('pay_') ? data.refId : null);
              activeMeeting.paymongo_payment_id = activeMeeting.initial_fee_paymongo_id;

              if (typeof updateBillingUI === 'function') {
                updateBillingUI(activeMeetingResCache || resId);
              }

              // Show toast notification
              const toast = document.createElement('div');
              toast.style.cssText = 'position:fixed;bottom:24px;right:24px;background:#2ea043;color:#fff;padding:16px 24px;border-radius:12px;font-size:14px;font-weight:700;z-index:99999;box-shadow:0 8px 30px rgba(0,0,0,0.4);border:1px solid rgba(255,255,255,0.2);';
              toast.textContent = 'Online Payment Verified: GCash initial fee payment received from customer.';
              document.body.appendChild(toast);
              setTimeout(() => toast.remove(), 6000);
            }
          }
        } catch (err) {
          console.warn('[AdminPaymongoPoll] check warning:', err);
        } finally {
          _isAdminCheckingPaymongo = false;
        }
      };

      _adminPaymongoPollTimer = setInterval(pollFn, 2500);
      setTimeout(pollFn, 1000);
    }

    function stopAdminPaymongoPoll() {
      if (_adminPaymongoPollTimer) {
        clearInterval(_adminPaymongoPollTimer);
        _adminPaymongoPollTimer = null;
      }
    }
    window.startAdminPaymongoPoll = startAdminPaymongoPoll;
    window.stopAdminPaymongoPoll = stopAdminPaymongoPoll;


    if (window.activeMtResUnsub) {
      window.activeMtResUnsub();
      window.activeMtResUnsub = null;
    }

    if (window.activeMtSbUnsub) {
      window.supabaseClient.removeChannel(window.activeMtSbUnsub);
      window.activeMtSbUnsub = null;
    }

    if (mtId && mtId !== 'demo' && window.supabaseClient) {
      window.activeMtSbUnsub = window.supabaseClient.channel('admin-meeting-' + mtId)
        .on('postgres_changes', { event: '*', schema: 'public', table: 'meetings', filter: 'id=eq.' + mtId }, (payload) => {
          if (payload.new && activeMeeting) {
            Object.assign(activeMeeting, payload.new);
            try {
              let cData = null;
              if (payload.new.live_draft && payload.new.live_draft.cancellation_pay) {
                cData = payload.new.live_draft.cancellation_pay;
              } else if (payload.new.cancellationNote && typeof payload.new.cancellationNote === 'string' && payload.new.cancellationNote.trim().startsWith('{')) {
                cData = JSON.parse(payload.new.cancellationNote);
              }
              if (cData && typeof cData === 'object') {
                Object.assign(activeMeeting, cData);
              } else if (!payload.new.cancellationNote && (!payload.new.live_draft || !payload.new.live_draft.cancellation_pay)) {
                activeMeeting.cancellation_fee_status = null;
                activeMeeting.cancellation_pay_triggered = false;
                activeMeeting.cancellation_fee_proof = null;
              }
            } catch (err) {}
            updateBillingUI(activeMeetingResCache);
            if (typeof renderMtModeCancellationPanel === 'function') {
              renderMtModeCancellationPanel(activeMeetingResCache);
            }
            // If customer uploaded docs, merge them into mtUploadedUrls and re-render
            const freshDocs = payload.new.shared_documents || [];
            if (freshDocs.length > 0) {
              // Merge: keep admin's local entries, add any from freshDocs not already present
              const existingUrls = new Set(mtUploadedUrls.map(f => f.url));
              freshDocs.forEach(d => {
                if (!existingUrls.has(d.url)) {
                  mtUploadedUrls.push(d);
                  existingUrls.add(d.url);
                }
              });
              if (typeof renderMtUploadList === 'function') renderMtUploadList();
            }
          }
        }).subscribe();
    }

    renderMtModeResDetails(res);

    if (res && res.id !== 'demo-res-123') {
      // Call immediately so the downpayment shows on open, before the first snapshot fires
      updateBillingUI(activeMeetingResCache || res);
      if (window.firebaseFns && window.firebaseFns.doc && window.firebaseFns.onSnapshot && window.firebaseDB) {
        try {
          const { doc, onSnapshot } = window.firebaseFns;
          window.activeMtResUnsub = onSnapshot(doc(window.firebaseDB, 'reservations', res.id), (snap) => {
            if (snap.exists()) {
              activeMeetingResCache = { id: snap.id, ...snap.data() };
              updateBillingUI(activeMeetingResCache);
            }
          });
        } catch(snapErr) {
          console.warn('Meeting reservation snapshot setup notice:', snapErr);
        }
      }
    } else {
      updateBillingUI(res);
    }
  } catch (e) { console.error(e); }
}


let mtModifyMode = false;
