window.handleMtReplaceFood = function (dish) {
  // Resolve the category of the dish being replaced
  const catalogEntry = CAT.find(c => c.name === dish);
  const dishCat = (catalogEntry && catalogEntry.cat) ? catalogEntry.cat.toLowerCase() : 'food';

  // Show a styled in-page mini confirmation panel first, not browser confirm
  const existingModal = document.getElementById('mt-replace-confirm-modal');
  if (existingModal) existingModal.remove();

  const modal = document.createElement('div');
  modal.id = 'mt-replace-confirm-modal';
  modal.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.7);z-index:999999;display:flex;align-items:center;justify-content:center;backdrop-filter:blur(4px);';

  const origin = getMtOrigin();
  const isLocked = (origin === 'dynamically set' || origin === 'majorly set');
  const catLabel = dishCat.charAt(0).toUpperCase() + dishCat.slice(1);
  const warningHtml = isLocked
    ? `<div style="background:rgba(192,57,43,0.12);border:1px solid rgba(192,57,43,0.4);border-radius:8px;padding:10px 14px;font-size:12px;color:#e74c3c;margin-bottom:16px;">
        <strong>⚠️ ${origin.charAt(0).toUpperCase() + origin.slice(1)} Package</strong><br>
        Items in this package are set. Proceeding will forcefully replace <strong>${dish}</strong> with a ${dishCat} item you choose.
       </div>`
    : '';

  modal.innerHTML = `
    <div style="background:var(--card,#1e1e1e);padding:32px;border-radius:16px;width:90%;max-width:440px;border:1px solid var(--border,#333);box-shadow:0 12px 40px rgba(0,0,0,0.5);">
      <h2 style="margin:0 0 8px;font-size:20px;color:var(--text,#fff);">Replace ${catLabel} Item?</h2>
      <p style="font-size:13px;color:var(--text-dim,#aaa);margin-bottom:20px;">
        You are about to replace <strong style="color:var(--gold,#c49a3c);">${dish}</strong> from the package with a different <strong>${catLabel}</strong> item.<br>Proceed to the catalog to choose the replacement.
      </p>
      ${warningHtml}
      <div style="display:flex;gap:12px;">
        <button onclick="document.getElementById('mt-replace-confirm-modal').remove()" style="flex:1;padding:12px;border-radius:8px;border:none;background:#4b5563;color:#ffffff;cursor:pointer;font-size:13px;font-weight:700;">Cancel</button>
        <button id="mt-replace-proceed-btn" style="flex:1;padding:12px;border-radius:8px;border:none;background:#c0392b;color:#fff;cursor:pointer;font-size:13px;font-weight:700;">Yes, Replace</button>
      </div>
    </div>`;

  document.body.appendChild(modal);

  document.getElementById('mt-replace-proceed-btn').onclick = function () {
    modal.remove();
    // Store both the dish name and its category
    window.mtReplaceFoodMode = { dish, cat: dishCat };
    window.toggleMtModifyMode();
  };
};
