  const nowIso = new Date().toISOString();
  const refId = 'POS-BIZ-' + String(res.id || '000000').slice(-6).toUpperCase();
  const adminName = (typeof currentAdminUser !== 'undefined' && currentAdminUser?.name) || 'Admin';

  res.cancellation_by = 'business';
  res.cancelled_by = 'business';
  res.business_liability_paid = true;
  res.cancellation_business_paid = true;
  res.cancellation_status = 'settled';
  res.cancellation_request_status = 'settled';
  res.cancellation_payout_method = 'cash';
