window.validateMeetingFinalization = function () {
  if (!activeMeeting || !activeMeetingResCache) return;

  const checks = [];
  const agendaStr = (activeMeeting.agenda || "").toUpperCase();

  const hasFood = agendaStr.includes('FOOD TASTING') || dynamicAgendas.includes('food');
  const hasDesign = agendaStr.includes('DESIGN') || dynamicAgendas.includes('design');
  const hasLogistics = agendaStr.includes('ADDITIONAL RESERVATION DISCUSSION') || dynamicAgendas.includes('logistics');

  if (hasFood) {
    // ALL food items must first be marked as tried
    const allFoodRows = document.querySelectorAll('#mt-food-tasting-list > div');
    const untriedItems = [];
    allFoodRows.forEach(row => {
      const triedCb = row.querySelector('.food-tried');
      if (triedCb && !triedCb.checked) untriedItems.push(triedCb.dataset.dish || 'Unknown dish');
    });
    checks.push({
      label: `All food items must be marked as Tried (${untriedItems.length > 0 ? untriedItems.join(', ') + ' not yet tried' : 'All marked ✓'})`,
      passed: untriedItems.length === 0
    });

    // All checked (tried) items must have a definitive decision: approved or rejected
    const triedRows = [];
    document.querySelectorAll('#mt-food-tasting-list > div').forEach(row => {
      const triedCb = row.querySelector('.food-tried');
      if (triedCb && triedCb.checked) {
        const decision = row.querySelector('.food-decision');
        triedRows.push({ dish: triedCb.dataset.dish, decision: decision ? decision.value : 'pending' });
      }
    });
    const pendingItems = triedRows.filter(r => r.decision === 'pending');
    checks.push({
      label: `All tried items must be marked Approved or Rejected (${pendingItems.length > 0 ? pendingItems.map(r => r.dish).join(', ') + ' still Pending' : 'All clear ✓'})`,
      passed: pendingItems.length === 0
    });
  }

  if (hasDesign) {
    const designRows = document.querySelectorAll('#mt-design-items-list > div[data-item-name]');
    const unselectedItems = [];
    designRows.forEach(row => {
      const selected = row.querySelector('.catalog-img.selected');
      if (!selected) unselectedItems.push(row.dataset.itemName || 'Unknown item');
    });
    if (designRows.length > 0) {
      checks.push({
        label: `A catalog option must be selected for all decoration items (${unselectedItems.length > 0 ? unselectedItems.join(', ') + ' : no option selected' : 'All items have a selection ✓'})`,
        passed: unselectedItems.length === 0
      });
    }
  }

  if (hasLogistics) {
    const _cRes = RESERVATIONS.find(r => r.id === activeMeeting.reservationId);
    if (_cRes) {
      const _cPax = parseInt(_cRes.pax) || 0;
      const _rawVip = _cRes.vipCount != null ? _cRes.vipCount : (_cRes.vip && typeof _cRes.vip === 'object' ? _cRes.vip.count : _cRes.vip);
      const _cVipPax = parseInt(_rawVip) || 0;
      const _cExtra = getActiveReservationExtra(activeMeeting.reservationId);

      // Guest list vs pax
      if (_cExtra && Array.isArray(_cExtra.guests)) {
        const _cNamed = _cExtra.guests.filter(g => (g.name || '').trim()).length;
        checks.push({
          label: `Guest list (${_cNamed} names) must not exceed reservation pax (${_cPax})${_cNamed > _cPax ? ` : remove ${_cNamed - _cPax} guest(s)` : ' ✓'}`,
          passed: _cNamed <= _cPax
        });
      }

      // Total chairs vs pax
      if (Array.isArray(seatingElements)) {
        const _cChairs = seatingElements.filter(e => e.type === 'chair').length;
        checks.push({
          label: `Venue chairs (${_cChairs}) must not exceed reservation pax (${_cPax})${_cChairs > _cPax ? ` : remove ${_cChairs - _cPax} chair(s)` : ' ✓'}`,
          passed: _cChairs <= _cPax
        });

        // VIP chairs vs vipCount
        if (_cVipPax > 0) {
          let _cVipChairs = 0;
          seatingElements.forEach(e => {
            if (e.type === 'chair' && e.parentId) {
              const _cp = seatingElements.find(p => p.id === e.parentId);
              if (_cp && _cp.isVip) _cVipChairs++;
            }
          });
          checks.push({
            label: `VIP chairs (${_cVipChairs}) must not exceed VIP pax (${_cVipPax})${_cVipChairs > _cVipPax ? ` : remove ${_cVipChairs - _cVipPax} VIP chair(s)` : ' ✓'}`,
            passed: _cVipChairs <= _cVipPax
          });
        }

        // Event flow items past end time
        const _cTimeStr = _cRes.time || '';
        const _cToTimePart = _cTimeStr.split(/\sto\s/i)[1] || '';
        const _cEndMins = _parseResTimeToMinutes(_cToTimePart.trim());
        if (_cEndMins !== null && _cRes.executionPlan && Array.isArray(_cRes.executionPlan.phases)) {
          let _cFlowOverrun = [];
          _cRes.executionPlan.phases.forEach(ph => {
            if (Array.isArray(ph.agenda)) {
              ph.agenda.forEach(item => {
                if (item.time) {
                  const _iMins = _parseResTimeToMinutes(item.time);
                  if (_iMins !== null && _iMins > _cEndMins) {
                    _cFlowOverrun.push(item.text || 'Unnamed item');
                  }
                }
              });
            }
          });
          if (_cFlowOverrun.length > 0 || _cEndMins !== null) {
            checks.push({
              label: `Event flow items must be within reservation time${_cFlowOverrun.length > 0 ? ` : ${_cFlowOverrun.length} item(s) exceed end time: ${_cFlowOverrun.join(', ')}` : ' ✓'}`,
              passed: _cFlowOverrun.length === 0
            });
          }
        }
      }
    }
  }

  if (agendaStr.includes('CONTRACT FINALIZATION')) {
    // 1. Document Added
    const hasDoc = mtUploadedUrls && mtUploadedUrls.some(f => (f.agenda || 'res') === 'res');
    checks.push({
      label: "A contract or final document is uploaded",
      passed: hasDoc
    });

    // 2. Downpayment Schedule Set
    const dpDueInput = document.getElementById('mt-downpayment-due');
    const hasDp = dpDueInput && dpDueInput.value.trim() !== '';
    checks.push({
      label: "Downpayment schedule date is set",
      passed: hasDp
    });

    // 3. Initial Fee Settled
    const initDueDate = (activeMeeting && (activeMeeting.initial_fee_due_date || activeMeeting.initialFeeDueDate)) ||
      (activeMeetingResCache && (activeMeetingResCache.initial_fee_due_date || activeMeetingResCache.initialFeeDueDate)) ||
      (document.getElementById('mt-initial-fee-due')?.value.trim()) ||
      ((typeof RESERVATIONS !== 'undefined' && (activeMeeting?.reservationId || activeMeeting?.reservation_id)) ? RESERVATIONS.find(r => r.id === (activeMeeting.reservationId || activeMeeting.reservation_id))?.initial_fee_due_date : null);
    const feeStatus = activeMeeting.initial_fee_status || (activeMeetingResCache && activeMeetingResCache.initial_fee_status);
    const isFeeSettled = feeStatus === 'paid' || feeStatus === 'declined_24h' || feeStatus === 'pending_schedule' || feeStatus === 'scheduled' || !!initDueDate;
    checks.push({
      label: "Initial reservation billing is settled (Paid or Delayed)",
      passed: isFeeSettled
    });

    // 4. Final Payment Schedule must be saved (mandatory for contract finalization)
    const _resFinalCheck = (activeMeetingResCache || (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS.find(r => r.id === activeMeeting?.reservationId) : null) || {});
    const hasFinalPaymentSaved = !!(
      (_resFinalCheck && (_resFinalCheck.finalPaymentDueDate || _resFinalCheck.final_payment_due_date)) ||
      (activeMeeting && (activeMeeting.finalPaymentDueDate || activeMeeting.final_payment_due_date))
    );
    checks.push({
      label: "Final Payment Schedule must be saved before completing this meeting",
      passed: hasFinalPaymentSaved
    });

    // 5. Cancellation window schedule is set (mandatory for contract finalization)
    const cwVal = (activeMeeting && (activeMeeting.cancellation_window || activeMeeting.cancellationWindow)) ||
      (activeMeetingResCache && (activeMeetingResCache.cancellation_window || activeMeetingResCache.cancellationWindow)) ||
      (document.getElementById('mt-cancellation-window-date')?.value.trim()) ||
      ((typeof RESERVATIONS !== 'undefined' && (activeMeeting?.reservationId || activeMeeting?.reservation_id)) ? RESERVATIONS.find(r => r.id === (activeMeeting.reservationId || activeMeeting.reservation_id))?.cancellation_window : null);
    checks.push({
      label: "Cancellation window schedule is set",
      passed: !!cwVal
    });
  }


  const allPassed = checks.length === 0 || checks.every(c => c.passed);

  if (allPassed) {
    markContractFinalized();
  } else {
    const listHtml = checks.map(c => {
      const icon = c.passed
        ? '<i class="fas fa-check-circle" style="color:var(--green); font-size:16px;"></i>'
        : '<i class="fas fa-times-circle" style="color:var(--red); font-size:16px;"></i>';
      const color = c.passed ? 'var(--text)' : 'var(--red)';
      return `<div style="display:flex; align-items:center; gap:10px; font-size:14px; color:${color}; font-weight:600;">${icon} ${c.label}</div>`;
    }).join('');

    document.getElementById('validation-checklist').innerHTML = listHtml;
    document.getElementById('admin-validation-modal').style.display = 'flex';
  }
};

window.markContractFinalized = markContractFinalized;
