window.sendMtChatMsg = async function () {
  const input = document.getElementById('mt-chat-input');
  const text = input.value.trim();
  if (!text || !activeMtResId) return;

  const sb = window.supabaseClient;
  if (!sb) return;

  const customerId = window.activeMtCustomerId;
  if (!customerId) return;

  try {
    const { data: { session } } = await sb.auth.getSession();
    const sender_id = session?.user?.id || (typeof activeCustomerId !== 'undefined' ? activeCustomerId : null) || (typeof uid !== 'undefined' ? uid : null) || 'b2700254-57b5-4b91-bef2-d0228531fb95';

    const newMsg = {
      customer_id: customerId,
      sender_role: 'admin',
      sender_id: sender_id,
      message: text,
      created_at: new Date().toISOString()
    };
    
    // Optimistic render
    if (window._mtChatAppend) {
      newMsg.id = 'opt_' + Date.now();
      window._mtChatAppend(newMsg);
    }
    input.value = '';

    const dbMsg = { ...newMsg };
    delete dbMsg.id;

    const { error } = await sb.from('support_messages').insert([dbMsg]);
    if (error) throw error;
  } catch (e) {
    console.error("Chat send failed", e);
  }
};

// ===== EVENT DETAILS =====
let currentEditingEventId = null;

function openEventDetails(id) {
  const ev = RESERVATIONS.find(r => r.id === id);
  if (!ev) return;
  currentEditingEventId = id;

  // Reset view to standard details view
  const edMain = document.getElementById('ed-main-body');
  const edFeas = document.getElementById('ed-feasibility-body');
  const btnFeas = document.getElementById('btn-assess-feasibility');
  if (edMain) edMain.style.display = 'block';
  if (edFeas) { edFeas.style.display = 'none'; edFeas.innerHTML = ''; }
  if (btnFeas) btnFeas.textContent = 'Assess Feasibility';

  const set = (elId, val) => { const el = document.getElementById(elId); if (el) el.textContent = val || ':'; };

  // Header
  document.getElementById('ed-title').textContent = ev.client + ' : ' + (ev.packageName || ev.type || 'Event');

  // Origin / category badge
  const originRaw = ev.package_origin || ev.packageOrigin || '';
  let originLabel = 'Custom';
  if (originRaw.toLowerCase().includes('dynamically')) originLabel = 'Dynamically Set';
  else if (originRaw.toLowerCase().includes('majorly')) originLabel = 'Majorly Set';
  const statusLabel = (ev.status || 'pending').charAt(0).toUpperCase() + (ev.status || 'pending').slice(1);
  const originBadge = document.getElementById('ed-origin-badge');
  if (originBadge) originBadge.textContent = originLabel + '  •  ' + statusLabel;

  // Package name & description
  set('ed-pkg-name', ev.packageName || ev.name || ev.type || 'Custom Package');
  const edPremadeWrap = document.getElementById('ed-premade-name-wrap');
  const edPremadeVal = document.getElementById('ed-premade-name');
  const origPremadeName = ev.premadePackageName || ev.premade_package_name || null;
  if (edPremadeWrap && edPremadeVal) {
    if (origPremadeName) {
      edPremadeVal.textContent = origPremadeName;
      edPremadeWrap.style.display = 'block';
    } else {
      edPremadeWrap.style.display = 'none';
    }
  }
  const descEl = document.getElementById('ed-description');
  if (descEl) descEl.textContent = ev.description || ev.eventDescription || '';

  // Price & pax
  set('ed-amount', ev.displayAmount || (ev.amount ? '₱' + Number(ev.amount).toLocaleString() : ':'));
  set('ed-pax', (ev.pax || '0') + ' Pax');

  // Info grid
  set('ed-theme', ev.theme || ':');
  set('ed-occasion', ev.type || ev.occasion || ':');
  set('ed-date', ev.date || ':');
  // Normalize time string for display : handles '2:00 to 3 AM', '02:00 - 15:00', '2:00 AM to 3:00 PM' etc.
  (function () {
    const rawTime = ev.time || ev.timeframe || '';
    if (!rawTime) { set('ed-timeframe', ':'); return; }
    const _sep = rawTime.toLowerCase().includes(' to ') ? / to /i : (rawTime.includes('-') ? /-/ : null);
    if (!_sep) { set('ed-timeframe', rawTime); return; }
    const _parts = rawTime.split(_sep).map(p => p.trim());
    const _fmt = (str) => {
      if (!str) return '';
      if (/^\d{1,2}:\d{2}$/.test(str)) {
        let h = parseInt(str), m = str.split(':')[1];
        const ap = h >= 12 ? 'PM' : 'AM'; h = h % 12 || 12;
        return h + ':' + m + ' ' + ap;
      }
      const match = str.match(/(\d{1,2}):?(\d{2})?\s*(AM|PM|am|pm)?/i);
      if (!match) return str;
      let h = parseInt(match[1]), m = match[2] || '00', ap = (match[3] || '').toUpperCase();
      if (!ap) ap = h >= 12 ? 'PM' : 'AM';
      h = h % 12 || 12;
      return h + ':' + m + ' ' + ap;
    };
    if (_parts.length >= 2) set('ed-timeframe', _fmt(_parts[0]) + ' to ' + _fmt(_parts[_parts.length - 1]));
    else set('ed-timeframe', rawTime);
  })();

  // Call Time
  const rawCallTime = ev.callTime || ev.call_time || ev.calltime || '';
  if (rawCallTime) {
    if (/^\d{1,2}:\d{2}$/.test(rawCallTime)) {
      let h = parseInt(rawCallTime), m = rawCallTime.split(':')[1];
      const ap = h >= 12 ? 'PM' : 'AM'; h = h % 12 || 12;
      set('ed-calltime', h + ':' + m + ' ' + ap);
    } else {
      set('ed-calltime', rawCallTime);
    }
  } else {
    set('ed-calltime', ':');
  }

  // Contact Phone
  let clientPhone = ev.phone || ev.client_phone || ev.customer_phone || ev.clientPhone || ev.customerPhone;
  if (!clientPhone || clientPhone === '—') {
    const sb = window.supabaseClient || window.supabase || window.supabaseBackupClient;
    if (sb) {
      const uId = ev.user_id || ev.userId || ev.customer_id || ev.customerId;
      const uEmail = ev.email || ev.customerEmail || ev.customer_email || ev.clientEmail;
      let query = sb.from('users').select('phone').limit(1);
      if (uId) query = query.eq('id', uId);
      else if (uEmail) query = query.eq('email', uEmail);
      else if (ev.client) query = query.ilike('name', ev.client);
      
      query.maybeSingle().then(({ data }) => {
        if (data && data.phone) {
          ev.phone = data.phone;
          set('ed-phone', data.phone);
        }
      }).catch(() => {});
    }
  }
  set('ed-phone', clientPhone || '—');

  // Additional Charges
  const addChargesEl = document.getElementById('ed-additional-charges');
  if (addChargesEl) {
    const otc = parseFloat(ev.outOfTownCharge || ev.out_of_town_charge || 0);
    const svcp = parseFloat(ev.service_charge_pct || ev.serviceChargePct || 0);
    const evAmt = parseFloat(ev.amount || 0);
    const evBase = (otc > 0 && evAmt >= otc) ? (evAmt - otc) : evAmt;
    const svcAmt = svcp > 0 ? Math.round(evBase * (svcp / 100)) : 0;
    const addParts = [];
    if (otc > 0) addParts.push(`Out of town charges: +₱${otc.toLocaleString()}`);
    if (svcAmt > 0) addParts.push(`Service charges (+${svcp}%): +₱${svcAmt.toLocaleString()}`);
    if (addParts.length > 0) {
      addChargesEl.textContent = addParts.join(', ');
    } else if (ev.additionalCharges) {
      addChargesEl.textContent = ev.additionalCharges;
    } else {
      addChargesEl.textContent = 'None';
    }
  }

  // Venue
  const venueCity = document.getElementById('ed-venue-city');
  const venueAddr = document.getElementById('ed-venue-address');
  // Try dedicated city field first, then extract from venue address string
  let _resolvedCity = ev.city || ev.venueCity || ev.venueLocation || null;
  if (!_resolvedCity && ev.venue) {
    const _ncrCities = ['Quezon City', 'Caloocan', 'Las Pinas', 'Makati', 'Malabon', 'Mandaluyong', 'Marikina', 'Muntinlupa', 'Navotas', 'Paranaque', 'Pasay', 'Pasig', 'San Juan', 'Taguig', 'Valenzuela', 'Manila'];
    _resolvedCity = _ncrCities.find(c => ev.venue.toLowerCase().includes(c.toLowerCase())) || null;
  }
  if (venueCity) venueCity.textContent = _resolvedCity || ':';
  if (venueAddr) venueAddr.textContent = ev.venue || '';

  // VIP
  const vipEl = document.getElementById('ed-vip');
  if (vipEl) {
    if (ev.vipCount && parseInt(ev.vipCount) > 0) {
      vipEl.textContent = ev.vipCount + ' VIP guest(s)' + (ev.vipService ? ' : ' + ev.vipService : '');
    } else {
      vipEl.textContent = 'None';
    }
  }

  // Event Setup
  const setupName = ev.eventSetup || (ev.eventSetupSlug ? ((window.EVENT_SETUPS || []).find(s => s.slug === ev.eventSetupSlug)?.name || ev.eventSetupSlug.replace(/_/g, ' ').toUpperCase()) : 'Complete Setup');
  set('ed-event-setup', setupName);

  // Initial Fee Due Date & Cancellation Window removed from expanded reservation modal per user request

  // Proposed meeting times
  const mtEl = document.getElementById('ed-meeting-times');
  if (mtEl) {
    let times = ev.meetingTimes || ev.proposedMeetingTimes || ev.proposed_meeting_times || ev.meeting_times || [];
    if (typeof times === 'string') {
      const trimmed = times.trim();
      if ((trimmed.startsWith('[') && trimmed.endsWith(']')) || (trimmed.startsWith('{') && trimmed.endsWith('}'))) {
        try { times = JSON.parse(trimmed); } catch (e) { }
      }
    }
    if (!Array.isArray(times)) {
      times = times ? [times] : [];
    }
    if (times.length) {
      mtEl.innerHTML = times.map(t => {
        const label = formatMeetingTimeString(t);
        return `<div style="background:var(--bg2); border:1px solid var(--border); border-radius:8px; padding:10px 14px; margin-bottom:6px; font-size:13px; color:var(--text); font-weight:600;">${label}</div>`;
      }).join('');
    } else {
      mtEl.textContent = 'No proposed times provided.';
    }
  }

  // Operational status
  const statusSel = document.getElementById('ed-status');
  if (statusSel) statusSel.value = ev.status || 'pending';

  // Open overlay
  document.getElementById('ed-overlay').classList.add('on');
  document.getElementById('section-event-details').classList.add('open');

  // Render included package items in box forms with price & customizations
  const stocksList = document.getElementById('ed-stocks-list');
  let html = '';
  
  const rawItemList = (Array.isArray(ev.items) && ev.items.length > 0)
    ? ev.items
    : ((Array.isArray(ev.custom_items) && ev.custom_items.length > 0)
      ? ev.custom_items
      : (Array.isArray(ev.packageItems) && ev.packageItems.length > 0 ? ev.packageItems : []));

  const originLower = String(ev.package_origin || ev.packageOrigin || ev.pricingMode || '').toLowerCase();
  const isCustomPkg = !originLower.includes('majorly') && !origPremadeName && !originLower.includes('premade') && (originLower.includes('custom') || originLower.includes('item-based') || !ev.activePkgId);

  if (rawItemList && rawItemList.length) {
    const itemsByCategory = {};
    rawItemList.forEach(item => {
      const name = typeof item === 'string' ? item : (item.name || 'Unknown');
      const catItem = typeof CAT !== 'undefined' ? CAT.find(c => c.name.toLowerCase() === name.toLowerCase()) : null;
      const cat = (typeof item === 'object' && item.cat) ? item.cat.toUpperCase() : (catItem && catItem.cat ? catItem.cat.toUpperCase() : 'OTHER');
      if (!itemsByCategory[cat]) itemsByCategory[cat] = [];
      itemsByCategory[cat].push(item);
    });

    const catOrder = ['FOOD', 'DESSERT', 'DRINK', 'DECORATION', 'EQUIPMENT', 'ENTERTAINMENT', 'OTHER'];
    const sortedCats = Object.keys(itemsByCategory).sort((a, b) => {
      const ia = catOrder.indexOf(a), ib = catOrder.indexOf(b);
      return (ia === -1 ? 99 : ia) - (ib === -1 ? 99 : ib);
    });

    sortedCats.forEach(cat => {
      const items = itemsByCategory[cat];
      html += `<div style="margin-bottom:18px;">`;
      html += `<div style="font-size:11px; color:var(--gold); text-transform:uppercase; letter-spacing:1px; margin-bottom:10px; font-weight:700; border-bottom:1px solid rgba(196,154,60,0.3); padding-bottom:4px;">${cat}</div>`;
      html += `<div style="display:flex; flex-wrap:wrap; gap:8px;">`;

      items.forEach(item => {
        const name = typeof item === 'string' ? item : (item.name || 'Unknown');
        let priceVal = null;
        let isFree = false;
        const isEquipmentItem = (cat === 'EQUIPMENT') || (typeof item === 'object' && item.cat === 'equipment');
        if (typeof item === 'object') {
          isFree = !isEquipmentItem && !!(item.isFree || item.isFreeChoiceApplied || item.isEventSetupEquipment || item.isAutoAdded);
          priceVal = item.snapshotPrice || item.price || item.dynamic_price;
        }
        if (!priceVal && typeof CAT !== 'undefined') {
          const catEntry = CAT.find(c => c.name.toLowerCase() === name.toLowerCase());
          if (catEntry) {
            priceVal = typeof getDynamicPrice === 'function' ? getDynamicPrice(catEntry, ev.pax || 50) : catEntry.price;
          }
        }

        const priceDisplay = (isCustomPkg && priceVal && (!isFree || isEquipmentItem))
          ? `<div style="font-size:11px; font-weight:700; color:var(--gold); margin-top:4px;">₱${Number(priceVal).toLocaleString()}</div>`
          : (isFree ? `<div style="font-size:10px; font-weight:700; color:var(--text-dim); margin-top:4px; text-transform:uppercase;">Included</div>` : '');

        let customDetailsHtml = '';
        let isCustomized = false;
        if (isEquipmentItem) {
          let eqCount = null;
          if (typeof item === 'object') {
            const cQ = (item.customQty != null) ? item.customQty : (item.custom_qty != null ? item.custom_qty : null);
            if (cQ !== null && parseInt(cQ) > 0) {
              eqCount = parseInt(cQ);
            } else if ((item.isCustomized || item.is_customized) && (item.quantity || item.qty || item.count)) {
              eqCount = parseInt(item.quantity || item.qty || item.count);
            }
          }
          if (!eqCount) {
            const catEntry = typeof CAT !== 'undefined' ? CAT.find(c => c.name.toLowerCase() === name.toLowerCase()) : null;
            const resolvedItem = Object.assign({}, catEntry || {}, typeof item === 'object' ? item : { name });
            eqCount = (typeof getEquipmentAllocatedQty === 'function') ? getEquipmentAllocatedQty(resolvedItem, ev.pax || 50, rawItemList) : 1;
          }
          const pPax = typeof item === 'object' ? (item.customPax || item.portion_pax || null) : null;
          const specs = typeof item === 'object' ? (item.specifications || item.specs || '') : '';
          isCustomized = typeof item === 'object' && (
            (item.customQty !== undefined && item.customQty !== null) ||
            item.isLocked ||
            item.isCustomized ||
            (item.specifications && String(item.specifications).trim().length > 0)
          );

          customDetailsHtml = `
            <div style="margin-top:6px; padding-top:4px; border-top:1px dashed rgba(196,154,60,0.3); font-size:11px;">
              ${pPax ? `<div style="font-weight:700; color:var(--gold);">Custom: ${pPax} pax</div>` : ''}
              <div style="font-weight:700; color:var(--gold);">Count: ${eqCount} pcs</div>
              ${specs ? `<div style="color:var(--text-dim); font-style:italic; margin-top:2px; word-break:break-word;">"${escHtml(specs)}"</div>` : ''}
            </div>`;
        } else if (typeof item === 'object') {
          const pPax = item.customPax || item.portion_pax || null;
          const qQty = item.customQty || item.quantity || null;
          const specs = item.specifications || item.specs || '';
          if (pPax || qQty || specs) {
            customDetailsHtml = `
              <div style="margin-top:6px; padding-top:4px; border-top:1px dashed rgba(196,154,60,0.3); font-size:11px;">
                ${pPax ? `<div style="font-weight:700; color:var(--gold);">Custom: ${pPax} pax</div>` : ''}
                ${qQty ? `<div style="font-weight:700; color:var(--gold);">Count: ${qQty} pcs</div>` : ''}
                ${specs ? `<div style="color:var(--text-dim); font-style:italic; margin-top:2px; word-break:break-word;">"${escHtml(specs)}"</div>` : ''}
              </div>`;
          }
        }

        html += `
          <div class="crm-item-mini-box" style="background:var(--bg3); border:1px solid var(--border); border-radius:8px; padding:10px 12px; display:flex; flex-direction:column; justify-content:space-between; min-width:135px; flex:1 1 calc(25% - 10px); box-sizing:border-box;">
            <div style="display:flex; justify-content:space-between; align-items:flex-start; gap:4px; margin-bottom:2px;">
              <div style="font-size:12px; font-weight:700; color:var(--cream); line-height:1.3;">${escHtml(name)}</div>
              ${isCustomized ? `<span style="font-size:9.5px; font-weight:700; color:var(--gold); border:1px solid rgba(196,154,60,0.5); border-radius:3px; padding:1px 5px; text-transform:uppercase; letter-spacing:0.5px; white-space:nowrap;">Customized</span>` : ''}
            </div>
            ${priceDisplay}
            ${customDetailsHtml}
          </div>`;
      });

      html += `</div></div>`;
    });
  } else {
    html = `<div style="font-size:13px; color:var(--text-dim); padding:10px;">Standard package : no specific items mapped.</div>`;
  }
  if (stocksList) stocksList.innerHTML = html;

  // Render Pricing Details at bottom
  const _pricingRows = document.getElementById('ed-pricing-rows');
  const _pricingTotal = document.getElementById('ed-pricing-total');
  if (_pricingRows && _pricingTotal) {
    const details = computePricingDetails(ev, ev.pax);
    let _rowsHtml = '';
    if (details.isMajorlySet) {
      const _paxLabel = details.pax > 0 ? ` (${details.pax} pax)` : '';
      _rowsHtml += `<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;"><span style="color:var(--text-dim);">Pricing Rule${_paxLabel}</span><span style="color:var(--cream);font-weight:600;">₱${details.basePrice.toLocaleString()}</span></div>`;
    } else if (details.isDynamic) {
      const _dynLabel = details.pax > 0 && details.perHead > 0
        ? `Pricing Rule (${details.pax} pax ₱${details.perHead.toLocaleString()}/head)`
        : `Pricing Rule${details.pax > 0 ? ` (${details.pax} pax)` : ''}`;
      _rowsHtml += `<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;"><span style="color:var(--text-dim);">${_dynLabel}</span><span style="color:var(--cream);font-weight:600;">₱${details.basePrice.toLocaleString()}</span></div>`;
    } else {
      _rowsHtml += `<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;"><span style="color:var(--text-dim);">Items Subtotal</span><span style="color:var(--cream);font-weight:600;">₱${details.basePrice.toLocaleString()}</span></div>`;
    }
    if (details.otc > 0) {
      _rowsHtml += `<div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;"><span style="color:var(--gold);">Out of Town Charge (+5%)</span><span style="color:var(--gold);font-weight:600;">+₱${details.otc.toLocaleString()}</span></div>`;
    }
    _pricingRows.innerHTML = _rowsHtml;
    _pricingTotal.textContent = '₱' + details.finalTotal.toLocaleString();
  }
}

function closeEventDetails() {
  document.getElementById('ed-overlay').classList.remove('on');
  document.getElementById('section-event-details').classList.remove('open');
  const mainBody = document.getElementById('ed-main-body');
  const feasBody = document.getElementById('ed-feasibility-body');
  const btnFeas = document.getElementById('btn-assess-feasibility');
  if (mainBody) mainBody.style.display = 'block';
  if (feasBody) { feasBody.style.display = 'none'; feasBody.innerHTML = ''; }
  if (btnFeas) btnFeas.textContent = 'Assess Feasibility';
  currentEditingEventId = null;
}

async function exportAdminReservationQuotation(targetId) {
  const resId = targetId || currentEditingEventId;
  if (!resId) return alert('No reservation selected.');
  const ev = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS.find(r => String(r.id) === String(resId)) : null) || {};

  const _totalAmt = parseFloat(String(ev.amount || '0').replace(/[^0-9.]/g, '')) || 0;
  const _details = (typeof computePricingDetails === 'function')
    ? computePricingDetails(ev, ev.pax, _totalAmt)
    : null;

  const _isMal = (typeof window.isReservationMalabon === 'function') ? window.isReservationMalabon(ev) : false;
  let _otc = _isMal ? 0 : parseFloat(ev.outOfTownCharge || ev.out_of_town_charge || 0);
  if (_details && _details.otc !== undefined) {
    _otc = _details.otc;
  } else if (!_isMal && _otc <= 0 && _totalAmt > 0) {
    _otc = Math.round(_totalAmt * 0.05);
  }

  const _extraItemsAmt = _details ? (_details.extraItemsTotal || 0) : (parseFloat(ev.additional_items_charge || ev.additionalItemsCharge || 0) || 0);
  const _extraBreakdown = (_details && Array.isArray(_details.extraItemsBreakdown)) ? _details.extraItemsBreakdown : [];

  const _baseAmt = (_details && _details.basePrice > 0)
    ? _details.basePrice
    : ((_otc > 0 && _totalAmt >= _otc) ? (_totalAmt - _otc) : _totalAmt);
  const _pkgOriginRaw = String(ev.package_origin || ev.packageOrigin || ev.package_type || ev.pricingMode || '').toLowerCase();
  const _isMajorlySet = _pkgOriginRaw.includes('majorly') || _pkgOriginRaw.includes('tiered');
  const _isDynamic = _pkgOriginRaw.includes('dynamic') || _pkgOriginRaw.includes('per_head');
  const _paxNum = parseInt(ev.pax) || 0;

  let _baseRowLabel;
  if (_isMajorlySet) {
    _baseRowLabel = _paxNum > 0 ? `Pricing Rule (${_paxNum} pax)` : 'Pricing Rule';
  } else if (_isDynamic) {
    const _pph = parseFloat(ev.price_per_head || ev.pricePerHead) || (_paxNum > 0 ? Math.round(_baseAmt / _paxNum) : 0);
    _baseRowLabel = _paxNum > 0 && _pph > 0
      ? `Pricing Rule (${_paxNum} pax ₱${_pph.toLocaleString()}/head)`
      : `Pricing Rule${_paxNum > 0 ? ` (${_paxNum} pax)` : ''}`;
  } else {
    _baseRowLabel = 'Items Subtotal';
  }

  const _svcpQuo = _details ? _details.serviceChargePct : parseFloat(ev.service_charge_pct || ev.serviceChargePct || 0);
  const _svcAmtQuo = _details ? _details.serviceChargeAmt : ((_svcpQuo > 0 && (_baseAmt + _extraItemsAmt) > 0) ? Math.round((_baseAmt + _extraItemsAmt) * (_svcpQuo / 100)) : 0);
  const _finalQuoTotal = (_details && _details.finalTotal > 0) ? _details.finalTotal : (_baseAmt + _extraItemsAmt + _otc + _svcAmtQuo);

  let pricingRowsHtml = `<tr><td style="padding:7px 0;color:#555;">${_baseRowLabel}</td><td style="padding:7px 0;text-align:right;color:#222;font-weight:600;">₱${_baseAmt.toLocaleString()}</td></tr>`;
  if (_extraBreakdown.length > 0) {
    _extraBreakdown.forEach(ei => {
      pricingRowsHtml += `<tr><td style="padding:7px 0;color:#b8860b;">Additional Item: ${ei.name}</td><td style="padding:7px 0;text-align:right;color:#b8860b;font-weight:600;">+₱${ei.price.toLocaleString()}</td></tr>`;
    });
  } else if (_extraItemsAmt > 0) {
    pricingRowsHtml += `<tr><td style="padding:7px 0;color:#b8860b;">Additional Package Items</td><td style="padding:7px 0;text-align:right;color:#b8860b;font-weight:600;">+₱${_extraItemsAmt.toLocaleString()}</td></tr>`;
  }
  if (_otc > 0) {
    const _otcPct = _baseAmt > 0 ? Math.round((_otc / _baseAmt) * 100) : 0;
    const _otcLabel = _otcPct > 0 ? `Out of Town Charge (+${_otcPct}%)` : 'Out of Town Charge';
    pricingRowsHtml += `<tr><td style="padding:7px 0;color:#b8860b;">${_otcLabel}</td><td style="padding:7px 0;text-align:right;color:#b8860b;font-weight:600;">+₱${_otc.toLocaleString()}</td></tr>`;
  }
  if (_svcAmtQuo > 0) {
    pricingRowsHtml += `<tr><td style="padding:7px 0;color:#b8860b;">Service Charge (+${_svcpQuo}%)</td><td style="padding:7px 0;text-align:right;color:#b8860b;font-weight:600;">+₱${_svcAmtQuo.toLocaleString()}</td></tr>`;
  }

  const rawDate = ev.date || '';
  let niceDate = rawDate;
  if (rawDate) {
    const d = new Date(rawDate + 'T00:00:00');
    if (!isNaN(d)) niceDate = d.toLocaleDateString('en-PH', { year: 'numeric', month: 'long', day: 'numeric' });
  }

  const originMap = {
    'majorly set': 'Majority Set', 'majorly_set': 'Majority Set',
    'dynamically set': 'Dynamically Set', 'per_head': 'Dynamically Set',
    'custom': 'Custom Build', 'item-based': 'Custom Build'
  };
  const originLabel = originMap[ev.packageOrigin || ev.package_origin || ev.pricingMode] || 'Custom Build';
  const setupName = ev.eventSetup || (ev.eventSetupSlug ? ((window.EVENT_SETUPS || []).find(s => s.slug === ev.eventSetupSlug)?.name || ev.eventSetupSlug.replace(/_/g, ' ').toUpperCase()) : 'Complete Setup');

  let vipStr = 'None';
  if (ev.vipCount && parseInt(ev.vipCount) > 0) vipStr = `${ev.vipCount} VIP${parseInt(ev.vipCount) > 1 ? 's' : ''} : ${ev.vipService || 'Standard'}`;

  const _addlQuoParts = [];
  if (_extraBreakdown.length > 0) {
    _extraBreakdown.forEach(ei => {
      _addlQuoParts.push(`${ei.name}: +₱${ei.price.toLocaleString()}`);
    });
  } else if (_extraItemsAmt > 0) {
    _addlQuoParts.push(`Additional items: +₱${_extraItemsAmt.toLocaleString()}`);
  }
  if (_otc > 0) _addlQuoParts.push(`Out of town charges: +₱${_otc.toLocaleString()}`);
  if (_svcAmtQuo > 0) _addlQuoParts.push(`Service Charge (+${_svcpQuo}%): +₱${_svcAmtQuo.toLocaleString()}`);
  let addlStr = _addlQuoParts.length > 0 ? _addlQuoParts.join(', ') : 'None';

  let callTimeStr = ev.callTime || '';
  if (!callTimeStr) {
    const tf = ev.time || ev.timeframe || '';
    const sep = tf.toLowerCase().includes(' to ') ? / to /i : (tf.includes('-') ? /-/ : null);
    if (sep) {
      const sp = tf.split(sep)[0].trim();
      if (sp) callTimeStr = sp + ' (same as start)';
    }
  }
  callTimeStr = callTimeStr || '—';

  const venueName = ev.city || ev.venueCity || ev.venueLocation || ev.venue_location || '—';
  const venueAddr = ev.venue || '';

  // Items fetching in Box Mode with individual prices & customizations
  let itemsHtml = '';
  const isCustomPkgForQuo = !String(ev.package_origin || ev.packageOrigin || ev.pricingMode || '').toLowerCase().includes('majorly') && !ev.premadePackageName && !ev.premade_package_name && !ev.activePkgId;

  const rawQuoItems = (Array.isArray(ev.items) && ev.items.length > 0)
    ? ev.items
    : ((Array.isArray(ev.custom_items) && ev.custom_items.length > 0)
      ? ev.custom_items
      : (Array.isArray(ev.packageItems) && ev.packageItems.length > 0 ? ev.packageItems : []));

  if (rawQuoItems.length > 0) {
    const grouped = {};
    rawQuoItems.forEach(i => {
      const name = typeof i === 'string' ? i : (i.name || 'Item');
      const catItem = typeof CAT !== 'undefined' ? CAT.find(c => c.name.toLowerCase() === name.toLowerCase()) : null;
      const cat = (typeof i === 'object' && i.cat) ? i.cat.toLowerCase() : (catItem && catItem.cat ? catItem.cat.toLowerCase() : 'other');
      if (!grouped[cat]) grouped[cat] = [];
      grouped[cat].push(i);
    });

    const catOrder = ['food', 'dessert', 'drink', 'decoration', 'equipment', 'entertainment', 'other'];
    const catTitles = { food: 'Food', dessert: 'Dessert', drink: 'Drink', decoration: 'Decoration', equipment: 'Equipment', entertainment: 'Add-ons', other: 'Other' };

    catOrder.forEach(c => {
      if (!grouped[c] || grouped[c].length === 0) return;
      const title = catTitles[c] || c.toUpperCase();
      const boxes = grouped[c].map(item => {
        const name = typeof item === 'string' ? item : (item.name || 'Item');
        let priceVal = (typeof item === 'object') ? (item.snapshotPrice || item.price || item.dynamic_price) : null;
        const isFree = (typeof item === 'object') && c !== 'equipment' && !!(item.isFree || item.isFreeChoiceApplied);
        if (!priceVal && typeof CAT !== 'undefined') {
          const ce = CAT.find(x => x.name.toLowerCase() === name.toLowerCase());
          if (ce) priceVal = typeof getDynamicPrice === 'function' ? getDynamicPrice(ce, ev.pax || 50) : ce.price;
        }

        const priceDisplay = (isCustomPkgForQuo && priceVal && !isFree)
          ? `<div style="font-size:11px; font-weight:700; color:#b8860b; margin-top:4px;">₱${Number(priceVal).toLocaleString()}</div>`
          : (isFree ? `<div style="font-size:10px; font-weight:600; color:#888; margin-top:4px; text-transform:uppercase;">Included</div>` : '');

        let customDetails = '';
        if (typeof item === 'object') {
          const pPax = item.customPax || item.portion_pax || null;
          const specs = item.specifications || item.specs || '';
          const isEq = c === 'equipment' || (item.cat && item.cat.toLowerCase() === 'equipment');
          const eqQty = isEq ? (item.customQty != null ? item.customQty : (item.quantity != null ? item.quantity : (item.autoQty != null ? item.autoQty : 1))) : null;

          const detailsList = [];
          if (eqQty) detailsList.push(`<div style="font-weight:700; color:#444;">Quantity: ${eqQty} pcs</div>`);
          if (pPax) detailsList.push(`<div style="font-weight:700; color:#b8860b;">Custom: ${pPax} pax</div>`);
          if (specs) detailsList.push(`<div style="color:#666; font-style:italic; margin-top:2px;">Notes: "${escHtml(specs)}"</div>`);

          if (detailsList.length > 0) {
            customDetails = `
              <div style="margin-top:4px; padding-top:4px; border-top:1px dashed #e8e0d0; font-size:10px;">
                ${detailsList.join('')}
              </div>`;
          }
        }

        return `
          <div class="item-box">
            <div style="font-size:12px; font-weight:700; color:#222; line-height:1.3;">${escHtml(name)}</div>
            ${priceDisplay}
            ${customDetails}
          </div>`;
      }).join('');

      itemsHtml += `<div class="item-group"><div class="item-group-label">${title}</div><div class="item-boxes">${boxes}</div></div>`;
    });
  } else {
    itemsHtml = '<p style="color:#aaa; font-size:12px;">Standard package : no itemized breakdown recorded.</p>';
  }

  const generatedAt = new Date().toLocaleString('en-PH', { year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });

  const printWindow = window.open('', '_blank', 'width=900,height=750');
  if (!printWindow) return alert('Pop-up blocked. Please allow pop-ups for this site to export the quotation.');

  printWindow.document.write(`<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<title>Quotation - ${ev.client || 'Client'} - Halden's Catering Services</title>
<style>
  * { box-sizing:border-box; margin:0; padding:0; font-family:'Segoe UI',Roboto,Arial,sans-serif; }
  body { background:#fff; color:#1a1a1a; padding:36px 40px; font-size:13px; }
  .page { max-width:800px; margin:0 auto; }
  .header { display:flex; justify-content:space-between; align-items:flex-start; border-bottom:2px solid #b8860b; padding-bottom:18px; margin-bottom:24px; }
  .brand-name { font-size:26px; font-weight:800; color:#b8860b; letter-spacing:1px; }
  .brand-sub { font-size:11px; color:#666; letter-spacing:1.5px; text-transform:uppercase; margin-top:2px; }
  .doc-title { text-align:right; }
  .doc-title h1 { font-size:22px; font-weight:800; color:#222; text-transform:uppercase; letter-spacing:2px; }
  .gen-date { font-size:11px; color:#888; margin-top:4px; }
  .pkg-header { background:#faf8f4; border:1px solid #e8e0d0; border-radius:10px; padding:16px 20px; margin-bottom:20px; }
  .pkg-origin { font-size:9px; font-weight:800; color:#b8860b; text-transform:uppercase; letter-spacing:1.5px; margin-bottom:4px; }
  .pkg-name { font-size:20px; font-weight:700; color:#222; }
  .pkg-desc { font-size:12px; color:#666; margin-top:6px; line-height:1.5; }
  .price-bar { display:flex; justify-content:space-between; align-items:center; background:#fff; border:1px solid #e8e0d0; border-radius:8px; padding:12px 18px; margin-bottom:22px; }
  .price-amount { font-size:24px; font-weight:800; color:#b8860b; }
  .price-pax { font-size:12px; color:#666; margin-top:2px; }
  .price-status { font-size:11px; font-weight:700; color:#555; background:#f0f0f0; border-radius:4px; padding:4px 10px; }
  .section-title { font-size:11px; font-weight:800; color:#b8860b; text-transform:uppercase; letter-spacing:1.5px; margin-bottom:10px; }
  .info-grid { display:grid; grid-template-columns:1fr 1fr; gap:10px 20px; margin-bottom:22px; }
  .info-cell { border:1px solid #eee; border-radius:8px; padding:10px 14px; }
  .info-cell .lbl { font-size:9px; font-weight:800; color:#b8860b; text-transform:uppercase; letter-spacing:1.2px; margin-bottom:3px; }
  .info-cell .val { font-size:13px; font-weight:600; color:#222; }
  .info-cell.full { grid-column:1/-1; }
  .divider { border:none; border-top:1px solid #eee; margin:18px 0; }
  .items-section { margin-bottom:22px; }
  .item-group { margin-bottom:14px; }
  .item-group-label { font-size:9px; font-weight:800; color:#b8860b; text-transform:uppercase; letter-spacing:1.2px; margin-bottom:6px; }
  .item-boxes { display:flex; flex-wrap:wrap; gap:8px; }
  .item-box { background:#fafafa; border:1px solid #ddd; border-radius:6px; padding:8px 10px; min-width:130px; flex:1 1 calc(25% - 8px); box-sizing:border-box; }
  .item-chips { display:flex; flex-wrap:wrap; gap:6px; }
  .item-chip { border:1px solid #ddd; border-radius:20px; padding:4px 11px; font-size:11px; color:#333; }
  .pricing-table { width:100%; border-collapse:collapse; margin-bottom:6px; font-size:13px; }
  .pricing-table td { padding:7px 4px; border-bottom:1px solid #f0f0f0; }
  .pricing-table tr:last-child td { border-bottom:none; }
  .total-row { display:flex; justify-content:space-between; align-items:center; background:#fffbf0; border:1px solid #e8c96a; border-radius:8px; padding:12px 16px; margin-top:10px; }
  .total-label { font-size:14px; font-weight:700; color:#222; }
  .total-value { font-size:22px; font-weight:800; color:#b8860b; }
  .footer { margin-top:36px; padding-top:16px; border-top:1px solid #eee; display:flex; justify-content:space-between; align-items:flex-end; }
  .footer-note { font-size:10px; color:#aaa; line-height:1.6; }
  .footer-sig { text-align:right; font-size:10px; color:#bbb; }
  .print-btn { display:inline-block; margin:20px auto; padding:11px 30px; background:#b8860b; color:#fff; border:none; border-radius:8px; font-size:14px; font-weight:700; cursor:pointer; letter-spacing:0.5px; }
  @media print { .no-print { display:none !important; } }
</style>
</head>
<body>
<div class="page">
  <div class="header">
    <div class="header-brand">
      <div class="brand-name">Halden's</div>
      <div class="brand-sub">Catering Services</div>
    </div>
    <div class="doc-title">
      <h1>Quotation</h1>
      <div class="gen-date">Generated: ${generatedAt}</div>
    </div>
  </div>

  <div class="pkg-header">
    <div class="pkg-origin">${originLabel}</div>
    <div class="pkg-name">${ev.packageName || ev.name || ev.type || 'Custom Package'}</div>
    ${(ev.premadePackageName || ev.premade_package_name) ? `<div style="font-size:12px; color:#666; margin-bottom:4px;">Premade Package: <strong style="color:#b8860b;">${ev.premadePackageName || ev.premade_package_name}</strong></div>` : ''}
    <div class="pkg-desc">${ev.description || ev.eventDescription || 'No description provided.'}</div>
  </div>

  <div class="price-bar">
    <div>
      <div class="price-amount">₱${_finalQuoTotal.toLocaleString()}</div>
      <div class="price-pax">${ev.pax ? ev.pax + ' Pax' : ''}</div>
    </div>
    <div class="price-status">${(ev.status || 'Pending').toUpperCase()}</div>
  </div>

  <div class="section-title">Event Details</div>
  <div class="info-grid">
    <div class="info-cell"><div class="lbl">Client</div><div class="val">${ev.client || 'N/A'}</div></div>
    <div class="info-cell"><div class="lbl">Theme</div><div class="val">${ev.theme || 'N/A'}</div></div>
    <div class="info-cell"><div class="lbl">Occasion</div><div class="val">${ev.type || ev.occasion || 'N/A'}</div></div>
    <div class="info-cell"><div class="lbl">Event Date</div><div class="val">${niceDate || '—'}</div></div>
    <div class="info-cell"><div class="lbl">Time Frame</div><div class="val">${ev.time || ev.timeframe || '—'}</div></div>
    <div class="info-cell"><div class="lbl">Call Time</div><div class="val">${callTimeStr}</div></div>
    <div class="info-cell"><div class="lbl">VIP Guests</div><div class="val">${vipStr}</div></div>
    <div class="info-cell"><div class="lbl">Additional Charges</div><div class="val">${addlStr}</div></div>
    <div class="info-cell full"><div class="lbl">Event Setup</div><div class="val" style="color:#b8860b; font-weight:700;">${setupName}</div></div>
    <div class="info-cell full"><div class="lbl">Venue</div><div class="val">${venueName}${venueAddr ? ' &mdash; ' + venueAddr : ''}</div></div>
  </div>

  <hr class="divider">
  <div class="section-title">Included in this Package</div>
  <div class="items-section">${itemsHtml}</div>

  <hr class="divider">
  <div class="section-title">Pricing Details</div>
  <table class="pricing-table">
    <tbody>${pricingRowsHtml}</tbody>
  </table>
  <div class="total-row">
    <span class="total-label">Total Amount</span>
    <span class="total-value">₱${_finalQuoTotal.toLocaleString()}</span>
  </div>

  <div class="footer">
    <div class="footer-note">This quotation is generated by Halden's Catering Services.<br>Authorized Admin Quotation.</div>
    <div class="footer-sig">Halden's Catering Services<br>Authorized Quotation</div>
  </div>
</div>
<div class="no-print" style="text-align:center; padding:16px;">
  <button class="print-btn" onclick="window.print()">Print / Save as PDF</button>
</div>
<script>window.onload=function(){ setTimeout(function(){ window.print(); }, 500); };<\/script>
</body>
</html>`);
  printWindow.document.close();
}
window.exportAdminReservationQuotation = exportAdminReservationQuotation;

function backToCalendar() {
  closeEventDetails();
}

function changeEventStatus() {
  if (!currentEditingEventId) return;
  updateReservationStatus(currentEditingEventId, document.getElementById('ed-status').value);
}

/**
 * Toggles between standard Event Details view and the Feasibility Assessment view
 * in the Event Details modal (#section-event-details).
 */
async function toggleAssessFeasibility() {
  const mainBody = document.getElementById('ed-main-body');
  const feasBody = document.getElementById('ed-feasibility-body');
  const btnFeas = document.getElementById('btn-assess-feasibility');
  if (!mainBody || !feasBody) return;

  const isShowingFeas = (feasBody.style.display !== 'none');
  if (isShowingFeas) {
    feasBody.style.display = 'none';
    mainBody.style.display = 'block';
    if (btnFeas) btnFeas.textContent = 'Assess Feasibility';
  } else {
    mainBody.style.display = 'none';
    feasBody.style.display = 'block';
    if (btnFeas) btnFeas.textContent = 'Back to Event Details';

    const ev = (RESERVATIONS || []).find(r => r.id === currentEditingEventId);
    if (ev) {
      await renderAssessFeasibilityView(ev);
    } else {
      feasBody.innerHTML = '<div style="text-align:center; padding:40px; color:var(--text-dim); font-size:13px;">No reservation selected.</div>';
    }
  }
}
window.toggleAssessFeasibility = toggleAssessFeasibility;

/**
 * Renders the comprehensive Feasibility Assessment view for a selected reservation:
 * 1. Other bookings on the same date with their time ranges and call times.
 * 2. Equipment availability table matching the asset availability table, plus a new
 *    'Same Equipment Demands' column detailing equipment needed by other bookings on the same date.
 * 3. List of all staff members currently marked as Active.
 */
async function renderAssessFeasibilityView(ev) {
  const feasBody = document.getElementById('ed-feasibility-body');
  if (!feasBody) return;

  feasBody.innerHTML = '<div style="text-align:center; padding:50px; color:var(--text-dim); font-size:13px;">Analyzing reservation feasibility...</div>';

  const sb = window.supabaseClient;
  if (!sb) {
    feasBody.innerHTML = '<div style="padding:20px; color:var(--red);">Supabase client unavailable.</div>';
    return;
  }

  // Format date helper
  const formatResDate = (dStr) => {
    if (!dStr) return null;
    const d = new Date(dStr);
    if (!isNaN(d.getTime())) return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
    return dStr;
  };

  const resDate = formatResDate(ev.date || ev.eventDate || null);
  const resId = ev.id;
  const pax = parseInt(ev.pax) || 0;

  // 1. Identify other bookings on the same date
  const sameDateReservations = (RESERVATIONS || []).filter(r => {
    if (r.id === resId) return false;
    const s = String(r.status || '').toLowerCase().trim();
    if (s === 'cancelled' || s === 'rejected') return false;
    const rDate = formatResDate(r.date || r.eventDate || null);
    return rDate && rDate === resDate;
  });

  // 2. Fetch inventory, historical allocations, and venue equipment from Supabase
  const allNeededResIds = [resId, ...sameDateReservations.map(r => r.id)];
  let baseEq = [];
  let histData = [];
  let venueData = [];

  try {
    const [resEq, resHist, resVenue] = await Promise.all([
      sb.from('equipment_inventory').select('id,asset_id,name,category,total_qty,maintenance_qty,parent_asset_id,is_disabled,extra_buffer'),
      sb.from('allocation_history')
        .select('asset_id,equipment_name,allocated_qty,reservation_id,reservation_name,allocation_batch,is_rental,recorded_at')
        .not('allocation_batch', 'is', null)
        .in('reservation_id', allNeededResIds.length > 0 ? allNeededResIds : ['NONE']),
      sb.from('venue_equipment').select('*').in('reservation_id', allNeededResIds.length > 0 ? allNeededResIds : ['NONE'])
    ]);

    if (resEq.error) throw resEq.error;
    if (resHist.error) throw resHist.error;

    baseEq = resEq.data || [];
    histData = resHist.data || [];
    venueData = resVenue.data || [];
  } catch (err) {
    console.warn('[Feasibility] Data fetch error:', err);
    feasBody.innerHTML = '<div style="padding:20px; color:var(--red);">Failed to load equipment feasibility data.</div>';
    return;
  }

  // Build venue config map
  const venueConfigMap = {};
  venueData.forEach(v => {
    venueConfigMap[v.reservation_id] = { items: v.items || [] };
  });

  // Deduplicate history data
  const dedupMap = {};
  histData.forEach(h => {
    if (!h.reservation_id) return;
    const isVenue = h.allocation_batch && h.allocation_batch.startsWith('VENUE-');
    const key = `${h.reservation_id}_${h.equipment_name || h.asset_id}_${h.is_rental}_${!!isVenue}`;
    const time = h.recorded_at ? new Date(h.recorded_at).getTime() : 0;
    if (!dedupMap[key] || time > dedupMap[key].time) {
      dedupMap[key] = { row: h, time };
    }
  });
  histData = Object.values(dedupMap).map(d => d.row);

  // Filter decorations
  const isDecoration = (assetId, cat, name) => {
    const c = String(cat || '').toLowerCase();
    if (c.includes('decoration')) return true;
    const id = String(assetId || '').toUpperCase().trim();
    const n = String(name || '').toLowerCase().trim();
    const a = (window.EIM_ASSETS || []).find(x =>
      (x.asset_id && String(x.asset_id).toUpperCase() === id) ||
      (x.id && String(x.id).toUpperCase() === id) ||
      (n && x.name && x.name.toLowerCase().trim() === n)
    );
    return !!(a && String(a.category || '').toLowerCase().includes('decoration'));
  };

  const eqRows = [];
  baseEq.forEach(eq => {
    if (isDecoration(eq.asset_id || eq.id, eq.category, eq.name)) return;
    eqRows.push({
      ...eq,
      allocated_qty: 0,
      rented_qty: 0,
      allocated_reservation_id: null,
      allocated_to: null,
      allocation_batch: null
    });
  });

  histData.forEach(h => {
    let eq = null;
    if (h.asset_id) {
      eq = baseEq.find(e => (e.asset_id || '').toUpperCase() === (h.asset_id || '').toUpperCase());
    }
    if (!eq && h.equipment_name) {
      eq = baseEq.find(e => (e.name || '').toLowerCase().trim() === (h.equipment_name || '').toLowerCase().trim());
    }
    eq = eq || {};
    if (isDecoration(h.asset_id || eq.asset_id || eq.id, eq.category, h.equipment_name || eq.name)) return;
    const isVenue = h.allocation_batch && h.allocation_batch.startsWith('VENUE-');
    eqRows.push({
      id: eq.id || h.asset_id,
      asset_id: h.asset_id || eq.asset_id || eq.id,
      name: h.equipment_name || eq.name,
      category: eq.category,
      total_qty: eq.total_qty,
      allocated_qty: (h.is_rental || isVenue) ? 0 : h.allocated_qty,
      rented_qty: h.is_rental ? h.allocated_qty : 0,
      venue_qty: isVenue ? h.allocated_qty : 0,
      allocated_reservation_id: h.reservation_id,
      allocated_to: h.reservation_name,
      allocation_batch: h.allocation_batch
    });
  });

  const allEquip = eqRows;
  const byAssetId = {};
  allEquip.forEach(row => {
    const key = (row.asset_id || '').toUpperCase().trim();
    if (key) {
      if (!byAssetId[key]) byAssetId[key] = [];
      byAssetId[key].push(row);
    }
  });

  const familyTotalQtyMap = {};
  const childToRootMap = {};
  baseEq.forEach(eq => {
    if (eq.parent_asset_id && !eq.is_disabled) {
      const rootKey = (eq.parent_asset_id || '').toUpperCase();
      const childKey = (eq.asset_id || '').toUpperCase();
      if (childKey) childToRootMap[childKey] = rootKey;
    }
  });
  (window.EIM_ASSETS || []).forEach(a => {
    if (a.parent_asset_id && !a.is_disabled) {
      const rootKey = (a.parent_asset_id || '').toUpperCase();
      const childKey = (a.asset_id || a.id || '').toUpperCase();
      if (childKey && !childToRootMap[childKey]) childToRootMap[childKey] = rootKey;
    }
  });
  baseEq.forEach(eq => {
    if (eq.is_disabled) return;
    const key = (eq.asset_id || '').toUpperCase();
    if (!key) return;
    const rootKey = childToRootMap[key] || key;
    const usableQty = (parseInt(eq.total_qty) || 0) - (parseInt(eq.maintenance_qty) || 0);
    familyTotalQtyMap[rootKey] = (familyTotalQtyMap[rootKey] || 0) + Math.max(0, usableQty);
  });

  const getFamilyTotal = (assetIdKey) => {
    const key = (assetIdKey || '').toUpperCase();
    const rootKey = childToRootMap[key] || key;
    if (familyTotalQtyMap[rootKey] != null) return familyTotalQtyMap[rootKey];
    const eimFamily = (window.EIM_ASSETS || []).filter(a => !a.is_disabled && ((a.asset_id || a.id || '').toUpperCase() === rootKey || (a.parent_asset_id || '').toUpperCase() === rootKey));
    if (eimFamily.length > 0) return eimFamily.reduce((sum, a) => sum + Math.max(0, (parseInt(a.quantity) || 0) - (parseInt(a.maintenance_qty) || 0)), 0);
    const byAss = byAssetId[key] && byAssetId[key][0];
    return byAss ? Math.max(0, (parseInt(byAss.total_qty) || 0) - (parseInt(byAss.maintenance_qty) || 0)) : 0;
  };

  const getFamilyKeys = (assetIdKey) => {
    const rootKey = (childToRootMap[(assetIdKey || '').toUpperCase()] || (assetIdKey || '').toUpperCase());
    const childKeys = (window.EIM_ASSETS || [])
      .filter(a => a.parent_asset_id && (a.parent_asset_id || '').toUpperCase() === rootKey && !a.is_disabled)
      .map(a => (a.asset_id || a.id || '').toUpperCase())
      .filter(Boolean);
    return new Set([rootKey, ...childKeys]);
  };

  const curResHasVip = parseInt(ev.vipCount || ev.vip_count || (ev.vip && typeof ev.vip === 'object' ? ev.vip.count : ev.vip)) > 0 || !!(ev.hasVip || ev.isVip);
  const calcQty = (aKey, assetRuleFallback, targetPax = pax) => {
    const realAsset = typeof window.findAssetForRule === 'function' ? window.findAssetForRule({ assetId: aKey }) : null;
    const fallback = assetRuleFallback || (realAsset ? realAsset.allocationRule || realAsset.allocation_type : 'fixed');
    const r = (fallback || 'fixed').toLowerCase();
    const curTables = Math.ceil(targetPax / 8);
    const mPerItem = r.match(/^per_(\d+)_per_item:(.+)$/i);
    if (mPerItem) return parseInt(mPerItem[1]) || 1;
    if (r === 'per_pax') return targetPax;
    else if (r === 'per_5_pax') return Math.ceil(targetPax / 5);
    else if (r === 'per_8_pax') return Math.ceil(targetPax / 8);
    else if (r === 'per_10_pax') return Math.ceil(targetPax / 10);
    else if (r === 'per_table') return curTables;
    else if (r === 'per_menu_item') return 1;
    else if (r === 'every_vip') return curResHasVip ? 1 : 0;
    else if (r === 'fixed' || r === 'flat') return 1;
    return targetPax;
  };

  const vConfig = venueConfigMap[resId] || { items: [] };
  const getVenueQty = (aKey) => {
    if (!aKey) return 0;
    const vItem = vConfig.items.find(i => (i.assetId || '').toUpperCase() === aKey);
    return vItem ? (parseInt(vItem.quantity) || 0) : 0;
  };
  const calcBuffer = (qty, aKey, venueQty = 0) => {
    const eqList = aKey ? (byAssetId[aKey] || []) : [];
    const asset = eqList[0] || {};
    return asset.extra_buffer || 0;
  };

  // Build items for THIS reservation
  const rawBatchItems = allEquip.filter(e => e.allocated_reservation_id === resId && (e.asset_id || '').toUpperCase() !== 'VENUE');
  const aggregatedBatchItems = {};
  rawBatchItems.forEach(eq => {
    let rawKey = (eq.asset_id || '').toUpperCase().trim();
    if (!rawKey) {
      const match = allEquip.find(e => (e.name || '').toLowerCase() === (eq.name || '').toLowerCase() && e.asset_id && e.asset_id.toUpperCase() !== 'VENUE');
      if (match) {
        rawKey = (match.asset_id || '').toUpperCase().trim();
        eq.asset_id = match.asset_id;
        eq.total_qty = match.total_qty;
      } else {
        rawKey = 'NAME-' + (eq.name || '').toUpperCase().trim();
      }
    }
    const aKey = childToRootMap[rawKey] || rawKey;
    if (!aggregatedBatchItems[aKey]) {
      const rootEqRow = allEquip.find(e => (e.asset_id || '').toUpperCase() === aKey) || eq;
      aggregatedBatchItems[aKey] = { ...rootEqRow, asset_id: aKey, allocated_qty: 0, rented_qty: 0, venue_qty: 0 };
    }
    aggregatedBatchItems[aKey].allocated_qty += (parseInt(eq.allocated_qty) || 0);
    aggregatedBatchItems[aKey].rented_qty += (parseInt(eq.rented_qty) || 0);
    aggregatedBatchItems[aKey].venue_qty += (parseInt(eq.venue_qty) || 0);
  });
  const batchItems = Object.values(aggregatedBatchItems);
  const batchAssetIds = new Set(batchItems.map(e => (e.asset_id || '').toUpperCase().trim()).filter(Boolean));

  const supplementRows = [];
  const seenInSupplement = new Set(batchAssetIds);

  if (ev.equipmentManifest && ev.equipmentManifest.length) {
    ev.equipmentManifest.forEach(mItem => {
      const mKey = (mItem.assetId || '').toUpperCase().trim();
      if (mKey === 'VENUE' || (mKey && seenInSupplement.has(mKey))) return;
      const realAsset = (window.EIM_ASSETS || []).find(a => (a.asset_id || a.id || '').toUpperCase().trim() === mKey);
      if (realAsset && (realAsset.category || '').toLowerCase().includes('decoration')) return;
      const eqList = mKey ? (byAssetId[mKey] || []) : [];
      const eq = eqList[0] || { asset_id: mItem.assetId, name: mItem.name, total_qty: 0 };
      const needed = calcQty(mKey, eq.allocationRule || eq.allocation_type);
      if (needed <= 0) return;
      if (mKey) seenInSupplement.add(mKey);
      const buffer = calcBuffer(needed, mKey);
      supplementRows.push({ assetId: mItem.assetId || ':', name: mItem.name || ':', needed, buffer, eq });
    });
  }

  if (ev.packageItems && ev.packageItems.length) {
    const assets = window.EIM_ASSETS || [];
    ev.packageItems.forEach(itemEntry => {
      const itemName = typeof itemEntry === 'string' ? itemEntry : (itemEntry.name || '');
      if (!itemName) return;
      const asset = assets.find(a => (a.name || '').toLowerCase().trim() === itemName.toLowerCase().trim())
        || (typeof window.findAssetForRule === 'function' ? window.findAssetForRule({ name: itemName }) : null);
      if (!asset) return;
      const aKey = (asset.id || asset.asset_id || '').toUpperCase().trim();
      if (aKey && seenInSupplement.has(aKey)) return;
      if (asset && (asset.category || '').toLowerCase().includes('decoration')) return;
      let qty = calcQty(aKey, asset.allocationRule);
      if (qty <= 0) return;
      const eqList = aKey ? (byAssetId[aKey] || []) : [];
      const eq = eqList[0] || { asset_id: asset.id || asset.asset_id, name: asset.name, total_qty: asset.quantity || 0 };
      if (aKey) seenInSupplement.add(aKey);
      const buffer = calcBuffer(qty, aKey);
      supplementRows.push({ assetId: asset.id || asset.asset_id || ':', name: asset.name || itemName, needed: qty, buffer, eq });
    });
  }

  const resPackageItemNames = new Set(
    (ev.packageItems || []).map(n => (typeof n === 'string' ? n : (n && n.name) || '').toLowerCase().trim()).filter(Boolean)
  );
  (ALLOC_RULES || []).forEach(rule => {
    if (!rule || !rule.name) return;
    const ruleKey = (rule.assetId || '').toUpperCase().trim();
    if (seenInSupplement.has(ruleKey)) return;
    if (resPackageItemNames.size > 0 && !resPackageItemNames.has((rule.name || '').toLowerCase().trim())) return;
    seenInSupplement.add(ruleKey);
    const eqList = ruleKey ? (byAssetId[ruleKey] || []) : [];
    if (!eqList.length) return;
    if (eqList[0] && (eqList[0].category || '').toLowerCase().includes('decoration')) return;
    let qty = calcQty(ruleKey, 'fixed');
    if (qty <= 0) return;
    const buffer = calcBuffer(qty, ruleKey);
    supplementRows.push({ assetId: rule.assetId, name: rule.name, needed: qty, buffer, eq: eqList[0] });
  });

  // Equipment tied to specific menu items (Other: Per N Per Menu Item)
  allEquip.forEach(eq => {
    if (!eq || eq.is_disabled || (eq.category || '').toLowerCase().includes('decoration')) return;
    const r = ((eq.allocationRule || eq.allocation_type || '') + '').toLowerCase();
    const m = r.match(/^per_(\d+)_per_item:(.+)$/i);
    if (m) {
      const targetDishName = m[2].trim().toLowerCase();
      let dishPresent = resPackageItemNames.has(targetDishName);
      if (!dishPresent && Array.isArray(ev.dishes)) {
        dishPresent = ev.dishes.some(d => (typeof d === 'string' ? d : (d && d.name) || '').trim().toLowerCase() === targetDishName);
      }
      if (!dishPresent && Array.isArray(ev.custom_package_items)) {
        dishPresent = ev.custom_package_items.some(d => (typeof d === 'string' ? d : (d && d.name) || '').trim().toLowerCase() === targetDishName);
      }
      if (!dishPresent && Array.isArray(ev.customPackageItems)) {
        dishPresent = ev.customPackageItems.some(d => (typeof d === 'string' ? d : (d && d.name) || '').trim().toLowerCase() === targetDishName);
      }
      if (dishPresent) {
        const key = (eq.asset_id || '').toUpperCase().trim();
        if (key && !seenInSupplement.has(key)) {
          seenInSupplement.add(key);
          const reqN = parseInt(m[1]) || 1;
          const buffer = calcBuffer(reqN, key);
          supplementRows.push({ assetId: eq.asset_id || ':', name: eq.name || ':', needed: reqN, buffer, eq });
        }
      }
    }
  });

  const sameDateResIds = new Set(sameDateReservations.map(r => r.id));
  const rows = [];

  batchItems.forEach(eq => {
    const aKey = (eq.asset_id || '').toUpperCase().trim();
    if (isDecoration(aKey, eq.category, eq.name)) return;
    let needed = calcQty(aKey, eq.allocation_type || eq.allocationRule);
    const custInfo = getEquipmentCustomizationDelta(eq, ev, needed);
    const custDelta = custInfo.delta;
    const venueToThis = parseInt(eq.venue_qty) || getVenueQty(aKey);
    const buffer = calcBuffer(needed, aKey, venueToThis);
    const effectiveNeeded = Math.max(0, needed + custDelta);
    const afterVenue = Math.max(0, effectiveNeeded - venueToThis);
    const totalReq = afterVenue + buffer;
    const total = getFamilyTotal(aKey);
    const allocatedToThis = parseInt(eq.allocated_qty) || 0;
    const rentedToThis = parseInt(eq.rented_qty) || 0;
    const familyKeys = getFamilyKeys(aKey);
    const allocatedToOthers = allEquip
      .filter(e2 => familyKeys.has((e2.asset_id || '').toUpperCase()) && e2.allocated_reservation_id && sameDateResIds.has(e2.allocated_reservation_id))
      .reduce((s, e2) => s + (parseInt(e2.allocated_qty) || 0), 0);
    const available = Math.max(0, total - allocatedToOthers);
    rows.push({ assetId: eq.asset_id || ':', name: eq.name || ':', needed, buffer, custDelta, totalReq, total, allocatedToThis, rentedToThis, venueToThis, available });
  });

  supplementRows.forEach(nr => {
    const eq = nr.eq;
    const aKey = (eq.asset_id || '').toUpperCase();
    if (isDecoration(aKey, eq.category, nr.name)) return;
    const total = getFamilyTotal(aKey);
    const familyKeys = getFamilyKeys(aKey);
    const allocatedToOthers = allEquip
      .filter(e2 => familyKeys.has((e2.asset_id || '').toUpperCase()) && e2.allocated_reservation_id && sameDateResIds.has(e2.allocated_reservation_id))
      .reduce((s, e2) => s + (parseInt(e2.allocated_qty) || 0), 0);
    const available = Math.max(0, total - allocatedToOthers);
    const venueToThis = getVenueQty(aKey);
    const custInfo = getEquipmentCustomizationDelta(nr.eq, ev, nr.needed);
    const custDelta = custInfo.delta;
    const effectiveNeeded = Math.max(0, nr.needed + custDelta);
    const afterVenue = Math.max(0, effectiveNeeded - venueToThis);
    const buffer = calcBuffer(nr.needed, aKey, venueToThis);
    const totalReq = afterVenue + buffer;
    rows.push({ assetId: nr.assetId || ':', name: nr.name, needed: nr.needed, buffer, custDelta, totalReq, total, allocatedToThis: 0, rentedToThis: 0, venueToThis, available });
  });

  // Calculate same equipment demands per other reservation
  const getSameDemandsForAsset = (aKey, assetName) => {
    const normKey = (aKey || '').toUpperCase().trim();
    const normName = (assetName || '').toLowerCase().trim();
    const demands = [];

    sameDateReservations.forEach(oRes => {
      const oPax = parseInt(oRes.pax) || 0;
      let demandedQty = 0;

      // 1. Check allocation history for other reservation
      const oHist = histData.filter(h => h.reservation_id === oRes.id && ((h.asset_id && (h.asset_id || '').toUpperCase().trim() === normKey) || (h.equipment_name && (h.equipment_name || '').toLowerCase().trim() === normName)));
      if (oHist.length > 0) {
        demandedQty = oHist.reduce((s, h) => s + (parseInt(h.allocated_qty) || 0) + (parseInt(h.is_rental ? h.allocated_qty : 0) || 0), 0);
      }

      // 2. Check equipment manifest
      if (demandedQty === 0 && oRes.equipmentManifest && Array.isArray(oRes.equipmentManifest)) {
        const m = oRes.equipmentManifest.find(item => (item.assetId && (item.assetId || '').toUpperCase().trim() === normKey) || (item.name && (item.name || '').toLowerCase().trim() === normName));
        if (m) demandedQty = parseInt(m.quantity || m.qty || 0);
      }

      // 3. Check package items & rules
      if (demandedQty === 0 && oRes.packageItems && Array.isArray(oRes.packageItems)) {
        const hasItem = oRes.packageItems.some(item => {
          const iname = typeof item === 'string' ? item : (item.name || '');
          return iname.toLowerCase().trim() === normName;
        });
        if (hasItem) {
          demandedQty = calcQty(normKey, null, oPax);
        }
      }

      if (demandedQty > 0) {
        demands.push({
          id: oRes.id,
          client: oRes.client,
          pkg: oRes.packageName || oRes.type || 'Custom Package',
          qty: demandedQty
        });
      }
    });

    return demands;
  };

  // Build table rows HTML
  const tableRowsHtml = rows.map(r => {
    let fulfillable, fColor;
    const totalSecured = r.allocatedToThis + r.rentedToThis + r.venueToThis;
    if (totalSecured >= r.totalReq && r.totalReq > 0) {
      fulfillable = 'Allocated'; fColor = 'var(--green)';
    } else if (r.available + r.rentedToThis + r.venueToThis >= r.totalReq) {
      fulfillable = 'Yes'; fColor = 'var(--gold)';
    } else {
      fulfillable = 'Short'; fColor = 'var(--red)';
    }

    let allocatedDisplay = r.allocatedToThis;
    if (r.rentedToThis > 0 && r.venueToThis > 0) allocatedDisplay += ' <span style="color:var(--gold); font-size:10px;">(+' + r.rentedToThis + ' rented, +' + r.venueToThis + ' venue)</span>';
    else if (r.rentedToThis > 0) allocatedDisplay += ' <span style="color:var(--gold); font-size:10px;">(+' + r.rentedToThis + ' rented)</span>';
    else if (r.venueToThis > 0) allocatedDisplay += ' <span style="color:var(--amber); font-size:10px;">(+' + r.venueToThis + ' venue)</span>';

    const shortAmt = Math.max(0, r.totalReq - (r.available + r.rentedToThis + r.venueToThis));
    const shortDisplay = shortAmt > 0
      ? '<span style="font-weight:700; color:var(--red);">' + shortAmt + '</span>'
      : '<span style="color:var(--green);">0</span>';

    // Compute Same Equipment Demands
    const demands = getSameDemandsForAsset(r.assetId, r.name);
    let demandsDisplay = '<span style="color:var(--text-dim);">-</span>';
    if (demands.length > 0) {
      demandsDisplay = demands.map(d => `
        <div style="font-size:11px; padding:2px 0; line-height:1.4;">
          <span style="font-weight:600; color:var(--gold);">${escHtml(d.client || 'Reservation ' + d.id)}</span>
          <span style="color:var(--text-dim);">(${escHtml(d.pkg)}):</span>
          <span style="font-weight:700; color:var(--cream);">${d.qty}</span>
        </div>
      `).join('');
    }

    return `
      <tr style="border-bottom:1px solid rgba(255,255,255,0.05);">
        <td style="font-size:11px; padding:8px 10px; color:var(--text);">${escHtml(r.assetId || ':')}</td>
        <td style="font-size:12px; padding:8px 10px; font-weight:600; color:var(--cream);">${escHtml(r.name)}</td>
        <td style="font-size:12px; padding:8px 10px; font-weight:700;">${r.needed}</td>
        <td style="font-size:12px; padding:8px 10px; color:var(--amber);">+${r.buffer}</td>
        <td style="font-size:12px; padding:8px 10px;">${r.custDelta > 0 ? `<span style="font-weight:700; color:var(--gold);">+${r.custDelta}</span>` : (r.custDelta < 0 ? `<span style="font-weight:700; color:var(--red);">${r.custDelta}</span>` : `<span style="color:var(--text-dim);">-</span>`)}</td>
        <td style="font-size:12px; padding:8px 10px; font-weight:700; color:var(--cream);">${r.totalReq}</td>
        <td style="font-size:12px; padding:8px 10px;">${allocatedDisplay}</td>
        <td style="font-size:12px; padding:8px 10px;">${resDate ? r.available + ' on ' + resDate : r.total + ' total'}</td>
        <td style="font-size:12px; padding:8px 10px; text-align:center;">${shortDisplay}</td>
        <td style="font-size:12px; padding:8px 10px; font-weight:700; color:${fColor};">${fulfillable}</td>
        <td style="font-size:12px; padding:8px 10px; min-width:200px;">${demandsDisplay}</td>
      </tr>
    `;
  }).join('');

  // 3. Fetch and filter active staff members (excluding Admin & staff assigned on same date)
  if (!USERS || USERS.length === 0) {
    if (typeof fetchStaff === 'function') await fetchStaff();
  }

  // Find staff assigned to other reservations on this same date
  const otherSameDateResIds = sameDateReservations.map(r => r.id);
  const busyStaffIdSet = new Set();
  if (otherSameDateResIds.length > 0 && sb) {
    try {
      const { data: assignData } = await sb
        .from('reservation_staff_assignments')
        .select('staff_id, reservation_id')
        .in('reservation_id', otherSameDateResIds);
      if (assignData && assignData.length > 0) {
        assignData.forEach(a => {
          if (a.staff_id) busyStaffIdSet.add(String(a.staff_id));
        });
      }
    } catch (err) {
      console.warn('[Feasibility View] Error querying same-date staff assignments:', err);
    }
  }
  sameDateReservations.forEach(r => {
    if (r.assigned_staff && Array.isArray(r.assigned_staff)) {
      r.assigned_staff.forEach(s => busyStaffIdSet.add(String(s.id || s.staff_id || s)));
    }
    if (r.executionPlan && r.executionPlan.phases) {
      r.executionPlan.phases.forEach(p => (p.tasks || []).forEach(t => (t.staffIds || []).forEach(id => busyStaffIdSet.add(String(id)))));
    }
  });

  const activeStaff = (USERS || []).filter(u => {
    const role = (u.role || '').toLowerCase();
    const status = (u.status || 'Active').toLowerCase();
    // Exclude Admin accounts
    if (role === 'admin') return false;
    // Must be Staff and Active
    if (role !== 'staff' || status !== 'active') return false;
    // Exclude if already assigned to a different reservation on the same date
    if (busyStaffIdSet.has(String(u.id)) || busyStaffIdSet.has(String(u.user_id))) return false;
    return true;
  });

  // Render Full Feasibility UI
  feasBody.innerHTML = `
    <!-- Top Feasibility Header -->
    <div style="background:var(--bg3); border:1px solid var(--border); border-radius:12px; padding:18px 22px; margin-bottom:20px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:12px;">
      <div>
        <div style="font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:1.5px; color:var(--gold); margin-bottom:4px;">Feasibility Assessment</div>
        <div style="font-size:18px; font-weight:700; color:var(--cream);">${escHtml(ev.client)} &bull; ${escHtml(ev.packageName || ev.type || 'Event')}</div>
        <div style="font-size:12px; color:var(--text-dim); margin-top:3px;">Date: <strong style="color:var(--gold);">${resDate || 'Unscheduled'}</strong> &bull; Pax: <strong>${pax}</strong> &bull; Venue: <strong>${escHtml(ev.venue || 'TBD')}</strong></div>
      </div>
      <div>
        <button class="btn-outline" style="padding:6px 14px; font-size:11px;" onclick="renderAssessFeasibilityView(RESERVATIONS.find(r => r.id === currentEditingEventId))">Refresh Assessment</button>
      </div>
    </div>

    <!-- Section 1: Other Bookings on This Date -->
    <div style="background:var(--bg3); border:1px solid var(--border); border-radius:12px; padding:20px; margin-bottom:22px;">
      <div style="font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:1px; color:var(--gold); margin-bottom:14px;">
        Other Bookings on ${resDate || 'This Date'} (${sameDateReservations.length})
      </div>
      ${sameDateReservations.length === 0 ? `
        <div style="font-size:13px; color:var(--text-dim); padding:10px 0;">No other reservations booked on this date.</div>
      ` : `
        <div style="display:flex; flex-direction:column; gap:10px;">
          ${sameDateReservations.map(r => {
            const timeRange = r.time || r.timeframe || 'Time not specified';
            const callTime = r.callTime || r.call_time || '';
            const statusLabel = (r.status || 'confirmed').toUpperCase();
            return `
              <div style="background:var(--bg2); border:1px solid var(--border); border-radius:10px; padding:12px 16px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:12px;">
                <div>
                  <div style="font-size:14px; font-weight:700; color:var(--cream);">${escHtml(r.client || 'Client')} <span style="font-size:11px; font-weight:400; color:var(--text-dim);">(${escHtml(r.id)})</span></div>
                  <div style="font-size:12px; color:var(--gold); margin-top:2px;">${escHtml(r.packageName || r.type || 'Event')} &bull; ${r.pax || 0} Pax &bull; ${escHtml(r.venue || 'Venue TBD')}</div>
                </div>
                <div style="text-align:right;">
                  <div style="font-size:13px; font-weight:600; color:var(--cream);">${escHtml(timeRange)}</div>
                  ${callTime ? `<div style="font-size:11px; color:var(--text-dim);">Call Time: ${escHtml(callTime)}</div>` : ''}
                  <div style="font-size:10px; font-weight:700; color:var(--text-mid); text-transform:uppercase; margin-top:3px;">Status: ${statusLabel}</div>
                </div>
              </div>
            `;
          }).join('')}
        </div>
      `}
    </div>

    <!-- Section 2: Equipment Availability Table with Same Equipment Demands -->
    <div style="background:var(--bg3); border:1px solid var(--border); border-radius:12px; padding:20px; margin-bottom:22px;">
      <div style="font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:1px; color:var(--gold); margin-bottom:14px;">
        Equipment Availability &amp; Demands
      </div>
      <div style="overflow-x:auto;">
        <table style="width:100%; border-collapse:collapse; min-width:860px;">
          <thead>
            <tr style="border-bottom:1px solid var(--border); text-align:left;">
              <th style="font-size:11px; color:var(--text-dim); padding:8px 10px; text-transform:uppercase;">Asset ID</th>
              <th style="font-size:11px; color:var(--text-dim); padding:8px 10px; text-transform:uppercase;">Equipment</th>
              <th style="font-size:11px; color:var(--text-dim); padding:8px 10px; text-transform:uppercase;">Required</th>
              <th style="font-size:11px; color:var(--text-dim); padding:8px 10px; text-transform:uppercase;">Buffer</th>
              <th style="font-size:11px; color:var(--text-dim); padding:8px 10px; text-transform:uppercase;">Customization</th>
              <th style="font-size:11px; color:var(--text-dim); padding:8px 10px; text-transform:uppercase;">Total</th>
              <th style="font-size:11px; color:var(--text-dim); padding:8px 10px; text-transform:uppercase;">Allocated</th>
              <th style="font-size:11px; color:var(--text-dim); padding:8px 10px; text-transform:uppercase;">Available</th>
              <th style="font-size:11px; color:var(--red); padding:8px 10px; text-transform:uppercase; text-align:center;">Short</th>
              <th style="font-size:11px; color:var(--text-dim); padding:8px 10px; text-transform:uppercase;">Fulfillable</th>
              <th style="font-size:11px; color:var(--gold); padding:8px 10px; text-transform:uppercase;">Same Equipment Demands</th>
            </tr>
          </thead>
          <tbody>
            ${tableRowsHtml || '<tr><td colspan="11" style="padding:20px; text-align:center; color:var(--text-dim);">No equipment items mapped.</td></tr>'}
          </tbody>
        </table>
      </div>
    </div>

    <!-- Section 3: Active Staff Members -->
    <div style="background:var(--bg3); border:1px solid var(--border); border-radius:12px; padding:20px;">
      <div style="font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:1px; color:var(--gold); margin-bottom:14px;">
        Active Staff Members (${activeStaff.length})
      </div>
      ${activeStaff.length === 0 ? `
        <div style="font-size:13px; color:var(--text-dim); padding:10px 0;">No active staff members found.</div>
      ` : `
        <div style="overflow-x:auto;">
          <table style="width:100%; border-collapse:collapse; font-size:12px; min-width:380px;">
            <thead>
              <tr style="border-bottom:1px solid var(--border); text-align:left;">
                <th style="padding:8px 10px; color:var(--text-dim); font-size:11px; text-transform:uppercase;">Name</th>
                <th style="padding:8px 10px; color:var(--text-dim); font-size:11px; text-transform:uppercase;">Role</th>
                <th style="padding:8px 10px; color:var(--text-dim); font-size:11px; text-transform:uppercase;">Status</th>
              </tr>
            </thead>
            <tbody>
              ${activeStaff.map(s => `
                <tr style="border-bottom:1px solid rgba(255,255,255,0.05);">
                  <td style="padding:8px 10px; font-weight:600; color:var(--cream);">${escHtml(s.name || 'Staff')}</td>
                  <td style="padding:8px 10px; color:var(--gold); font-weight:600;">${escHtml(s.role || 'Staff')}</td>
                  <td style="padding:8px 10px; color:var(--green); font-weight:600;">Active</td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        </div>
      `}
    </div>
  `;
}
window.renderAssessFeasibilityView = renderAssessFeasibilityView;

window.openEventDetails = openEventDetails;
window.closeEventDetails = closeEventDetails;
window.backToCalendar = backToCalendar;
window.changeEventStatus = changeEventStatus;

// ===== RENDER DASHBOARD =====
function renderDashboard() {
  if (typeof renderAdminAvailabilityGrid === 'function') renderAdminAvailabilityGrid();
  // Active reservations: as long as a reservation is not marked as pending, completed, or cancelled, read it!
  const activeReservations = RESERVATIONS.filter(r => {
    const s = String(r.status || '').toLowerCase().trim();
    return !['completed', 'cancelled', 'rejected'].includes(s);
  });
  const calendarReservations = RESERVATIONS.filter(r => {
    const s = String(r.status || '').toLowerCase();
    return ['confirmed', 'approved', 'pending', 'procurement', 'procuring', 'preparing', 'on-going', 'ongoing', 'in-progress', 'in_progress'].includes(s);
  });
  const pending = RESERVATIONS.filter(r => r.status === 'pending');

  document.getElementById('dash-stat-upcoming').textContent = activeReservations.length;
  document.getElementById('dash-stat-pending').textContent = pending.length;

  // Equipment stat: Synchronizes strictly with the Equipment Maintenance Pipeline
  let underRepair = 0;
  let issuesCount = 0;

  // 1. Pending routine checks with incidents not yet sent to repair
  const pendingRoutine = (window.routineChecksCache || []).filter(rc => {
    return !(window.maintenanceTasks || []).some(t => t.routine_check_id === rc.id);
  });
  // 2. Execution day batch equipment incidents (broken/maintenance) not sent to repair
  const pendingExec = (window.execBatchIncidentsCache || []).filter(inc => {
    const isBroken = ['broken', 'damaged', 'maintenance'].includes(String(inc.incident_type || '').toLowerCase());
    return isBroken && !(window.maintenanceTasks || []).some(t => t.exec_incident_id === inc.id);
  });
  // 3. Normal inspection reports (standalone reports outside routine checks) not sent to repair
  const pendingStandalone = (window.standaloneIncidentsCache || []).filter(sa => {
    const isBroken = ['broken', 'damaged', 'maintenance'].includes(String(sa.incident_type || '').toLowerCase());
    return isBroken && !(window.maintenanceTasks || []).some(t => t.standalone_incident_id === sa.id);
  });

  const pipelineReview = pendingRoutine.length + pendingExec.length + pendingStandalone.length;

  let pipelineRepair = 0;
  (window.maintenanceTasks || []).forEach(t => {
    const s = String(t.status || '').toLowerCase();
    if (s === 'pending' || s === 'in repair' || s === 'under repair' || s === 'in_repair') {
      pipelineRepair += (t.quantity || 1);
    }
  });

  let assetMaintQty = 0;
  (EIM_ASSETS || []).forEach(a => {
    let mQty = parseInt(a.maintenance_qty || 0);
    const cachedUnits = window.EQUIPMENT_UNITS_CACHE ? window.EQUIPMENT_UNITS_CACHE[a.asset_id || a.id] : null;
    if (cachedUnits && Array.isArray(cachedUnits)) {
      const uBroken = cachedUnits.filter(u => (u.condition || '').toLowerCase() === 'broken' || (u.status || '').toLowerCase() === 'maintenance').length;
      mQty = Math.max(mQty, uBroken);
    }
    if (a.status === 'Under Repair' || a.status === 'under_repair' || a.status === 'Maintenance') {
      assetMaintQty += (mQty > 0 ? mQty : 1);
    } else {
      assetMaintQty += mQty;
    }
    const missQty = parseInt(a.missing_qty || 0);
    issuesCount += (mQty + missQty);
  });

  const pipelineTotal = pipelineReview + pipelineRepair;
  underRepair = pipelineTotal > 0 ? pipelineTotal : assetMaintQty;

  const dashStatEquip = document.getElementById('dash-stat-equip');
  if (dashStatEquip) {
    dashStatEquip.textContent = underRepair > 0 ? underRepair : (issuesCount > 0 ? issuesCount : 'Operational');
    dashStatEquip.style.color = (underRepair > 0 || issuesCount > 0) ? 'var(--red)' : '';
  }

  const dashStatEquipSub = document.getElementById('dash-stat-equip-sub');
  if (dashStatEquipSub) {
    if (underRepair > 0) {
      dashStatEquipSub.textContent = underRepair === 1 ? 'item under repair' : 'items under repair';
      dashStatEquipSub.style.color = 'var(--red)';
    } else if (issuesCount > 0) {
      dashStatEquipSub.textContent = 'issues detected';
      dashStatEquipSub.style.color = 'var(--red)';
    } else {
      dashStatEquipSub.textContent = 'All assets operational';
      dashStatEquipSub.style.color = '';
    }
  }

  // Est. Revenue (Month): reads all active reservations (including on-going, confirmed, etc.)
  const rev = activeReservations.reduce((sum, r) => {
    const raw = r.amount != null ? String(r.amount).replace(/[^\d.]/g, '') : '0';
    return sum + (parseFloat(raw) || 0);
  }, 0);
  document.getElementById('dash-stat-revenue').textContent = '₱' + Math.round(rev).toLocaleString();

  const resBadge = document.getElementById('res-sidebar-badge');
  if (resBadge) {
    resBadge.textContent = pending.length;
    resBadge.style.display = pending.length > 0 ? 'inline-flex' : 'none';
  }

  // Upcoming reservations panel: displays active events (not pending, completed, or cancelled)
  const upcoming = activeReservations.slice(0, 4);
  document.getElementById('dash-reservations').innerHTML = upcoming.length ? upcoming.map(r => {
    const dateVal = String(r.date || '');
    const parts = dateVal.includes(' ') ? dateVal.split(' ') : [dateVal, ''];
    const day = (parts[1] || '').replace(',', '') || dateVal.split('-')[2] || '';
    const mon = parts[0] || '';

    return `
      <div class="res-item">
        <div class="res-date-box">
          <div class="res-date-day">${day}</div>
          <div class="res-date-mon">${mon}</div>
        </div>
        <div class="res-info">
          <div class="res-name">${r.client || 'Unnamed Client'}</div>
          <div style="font-size:11px;color:var(--gold);margin-top:2px;">${r.packageName || r.type || 'Custom Event'}</div>
          <div class="res-details"><span> ${r.pax || 0} pax</span><span> ${r.type || 'Event'}</span></div>
        </div>
        <div class="res-right">
          <div class="res-price">${r.displayAmount || '₱0'}</div>
          <span class="badge ${r.status || 'pending'}">${(r.status || 'pending').charAt(0).toUpperCase() + (r.status || 'pending').slice(1)}</span>
        </div>
      </div>`;
  }).join('') : `<div style="text-align:center;padding:24px;color:var(--text-dim);font-size:13px;">No active events found.</div>`;

  // Activity log
  const logEl = document.getElementById('activity-log');
  if (logEl) {
    logEl.innerHTML = (ACTIVITY || []).map(a => `
      <div class="timeline-item">
        <div class="timeline-dot ${a.dot || 'amber'}"></div>
        <div class="timeline-content">
          <div class="timeline-title">${a.title || 'System Update'}</div>
          <div class="timeline-sub">${a.sub || 'No details available'}</div>
        </div>
        <div class="timeline-time">${a.time || 'now'}</div>
      </div>`).join('') || '<div style="text-align:center;padding:24px;color:var(--text-dim);font-size:13px;">No recent activity.</div>';
  }

  // Dashboard Calendar
  const calEl = document.getElementById('dash-calendar');
  if (!calEl) return;

  if (typeof FullCalendar === 'undefined') {
    calEl.innerHTML = '<div style="text-align:center;padding:40px;color:var(--text-dim);">Calendar library loading...</div>';
    return;
  }

  const eventsData = buildReservationCalendarEvents(calendarReservations);
  try {
    if (window.dashCalendar) {
      try {
        window.dashCalendar.destroy();
      } catch (e) { }
      window.dashCalendar = null;
    }

    function updateDashCalendarTitleDropdowns() {
      if (!window.dashCalendar) return;
      const cEl = document.getElementById('dash-calendar');
      if (!cEl) return;
      const titleEl = cEl.querySelector('.fc-toolbar-title');
      if (!titleEl) return;

      const curDate = window.dashCalendar.getDate();
      const curMonth = curDate.getMonth();
      const curYear = curDate.getFullYear();

      const monthNames = [
        'January', 'February', 'March', 'April', 'May', 'June',
        'July', 'August', 'September', 'October', 'November', 'December'
      ];

      let mSelect = document.getElementById('dash-cal-month-select');
      let ySelect = document.getElementById('dash-cal-year-select');

      if (!mSelect || !ySelect || !titleEl.contains(mSelect)) {
        titleEl.innerHTML = '';
        const wrap = document.createElement('div');
        wrap.style.cssText = 'display:inline-flex; align-items:center; justify-content:center; gap:8px;';

        const mSel = document.createElement('select');
        mSel.id = 'dash-cal-month-select';
        mSel.className = 'custom-cal-select';
        mSel.setAttribute('aria-label', 'Select month');
        mSel.style.cssText = 'font-weight:700; font-size:14px; padding:4px 10px; cursor:pointer; background:var(--bg3, #221a12); color:var(--cream, #fff); border:1px solid var(--border, rgba(180,140,60,0.3)); border-radius:6px;';
        monthNames.forEach((name, idx) => {
          const opt = document.createElement('option');
          opt.value = idx;
          opt.textContent = name;
          if (idx === curMonth) opt.selected = true;
          mSel.appendChild(opt);
        });

        const ySel = document.createElement('select');
        ySel.id = 'dash-cal-year-select';
        ySel.className = 'custom-cal-select';
        ySel.setAttribute('aria-label', 'Select year');
        ySel.style.cssText = 'font-weight:700; font-size:14px; padding:4px 10px; cursor:pointer; background:var(--bg3, #221a12); color:var(--cream, #fff); border:1px solid var(--border, rgba(180,140,60,0.3)); border-radius:6px;';
        for (let y = 2024; y <= 2035; y++) {
          const opt = document.createElement('option');
          opt.value = y;
          opt.textContent = y;
          if (y === curYear) opt.selected = true;
          ySel.appendChild(opt);
        }

        const onNavChange = function() {
          const mVal = parseInt(mSel.value, 10);
          const yVal = parseInt(ySel.value, 10);
          if (!isNaN(mVal) && !isNaN(yVal) && window.dashCalendar) {
            window.dashCalendar.gotoDate(new Date(yVal, mVal, 1));
          }
        };
        mSel.onchange = onNavChange;
        ySel.onchange = onNavChange;

        wrap.appendChild(mSel);
        wrap.appendChild(ySel);
        titleEl.appendChild(wrap);
      } else {
        mSelect.value = curMonth;
        ySelect.value = curYear;
      }
    }

    window.dashCalendar = new FullCalendar.Calendar(calEl, {
      initialView: 'dayGridMonth',
      headerToolbar: { left: 'prev', center: 'title', right: 'next' },
      height: 580,
      displayEventTime: false,
      events: eventsData,
      datesSet: function() {
        if (typeof updateDashCalendarTitleDropdowns === 'function') {
          updateDashCalendarTitleDropdowns();
        }
        if (typeof refreshCalendarDisabledCells === 'function') {
          setTimeout(refreshCalendarDisabledCells, 15);
        }
      },
      dayCellDidMount: function (arg) {
        let dateKey = (arg.el && arg.el.getAttribute('data-date')) || arg.dateStr;
        if (!dateKey && arg.date instanceof Date) {
          const d = arg.date;
          dateKey = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
        }
        if (!dateKey || !/^\d{4}-\d{2}-\d{2}$/.test(dateKey)) return;
        const now = new Date();
        const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
        const isPast = dateKey < todayStr;
        if (isPast && window.DISABLED_CALENDAR_DATES && window.DISABLED_CALENDAR_DATES.has(dateKey)) {
          window.DISABLED_CALENDAR_DATES.delete(dateKey);
        }
        const isDis = !isPast && window.DISABLED_CALENDAR_DATES && window.DISABLED_CALENDAR_DATES.has(dateKey);
        arg.el.classList.toggle('fc-day-disabled', !!isDis);
        
        // Target .fc-daygrid-day-top so the label stays neatly inside the header
        const topEl = arg.el.querySelector('.fc-daygrid-day-top') || arg.el.querySelector('.fc-daygrid-day-frame') || arg.el;
        const oldLbls = arg.el.querySelectorAll('.fc-day-disable-label');
        oldLbls.forEach(l => l.remove());

        if (!isPast) {
          const lbl = document.createElement('label');
          lbl.className = 'fc-day-disable-label';
          lbl.title = 'Disable booking and meetings for ' + dateKey;
          lbl.onclick = function(e) { e.stopPropagation(); };
          lbl.innerHTML = `<input type="checkbox" class="fc-disable-chk" data-date="${dateKey}" ${isDis ? 'checked' : ''} onclick="event.stopPropagation()" onchange="event.stopPropagation(); toggleAdminCalendarDateDisabled('${dateKey}', this.checked)" /> <span>Disable</span>`;
          topEl.insertBefore(lbl, topEl.firstChild);
        }
      },
      eventClick: function (info) { if (info.event.extendedProps?.type === 'meeting') { openMtDetailsModal(info.event.extendedProps?.meetingId || info.event.id); } else { openEventDetails(info.event.extendedProps?.reservationId || info.event.id); } }
    });
    if (document.getElementById('section-dashboard').classList.contains('active')) {
      window.dashCalendar.render();
      if (typeof refreshCalendarDisabledCells === 'function') refreshCalendarDisabledCells();
    }
  } catch (e) {
    console.error('FullCalendar Error:', e);
    calEl.innerHTML = '<div style="text-align:center;padding:40px;color:var(--red);">Error loading calendar.</div>';
  }
  updateRoutineAlertBanner();
  if (typeof renderAdminAlerts === 'function') renderAdminAlerts();
  // (Session check moved to loadEIMFromSupabase to ensure EIM_ASSETS is loaded first)
}

function getReservationPrepStartDate(res) {
  const eventDate = normalizeDateKey(res.date);
  if (!eventDate) return eventDate;
  const eventObj = new Date(eventDate + 'T00:00:00');
  if (isNaN(eventObj.getTime())) return eventDate;

  // Safety cap: never render more than 7 prep days.
  const minPrepObj = new Date(eventObj);
  minPrepObj.setDate(minPrepObj.getDate() - 7);

  const submitted = normalizeDateKey(res.submittedDate || res.createdAt || res.requestedAt || res.bookedAt);
  if (submitted) {
    const submittedObj = new Date(submitted + 'T00:00:00');
    if (!isNaN(submittedObj.getTime()) && submittedObj < eventObj) {
      return (submittedObj > minPrepObj ? submittedObj : minPrepObj).toISOString().split('T')[0];
    }
  }
  return minPrepObj.toISOString().split('T')[0];
}

function getColorForId(id, index) {
  const colors = [
    '#2563eb', // Royal Blue
    '#059669', // Emerald Green
    '#7c3aed', // Purple
    '#d97706', // Amber Gold
    '#db2777', // Pink/Rose
    '#0891b2', // Cyan
    '#65a30d', // Lime
    '#ea580c', // Orange
    '#4f46e5', // Indigo
    '#0d9488', // Teal
    '#9333ea', // Violet
    '#e11d48', // Crimson
    '#0284c7', // Sky Blue
    '#16a34a', // Green
    '#b45309', // Ochre
    '#6d28d9', // Deep Violet
    '#be185d', // Fuchsia
    '#1d4ed8', // Cobalt
    '#4338ca', // Deep Indigo
    '#0f766e'  // Deep Teal
  ];
  if (index !== undefined && index !== null && !isNaN(index)) {
    return colors[index % colors.length];
  }
  let hash = 0;
  if (!id) return colors[0];
  for (let i = 0; i < id.length; i++) {
    hash = id.charCodeAt(i) + ((hash << 5) - hash);
  }
  return colors[Math.abs(hash) % colors.length];
}

function formatReservationTimeRange12h(timeStr) {
  if (!timeStr || typeof timeStr !== 'string' || !timeStr.trim()) {
    return '12:00 PM - 5:00 PM';
  }
  const str = timeStr.trim();
  function to12h(t) {
    if (!t) return '';
    let raw = t.trim();
    const hasAm = /am/i.test(raw);
    const hasPm = /pm/i.test(raw);
    raw = raw.replace(/am|pm/ig, '').trim();
    const parts = raw.split(':');
    let h = parseInt(parts[0], 10);
    let m = parts[1] !== undefined ? parseInt(parts[1], 10) : 0;
    if (isNaN(h)) return t.trim();
    if (isNaN(m)) m = 0;

    let period = 'AM';
    if (hasPm) {
      period = 'PM';
      if (h < 12) {}
    } else if (hasAm) {
      period = 'AM';
      if (h === 12) h = 12;
    } else {
      if (h >= 12) {
        period = 'PM';
        if (h > 12) h -= 12;
      } else {
        period = 'AM';
        if (h === 0) h = 12;
      }
    }
    const mStr = String(m).padStart(2, '0');
    return `${h}:${mStr} ${period}`;
  }

  if (str.includes('-')) {
    const [p1, p2] = str.split('-');
    const t1 = to12h(p1);
    const t2 = to12h(p2);
    if (t1 && t2) return `${t1} - ${t2}`;
  }
  return to12h(str) || '12:00 PM - 5:00 PM';
}
window.formatReservationTimeRange12h = formatReservationTimeRange12h;

function buildReservationCalendarEvents(resList, opts) {
  const options = opts || {};
  const events = [];
  (resList || []).forEach(function (ev, idx) {
    const status = String(ev.status || '').toLowerCase();
    if (!['confirmed', 'approved', 'pending', 'procurement', 'procuring', 'preparing', 'on-going', 'ongoing', 'in-progress', 'in_progress'].includes(status)) return;
    const eventDate = normalizeDateKey(ev.date);
    const prepStart = getReservationPrepStartDate(ev);
    const resColor = getColorForId(ev.id, idx);

    // Push single multi-day event for prep period (covers up to the day before natively via exclusive end)
    if (prepStart !== eventDate) {
      events.push({
        id: ev.id + '-prep',
        title: '', // Removed 'Reserved'
        start: prepStart,
        end: eventDate,
        allDay: true,
        color: resColor,
        textColor: '#fff',
        sortOrder: 3,
        className: 'prep-event',
        extendedProps: { reservationId: ev.id, type: 'prep' }
      });
    }

    const timeFormatted = formatReservationTimeRange12h(ev.timeframe || ev.time || '');

    // Push main event (only 12h time range, no client / package prefix)
    events.push({
      id: ev.id,
      title: options.includeMainEventLabel === false ? 'Event Day' : timeFormatted,
      start: eventDate,
      allDay: true,
      color: resColor,
      textColor: '#fff',
      sortOrder: 0,
      extendedProps: { reservationId: ev.id, type: 'event' }
    });
  });

  // Display scheduled meetings on the Approved Calendar with time range in sharp yellow color
  const now = new Date();
  const todayStr = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  const meetingsList = (window.MEETINGS && Array.isArray(window.MEETINGS)) ? window.MEETINGS : ((typeof MEETINGS !== 'undefined' && Array.isArray(MEETINGS)) ? MEETINGS : []);
  meetingsList.forEach(m => {
    if (!m || !m.date) return;
    const mDate = normalizeDateKey(m.date);
    if (!mDate) return;

    // Do NOT display meetings that have passed the date already!
    if (mDate < todayStr) return;

    // Do NOT display meetings for cancelled, rejected, or completed meetings!
    const mStatus = String(m.status || '').toLowerCase().trim();
    if (mStatus === 'cancelled' || mStatus === 'rejected' || mStatus === 'completed') return;

    // Do NOT display meetings for cancelled or completed reservations!
    const rId = m.reservationId || m.reservation_id;
    const allRes = (window.RESERVATIONS && Array.isArray(window.RESERVATIONS)) ? window.RESERVATIONS : ((typeof RESERVATIONS !== 'undefined' && Array.isArray(RESERVATIONS)) ? RESERVATIONS : []);
    if (rId && allRes.length > 0) {
      const matchedRes = allRes.find(r => r && (r.id === rId || String(r.id) === String(rId)));
      if (matchedRes) {
        const rStatus = String(matchedRes.status || '').toLowerCase().trim();
        if (['cancelled', 'rejected', 'completed'].includes(rStatus)) return;
      }
    }

    let timeText = '';
    const rawTime = m.time || '';
    const rawEnd = m.timeEnd || m.time_end || '';
    if (rawTime && (rawTime.includes(' to ') || rawTime.includes(' - '))) {
      timeText = rawTime.replace(' to ', ' - ');
    } else if (rawTime) {
      const s12 = rawTime.includes('M') ? rawTime : (typeof adminTime24ToAMPM === 'function' ? adminTime24ToAMPM(rawTime) : rawTime);
      const e12 = rawEnd ? (rawEnd.includes('M') ? rawEnd : (typeof adminTime24ToAMPM === 'function' ? adminTime24ToAMPM(rawEnd) : rawEnd)) : '';
      timeText = e12 ? `${s12} - ${e12}` : s12;
    } else {
      timeText = 'Meeting';
    }

    events.push({
      id: 'mtg-' + (m.id || Math.random().toString(36).substr(2, 9)),
      title: timeText,
      start: mDate,
      allDay: true,
      color: '#eab308',
      backgroundColor: '#eab308',
      borderColor: '#ca8a04',
      textColor: '#000000',
      sortOrder: 1,
      className: 'fc-meeting-event-sharp-yellow',
      extendedProps: {
        meetingId: m.id,
        reservationId: m.reservationId || m.reservation_id,
        type: 'meeting',
        clientName: m.clientName || m.customerName || m.customer_name || ''
      }
    });
  });

  return events;
}

// ===== RENDER RESERVATIONS =====
function formatReservationDateDisplay(dateStr) {
  if (!dateStr) return '';
  const str = String(dateStr).trim();
  const m = str.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) {
    const yr = parseInt(m[1], 10);
    const mo = parseInt(m[2], 10) - 1;
    const dy = parseInt(m[3], 10);
    const d = new Date(yr, mo, dy);
    return d.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
  }
  const parsed = new Date(str);
  if (!isNaN(parsed.getTime())) {
    return parsed.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
  }
  return str;
}
window.formatReservationDateDisplay = formatReservationDateDisplay;

let currentFilter = 'all';
let resCurrentPage = 1;
const resPageSize = 20;

function renderReservations(filter = 'all', page = null) {
  if (filter !== currentFilter) {
    currentFilter = filter;
    resCurrentPage = 1;
  }
  if (page !== null) {
    resCurrentPage = page;
  }
  let filtered;
  if (currentFilter === 'all') {
    filtered = RESERVATIONS;
  } else if (currentFilter === 'confirmed') {
    // Include on-going, ongoing, preparation, preparing, procurement, etc.
    // If not pending, cancelled, rejected, or completed -> display as confirmed in the all reservations area
    filtered = RESERVATIONS.filter(r => {
      const s = String(r.status || '').toLowerCase().trim();
      return s !== 'pending' && s !== 'cancelled' && s !== 'rejected' && s !== 'completed';
    });
  } else {
    filtered = RESERVATIONS.filter(r => String(r.status || '').toLowerCase().trim() === currentFilter.toLowerCase().trim());
  }

  const paginationEl = document.getElementById('res-pagination-container');

  if (!filtered.length) {
    document.getElementById('res-tbody').innerHTML = `
      <tr><td colspan="7" style="text-align:center;padding:24px;color:var(--text-dim);">
        No ${currentFilter === 'all' ? '' : currentFilter} reservations found.
      </td></tr>`;
    if (paginationEl) {
      paginationEl.style.display = 'none';
      paginationEl.innerHTML = '';
    }
    return;
  }

  const totalItems = filtered.length;
  const totalPages = Math.ceil(totalItems / resPageSize) || 1;
  if (resCurrentPage > totalPages) resCurrentPage = totalPages;
  if (resCurrentPage < 1) resCurrentPage = 1;

  const startIdx = (resCurrentPage - 1) * resPageSize;
  const pageRows = filtered.slice(startIdx, startIdx + resPageSize);

  document.getElementById('res-tbody').innerHTML = pageRows.map(r => {
    const obCount = getOverbookingCount(r.date);
    const isOverbooked = obCount >= 3;

    // Check if reservation is happening soon and is heavy (200+ equipment allocation or 200+ pax)
    let isUpcomingHeavy = false;
    const rStatus = String(r.status || '').toLowerCase();
    if (!['cancelled', 'completed', 'rejected'].includes(rStatus) && r.date) {
      const nowMs = new Date().setHours(0, 0, 0, 0);
      const evMs = new Date(r.date).getTime();
      const diffDays = Math.ceil((evMs - nowMs) / (1000 * 60 * 60 * 24));
      // Happening soon (within upcoming 45 days or active upcoming event)
      const isSoon = diffDays >= -1 && diffDays <= 45;

      const rPax = parseInt(r.pax || r.guestCount || 0) || 0;
      let rEquipQty = 0;
      const rItems = Array.isArray(r.items) ? r.items : (Array.isArray(r.custom_items) ? r.custom_items : (Array.isArray(r.packageItems) ? r.packageItems : []));
      rItems.forEach(it => {
        if (typeof it === 'object' && it) {
          const c = String(it.cat || it.category || '').toLowerCase();
          if (c === 'equipment') {
            rEquipQty += (parseInt(it.customQty ?? it.autoQty ?? it.quantity ?? it.allocated_qty ?? 1) || 1);
          }
        }
      });
      if (r.allocated_qty && parseInt(r.allocated_qty) >= 200) rEquipQty = Math.max(rEquipQty, parseInt(r.allocated_qty));

      const isHeavy = (rEquipQty >= 200 || rPax >= 200);
      if (isSoon && isHeavy) {
        isUpcomingHeavy = true;
      }
    }

    const glowStyle = isUpcomingHeavy
      ? 'background-color: rgba(239, 68, 68, 0.16) !important; border-left: 4px solid #f87171 !important;'
      : '';

    return `
      <tr class="res-row-clickable" style="${glowStyle}" onclick="openEventDetails('${r.id}')">
        <td>
          <div class="item-name">${r.client}</div>
          <div style="font-size:11px;color:var(--gold);margin-top:2px;">${r.packageName || r.type}</div>
          ${isOverbooked ? '<span class="badge overbooked" style="font-size:9px; margin-top:4px;"> DATE OVERBOOKED (' + obCount + ')</span>' : ''}
          ${(() => {
            const ifStatus = String(r.initial_fee_status || r.initialFeeStatus || '').toLowerCase();
            const ifDue = r.initial_fee_due_date || r.initialFeeDueDate || (r.initial_fee_deadline ? r.initial_fee_deadline.slice(0, 10) : null);
            if (ifStatus !== 'paid' && ifDue) {
              return `<div style="font-size:10.5px; color:#f59e0b; margin-top:3px; font-weight:600;"><i class="fas fa-calendar-alt"></i> Initial Fee Due: ${escHtml(formatReservationDateDisplay(ifDue))}</div>`;
            }
            return '';
          })()}
        </td>
        <td style="font-size:12px;color:var(--text-mid);">${r.type}</td>
        <td style="font-size:12px;color:var(--text-mid);">${formatReservationDateDisplay(r.date)}</td>
        <td style="font-size:13px;">${r.pax}</td>
        <td><div style="font-family:'Arial',serif;font-size:14px;font-weight:600;color:var(--cream);">${r.displayAmount}</div></td>
        <td>
           <span class="badge ${r.status}">${r.status === 'pending' ? 'Semi-Approved' : r.status.charAt(0).toUpperCase() + r.status.slice(1)}</span>
           ${r.rejectionReason ? `<div style="font-size:9px; color:var(--red); margin-top:4px; max-width:100px; overflow:hidden; text-overflow:ellipsis;">Reason: ${r.rejectionReason}</div>` : ''}
        </td>
        <td>
          <div style="display:flex; gap:6px;">
            ${r.status === 'pending'
        ? `<button class="btn-view" onclick="openEventDetails('${r.id}')">Details</button>
           <button class="btn-reject" onclick="initiateRejection('${r.id}', event)">Reject</button>`
        : `<button class="btn-view" onclick="openEventDetails('${r.id}')">Details</button>`}
          </div>
        </td>
      </tr>`;
  }).join('');

  if (paginationEl) {
    if (totalItems <= resPageSize) {
      paginationEl.style.display = 'none';
      paginationEl.innerHTML = '';
    } else {
      paginationEl.style.display = 'flex';
      paginationEl.innerHTML = `
        <div style="color:var(--text-dim); font-size:12px;">
          Showing <span style="color:var(--cream); font-weight:600;">${startIdx + 1}</span>-<span style="color:var(--cream); font-weight:600;">${Math.min(startIdx + resPageSize, totalItems)}</span> of <span style="color:var(--cream); font-weight:600;">${totalItems}</span> reservations
        </div>
        <div style="display:flex; align-items:center; gap:8px;">
          <button type="button" onclick="window.resChangePage(${resCurrentPage - 1})" ${resCurrentPage <= 1 ? 'disabled' : ''} style="padding:6px 14px; background:var(--bg3); border:1px solid var(--border); border-radius:6px; color:var(--cream); font-size:12px; font-weight:600; cursor:${resCurrentPage <= 1 ? 'not-allowed' : 'pointer'}; opacity:${resCurrentPage <= 1 ? '0.4' : '1'};">
            Previous
          </button>
          <span style="font-size:12px; color:var(--text-dim); margin:0 4px;">Page <span style="color:var(--gold); font-weight:700;">${resCurrentPage}</span> of <span style="font-weight:600;">${totalPages}</span></span>
          <button type="button" onclick="window.resChangePage(${resCurrentPage + 1})" ${resCurrentPage >= totalPages ? 'disabled' : ''} style="padding:6px 14px; background:var(--bg3); border:1px solid var(--border); border-radius:6px; color:var(--cream); font-size:12px; font-weight:600; cursor:${resCurrentPage >= totalPages ? 'not-allowed' : 'pointer'}; opacity:${resCurrentPage >= totalPages ? '0.4' : '1'};">
            Next
          </button>
        </div>
      `;
    }
  }
}

window.resChangePage = function (p) {
  renderReservations(currentFilter, p);
};

function filterRes(filter, btn) {
  document.querySelectorAll('#section-reservations .tab-btn').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  renderReservations(filter);
  renderReservationDetailsHandling();
}

function reservationEligibleForActivityLogs(r) {
  const s = String(r.status || '').toLowerCase();
  return ['confirmed', 'preparing', 'preparation', 'procurement', 'procuring', 'on-going', 'ongoing', 'completed'].includes(s);
}

function activityLogBadgeClass(cat) {
  const c = String(cat || '').toLowerCase();
  if (c === 'approval' || c === 'customer') return 'confirmed';
  if (c === 'finance') return 'pending';
  if (c === 'meeting') return 'warning';
  if (c === 'inventory' || c === 'allocation') return 'pending';
  if (c === 'execution' || c === 'tracking') return 'confirmed';
  if (c === 'bashout' || c === 'payment') return 'warning';
  return 'pending';
}

function lifecycleAnchorDate(res) {
  const dk = normalizeDateKey(res.date) || new Date().toISOString().split('T')[0];
  const x = new Date(dk + 'T12:00:00');
  return isNaN(x.getTime()) ? new Date() : x;
}

function isoShiftDays(base, dayDelta, hh, mm) {
  const d = new Date(base.getTime());
  d.setDate(d.getDate() + dayDelta);
  d.setHours(hh != null ? hh : 10, mm != null ? mm : 0, 0, 0);
  return d.toISOString();
}

