window.filterResdApprovedDropdown = function () {
  const input = document.getElementById('resd-approved-input');
  const dropdown = document.getElementById('resd-approved-dropdown');
  if (!input || !dropdown) return;

  const chkCancelled = document.getElementById('chk-show-cancelled-res');
  const showCancelled = chkCancelled ? chkCancelled.checked : false;
  const chkCompleted = document.getElementById('chk-show-completed-res');
  const showCompleted = chkCompleted ? chkCompleted.checked : false;

  const approved = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).filter(function (r) {
    const st = String(r.status || '').toLowerCase().trim();
    const cancelStatus = String(r.cancellation_status || r.cancellationStatus || r.cancellation_request_status || '').toLowerCase().trim();
    const isCanc = st === 'cancelled' || cancelStatus === 'cancelled' || (typeof isReservationCancelled === 'function' && isReservationCancelled(r));
    const isUnresolved = st === 'unresolved' || cancelStatus === 'unresolved' || (typeof localStorage !== 'undefined' && localStorage.getItem('res_unresolved_' + r.id) === 'true');
    const isComp = st === 'completed' || r.ops_status === 'completed' || r.execution_live_status === 'concluded' || r.execution_live_status === 'completed';
    const hasPendingBal = typeof isCancelledWithPendingBalance === 'function' ? isCancelledWithPendingBalance(r) : false;

    if (showCompleted) {
      if (!isComp) return false;
    } else if (showCancelled) {
      if (!isCanc && !isUnresolved) return false;
    } else {
      if (isComp) return false;
      if (isCanc || isUnresolved) {
        if (!hasPendingBal || isUnresolved) return false;
      } else if (!['confirmed', 'preparing', 'procurement', 'procuring', 'on-going', 'approved', 'semi-approved', 'semi_approved', 'semi approved', 'pending'].includes(st)) {
        return false;
      }
    }

    // Apply active date filter if selected
    if (window._resdFilter && window._resdFilter.rangeMonths > 0) {
      const months = getAdminMonthRangeKeys(window._resdFilter);
      if (!filterResDate(r, months)) return false;
    }

    return true;
  });

  const q = (input.value || '').toLowerCase().trim();
  dropdown.style.display = 'block';

  const filtered = approved.filter(r => {
    if (!q) return true;
    const client = (r.client || '').toLowerCase();
    const pkg = (r.packageName || r.type || '').toLowerCase();
    const date = (r.date || '').toLowerCase();
    const id = (r.id || '').toLowerCase();
    return client.includes(q) || pkg.includes(q) || date.includes(q) || id.includes(q);
  });

  if (filtered.length === 0) {
    dropdown.innerHTML = '<div style="padding:14px; font-size:12px; color:var(--text-dim); text-align:center;">No matching reservations found</div>';
    return;
  }

  dropdown.innerHTML = filtered.map(r => {
    const hasWarn = !!_resdConstraintWarnings[r.id];
    const isCanc = String(r.status || '').toLowerCase() === 'cancelled';
    const isComp = String(r.status || '').toLowerCase() === 'completed';
    const isSemi = ['semi-approved', 'semi_approved', 'semi approved'].includes(String(r.status || '').toLowerCase());
    const isPending = String(r.status || '').toLowerCase() === 'pending';
    const statusEsc = isCanc ? '<span style="color:var(--red,#ef4444);font-size:11px;font-weight:700;margin-right:6px;">[CANCELLED]</span>' : (isComp ? '<span style="color:var(--green,#2d8a4e);font-size:11px;font-weight:700;margin-right:6px;">[COMPLETED]</span>' : (isSemi ? '<span style="color:var(--gold,#c49a3c);font-size:11px;font-weight:700;margin-right:6px;">[SEMI-APPROVED]</span>' : (isPending ? '<span style="color:var(--gold,#c49a3c);font-size:11px;font-weight:700;margin-right:6px;">[PENDING]</span>' : '')));
    const clientEsc = statusEsc + escHtml(r.client || 'Client');
    const pkgEsc = escHtml(r.packageName || 'Custom Package');
    const dateEsc = escHtml(r.date || 'TBD');
    const statusPrefix = isCanc ? '[CANCELLED] ' : (isComp ? '[COMPLETED] ' : (isSemi ? '[SEMI-APPROVED] ' : (isPending ? '[PENDING] ' : '')));
    const label = `${statusPrefix}${r.client} : ${r.packageName || 'Custom Package'} (${r.date})`;
    const labelEsc = (label || '').replace(/'/g, "\\'");
    const isSelected = activeResDetailId === r.id;

    return `
      <div class="resd-dropdown-item" onclick="window.selectResdApprovedItem('${r.id}', '${labelEsc}')"
        style="padding:10px 14px; font-size:13px; color:var(--cream); cursor:pointer; border-bottom:1px solid rgba(255,255,255,0.06); transition:background 0.2s; background:${isSelected ? 'rgba(196,154,60,0.15)' : 'transparent'};"
        onmouseover="this.style.background='rgba(196,154,60,0.2)'" onmouseout="this.style.background='${isSelected ? 'rgba(196,154,60,0.15)' : 'transparent'}'">
        <div style="display:flex; justify-content:space-between; align-items:center;">
          <div style="font-weight:700; color:var(--cream);">${hasWarn ? '⚠ ' : ''}${clientEsc}</div>
          <span style="font-size:11px; color:var(--gold); font-weight:600;">${dateEsc}</span>
        </div>
        <div style="font-size:11px; color:var(--text-dim); margin-top:2px;">${pkgEsc} &bull; ${r.pax || 0} pax</div>
      </div>
    `;
  }).join('');
};

