/**
 * filterResdApprovedSelector — filters the RDH active reservation dropdown
 * by the search text entered in the accompanying input.
 * Shows any option whose text contains all words typed (case-insensitive).
 */
window.filterResdApprovedSelector = function(searchVal) {
  const sel = document.getElementById('resd-approved-selector');
  if (!sel) return;
  const tokens = (searchVal || '').toLowerCase().trim().split(/\s+/).filter(Boolean);
  for (let i = 0; i < sel.options.length; i++) {
    const opt = sel.options[i];
    if (!opt.value) { opt.style.display = ''; continue; } // keep placeholder
    const text = opt.textContent.toLowerCase();
    // Show if ALL typed tokens are found in the option text
    const match = tokens.length === 0 || tokens.every(t => text.includes(t));
    opt.style.display = match ? '' : 'none';
  }
};
window.selectReservationDetail = selectReservationDetail;

