// Helper: get package origin for the active reservation detail
// Returns: 'custom' | 'dynamically set' | 'majorly set'
function getResdOrigin() {
  const res = RESERVATIONS.find(r => r.id === activeResDetailId);
  if (!res) return 'custom';

  // Priority 1: pricingMode : this is the original creation-time field, never corrupted by save code
  const mode = (res.pricingMode || res.pricing_mode || '').toLowerCase();
  if (mode === 'majorly_set' || mode === 'tiered') return 'majorly set';
  if (mode === 'per_head' || mode === 'dynamically_set' || mode === 'dynamically set') return 'dynamically set';

  // Priority 2: Stored packageOrigin (check but only trust non-custom values set correctly)
  const storedOrigin = (res.packageOrigin || res.package_origin || '').toLowerCase();
  if (storedOrigin === 'majorly set') return 'majorly set';
  if (storedOrigin === 'dynamically set') return 'dynamically set';

  // Priority 3: PKGS catalog lookup
  const matchedPkg = PKGS.find(p => p.name === res.packageName);
  if (matchedPkg) {
    if (matchedPkg.pricingMode === 'majorly_set' || matchedPkg.pricingMode === 'tiered') return 'majorly set';
    return 'dynamically set';
  }
  return 'custom';
}

let resdActiveCatFilter = null;
function renderResdCatalog() {
  const grid = document.getElementById('resd-catalog-grid');
  const catWrap = document.getElementById('resd-catalog-cats');
  if (!grid || !catWrap) return;

  const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(x => x.id === activeResDetailId || String(x.id) === String(activeResDetailId));
  const origin = getResdOrigin();
  const isPremade = origin === 'majorly set' || origin === 'dynamically set';
  const searchVal = (document.getElementById('resd-catalog-search')?.value || '').toLowerCase();
  const _resdPax = parseInt(document.getElementById('edit-ev-pax')?.value) || (typeof mtPax !== 'undefined' && mtPax > 0 ? mtPax : (parseInt(res && res.pax) || 50));

  const _catDefs = [
    { label: 'All Items',     value: null },
    { label: 'Food',          value: 'food' },
    { label: 'Desserts',      value: 'dessert' },
    { label: 'Drinks',        value: 'drink' },
    { label: 'Special Items', value: 'special' },
    { label: 'Decorations',   value: 'decoration' },
    { label: 'Equipment',     value: 'equipment' },
    { label: 'Add-ons',       value: 'entertainment' }
  ];
  catWrap.style.cssText = 'display:flex; flex-wrap:wrap; gap:8px; margin-bottom:6px;';
  catWrap.innerHTML = _catDefs.map(function(c) {
    const isActive = c.value === null ? !resdActiveCatFilter : resdActiveCatFilter === c.value;
    const borderCol = isActive ? 'var(--gold, #c49a3c)' : 'var(--border, #333)';
    const textCol = isActive ? 'var(--gold, #c49a3c)' : 'var(--text-dim, #aaa)';
    const arg = c.value === null ? 'null' : ("'" + c.value + "'");
    return '<button type="button" class="fb ' + (isActive ? 'active' : '') + '" style="padding:6px 14px; border:1px solid ' + borderCol + '; background:transparent; color:' + textCol + '; border-radius:6px; cursor:pointer; font-size:11px; font-weight:700; white-space:nowrap; transition:0.2s;" onclick="filterResdCat(' + arg + ')">' + c.label + '</button>';
  }).join('');

  // Combine CAT items with any custom/package items not in CAT so all added items appear
  const baseCat = Array.isArray(CAT) ? [...CAT].filter(function(i) { return !i.hidden && i.is_available !== false; }) : [];
  const mergedPool = [...baseCat];
  if (Array.isArray(mtCustomPkgItems)) {
    mtCustomPkgItems.forEach(function(pkgIt) {
      if (!pkgIt || pkgIt.name === 'Free Choices of Food From Menu') return;
      const inPool = mergedPool.some(function(c) {
        return (c.id && pkgIt.id && String(c.id) === String(pkgIt.id)) || (c.name && pkgIt.name && c.name.toLowerCase() === pkgIt.name.toLowerCase());
      });
      if (!inPool) {
        mergedPool.push({ ...pkgIt });
      }
    });
  }

  let items = mergedPool.filter(function(i) {
    if (i.name === 'Free Choices of Food From Menu') return false;
    const isAddedInPkg = Array.isArray(mtCustomPkgItems) && mtCustomPkgItems.some(function(p) {
      return (p.id && i.id && String(p.id) === String(i.id)) || (p.name && i.name && p.name.toLowerCase() === i.name.toLowerCase());
    });
    if (!isAddedInPkg && typeof window.isParentSpecialItemInPackage === 'function' && !window.isParentSpecialItemInPackage(i, mtCustomPkgItems)) {
      return false;
    }
    return true;
  });

  if (resdActiveCatFilter === 'special') {
    items = items.filter(function(i) { return window.isSpecialParentItem && window.isSpecialParentItem(i); });
  } else if (resdActiveCatFilter) {
    items = items.filter(function(i) { return (i.cat || i.category || '').toLowerCase() === resdActiveCatFilter.toLowerCase(); });
  }

  if (searchVal) {
    items = items.filter(function(i) {
      return (i.name || '').toLowerCase().includes(searchVal) || (i.desc || i.description || '').toLowerCase().includes(searchVal);
    });
  }

  // Sort: ALL added/included items at the TOP of the list!
  const catOrder = ['food', 'dessert', 'drink', 'decoration', 'equipment', 'entertainment', 'other'];
  items.sort(function(a, b) {
    const aAdded = mtCustomPkgItems.some(function(p) { return (p.id && a.id && String(p.id) === String(a.id)) || (p.name && a.name && p.name.toLowerCase() === a.name.toLowerCase()); }) ? 0 : 1;
    const bAdded = mtCustomPkgItems.some(function(p) { return (p.id && b.id && String(p.id) === String(b.id)) || (p.name && b.name && p.name.toLowerCase() === b.name.toLowerCase()); }) ? 0 : 1;
    if (aAdded !== bAdded) return aAdded - bAdded;

    const aSpec = (window.isSpecialParentItem && window.isSpecialParentItem(a)) ? 0 : 1;
    const bSpec = (window.isSpecialParentItem && window.isSpecialParentItem(b)) ? 0 : 1;
    if (aSpec !== bSpec) return aSpec - bSpec;

    const aCat = catOrder.indexOf((a.cat || a.category || 'other').toLowerCase());
    const bCat = catOrder.indexOf((b.cat || b.category || 'other').toLowerCase());
    if (aCat !== bCat) return (aCat === -1 ? 99 : aCat) - (bCat === -1 ? 99 : bCat);
    return (a.name || '').localeCompare(b.name || '');
  });

  const hasFreeChoiceGlobal = mtCustomPkgItems.some(function(i) { return i.name === 'Free Choices of Food From Menu'; });
  const _fcMsg = document.getElementById('resd-free-choice-msg');
  if (_fcMsg) _fcMsg.style.display = (isPremade && hasFreeChoiceGlobal) ? 'block' : 'none';

  if (!items.length) {
    grid.innerHTML = '<div style="grid-column:1/-1; padding:40px; text-align:center; color:var(--text-dim);">No items found.</div>';
    return;
  }

  grid.innerHTML = items.map(function(item) {
    const pkgIdx = mtCustomPkgItems.findIndex(function(i) {
      return (i.id && item.id && String(i.id) === String(item.id)) || (i.name && item.name && i.name.toLowerCase() === item.name.toLowerCase());
    });
    const matchedPkgItem = pkgIdx > -1 ? mtCustomPkgItems[pkgIdx] : null;
    const isAdded = !!matchedPkgItem;
    const isFreeChoiceApplied = !!(matchedPkgItem && matchedPkgItem.isFreeChoiceApplied);
    const catLower = (item.cat || item.category || 'other').toLowerCase();
    const isEq = catLower === 'equipment';
    const isSpecialParent = window.isSpecialParentItem ? window.isSpecialParentItem(item) : false;
    const connectedParent = typeof getSpecialParentName === 'function' ? getSpecialParentName(item) : null;
    const ident = (item.identify || (matchedPkgItem && matchedPkgItem.identify) || '').toLowerCase();
    const itemNameLow = String(item.name || '').toLowerCase();
    const isSubOpt = ident === 'mobile_bar_option' || ident === 'ice_cream_option' || (catLower === 'drink' && ident !== 'drinks_package' && ident !== 'mobile_bar' && (parseFloat(item.price) || 0) === 0);
    const isScalableFood = (catLower === 'food' || catLower === 'dessert' || catLower === 'desserts' || catLower === 'drink' || catLower === 'drinks' || isSpecialParent || catLower === 'special' || catLower === 'special items' || catLower === 'special_items' || itemNameLow.includes('unlimited drinks') || itemNameLow.includes('ice cream')) && !isSubOpt && !isEq;

    // Premade lock rules: Premade packages are locked (except Free Choice selection when available)
    const isEligibleFood = (catLower === 'food' || catLower === 'dessert') && !isSpecialParent;
    const canUseFreeChoice = isPremade && hasFreeChoiceGlobal && isEligibleFood && !isAdded;
    const isLockedPremade = isPremade && !canUseFreeChoice && !isFreeChoiceApplied;

    // Quantity & Price display
    let eqQty = 1;
    if (isEq) {
      if (matchedPkgItem && matchedPkgItem.customQty != null) {
        eqQty = parseInt(matchedPkgItem.customQty) || 1;
      } else if (matchedPkgItem && matchedPkgItem.autoQty != null) {
        eqQty = parseInt(matchedPkgItem.autoQty) || 1;
      } else {
        eqQty = typeof getEquipmentAllocatedQty === 'function' ? getEquipmentAllocatedQty(item, _resdPax, mtCustomPkgItems) : 1;
      }
    }

    let priceHtml = '';
    if (isPremade) {
      // Do NOT show prices on equipment or locked premade items
      if (isEq) {
        priceHtml = '<div style="font-size:11px;font-weight:700;color:var(--gold);margin-top:6px;">Quantity Allocated: ' + eqQty + ' pcs</div>';
      } else if (isAdded) {
        priceHtml = '<div style="font-size:11px;font-weight:700;color:var(--text-dim);margin-top:6px;text-transform:uppercase;">Included in Package</div>';
      }
    } else {
      // Custom package price display
      let dispP = 0;
      if (matchedPkgItem && matchedPkgItem.snapshotPrice != null && !matchedPkgItem.isFree) {
        dispP = Number(matchedPkgItem.snapshotPrice);
      } else if (isEq) {
        dispP = (parseFloat(item.price) || 0) * eqQty;
      } else if (typeof getDynamicPrice === 'function') {
        dispP = getDynamicPrice(item, _resdPax);
      } else {
        dispP = parseFloat(item.price) || 0;
      }
      const batchInfo = (!isEq && typeof getBatchInfo === 'function') ? getBatchInfo(item, (matchedPkgItem && matchedPkgItem.customPax) || _resdPax) : '';
      if (isSubOpt || (matchedPkgItem && matchedPkgItem.isFree)) {
        priceHtml = '<div style="font-size:11px;font-weight:700;color:var(--text-dim);margin-top:6px;text-transform:uppercase;">Included Option</div>';
      } else if (isEq) {
        priceHtml = '<div style="font-size:11px;font-weight:700;color:var(--gold);margin-top:6px;">Quantity Allocated: ' + eqQty + ' pcs</div>'
          + '<div style="font-size:13px;font-weight:800;color:var(--gold);margin-top:2px;">&#8369;' + Number(dispP).toLocaleString() + ' <span style="font-size:10px;color:var(--text-dim);font-weight:400;">(&#8369;' + Number(item.price || 0).toLocaleString() + '/pc)</span></div>';
      } else {
        const custPaxNote = (matchedPkgItem && matchedPkgItem.customPax) ? (' (Custom: ' + matchedPkgItem.customPax + ' pax)') : '';
        priceHtml = '<div style="font-size:13px;font-weight:800;color:var(--gold);margin-top:6px;">&#8369;' + Number(dispP).toLocaleString() + '<span style="font-size:10px;color:var(--text-dim);font-weight:500;">' + custPaxNote + (batchInfo ? ' ' + batchInfo : '') + '</span></div>';
      }
    }

    const cardBorder = isAdded ? '1.5px solid var(--gold, #c49a3c)' : '1px solid var(--border, rgba(255,255,255,0.08))';
    const subcatLbl = escHtml((item.subcategory || item.cat || 'ITEM').toUpperCase());
    const itemImg = item.image || item.image_url || 'haldens_logo.png';
    const imgHtml = '<div class="cat-thumb" style="width:100%; height:115px; border-radius:6px; overflow:hidden; margin-bottom:8px; background:#000;"><img src="' + itemImg + '" alt="' + escHtml(item.name) + '" loading="lazy" style="width:100%; height:100%; object-fit:cover;" onerror="this.onerror=null;this.src=\'haldens_logo.png\';"></div>';

    let badgeText = '';
    if (isAdded) {
      const isCust = matchedPkgItem && (matchedPkgItem.customPax != null || (matchedPkgItem.isCustomized && matchedPkgItem.customQty != null) || (matchedPkgItem.specifications && String(matchedPkgItem.specifications).trim()));
      badgeText = isCust ? 'ADDED · CUSTOMIZED' : 'IN PACKAGE';
    } else if (isSpecialParent) {
      badgeText = 'SPECIAL ITEM';
    } else if (connectedParent) {
      badgeText = escHtml(connectedParent.toUpperCase());
    }

    // Action button & inline customization area
    let actionAreaHtml = '';
    const safeIdOrName = escAttr(String(item.id || item.name).replace(/'/g, "\\'"));
    if (isPremade) {
      const btnText = isAdded
        ? (isFreeChoiceApplied ? 'Free Choice Selected (Click to Change)' : 'Locked - Included in Package')
        : (canUseFreeChoice ? '+ Select as Free Choice' : 'Locked - Premade Package');
      const btnDisabled = isLockedPremade;
      const btnOnClick = btnDisabled ? '' : ('onclick="event.stopPropagation(); ' + (isAdded ? ("removeResdItem('" + safeIdOrName + "')") : ("addResdItem('" + safeIdOrName + "')")) + '"');
      actionAreaHtml += '<button type="button" class="btn-add ' + (isAdded ? 'added' : '') + '" ' + (btnDisabled ? 'disabled' : btnOnClick) + ' style="width:100%; padding:8px 10px; border-radius:6px; border:1px solid ' + (isAdded ? 'var(--gold)' : 'var(--border)') + '; background:transparent; color:' + (isAdded ? 'var(--gold)' : 'var(--text-dim)') + '; cursor:' + (btnDisabled ? 'not-allowed' : 'pointer') + '; font-weight:700; font-size:11.5px; opacity:' + (btnDisabled ? '0.65' : '1') + ';">' + btnText + '</button>';

      // For Premade Packages: NO Customize buttons, ONLY a direct text input area for specifications/notes on included items
      if (isAdded && pkgIdx > -1) {
        const curSpecs = escAttr(matchedPkgItem.specifications || '');
        actionAreaHtml += '<div onclick="event.stopPropagation();" style="margin-top:8px; padding-top:8px; border-top:1px dashed var(--border);">'
          + '<label style="display:block; font-size:10px; font-weight:700; color:var(--text-dim); text-transform:uppercase; margin-bottom:4px;">Item Notes / Specifications</label>'
          + '<input type="text" class="input-field" value="' + curSpecs + '" placeholder="Add notes or instructions for this item..." oninput="updateAdminResdItemSpecs(' + pkgIdx + ', this.value)" style="width:100%; font-size:11.5px; padding:6px 8px; box-sizing:border-box;">'
          + '</div>';
      }
    } else {
      // Custom Package: Add / Added button + Customize button + inline customization drawer
      const btnText = isAdded ? 'Added (Click to Remove)' : '+ Add to Package';
      const btnOnClick = 'onclick="event.stopPropagation(); ' + (isAdded ? ("removeResdItem('" + safeIdOrName + "')") : ("addResdItem('" + safeIdOrName + "')")) + '"';
      actionAreaHtml += '<button type="button" class="btn-add ' + (isAdded ? 'added' : '') + '" ' + btnOnClick + ' style="width:100%; padding:8px 10px; border-radius:6px; border:1px solid ' + (isAdded ? 'var(--green)' : 'var(--gold)') + '; background:transparent; color:' + (isAdded ? 'var(--green)' : 'var(--gold)') + '; cursor:pointer; font-weight:700; font-size:11.5px;">' + btnText + '</button>';

      if (isAdded && pkgIdx > -1) {
        const custBtnLbl = isEq ? 'Customize Equipment' : (isScalableFood ? 'Customize Pax & Notes' : 'Customize Notes');
        const showBox = !!matchedPkgItem._showCustomize;
        const curSpecs = escAttr(matchedPkgItem.specifications || '');
        actionAreaHtml += '<button type="button" onclick="event.stopPropagation(); toggleAdminFoodCustomize(' + pkgIdx + ')" style="width:100%; margin-top:6px; padding:6px 10px; border-radius:6px; border:1px solid var(--gold); background:transparent; color:var(--gold); cursor:pointer; font-weight:700; font-size:11px;">' + (showBox ? 'Hide Customization' : custBtnLbl) + '</button>';

        if (showBox) {
          if (isEq) {
            actionAreaHtml += '<div class="item-custom-pax-box" onclick="event.stopPropagation();" style="margin-top:8px; padding:10px; border:1px solid var(--border); border-radius:8px; background:var(--bg3); font-size:11px;">'
              + '<div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;">'
              + '<span style="font-weight:700; color:var(--cream);">Allocated Qty (pcs)</span>'
              + '<button type="button" onclick="resetAdminResdItemCustomization(' + pkgIdx + ')" style="background:transparent; border:1px solid var(--border); color:var(--text-dim); font-size:10px; padding:2px 6px; border-radius:4px; cursor:pointer;">Reset</button>'
              + '</div>'
              + '<div style="display:flex; align-items:center; gap:6px; margin-bottom:8px;">'
              + '<button type="button" onclick="changeAdminResdEquipmentQty(' + pkgIdx + ', -1)" style="width:28px; height:28px; border:1px solid var(--border); background:var(--bg2); color:var(--text); border-radius:4px; cursor:pointer; font-weight:700;">-</button>'
              + '<input type="number" min="1" max="999" value="' + eqQty + '" onchange="setAdminResdEquipmentQty(' + pkgIdx + ', this.value)" style="flex:1; text-align:center; padding:4px 6px; background:var(--bg2); border:1px solid var(--border); border-radius:4px; color:var(--text); font-weight:700;">'
              + '<button type="button" onclick="changeAdminResdEquipmentQty(' + pkgIdx + ', 1)" style="width:28px; height:28px; border:1px solid var(--border); background:var(--bg2); color:var(--text); border-radius:4px; cursor:pointer; font-weight:700;">+</button>'
              + '</div>'
              + '<label style="display:block; font-size:10px; color:var(--text-dim); margin-bottom:3px;">Arrangement / Placement Notes:</label>'
              + '<input type="text" value="' + curSpecs + '" placeholder="Specify arrangement or notes..." oninput="updateAdminResdItemSpecs(' + pkgIdx + ', this.value)" style="width:100%; padding:5px 7px; font-size:11px; background:var(--bg2); border:1px solid var(--border); border-radius:4px; color:var(--text); box-sizing:border-box;">'
              + '</div>';
          } else if (isScalableFood) {
            const curCustPax = matchedPkgItem.customPax || _resdPax;
            actionAreaHtml += '<div class="item-custom-pax-box" onclick="event.stopPropagation();" style="margin-top:8px; padding:10px; border:1px solid var(--border); border-radius:8px; background:var(--bg3); font-size:11px;">'
              + '<div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;">'
              + '<span style="font-weight:700; color:var(--cream);">Portion Pax (Max: 999)</span>'
              + '<button type="button" onclick="resetAdminResdItemCustomization(' + pkgIdx + ')" style="background:transparent; border:1px solid var(--border); color:var(--text-dim); font-size:10px; padding:2px 6px; border-radius:4px; cursor:pointer;">Reset</button>'
              + '</div>'
              + '<input type="number" min="1" max="999" maxlength="3" value="' + curCustPax + '" onchange="updateAdminFoodPax(' + pkgIdx + ', this.value)" style="width:100%; margin-bottom:8px; padding:5px 7px; font-size:11px; background:var(--bg2); border:1px solid var(--border); border-radius:4px; color:var(--text); box-sizing:border-box;">'
              + '<label style="display:block; font-size:10px; color:var(--text-dim); margin-bottom:3px;">Flavor / Preparation Notes:</label>'
              + '<input type="text" value="' + curSpecs + '" placeholder="Specify flavor, dietary notes..." oninput="updateAdminResdItemSpecs(' + pkgIdx + ', this.value)" style="width:100%; padding:5px 7px; font-size:11px; background:var(--bg2); border:1px solid var(--border); border-radius:4px; color:var(--text); box-sizing:border-box;">'
              + '</div>';
          } else {
            actionAreaHtml += '<div class="item-custom-pax-box" onclick="event.stopPropagation();" style="margin-top:8px; padding:10px; border:1px solid var(--border); border-radius:8px; background:var(--bg3); font-size:11px;">'
              + '<div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:6px;">'
              + '<span style="font-weight:700; color:var(--cream);">Specifications / Notes</span>'
              + '<button type="button" onclick="resetAdminResdItemCustomization(' + pkgIdx + ')" style="background:transparent; border:1px solid var(--border); color:var(--text-dim); font-size:10px; padding:2px 6px; border-radius:4px; cursor:pointer;">Clear</button>'
              + '</div>'
              + '<input type="text" value="' + curSpecs + '" placeholder="Specify color, style, or notes..." oninput="updateAdminResdItemSpecs(' + pkgIdx + ', this.value)" style="width:100%; padding:5px 7px; font-size:11px; background:var(--bg2); border:1px solid var(--border); border-radius:4px; color:var(--text); box-sizing:border-box;">'
              + '</div>';
          }
        }
      }
    }

    return '<div class="cat-card" onclick="openDishModal(\'' + escAttr(String(item.id || item.name)) + '\')" style="padding:14px; border:' + cardBorder + '; background:var(--bg3); border-radius:10px; display:flex; flex-direction:column; gap:8px; cursor:pointer;">'
      + imgHtml
      + '<div class="cat-info" style="flex:1;">'
      + '<div style="display:flex; justify-content:space-between; align-items:center; gap:6px; margin-bottom:6px;">'
      + '<div class="cat-cat-lbl" style="margin:0; font-size:10px; color:var(--text-dim); text-transform:uppercase; font-weight:700; letter-spacing:0.8px;">' + subcatLbl + '</div>'
      + (badgeText ? '<div style="font-size:9.5px; font-weight:700; color:var(--gold); letter-spacing:0.5px;">' + badgeText + '</div>' : '')
      + '</div>'
      + '<div class="cat-n" style="font-size:13.5px; font-weight:700; color:var(--cream); line-height:1.3;">' + escHtml(item.name) + '</div>'
      + '<div class="cat-d" style="font-size:11px; color:var(--text-dim); margin-top:4px; line-height:1.4;">' + escHtml(item.desc || item.description || '') + '</div>'
      + priceHtml
      + '</div>'
      + '<div style="margin-top:auto;">' + actionAreaHtml + '</div>'
      + '</div>';
  }).join('');
}

function filterResdCat(cat) { resdActiveCatFilter = cat; renderResdCatalog(); }
function onResdCatalogSearch(val) { renderResdCatalog(); }

async function addResdItem(idOrName) {
  const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(r => r.id === activeResDetailId || String(r.id) === String(activeResDetailId));
  if (res && res.is_locked) {
    showToast('Reservation is locked because equipment allocations have been assigned.', 'warning');
    return;
  }

  const item = CAT.find(it => String(it.id) === String(idOrName) || it.name === idOrName);
  if (!item) return;
  const name = item.name;

  const origin = getResdOrigin();
  const isPremade = origin === 'majorly set' || origin === 'dynamically set';
  const catLower = (item.cat || item.category || '').toLowerCase();
  const hasFreeChoice = mtCustomPkgItems.some(i => i.name === 'Free Choices of Food From Menu');
  const isFoodOrDessert = catLower === 'food' || catLower === 'dessert';

  if (isPremade && !(hasFreeChoice && isFoodOrDessert && !window.isSpecialParentItem(item))) {
    showToast('Items in a premade package are locked and cannot be added or removed.', 'warning');
    return;
  }

  // Sub-item check
  const parentKey = window.getSpecialParentKey ? window.getSpecialParentKey(item) : null;
  if (parentKey) {
    const isParentInPkg = window.isParentSpecialItemInPackage(item, mtCustomPkgItems);
    if (!isParentInPkg) {
      alert("Please add the parent special item to the package before selecting its options.");
      return;
    }

    const currentChildItems = mtCustomPkgItems.filter(c => {
      const cKey = window.getSpecialParentKey(c);
      if (!cKey) return false;
      return cKey === parentKey ||
        (parentKey === 'ice_cream' && cKey === 'ice_cream') ||
        (parentKey === 'mobile_bar' && cKey === 'mobile_bar') ||
        (parentKey === 'drinks_package' && cKey === 'drinks_package');
    });

    if (currentChildItems.length >= 3) {
      alert("You can only select up to 3 included options for this special item.");
      return;
    }
  }

  // Dessert limit check (3 regular dessert items max)
  if (catLower === 'dessert' && !window.isSpecialParentItem(item) && item.identify !== 'ice_cream_option') {
    const currentDesserts = mtCustomPkgItems.filter(i => (i.cat || i.category || '').toLowerCase() === 'dessert' && !window.isSpecialParentItem(i) && i.identify !== 'ice_cream_option');
    if (currentDesserts.length >= 3) {
      alert("You are only allowed to have up to 3 regular dessert items in the package.");
      return;
    }
  }

  if (isPremade) {
    const placeholderIdx = mtCustomPkgItems.findIndex(i => i.name === 'Free Choices of Food From Menu');
    if (placeholderIdx > -1) {
      mtCustomPkgItems.splice(placeholderIdx, 1);
      mtCustomPkgItems.push({ ...item, isFree: true, isFreeChoiceApplied: true, snapshotPrice: 0, specifications: '' });
    }
  } else {
    if (mtCustomPkgItems.find(i => i.name.toLowerCase() === name.toLowerCase())) return;
    const isEq = (item.cat || '').toLowerCase() === 'equipment';
    const curPax = parseInt(document.getElementById('edit-ev-pax')?.value) || (typeof mtPax !== 'undefined' && mtPax > 0 ? mtPax : (parseInt(res?.pax) || 50));
    let autoQ = 1;
    if (isEq && typeof getEquipmentAllocatedQty === 'function') {
      autoQ = getEquipmentAllocatedQty(item, curPax, mtCustomPkgItems);
    }
    const ident = (item.identify || '').toLowerCase();
    const isSubOpt = ident === 'mobile_bar_option' || ident === 'ice_cream_option' || (catLower === 'drink' && ident !== 'drinks_package' && ident !== 'mobile_bar' && (parseFloat(item.price) || 0) === 0);
    let dynamicP = isSubOpt ? 0 : (isEq ? ((parseFloat(item.price) || 0) * autoQ) : ((typeof getDynamicPrice === 'function') ? getDynamicPrice(item, curPax) : (parseFloat(item.price) || 0)));

    const newItemObj = {
      ...item,
      snapshotPrice: dynamicP,
      customQty: isEq ? autoQ : null,
      autoQty: isEq ? autoQ : null,
      customPax: null,
      specifications: '',
      isCustomized: false,
      isFree: isSubOpt,
      _showCustomize: false
    };

    // Target Budget enforcement
    const budgetVal = parseFloat(document.getElementById('edit-ev-budget')?.value) || 0;
    if (budgetVal > 0 && res) {
      mtCustomPkgItems.push(newItemObj);
      const testPricing = computePricingDetails(res, curPax);
      if (testPricing && testPricing.finalTotal > budgetVal) {
        mtCustomPkgItems.pop();
        alert('Adding "' + name + '" would exceed the Target Budget of ₱' + budgetVal.toLocaleString() + '.');
        return;
      }
    } else {
      mtCustomPkgItems.push(newItemObj);
    }

    // Auto-select default child item for special parent item
    if (typeof window.isSpecialParentItem === 'function' && window.isSpecialParentItem(item)) {
      const pIdent = (item.identify || '').toLowerCase();
      const pName = (item.name || '').toLowerCase();
      const childPool = (typeof CAT !== 'undefined' ? CAT : []).filter(c => {
        if (window.isSpecialParentItem(c)) return false;
        const pk = window.getSpecialParentKey ? window.getSpecialParentKey(c) : null;
        if (pIdent === 'drinks_package' || pName.includes('unlimited drinks')) return pk === 'drinks_package' || (c.cat === 'drink' && !window.isSpecialParentItem(c));
        if (pIdent === 'mobile_bar' || pName.includes('mobile bar')) return pk === 'mobile_bar' || (c.identify && c.identify.includes('mobile_bar'));
        if (pIdent === 'ice_cream' || pName.includes('ice cream')) return pk === 'ice_cream' || (c.identify && c.identify.includes('ice_cream'));
        return pk === item.id || pk === item.name || pk === pIdent;
      });

      if (childPool.length > 0) {
        let defaultChild = null;
        if (pIdent === 'drinks_package' || pName.includes('unlimited drinks')) {
          defaultChild = childPool.find(c => c.name.toLowerCase().includes('water')) || childPool[0];
        } else {
          defaultChild = childPool[0];
        }

        if (defaultChild && !mtCustomPkgItems.some(c => String(c.id) === String(defaultChild.id) || (c.name && c.name.toLowerCase() === defaultChild.name.toLowerCase()))) {
          mtCustomPkgItems.push({
            ...defaultChild,
            id: defaultChild.id,
            name: defaultChild.name,
            cat: defaultChild.cat || 'drink',
            price: 0,
            snapshotPrice: 0,
            image: defaultChild.image || defaultChild.image_url || 'haldens_logo.png',
            desc: defaultChild.desc || '',
            specifications: '',
            isFree: true,
            isAutoAdded: true,
            _showCustomize: false
          });
        }
      }
    }
  }

  window.refreshAdminModifyPricingUI();
  renderResdCatalog();
}

async function removeResdItem(idOrName) {
  const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(r => r.id === activeResDetailId || String(r.id) === String(activeResDetailId));
  if (res && res.is_locked) {
    showToast('Reservation is locked because equipment allocations have been assigned.', 'warning');
    return;
  }

  const catItem = CAT.find(it => String(it.id) === String(idOrName) || it.name === idOrName);
  const name = catItem ? catItem.name : idOrName;
  const origin = getResdOrigin();
  const isPremade = origin === 'majorly set' || origin === 'dynamically set';

  const item = mtCustomPkgItems.find(i => String(i.id) === String(idOrName) || (i.name && i.name.toLowerCase() === String(name).toLowerCase()));
  if (!item) return;

  if (isPremade && !item.isFreeChoiceApplied) {
    showToast('Items in a premade package are locked and cannot be removed.', 'warning');
    return;
  }

  if (item.isFreeChoiceApplied) {
    const placeholder = CAT.find(i => i.name === 'Free Choices of Food From Menu') || { id: 'free_choice_placeholder', name: 'Free Choices of Food From Menu', cat: 'food', price: 0 };
    mtCustomPkgItems.push({ ...placeholder, isFree: true, snapshotPrice: 0 });
  }

  if (catItem && window.isSpecialParentItem && window.isSpecialParentItem(catItem)) {
    mtCustomPkgItems = window.removeChildItemsForSpecialParent(catItem.name || catItem.identify, mtCustomPkgItems)
      .filter(i => String(i.id) !== String(catItem.id) && i.name.toLowerCase() !== catItem.name.toLowerCase());
  } else {
    mtCustomPkgItems = mtCustomPkgItems.filter(i => String(i.id) !== String(idOrName) && (i.name || '').toLowerCase() !== String(name).toLowerCase());
  }

  try { window.logResdActivity(activeResDetailId, 'Removed Package Item', `Removed "${name}" from the reservation package (not yet saved)`); } catch (_logErr) {}
  window.refreshAdminModifyPricingUI();
  renderResdCatalog();
}

async function renderProcurementTab() {
  const res = RESERVATIONS.find(r => r.id === activeResDetailId);
  if (!res) return;

  // Initialize UI loading
  ['food', 'equipment', 'decoration', 'personnel'].forEach(cat => {
    const list = document.getElementById(`proc-${cat}-list`);
    if (list) list.innerHTML = '<div style="font-size:12px; color:var(--text-dim); padding:20px; text-align:center;">Loading items...</div>';
  });

  // 1. Fetch procurement status from Firebase
  const procData = await fetchProcurementData(res.id);

  // 2. Map items from res.packageItems using CAT
  const itemNames = (res.packageItems || []).map(ri => (typeof ri === 'string' ? ri : (ri && ri.name ? ri.name : '')));
  const items = itemNames.map(name => CAT.find(c => c.name === name)).filter(Boolean);
  const pax = parseInt(res.pax) || 0;

  // Render all columns, capturing costs
  const foodResult = renderProcFood(res, items, pax, procData);
  renderProcEquip(items, procData);
  renderProcDecor(res, items);
  const personnelResult = renderProcPersonnel(items, procData) || { personnelCost: 0 };
  renderProcStaff(res, procData);

  // Consolidate analytics : ingredientCost set by renderProcFood internally via renderProcAnalytics
  // We re-call now with all data
  const supplierGroups = {};
  let ingredientCost = 0;
  let nonSupplierCount = 0;
  items.filter(i => i.cat === 'food').forEach(dish => {
    const ings = getIngredientsForDish(dish.name, pax);
    ings.forEach(ing => {
      ingredientCost += ing.totalCost;
      if (ing.supplier) {
        if (!supplierGroups[ing.supplier]) supplierGroups[ing.supplier] = true;
      } else {
        nonSupplierCount++;
      }
    });
  });

  renderProcAnalytics(res, items);
  loadTransportationDrivers(res);

  // Update Column Colors (Sorted Status)
  updateProcColumnStatus(procData);
}


// In-memory procurement state (synced with Supabase reservation_exec_sorted)
const _procDataCache = {};

// Master Evaluator and Synchronizer for Resource Preparation and public.reservation_exec_sorted
async function evaluateAndSyncReservationExecSorted(resId) {
  if (!resId) return null;
  const sb = window.supabaseClient;
  const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(r => r.id === resId || String(r.id) === String(resId));
  if (!res) return null;

  // 1. Fetch current row from reservation_exec_sorted if it exists
  let existingSorted = null;
  if (sb) {
    try {
      const { data } = await sb.from('reservation_exec_sorted').select('*').eq('reservation_id', resId).maybeSingle();
      if (data) existingSorted = data;
    } catch(e) {
      console.warn('[evaluateAndSyncReservationExecSorted] Fetch notice:', e);
    }
  }

  // 2. Evaluate each condition according to requirements:

  // (1) FOOD: all items in dishes & ingredients have their price placed (even without receipt)
  let sortedFood = existingSorted ? !!existingSorted.sorted_food : false;
  try {
    let expenseData = window._currentDishesExpenseData;
    if (!expenseData || !expenseData.expenses || String(window._currentDishesResId || activeResDetailId) !== String(resId)) {
      try {
        const localSaved = JSON.parse(localStorage.getItem(`ss_ing_expenses_${resId}`) || '{}');
        if (localSaved && localSaved.expenses) expenseData = localSaved;
      } catch(e){}
    }
    if (sb && (!expenseData || !expenseData.expenses || Object.keys(expenseData.expenses).length === 0)) {
      try {
        const { data: dbExp } = await sb.from('reservation_ingredient_expenses').select('*').eq('reservation_id', resId).maybeSingle();
        if (dbExp && dbExp.expenses) expenseData = dbExp;
      } catch(e){}
    }
    if (!expenseData || !expenseData.expenses || Object.keys(expenseData.expenses).length === 0) {
      const ep = res.executionPlan || res.execution_plan;
      if (ep && ep.dishes_expenses && ep.dishes_expenses.expenses) {
        expenseData = ep.dishes_expenses;
      }
    }

    const isSpecialItem = (i) => {
      if (!i) return false;
      if (typeof window.isSpecialParentItem === 'function' && window.isSpecialParentItem(i)) return true;
      if (typeof window.getSpecialParentKey === 'function' && window.getSpecialParentKey(i)) return true;
      const cat = (i.cat || i.category || '').toLowerCase();
      if (cat === 'special') return true;
      const ident = (i.identify || '').toLowerCase();
      if (ident === 'mobile_bar' || ident === 'drinks_package' || ident === 'ice_cream' || ident === 'special') return true;
      const name = (i.name || '').toLowerCase();
      if (name.includes('mobile bar') || name.includes('unlimited drinks') || name.includes('ice cream machine')) return true;
      return false;
    };

    const isSpecialIngredient = (ingName) => {
      if (!ingName) return true;
      const n = ingName.toLowerCase().trim();
      if (n.startsWith('per_') || n.includes('sub_items:') || n.includes('pax:') || n.includes('options:')) return true;
      if (n === 'mobile bar' || n === 'unlimited drinks' || n === 'ice cream bar') return true;
      return false;
    };

    const itemNames = (res.packageItems || []).map(ri => (typeof ri === 'string' ? ri : (ri && ri.name ? ri.name : '')));
    const catPool = (Array.isArray(window.sbMenuItems) && window.sbMenuItems.length > 0) ? window.sbMenuItems : (typeof CAT !== 'undefined' ? CAT : []);
    const items = itemNames.map(n => catPool.find(c => c.name === n)).filter(Boolean);
    const consumableItems = items.filter(i => ['food', 'dessert', 'drink', 'drinks'].includes((i.cat || i.category || '').toLowerCase()) && !isSpecialItem(i));

    const allIngMap = {};
    consumableItems.forEach(dish => {
      const rawIngs = Array.isArray(dish.ingredients)
        ? dish.ingredients
        : (typeof dish.ingredients === 'string' ? dish.ingredients.split(',').map(s => s.trim()) : []);
      rawIngs.forEach(ing => {
        if (typeof ing !== 'string' || !ing.trim()) return;
        if (isSpecialIngredient(ing)) return;
        const k = ing.toLowerCase().trim();
        if (!allIngMap[k]) allIngMap[k] = true;
      });
    });
    const allKeys = Object.keys(allIngMap);

    if (expenseData && expenseData.is_sorted) {
      sortedFood = true;
    } else if (allKeys.length > 0 && expenseData && expenseData.expenses) {
      const filledCount = allKeys.filter(k => {
        const val = expenseData.expenses[k];
        return val !== undefined && val !== null && val !== '' && !isNaN(Number(val)) && Number(val) > 0;
      }).length;
      if (filledCount === allKeys.length) {
        sortedFood = true;
      }
    } else if (expenseData && expenseData.expenses && Object.keys(expenseData.expenses).length > 0) {
      const expKeys = Object.keys(expenseData.expenses);
      const allPriced = expKeys.length > 0 && expKeys.every(k => Number(expenseData.expenses[k]) > 0);
      if (allPriced) {
        sortedFood = true;
      }
    }
  } catch(e) {
    console.warn('[evaluateAndSyncReservationExecSorted] Food eval notice:', e);
  }

  // (2) EQUIPMENT: batch allocation made through deployment manifest (can only be unmarked if batch allocation deleted)
  let sortedEquipment = existingSorted ? !!existingSorted.sorted_equipment : false;
  try {
    if (sb) {
      const { data: allocRows, error: aErr } = await sb.from('allocation_history')
        .select('id, is_rental, equipment_name')
        .eq('reservation_id', resId);
      if (!aErr && allocRows) {
        sortedEquipment = allocRows.some(a => !a.is_rental);
      }
    }
  } catch(e) {
    console.warn('[evaluateAndSyncReservationExecSorted] Equip eval notice:', e);
  }

  // (3) DECORATION: decoration equipment allocation is done in equipment cycle area
  let sortedDecoration = existingSorted ? !!existingSorted.sorted_decoration : false;
  try {
    if (sb) {
      const { data: allocRows, error: aErr } = await sb.from('allocation_history')
        .select('id, equipment_name')
        .eq('reservation_id', resId);
      if (!aErr && allocRows) {
        const hasDecoAlloc = allocRows.some(a => {
          const name = (a.equipment_name || '').toLowerCase();
          return name.includes('standee') || name.includes('stylist') || name.includes('entrance') || name.includes('decor') || name.includes('backdrop') || name.includes('props') || name.includes('flower') || name.includes('lighting');
        });
        if (hasDecoAlloc) sortedDecoration = true;
      }
    }
    const itemNames = (res.packageItems || []).map(ri => (typeof ri === 'string' ? ri : (ri && ri.name ? ri.name : '')));
    const hasDecorInPkg = itemNames.some(name => {
      const c = (typeof CAT !== 'undefined' ? CAT : []).find(item => item.name === name);
      return c && c.cat === 'decoration';
    });
    if (sortedEquipment && !hasDecorInPkg) {
      sortedDecoration = true;
    }
  } catch(e) {
    console.warn('[evaluateAndSyncReservationExecSorted] Decor eval notice:', e);
  }

  // (4) PERSONNEL: all addons have a personnel assigned and selected as confirmed
  let sortedPersonnel = existingSorted ? !!existingSorted.sorted_personnel : false;
  try {
    const itemNames = (res.packageItems || []).map(ri => (typeof ri === 'string' ? ri : (ri && ri.name ? ri.name : '')));
    const personnelItems = itemNames.map(name => (typeof CAT !== 'undefined' ? CAT : []).find(c => c.name === name))
      .filter(entry => entry && (entry.cat === 'entertainment' || entry.cat === 'photography'));

    if (personnelItems.length === 0) {
      sortedPersonnel = true;
    } else {
      let hp = res.hired_personnel || res.hiredPersonnel;
      if (!hp && sb) {
        try {
          const { data: rRow } = await sb.from('reservations').select('hired_personnel').eq('id', resId).maybeSingle();
          if (rRow && rRow.hired_personnel) hp = rRow.hired_personnel;
        } catch(e){}
      }
      if (typeof hp === 'string') {
        try { hp = JSON.parse(hp); } catch(e){ hp = {}; }
      }
      hp = hp || {};

      const allConfirmed = personnelItems.every(item => {
        const assigned = hp[item.id] || hp[item.name];
        return assigned && (assigned.email || assigned.name) && (assigned.status === 'confirmed' || assigned.status === 'completed');
      });
      sortedPersonnel = allConfirmed;
    }
  } catch(e) {
    console.warn('[evaluateAndSyncReservationExecSorted] Personnel eval notice:', e);
  }

  // (5) STAFF ALLOCATION: 2 or more staff are assigned for that reservation
  let sortedStaff = existingSorted ? !!existingSorted.sorted_staff_allocation : false;
  try {
    if (sb) {
      const { data: staffData, error: sErr } = await sb.from('reservation_staff_assignments')
        .select('staff_id')
        .eq('reservation_id', resId);
      if (!sErr && staffData) {
        sortedStaff = staffData.length >= 2;
      }
    }
    if (!sortedStaff && res.staffing && Array.isArray(res.staffing.assignments)) {
      sortedStaff = res.staffing.assignments.length >= 2;
    }
    if (!sortedStaff && window.assignedStaffSet && window.assignedStaffSet.size >= 2 && activeResDetailId === resId) {
      sortedStaff = true;
    }
  } catch(e) {
    console.warn('[evaluateAndSyncReservationExecSorted] Staff eval notice:', e);
  }

  // (6) TRANSPORTATION: driver selected in dropdown box
  let sortedTrans = existingSorted ? !!existingSorted.sorted_transportation : false;
  try {
    const driverId = res.transportation_driver_id || res.transportationDriverId || res.driverId;
    if (driverId && String(driverId).trim() !== '') {
      sortedTrans = true;
    } else {
      const selCol = document.getElementById('proc-trans-driver-select');
      if (selCol && selCol.value && String(selCol.value).trim() !== '' && activeResDetailId === resId) {
        sortedTrans = true;
      } else {
        sortedTrans = false;
      }
    }
  } catch(e) {
    console.warn('[evaluateAndSyncReservationExecSorted] Trans eval notice:', e);
  }

  // 3. Persist to Supabase reservation_exec_sorted
  const updatedSorted = {
    food:             sortedFood,
    equipment:        sortedEquipment,
    decoration:       sortedDecoration,
    personnel:        sortedPersonnel,
    staff_allocation: sortedStaff,
    transportation:   sortedTrans
  };

  if (sb) {
    try {
      const payload = {
        reservation_id:          resId,
        sorted_food:             updatedSorted.food,
        sorted_equipment:        updatedSorted.equipment,
        sorted_decoration:       updatedSorted.decoration,
        sorted_personnel:        updatedSorted.personnel,
        sorted_staff_allocation: updatedSorted.staff_allocation,
        sorted_transportation:   updatedSorted.transportation,
        updated_at:              new Date().toISOString()
      };
      await sb.from('reservation_exec_sorted').upsert(payload, { onConflict: 'reservation_id' });
    } catch(e) {
      console.warn('[evaluateAndSyncReservationExecSorted] Supabase upsert error:', e);
    }
  }

  // 4. Update memory caches and globals
  if (!_procDataCache[resId]) {
    _procDataCache[resId] = { id: resId, sorted: {}, assignments: {}, poStatuses: {} };
  }
  _procDataCache[resId].sorted = { ...updatedSorted };

  if (typeof execDayProcSorted !== 'undefined') {
    execDayProcSorted.food = updatedSorted.food;
    execDayProcSorted.equipment = updatedSorted.equipment;
    execDayProcSorted.decoration = updatedSorted.decoration;
    execDayProcSorted.personnel = updatedSorted.personnel;
    execDayProcSorted.staff_allocation = updatedSorted.staff_allocation;
    execDayProcSorted.transportation = updatedSorted.transportation;
  }

  return updatedSorted;
}
window.evaluateAndSyncReservationExecSorted = evaluateAndSyncReservationExecSorted;

async function fetchProcurementData(resId) {
  const defaultData = {
    id: resId,
    sorted: { food: false, equipment: false, decoration: false, personnel: false, staff_allocation: false, transportation: false },
    assignments: {},
    poStatuses: {}
  };
  
  try {
    const sorted = await evaluateAndSyncReservationExecSorted(resId);
    if (sorted) {
      defaultData.sorted = { ...sorted };
    }
  } catch (e) {
    console.warn('[fetchProcurementData] Error:', e);
  }

  _procDataCache[resId] = defaultData;
  return defaultData;
}


// Shared Supabase fetch for all package items : called once, used by both food and decor
async function fetchMenuItemsForPackage(res) {
  const itemNames = (res.packageItems || []).map(ri =>
    typeof ri === 'string' ? ri : (ri && ri.name ? ri.name : '')
  ).filter(Boolean);
  if (!itemNames.length) return [];
  const { data, error } = await window.supabaseClient
    .from('menu_items')
    .select('name, ingredients, identify, description, category')
    .in('name', itemNames);
  if (error) throw error;
  return data || [];
}

function renderProcFood(res, items, pax, procData) {
  const list = document.getElementById('proc-food-list');
  if (!list) return { ingredientCost: 0 };

  // Use the already-resolved CAT items : these are confirmed to be in the package
  const targetCats = ['food', 'dessert', 'drink'];
  const excludedItems = ['Unlimited Drinks', 'Free Choices of Food From Menu'];
  const foodItems = items.filter(i => targetCats.includes(i.cat) && !excludedItems.includes(i.name));

  if (!foodItems.length) {
    list.innerHTML = '<div style="font-size:11px; color:var(--text-dim); font-style:italic;">No food, dessert, or drink items in package.</div>';
    return { ingredientCost: 0 };
  }

  // Render placeholders immediately so the user sees the items right away
  let html = '';
  foodItems.forEach((dish, idx) => {
    html += `
      <div class="proc-item-card" id="proc-food-card-${idx}" style="margin-bottom: 12px; padding: 12px; background: rgba(0,0,0,0.1); border: 1px solid var(--border); border-left: 3px solid var(--gold); border-radius: 6px;">
        <div style="font-size:13px; font-weight:700; color:var(--gold); margin-bottom:8px;">${escHtml(dish.name)}</div>
        <div class="proc-ing-body" style="display:flex; flex-direction:column; gap:6px;">
          <div style="font-size:11px; color:var(--text-dim); font-style:italic; padding-left:10px;">Loading ingredients...</div>
        </div>
      </div>
    `;
  });
  list.innerHTML = html;

  // Now async-enrich each card with real ingredients from Supabase
  setTimeout(async () => {
    try {
      if (!window.supabaseClient) return;

      const names = foodItems.map(i => i.name);
      const { data: menuRows, error } = await window.supabaseClient
        .from('menu_items')
        .select('name, ingredients')
        .in('name', names);

      if (error) throw error;

      // Build lookup map: name -> ingredients string
      const ingMap = {};
      (menuRows || []).forEach(row => { ingMap[row.name] = row.ingredients || ''; });

      foodItems.forEach((dish, idx) => {
        const card = list.querySelector(`#proc-food-card-${idx} .proc-ing-body`);
        if (!card) return;
        const rawIngs = (ingMap[dish.name] || '').split(',').map(s => s.trim()).filter(Boolean);
        if (!rawIngs.length) {
          card.innerHTML = `<div style="font-size:11px; color:var(--text-dim); font-style:italic; padding-left:10px;">No ingredients listed.</div>`;
        } else {
          card.innerHTML = rawIngs.map(ing => `
            <div style="display:flex; align-items:center; gap:6px; padding-left:10px;">
              <span style="color:var(--gold); font-size:14px; line-height:1;">•</span>
              <div style="font-size:12px; color:var(--cream);">${escHtml(ing)}</div>
            </div>
          `).join('');
        }
      });
    } catch (e) {
      console.error('Failed to load food ingredients from Supabase:', e);
    }
  }, 0);

  return { ingredientCost: 0 };
}



async function updatePoStatus(supplier, newStatus) {
  const res = RESERVATIONS.find(r => r.id === activeResDetailId);
  if (!res) return;

  try {
    const { updateDoc, doc } = window.firebaseFns;
    await updateDoc(doc(window.firebaseDB, 'procurement', res.id), {
      [`poStatuses.${supplier}`]: newStatus
    });
    // Optional: Log action
    console.log(`PO status updated for ${supplier}: ${newStatus}`);
  } catch (e) {
    console.error(e);
    alert('Failed to update PO status.');
  }
}

function renderProcAnalytics(res, items) {
  const container = document.getElementById('proc-analytics-container');
  if (!container) return;

  const foodCount = (items || []).filter(i => ['food', 'dessert', 'drink'].includes(i.cat)).length;
  const equipCount = (items || []).filter(i => i.cat === 'equipment').length;
  const decorCount = (items || []).filter(i => i.cat === 'decoration').length;
  // Fallback for addons using known CAT categories for personnel/addons
  const catAddonCount = (items || []).filter(i => ['other', 'others', 'addon', 'add-on', 'entertainment'].includes((i.cat || '').toLowerCase())).length;

  // Days Left Countdown Calculation
  let daysLeftTxt = ':';
  const rawDate = (res && res.date) || (res && res.eventDate) || '';
  const normDateStr = (typeof normalizeDateKey === 'function') ? normalizeDateKey(rawDate) : rawDate;
  if (normDateStr) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const eventDateObj = new Date(normDateStr.includes('T') ? normDateStr : normDateStr + 'T00:00:00');
    if (!isNaN(eventDateObj.getTime())) {
      eventDateObj.setHours(0, 0, 0, 0);
      const diffTime = eventDateObj - today;
      const daysLeft = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      daysLeftTxt = daysLeft < 0 ? 'Passed' : daysLeft === 0 ? 'Today!' : `${daysLeft} Day${daysLeft === 1 ? '' : 's'}`;
    }
  }


  container.innerHTML = `
    <div class="proc-analytics-bar" style="grid-template-columns: repeat(6, 1fr);">
      <div class="proc-stat-box proc-solid-gold" style="border-color: #c49a3c !important; background: #c49a3c !important; color: #ffffff !important;">
        <div class="proc-stat-val" style="font-size:17px; color: #ffffff !important;">₱${Math.round(Number(String(res.amount || 0).replace(/[^0-9.]/g, ''))).toLocaleString()}</div>
        <div class="proc-stat-lbl" style="color: #ffffff !important;">Reservation Total</div>
      </div>
      <div class="proc-stat-box">
        <div class="proc-stat-val" id="proc-stat-food">${foodCount}</div>
        <div class="proc-stat-lbl">Total Food Items</div>
      </div>
      <div class="proc-stat-box">
        <div class="proc-stat-val" id="proc-stat-equip">${equipCount}</div>
        <div class="proc-stat-lbl">Total Equipment Needed</div>
      </div>
      <div class="proc-stat-box">
        <div class="proc-stat-val" id="proc-stat-decor">${decorCount}</div>
        <div class="proc-stat-lbl">Total Decorations Selected</div>
      </div>
      <div class="proc-stat-box">
        <div class="proc-stat-val" id="proc-stat-addon">...</div>
        <div class="proc-stat-lbl">Total Add-ons</div>
      </div>
      <div class="proc-stat-box proc-solid-red" style="border-color: #dc2626 !important; background: #dc2626 !important; color: #ffffff !important;">
        <div class="proc-stat-val" style="font-size:18px; color: #ffffff !important; font-weight:800;">${daysLeftTxt}</div>
        <div class="proc-stat-lbl" style="color: #ffffff !important;">Days Left (Execution)</div>
      </div>
    </div>
  `;

  setTimeout(async () => {
    try {
      if (!window.supabaseClient) {
        const addonEl = document.getElementById('proc-stat-addon');
        if (addonEl) addonEl.innerText = catAddonCount;
        return;
      }

      const allItems = await fetchMenuItemsForPackage(res);
      let addonCount = 0;

      allItems.forEach(i => {
        if ((i.identify || '').toLowerCase() === 'addon') {
          addonCount++;
        }
      });

      // Use whichever is higher to ensure we don't miss anything
      if (addonCount < catAddonCount) addonCount = catAddonCount;

      const addonEl = document.getElementById('proc-stat-addon');
      if (addonEl) addonEl.innerText = addonCount;

    } catch (e) {
      console.error('Failed to calculate analytics counts:', e);
      const addonEl = document.getElementById('proc-stat-addon');
      if (addonEl) addonEl.innerText = catAddonCount;
    }
  }, 0);
}

