let _transDrivers = [];
let ptrGpsMap = null;
let _transCalculatedData = null;

async function loadTransportationDrivers(res) {
  const selCol = document.getElementById('proc-trans-driver-select');
  const selMod = document.getElementById('ptr-driver-select');

  const defaultDrivers = [
    { id: 'd1', full_name: 'Rodrigo "Rody" Dalisay', contact_number: '+63 917 555 1024', rate: 2500, description: 'Senior Logistics Driver - 10-Wheeler & Cold Chain' },
    { id: 'd2', full_name: 'Marco Antonio Santos', contact_number: '+63 920 888 4192', rate: 2000, description: 'Catering Van Driver - Fragile Decor Specialist' },
    { id: 'd3', full_name: 'Juan Carlo Reyes', contact_number: '+63 918 333 7711', rate: 1800, description: 'Express Delivery & Light Equipment Driver' },
    { id: 'd4', full_name: 'Ernesto "Ka Erning" Cruz', contact_number: '+63 929 444 9900', rate: 2200, description: 'Heavy Equipment Transporter & Mobile Kitchen Rig Driver' }
  ];

  const sb = window.supabaseClient || window.supabase;
  try {
    if (sb) {
      const { data, error } = await sb.from('personnel').select('*');
      if (!error && data && data.length > 0) {
        const transOnly = data.filter(p => {
          const st = String(p.service_type || '').toLowerCase();
          return st.includes('trans') || st.includes('driver') || st.includes('logistics');
        });
        _transDrivers = transOnly.length > 0 ? transOnly : data;
      } else {
        _transDrivers = defaultDrivers;
      }
    } else {
      _transDrivers = defaultDrivers;
    }
  } catch (e) {
    console.error('Error fetching transportation drivers:', e);
    _transDrivers = defaultDrivers;
  }

  const savedDriverId = (res && (res.transportation_driver_id || res.transportationDriverId || res.driverId)) || '';

  const optsHtml = '<option value="">-- Select Driver --</option>' +
    _transDrivers.map(d => `<option value="${d.id}" ${d.id === savedDriverId ? 'selected' : ''}>${escHtml(d.full_name || 'Driver')} (₱${(d.rate || 0).toLocaleString()})</option>`).join('') +
    `<option value="Lalamove" ${savedDriverId === 'Lalamove' ? 'selected' : ''}>Lalamove</option>`;

  if (selCol) selCol.innerHTML = optsHtml;
  if (selMod) selMod.innerHTML = optsHtml;

  if (savedDriverId && res && _procDataCache[res.id]) {
    _procDataCache[res.id].sorted.transportation = true;
  }

  renderDriverInfoCard(savedDriverId);
}

async function saveTransDriver(driverId) {
  const res = RESERVATIONS.find(r => r.id === activeResDetailId);
  if (res) {
    res.transportationDriverId = driverId;
    res.transportation_driver_id = driverId;

    // Save to Firebase
    try {
      if (window.firebaseFns && window.firebaseDB) {
        const { updateDoc, doc } = window.firebaseFns;
        await updateDoc(doc(window.firebaseDB, "reservations", res.id), {
          transportationDriverId: driverId
        });
      }
    } catch (e) { console.error("Firebase transportation driver update error:", e); }

    // Save to Supabase
    try {
      if (window.supabaseClient) {
        await window.supabaseClient.from('reservations').update({
          transportation_driver_id: driverId
        }).eq('id', res.id);
      }
    } catch (e) { console.error("Supabase transportation driver update error:", e); }

    // Auto-sync transportation sorted status
    if (typeof setProcSorted === 'function') {
      await setProcSorted(res.id, 'transportation', !!(driverId && String(driverId).trim() !== ''));
    }
  }
  const selCol = document.getElementById('proc-trans-driver-select');
  const selMod = document.getElementById('ptr-driver-select');
  if (selCol) selCol.value = driverId;
  if (selMod) selMod.value = driverId;

  renderDriverInfoCard(driverId);

  // Comprehensive Admin Activity Logging for transportation driver assignment
  try {
    if (typeof window.logAdminActivity === 'function') {
      const dObj = (window.ALL_DRIVERS || []).find(d => d.id === driverId);
      const dName = dObj ? (dObj.name || dObj.full_name) : (driverId || 'None');
      window.logAdminActivity(
        'Assigned Transportation',
        driverId ? `Assigned driver ${dName} to reservation #${res?.id || ''} (${res?.client || 'Client'}).` : `Unassigned driver from reservation #${res?.id || ''} (${res?.client || 'Client'}).`,
        { category: 'Reservations', reservation_id: res?.id, client_name: res?.client, driver_id: driverId }
      );
    }
  } catch (_logErr) {
    console.warn('Logging saveTransDriver failed:', _logErr);
  }
}

function renderDriverInfoCard(driverId) {
  const infoEl = document.getElementById('ptr-driver-info');
  if (!infoEl) return;
  const d = _transDrivers.find(x => x.id === driverId);
  if (!d) {
    infoEl.innerHTML = '<div style="font-size:11px; color:var(--text-dim);">No driver selected.</div>';
    return;
  }
  infoEl.innerHTML = `
    <div style="font-size:13px; font-weight:700; color:var(--gold);">${escHtml(d.full_name)}</div>
    <div style="font-size:11px; color:var(--text-dim); margin-top:2px;">Phone: ${escHtml(d.contact_number || 'N/A')}</div>
    <div style="font-size:11px; color:var(--text-dim);">Rate: ₱${(d.rate || 0).toLocaleString()} / event</div>
    <div style="font-size:10px; color:var(--text-mid); margin-top:4px;">${escHtml(d.description || '')}</div>
  `;
}

function openTransportationPanel() {
  const res = RESERVATIONS.find(r => r.id === activeResDetailId);
  if (!res) { alert('Please select a reservation first.'); return; }
  const panel = document.getElementById('proc-trans-detail-panel');
  if (panel) { panel.style.display = 'flex'; }

  const subEl = document.getElementById('ptr-sub');
  if (subEl) subEl.textContent = `${res.client || 'Client'} : ${res.date} (${res.venue || 'Venue Address'})`;

  const addrEl = document.getElementById('ptr-venue-addr');
  if (addrEl) addrEl.textContent = res.venue || res.venueAddress || res.location || '18 Basilio St, Manila, Metro Manila';

  loadTransportationDrivers(res);
}

function closeTransportationPanel() {
  const panel = document.getElementById('proc-trans-detail-panel');
  if (panel) { panel.style.display = 'none'; }
}

function calculateTransportationRoute() {
  const res = RESERVATIONS.find(r => r.id === activeResDetailId);
  const statusEl = document.getElementById('ptr-map-status');
  const placeholder = document.getElementById('ptr-map-placeholder');

  if (statusEl) statusEl.textContent = 'Requesting GPS Location...';
  if (placeholder) placeholder.innerHTML = '<i class="fas fa-spinner fa-spin" style="font-size:32px; color:var(--gold);"></i><div style="margin-top:8px;">Acquiring device GPS position & calculating route...</div>';

  const venueAddr = (res && (res.venue || res.venueAddress)) || '18 Basilio St, Manila';

  if (navigator.geolocation) {
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const startCoords = [pos.coords.latitude, pos.coords.longitude];
        renderGpsRouteMap(startCoords, venueAddr, "My Current GPS Location");
      },
      (err) => {
        console.warn("Geolocation permission denied/error. Falling back to HQ coords:", err);
        const fallbackHQ = [14.6138, 120.9948];
        renderGpsRouteMap(fallbackHQ, venueAddr, "Halden Catering HQ (Manila)");
      },
      { timeout: 8000, enableHighAccuracy: true }
    );
  } else {
    const fallbackHQ = [14.6138, 120.9948];
    renderGpsRouteMap(fallbackHQ, venueAddr, "Halden Catering HQ (Manila)");
  }
}

async function renderGpsRouteMap(startCoords, venueAddress, startLabel) {
  const statusEl = document.getElementById('ptr-map-status');
  const placeholder = document.getElementById('ptr-map-placeholder');
  if (placeholder) placeholder.style.display = 'none';

  if (ptrGpsMap) { ptrGpsMap.remove(); ptrGpsMap = null; }

  try {
    let endCoords = null;
    try {
      const resp = await fetch(`https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(venueAddress)}`);
      const data = await resp.json();
      if (data && data.length > 0) endCoords = [parseFloat(data[0].lat), parseFloat(data[0].lon)];
    } catch (e) { }

    if (!endCoords) {
      endCoords = [14.5547, 121.0244];
    }

    const map = L.map('ptr-gps-map').setView(startCoords, 13);
    ptrGpsMap = map;

    L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}', {
      maxZoom: 19,
      attribution: '© OpenStreetMap'
    }).addTo(map);

    // Custom pins
    const startPin = L.circleMarker(startCoords, { radius: 10, fillColor: '#3b82f6', color: '#ffffff', weight: 3, fillOpacity: 0.95 }).addTo(map);
    startPin.bindPopup(`<b>Start Point</b><br>${startLabel}`).openPopup();

    const endPin = L.circleMarker(endCoords, { radius: 10, fillColor: '#ef4444', color: '#ffffff', weight: 3, fillOpacity: 0.95 }).addTo(map);
    endPin.bindPopup(`<b>Destination Venue</b><br>${venueAddress}`);

    // Call OSRM Driving Routing API for real street route (like Waze / Grab)
    let routeWaypoints = [startCoords, endCoords];
    let distanceKm = '3.9';
    let drivingMins = 12;

    try {
      const osrmUrl = `https://router.project-osrm.org/route/v1/driving/${startCoords[1]},${startCoords[0]};${endCoords[1]},${endCoords[0]}?overview=full&geometries=geojson`;
      const osrmResp = await fetch(osrmUrl);
      const osrmData = await osrmResp.json();

      if (osrmData && osrmData.code === 'Ok' && osrmData.routes && osrmData.routes.length > 0) {
        const route = osrmData.routes[0];
        // Convert [lon, lat] back to [lat, lon]
        routeWaypoints = route.geometry.coordinates.map(c => [c[1], c[0]]);
        distanceKm = (route.distance / 1000).toFixed(1);
        drivingMins = Math.round(route.duration / 60);
      }
    } catch (routeErr) {
      console.warn("OSRM routing API fallback:", routeErr);
    }

    // Render vivid navigation route line (Waze style glowing path with casing)
    L.polyline(routeWaypoints, { color: '#000000', weight: 8, opacity: 0.5 }).addTo(map);
    const routePoly = L.polyline(routeWaypoints, { color: '#38bdf8', weight: 5, opacity: 0.95 }).addTo(map);

    map.fitBounds(routePoly.getBounds(), { padding: [50, 50] });

    const bufferMinutes = 10;
    const totalTravelTime = drivingMins + bufferMinutes;
    const numericKm = parseFloat(distanceKm) || 4;
    let lateRiskPct = Math.min(75, Math.max(4, Math.round((numericKm / 30) * 18 + (drivingMins > 35 ? 12 : 0))));

    _transCalculatedData = {
      startLabel,
      startCoords,
      endCoords,
      venueAddress,
      distanceKm,
      drivingMins,
      bufferMinutes,
      totalTravelTime,
      lateRiskPct
    };

    document.getElementById('ptr-metric-distance').textContent = `${distanceKm} km`;
    document.getElementById('ptr-metric-duration').textContent = `${totalTravelTime} mins`;
    document.getElementById('ptr-metric-risk').textContent = `${lateRiskPct}%`;

    if (statusEl) statusEl.textContent = `Route Active: ${distanceKm} km · ${totalTravelTime} mins est.`;

  } catch (e) {
    console.error("GPS Route calculation error:", e);
    if (statusEl) statusEl.textContent = 'Calculation completed with estimation.';
  }
}

function exportTransportationPDF() {
  const res = RESERVATIONS.find(r => r.id === activeResDetailId);
  const selMod = document.getElementById('ptr-driver-select');
  const driverId = selMod ? selMod.value : '';
  const d = _transDrivers.find(x => x.id === driverId) || { full_name: 'Unassigned', contact_number: 'N/A', rate: 0 };

  const calc = _transCalculatedData || {
    distanceKm: '14.2',
    totalTravelTime: '42',
    bufferMinutes: '10',
    lateRiskPct: '12%',
    venueAddress: res ? res.venue : 'Manila Venue'
  };

  const pw = window.open('', '_blank');
  if (!pw) return alert('Please allow pop-ups to export PDF.');

  pw.document.write(`<!DOCTYPE html><html><head><title>HAL'SERVE - Transportation & GPS Route Dispatch</title>`
    + `<style>body{font-family:Arial,sans-serif;padding:30px;color:#111;line-height:1.6;}`
    + `h1{font-size:20px;color:#c49a3c;margin-bottom:4px;border-bottom:2px solid #c49a3c;padding-bottom:6px;}`
    + `.box{border:1px solid #ddd;border-radius:8px;padding:16px;margin-bottom:16px;background:#fafafa;}`
    + `.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;}`
    + `.metric-box{text-align:center;border:1px solid #ccc;border-radius:8px;padding:12px;background:#fff;}`
    + `.metric-val{font-size:22px;font-weight:bold;color:#c49a3c;}`
    + `.footer{margin-top:30px;font-size:11px;color:#777;text-align:center;border-top:1px solid #eee;padding-top:10px;}</style>`
    + `</head><body>`
    + `<h1>HAL'SERVE - Transportation & GPS Logistics Manifest</h1>`
    + `<p><b>Reservation Ref:</b> ${res ? res.id : 'N/A'} &nbsp;|&nbsp; <b>Client:</b> ${res ? res.client : 'N/A'} &nbsp;|&nbsp; <b>Event Date:</b> ${res ? res.date : 'N/A'}</p>`
    + `<div class="box">`
    + `<h3>Driver & Vehicle Dispatch Info</h3>`
    + `<p><b>Assigned Driver:</b> ${d.full_name}</p>`
    + `<p><b>Contact Number:</b> ${d.contact_number}</p>`
    + `<p><b>Driver Rate:</b> ₱${(d.rate || 0).toLocaleString()} per event</p>`
    + `<p><b>Specialization:</b> ${d.description || 'General Delivery'}</p>`
    + `</div>`
    + `<div class="box">`
    + `<h3>Route & Destination Info</h3>`
    + `<p><b>Starting Origin:</b> ${calc.startLabel || 'HAL\'SERVE Logistics HQ (Manila)'}</p>`
    + `<p><b>Destination Venue:</b> ${calc.venueAddress || (res ? res.venue : 'N/A')}</p>`
    + `</div>`
    + `<div class="grid">`
    + `<div class="metric-box"><div class="metric-val">${calc.distanceKm} km</div><div>Calculated Distance</div></div>`
    + `<div class="metric-box"><div class="metric-val">${calc.totalTravelTime} mins</div><div>Travel Time (+10m Buffer)</div></div>`
    + `<div class="metric-box" style="grid-column:span 2;"><div class="metric-val" style="color:#d97706;">${calc.lateRiskPct}%</div><div>Estimated Risk of Being Late</div></div>`
    + `</div>`
    + `<div class="footer">Document generated automatically by HAL'SERVE System. Authorized for Driver Dispatch.</div>`
    + `<script>window.onload=function(){window.print();};<\/script>`
    + `</body></html>`);
  pw.document.close();
}

