function renderProcStaff(res, procData) {
  const list = document.getElementById('proc-staff-list');
  if (!list) return;

  list.innerHTML = '<div style="font-size:11px; color:var(--text-dim); font-style:italic;"><i class="fas fa-circle-notch fa-spin"></i> Loading staff...</div>';

  setTimeout(async () => {
    try {
      if (!window.supabaseClient) {
        list.innerHTML = '<div style="font-size:11px; color:var(--text-dim); font-style:italic;">Supabase not available.</div>';
        return;
      }

      // Fetch all Available staff from users table
      const { data: userRows } = await window.supabaseClient
        .from('users')
        .select('id, name, role, availability')
        ;

      const allActiveStaff = (userRows || []).filter(r => (r.role || '').toLowerCase().trim() === 'staff' && !(r.name||'').toLowerCase().includes('lalamove'));

      // Fetch assignments for this reservation
      const { data: assignments } = await window.supabaseClient
        .from('reservation_staff_assignments')
        .select('staff_id')
        .eq('reservation_id', res.id);

      const assignedIds = new Set((assignments || []).map(a => a.staff_id));

      if (!allActiveStaff.length) {
        list.innerHTML = '<div style="font-size:11px; color:var(--text-dim); font-style:italic;">No active staff found.</div>';
        return;
      }

      const rows = allActiveStaff.map(s => {
        const isAssigned = assignedIds.has(s.id);
        return `
          <div style="display:flex; align-items:center; gap:8px; padding:7px 10px; border-radius:8px;
            background:${isAssigned ? 'rgba(46,160,67,0.1)' : 'rgba(255,255,255,0.02)'};
            border:1px solid ${isAssigned ? 'rgba(46,160,67,0.35)' : 'var(--border)'};
            margin-bottom:6px; cursor:pointer;"
            onclick="switchResDetailsTab('staff', document.getElementById('resd-tab-staff'))">
            <div style="width:7px; height:7px; border-radius:50%; flex-shrink:0;
              background:${isAssigned ? 'var(--green)' : 'rgba(196,154,60,0.4)'};" ></div>
            <div style="flex:1; min-width:0;">
              <div style="font-size:12px; font-weight:${isAssigned ? '700' : '500'};
                color:${isAssigned ? 'var(--cream)' : 'var(--text-dim)'};
                white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">
                ${escHtml(s.name)}
              </div>
            </div>
          </div>`;
      }).join('');

      const assignedCount = assignedIds.size;
      const isStaffSorted = assignedCount >= 2;
      if (typeof setProcSorted === 'function') {
        setProcSorted(res.id, 'staff_allocation', isStaffSorted);
      }
      list.innerHTML = `
        <div style="margin-bottom:10px; padding:8px 10px; background:rgba(196,154,60,0.08);
          border:1px solid rgba(196,154,60,0.25); border-radius:8px; text-align:center;">
          <div style="font-size:18px; font-weight:800; color:var(--gold);">${assignedCount}</div>
          <div style="font-size:10px; color:var(--text-dim); text-transform:uppercase; letter-spacing:0.5px;">Assigned</div>
        </div>
        <div style="font-size:10px; font-weight:700; color:var(--text-dim); text-transform:uppercase;
          letter-spacing:0.8px; margin-bottom:8px;">All Active Staff</div>
        ${rows}
        <div style="margin-top:10px;">
          <button class="btn-primary" style="width:100%; font-size:11px; padding:8px;"
            onclick="switchResDetailsTab('staff', document.getElementById('resd-tab-staff'))">
            Manage Assignments
          </button>
        </div>`;
    } catch (e) {
      console.error('renderProcStaff error:', e);
      list.innerHTML = '<div style="font-size:11px; color:var(--red); font-style:italic;">Failed to load staff.</div>';
    }
  }, 0);
}
