function updateProcColumnStatus(procData) {
  const sorted = procData.sorted || {};
  ['food', 'equipment', 'decoration', 'personnel', 'staff_allocation', 'transportation'].forEach(cat => {
    const col = document.getElementById(`proc-col-${cat}`);
    const btn = document.getElementById(`btn-sort-${cat}`);
    if (col) {
      if (sorted[cat]) {
        col.classList.add('sorted');
        col.style.borderColor = 'var(--green, #2ea043)';
        col.style.boxShadow = '0 0 12px rgba(46,160,67,0.3)';
        if (btn) {
          btn.textContent = 'Column Sorted';
          btn.style.background = 'transparent';
          btn.style.color = 'var(--green, #2ea043)';
          btn.style.border = 'none';
        }
      } else {
        col.classList.remove('sorted');
        col.style.borderColor = '';
        col.style.boxShadow = '';
        if (btn) {
          btn.textContent = 'Mark Column Sorted';
          btn.style.background = 'var(--red, #c0392b)';
          btn.style.color = '#fff';
        }
      }
    }
  });
}

async function toggleProcSorted(cat) {
  const res = RESERVATIONS.find(r => r.id === activeResDetailId);
  if (!res) return;

  try {
    const col = document.getElementById(`proc-col-${cat}`);
    const isCurrentlySorted = col ? col.classList.contains('sorted') : (_procDataCache[res.id]?.sorted[cat] || false);

    // Requirement 9: When a column is marked sorted, it cannot be unsorted easily if its automated condition is met.
    if (isCurrentlySorted) {
      if (cat === 'food') {
        const ingData = window._currentDishesExpenseData;
        const allKeys = window._currentDishesAllIngKeys || [];
        const filled = allKeys.filter(k => ingData && ingData.expenses && Number(ingData.expenses[k]) > 0).length;
        if (allKeys.length > 0 && filled === allKeys.length) {
          if (typeof showToast === 'function') showToast('Dishes & Ingredients is marked sorted because all ingredient expenses have prices placed. Clear prices in Dishes panel to unmark.', 'warning');
          return;
        }
      } else if (cat === 'equipment') {
        const sb = window.supabaseClient;
        if (sb) {
          const { data } = await sb.from('allocation_history').select('id').eq('reservation_id', res.id).eq('is_rental', false);
          if (data && data.length > 0) {
            if (typeof showToast === 'function') showToast('Event Equipment is sorted because a batch allocation is currently deployed. Delete the batch allocation via Deployment Manifest to unmark.', 'warning');
            return;
          }
        }
      } else if (cat === 'decoration') {
        const sb = window.supabaseClient;
        if (sb) {
          const { data } = await sb.from('allocation_history').select('id, equipment_name').eq('reservation_id', res.id);
          const hasDec = data && data.some(a => (a.equipment_name || '').toLowerCase().match(/standee|stylist|entrance|decor|backdrop/));
          if (hasDec) {
            if (typeof showToast === 'function') showToast('Aesthetic & Decor is sorted because decoration equipment is allocated.', 'warning');
            return;
          }
        }
      } else if (cat === 'personnel') {
        const hp = res.hired_personnel || res.hiredPersonnel || {};
        const hpKeys = Object.keys(hp);
        if (hpKeys.length > 0 && hpKeys.every(k => hp[k] && (hp[k].status === 'confirmed' || hp[k].status === 'completed'))) {
          if (typeof showToast === 'function') showToast('Talent & Personnel is sorted because all addon roles have confirmed staff assigned.', 'warning');
          return;
        }
      } else if (cat === 'staff_allocation') {
        const sb = window.supabaseClient;
        if (sb) {
          const { data } = await sb.from('reservation_staff_assignments').select('staff_id').eq('reservation_id', res.id);
          if (data && data.length >= 2) {
            if (typeof showToast === 'function') showToast('Staff Allocation is sorted because 2 or more staff are assigned. Update assignments in Staff Allocation tab to change.', 'warning');
            return;
          }
        }
      } else if (cat === 'transportation') {
        if (res.transportation_driver_id || res.transportationDriverId || res.driverId) {
          if (typeof showToast === 'function') showToast('Transportation is sorted because a driver is selected. Click Cancel Driver to unmark.', 'warning');
          return;
        }
      }
    }

    const targetState = !isCurrentlySorted;
    await setProcSorted(res.id, cat, targetState);
    if (typeof showToast === 'function') showToast(`Column marked as ${targetState ? 'SORTED' : 'UNSORTED'}.`, targetState ? 'success' : 'info');
  } catch (e) {
    console.error('[toggleProcSorted] Error:', e);
    alert('Error updating status.');
  }
}

// ─── SHARED HELPER: auto-set a procurement sorted column ──────────────────────
// Called by automation triggers (saveAllocAssignment, saveDecorationAllocation,
// updatePersonnelStatus, saveStaffRoles, saveTransDriver). Writes to Supabase and updates
// the in-memory cache + DOM if the user is on the Resource Preparation tab.
async function setProcSorted(resId, cat, value) {
  if (!resId) return;
  try {
    // Update in-memory cache
    if (!_procDataCache[resId]) {
      _procDataCache[resId] = { id: resId, sorted: {}, assignments: {}, poStatuses: {} };
    }
    if (!_procDataCache[resId].sorted) _procDataCache[resId].sorted = {};
    _procDataCache[resId].sorted[cat] = value;

    if (typeof execDayProcSorted !== 'undefined') {
      execDayProcSorted[cat] = value;
    }

    // Refresh DOM column status if procurement tab visible
    if (resDetailsActiveTab === 'procurement') {
      updateProcColumnStatus(_procDataCache[resId]);
    }

    // Automatically sync logistics timeline tasks with this column sorted state
    if (typeof syncResourcePlanningTasksFromSorted === 'function') {
      syncResourcePlanningTasksFromSorted(resId, _procDataCache[resId].sorted);
    }

    // Persist full state to Supabase reservation_exec_sorted
    const sb = window.supabaseClient;
    if (!sb) return;
    const curr = _procDataCache[resId].sorted || {};
    const payload = {
      reservation_id:          String(resId),
      sorted_food:             curr.food !== undefined ? !!curr.food : false,
      sorted_equipment:        curr.equipment !== undefined ? !!curr.equipment : false,
      sorted_decoration:       curr.decoration !== undefined ? !!curr.decoration : false,
      sorted_personnel:        curr.personnel !== undefined ? !!curr.personnel : false,
      sorted_staff_allocation: curr.staff_allocation !== undefined ? !!curr.staff_allocation : false,
      sorted_transportation:   curr.transportation !== undefined ? !!curr.transportation : false,
      updated_at:              new Date().toISOString()
    };
    const validCats = ['food', 'equipment', 'decoration', 'personnel', 'staff_allocation', 'transportation'];
    if (validCats.includes(cat)) {
      payload[`sorted_${cat}`] = !!value;
    }

    await sb.from('reservation_exec_sorted')
      .upsert(payload, { onConflict: 'reservation_id' });
  } catch (e) {
    console.warn('[setProcSorted] Error:', e);
  }
}
window.setProcSorted = setProcSorted;
// ──────────────────────────────────────────────────────────────────────────────

async function assignPersonnel(itemId, email) {
  const res = RESERVATIONS.find(r => r.id === activeResDetailId);
  if (!res) return;

  const item = CAT.find(i => i.id === itemId);
  if (item && (item.cat === 'entertainment' || item.cat === 'photography')) {
    if (!res.hiredPersonnel) res.hiredPersonnel = {};
    if (email) {
      let personName = email;
      if (window.supabaseClient) {
        try {
          const { data } = await window.supabaseClient.from('personnel').select('full_name').eq('email', email).maybeSingle();
          if (data) personName = data.full_name || email;
        } catch(e){}
      }
      res.hiredPersonnel[itemId] = {
        email: email,
        name: personName,
        status: 'pending', // Starts at pending
        hiredAt: new Date().toISOString()
      };
    } else {
      delete res.hiredPersonnel[itemId];
    }
  }

  try {
    const { updateDoc, doc } = window.firebaseFns;
    await updateDoc(doc(window.firebaseDB, 'procurement', res.id), {
      [`assignments.${itemId}`]: email
    });
    await updateDoc(doc(window.firebaseDB, "reservations", res.id), {
      hiredPersonnel: res.hiredPersonnel || {}
    });
  } catch (e) { console.error("Failed to assign personnel:", e); }

  if (resDetailsActiveTab === 'personnel') renderPersonnelTab(true);
}

