// =====================================================================
// EXPORT INGREDIENTS SHOPPING LIST AS PDF / PRINT
// Detailed comment:
// This function generates a printable Ingredients Shopping List.
// As requested, each ingredient row has a clear line under it, and there is
// a dedicated 'Expenses' column displaying recorded costs (or a blank line to write expenses).
// =====================================================================
function exportIngredientsPDF() {
  const res = RESERVATIONS.find(r => r.id === activeResDetailId);
  if (!res) return;
  const pax = parseInt(res.pax) || 0;

  // Use cache set by renderDishesPanel: array of { dish, ingredients[] }
  const cache = window._dishPanelIngCache || [];

  // Retrieve saved expenses mapping from state
  const savedExpenses = (window._currentDishesExpenseData && window._currentDishesExpenseData.expenses) || {};
  let totalExpensesSum = 0;

  let content = `<div style="max-width:800px;margin:0 auto;font-family:'Inter',sans-serif;color:#222;">
    <h1 style="color:#c49a3c;margin-bottom:6px;font-size:24px;letter-spacing:-0.5px;">INGREDIENTS SHOPPING LIST</h1>
    <p style="color:#555;margin-bottom:6px;font-size:13px;">Event: <strong>${escHtml(res.client)}</strong> &nbsp;|&nbsp; Guests: ${pax} pax &nbsp;|&nbsp; Date: ${escHtml(res.date)}</p>
    <hr style="border:none;border-top:2px solid #222;margin-bottom:24px;"/>
  `;

  if (!cache.length) {
    content += `<p style="color:#999;text-align:center;padding:40px 0;">No ingredients found.</p>`;
  } else {
    cache.forEach(({ dish, ingredients }) => {
      content += `<div style="margin-bottom:26px;">
        <h3 style="margin-bottom:8px;border-left:4px solid #c49a3c;padding-left:10px;font-size:15px;color:#111;">${escHtml(dish)}</h3>
        <table style="width:100%;border-collapse:collapse;">
          <thead>
            <tr style="border-bottom:2px solid #444;font-size:12px;text-transform:uppercase;color:#555;">
              <th style="padding:8px 8px;width:36px;text-align:center;"></th>
              <th style="padding:8px 10px;text-align:left;">Ingredient</th>
              <th style="padding:8px 10px;text-align:right;width:150px;">Expenses</th>
            </tr>
          </thead>
          <tbody>`;
      ingredients.forEach(ing => {
        const k = (ing || '').toLowerCase().trim();
        const expVal = savedExpenses[k];
        let expText = '₱ ____________';
        if (expVal !== undefined && expVal !== null && expVal !== '' && !isNaN(Number(expVal)) && Number(expVal) > 0) {
          const num = Number(expVal);
          totalExpensesSum += num;
          expText = `<strong>₱${num.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</strong>`;
        }
        content += `<tr style="border-bottom:1px solid #bbb;font-size:14px;">
            <td style="padding:9px 8px;width:36px;text-align:center;"><input type="checkbox"/></td>
            <td style="padding:9px 10px;color:#222;">${escHtml(ing)}</td>
            <td style="padding:9px 10px;text-align:right;color:#111;font-family:monospace,sans-serif;">${expText}</td>
          </tr>`;
      });
      content += `</tbody></table></div>`;
    });

    if (totalExpensesSum > 0) {
      content += `
        <div style="margin-top:20px;padding:14px 18px;background:#f9f9f9;border:1px solid #ddd;border-radius:8px;display:flex;justify-content:space-between;align-items:center;">
          <span style="font-weight:700;font-size:14px;color:#333;text-transform:uppercase;">Total Recorded Expenses:</span>
          <span style="font-weight:800;font-size:18px;color:#c49a3c;">₱${totalExpensesSum.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</span>
        </div>
      `;
    }
  }

  content += `<p style="color:#888;font-size:11px;margin-top:28px;border-top:1px solid #eee;padding-top:10px;">Generated by SmartServe &mdash; ${new Date().toLocaleString()}</p></div>`;

  const printWindow = window.open('', '_blank');
  printWindow.document.write(`<html><head><meta charset="UTF-8"><title>Ingredients - ${escHtml(res.client)}</title><style>body{padding:40px;background:#fff;color:#222;font-family:system-ui,-apple-system,sans-serif;} input[type=checkbox]{width:16px;height:16px;} @media print{input[type=checkbox]{-webkit-print-color-adjust:exact;}}</style></head><body>${content}</body></html>`);
  printWindow.document.close();
  setTimeout(() => printWindow.print(), 400);
}

