function exportVenueLayoutPDF(targetResId) {
  const targetId = targetResId || activeResDetailId || activeExecDayResId;
  const res = RESERVATIONS.find(r => r.id === targetId);
  const extra = typeof getActiveReservationExtra === 'function' ? getActiveReservationExtra(targetId) : null;
  let elements = (extra && extra.seatingElements && extra.seatingElements.length > 0) ? extra.seatingElements : [];
  if (!elements.length && res && res.seatingLayout) {
    try {
      elements = Array.isArray(res.seatingLayout) ? res.seatingLayout : JSON.parse(res.seatingLayout);
    } catch(e) {}
  }
  if (!elements.length && window.seatingElements && (!targetResId || targetResId === activeResDetailId)) {
    elements = window.seatingElements;
  }

  const pw = window.open('', '_blank');
  if (!pw) return alert('Please allow pop-ups to export the Venue Layout PDF.');

  const resName = res ? (res.packageName || res.client || res.name || res.id) : 'Reservation';
  const clientName = res ? (res.client || res.name || 'N/A') : 'N/A';
  const eventDate = res ? (res.date || res.eventDate || 'N/A') : 'N/A';
  const venue = res ? (res.venue || 'N/A') : 'N/A';

  const tables = elements.filter(e => e.type && e.type.includes('table'));
  const chairs = elements.filter(e => e.type && e.type.includes('chair'));
  const vipTables = tables.filter(t => t.vip || t.isVip);

  // Compute exact bounding box of all elements to prevent clipping/cut-off
  let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
  elements.forEach(el => {
    const x = Number(el.x) || 0;
    const y = Number(el.y) || 0;
    let rx = 35, ry = 35;
    if (el.type === 'table-round') { rx = 55; ry = 55; }
    else if (el.type && el.type.includes('table')) { rx = 75; ry = 50; }
    else if (el.type === 'chair') { rx = 25; ry = 45; } // includes guest text label below
    minX = Math.min(minX, x - rx);
    maxX = Math.max(maxX, x + rx);
    minY = Math.min(minY, y - ry);
    maxY = Math.max(maxY, y + ry);
  });
  if (!isFinite(minX) || elements.length === 0) {
    minX = 0; minY = 0; maxX = 800; maxY = 550;
  }
  const padding = 50;
  const boxX = Math.round(minX - padding);
  const boxY = Math.round(minY - padding);
  const boxW = Math.max(300, Math.round((maxX - minX) + padding * 2));
  const boxH = Math.max(200, Math.round((maxY - minY) + padding * 2));

  const tableLabels = typeof getTableLabels === 'function' ? getTableLabels(elements) : {};
  if (tables.length > 0) {
    tables.forEach((t, i) => {
      if (!tableLabels[t.id]) {
        tableLabels[t.id] = t.label || t.tableNumber || ('A' + (i + 1));
      }
    });
  }

  // Sort tables first, then chairs on top
  const sorted = [...elements].sort((a, b) => {
    if (a.type && a.type.includes('table') && b.type === 'chair') return -1;
    if (a.type === 'chair' && b.type && b.type.includes('table')) return 1;
    return 0;
  });

  let svgInner = '';
  sorted.forEach(el => {
    const x = Number(el.x) || 0;
    const y = Number(el.y) || 0;
    svgInner += `<g transform="translate(${x}, ${y})">`;
    if (el.type && el.type.includes('table')) {
      const isRound = el.type === 'table-round';
      if (isRound) {
        svgInner += `<circle r="45" fill="#f1c40f" stroke="#b45309" stroke-width="2.5" class="table" />`;
      } else {
        svgInner += `<rect width="130" height="80" x="-65" y="-40" rx="8" fill="#f1c40f" stroke="#b45309" stroke-width="2.5" class="table" />`;
      }
      const tLabel = tableLabels[el.id] || el.label || el.tableNumber || '';
      if (tLabel) {
        svgInner += `<text y="6" text-anchor="middle" font-size="16" font-weight="800" fill="#000000" font-family="'Segoe UI', Arial, sans-serif">${escHtml(tLabel)}</text>`;
      }
    } else {
      svgInner += `<circle r="16" fill="#ffffff" stroke="#333333" stroke-width="1.8" class="chair" />`;
      if (el.guest) {
        svgInner += `<text y="5" text-anchor="middle" font-size="11" font-weight="700" fill="#000000" font-family="'Segoe UI', Arial, sans-serif">${escHtml(el.guest.charAt(0).toUpperCase())}</text>`;
        svgInner += `<text y="32" text-anchor="middle" font-size="11" font-weight="600" fill="#000000" font-family="'Segoe UI', Arial, sans-serif">${escHtml(el.guest)}</text>`;
      }
    }
    svgInner += `</g>`;
  });

  const svgContent = `<svg viewBox="${boxX} ${boxY} ${boxW} ${boxH}" preserveAspectRatio="xMidYMid meet" style="width:100%;max-height:560px;display:block;margin:0 auto;background:#fafafa;border:1px solid #e5e5e5;border-radius:8px;">${svgInner}</svg>`;

  let tableBreakdownHtml = '';
  if (tables.length > 0) {
    tableBreakdownHtml = tables.map((t, idx) => {
      const label = tableLabels[t.id] || t.label || t.tableNumber || ('A' + (idx + 1));
      const isVip = !!(t.vip || t.isVip);
      const tChairs = chairs.filter(c => c.parentId === t.id);
      const assignedGuests = tChairs.map(c => c.guestName || c.guest).filter(Boolean);
      const guestListStr = assignedGuests.length > 0 ? assignedGuests.join(', ') : 'Open Seating';

      return `<tr>
        <td style="padding:8px 12px;border-bottom:1px solid #eee;font-weight:600;color:#111;">${escHtml(label)}</td>
        <td style="padding:8px 12px;border-bottom:1px solid #eee;font-size:12px;color:#555;">${t.type === 'table-round' ? 'Round Table' : 'Rectangular Table'}</td>
        <td style="padding:8px 12px;border-bottom:1px solid #eee;text-align:center;font-size:12px;">${tChairs.length} chairs</td>
        <td style="padding:8px 12px;border-bottom:1px solid #eee;text-align:center;">${isVip ? '<span style="background:#fef3c7;color:#b45309;padding:2px 8px;border-radius:10px;font-size:11px;font-weight:700;">VIP</span>' : '<span style="color:#777;font-size:11px;">Standard</span>'}</td>
        <td style="padding:8px 12px;border-bottom:1px solid #eee;font-size:12px;color:#333;">${escHtml(guestListStr)}</td>
      </tr>`;
    }).join('');
  }

  pw.document.write(`<!DOCTYPE html><html><head><title>Venue Seating Layout - ${escHtml(resName)}</title>
    <style>
      body { font-family: 'Segoe UI', Arial, sans-serif; padding: 36px; color: #111; line-height: 1.5; }
      h1 { font-size: 22px; color: #c49a3c; margin: 0 0 4px; }
      .subhdr { font-size: 13px; color: #666; margin-bottom: 20px; }
      .meta-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-bottom: 24px; padding: 16px; background: #fafafa; border: 1px solid #e5e5e5; border-radius: 8px; }
      .meta-label { font-size: 10px; text-transform: uppercase; color: #888; font-weight: 700; letter-spacing: 0.5px; }
      .meta-val { font-size: 14px; font-weight: 600; color: #111; margin-top: 2px; }
      .canvas-wrap { margin-bottom: 24px; display: flex; justify-content: center; align-items: center; width: 100%; box-sizing: border-box; }
      .table { fill: #f1c40f !important; stroke: #b45309 !important; stroke-width: 2.5px !important; }
      .chair { fill: #ffffff !important; stroke: #333333 !important; stroke-width: 1.8px !important; }
      text, .label { fill: #000000 !important; color: #000000 !important; font-family: 'Segoe UI', Arial, sans-serif !important; }
      table { width: 100%; border-collapse: collapse; margin-top: 12px; }
      th { text-align: left; padding: 8px 12px; background: #f4f4f4; border-bottom: 2px solid #ccc; font-size: 11px; text-transform: uppercase; color: #555; }
      .footer { margin-top: 36px; padding-top: 12px; border-top: 1px solid #eee; font-size: 11px; color: #888; text-align: center; }
      @media print {
        body { padding: 16px; }
        @page { size: landscape; margin: 1.2cm; }
        .canvas-wrap { page-break-inside: avoid; }
      }
    </style>
  </head><body>
    <h1>HAL'SERVE - Venue Floor Plan &amp; Seating Layout</h1>
    <div class="subhdr">Physical Floor Configuration &amp; Table Assignment Reference</div>
    <div class="meta-grid">
      <div class="meta-box"><div class="meta-label">Client</div><div class="meta-val">${escHtml(clientName)}</div></div>
      <div class="meta-box"><div class="meta-label">Event Date</div><div class="meta-val">${escHtml(eventDate)}</div></div>
      <div class="meta-box"><div class="meta-label">Venue Location</div><div class="meta-val">${escHtml(venue)}</div></div>
      <div class="meta-box"><div class="meta-label">Layout Capacity</div><div class="meta-val">${tables.length} Tables &bull; ${chairs.length} Chairs (${vipTables.length} VIP)</div></div>
    </div>
    <div class="canvas-wrap">
      ${svgContent}
    </div>
    ${tables.length > 0 ? `
    <h3 style="font-size:15px;color:#c49a3c;margin:20px 0 8px;border-bottom:1px solid #c49a3c;padding-bottom:4px;">Table Seating Breakdown</h3>
    <table>
      <thead>
        <tr>
          <th>Table</th>
          <th>Shape</th>
          <th style="text-align:center;">Capacity</th>
          <th style="text-align:center;">Status</th>
          <th>Seated Guests</th>
        </tr>
      </thead>
      <tbody>
        ${tableBreakdownHtml}
      </tbody>
    </table>` : ''}
    <div class="footer">Generated by SmartServe HAL'SERVE System. Authorized for Floor Operations.</div>
    <script>window.onload = function() { setTimeout(function(){ window.print(); }, 400); };<\/script>
  </body></html>`);
  pw.document.close();
}
window.exportVenueLayoutPDF = exportVenueLayoutPDF;

async function saveGuestList() {
  const res = RESERVATIONS.find(function (r) { return r.id === activeResDetailId; });
  const extra = getActiveReservationExtra();
  if (!res || !extra) return;
  try {
    const cleanGuests = extra.guests.map(g => ({
      name: g.name || '', role: g.role || 'Ordinary', tableSeat: g.tableSeat || 'Any'
    }));

    // Update in-memory reservation object immediately
    res.guestList = cleanGuests;
    res.guest_list = cleanGuests;
    if (extra.seatingElements) {
      res.seatingLayout = extra.seatingElements;
      res.seating_elements = extra.seatingElements;
    }

    if (window.firebaseFns && window.firebaseDB) {
      const { doc, updateDoc } = window.firebaseFns;
      await updateDoc(doc(window.firebaseDB, 'reservations', res.id), {
        guestList: cleanGuests,
        layoutSentToCustomer: !!extra.layoutSent,
        layoutWithNamesReceived: !!extra.layoutReceived,
        seatingLayout: Array.isArray(extra.seatingElements) ? extra.seatingElements : []
      });
    }

    // Persist to Supabase additional_reservation_details
    if (window.supabaseClient) {
      try {
        await window.supabaseClient.from('additional_reservation_details').upsert({
          reservation_id: res.id,
          guest_list: cleanGuests,
          seating_elements: Array.isArray(extra.seatingElements) ? extra.seatingElements : []
        }, { onConflict: 'reservation_id' });
      } catch (_sbErr) {
        console.warn('Failed to upsert guest_list to additional_reservation_details:', _sbErr);
      }
    }

    showToast('Guest list and extra details saved.');

    // Dynamically refresh Execution Day panel so Export buttons and guest list appear instantly
    if (typeof syncAndRefreshExecutionDay === 'function') {
      syncAndRefreshExecutionDay(res.id);
    }

    try {
      const _gl = Array.isArray(extra.guests) ? extra.guests : [];
      const _named = _gl.filter(g => (g.name || '').trim()).length;
      const _vip = _gl.filter(g => g.role === 'VIP').length;
      window.logResdActivity(res, 'Saved Guest List', `Guest list saved: ${_named} named guest(s), ${_vip} VIP; layout sent to customer: ${extra.layoutSent ? 'Yes' : 'No'}; layout with names received: ${extra.layoutReceived ? 'Yes' : 'No'}`);
    } catch (_logErr) {}
  } catch (e) {
    console.error(e);
    alert('Failed to save guest list.');
  }
}

function getTimelineTasks() {
  const extra = getActiveReservationExtra();
  if (!extra) return [];
  if (!Array.isArray(extra.timelineTasks)) extra.timelineTasks = [];

  // --- AUTO-REPAIR: If Meeting milestone has 0 tasks, inject MANDATORY_TOPICS ---
  const hasMeeting = extra.timelineTasks.some(t => t.milestoneId === 'meeting');
  if (!hasMeeting && extra.logisticsMilestones && extra.logisticsMilestones.length > 0) {
    const meetingMs = extra.logisticsMilestones.find(m => m.id === 'meeting');
    if (meetingMs) {
      const res = RESERVATIONS.find(r => r.id === activeResDetailId);
      if (res && typeof MANDATORY_TOPICS !== 'undefined') {
        const topics = MANDATORY_TOPICS;
        const concluded = String(res['mandatory-meeting concluded'] || '').toLowerCase();

        const mStartDate = new Date(meetingMs.startDate + 'T00:00:00');
        const mEndDate = new Date(meetingMs.endDate + 'T00:00:00');
        const mDays = Math.max(1, Math.round((mEndDate - mStartDate) / (1000 * 60 * 60 * 24)) + 1);

        const newTasks = [];
        topics.forEach((topic, idx) => {
          const dayOffset = topics.length === 1 ? 0 : Math.floor(idx * mDays / topics.length);
          const tDate = new Date(mStartDate);
          tDate.setDate(tDate.getDate() + Math.min(dayOffset, mDays - 1));

          newTasks.push({
            id: 'auto-meeting-' + idx + '-' + Math.random().toString(36).substr(2, 5),
            milestoneId: 'meeting',
            title: topic,
            date: normalizeDateKey(tDate),
            status: concluded.includes(topic.toLowerCase()) ? 'done' : 'pending',
            type: 'auto',
            color: meetingMs.color || '#3b82f6',
            linkTo: 'meetings'
          });
        });

        extra.timelineTasks.push(...newTasks);
        // Fire-and-forget save to persist the repaired state
        if (typeof saveLogisticsData === 'function') saveLogisticsData();
      }
    }
  }

  // --- RETROACTIVE FIX: Ensure all 'meeting' tasks have linkTo: 'meetings' ---
  let changedLinkTo = false;
  extra.timelineTasks.forEach(t => {
    if (t.milestoneId === 'meeting' && t.linkTo !== 'meetings') {
      t.linkTo = 'meetings';
      changedLinkTo = true;
    }
  });

  // --- AUTO-SYNC: Ensure payment tasks (downpayment & final payment) are synchronized ---
  const resObj = RESERVATIONS.find(r => r.id === activeResDetailId);
  if (resObj) {
    let tasksModified = false;
    const dpPaidFlag = isDownpaymentPaid(resObj);
    extra.timelineTasks.forEach(t => {
      if (t.milestoneId === 'payment' && String(t.title || '').toLowerCase().includes('downpayment')) {
        if (dpPaidFlag && t.status !== 'done') {
          t.status = 'done';
          t.autoCheck = true;
          tasksModified = true;
        }
      }
    });

    const payMs = extra.logisticsMilestones && extra.logisticsMilestones.find(m => m.id === 'payment');
    if (payMs) {
      const hasFinalPayment = extra.timelineTasks.some(t =>
        t.milestoneId === 'payment' && (String(t.title || '').toLowerCase().includes('final payment') || String(t.title || '').toLowerCase().includes('balance'))
      );
      const evDateStr = normalizeDateKey(resObj.date || resObj.eventDate);
      let lockedFinalDueDate = '';
      if (evDateStr) {
        const evD = new Date(evDateStr + 'T00:00:00');
        evD.setDate(evD.getDate() - 3);
        lockedFinalDueDate = normalizeDateKey(evD);
      }
      const finalDueDate = resObj.finalPaymentDueDate || resObj.final_payment_due_date || lockedFinalDueDate;
      const finalPaidFlag = typeof isFinalPaymentSettled === 'function' ? isFinalPaymentSettled(resObj) : (resObj.finalPaymentStatus === 'paid' || resObj.final_payment_status === 'paid' || resObj.settled === true);
      const totalAmt = safeNum(resObj.amount || resObj.totalContract || 0);
      const dpAmt = safeNum(resObj.downpaymentAmount || resObj.downpayment_amount || 0);
      const rawFinalAmt = safeNum(resObj.finalPaymentAmount || resObj.final_payment_amount || 0);
      const finalAmt = rawFinalAmt > 0 ? rawFinalAmt : Math.max(0, totalAmt - dpAmt);

      if (!hasFinalPayment) {
        extra.timelineTasks.push({
          id: 'auto-payment-final-' + Math.random().toString(36).substr(2, 5),
          milestoneId: 'payment',
          title: finalAmt > 0 ? `Final Payment Due: ₱${finalAmt.toLocaleString()}` : 'Final Payment Due',
          date: finalDueDate || payMs.endDate,
          status: finalPaidFlag ? 'done' : 'pending',
          autoCheck: finalPaidFlag,
          type: 'auto',
          color: payMs.color || '#f59e0b'
        });
        if (finalDueDate && (!payMs.endDate || payMs.endDate < finalDueDate)) {
          payMs.endDate = finalDueDate;
        }
        tasksModified = true;
      } else {
        extra.timelineTasks.forEach(t => {
          if (t.milestoneId === 'payment' && (String(t.title || '').toLowerCase().includes('final payment') || String(t.title || '').toLowerCase().includes('balance'))) {
            if (finalDueDate && t.date !== finalDueDate) {
              t.date = finalDueDate;
              tasksModified = true;
            }
            if (finalAmt > 0 && !t.title.includes(finalAmt.toLocaleString())) {
              t.title = `Final Payment Due: ₱${finalAmt.toLocaleString()}`;
              tasksModified = true;
            }
            if (finalPaidFlag && t.status !== 'done') {
              t.status = 'done';
              t.autoCheck = true;
              tasksModified = true;
            }
          }
        });
        if (finalDueDate && (!payMs.endDate || payMs.endDate < finalDueDate)) {
          payMs.endDate = finalDueDate;
          tasksModified = true;
        }
      }
    }

    // --- RESOURCE PLANNING ACTIVITIES SYNC & MIGRATION ---
    const resourceMs = extra.logisticsMilestones && extra.logisticsMilestones.find(m => m.id === 'resources');
    if (resourceMs) {
      const resId = activeResDetailId;
      const sortedCache = (_procDataCache && _procDataCache[resId] && _procDataCache[resId].sorted) ? _procDataCache[resId].sorted : null;

      // 1. Remove deprecated tasks: 'Rental Confirmation', 'Supplier Coordination'
      const deprecated = ['Rental Confirmation', 'Supplier Coordination'];
      const hadDeprecated = extra.timelineTasks.some(t => t.milestoneId === 'resources' && deprecated.includes(t.title));
      if (hadDeprecated) {
        extra.timelineTasks = extra.timelineTasks.filter(t => !(t.milestoneId === 'resources' && deprecated.includes(t.title)));
        tasksModified = true;
      }

      // 2. Define the 6 resource planning tasks with their linkTo targets and category keys
      const resourceDefs = [
        { title: 'Ingredient Procurement', linkTo: 'res_dishes', cat: 'food' },
        { title: 'Equipment Allocation', linkTo: 'res_equipment', cat: 'equipment' },
        { title: 'Decoration Allocation', linkTo: 'res_decoration', cat: 'decoration' },
        { title: 'Personnel Coordination', linkTo: 'res_personnel', cat: 'personnel' },
        { title: 'Transportation Selection', linkTo: 'res_transportation', cat: 'transportation' },
        { title: 'Staff Assignment', linkTo: 'res_staff', cat: 'staff_allocation' }
      ];

      const rStartDate = new Date(resourceMs.startDate + 'T00:00:00');
      const rEndDate = new Date(resourceMs.endDate + 'T00:00:00');
      const rDays = Math.max(1, Math.round((rEndDate - rStartDate) / (1000 * 60 * 60 * 24)) + 1);

      resourceDefs.forEach((def, idx) => {
        let existingTask = extra.timelineTasks.find(t => t.milestoneId === 'resources' && t.title === def.title);
        const isSorted = sortedCache ? !!sortedCache[def.cat] : false;

        if (!existingTask) {
          // Compute distributed date across milestone range
          const dayOffset = Math.floor(idx * rDays / resourceDefs.length);
          const tDate = new Date(rStartDate);
          tDate.setDate(tDate.getDate() + Math.min(dayOffset, rDays - 1));

          existingTask = {
            id: 'auto-resources-' + idx + '-' + Math.random().toString(36).substr(2, 5),
            milestoneId: 'resources',
            title: def.title,
            date: normalizeDateKey(tDate),
            status: isSorted ? 'done' : 'pending',
            autoCheck: isSorted,
            type: 'auto',
            color: resourceMs.color || '#06b6d4',
            linkTo: def.linkTo
          };
          extra.timelineTasks.push(existingTask);
          tasksModified = true;
        } else {
          // Ensure linkTo is set
          if (existingTask.linkTo !== def.linkTo) {
            existingTask.linkTo = def.linkTo;
            tasksModified = true;
          }
          // Auto-check based on Resource Preparation sorted status
          if (sortedCache) {
            const expectedStatus = isSorted ? 'done' : (existingTask.autoCheck ? 'pending' : existingTask.status);
            if (existingTask.status !== expectedStatus || existingTask.autoCheck !== isSorted) {
              existingTask.status = expectedStatus;
              existingTask.autoCheck = isSorted;
              tasksModified = true;
            }
          }
        }
      });
    }

    if ((changedLinkTo || tasksModified) && typeof saveLogisticsData === 'function') {
      saveLogisticsData();
    }
  } else if (changedLinkTo && typeof saveLogisticsData === 'function') {
    saveLogisticsData();
  }

  return extra.timelineTasks;
}

// ─── RESOURCE PLANNING CHECKBOX AUTO-SYNC HELPER ─────────────────────────────
// Keeps the 6 resource planning timeline tasks automatically checked / unchecked
// based on whether the corresponding column is marked sorted in Resource Preparation.
function syncResourcePlanningTasksFromSorted(resId, sortedMap) {
  if (!resId) return;
  const extra = (typeof reservationExtraDetails !== 'undefined' && reservationExtraDetails[resId]) ? reservationExtraDetails[resId] : null;
  if (!extra || !Array.isArray(extra.timelineTasks)) return;

  const mapping = [
    { cat: 'food', title: 'Ingredient Procurement', linkTo: 'res_dishes' },
    { cat: 'equipment', title: 'Equipment Allocation', linkTo: 'res_equipment' },
    { cat: 'decoration', title: 'Decoration Allocation', linkTo: 'res_decoration' },
    { cat: 'personnel', title: 'Personnel Coordination', linkTo: 'res_personnel' },
    { cat: 'transportation', title: 'Transportation Selection', linkTo: 'res_transportation' },
    { cat: 'staff_allocation', title: 'Staff Assignment', linkTo: 'res_staff' }
  ];

  let modified = false;
  mapping.forEach(m => {
    const isSorted = sortedMap ? !!sortedMap[m.cat] : false;
    const task = extra.timelineTasks.find(t => t.milestoneId === 'resources' && t.title === m.title);
    if (task) {
      if (task.linkTo !== m.linkTo) {
        task.linkTo = m.linkTo;
        modified = true;
      }
      const newStatus = isSorted ? 'done' : (task.autoCheck ? 'pending' : task.status);
      if (task.status !== newStatus || task.autoCheck !== isSorted) {
        if (newStatus === 'done' && task.status !== 'done') {
          const res = RESERVATIONS.find(r => r.id === resId);
          const notifService = window.HalServeNotifications || window.SmartServeNotifications;
          if (res && notifService && typeof notifService.notifyLogisticsTaskCompleted === 'function') {
            const custEmail = res.email || res.client_email || res.customerEmail;
            if (custEmail) {
              notifService.notifyLogisticsTaskCompleted({
                taskTitle: m.title || task.title,
                taskDate: task.date || res.date || 'TBD',
                milestoneName: 'RESOURCE PREPARATION',
                customerEmail: custEmail,
                customerName: res.client || res.name || res.client_name || res.customerName || 'Valued Client',
                reservationId: res.id || res.reference_id || 'N/A',
                packageName: res.packageName || res.package || res.eventType || res.type || 'Catering Reservation',
                eventDate: res.date || 'Scheduled Event'
              });
            }
          }
        }
        task.status = newStatus;
        task.autoCheck = isSorted;
        modified = true;
      }
    }
  });

  if (modified) {
    if (typeof saveLogisticsData === 'function') saveLogisticsData();
    if (activeResDetailId === resId) {
      const res = RESERVATIONS.find(r => r.id === resId);
      if (typeof renderLogisticsActivities === 'function') renderLogisticsActivities();
      if (typeof renderLogisticsMilestones === 'function' && res) renderLogisticsMilestones(res);
      if (resTimelineCalendar) {
        try { resTimelineCalendar.refetchEvents(); } catch (e) { }
      }
    }
  }
}
window.syncResourcePlanningTasksFromSorted = syncResourcePlanningTasksFromSorted;

function getContractBaseDate(res) {
  if (res && res.contractFinalizedAt) return normalizeDateKey(res.contractFinalizedAt);
  if (res && res.contractUrl && res.updatedAt) return normalizeDateKey(res.updatedAt);
  return null;
}

function computePaymentMilestones(res) {
  const base = getContractBaseDate(res);
  if (!base) return [];
  const extra = getActiveReservationExtra();
  if (!extra.paymentRecords) extra.paymentRecords = {};
  const labels = [
    { key: 'reservation_payment', label: 'Pending Reservation Payment Due', offset: 1 },
    { key: 'down_payment', label: 'Down Payment Due', offset: 7 },
    { key: 'final_payment', label: 'Final Payment Due', offset: 14 },
    { key: 'damages_fee', label: 'Pending Damages Fees Due', offset: 21 }
  ];
  return labels.map(function (p) {
    const d = new Date(base + 'T00:00:00');
    d.setDate(d.getDate() + p.offset);
    const dueDate = d.toISOString().split('T')[0];
    if (!extra.paymentRecords[p.key]) extra.paymentRecords[p.key] = { status: 'pending' };
    return {
      key: p.key,
      label: p.label,
      dueDate: dueDate,
      record: extra.paymentRecords[p.key]
    };
  });
}

async function autoHandlePendingPayments(res, milestones) {
  if (!res || !milestones.length) return;
  const today = new Date().toISOString().split('T')[0];
  const extra = getActiveReservationExtra();
  if (!extra) return;
  if (!extra.autoPaymentTriggered) extra.autoPaymentTriggered = {};
  let requiresSave = false;

  milestones.forEach(function (m) {
    const rec = m.record || {};
    if (rec.status === 'paid' || rec.status === 'cancelled') return;
    if (today >= m.dueDate && !rec.gatewayTriggeredAt) {
      rec.status = 'gateway_triggered';
      rec.gatewayTriggeredAt = new Date().toISOString();
      extra.autoPaymentTriggered[m.key] = true;
      requiresSave = true;
    }
    if (today > m.dueDate && rec.status !== 'paid' && !extra.cancelledForNonPayment) {
      extra.cancelledForNonPayment = true;
      rec.status = 'cancelled';
      requiresSave = true;
      updateReservationStatus(res.id, 'cancelled', 'Auto-cancelled due to missed scheduled payment.');
    }
  });

  if (requiresSave) {
    try {
      const { doc, updateDoc } = window.firebaseFns;
      await updateDoc(doc(window.firebaseDB, 'reservations', res.id), {
        paymentTimeline: extra.paymentRecords,
        paymentRequested: true,
        paymentStatus: 'pending'
      });
    } catch (e) { }
  }
}

async function runReservationPaymentAutomation() {
  const res = RESERVATIONS.find(function (r) { return r.id === activeResDetailId; });
  if (!res) return;
  const milestones = computePaymentMilestones(res);
  await autoHandlePendingPayments(res, milestones);
  renderReservationTimelineView();
}

function renderTimelineTaskList() {
  const listEl = document.getElementById('resd-task-list');
  if (!listEl) return;
  const tasks = getTimelineTasks().slice().sort(function (a, b) { return String(a.date).localeCompare(String(b.date)); });
  if (!tasks.length) {
    listEl.innerHTML = '<div style="font-size:12px;color:var(--text-dim);padding:8px 0;">No activities logged yet.</div>';
    return;
  }
  listEl.innerHTML = tasks.map(function (t) {
    const b = t.status === 'done' ? 'confirmed' : (t.status === 'in-progress' ? 'pending' : 'warning');
    return `<div style="border:1px solid var(--border);border-radius:8px;padding:8px 10px;margin-bottom:8px;">
      <div style="display:flex;justify-content:space-between;gap:8px;align-items:center;">
        <div style="font-size:12px;font-weight:700;color:var(--cream);">${escHtml(t.title || 'Untitled Activity')}</div>
        <span class="badge ${b}" style="font-size:10px;">${escHtml(t.status || 'pending')}</span>
      </div>
      <div style="font-size:11px;color:var(--text-dim);margin-top:3px;">${escHtml(t.date || ':')} ${t.note ? '· ' + escHtml(t.note) : ''}</div>
      <div style="margin-top:8px;display:flex;gap:6px;justify-content:flex-end;">
        <button class="btn-outline" style="font-size:10px;padding:3px 8px;" onclick="updateTimelineTaskStatus('${t.id}','pending')">Pending</button>
        <button class="btn-outline" style="font-size:10px;padding:3px 8px;" onclick="updateTimelineTaskStatus('${t.id}','in-progress')">In Progress</button>
        <button class="btn-outline" style="font-size:10px;padding:3px 8px;" onclick="updateTimelineTaskStatus('${t.id}','done')">Done</button>
      </div>
    </div>`;
  }).join('');
}

function renderPaymentTimeline(res, milestones) {
  const el = document.getElementById('resd-payment-list');
  if (!el) return;
  if (!milestones.length) {
    el.innerHTML = '<div style="font-size:12px;color:var(--text-dim);">Payment dates will auto-generate after contract finalization in Meeting Mode.</div>';
    return;
  }
  el.innerHTML = milestones.map(function (m) {
    const st = m.record.status || 'pending';
    const cls = st === 'paid' ? 'confirmed' : (st === 'gateway_triggered' ? 'pending' : (st === 'cancelled' ? 'cancelled' : 'warning'));
    return `<div style="border:1px solid var(--border);border-radius:8px;padding:10px;margin-bottom:8px;">
      <div style="display:flex;justify-content:space-between;gap:8px;align-items:center;">
        <div style="font-size:12px;font-weight:700;color:var(--cream);">${escHtml(m.label)}</div>
        <span class="badge ${cls}" style="font-size:10px;">${escHtml(st)}</span>
      </div>
      <div style="font-size:11px;color:var(--text-dim);margin-top:4px;">Due: ${escHtml(m.dueDate)}</div>
      <div style="display:flex;justify-content:flex-end;margin-top:8px;">
        <button class="btn-outline" style="font-size:10px;padding:4px 10px;" onclick="markTimelinePaymentPaid('${m.key}')">Mark Paid</button>
      </div>
    </div>`;
  }).join('');
}

let activeLogisticsMilestoneId = null;

function setActiveLogisticsMilestone(id) {
  if (activeLogisticsMilestoneId === id) {
    activeLogisticsMilestoneId = null; // Toggle off
  } else {
    activeLogisticsMilestoneId = id;
  }
  const res = RESERVATIONS.find(function (r) { return r.id === activeResDetailId; });
  if (res) {
    renderLogisticsMilestones(res);
  }
}

function renderLogisticsMilestones(res) {
  const el = document.getElementById('resd-timeline-milestones');
  if (!el) return;
  const extra = getActiveReservationExtra();
  if (!extra || !extra.logisticsMilestones || !extra.logisticsMilestones.length) {
    el.innerHTML = '<div style="font-size:12px;color:var(--text-dim);padding:20px;text-align:center;background:rgba(255,255,255,0.02);border-radius:12px;">No milestones generated. Milestones will appear after contract finalization.</div>';
    return;
  }

  el.innerHTML = extra.logisticsMilestones.map(function (m) {
    const status = m.status || 'upcoming';
    const tasks = (extra.timelineTasks || []).filter(t => t.milestoneId === m.id);
    const doneTasks = tasks.filter(t => t.status === 'done').length;
    const progress = tasks.length ? Math.round((doneTasks / tasks.length) * 100) : 0;
    const color = m.color || 'var(--gold)';
    const isActive = m.id === activeLogisticsMilestoneId;
    const borderStyle = isActive ? `border:1px solid ${color};` : `border:1px solid var(--border);`;
    const bgStyle = isActive ? `background:rgba(255,255,255,0.05);` : `background:var(--bg3);`;

    let content = '';
    if (isEditingLogistics) {
      content = `
        <div style="display:flex;gap:10px;margin-bottom:12px;align-items:center;">
          <div style="font-size:12px;font-weight:700;color:var(--cream);flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escHtml(m.label)}</div>
          <select class="btn-outline" style="font-size:10px;padding:2px 4px;background:transparent;color:var(--text-mid);" onchange="updateLogisticsMilestoneStatus('${m.id}', this.value)">
             <option value="upcoming" ${status === 'upcoming' ? 'selected' : ''}>Upcoming</option>
             <option value="in-progress" ${status === 'in-progress' ? 'selected' : ''}>In Progress</option>
             <option value="completed" ${status === 'completed' ? 'selected' : ''}>Completed</option>
          </select>
        </div>
        <div style="display:flex;flex-direction:column;gap:6px;">
          <div style="display:flex;align-items:center;gap:4px;">
            <span style="font-size:10px;color:var(--text-dim);width:30px;">Start:</span>
            <input type="date" class="input-field" style="width:110px;padding:2px 4px;font-size:10px;" value="${m.startDate}" onchange="updateMilestoneDate('${m.id}', 'startDate', this.value)" onclick="event.stopPropagation()" />
          </div>
          <div style="display:flex;align-items:center;gap:4px;">
            <span style="font-size:10px;color:var(--text-dim);width:30px;">End:</span>
            <input type="date" class="input-field" style="width:110px;padding:2px 4px;font-size:10px;" value="${m.endDate}" onchange="updateMilestoneDate('${m.id}', 'endDate', this.value)" onclick="event.stopPropagation()" />
          </div>
        </div>
      `;
    } else {
      content = `
        <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px;">
          <div style="overflow:hidden;flex:1;margin-right:10px;">
            <div style="font-size:13px;font-weight:700;color:var(--cream);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;" title="${escHtml(m.label)}">${escHtml(m.label)}</div>
            <div style="font-size:10px;color:var(--text-dim);margin-top:2px;">${m.startDate} - ${m.endDate}</div>
          </div>
          <span style="font-size:9px; font-weight:700; color:${color};">${escHtml(status.toUpperCase())}</span>
        </div>
        
        <div style="height:4px;background:rgba(255,255,255,0.05);border-radius:2px;overflow:hidden;margin-bottom:6px;">
          <div style="height:100%;width:${progress}%;background:${color};transition:width 0.3s ease;"></div>
        </div>
        <div style="font-size:9px;color:var(--text-dim);">
          ${doneTasks}/${tasks.length} Activities (${progress}%)
        </div>
      `;
    }

    let tasksListHtml = '';
    if (isActive) {
      if (tasks.length > 0) {
        tasksListHtml = `<div style="margin-top:12px; padding-top:12px; border-top:1px dashed var(--border); display:flex; flex-direction:column; gap:8px;">
          <div style="font-size:10px; color:var(--text-dim); text-transform:uppercase; letter-spacing:1px; margin-bottom:4px;">Activities</div>
          ${tasks.map(t => {
          const isDone = t.status === 'done' || t.autoCheck;
          return `
              <div style="display:flex; align-items:flex-start; gap:8px; text-align:left;">
                <div style="width:12px; height:12px; border-radius:50%; border:1px solid ${isDone ? 'var(--green)' : 'var(--text-dim)'}; background:${isDone ? 'var(--green)' : 'transparent'}; margin-top:2px; flex-shrink:0;"></div>
                <div style="flex:1;">
                  <div style="font-size:11px; color:${isDone ? 'var(--text-dim)' : 'var(--cream)'}; text-decoration:${isDone ? 'line-through' : 'none'};">${escHtml(t.title)}</div>
                  <div style="font-size:9px; color:var(--text-dim);">${t.date || 'No Date'}</div>
                </div>
              </div>
            `;
        }).join('')}
        </div>`;
      } else {
        tasksListHtml = `<div style="margin-top:12px; padding-top:12px; border-top:1px dashed var(--border); font-size:10px; color:var(--text-dim); text-align:center;">No activities scheduled.</div>`;
      }
    }

    return `<div onclick="setActiveLogisticsMilestone('${m.id}')" style="${borderStyle}border-left:4px solid ${color};border-radius:8px;padding:12px;cursor:pointer;min-width:240px;flex:0 0 240px;${bgStyle}transition:all 0.2s;">
      ${content}
      ${tasksListHtml}
    </div>`;
  }).join('');
}

window._timelineTaskNavigate = function (linkTo, title) {
  if (linkTo === 'meetings') {
    const navEl = document.getElementById('nav-meetings');
    if (navEl && typeof showSection === 'function') showSection('meetings', navEl);
  } else if (linkTo === 'billing') {
    const navEl = document.getElementById('nav-billing');
    if (navEl && typeof showSection === 'function') showSection('billing', navEl);
  } else if (linkTo === 'res_dishes') {
    // 1. Ingredient Procurement: redirect to dishes & ingredients expanded area
    const resId = activeResDetailId;
    if (typeof openDishesPanel === 'function') {
      openDishesPanel(resId);
    }
  } else if (linkTo === 'res_equipment') {
    // 2. Equipment Allocation: redirect to equipment cycle, equipments tab in deployment manifest area
    const resId = activeResDetailId;
    if (typeof openEquipmentCycleScheduling === 'function') {
      openEquipmentCycleScheduling(resId);
    }
    setTimeout(() => {
      if (typeof switchAllocSubTab === 'function') {
        switchAllocSubTab('equipments');
      }
    }, 200);
  } else if (linkTo === 'res_decoration') {
    // 3. Decoration Allocation: redirect to equipment cycle event allocation decoration tab
    const resId = activeResDetailId;
    if (typeof openEquipmentCycleScheduling === 'function') {
      openEquipmentCycleScheduling(resId);
    }
    setTimeout(() => {
      if (typeof switchAllocSubTab === 'function') {
        switchAllocSubTab('decorations');
      }
    }, 200);
  } else if (linkTo === 'res_personnel') {
    // 4. Personnel Coordination: redirect to personnel tab
    if (typeof showSection === 'function') {
      const navBtn = document.getElementById('nav-res-details') || document.querySelector('[data-section="res-details"]');
      showSection('res-details', navBtn);
    }
    if (typeof switchResDetailsTab === 'function') {
      switchResDetailsTab('personnel');
    }
  } else if (linkTo === 'res_transportation') {
    // 5. Transportation Selection: redirect to transportation expanded area
    if (typeof openTransportationPanel === 'function') {
      openTransportationPanel();
    }
  } else if (linkTo === 'res_staff') {
    // 6. Staff Assignment: redirect to staff allocation tab
    if (typeof showSection === 'function') {
      const navBtn = document.getElementById('nav-res-details') || document.querySelector('[data-section="res-details"]');
      showSection('res-details', navBtn);
    }
    if (typeof switchResDetailsTab === 'function') {
      switchResDetailsTab('staff');
    }
  }
};

function renderLogisticsActivities() {
  const el = document.getElementById('resd-timeline-activities');
  if (!el) return;

  const tasks = getTimelineTasks().slice().sort((a, b) => String(a.date).localeCompare(String(b.date)));
  if (!tasks.length) {
    el.innerHTML = '<div style="font-size:12px;color:var(--text-dim);padding:20px;text-align:center;background:rgba(255,255,255,0.02);border-radius:12px;border:1px dashed var(--border);">No activities planned yet.</div>';
    return;
  }

  // Group all tasks by date
  const tasksByDate = {};
  tasks.forEach(t => {
    const d = t.date || 'Undated';
    if (!tasksByDate[d]) tasksByDate[d] = [];
    tasksByDate[d].push(t);
  });

  const todayKey = normalizeDateKey(new Date());

  let html = `
    <div class="panel" style="margin:0;"><div class="panel-body" style="padding:18px;">
      <div style="font-size:15px; font-weight:800; color:var(--cream); margin-bottom:16px; display:flex; align-items:center; justify-content:space-between; border-bottom:1px solid var(--border); padding-bottom:10px;">
        <span>All Logistics Activities (${tasks.length} tasks)</span>
        <span style="font-size:11px; color:var(--text-dim); font-weight:500;">Categorized per Assigned Date</span>
      </div>
      <div style="display:flex; flex-direction:column; gap:16px;">
  `;

  const sortedDates = Object.keys(tasksByDate).sort();
  sortedDates.forEach(dateKey => {
    const dayTasks = tasksByDate[dateKey];
    const doneCount = dayTasks.filter(t => t.status === 'done' || t.autoCheck).length;

    let dateLabel = dateKey;
    if (dateKey !== 'Undated') {
      try {
        const dObj = new Date(dateKey + 'T00:00:00');
        dateLabel = dObj.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' }).toUpperCase();
      } catch(e) {}
    }

    let badgeHtml = '';
    if (dateKey === todayKey) {
      badgeHtml = `<span style="background:var(--gold);color:#000;padding:2px 8px;border-radius:4px;font-size:10px;font-weight:800;margin-left:8px;">TODAY</span>`;
    } else if (dateKey < todayKey && doneCount < dayTasks.length) {
      badgeHtml = `<span style="background:var(--red);color:#fff;padding:2px 8px;border-radius:4px;font-size:10px;font-weight:800;margin-left:8px;">OVERDUE</span>`;
    }

    html += `
      <div style="background:rgba(255,255,255,0.02); border:1px solid var(--border); border-radius:10px; padding:14px; overflow:hidden;">
        <div style="display:flex; align-items:center; justify-content:space-between; margin-bottom:10px; padding-bottom:8px; border-bottom:1px solid rgba(255,255,255,0.06);">
          <div style="font-size:13px; font-weight:800; color:var(--cream); display:flex; align-items:center;">
            ${dateLabel} ${badgeHtml}
          </div>
          <div style="font-size:11px; font-weight:700; color:${doneCount === dayTasks.length ? 'var(--green)' : 'var(--text-dim)'};">
            ${doneCount}/${dayTasks.length} done
          </div>
        </div>
        <div style="display:flex; flex-direction:column; gap:8px;">
          ${dayTasks.map(t => {
            const isDone = t.status === 'done' || t.autoCheck;
            const bg = isDone ? 'rgba(45, 138, 78, 0.05)' : 'var(--bg2)';
            const bColor = isDone ? '#2d8a4e' : 'var(--border)';
            const textColor = isDone ? 'var(--text-dim)' : 'var(--cream)';
            const msLabel = t.milestoneId ? t.milestoneId.toUpperCase() : '';
            const msColor = t.color || 'var(--gold)';
            return `<div style="display:flex; align-items:center; gap:12px; padding:10px 14px; background:${bg}; border:1px solid ${bColor}; border-radius:8px; transition:all 0.2s;">
              <input type="checkbox"
                ${isDone ? 'checked' : ''}
                ${t.autoCheck ? 'disabled title="Automatically synchronized with Resource Preparation sorted status"' : `onclick="updateTimelineTaskStatus('${t.id}', this.checked ? 'done' : 'pending'); setTimeout(renderLogisticsActivities, 50);"`}
                style="cursor:${t.autoCheck ? 'default' : 'pointer'}; width:18px; height:18px; accent-color:#2d8a4e; margin:0;">
              <div
                ${t.linkTo ? `onclick="window._timelineTaskNavigate('${t.linkTo}', '${escHtml(t.title)}')"` : ''}
                style="flex:1; display:flex; align-items:center; gap:10px; ${t.linkTo ? 'cursor:pointer;' : ''}">
                <div
                  style="font-size:13px; font-weight:600; color:${textColor}; ${isDone ? 'text-decoration:line-through;' : ''} ${t.linkTo ? 'text-decoration:underline dashed rgba(255,255,255,0.3); text-underline-offset:4px;' : ''}"
                >${escHtml(t.title || 'Activity')}</div>
                ${msLabel ? `<span style="font-size:9px; font-weight:700; color:${String(msColor).split(';')[0]}; background:transparent !important; border:none !important; padding:0 !important;">${msLabel}</span>` : ''}
              </div>
            </div>`;
          }).join('')}
        </div>
      </div>
    `;
  });

  html += `</div></div></div>`;
  el.innerHTML = html;
}

window.reloadTimelineCalendar = function() {
  const calEl = document.getElementById('resd-timeline-calendar');
  const btn = document.getElementById('btn-toggle-timeline-calendar');
  if (!calEl) return;
  if (btn) btn.textContent = 'Hide Calendar';
  calEl.style.display = 'block';

  const cal = resTimelineCalendar || window.resdTimelineCalendarInstance;
  if (cal) {
    // If instance is already mounted, simply recalculate layout dimensions safely
    setTimeout(() => {
      try {
        cal.updateSize();
        if (typeof cal.render === 'function') cal.render();
      } catch (e) { }
    }, 60);
  } else {
    // If not yet mounted, initialize timeline view
    if (typeof renderReservationTimelineView === 'function') {
      renderReservationTimelineView();
    }
  }
};

window.toggleTimelineCalendarCollapse = function() {
  const calEl = document.getElementById('resd-timeline-calendar');
  const btn = document.getElementById('btn-toggle-timeline-calendar');
  if (!calEl || !btn) return;
  const isHidden = calEl.style.display === 'none';
  if (isHidden) {
    window.reloadTimelineCalendar();
  } else {
    calEl.style.display = 'none';
    btn.textContent = 'Show Calendar';
    // Preserve FullCalendar instance intact so unhiding will not render a blank grid
  }
};

window.changeTimelineChecklistDate = function (dir) {
  const tasks = getTimelineTasks().slice().sort((a, b) => String(a.date).localeCompare(String(b.date)));
  const dates = [...new Set(tasks.map(t => t.date))].filter(Boolean);
  let curIdx = dates.indexOf(window._activeTimelineChecklistDate);
  if (curIdx === -1) return;
  curIdx += dir;
  if (curIdx >= 0 && curIdx < dates.length) {
    window._activeTimelineChecklistDate = dates[curIdx];
    renderLogisticsActivities();
  }
};

let isEditingLogistics = false;
function toggleLogisticsEditMode() {
  isEditingLogistics = !isEditingLogistics;
  const btn = document.getElementById('btn-edit-logistics');
  if (btn) {
    btn.textContent = isEditingLogistics ? 'Finish Editing' : 'Modify Timeline';
    btn.style.background = isEditingLogistics ? 'var(--green)' : 'var(--gold)';
  }
  renderReservationTimelineView();
}

async function updateMilestoneDate(mId, field, value) {
  const extra = getActiveReservationExtra();
  if (!extra) return;
  const m = extra.logisticsMilestones.find(x => x.id === mId);
  if (m) {
    const _oldVal = m[field];
    m[field] = value;
    await saveLogisticsData();
    try { if (_oldVal !== value) window.logResdActivity(activeResDetailId, 'Updated Milestone Date', `Milestone "${m.title || m.name || mId}" ${field}: ${_oldVal || 'Not set'} -> ${value || 'Not set'}`); } catch (_logErr) {}
    // We don't re-render immediately to avoid focus loss on input, 
    // unless user wants strict validation feedback.
    // However, FullCalendar might need update.
    if (resTimelineCalendar) renderReservationTimelineView();
  }
}

async function updateActivityDate(taskId, value, minDate, maxDate) {
  if (value < minDate || value > maxDate) {
    alert(`Activity date must be within milestone range: ${minDate} to ${maxDate}`);
    renderReservationTimelineView();
    return;
  }
  const extra = getActiveReservationExtra();
  if (!extra) return;
  const t = extra.timelineTasks.find(x => x.id === taskId);
  if (t) {
    t.date = value;
    await saveLogisticsData();
    renderReservationTimelineView();
  }
}

async function updateLogisticsMilestoneStatus(id, newStatus) {
  const extra = getActiveReservationExtra();
  if (!extra) return;
  const m = extra.logisticsMilestones.find(x => x.id === id);
  if (m) {
    const _oldMs = m.status;
    m.status = newStatus;
    await saveLogisticsData();
    try { if (_oldMs !== newStatus) window.logResdActivity(activeResDetailId, 'Updated Logistics Milestone', `Milestone "${m.title || m.name || id}": ${_oldMs || 'pending'} -> ${newStatus}`); } catch (_logErr) {}
    renderReservationTimelineView();
  }
}

async function toggleTimelineTaskStatus(taskId) {
  const extra = getActiveReservationExtra();
  if (!extra) return;
  const t = extra.timelineTasks.find(x => x.id === taskId);
  if (t) {
    const cycle = { pending: 'in-progress', 'in-progress': 'done', done: 'pending' };
    const _oldTs = t.status || 'pending';
    t.status = cycle[t.status] || 'pending';
    await saveLogisticsData();
    try { window.logResdActivity(activeResDetailId, 'Updated Timeline Task', `Task "${t.title || taskId}": ${_oldTs} -> ${t.status}`); } catch (_logErr) {}
    renderReservationTimelineView();
  }
}

async function saveLogisticsData() {
  if (!activeResDetailId) return;
  try {
    const extra = getActiveReservationExtra();
    const { updateDoc, doc } = window.firebaseFns;
    await updateDoc(doc(window.firebaseDB, 'reservations', activeResDetailId), {
      logisticsMilestones: extra.logisticsMilestones,
      timelineTasks: extra.timelineTasks
    });
  } catch (e) { console.error(e); }
}

function renderTimelineAnalytics(res, tasks) {
  const container = document.getElementById('resd-timeline-analytics');
  if (!container) return;

  if (!res) {
    container.style.display = 'none';
    return;
  }

  const todayStr = new Date().toISOString().split('T')[0];
  // normalizeDateKey converts any date format (e.g. 'Sep 16, 2026') to YYYY-MM-DD
  const eventDateStr = (typeof normalizeDateKey === 'function') ? normalizeDateKey(res.date) : res.date;

  // 1. Days left
  let daysLeftText = 'Event Passed';
  let daysLeftColor = 'var(--text-dim)';
  if (eventDateStr) {
    const today = new Date(todayStr + 'T00:00:00');
    const evDate = new Date(eventDateStr + 'T00:00:00');
    const diff = Math.ceil((evDate - today) / (1000 * 60 * 60 * 24));
    if (diff > 0) {
      daysLeftText = `${diff} Days Left`;
      daysLeftColor = diff <= 3 ? 'var(--red)' : (diff <= 7 ? 'var(--amber)' : 'var(--green)');
    } else if (diff === 0) {
      daysLeftText = 'Today is the Event';
      daysLeftColor = 'var(--gold)';
    }
  }

  // 2. Today's Load
  const todayTasks = tasks.filter(t => t.date === todayStr);
  const pendingToday = todayTasks.filter(t => t.status === 'pending' || t.status === 'in-progress');
  const todayColor = pendingToday.length > 0 ? 'var(--amber)' : 'var(--text-dim)';

  // 3. Delayed/Overdue
  const overdueTasks = tasks.filter(t => t.date < todayStr && t.status !== 'done');
  const overdueColor = overdueTasks.length > 0 ? 'var(--red)' : 'var(--green)';

  const extra = getActiveReservationExtra();
  const hasTasks = extra && extra.timelineTasks && extra.timelineTasks.length > 0;
  const warningHtml = !hasTasks 
    ? `<div style="grid-column: 1 / -1; background:rgba(196,154,60,0.1); border:1px solid rgba(196,154,60,0.3); border-radius:10px; padding:15px; text-align:center; margin-bottom:15px; color:#000; font-weight:700; font-size:14px;">Contract finalization not concluded yet, hence the automatic scheduling of tasks hasn't been done yet.</div>` 
    : '';

  container.innerHTML = `
    ${warningHtml}
    <div style="background:var(--bg3); border:1px solid var(--border); border-radius:10px; padding:15px; display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center;">
      <div style="font-size:11px; color:var(--text-dim); text-transform:uppercase; letter-spacing:1px; margin-bottom:5px;">Countdown</div>
      <div style="font-size:24px; font-weight:700; color:${daysLeftColor};">${daysLeftText}</div>
    </div>
    <div style="background:var(--bg3); border:1px solid var(--border); border-radius:10px; padding:15px; display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center;">
      <div style="font-size:11px; color:var(--text-dim); text-transform:uppercase; letter-spacing:1px; margin-bottom:5px;">Today's Load</div>
      <div style="font-size:24px; font-weight:700; color:${todayColor};">${pendingToday.length} Pending</div>
      <div style="font-size:10px; color:var(--text-dim); margin-top:2px;">out of ${todayTasks.length} scheduled today</div>
    </div>
    <div style="background:var(--bg3); border:1px solid var(--border); border-radius:10px; padding:15px; display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center;">
      <div style="font-size:11px; color:var(--text-dim); text-transform:uppercase; letter-spacing:1px; margin-bottom:5px;">Delayed Activities</div>
      <div style="font-size:24px; font-weight:700; color:${overdueColor};">${overdueTasks.length}</div>
      <div style="font-size:10px; color:var(--text-dim); margin-top:2px;">past due deadline</div>
    </div>
  `;
  container.style.display = 'grid';
}

function renderReservationTimelineView() {
  const summary = document.getElementById('resd-timeline-summary');
  const calEl = document.getElementById('resd-timeline-calendar');
  if (!summary || !calEl) return;
  const res = RESERVATIONS.find(function (r) { return r.id === activeResDetailId; });
  if (!res) {
    summary.textContent = 'Select a reservation first.';
    return;
  }

  // Auto-sync meeting task checkboxes with actual completed meetings in Supabase
  setTimeout(async () => {
    try {
      if (!window.supabaseClient) return;
      const { data: meetings, error } = await window.supabaseClient
        .from('meetings')
        .select('agenda')
        .or(`reservationId.eq.${res.id},reservation_id.eq.${res.id}`)
        .eq('status', 'completed');

      if (error) throw error;

      const extra = getActiveReservationExtra();
      if (!extra || !extra.timelineTasks) return;

      let changed = false;
      if (meetings && meetings.length > 0) {
        const allAgendas = meetings.map(m => (m.agenda || '').toLowerCase()).join(', ');
        extra.timelineTasks.forEach(t => {
          if (t.milestoneId === 'meeting' && t.status !== 'done') {
            if (allAgendas.includes(t.title.toLowerCase())) {
              t.status = 'done';
              t.logAt = new Date().toISOString();
              changed = true;
            }
          }
        });
      }

      // Auto-sync Resource Planning task checkboxes with reservation_exec_sorted in Supabase
      const { data: sortedData } = await window.supabaseClient
        .from('reservation_exec_sorted')
        .select('*')
        .eq('reservation_id', res.id)
        .maybeSingle();

      if (sortedData) {
        if (!_procDataCache[res.id]) {
          _procDataCache[res.id] = { id: res.id, sorted: {}, assignments: {}, poStatuses: {} };
        }
        if (!_procDataCache[res.id].sorted) _procDataCache[res.id].sorted = {};
        _procDataCache[res.id].sorted.food = !!sortedData.sorted_food;
        _procDataCache[res.id].sorted.equipment = !!sortedData.sorted_equipment;
        _procDataCache[res.id].sorted.decoration = !!sortedData.sorted_decoration;
        _procDataCache[res.id].sorted.personnel = !!sortedData.sorted_personnel;
        _procDataCache[res.id].sorted.staff_allocation = !!sortedData.sorted_staff_allocation;
        _procDataCache[res.id].sorted.transportation = !!sortedData.sorted_transportation;

        if (typeof syncResourcePlanningTasksFromSorted === 'function') {
          syncResourcePlanningTasksFromSorted(res.id, _procDataCache[res.id].sorted);
        }
      }

      if (changed) {
        if (typeof saveLogisticsData === 'function') saveLogisticsData();
        renderLogisticsActivities();
        renderLogisticsMilestones(res);
      }
    } catch (e) {
      console.warn('Silent sync failed:', e);
    }
  }, 100);

  const startDate = getReservationPrepStartDate(res);
  const eventDate = normalizeDateKey(res.date);
  summary.textContent = `Coverage: ${startDate} to ${eventDate}. Assign tasks per day and monitor payment milestones.`;

  const tasks = getTimelineTasks();
  renderTimelineAnalytics(res, tasks);

  const extra = getActiveReservationExtra();
  const milestones = (extra && extra.logisticsMilestones) || [];

  const taskEvents = tasks.map(function (t) {
    const m = milestones.find(x => x.id === t.milestoneId);
    const mColor = m ? m.color : '#8a7a5a';

    // Status color logic: if done, use green. if in-progress, use amber. if pending, use milestone color or default.
    let color = mColor;
    const today = new Date().toISOString().split('T')[0];
    if (t.status === 'done') color = '#2d8a4e';
    else if (t.status === 'in-progress') color = '#d97706';
    else if (t.status !== 'done' && t.date && t.date < today) color = '#c0392b'; // Delayed: red

    return {
      id: t.id,
      title: t.title || 'Activity',
      start: t.date,
      allDay: true,
      color: color,
      textColor: '#fff',
      sortOrder: 2,
      editable: true, // Allow dragging activities
      extendedProps: { status: t.status, milestoneId: t.milestoneId, linkTo: t.linkTo }
    };
  });

  const milestoneEvents = milestones.map(m => {
    // Add 1 day to endDate because FullCalendar 'end' is exclusive for all-day events
    let endPlusOne = m.endDate;
    try {
      const d = new Date(m.endDate + 'T00:00:00');
      d.setDate(d.getDate() + 1);
      endPlusOne = d.toISOString().split('T')[0];
    } catch (e) { }

    return {
      id: 'm-' + m.id,
      title: m.label,
      start: m.startDate,
      end: endPlusOne,
      allDay: true,
      color: m.color || 'var(--gold)',
      display: 'block',
      opacity: 0.9,
      sortOrder: 1,
      editable: false, // Don't drag milestones as they are ranges
      className: 'milestone-event-block'
    };
  });

  const coverageEvents = buildReservationCalendarEvents([res], { includeMainEventLabel: false });
  const allEvents = coverageEvents.concat(taskEvents).concat(milestoneEvents);

  if (resTimelineCalendar) {
    try {
      resTimelineCalendar.destroy();
    } catch (e) { }
    resTimelineCalendar = null;
  }

  try {
    resTimelineCalendar = new FullCalendar.Calendar(calEl, {
      initialView: 'dayGridMonth',
      headerToolbar: { left: 'prev,next today', center: 'title', right: 'dayGridMonth,listWeek' },
      height: 520,
      displayEventTime: false,
      editable: true,
      events: allEvents,
      eventOrder: 'sortOrder,start', // Milestones (1) first, then Tasks (2)
      eventClick: function (info) {
        // 1. Check if Event Day is clicked (Execution Planner)
        if (info.event.extendedProps.type === 'event') {
          openExecutionPlanner(info.event.startStr);
          return;
        }

        // 2. Direct task navigation if linked
        if (info.event.extendedProps && info.event.extendedProps.linkTo) {
          window._timelineTaskNavigate(info.event.extendedProps.linkTo, info.event.title);
          return;
        }

        // 3. Fallback Smart Activity Redirect
        if (String(info.event.id).startsWith('auto-')) {
          const t = info.event.title.toLowerCase();

          if (t.includes('food tast') || t.includes('menu')) {
            switchResDetailsTab('food');
          } else if (t.includes('venue assess') || t.includes('ocular')) {
            switchResDetailsTab('venue');
          } else if (t.includes('equipment') || t.includes('procure') || t.includes('inventory')) {
            switchResDetailsTab('procurement');
          } else if (t.includes('design') || t.includes('theme') || t.includes('decor')) {
            switchResDetailsTab('design');
          } else if (t.includes('personnel') || t.includes('staff')) {
            switchResDetailsTab('staff');
          } else {
            // General task without specific tab
            toggleTimelineTaskStatus(info.event.id);
          }
        }
      },
      eventDrop: async function (info) {
        const taskId = info.event.id;
        if (!taskId.startsWith('auto-')) {
          info.revert();
          return;
        }
        const newDate = info.event.startStr;
        const milestoneId = info.event.extendedProps.milestoneId;
        const m = milestones.find(x => x.id === milestoneId);

        if (m && (newDate < m.startDate || newDate > m.endDate)) {
          alert(`Cannot move activity outside milestone range (${m.startDate} to ${m.endDate})`);
          info.revert();
          return;
        }

        // Update database
        await updateActivityDate(taskId, newDate, m ? m.startDate : '1900-01-01', m ? m.endDate : '2100-01-01');
      },
      eventDidMount: function (info) {
        if (info.event.id.startsWith('m-')) {
          info.el.style.borderLeft = '4px solid rgba(255,255,255,0.3)';
          info.el.style.fontWeight = 'bold';
        }
      }
    });
    resTimelineCalendar.render();
    window.resdTimelineCalendarInstance = resTimelineCalendar;
  } catch (e) {
    console.warn('[Admin resTimelineCalendar Safe Catch]:', e);
  }

  renderLogisticsMilestones(res);
  renderLogisticsActivities();
  renderTimelineTaskList();
  const payMilestones = computePaymentMilestones(res);
  renderPaymentTimeline(res, payMilestones);
  renderReschedulePanel(res);
  renderExecutionPanelState();

  // Automatically load & display the Execution Day Strategy planner for the active reservation
  // Ensures the system never displays "No execution plan loaded" as long as a reservation is active
  if (res) {
    const plannerPanel = document.getElementById('resd-execution-planner');
    if (plannerPanel) plannerPanel.style.display = 'block';
    openExecutionPlanner(res.date || normalizeDateKey(new Date()), { noScroll: true });
  }
}

window._initialRescheduleValues = null;

function renderReschedulePanel(res) {
  const dateEl = document.getElementById('resd-resched-date');
  if (!dateEl) return;
  const todayStr = normalizeDateKey(new Date());
  const timeStartEl = document.getElementById('resd-resched-time-start');
  const timeEndEl = document.getElementById('resd-resched-time-end');
  const dpEl = document.getElementById('resd-resched-dp');
  const reasonEl = document.getElementById('resd-resched-reason');

  // Populate Current Locked Fields
  const cDateEl = document.getElementById('resd-resched-current-date');
  const cTimeEl = document.getElementById('resd-resched-current-time');
  const cDpEl = document.getElementById('resd-resched-current-dp');

  const to24hTimeStr = (str) => {
    if (!str) return '';
    str = String(str).trim();
    if (/^\d{2}:\d{2}$/.test(str)) return str;
    const m = str.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)?$/i);
    if (!m) return '';
    let h = parseInt(m[1], 10);
    const min = m[2];
    const ampm = (m[3] || '').toUpperCase();
    if (ampm === 'PM' && h < 12) h += 12;
    if (ampm === 'AM' && h === 12) h = 0;
    return String(h).padStart(2, '0') + ':' + min;
  };

  let tStart = '', tEnd = '';
  if (res.time) {
    const parts = res.time.split(/[--—]| to /i).map(p => p.trim());
    tStart = parts[0] || '';
    tEnd = parts[1] || '';
  }

  if (cDateEl) cDateEl.value = res.date || '—';
  if (cTimeEl) cTimeEl.value = res.time || (tStart && tEnd ? tStart + ' - ' + tEnd : '—');
  if (cDpEl) cDpEl.value = res.downpaymentDueDate || '—';

  if (dateEl) { dateEl.value = res.date || ''; dateEl.min = todayStr; }
  if (timeStartEl) timeStartEl.value = to24hTimeStr(tStart);
  if (timeEndEl) timeEndEl.value = to24hTimeStr(tEnd);
  if (dpEl) { dpEl.value = res.downpaymentDueDate || ''; dpEl.min = todayStr; }
  if (reasonEl) reasonEl.value = '';

  window._initialRescheduleValues = {
    date: dateEl ? dateEl.value : '',
    timeStart: timeStartEl ? timeStartEl.value : '',
    timeEnd: timeEndEl ? timeEndEl.value : '',
    dp: dpEl ? dpEl.value : ''
  };

  validateRescheduleForm();
}

function validateRescheduleForm() {
  const dateEl = document.getElementById('resd-resched-date');
  if (!dateEl) return;
  const timeStartEl = document.getElementById('resd-resched-time-start');
  const timeEndEl = document.getElementById('resd-resched-time-end');
  const dpEl = document.getElementById('resd-resched-dp');
  const reasonEl = document.getElementById('resd-resched-reason');
  const confirmBtn = document.getElementById('resd-resched-confirm-btn');
  const discardBtn = document.getElementById('resd-resched-discard-btn');

  if (!window._initialRescheduleValues || !confirmBtn || !discardBtn) return;

  const curDate = dateEl ? dateEl.value : '';
  const curStart = timeStartEl ? timeStartEl.value : '';
  const curEnd = timeEndEl ? timeEndEl.value : '';
  const curDp = dpEl ? dpEl.value : '';
  const reason = reasonEl ? reasonEl.value.trim() : '';

  const init = window._initialRescheduleValues;

  const dateChanged = curDate !== init.date && curDate !== '';
  const dpChanged = curDp !== init.dp && curDp !== '';
  const timeStartChanged = curStart !== init.timeStart;
  const timeEndChanged = curEnd !== init.timeEnd;
  const timeChanged = timeStartChanged || timeEndChanged;

  // Time range must have BOTH start and end filled if time range is changed
  let timeValid = true;
  if (timeChanged) {
    timeValid = (curStart !== '' && curEnd !== '');
  }

  const isChanged = dateChanged || dpChanged || timeChanged || (reason !== '');

  // Enable button if downpayment alone, date alone, or time range alone (with both times filled) is changed!
  const isValidToConfirm = isChanged && timeValid && (dateChanged || dpChanged || (timeChanged && curStart && curEnd));

  if (isChanged) {
    discardBtn.disabled = false;
    discardBtn.style.opacity = '1';
    discardBtn.style.cursor = 'pointer';
  } else {
    discardBtn.disabled = true;
    discardBtn.style.opacity = '0.5';
    discardBtn.style.cursor = 'not-allowed';
  }

  if (isValidToConfirm) {
    confirmBtn.disabled = false;
    confirmBtn.style.opacity = '1';
    confirmBtn.style.cursor = 'pointer';
  } else {
    confirmBtn.disabled = true;
    confirmBtn.style.opacity = '0.5';
    confirmBtn.style.cursor = 'not-allowed';
  }
}
window.validateRescheduleForm = validateRescheduleForm;


function discardRescheduleForm() {
  if (!window._initialRescheduleValues) return;
  const res = RESERVATIONS.find(r => r.id === activeResDetailId);
  if (res) renderReschedulePanel(res);
}
window.discardRescheduleForm = discardRescheduleForm;

async function executeReschedule() {
  const res = RESERVATIONS.find(function (r) { return r.id === activeResDetailId; });
  if (!res) return;

  const newDateStr = document.getElementById('resd-resched-date').value;
  const startStr = document.getElementById('resd-resched-time-start').value;
  const endStr = document.getElementById('resd-resched-time-end').value;
  const newTimeStr = `${startStr} - ${endStr}`;
  const newDpStr = document.getElementById('resd-resched-dp').value;
  const reason = document.getElementById('resd-resched-reason').value.trim();

  if (!newDateStr) return alert('Please select a new event date.');
  if (!startStr || !endStr) return alert('Please provide a valid time range.');
  if (!reason) return alert('Please provide a reason for the rescheduling.');

  const oldDateStr = res.date;
  const extra = getActiveReservationExtra();

  const statusMap = {};
  if (extra && extra.timelineTasks) {
    extra.timelineTasks.forEach(t => { if (t.status !== 'pending') statusMap[t.title] = t.status; });
  }

  const oldResPayload = { date: res.date, time: res.time, downpaymentDueDate: res.downpaymentDueDate };
  res.date = newDateStr;
  res.time = newTimeStr;
  res.downpaymentDueDate = newDpStr;

  // Fetch meetings for this reservation directly from Supabase
  let resMeetings = [];
  try {
    const { collection, query, where, getDocs } = window.firebaseFns;
    const mtSnap = await getDocs(query(
      collection(window.firebaseDB, 'meetings'),
      where('reservationId', '==', res.id)
    ));
    mtSnap.docs.forEach(d => {
      const data = d.data();
      if (data.status !== 'cancelled' && data.agenda && data.agenda.trim()) {
        resMeetings.push({ id: d.id, ...data });
      }
    });
  } catch (e) {
    console.warn('Could not fetch meetings for timeline regeneration:', e);
  }

  const genResult = generateAutoLogisticsMilestones(res, resMeetings);

  if (extra) {
    // Always fully regenerate milestones so they spread evenly across the new date range.
    // (Simply shifting dates by a delta leaves milestone proportions wrong for the new span.)
    extra.logisticsMilestones = genResult.milestones;
    extra.timelineTasks = genResult.tasks;

    // Re-apply any previously completed/in-progress task statuses
    if (Object.keys(statusMap).length > 0) {
      extra.timelineTasks.forEach(t => {
        if (statusMap[t.title]) t.status = statusMap[t.title];
      });
    }

    // Warn if any tasks landed on weekends
    let weekendCount = 0;
    extra.timelineTasks.forEach(t => {
      const dayOfWeek = new Date(t.date + 'T00:00:00').getDay();
      if (dayOfWeek === 0 || dayOfWeek === 6) weekendCount++;
    });
    if (weekendCount > 0) {
      alert(`Note: ${weekendCount} tasks landed on weekends after rescheduling. Please review the calendar.`);
    }

    await saveLogisticsData();
  }

  // Auto-update final payment due date = new event date - 3 days
  let newFinalPaymentDueDate = null;
  if (newDateStr) {
    const evtD = new Date(newDateStr + 'T00:00:00');
    if (!isNaN(evtD.getTime())) {
      const fpD = new Date(evtD);
      fpD.setDate(fpD.getDate() - 3);
      newFinalPaymentDueDate = fpD.toISOString().split('T')[0];
    }
  }

  const payload = {
    date: newDateStr,
    time: newTimeStr,
    downpaymentDueDate: newDpStr,
    ...(newFinalPaymentDueDate ? {
      finalPaymentDueDate: newFinalPaymentDueDate,
      final_payment_due_date: newFinalPaymentDueDate
    } : {})
  };
  try {
    const { doc, updateDoc } = window.firebaseFns;
    await updateDoc(doc(window.firebaseDB, 'reservations', res.id), payload);
    Object.assign(res, payload);

    // Also update Supabase final payment due date if it was set
    if (newFinalPaymentDueDate && window.supabaseClient) {
      try {
        await window.supabaseClient.from('reservations').update({
          final_payment_due_date: newFinalPaymentDueDate
        }).eq('id', res.id);
        // Also update reservation_payments final record
        await window.supabaseClient.from('reservation_payments').update({
          due_date: newFinalPaymentDueDate
        }).eq('reservation_id', res.id).eq('payment_type', 'final');
      } catch (_spErr) {
        console.warn('[Reschedule] Could not update Supabase final payment due date:', _spErr);
      }
    }

    const logs = ensureReservationLifecycleLogs(res);
    logs.push({
      id: 'log-' + Date.now() + '-' + Math.random().toString(16).slice(2, 6),
      category: 'system',
      message: `Reservation rescheduled from ${oldDateStr} to ${newDateStr}. Reason: ${reason}${newFinalPaymentDueDate ? ` Final payment due date updated to ${newFinalPaymentDueDate}.` : ''}`,
      at: new Date().toISOString()
    });
    await updateDoc(doc(window.firebaseDB, 'reservations', res.id), { activityLogs: logs });
    showToast('Reservation successfully rescheduled.');
    renderReservationTimelineView();
  } catch (e) {
    console.error(e);
    alert('Failed to save reschedule changes. Check console.');
    Object.assign(res, oldResPayload);
  }
}

function setExecText(id, txt) {
  const el = document.getElementById(id);
  if (el) el.textContent = txt;
}

function setExecStatus(msg) {
  setExecText('res-exec-status', msg);
}

function initExecutionMap() {
  const el = document.getElementById('res-exec-map');
  if (!el || typeof L === 'undefined') return false;
  if (!resExecMap) {
    resExecMap = L.map(el, { zoomControl: true, attributionControl: false }).setView([14.5995, 120.9842], 12);
    L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}', { maxZoom: 19 }).addTo(resExecMap);
  }
  return true;
}

async function geocodeVenueAddress(query) {
  const url = 'https://nominatim.openstreetmap.org/search?format=json&q=' + encodeURIComponent(query) + '&limit=1&countrycodes=ph';
  const r = await fetch(url);
  const data = await r.json();
  if (!data || !data.length) return null;
  return [parseFloat(data[0].lat), parseFloat(data[0].lon)];
}

async function fetchRouteLL(fromLL, toLL) {
  const url = 'https://router.project-osrm.org/route/v1/driving/' + fromLL[1] + ',' + fromLL[0] + ';' + toLL[1] + ',' + toLL[0] + '?overview=full&geometries=geojson';
  const r = await fetch(url);
  if (!r.ok) return null;
  const data = await r.json();
  if (!data.routes || !data.routes.length) return null;
  const route = data.routes[0];
  return {
    coords: route.geometry.coordinates.map(function (c) { return [c[1], c[0]]; }),
    distanceKm: (route.distance || 0) / 1000,
    etaMin: (route.duration || 0) / 60
  };
}

function getActiveReservationVenue() {
  const res = RESERVATIONS.find(function (r) { return r.id === activeResDetailId; });
  if (!res) return null;
  return res.venue || res.venueAddress || res.eventVenue || null;
}

function getActiveExecutionState() {
  const extra = getActiveReservationExtra();
  if (!extra) return null;
  if (!extra.execution) {
    extra.execution = {
      liveStatus: 'idle',
      delayReason: '',
      activityLogs: [],
      lastLocationLogAt: null,
      selectedPhaseId: 'departure',
      phasedPlan: null
    };
  }
  if (!Array.isArray(extra.execution.activityLogs)) extra.execution.activityLogs = [];
  if (!extra.execution.selectedPhaseId) extra.execution.selectedPhaseId = 'departure';
  return extra.execution;
}

function getExecutionDateKey() {
  const override = (window.executionDayOverrides || {})[activeResDetailId];
  if (override && override.forcedDate) return override.forcedDate;
  const res = RESERVATIONS.find(function (r) { return r.id === activeResDetailId; });
  return normalizeDateKey((res && res.date) || new Date().toISOString().split('T')[0]);
}

