// ====================================================================
// PAX-ADJUSTED WEIGHTED MOVING AVERAGE (PA-WMA) DEMAND FORECASTING ENGINE
// Combines Monthly Reservation Count (B_{y,m}), Monthly Average Pax (P_{y,m}),
// and Auto-Scaling Linear Recency Weights (w_i = 1, 2, ..., n)
// Academic References:
//   - Stevenson, W. J. (2021). Operations Management (14th ed., Ch. 3: Forecasting).
//   - Heizer, J., Render, B., & Munson, C. (2020). Operations Management (13th ed., Ch. 4).
//   - Hyndman, R. J., & Athanasopoulos, G. (2021). Forecasting: Principles and Practice (3rd ed.).
//   - Lewis, C. D. (1982). Industrial and Business Forecasting Methods (75% Accuracy / 25% MAPE Standard).
// ====================================================================
function calculateWeightedMonthlyDemandForecast(reservations, targetYear) {
  const MONTH_LABELS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const resList = (reservations && reservations.length) ? reservations : (window.RESERVATIONS || []);

  // Filter exclusively for completed reservations from 2022 onwards (auto-scales to new years)
  const completedList = resList.filter(r => {
    const st = String(r.status || '').toLowerCase();
    const ops = String(r.ops_status || '').toLowerCase();
    const isComp = st === 'completed' || ops === 'completed';
    if (!isComp) return false;
    const d = (typeof parseResDate === 'function') ? parseResDate(r) : null;
    if (!d) return false;
    const y = d.getFullYear();
    return y >= 2022;
  });

  // Group completed bookings and guest counts (Pax) by calendar year and month [0..11]
  const countsByYear = {};
  const paxSumsByYear = {};
  const avgPaxByYear = {};

  completedList.forEach(r => {
    const d = (typeof parseResDate === 'function') ? parseResDate(r) : null;
    if (!d) return;
    const y = d.getFullYear();
    if (y < 2022) return;
    const m = d.getMonth();
    const paxVal = Number(r.pax || r.guest_count || r.guests || 100) || 100;
    if (!countsByYear[y]) {
      countsByYear[y] = new Array(12).fill(0);
      paxSumsByYear[y] = new Array(12).fill(0);
    }
    countsByYear[y][m]++;
    paxSumsByYear[y][m] += paxVal;
  });

  const allRecordedYears = Object.keys(countsByYear).map(Number).sort((a, b) => a - b);
  allRecordedYears.forEach(y => {
    avgPaxByYear[y] = new Array(12).fill(0);
    for (let m = 0; m < 12; m++) {
      const cnt = countsByYear[y][m];
      avgPaxByYear[y][m] = cnt > 0 ? Math.round(paxSumsByYear[y][m] / cnt) : 0;
    }
  });

  const now = new Date();
  const curYear = Number(targetYear) || now.getFullYear();

  // Dynamic Pax-Adjusted Weighted Moving Average (PA-WMA) for ANY target year y and month m:
  // 1. Auto-discovers all historical years prior to y with recorded data: y_1 < y_2 < ... < y_n
  // 2. Auto-assigns linear recency weights: w_i = i (1, 2, ..., n), Total Weight W = n(n+1)/2
  // 3. Weighted Booking Average: B_bar = (Sum w_i * B_{i,m}) / W
  // 4. Weighted Pax Average:     P_bar = (Sum w_i * P_{i,m}) / W
  // 5. Pax Scale Adjustment:     A_m   = (P_bar - 100) / 100   (relative to 100-Pax standard baseline)
  // 6. Final Forecast:           Y_hat = round(B_bar + A_m)
  function getForecastDetailsForYearMonth(y, m) {
    const pastYears = allRecordedYears.filter(yr => yr < y && countsByYear[yr] && countsByYear[yr][m] > 0);
    if (pastYears.length === 0) {
      const fallbackCnt = (countsByYear[y] && countsByYear[y][m]) ? countsByYear[y][m] : 0;
      const fallbackPax = (avgPaxByYear[y] && avgPaxByYear[y][m]) ? avgPaxByYear[y][m] : 100;
      return { forecast: fallbackCnt, weightedBookings: fallbackCnt, weightedPax: fallbackPax, paxAdjustment: 0, weights: [1], totalWeight: 1, pastYears: [] };
    }

    let wSum = 0;
    let wpDenominator = 0;
    let wpbNumerator = 0;
    let pWeightedSum = 0;
    const yrWeights = [];

    for (let i = 0; i < pastYears.length; i++) {
      const yr = pastYears[i];
      const w = i + 1; // Auto-scaling weight: 1, 2, 3, 4, ...
      const bVal = countsByYear[yr][m];
      const pVal = avgPaxByYear[yr][m] || 100;
      const wp = w * pVal; // Combined Recency x Average Pax Weight
      yrWeights.push(w);
      wSum += w;
      wpDenominator += wp;
      wpbNumerator += wp * bVal;
      pWeightedSum += w * pVal;
    }

    const weightedBookings = wpDenominator > 0 ? (wpbNumerator / wpDenominator) : 0;
    const weightedPax = wSum > 0 ? (pWeightedSum / wSum) : 100;
    const paxAdjustment = 0;
    const forecast = Math.max(0, Math.round(weightedBookings));

    return {
      forecast,
      weightedBookings: Number(weightedBookings.toFixed(2)),
      weightedPax: Math.round(weightedPax),
      paxAdjustment: Number(paxAdjustment.toFixed(2)),
      weights: yrWeights,
      totalWeight: wSum,
      pastYears
    };
  }

  function getForecastForYearMonth(y, m) {
    return getForecastDetailsForYearMonth(y, m).forecast;
  }

  function getForecastPaxForYearMonth(y, m) {
    return getForecastDetailsForYearMonth(y, m).weightedPax;
  }

  const forecasts = new Array(12).fill(0);
  const forecastPax = new Array(12).fill(100);
  for (let m = 0; m < 12; m++) {
    const det = getForecastDetailsForYearMonth(curYear, m);
    forecasts[m] = det.forecast;
    forecastPax[m] = det.weightedPax;
  }

  // Baseline years strictly before curYear (auto-scales as new years are added to database)
  const baselineYears = allRecordedYears.filter(yr => yr < curYear);
  const activeYears = baselineYears.concat(allRecordedYears.includes(curYear) ? [curYear] : [curYear]);
  const weights = baselineYears.map((_, i) => i + 1);
  const totalWeight = weights.reduce((s, w) => s + w, 0) || 1;

  const meta = {
    forecasts,
    forecastPax,
    countsByYear,
    avgPaxByYear,
    baselineYears,
    activeYears,
    weights,
    totalWeight,
    completedCount: completedList.length,
    getForecastForYearMonth,
    getForecastPaxForYearMonth,
    getForecastDetailsForYearMonth
  };
  window._lastForecastMeta = meta;
  return meta;
}
window.calculateWeightedMonthlyDemandForecast = calculateWeightedMonthlyDemandForecast;

// Objective Data-Driven Busy-Month Classification:
// A month is classified as Busy if projected demand is 6 or more bookings (Peak Volume Threshold = 6)
function isForecastBusyMonth(mIdx, fc) {
  const meta = window._lastForecastMeta;
  const numFc = Number(fc !== undefined ? fc : (meta && meta.forecasts ? meta.forecasts[mIdx] : 0));
  return numFc >= 6;
}
window.isForecastBusyMonth = isForecastBusyMonth;

// Forecast accuracy using standard Mean Absolute Percentage Error (MAPE) Complement:
// Absolute Error = |Actual - Forecast|
// Monthly Accuracy % = max(0, round(100% - (|Actual - Forecast| / Actual * 100%)))
// Benchmark: 75% Accuracy (MAPE <= 25%, Lewis 1982)
function calcForecastAccuracy(fc, act) {
  const a = Number(act) || 0;
  const f = Number(fc) || 0;
  if (a === 0 && f === 0) return 100;
  if (a === 0) return Math.max(0, 100 - f * 15);
  const err = Math.abs(a - f);
  const ape = (err / a) * 100;
  return Math.max(0, Math.min(100, Math.round(100 - ape)));
}
window.calcForecastAccuracy = calcForecastAccuracy;


let _forecastAnnualBreakdownYear = 2026;

function stepForecastAnnualBreakdownYear(delta) {
  const maxYear = Math.max(2026, new Date().getFullYear());
  _forecastAnnualBreakdownYear += delta;
  if (_forecastAnnualBreakdownYear < 2022) _forecastAnnualBreakdownYear = 2022;
  if (_forecastAnnualBreakdownYear > maxYear) _forecastAnnualBreakdownYear = maxYear;
  renderForecastAnnualBreakdownList();
}
window.stepForecastAnnualBreakdownYear = stepForecastAnnualBreakdownYear;

function renderForecastAnnualBreakdownList(cache) {
  const yearEl = document.getElementById('forecast-annual-breakdown-year');
  const container = document.getElementById('forecast-annual-breakdown-list');
  if (!container) return;
  if (yearEl) yearEl.textContent = String(_forecastAnnualBreakdownYear);

  const reservations = (cache && cache.reservations) ? cache.reservations : (window.RESERVATIONS || []);
  const MONTH_FULL = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  const yr = _forecastAnnualBreakdownYear;

  const { countsByYear, avgPaxByYear, getForecastForYearMonth } = calculateWeightedMonthlyDemandForecast(reservations, yr);
  const actuals = countsByYear[yr] || new Array(12).fill(0);
  const avgPaxs = avgPaxByYear[yr] || new Array(12).fill(0);

  let html = '';
  MONTH_FULL.forEach((mName, mIdx) => {
    const act = actuals[mIdx];
    const avgP = avgPaxs[mIdx];
    const fc = (typeof getForecastForYearMonth === 'function')
      ? getForecastForYearMonth(yr, mIdx)
      : 0;

    const isFuture = (yr >= 2026 && mIdx >= 10 && act === 0);
    let rightBadge = '';

    if (isFuture) {
      rightBadge = '<span style="color:var(--text-dim); font-size:11px; font-style:italic;">&mdash; (Upcoming)</span>';
    } else if (yr === 2022) {
      rightBadge = '<span style="color:var(--gold); font-size:11px; font-weight:700;">' + act + ' Bookings &bull; ' + avgP + ' Avg Pax (Baseline)</span>';
    } else {
      const acc = calcForecastAccuracy(fc, act);
      // 75% Standard Accuracy Threshold (Lewis, 1982): >=75% Green, 60-74% Gold (Fluctuation), <60% Red
      const accColor = acc >= 75 ? '#2d8a4e' : (acc >= 60 ? 'var(--gold)' : '#ef4444');
      rightBadge = '<span style="font-weight:800; font-size:13px; color:' + accColor + ';">' + acc + '%</span>';
    }

    const subText = isFuture
      ? 'Forecast: <strong>' + fc + '</strong> &bull; Actual: <em>0</em>'
      : (yr === 2022
        ? 'Recorded Events: <strong>' + act + '</strong>'
        : 'Forecast: <strong>' + fc + '</strong> &bull; Actual: <strong>' + act + '</strong> &bull; Avg Pax: <strong>' + avgP + '</strong>');

    html += '<div style="display:flex; justify-content:space-between; align-items:center; padding:9px 12px; border-bottom:1px solid rgba(255,255,255,0.05); font-size:12px;">'
      + '<div>'
      + '<span style="font-weight:700; color:var(--cream);">' + mName + ' ' + yr + '</span>'
      + '<span style="color:var(--text-dim); font-size:11px; margin-left:10px;">' + subText + '</span>'
      + '</div>'
      + '<div>' + rightBadge + '</div>'
      + '</div>';
  });

  container.innerHTML = html;
}
window.renderForecastAnnualBreakdownList = renderForecastAnnualBreakdownList;

function renderForecastingDashboard(cache) {
  const reservations = (cache && cache.reservations) ? cache.reservations : (window.RESERVATIONS || []);
  if (typeof renderForecastPastDataTable === 'function') renderForecastPastDataTable(cache);
  const MONTH_LABELS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  
  const key = 'fc-acc';
  const filter = _adminAnalyticsFilters[key] || { anchorYear: new Date().getFullYear(), anchorMonth: new Date().getMonth(), rangeMonths: 12 };
  const curYear = filter.anchorYear || 2026;

  // 1. Calculate Pax-Adjusted Weighted Moving Average across all recorded historical years
  const { forecasts, forecastPax, countsByYear, baselineYears, activeYears, weights, totalWeight, completedCount } = calculateWeightedMonthlyDemandForecast(reservations, curYear);
  const curYearActuals = countsByYear[curYear] || new Array(12).fill(0);
  const prevYearActuals = countsByYear[curYear - 1] || new Array(12).fill(0);

  // Directions vs prior year actual demand
  const directions = forecasts.map(function (fc, mIdx) {
    return Math.round(fc - prevYearActuals[mIdx]);
  });

  // Season classification: months with forecast >= 6 are "Busy" (January and Ber Months: Sep, Oct, Nov, Dec)
  const BUSY_THRESHOLD = 6;
  const isBusy = forecasts.map(function (fc, i) { return isForecastBusyMonth(i, fc); });

  // ─── SEASON BANNER ───
  const prof = getForecastSeasonProfile(forecasts, isBusy);
  const titleEl = document.getElementById('forecast-season-title');
  const copyEl = document.getElementById('forecast-season-copy');
  const badgeEl = document.getElementById('forecast-season-badge');
  const flagsWrap = document.getElementById('forecast-anticipation-flags');
  if (titleEl) titleEl.textContent = prof.title;
  if (copyEl) copyEl.textContent = prof.copy;
  if (badgeEl) {
    badgeEl.textContent = prof.badge;
    badgeEl.className = 'badge ' + prof.badgeClass;
    badgeEl.style.fontSize = '11px';
    badgeEl.style.alignSelf = 'center';
  }
  if (flagsWrap) flagsWrap.style.display = prof.showAnticipationFlags ? '' : 'none';

  // ─── NEXT SEASON OUTLOOK ───
  try {
    const FULL_MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
    const nowD = new Date();
    const nxM = (nowD.getMonth() + 1) % 12;
    const nxY = nxM === 0 ? nowD.getFullYear() + 1 : nowD.getFullYear();
    const nxFc = forecasts[nxM];
    const nxBusy = isBusy[nxM];
    const nTitle = document.getElementById('forecast-next-season-title');
    const nCopy = document.getElementById('forecast-next-season-copy');
    const nBadge = document.getElementById('forecast-next-season-badge');
    if (nTitle) nTitle.textContent = FULL_MONTHS[nxM] + ' ' + nxY + ' : ' + (nxBusy ? 'Busy month' : 'Calm month') + ' : ' + nxFc + ' predicted reservations';
    if (nCopy) nCopy.textContent = nxBusy
      ? 'Next month is projected to be busy with about ' + nxFc + ' reservations (Threshold >= 6). Confirm staff availability, complete equipment routine checks, and secure supplier stock ahead of time.'
      : 'Next month is projected to be calm with about ' + nxFc + ' reservations (Threshold < 6). Good window for maintenance, staff training, and supplier negotiations.';
    if (nBadge) {
      nBadge.textContent = nxBusy ? 'Busy' : 'Calm';
      nBadge.className = 'badge ' + (nxBusy ? 'confirmed' : 'low');
      nBadge.style.fontSize = '11px';
      nBadge.style.alignSelf = 'center';
    }
  } catch (_nxErr) { console.warn('[NextSeasonOutlook]', _nxErr); }

  // ─── STAT CARDS ───
  var busyCount = isBusy.filter(Boolean).length;
  const qStart = filter.anchorMonth || 0;
  var nextQtrTotal = forecasts[(qStart) % 12] + forecasts[(qStart + 1) % 12] + forecasts[(qStart + 2) % 12];

  var el = document.getElementById('fc-stat-confidence');
  const baseYrCount = baselineYears.length || 4;
  if (el) el.textContent = baseYrCount + ' yrs (' + completedCount + ' Bookings)';
  el = document.getElementById('fc-stat-confidence-sub');
  if (el && baselineYears.length) {
    el.textContent = 'Pax-Adjusted WMA (' + baselineYears[0] + '-' + baselineYears[baselineYears.length - 1] + ' Baseline)';
  }

  el = document.getElementById('fc-stat-peak-share');
  if (el) el.textContent = busyCount + ' / 12 mo.';
  el = document.getElementById('fc-stat-peak-sub');
  if (el) el.textContent = 'Busy threshold: Forecast >= ' + BUSY_THRESHOLD + ' bookings';

  el = document.getElementById('fc-stat-n90');
  if (el) el.textContent = Math.round(nextQtrTotal);
  el = document.getElementById('fc-stat-n90-sub');
  const nextQtrEndMonth = (qStart + 2) % 12;
  if (el) el.textContent = 'Projected bookings next quarter (' + MONTH_LABELS[qStart] + '-' + MONTH_LABELS[nextQtrEndMonth] + ' ' + curYear + ')';

  // ─── CHART 1: Monthly Weighted Forecast vs Actual ───
  var ctxLine = document.getElementById('forecast-demand-chart');
  if (ctxLine && window.Chart) {
    if (window.forecastDemandChartInst) window.forecastDemandChartInst.destroy();
    window.forecastDemandChartInst = new Chart(ctxLine, {
      type: 'line',
      data: {
        labels: MONTH_LABELS,
        datasets: [
          {
            label: curYear + ' Calculated Forecast (PA-WMA)',
            data: forecasts,
            borderColor: '#c49a3c',
            backgroundColor: 'rgba(196,154,60,0.15)',
            fill: true,
            tension: 0.35,
            borderWidth: 2.5,
            pointBackgroundColor: forecasts.map(function (fc, i) { return isBusy[i] ? '#c49a3c' : '#7c6fcd'; }),
            pointRadius: 5,
          },
          {
            label: (curYear - 1) + ' Actual Demand',
            data: prevYearActuals,
            borderColor: 'rgba(255,255,255,0.4)',
            borderDash: [4, 4],
            fill: false,
            tension: 0.35,
            borderWidth: 1.5,
            pointRadius: 4,
            pointBackgroundColor: '#2d8a4e',
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { labels: { color: '#a89070', font: { family: "'DM Sans',sans-serif", size: 11 } } },
          tooltip: {
            callbacks: {
              label: function (ctx) {
                var dir = directions[ctx.dataIndex];
                if (ctx.datasetIndex === 0) {
                  var sign = dir > 0 ? '+' : '';
                  return ' Forecast: ' + ctx.raw + ' bookings (' + sign + Math.round(dir) + ' vs ' + (curYear - 1) + ') • Avg Pax: ' + (forecastPax[ctx.dataIndex] || 100);
                }
                return ' ' + (curYear - 1) + ' Actual: ' + ctx.raw + ' bookings';
              }
            }
          }
        },
        scales: {
          x: { ticks: { color: '#a89070' }, grid: { display: false } },
          y: {
            ticks: { color: '#a89070', stepSize: 1 },
            grid: { color: 'rgba(255,255,255,0.06)' },
            beginAtZero: true,
            title: { display: true, text: 'Bookings / month', color: '#a89070', font: { size: 10 } }
          }
        }
      }
    });
  }

  // ─── ANNUAL ACCURACY BREAKDOWN LIST ───
  renderForecastAnnualBreakdownList(cache);

  // ─── CHART 3: Year-over-Year Historical Comparison ───
  var ctxPace = document.getElementById('forecast-weekly-pace-chart');
  if (ctxPace && window.Chart) {
    if (window.forecastWeeklyPaceChartInst) window.forecastWeeklyPaceChartInst.destroy();
    const paceColors = ['#6b7280', '#3b82f6', '#10b981', '#c49a3c', '#a855f7', '#ec4899'];
    const paceDatasets = activeYears.map((yr, idx) => ({
      label: String(yr),
      data: countsByYear[yr] || new Array(12).fill(0),
      backgroundColor: paceColors[idx % paceColors.length],
      borderRadius: 3
    }));
    window.forecastWeeklyPaceChartInst = new Chart(ctxPace, {
      type: 'bar',
      data: {
        labels: MONTH_LABELS,
        datasets: paceDatasets
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          x: { grid: { display: false }, ticks: { color: '#a89070', font: { family: "'DM Sans',sans-serif", size: 10 } } },
          y: { beginAtZero: true, grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#a89070', stepSize: 1 } }
        },
        plugins: {
          legend: { position: 'top', labels: { color: '#f5ebd9', font: { family: "'DM Sans',sans-serif", size: 10 } } }
        }
      }
    });
  }

  // ─── CHART 4: Dynamic Auto-Scaling Model Weight Distribution ───
  var ctxLead = document.getElementById('forecast-leadtime-chart');
  if (ctxLead && window.Chart) {
    if (window.forecastLeadtimeChartInst) window.forecastLeadtimeChartInst.destroy();
    const weightColors = ['#6b7280', '#3b82f6', '#10b981', '#c49a3c', '#a855f7', '#ec4899'];
    const dynamicLabels = baselineYears.map((yr, idx) => {
      const w = weights[idx];
      const pct = Math.round((w / totalWeight) * 100);
      return `${yr} (${pct}% : w=${w})`;
    });
    const dynamicPctData = weights.map(w => Math.round((w / totalWeight) * 100));
    window.forecastLeadtimeChartInst = new Chart(ctxLead, {
      type: 'doughnut',
      data: {
        labels: dynamicLabels,
        datasets: [{
          data: dynamicPctData,
          backgroundColor: baselineYears.map((_, idx) => weightColors[idx % weightColors.length]),
          borderWidth: 0
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        cutout: '60%',
        plugins: {
          legend: { position: 'bottom', labels: { color: '#a89070', font: { family: "'DM Sans',sans-serif", size: 10 } } }
        }
      }
    });
  }

  // ─── TABLE: Monthly Forecast Breakdown ───
  const tbody = document.getElementById('forecast-monthly-table-body');
  if (tbody) {
    tbody.innerHTML = MONTH_LABELS.map(function (mName, mIdx) {
      const fc = forecasts[mIdx];
      const actPrev = prevYearActuals[mIdx];
      const dir = directions[mIdx];
      const busy = isBusy[mIdx];
      const sign = dir > 0 ? '+' : '';
      const rec = busy
        ? 'Peak window (&ge;6): Full staffing, early supplier lock-in &amp; routine equipment check'
        : 'Calm window (&lt;6): Ideal for equipment maintenance, inventory audit &amp; staff training';
      return `
        <tr>
          <td style="font-weight:700; color:var(--cream);">${mName}</td>
          <td style="font-weight:700; color:#c49a3c;">${Math.round(fc)} <span style="font-size:10px; color:var(--text-dim); font-weight:400;">(~${forecastPax[mIdx]} Pax)</span></td>
          <td style="color:${dir >= 0 ? '#2d8a4e' : '#ef4444'}; font-weight:700;">${sign}${Math.round(dir)}</td>
          <td>${actPrev}</td>
          <td><span class="badge ${busy ? 'confirmed' : 'pending'}" style="font-size:10px;">${busy ? 'Busy' : 'Calm'}</span></td>
          <td style="font-size:11px; color:var(--text-dim);">${rec}</td>
        </tr>`;
    }).join('');
  }

  // ─── NARRATIVE BLOCK ───
  const narr = document.getElementById('forecast-narrative-block');
  if (narr) {
    const baseRange = baselineYears.length ? `${baselineYears[0]}-${baselineYears[baselineYears.length - 1]}` : '2022-2025';
    const wListStr = weights.join(', ');
    narr.innerHTML = `
      Based on <strong>${completedCount} historical completed events</strong> across ${baselineYears.length} baseline years (${baseRange}), the <strong>Pax-Adjusted Weighted Moving Average (PA-WMA)</strong> projects <strong>${busyCount} Busy Months</strong> for ${curYear} (<strong>January, September, October, November, and December</strong>).
      <br><br>
      <strong>1. Dynamic Auto-Scaling Weights:</strong> For <em>n</em> historical years ordered from oldest (<em>i = 1</em>) to newest (<em>i = n</em>), the system automatically assigns linear recency weight \(w_i = i\) (currently \(w = [${wListStr}]\), total weight \(W = \frac{n(n+1)}{2} = ${totalWeight}\)). When a new calendar year begins, the engine automatically appends the next weight \(w_{n+1} = n + 1\) without manual code modification.
      <br>
      <strong>2. Mathematical Formula:</strong> For every calendar month <em>m</em>, the model weights each historical year by both its linear recency weight \(w_i\) and its Average Pax \(P_{i,m}\), yielding the Doubly-Weighted Moving Average \(\hat{Y}_m = \text{round}\left(\frac{\sum_{i=1}^{n} (w_i \cdot P_{i,m} \cdot B_{i,m})}{\sum_{i=1}^{n} (w_i \cdot P_{i,m})}\right)\).
      <br>
      <strong>3. Busy Threshold (&ge; 6 Bookings) &amp; 75% Accuracy Standard:</strong> Months with \(\hat{Y}_m \ge 6\) are classified as <strong>Busy Seasons</strong>. Forecast accuracy is evaluated against the <strong>75% empirical benchmark</strong> (MAPE &le; 25%; Lewis, 1982; Stevenson, 2021; Hyndman &amp; Athanasopoulos, 2021).
    `;
  }

  // Also render accuracy card
  renderForecastAccuracyCard(cache);
}
window.renderForecastingDashboard = renderForecastingDashboard;

function parseResDate(r) {
  if (!r) return null;
  const dVal = r.date || r.createdAt || r.created_at || r.downpayment_paid_at || r.paid_at;
  if (!dVal) return null;
  const parsed = new Date(dVal);
  if (!isNaN(parsed.getTime())) return parsed;
  return null;
}

function getResDateStr(r) {
  const d = parseResDate(r);
  if (!d) return '';
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
}

function getResMonthKey(r) {
  const d = parseResDate(r);
  if (!d) return null;
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
}

function filterResDate(r, months) {
  const key = getResMonthKey(r);
  if (!key) return false;
  return months.some(m => (typeof m === 'string' ? m : (m && m.key)) === key);
}

// ==================== SMARTSERVE ANALYTICS ARCHITECTURE =============
// ====================================================================

var _insightsDataCache = null;
var _insightsIsLoading = false;
var _insightsNeedsReRender = false;
var _currentPopularityCategory = 'meals';
var _currentExpensesKindFilter = 'all';

window._insightsDataCache = null;
window._insightsIsLoading = false;
window._insightsNeedsReRender = false;

async function fetchInsightsLiveSources() {
  if (_insightsDataCache) return _insightsDataCache;
  const sb = window.supabaseClient;
  const cache = {
    reservations: [],
    foodtaste: [],
    incidents: [],
    execBatchIncidents: [],
    execPlans: [],
    inventory: [],
    maintenance: [],
    routineChecks: [],
    rentalOrders: [],
    recipeIngredients: [],
    suppliers: [],
    menuItems: [],
    premadePackages: [],
    themes: [],
    ingredientExpenses: {},
    customerFeedbacks: []
  };

  const localRes = (typeof RESERVATIONS !== 'undefined' && Array.isArray(RESERVATIONS)) ? RESERVATIONS : (window.RESERVATIONS || []);
  let sbRes = [];
  let dbIngredientExpenses = [];

  if (sb) {
    try {
      const [resP, ftP, incP, epP, invP, mntP, rcP, roP, riP, supP, miP, ppP, thP, rieP, cfP, ealP, esP] = await Promise.all([
        sb.from('reservations').select('*'),
        sb.from('foodtaste').select('*'),
        sb.from('exec_batch_incidents').select('*'),
        sb.from('execution_plans').select('*'),
        sb.from('equipment_inventory').select('*'),
        sb.from('equipment_maintenance').select('*'),
        sb.from('routine_check').select('*').limit(500),
        sb.from('rental_orders').select('*'),
        sb.from('recipe_ingredients').select('*'),
        sb.from('suppliers').select('*'),
        sb.from('menu_items').select('*'),
        sb.from('premade_packages').select('*'),
        sb.from('event_themes').select('*'),
        sb.from('reservation_ingredient_expenses').select('*'),
        sb.from('customer_feedbacks').select('*'),
        sb.from('equipment_activity_logs').select('*'),
        sb.from('execution_settlements').select('*')
      ]);
      if (resP && resP.data) sbRes = resP.data;
      if (ftP && ftP.data) cache.foodtaste = ftP.data;
      if (incP && incP.data) {
        cache.incidents = incP.data;
        cache.execBatchIncidents = incP.data;
      }
      if (epP && epP.data) cache.execPlans = epP.data;
      if (invP && invP.data) cache.inventory = invP.data;
      if (mntP && mntP.data) cache.maintenance = mntP.data;
      if (rcP && rcP.data) cache.routineChecks = rcP.data;
      if (roP && roP.data) cache.rentalOrders = roP.data;
      if (riP && riP.data) cache.recipeIngredients = riP.data;
      if (supP && supP.data) cache.suppliers = supP.data;
      if (miP && miP.data) cache.menuItems = miP.data;
      if (ppP && ppP.data) cache.premadePackages = ppP.data;
      if (thP && thP.data) cache.themes = thP.data;
      if (rieP && rieP.data) dbIngredientExpenses = rieP.data;
      if (cfP && cfP.data) cache.customerFeedbacks = cfP.data;
      if (ealP && ealP.data) cache.equipmentLogs = ealP.data;
      if (esP && esP.data) cache.executionSettlements = esP.data;
    } catch (e) {
      console.warn('[fetchInsightsLiveSources] Supabase fetch error:', e);
    }
  }

  // Merge reservations safely without overwriting non-null client name
  const resMap = new Map();
  localRes.forEach(r => {
    if (r && r.id) {
      const cName = r.client || r.client_name || r.name || 'Client';
      r.client = cName;
      r.client_name = cName;
      resMap.set(r.id, Object.assign({}, r));
    }
  });
  sbRes.forEach(r => {
    if (!r || !r.id) return;
    const existing = resMap.get(r.id);
    const cName = r.client || r.client_name || (existing && (existing.client || existing.client_name)) || r.name || 'Client';
    r.client = cName;
    r.client_name = cName;
    if (existing) {
      Object.assign(existing, r);
      existing.client = cName;
      existing.client_name = cName;
    } else {
      resMap.set(r.id, r);
    }
  });

  // Attach saved Supabase execution settlement data to reservations in cache
  if (Array.isArray(cache.executionSettlements) && cache.executionSettlements.length > 0) {
    cache.executionSettlements.forEach(es => {
      const r = resMap.get(String(es.reservation_id)) || resMap.get(es.reservation_id);
      if (r) {
        if (es.tip_amount !== undefined && es.tip_amount !== null) r.exec_tip = es.tip_amount;
        const chg = es.total_charges ?? es.additional_charges_amount;
        if (chg !== undefined && chg !== null) r.exec_total_charges = chg;
        
        const staffTotal = es.staff_total_amount ?? (Array.isArray(es.staff_expenses) ? es.staff_expenses.reduce((s, a) => s + (Number(a.amount) || 1000), 0) : es.staff_expenses);
        if (staffTotal !== undefined && staffTotal !== null) r.exec_staff_expense_amount = Number(staffTotal) || 0;
        if (es.staff_expenses) r.exec_staff_assignments = es.staff_expenses;

        const trans = es.transport_driver_amount ?? es.transportation_amount;
        if (trans !== undefined && trans !== null) r.exec_transport_amount = Number(trans) || 0;
        if (es.rentals_amount !== undefined && es.rentals_amount !== null) r.exec_rentals_amount = Number(es.rentals_amount) || 0;
        if (es.personnel_expenses) r.exec_personnel_breakdown = es.personnel_expenses;
        if (es.total_revenue !== undefined && es.total_revenue !== null) r.exec_total_revenue = es.total_revenue;
        if (es.total_expenses !== undefined && es.total_expenses !== null) r.exec_total_expenses = es.total_expenses;
        if (es.net_profit !== undefined && es.net_profit !== null) r.exec_net_profit = es.net_profit;
        if (es.additional_charges_breakdown) {
          r.exec_charges_breakdown = es.additional_charges_breakdown;
        } else if (es.incident_charges !== undefined || es.extra_overhead_amount !== undefined || es.overtime_amount !== undefined || es.floor_access_amount !== undefined) {
          r.exec_charges_breakdown = {
            incidents: es.incident_charges || 0,
            extraOverhead: es.extra_overhead_amount || 0,
            overtime: es.overtime_amount || 0,
            floorAccess: es.floor_access_amount || 0
          };
        }
      }
    });
  }

  cache.reservations = Array.from(resMap.values());
  if (!cache.inventory.length && typeof EIM_ASSETS !== 'undefined') cache.inventory = EIM_ASSETS;
  if (!cache.maintenance.length && typeof maintenanceTasks !== 'undefined') cache.maintenance = maintenanceTasks;

  // Retrieve customer reviews from localStorage and merge
  try {
    const rawFeedbacks = JSON.parse(localStorage.getItem('all_customer_feedbacks') || '[]');
    if (Array.isArray(rawFeedbacks) && rawFeedbacks.length) {
      if (!cache.customerFeedbacks || !cache.customerFeedbacks.length) {
        cache.customerFeedbacks = rawFeedbacks;
      } else {
        const existingIds = new Set(cache.customerFeedbacks.map(f => String(f.id || f.reservation_id)));
        rawFeedbacks.forEach(f => {
          if (!existingIds.has(String(f.id || f.reservation_id))) {
            cache.customerFeedbacks.push(f);
          }
        });
      }
    }
  } catch (e) {}

  // Also collect customer_feedback attached directly to reservations (execution_plan or direct)
  cache.reservations.forEach(r => {
    let ep = r.executionPlan || r.execution_plan;
    if (typeof ep === 'string') {
      try { ep = JSON.parse(ep); } catch (e) {}
    }
    let directFb = r.customer_feedback;
    if (typeof directFb === 'string') {
      try { directFb = JSON.parse(directFb); } catch (e) {}
    }
    const fb = (ep && ep.customer_feedback) || directFb;
    if (fb && typeof fb === 'object' && fb.comment) {
      const already = (cache.customerFeedbacks || []).some(cf => String(cf.reservation_id || cf.id) === String(r.id));
      if (!already) {
        cache.customerFeedbacks.push(Object.assign({
          reservation_id: r.id,
          client_name: fb.client_name || r.client || r.client_name || 'Client',
          package_name: fb.package_name || r.packageName || r.package_name || 'Catering Package',
          rating: parseInt(fb.rating || 5, 10),
          comment: fb.comment || '',
          saved_at: fb.saved_at || r.created_at || new Date().toISOString()
        }, fb));
      }
    }
  });

  // Comprehensive Dishes & Ingredients expenses aggregation
  const ingMap = {};
  if (Array.isArray(dbIngredientExpenses)) {
    dbIngredientExpenses.forEach(row => {
      if (row && row.reservation_id) ingMap[String(row.reservation_id)] = row;
    });
  }

  // Scan browser localStorage for ss_ing_expenses_* and exec_ing_expenses_*
  try {
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k && (k.startsWith('ss_ing_expenses_') || k.startsWith('exec_ing_expenses_'))) {
        const rId = k.replace(/^ss_ing_expenses_|^exec_ing_expenses_/, '');
        try {
          const item = JSON.parse(localStorage.getItem(k) || '{}');
          if (item && (item.expenses || item.total_expense)) {
            if (!ingMap[rId]) ingMap[rId] = { reservation_id: rId, expenses: {} };
            if (item.expenses && typeof item.expenses === 'object') {
              ingMap[rId].expenses = Object.assign({}, ingMap[rId].expenses, item.expenses);
            }
            if (item.total_expense) {
              ingMap[rId].total_expense = Number(item.total_expense);
            }
          }
        } catch(e) {}
      }
    }
  } catch(e) {}

  // Also check each reservation's execution_plan dishes_expenses
  cache.reservations.forEach(r => {
    const rId = String(r.id);
    const epExp = (r.executionPlan && r.executionPlan.dishes_expenses) || 
                  (r.execution_plan && r.execution_plan.dishes_expenses);
    if (epExp && (epExp.expenses || epExp.total_expense)) {
      if (!ingMap[rId]) ingMap[rId] = { reservation_id: rId, expenses: {} };
      if (epExp.expenses && typeof epExp.expenses === 'object') {
        ingMap[rId].expenses = Object.assign({}, ingMap[rId].expenses, epExp.expenses);
      }
      if (epExp.total_expense) {
        ingMap[rId].total_expense = Number(epExp.total_expense);
      }
    }
    if (r.exec_dishes_ingredients_expense && (!ingMap[rId] || !ingMap[rId].total_expense)) {
      if (!ingMap[rId]) ingMap[rId] = { reservation_id: rId, expenses: {} };
      ingMap[rId].total_expense = Number(r.exec_dishes_ingredients_expense);
    }
  });

  cache.ingredientExpenses = ingMap;
  _insightsDataCache = cache;
  return cache;
}

window.fetchInsightsLiveSources = fetchInsightsLiveSources;
window.refreshInsightsLiveCache = function () {
  _insightsDataCache = null;
  renderInsights();
};

let _insightsRealtimeSubscribed = false;
function initAdminAnalyticsRealtime() {
  if (_insightsRealtimeSubscribed) return;
  const sb = window.supabaseClient;
  if (!sb) return;
  try {
    const channel = sb.channel('admin-analytics-realtime')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'reservations' }, () => {
        window.triggerAdminAnalyticsUpdate();
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'reservation_payments' }, () => {
        window.triggerAdminAnalyticsUpdate();
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'reservation_ingredient_expenses' }, () => {
        window.triggerAdminAnalyticsUpdate();
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'exec_batch_incidents' }, () => {
        window.triggerAdminAnalyticsUpdate();
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'execution_plans' }, () => {
        window.triggerAdminAnalyticsUpdate();
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'equipment_inventory' }, () => {
        window.triggerAdminAnalyticsUpdate();
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'rental_orders' }, () => {
        window.triggerAdminAnalyticsUpdate();
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'foodtaste' }, () => {
        window.triggerAdminAnalyticsUpdate();
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'customer_feedbacks' }, () => {
        window.triggerAdminAnalyticsUpdate();
      })
      .subscribe();
    _insightsRealtimeSubscribed = true;
  } catch (err) {
    console.warn('[initAdminAnalyticsRealtime] Realtime subscription notice:', err);
  }
}

// Global update trigger: instantly refreshes analytics without requiring a page reload
window.triggerAdminAnalyticsUpdate = function() {
  _insightsDataCache = null;
  if (_insightsIsLoading) {
    _insightsNeedsReRender = true;
    return;
  }
  if (typeof renderInsights === 'function') {
    renderInsights();
  }
};

async function renderInsights() {
  if (_insightsIsLoading) {
    _insightsNeedsReRender = true;
    return;
  }
  _insightsIsLoading = true;
  try {
    const cache = await fetchInsightsLiveSources();
    initAdminAnalyticsRealtime();
    renderInsightsTopKPIs(cache);
    renderInsightsExpensesAll(cache);
    renderInsightsFinancialLine(cache);
    renderInsightsTipsLine(cache);
    renderInsightsAdditionalCharges(cache);
    renderInsightsBookingVolume(cache);
    renderInsightsCompletedVsCancelled(cache);
    renderInsightsCancellationOrigin(cache);
    renderInsightsAssetStatus(cache);
    renderInsightsGeographicVenues(cache);
    renderInsightsGeographicLocal(cache);
    renderInsightsPackagePremade(cache);
    renderInsightsExpensesIngredients(cache);
    renderInsightsFoodApprovals(cache);
    renderItemPopularitySection(cache);
    renderInsightsExecutionOperations(cache);
    renderInsightsReviewsRating(cache);
    renderForecastAccuracyCard(cache);
  } catch (err) {
    console.error('[renderInsights] Error executing insights engine:', err);
  } finally {
    _insightsIsLoading = false;
    if (_insightsNeedsReRender) {
      _insightsNeedsReRender = false;
      setTimeout(() => renderInsights(), 50);
    }
  }
}
window.renderInsights = renderInsights;

// Calculate realized revenue from an event, including tips and additional execution charges
function getResRealizedRevenue(r) {
  if (!r) return 0;
  const base = parseFloat(r.amount || r.total_amount || 0) || 0;
  const tip = parseFloat(r.exec_tip ?? r.tip_amount ?? (r.exec_summary && r.exec_summary.tip) ?? 0) || 0;
  const addCharges = parseFloat(r.exec_total_charges ?? r.additional_charges_amount ?? r.additional_charges ?? (r.exec_summary && r.exec_summary.totalCharges) ?? 0) || 0;
  return base + tip + addCharges;
}
window.getResRealizedRevenue = getResRealizedRevenue;

// ----------------------------------------------------
// PILLAR 1: Top KPI Summary (Strictly Filtered by Active Date Window)
// ----------------------------------------------------
function renderInsightsTopKPIs(cache) {
  const reservations = cache.reservations || [];
  const filter = _adminAnalyticsFilters['insights-fin-line'] || _adminAnalyticsFilters['insights-fin-bar'] || { anchorYear: new Date().getFullYear(), anchorMonth: new Date().getMonth(), rangeMonths: 12 };
  const months = getAdminMonthRangeKeys(filter);
  
  // Strictly filter by active window
  const windowReservations = reservations.filter(r => filterResDate(r, months));
  const monthName = ADMIN_MONTH_NAMES[filter.anchorMonth] + ' ' + filter.anchorYear;

  // 1. Completed Events
  const windowCompleted = windowReservations.filter(r => String(r.status || '').toLowerCase() === 'completed');
  const elComp = document.getElementById('insights-kpi-completed-events');
  const elCompSub = document.getElementById('insights-kpi-completed-events-sub');
  if (elComp) elComp.textContent = windowCompleted.length.toLocaleString();
  if (elCompSub) elCompSub.textContent = windowCompleted.length + ' completed events in ' + monthName;

  // 1b. Cancelled Events (Compared vs Previous Month)
  const windowCancelled = windowReservations.filter(r => String(r.status || '').toLowerCase() === 'cancelled');
  let prevMonth = filter.anchorMonth - 1;
  let prevYear = filter.anchorYear;
  if (prevMonth < 0) { prevMonth = 11; prevYear -= 1; }
  const prevMonthKey = `${prevYear}-${String(prevMonth + 1).padStart(2, '0')}`;
  const prevReservations = reservations.filter(r => filterResDate(r, [prevMonthKey]));
  const prevCancelled = prevReservations.filter(r => String(r.status || '').toLowerCase() === 'cancelled');

  let cancChangeText = '0% vs last month';
  let cancChangeClass = '';
  if (prevCancelled.length > 0) {
    const diff = windowCancelled.length - prevCancelled.length;
    const pct = Math.round((diff / prevCancelled.length) * 100);
    if (pct > 0) {
      cancChangeText = `+${pct}% vs last month`;
      cancChangeClass = 'down';
    } else if (pct < 0) {
      cancChangeText = `${pct}% vs last month`;
      cancChangeClass = 'up';
    } else {
      cancChangeText = '0% vs last month';
    }
  } else if (windowCancelled.length > 0) {
    cancChangeText = `+${windowCancelled.length} new this month`;
    cancChangeClass = 'down';
  }

  const elCanc = document.getElementById('insights-kpi-cancelled-events');
  const elCancSub = document.getElementById('insights-kpi-cancelled-events-sub');
  if (elCanc) elCanc.textContent = windowCancelled.length.toLocaleString();
  if (elCancSub) {
    elCancSub.textContent = cancChangeText;
    elCancSub.className = 'stat-change ' + cancChangeClass;
  }

  // 2. Total Guests Catered
  const totalPax = windowCompleted.reduce((acc, r) => acc + (parseInt(r.pax || r.guests || r.guest_count || 0, 10) || 0), 0);
  const avgPax = windowCompleted.length > 0 ? Math.round(totalPax / windowCompleted.length) : 0;
  const elPax = document.getElementById('insights-kpi-guests-served');
  const elPaxSub = document.getElementById('insights-kpi-guests-served-sub');
  if (elPax) elPax.textContent = totalPax.toLocaleString();
  if (elPaxSub) elPaxSub.textContent = avgPax + ' avg guests per completed event';

  // 3. Gross Contract Value (Includes tips & additional charges)
  let grossContractValue = 0;
  windowReservations.forEach(r => {
    const st = String(r.status || '').toLowerCase();
    if (st !== 'cancelled') {
      grossContractValue += getResRealizedRevenue(r);
    }
  });
  const elGross = document.getElementById('insights-kpi-gross-revenue');
  const elGrossSub = document.getElementById('insights-kpi-gross-revenue-sub');
  if (elGross) elGross.textContent = '₱' + Math.round(grossContractValue).toLocaleString();
  if (elGrossSub) elGrossSub.textContent = windowReservations.length + ' active bookings in ' + monthName;

  // 4. 200% Cancellation Penalty Liabilities
  let unpaidCancellationLiabilities = 0;
  let unpaidCancelCount = 0;
  windowReservations.forEach(r => {
    const st = String(r.status || '').toLowerCase();
    if (st === 'cancelled') {
      const cType = String(r.cancellation_by || r.cancelled_by || '').toLowerCase();
      const isBizCancel = cType.includes('business') || cType.includes('admin') || !cType.includes('customer');
      if (isBizCancel) {
        const amt = parseFloat(r.amount || r.total_amount || 0) || 0;
        unpaidCancellationLiabilities += (amt * 2.0);
        unpaidCancelCount++;
      }
    }
  });
  const elCancel = document.getElementById('insights-kpi-cancellation-liability') || document.getElementById('insights-kpi-cancelled-revenue');
  const elCancelSub = document.getElementById('insights-kpi-cancellation-liability-sub') || document.getElementById('insights-kpi-cancelled-revenue-sub');
  if (elCancel) elCancel.textContent = '₱' + Math.round(unpaidCancellationLiabilities).toLocaleString();
  if (elCancelSub) elCancelSub.textContent = unpaidCancelCount + ' business cancellations (200% penalty)';

  // 5. Total Expenses (Aggregates live Dishes & Ingredients expenses + operational expenses for window)
  let totalExpenses = 0;
  const ingMap = cache.ingredientExpenses || {};
  windowReservations.forEach(r => {
    const rId = String(r.id);
    const ingExp = (ingMap[rId] && ingMap[rId].total_expense) ? Number(ingMap[rId].total_expense) : (Number(r.exec_dishes_ingredients_expense) || 0);
    totalExpenses += ingExp;
    totalExpenses += (Number(r.exec_transport_amount) || 0);
    totalExpenses += (Number(r.exec_rentals_amount) || 0);
    const staffExpense = Number(r.exec_staff_expense_amount) || ((r.assigned_staff || r.staff_assignments || []).length * 1000) || 0;
    totalExpenses += staffExpense;
    totalExpenses += (Number(r.exec_consumables_amount) || 0);
    const persObj = r.exec_personnel_breakdown || {};
    const persTotal = Object.values(persObj).reduce((s, v) => s + (Number(v) || 0), 0) + (r.hired_personnel ? 5000 : 0);
    totalExpenses += persTotal;
  });
  if (windowReservations.length > 0 && totalExpenses === 0) {
    totalExpenses = Math.round(grossContractValue * 0.35);
  }
  const elExp = document.getElementById('insights-kpi-total-expenses');
  const elExpSub = document.getElementById('insights-kpi-total-expenses-sub');
  if (elExp) elExp.textContent = '₱' + Math.round(totalExpenses).toLocaleString();
  if (elExpSub) elExpSub.textContent = 'Procurement & operational outflows (' + monthName + ')';

  // 6. Net Realized Revenue (Includes tips and additional execution charges)
  let completedGross = 0;
  windowCompleted.forEach(r => {
    completedGross += getResRealizedRevenue(r);
  });
  const elNet = document.getElementById('insights-kpi-net-revenue');
  const elNetSub = document.getElementById('insights-kpi-net-revenue-sub');
  if (elNet) elNet.textContent = '₱' + Math.round(completedGross).toLocaleString();
  if (elNetSub) elNetSub.textContent = 'Gross contract minus liabilities (' + monthName + ')';

  // 7. Average Order Value (AOV)
  const aov = windowCompleted.length > 0 ? Math.round(completedGross / windowCompleted.length) : (grossContractValue > 0 ? Math.round(grossContractValue / Math.max(1, windowReservations.length)) : 0);
  const elAov = document.getElementById('insights-kpi-aov');
  const elAovSub = document.getElementById('insights-kpi-aov-sub');
  if (elAov) elAov.textContent = '₱' + aov.toLocaleString();
  if (elAovSub) elAovSub.textContent = 'Average value per event (' + monthName + ')';

  // 8. Top Premade Package (strictly counting premade packages, excluding custom packages)
  const pkgCounts = {};
  windowReservations.forEach(r => {
    const pkgName = (r.premade_package_name || r.package_name || r.packageName || '').trim();
    if (!pkgName) return;
    const lower = pkgName.toLowerCase();
    if (lower === 'custom package' || lower === 'my custom package' || lower === 'custom' || lower.startsWith('custom')) return;
    pkgCounts[pkgName] = (pkgCounts[pkgName] || 0) + 1;
  });
  const sortedPkgs = Object.entries(pkgCounts).sort((a, b) => b[1] - a[1]);
  const topPkgName = sortedPkgs.length > 0 ? sortedPkgs[0][0] : 'None';
  const topPkgCount = sortedPkgs.length > 0 ? sortedPkgs[0][1] : 0;
  const elTopPkg = document.getElementById('insights-kpi-top-package');
  const elTopPkgSub = document.getElementById('insights-kpi-top-package-sub');
  if (elTopPkg) elTopPkg.textContent = topPkgName;
  if (elTopPkgSub) elTopPkgSub.textContent = topPkgCount + ' bookings in selected period';

  // 9. Top Customer
  const custCounts = {};
  windowReservations.forEach(r => {
    const cName = r.client_name || r.name || r.client;
    if (cName) custCounts[cName] = (custCounts[cName] || 0) + 1;
  });
  const sortedCusts = Object.entries(custCounts).sort((a, b) => b[1] - a[1]);
  const topCustName = sortedCusts.length > 0 ? sortedCusts[0][0] : '--';
  const topCustCount = sortedCusts.length > 0 ? sortedCusts[0][1] : 0;
  const elCustName = document.getElementById('top-customer-name');
  const elCustBookings = document.getElementById('top-customer-bookings');
  if (elCustName) elCustName.textContent = topCustName;
  if (elCustBookings) elCustBookings.textContent = topCustCount + ' bookings in selected period';
}

// ----------------------------------------------------
// PILLAR 2: Gross Contract vs. 200% Penalty Liabilities (Bar Graph)
// ----------------------------------------------------
function renderInsightsFinancialBar(cache) {
  if (!document.getElementById('insights-chart-fin-bar')) return;
  const key = 'insights-fin-bar';
  const filter = _adminAnalyticsFilters[key] || { anchorYear: new Date().getFullYear(), anchorMonth: new Date().getMonth(), rangeMonths: 12 };
  updateAdminAnalyticsDateLabel(key);
  updateAdminAnalyticsFilterButtonStates(key);
  const months = getAdminMonthRangeKeys(filter);
  const reservations = cache.reservations || [];

  const dataByMonth = months.map(m => {
    let gross = 0;
    let liabilities = 0;
    reservations.filter(r => getResMonthKey(r) === m.key).forEach(r => {
      const st = String(r.status || '').toLowerCase();
      const amt = parseFloat(r.amount || r.total_amount || 0) || 0;
      if (st !== 'cancelled') {
        gross += amt;
      } else {
        const cType = String(r.cancellation_by || r.cancelled_by || '').toLowerCase();
        if (cType.includes('business') || cType.includes('admin') || !cType.includes('customer')) {
          liabilities += (amt * 2.0);
        }
      }
    });
    return { month: m, gross, liabilities };
  });

  const totalGross = dataByMonth.reduce((s, d) => s + d.gross, 0);
  const totalLiab = dataByMonth.reduce((s, d) => s + d.liabilities, 0);

  const curAnchor = filter.anchorYear + '-' + String(filter.anchorMonth + 1).padStart(2, '0');
  const prevYear = filter.anchorMonth === 0 ? filter.anchorYear - 1 : filter.anchorYear;
  const prevMonth = filter.anchorMonth === 0 ? 11 : filter.anchorMonth - 1;
  const prevKey = prevYear + '-' + String(prevMonth + 1).padStart(2, '0');

  const curMonthData = dataByMonth.find(d => d.month.key === curAnchor) || { gross: 0, liabilities: 0 };
  let prevGross = 0;
  const prevItem = dataByMonth.find(d => d.month.key === prevKey);
  if (prevItem) {
    prevGross = prevItem.gross;
  } else {
    reservations.filter(r => getResMonthKey(r) === prevKey).forEach(r => {
      const st = String(r.status || '').toLowerCase();
      if (st !== 'cancelled') {
        prevGross += getResGrossContractValue(r);
      }
    });
  }

  const statTot = document.getElementById('stat-insights-fin-bar-total');
  const statLast = document.getElementById('stat-insights-fin-bar-last-month');
  const statThis = document.getElementById('stat-insights-fin-bar-this-month');
  const statChg = document.getElementById('stat-insights-fin-bar-change');
  if (statTot) statTot.textContent = '₱' + Math.round(totalGross).toLocaleString();
  if (statLast) statLast.textContent = '₱' + Math.round(prevGross).toLocaleString();
  if (statThis) statThis.textContent = '₱' + Math.round(curMonthData.gross).toLocaleString();
  if (statChg) {
    const diff = curMonthData.gross - prevGross;
    const pct = prevGross > 0 ? Math.round((diff / prevGross) * 100) : (curMonthData.gross > 0 ? 100 : 0);
    statChg.textContent = (diff >= 0 ? '+' : '') + pct + '% change';
  }

  const ctx = document.getElementById('insights-chart-fin-bar');
  if (ctx && window.Chart) {
    if (window._insightsFinBarChartInst) window._insightsFinBarChartInst.destroy();
    window._insightsFinBarChartInst = new Chart(ctx, {
      type: 'bar',
      data: {
        labels: months.map(m => m.shortLabel),
        datasets: [
          { label: 'Gross Contract Value', data: dataByMonth.map(d => d.gross), backgroundColor: '#c49a3c', borderRadius: 4 },
          { label: '200% Penalty Liabilities', data: dataByMonth.map(d => d.liabilities), backgroundColor: '#e05656', borderRadius: 4 }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          x: { grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#a89070', font: { family: "'DM Sans',sans-serif", size: 11 } } },
          y: {
            beginAtZero: true,
            grid: { color: 'rgba(255,255,255,0.05)' },
            ticks: {
              color: '#a89070',
              callback: (v) => '₱' + (v >= 1000 ? (v / 1000).toFixed(0) + 'k' : v)
            }
          }
        },
        plugins: {
          legend: { position: 'top', labels: { color: '#f5ebd9', font: { family: "'DM Sans',sans-serif", size: 11 } } }
        }
      }
    });
  }

  const tblEl = document.getElementById('insights-table-insights-fin-bar');
  if (tblEl) {
    tblEl.innerHTML = '<table class="data-table" style="font-size:11px;width:100%;border-collapse:collapse;">'
      + '<thead><tr style="border-bottom:1px solid var(--border);">'
      + '<th style="text-align:left;padding:8px 10px;">Month</th>'
      + '<th style="text-align:left;padding:8px 10px;">Booked Package(s)</th>'
      + '<th style="text-align:right;padding:8px 10px;">Gross Contract Value</th>'
      + '<th style="text-align:right;padding:8px 10px;">200% Penalty Liabilities</th>'
      + '</tr></thead><tbody>'
      + dataByMonth.map(row => {
        const monthRes = reservations.filter(r => getResMonthKey(r) === row.month.key);
        const pkgs = Array.from(new Set(monthRes.map(r => r.package_name || r.packageName || r.type || 'Custom Package').filter(Boolean))).join(', ') || '—';
        const mLabel = row.month.fullLabel || row.month.shortLabel || row.month.key;
        return '<tr style="border-bottom:1px solid rgba(255,255,255,0.03);">'
          + '<td style="padding:7px 10px;font-weight:600;color:var(--cream);">' + mLabel + '</td>'
          + '<td style="padding:7px 10px;color:var(--gold);">' + pkgs + '</td>'
          + '<td style="padding:7px 10px;text-align:right;color:var(--gold);font-weight:700;">₱' + Math.round(row.gross).toLocaleString() + '</td>'
          + '<td style="padding:7px 10px;text-align:right;color:var(--red,#e05656);font-weight:700;">₱' + Math.round(row.liabilities).toLocaleString() + '</td>'
          + '</tr>';
      }).join('')
      + '</tbody></table>';
  }
}

// ----------------------------------------------------
// PILLAR 3: Net Realized Revenue Trend (Line Graph)
// ----------------------------------------------------
function renderInsightsFinancialLine(cache) {
  const key = 'insights-fin-line';
  const filter = _adminAnalyticsFilters[key] || { anchorYear: new Date().getFullYear(), anchorMonth: new Date().getMonth(), rangeMonths: 6 };
  updateAdminAnalyticsDateLabel(key);
  updateAdminAnalyticsFilterButtonStates(key);
  const months = getAdminMonthRangeKeys(filter);
  const reservations = cache.reservations || [];

  const completedRes = reservations.filter(r => String(r.status || '').toLowerCase() === 'completed');

  const dataByMonth = months.map(m => {
    let rev = 0;
    completedRes.filter(r => getResMonthKey(r) === m.key).forEach(r => {
      rev += getResRealizedRevenue(r);
    });
    return { month: m, revenue: rev };
  });

  const totalRev = dataByMonth.reduce((s, d) => s + d.revenue, 0);
  const curAnchor = filter.anchorYear + '-' + String(filter.anchorMonth + 1).padStart(2, '0');
  const prevYear = filter.anchorMonth === 0 ? filter.anchorYear - 1 : filter.anchorYear;
  const prevMonth = filter.anchorMonth === 0 ? 11 : filter.anchorMonth - 1;
  const prevKey = prevYear + '-' + String(prevMonth + 1).padStart(2, '0');

  const curItem = dataByMonth.find(d => d.month.key === curAnchor);
  const curVal = curItem ? curItem.revenue : 0;
  let prevRev = 0;
  const prevItem = dataByMonth.find(d => d.month.key === prevKey);
  if (prevItem) {
    prevRev = prevItem.revenue;
  } else {
    completedRes.filter(r => getResMonthKey(r) === prevKey).forEach(r => {
      prevRev += getResRealizedRevenue(r);
    });
  }

  const statTot = document.getElementById('stat-insights-fin-line-total');
  const statLast = document.getElementById('stat-insights-fin-line-last-month');
  const statThis = document.getElementById('stat-insights-fin-line-this-month');
  const statChg = document.getElementById('stat-insights-fin-line-change');
  if (statTot) statTot.textContent = '₱' + Math.round(totalRev).toLocaleString();
  if (statLast) statLast.textContent = '₱' + Math.round(prevRev).toLocaleString();
  if (statThis) statThis.textContent = '₱' + Math.round(curVal).toLocaleString();
  if (statChg) {
    const diff = curVal - prevRev;
    const pct = prevRev > 0 ? Math.round((diff / prevRev) * 100) : (curVal > 0 ? 100 : 0);
    statChg.textContent = (diff >= 0 ? '+' : '') + pct + '% change';
  }

  const ctx = document.getElementById('insights-chart-fin-line');
  if (ctx && window.Chart) {
    if (window._insightsFinLineChartInst) window._insightsFinLineChartInst.destroy();
    window._insightsFinLineChartInst = new Chart(ctx, {
      type: 'line',
      data: {
        labels: months.map(m => m.shortLabel),
        datasets: [{
          label: 'Net Realized Revenue (Completed Events)',
          data: dataByMonth.map(d => d.revenue),
          borderColor: '#2d8a4e',
          backgroundColor: 'rgba(45, 138, 78, 0.15)',
          borderWidth: 3,
          fill: true,
          tension: 0.35,
          pointBackgroundColor: '#2d8a4e',
          pointRadius: 4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          x: { grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#a89070', font: { family: "'DM Sans',sans-serif", size: 11 } } },
          y: {
            beginAtZero: true,
            grid: { color: 'rgba(255,255,255,0.05)' },
            ticks: {
              color: '#a89070',
              callback: (v) => '₱' + (v >= 1000 ? (v / 1000).toFixed(0) + 'k' : v)
            }
          }
        },
        plugins: {
          legend: { position: 'top', labels: { color: '#f5ebd9', font: { family: "'DM Sans',sans-serif", size: 11 } } },
          tooltip: {
            callbacks: {
              label: (c) => ' Net Revenue: ₱' + Math.round(c.raw).toLocaleString()
            }
          }
        }
      }
    });
  }

  const tblEl = document.getElementById('insights-table-insights-fin-line');
  if (tblEl) {
    tblEl.innerHTML = '<table class="data-table" style="font-size:11px;width:100%;border-collapse:collapse;">'
      + '<thead><tr style="border-bottom:1px solid var(--border);">'
      + '<th style="text-align:left;padding:8px 10px;">Date</th>'
      + '<th style="text-align:left;padding:8px 10px;">Client</th>'
      + '<th style="text-align:left;padding:8px 10px;">Package</th>'
      + '<th style="text-align:right;padding:8px 10px;">Net Realized</th>'
      + '</tr></thead><tbody>'
      + completedRes.filter(r => filterResDate(r, months)).map(r => {
        return '<tr style="border-bottom:1px solid rgba(255,255,255,0.03);">'
          + '<td style="padding:7px 10px;">' + (getResDateStr(r) || 'N/A') + '</td>'
          + '<td style="padding:7px 10px;font-weight:600;">' + (r.client_name || r.name || 'Client') + '</td>'
          + '<td style="padding:7px 10px;">' + (r.package_name || r.packageName || 'Package') + '</td>'
          + '<td style="padding:7px 10px;text-align:right;color:var(--green,#2d8a4e);font-weight:700;">₱' + Math.round(getResRealizedRevenue(r)).toLocaleString() + '</td>'
          + '</tr>';
      }).join('')
      + '</tbody></table>';
  }
}

// ----------------------------------------------------
// PILLAR 3B: Client Tips Given Volume & Trend (Line Graph & Itemized List Mode)
// ----------------------------------------------------
function renderInsightsTipsLine(cache) {
  const key = 'insights-tips-line';
  const filter = _adminAnalyticsFilters[key] || { anchorYear: new Date().getFullYear(), anchorMonth: new Date().getMonth(), rangeMonths: 6 };
  updateAdminAnalyticsDateLabel(key);
  updateAdminAnalyticsFilterButtonStates(key);
  const months = getAdminMonthRangeKeys(filter);
  const reservations = cache.reservations || [];

  const completedRes = reservations.filter(r => String(r.status || '').toLowerCase() === 'completed');

  const dataByMonth = months.map(m => {
    let monthlyTips = 0;
    completedRes.filter(r => getResMonthKey(r) === m.key).forEach(r => {
      const tip = parseFloat(r.exec_tip || (r.exec_summary && r.exec_summary.tip) || 0) || 0;
      monthlyTips += tip;
    });
    return { month: m, tips: monthlyTips };
  });

  const totalTips = dataByMonth.reduce((s, d) => s + d.tips, 0);
  const windowCompleted = completedRes.filter(r => filterResDate(r, months));
  const eventsWithTips = windowCompleted.filter(r => {
    const tip = parseFloat(r.exec_tip || (r.exec_summary && r.exec_summary.tip) || 0) || 0;
    return tip > 0;
  });
  const avgTip = eventsWithTips.length > 0 ? Math.round(totalTips / eventsWithTips.length) : 0;
  const topTip = windowCompleted.reduce((max, r) => {
    const tip = parseFloat(r.exec_tip || (r.exec_summary && r.exec_summary.tip) || 0) || 0;
    return Math.max(max, tip);
  }, 0);

  const statTot = document.getElementById('stat-insights-tips-line-total');
  const statAvg = document.getElementById('stat-insights-tips-line-avg');
  const statTop = document.getElementById('stat-insights-tips-line-top');
  if (statTot) statTot.textContent = '₱' + Math.round(totalTips).toLocaleString();
  if (statAvg) statAvg.textContent = '₱' + Math.round(avgTip).toLocaleString();
  if (statTop) statTop.textContent = '₱' + Math.round(topTip).toLocaleString();

  const ctx = document.getElementById('insights-chart-tips-line');
  if (ctx && window.Chart) {
    if (window._insightsTipsLineChartInst) window._insightsTipsLineChartInst.destroy();
    window._insightsTipsLineChartInst = new Chart(ctx, {
      type: 'line',
      data: {
        labels: months.map(m => m.shortLabel),
        datasets: [{
          label: 'Client Tips Given (₱)',
          data: dataByMonth.map(d => d.tips),
          borderColor: '#c49a3c',
          backgroundColor: 'rgba(196, 154, 60, 0.15)',
          borderWidth: 3,
          fill: true,
          tension: 0.35,
          pointBackgroundColor: '#c49a3c',
          pointRadius: 4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          x: { grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#a89070', font: { family: "'DM Sans',sans-serif", size: 11 } } },
          y: {
            beginAtZero: true,
            grid: { color: 'rgba(255,255,255,0.05)' },
            ticks: {
              color: '#a89070',
              callback: (v) => '₱' + (v >= 1000 ? (v / 1000).toFixed(0) + 'k' : v)
            }
          }
        },
        plugins: {
          legend: { position: 'top', labels: { color: '#f5ebd9', font: { family: "'DM Sans',sans-serif", size: 11 } } },
          tooltip: {
            callbacks: {
              label: (c) => ' Tips: ₱' + Math.round(c.raw).toLocaleString()
            }
          }
        }
      }
    });
  }

  const tblEl = document.getElementById('insights-table-insights-tips-line');
  if (tblEl) {
    const rows = windowCompleted.filter(r => {
      const tip = parseFloat(r.exec_tip || (r.exec_summary && r.exec_summary.tip) || 0) || 0;
      return tip > 0;
    });
    if (rows.length === 0) {
      tblEl.innerHTML = '<div style="padding:20px;text-align:center;color:var(--text-dim);font-size:12px;">No tips recorded in this time range.</div>';
    } else {
      tblEl.innerHTML = '<table class="data-table" style="font-size:11px;width:100%;border-collapse:collapse;">'
        + '<thead><tr style="border-bottom:1px solid var(--border);">'
        + '<th style="text-align:left;padding:8px 10px;">Date</th>'
        + '<th style="text-align:left;padding:8px 10px;">Client</th>'
        + '<th style="text-align:left;padding:8px 10px;">Package</th>'
        + '<th style="text-align:right;padding:8px 10px;">Tip Given</th>'
        + '</tr></thead><tbody>'
        + rows.map(r => {
          const tip = parseFloat(r.exec_tip || (r.exec_summary && r.exec_summary.tip) || 0) || 0;
          return '<tr style="border-bottom:1px solid rgba(255,255,255,0.03);">'
            + '<td style="padding:7px 10px;">' + (getResDateStr(r) || 'N/A') + '</td>'
            + '<td style="padding:7px 10px;font-weight:600;">' + (r.client_name || r.name || 'Client') + '</td>'
            + '<td style="padding:7px 10px;">' + (r.package_name || r.packageName || 'Package') + '</td>'
            + '<td style="padding:7px 10px;text-align:right;color:var(--gold,#c49a3c);font-weight:700;">₱' + Math.round(tip).toLocaleString() + '</td>'
            + '</tr>';
        }).join('')
        + '</tbody></table>';
    }
  }
}

// ----------------------------------------------------
// PILLAR 3C: Additional Execution Charges Frequency (Pie Chart & List Mode)
// ----------------------------------------------------
function renderInsightsAdditionalCharges(cache) {
  const key = 'insights-add-charges';
  const filter = _adminAnalyticsFilters[key] || { anchorYear: new Date().getFullYear(), anchorMonth: new Date().getMonth(), rangeMonths: 6 };
  updateAdminAnalyticsDateLabel(key);
  updateAdminAnalyticsFilterButtonStates(key);
  const months = getAdminMonthRangeKeys(filter);
  const reservations = cache.reservations || [];

  const completedRes = reservations.filter(r => String(r.status || '').toLowerCase() === 'completed');
  const windowCompleted = completedRes.filter(r => filterResDate(r, months));

  let overheadCount = 0, overheadSum = 0;
  let overtimeCount = 0, overtimeSum = 0;
  let floorCount = 0, floorSum = 0;
  let incidentCount = 0, incidentSum = 0;
  let otcCount = 0, otcSum = 0;
  let svcCount = 0, svcSum = 0;

  const resWithCharges = [];

  windowCompleted.forEach(r => {
    const sumObj = r.exec_summary || (r.executionPlan && r.executionPlan.exec_summary) || null;
    const overheadUnits = parseInt(r.exec_extra_overhead_units || sumObj?.overheadUnits || 0, 10) || 0;
    const overheadAmt = parseFloat(r.exec_extra_overhead_amount || sumObj?.overheadAmt || (overheadUnits * 450)) || 0;

    const overtimeUnits = parseInt(r.exec_overtime_units || sumObj?.overtimeUnits || 0, 10) || 0;
    const overtimeAmt = parseFloat(r.exec_overtime_amount || sumObj?.overtimeAmt || (overtimeUnits * 1000)) || 0;

    const floorUnits = parseInt(r.exec_floor_access_units || sumObj?.floorUnits || 0, 10) || 0;
    const floorAmt = parseFloat(r.exec_floor_access_amount || sumObj?.floorAmt || (floorUnits * 100)) || 0;

    const incCharge = parseFloat(r.exec_incident_charges || sumObj?.incCharge || 0) || 0;
    const otcAmt = parseFloat(r.outOfTownCharge || r.out_of_town_charge || sumObj?.otcAmt || 0) || 0;
    const svcAmt = parseFloat(r.serviceCharge || r.service_charge || sumObj?.svcAmt || 0) || 0;

    const items = [];
    if (overheadUnits > 0 || overheadAmt > 0) {
      overheadCount++;
      overheadSum += overheadAmt;
      items.push(`Extra Overhead (${overheadUnits} units @ ₱450 = ₱${overheadAmt.toLocaleString()})`);
    }
    if (overtimeUnits > 0 || overtimeAmt > 0) {
      overtimeCount++;
      overtimeSum += overtimeAmt;
      items.push(`Overtime (${overtimeUnits} hrs @ ₱1,000 = ₱${overtimeAmt.toLocaleString()})`);
    }
    if (floorUnits > 0 || floorAmt > 0) {
      floorCount++;
      floorSum += floorAmt;
      items.push(`Floor Accessibility (${floorUnits} floors = ₱${floorAmt.toLocaleString()})`);
    }
    if (incCharge > 0) {
      incidentCount++;
      incidentSum += incCharge;
      items.push(`Incident Charges (₱${incCharge.toLocaleString()})`);
    }
    if (otcAmt > 0) {
      otcCount++;
      otcSum += otcAmt;
      items.push(`Out of Town (₱${otcAmt.toLocaleString()})`);
    }
    if (svcAmt > 0) {
      svcCount++;
      svcSum += svcAmt;
      items.push(`Service Charge (₱${svcAmt.toLocaleString()})`);
    }

    const totalCharges = overheadAmt + overtimeAmt + floorAmt + incCharge + otcAmt + svcAmt;
    if (items.length > 0 || totalCharges > 0) {
      resWithCharges.push({
        id: r.id,
        client: r.client_name || r.name || r.client || 'Client',
        package: r.package_name || r.packageName || r.premade_package_name || 'Catering Package',
        date: getResDateStr(r) || 'N/A',
        breakdownText: items.join(', '),
        totalCharges: totalCharges
      });
    }
  });

  const categories = [
    { label: 'Extra Overhead', count: overheadCount, sum: overheadSum, color: '#e67e22' },
    { label: 'Overtime Charge', count: overtimeCount, sum: overtimeSum, color: '#d97706' },
    { label: 'Floor Accessibility', count: floorCount, sum: floorSum, color: '#3b82f6' },
    { label: 'Incident Charges', count: incidentCount, sum: incidentSum, color: '#ef4444' },
    { label: 'Out of Town Surcharge', count: otcCount, sum: otcSum, color: '#8b5cf6' },
    { label: 'Service Charge', count: svcCount, sum: svcSum, color: '#10b981' }
  ];

  const sortedCategories = [...categories].sort((a, b) => b.count - a.count);
  const mostFrequent = sortedCategories[0]?.count > 0 ? `${sortedCategories[0].label} (${sortedCategories[0].count} events)` : 'None';
  const totalIncurred = categories.reduce((s, c) => s + c.sum, 0);

  const statMost = document.getElementById('stat-insights-add-charges-most');
  const statTot = document.getElementById('stat-insights-add-charges-total');
  const statEvents = document.getElementById('stat-insights-add-charges-events');
  if (statMost) statMost.textContent = mostFrequent;
  if (statTot) statTot.textContent = '₱' + Math.round(totalIncurred).toLocaleString();
  if (statEvents) statEvents.textContent = resWithCharges.length + ' events';

  const ctx = document.getElementById('insights-chart-add-charges');
  if (ctx && window.Chart) {
    if (window._insightsAddChargesChartInst) window._insightsAddChargesChartInst.destroy();
    const hasData = categories.some(c => c.count > 0);
    window._insightsAddChargesChartInst = new Chart(ctx, {
      type: 'pie',
      data: {
        labels: hasData ? categories.map(c => c.label) : ['No Charges Logged'],
        datasets: [{
          data: hasData ? categories.map(c => c.count) : [1],
          backgroundColor: hasData ? categories.map(c => c.color) : ['rgba(255,255,255,0.1)'],
          borderWidth: 2,
          borderColor: '#16120d'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { position: 'bottom', labels: { color: '#a89070', font: { family: "'DM Sans',sans-serif", size: 10 } } },
          tooltip: {
            callbacks: {
              label: (c) => {
                if (!hasData) return ' No additional charges recorded';
                const cat = categories[c.dataIndex];
                return ` ${cat.label}: ${cat.count} events (₱${Math.round(cat.sum).toLocaleString()})`;
              }
            }
          }
        }
      }
    });
  }

  const tblEl = document.getElementById('insights-table-insights-add-charges');
  if (tblEl) {
    if (resWithCharges.length === 0) {
      tblEl.innerHTML = '<div style="padding:20px;text-align:center;color:var(--text-dim);font-size:12px;">No completed reservations had additional charges in this period.</div>';
    } else {
      tblEl.innerHTML = '<table class="data-table" style="font-size:11px;width:100%;border-collapse:collapse;">'
        + '<thead><tr style="border-bottom:1px solid var(--border);">'
        + '<th style="text-align:left;padding:8px 10px;">Client</th>'
        + '<th style="text-align:left;padding:8px 10px;">Package Name</th>'
        + '<th style="text-align:left;padding:8px 10px;">Event Date</th>'
        + '<th style="text-align:left;padding:8px 10px;">Additional Charges Incurred</th>'
        + '<th style="text-align:right;padding:8px 10px;">Total Charges</th>'
        + '</tr></thead><tbody>'
        + resWithCharges.map(item => {
          return '<tr style="border-bottom:1px solid rgba(255,255,255,0.03);">'
            + '<td style="padding:7px 10px;font-weight:600;">' + escHtml(item.client) + '</td>'
            + '<td style="padding:7px 10px;">' + escHtml(item.package) + '</td>'
            + '<td style="padding:7px 10px;">' + escHtml(item.date) + '</td>'
            + '<td style="padding:7px 10px;color:var(--cream);">' + escHtml(item.breakdownText) + '</td>'
            + '<td style="padding:7px 10px;text-align:right;color:var(--gold,#c49a3c);font-weight:700;">₱' + Math.round(item.totalCharges).toLocaleString() + '</td>'
            + '</tr>';
        }).join('')
        + '</tbody></table>';
    }
  }
}

// ----------------------------------------------------
// PILLAR 4A: Booking Submission Volume (Line Graph)
// ----------------------------------------------------
function renderInsightsBookingVolume(cache) {
  const key = 'insights-booking-vol';
  const filter = _adminAnalyticsFilters[key] || { anchorYear: new Date().getFullYear(), anchorMonth: new Date().getMonth(), rangeMonths: 6 };
  updateAdminAnalyticsDateLabel(key);
  updateAdminAnalyticsFilterButtonStates(key);
  const months = getAdminMonthRangeKeys(filter);
  const reservations = cache.reservations || [];

  const countsByMonth = months.map(m => {
    const count = reservations.filter(r => getResMonthKey(r) === m.key).length;
    return { month: m, count };
  });

  const totalBookings = countsByMonth.reduce((s, d) => s + d.count, 0);
  const curAnchor = filter.anchorYear + '-' + String(filter.anchorMonth + 1).padStart(2, '0');
  const prevYear = filter.anchorMonth === 0 ? filter.anchorYear - 1 : filter.anchorYear;
  const prevMonth = filter.anchorMonth === 0 ? 11 : filter.anchorMonth - 1;
  const prevKey = prevYear + '-' + String(prevMonth + 1).padStart(2, '0');

  const curItem = countsByMonth.find(d => d.month.key === curAnchor);
  const curCount = curItem ? curItem.count : 0;
  let prevCount = 0;
  const prevItem = countsByMonth.find(d => d.month.key === prevKey);
  if (prevItem) {
    prevCount = prevItem.count;
  } else {
    prevCount = reservations.filter(r => getResMonthKey(r) === prevKey).length;
  }

  const statTot = document.getElementById('stat-insights-booking-vol-total');
  const statLast = document.getElementById('stat-insights-booking-vol-last-month');
  const statThis = document.getElementById('stat-insights-booking-vol-this-month');
  const statChg = document.getElementById('stat-insights-booking-vol-change');
  if (statTot) statTot.textContent = totalBookings.toLocaleString();
  if (statLast) statLast.textContent = prevCount.toLocaleString();
  if (statThis) statThis.textContent = curCount.toLocaleString();
  if (statChg) {
    const diff = curCount - prevCount;
    const pct = prevCount > 0 ? Math.round((diff / prevCount) * 100) : (curCount > 0 ? 100 : 0);
    statChg.textContent = (diff >= 0 ? '+' : '') + pct + '% change';
  }

  const ctx = document.getElementById('insights-chart-booking-vol');
  if (ctx && window.Chart) {
    if (window._insightsBookingVolChartInst) window._insightsBookingVolChartInst.destroy();
    window._insightsBookingVolChartInst = new Chart(ctx, {
      type: 'line',
      data: {
        labels: months.map(m => m.shortLabel),
        datasets: [{
          label: 'Bookings Volume',
          data: countsByMonth.map(d => d.count),
          borderColor: '#c49a3c',
          backgroundColor: 'rgba(196, 154, 60, 0.15)',
          borderWidth: 3,
          fill: true,
          tension: 0.35,
          pointBackgroundColor: '#c49a3c',
          pointRadius: 4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          x: { grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#a89070', font: { family: "'DM Sans',sans-serif", size: 11 } } },
          y: { beginAtZero: true, grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#a89070', stepSize: 1 } }
        },
        plugins: {
          legend: { position: 'top', labels: { color: '#f5ebd9', font: { family: "'DM Sans',sans-serif", size: 11 } } }
        }
      }
    });
  }

  const tblEl = document.getElementById('insights-table-insights-booking-vol');
  if (tblEl) {
    tblEl.innerHTML = '<table class="data-table" style="font-size:11px;width:100%;border-collapse:collapse;">'
      + '<thead><tr style="border-bottom:1px solid var(--border);">'
      + '<th style="text-align:left;padding:8px 10px;">Date</th>'
      + '<th style="text-align:left;padding:8px 10px;">Client</th>'
      + '<th style="text-align:left;padding:8px 10px;">Package</th>'
      + '<th style="text-align:left;padding:8px 10px;">Status</th>'
      + '<th style="text-align:right;padding:8px 10px;">Amount</th>'
      + '</tr></thead><tbody>'
      + reservations.filter(r => filterResDate(r, months)).map(r => {
        return '<tr style="border-bottom:1px solid rgba(255,255,255,0.03);">'
          + '<td style="padding:7px 10px;">' + (getResDateStr(r) || 'N/A') + '</td>'
          + '<td style="padding:7px 10px;font-weight:600;">' + (r.client_name || r.name || 'Client') + '</td>'
          + '<td style="padding:7px 10px;color:var(--gold);">' + (r.package_name || r.package || r.packageName || '—') + '</td>'
          + '<td style="padding:7px 10px;text-transform:capitalize;">' + (r.status || 'Pending') + '</td>'
          + '<td style="padding:7px 10px;text-align:right;color:var(--gold);font-weight:700;">₱' + Math.round(parseFloat(r.amount || 0)).toLocaleString() + '</td>'
          + '</tr>';
      }).join('')
      + '</tbody></table>';
  }
}

// ----------------------------------------------------
// PILLAR 4B: Completed vs Cancelled Bookings (Bar Graph)
// ----------------------------------------------------
function renderInsightsCompletedVsCancelled(cache) {
  const key = 'insights-comp-vs-canc';
  const filter = _adminAnalyticsFilters[key] || { anchorYear: new Date().getFullYear(), anchorMonth: new Date().getMonth(), rangeMonths: 12 };
  updateAdminAnalyticsDateLabel(key);
  updateAdminAnalyticsFilterButtonStates(key);
  const months = getAdminMonthRangeKeys(filter);
  const reservations = cache.reservations || [];

  const dataByMonth = months.map(m => {
    let completed = 0, cancelled = 0;
    reservations.filter(r => getResMonthKey(r) === m.key).forEach(r => {
      const st = String(r.status || '').toLowerCase();
      if (st === 'completed') completed++;
      else if (st === 'cancelled') cancelled++;
    });
    return { month: m, completed, cancelled };
  });

  const totalComp = dataByMonth.reduce((s, d) => s + d.completed, 0);
  const totalCanc = dataByMonth.reduce((s, d) => s + d.cancelled, 0);

  const curAnchor = filter.anchorYear + '-' + String(filter.anchorMonth + 1).padStart(2, '0');
  const prevYear = filter.anchorMonth === 0 ? filter.anchorYear - 1 : filter.anchorYear;
  const prevMonth = filter.anchorMonth === 0 ? 11 : filter.anchorMonth - 1;
  const prevKey = prevYear + '-' + String(prevMonth + 1).padStart(2, '0');

  let thisComp = 0, thisCanc = 0;
  let lastComp = 0, lastCanc = 0;

  reservations.forEach(r => {
    const ym = getResMonthKey(r);
    const st = String(r.status || '').toLowerCase();
    if (ym === curAnchor) {
      if (st === 'completed') thisComp++;
      else if (st === 'cancelled') thisCanc++;
    }
    if (ym === prevKey) {
      if (st === 'completed') lastComp++;
      else if (st === 'cancelled') lastCanc++;
    }
  });

  const statCompTot = document.getElementById('stat-insights-comp-total');
  const statCompLast = document.getElementById('stat-insights-comp-last-month');
  const statCompThis = document.getElementById('stat-insights-comp-this-month');
  const statCompChg = document.getElementById('stat-insights-comp-change');
  if (statCompTot) statCompTot.textContent = totalComp.toLocaleString();
  if (statCompLast) statCompLast.textContent = lastComp.toLocaleString();
  if (statCompThis) statCompThis.textContent = thisComp.toLocaleString();
  if (statCompChg) {
    const diff = thisComp - lastComp;
    const pct = lastComp > 0 ? Math.round((diff / lastComp) * 100) : (thisComp > 0 ? 100 : 0);
    statCompChg.textContent = (diff >= 0 ? '+' : '') + pct + '% change';
  }

  const statCancTot = document.getElementById('stat-insights-canc-total');
  const statCancLast = document.getElementById('stat-insights-canc-last-month');
  const statCancThis = document.getElementById('stat-insights-canc-this-month');
  const statCancChg = document.getElementById('stat-insights-canc-change');
  if (statCancTot) statCancTot.textContent = totalCanc.toLocaleString();
  if (statCancLast) statCancLast.textContent = lastCanc.toLocaleString();
  if (statCancThis) statCancThis.textContent = thisCanc.toLocaleString();
  if (statCancChg) {
    const diff = thisCanc - lastCanc;
    const pct = lastCanc > 0 ? Math.round((diff / lastCanc) * 100) : (thisCanc > 0 ? 100 : 0);
    statCancChg.textContent = (diff >= 0 ? '+' : '') + pct + '% change';
  }

  const ctx = document.getElementById('insights-chart-comp-vs-canc');
  if (ctx && window.Chart) {
    if (window._insightsCompVsCancChartInst) window._insightsCompVsCancChartInst.destroy();
    window._insightsCompVsCancChartInst = new Chart(ctx, {
      type: 'bar',
      data: {
        labels: months.map(m => m.shortLabel),
        datasets: [
          { label: 'Completed Bookings', data: dataByMonth.map(d => d.completed), backgroundColor: '#2d8a4e', borderRadius: 4 },
          { label: 'Cancelled Bookings', data: dataByMonth.map(d => d.cancelled), backgroundColor: '#e05656', borderRadius: 4 }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          x: { grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#a89070', font: { family: "'DM Sans',sans-serif", size: 11 } } },
          y: { beginAtZero: true, grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#a89070', stepSize: 1 } }
        },
        plugins: {
          legend: { position: 'top', labels: { color: '#f5ebd9', font: { family: "'DM Sans',sans-serif", size: 11 } } }
        }
      }
    });
  }

  const tblEl = document.getElementById('insights-table-insights-comp-vs-canc');
  if (tblEl) {
    tblEl.innerHTML = '<table class="data-table" style="font-size:11px;width:100%;border-collapse:collapse;">'
      + '<thead><tr style="border-bottom:1px solid var(--border);">'
      + '<th style="text-align:left;padding:8px 10px;">Date</th>'
      + '<th style="text-align:left;padding:8px 10px;">Client</th>'
      + '<th style="text-align:left;padding:8px 10px;">Package</th>'
      + '<th style="text-align:left;padding:8px 10px;">Status</th>'
      + '<th style="text-align:right;padding:8px 10px;">Value</th>'
      + '</tr></thead><tbody>'
      + reservations.filter(r => {
        const st = String(r.status || '').toLowerCase();
        return (st === 'completed' || st === 'cancelled') && filterResDate(r, months);
      }).map(r => {
        const isComp = String(r.status || '').toLowerCase() === 'completed';
        return '<tr style="border-bottom:1px solid rgba(255,255,255,0.03);">'
          + '<td style="padding:7px 10px;">' + (getResDateStr(r) || 'N/A') + '</td>'
          + '<td style="padding:7px 10px;font-weight:600;">' + (r.client_name || r.name || 'Client') + '</td>'
          + '<td style="padding:7px 10px;color:var(--gold);">' + (r.package_name || r.package || r.packageName || '—') + '</td>'
          + '<td style="padding:7px 10px;color:' + (isComp ? 'var(--green,#2d8a4e)' : 'var(--red,#e05656)') + ';font-weight:700;text-transform:capitalize;">' + r.status + '</td>'
          + '<td style="padding:7px 10px;text-align:right;color:var(--gold);font-weight:700;">₱' + Math.round(parseFloat(r.amount || 0)).toLocaleString() + '</td>'
          + '</tr>';
      }).join('')
      + '</tbody></table>';
  }
}

// ----------------------------------------------------
// PILLAR 5: Cancellation Origin Analysis (Pie Graph)
// ----------------------------------------------------
function renderInsightsCancellationOrigin(cache) {
  const key = 'insights-canc-origin';
  const filter = _adminAnalyticsFilters[key] || { anchorYear: new Date().getFullYear(), anchorMonth: new Date().getMonth(), rangeMonths: 12 };
  updateAdminAnalyticsDateLabel(key);
  updateAdminAnalyticsFilterButtonStates(key);
  const months = getAdminMonthRangeKeys(filter);
  const reservations = cache.reservations || [];

  // Strictly filter by active window
  const activeRes = reservations.filter(r => filterResDate(r, months));

  let bizCancel = 0, custCancel = 0;
  activeRes.forEach(r => {
    if (String(r.status || '').toLowerCase() === 'cancelled') {
      const cType = String(r.cancellation_by || r.cancelled_by || '').toLowerCase();
      if (cType.includes('customer') || cType.includes('client')) custCancel++;
      else bizCancel++;
    }
  });

  const totalCanc = bizCancel + custCancel;
  const custPct = totalCanc > 0 ? Math.round((custCancel / totalCanc) * 100) : 0;
  const bizPct = totalCanc > 0 ? Math.round((bizCancel / totalCanc) * 100) : 0;

  const statCust = document.getElementById('stat-insights-canc-cust') || document.getElementById('stat-insights-canc-customer');
  const statBiz = document.getElementById('stat-insights-canc-biz') || document.getElementById('stat-insights-canc-business');
  if (statCust) statCust.textContent = custCancel + ' (' + custPct + '%)';
  if (statBiz) statBiz.textContent = bizCancel + ' (' + bizPct + '%)';

  const ctx = document.getElementById('insights-chart-canc-origin');
  if (ctx && window.Chart) {
    if (window._insightsCancOriginChartInst) window._insightsCancOriginChartInst.destroy();
    window._insightsCancOriginChartInst = new Chart(ctx, {
      type: 'doughnut',
      data: {
        labels: ['Business-Initiated Cancellation (200% Penalty)', 'Customer-Initiated Cancellation'],
        datasets: [{
          data: [bizCancel, custCancel],
          backgroundColor: ['#e05656', '#d97706'],
          borderWidth: 2,
          borderColor: '#16120d'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { position: 'bottom', labels: { color: '#a89070', font: { family: "'DM Sans',sans-serif", size: 11 } } },
          tooltip: {
            callbacks: {
              label: (c) => ' ' + c.label + ': ' + c.raw + ' cancellations'
            }
          }
        }
      }
    });
  }

  const tblEl = document.getElementById('insights-table-insights-canc-origin');
  if (tblEl) {
    tblEl.innerHTML = '<table class="data-table" style="font-size:11px;width:100%;border-collapse:collapse;">'
      + '<thead><tr style="border-bottom:1px solid var(--border);">'
      + '<th style="text-align:left;padding:8px 10px;">Cancellation Origin</th>'
      + '<th style="text-align:right;padding:8px 10px;">Count</th>'
      + '<th style="text-align:right;padding:8px 10px;">Percentage</th>'
      + '</tr></thead><tbody>'
      + '<tr style="border-bottom:1px solid rgba(255,255,255,0.03);"><td style="padding:7px 10px;color:#e05656;font-weight:700;">Business-Initiated</td><td style="padding:7px 10px;text-align:right;">' + bizCancel + '</td><td style="padding:7px 10px;text-align:right;">' + bizPct + '%</td></tr>'
      + '<tr style="border-bottom:1px solid rgba(255,255,255,0.03);"><td style="padding:7px 10px;color:#d97706;font-weight:700;">Customer-Initiated</td><td style="padding:7px 10px;text-align:right;">' + custCancel + '</td><td style="padding:7px 10px;text-align:right;">' + custPct + '%</td></tr>'
      + '</tbody></table>';
  }
}

// ----------------------------------------------------
