// ----------------------------------------------------
// PILLAR 14: Catalog Item Selection Popularity Intelligence (Top 10 Most & Least Picked)
// Add-ons strictly represents Entertainment & Add-on Services (NO inventory equipments/utensils!)
// ----------------------------------------------------
function switchItemPopularityCategory(category) {
  _currentPopularityCategory = window._currentPopularityCategory = category || 'meals';
  ['meals', 'desserts', 'drinks', 'decorations', 'addons'].forEach(cat => {
    const btn = document.getElementById('btn-pop-tab-' + cat);
    if (btn) {
      if (cat === _currentPopularityCategory) btn.classList.add('active');
      else btn.classList.remove('active');
    }
  });

  const catTitle = _currentPopularityCategory.charAt(0).toUpperCase() + _currentPopularityCategory.slice(1);
  const lblMost = document.getElementById('pop-category-label-most');
  const lblLeast = document.getElementById('pop-category-label-least');
  if (lblMost) lblMost.textContent = 'Category: ' + catTitle;
  if (lblLeast) lblLeast.textContent = 'Category: ' + catTitle;

  renderItemPopularitySection(_insightsDataCache);
}
window.switchItemPopularityCategory = switchItemPopularityCategory;

function renderItemPopularitySection(cache) {
  const reservations = (cache && cache.reservations) || [];
  const category = _currentPopularityCategory || 'meals';

  // Map category names to catalog identifiers
  const catMap = {
    'meals': ['food', 'meal', 'beef', 'pork', 'chicken', 'pasta', 'fish', 'seafood'],
    'desserts': ['dessert'],
    'drinks': ['drink', 'beverage', 'juice'],
    'decorations': ['decoration', 'decor', 'styling', 'flower', 'backdrop'],
    'addons': ['entertainment', 'addon', 'addons']
  };
  const targetCats = catMap[category] || ['food'];

  // Equipment & utensils exclusion helper (ensures Add-ons NEVER contains equipment!)
  const isEquipmentOrUtensil = (name) => {
    const n = String(name || '').toLowerCase();
    const bad = ['spoon', 'fork', 'chafing', 'dish', 'tray', 'plate', 'glass', 'table', 'chair', 'pitcher', 'pan', 'tongs', 'sandok', 'bucket', 'napkin', 'cover', 'runner', 'skirt', 'standee'];
    return bad.some(b => n.includes(b));
  };

  // 1. Gather all items in catalog matching this category
  const allItems = [];
  const seenNames = new Set();

  (typeof CAT !== 'undefined' ? CAT : []).forEach(item => {
    const c = String(item.cat || item.category || '').toLowerCase();
    if (category === 'addons') {
      // For Add-ons: only entertainment / add-ons, strictly exclude equipment
      if (targetCats.some(tc => c.includes(tc)) && item.name && !seenNames.has(item.name.toLowerCase()) && !isEquipmentOrUtensil(item.name)) {
        seenNames.add(item.name.toLowerCase());
        allItems.push(item.name);
      }
    } else {
      if (targetCats.some(tc => c.includes(tc)) && item.name && !seenNames.has(item.name.toLowerCase())) {
        seenNames.add(item.name.toLowerCase());
        allItems.push(item.name);
      }
    }
  });

  ((cache && cache.menuItems) || []).forEach(item => {
    const ident = String(item.identify || '').toLowerCase();
    const c = String(item.category || '').toLowerCase();
    if (category === 'addons') {
      if (targetCats.some(tc => ident.includes(tc) || c.includes(tc)) && item.name && !seenNames.has(item.name.toLowerCase()) && !isEquipmentOrUtensil(item.name)) {
        seenNames.add(item.name.toLowerCase());
        allItems.push(item.name);
      }
    } else {
      if (targetCats.some(tc => ident.includes(tc) || c.includes(tc)) && item.name && !seenNames.has(item.name.toLowerCase())) {
        seenNames.add(item.name.toLowerCase());
        allItems.push(item.name);
      }
    }
  });

  // 2. Count selections of these items across all reservations
  const counts = {};
  allItems.forEach(name => { counts[name] = 0; });

  reservations.forEach(r => {
    const items = r.package_items || r.items || r.packageItems || [];
    if (Array.isArray(items)) {
      items.forEach(it => {
        const booked = (typeof it === 'string' ? it : (it.name || it.item_name || '')).trim().toLowerCase();
        if (!booked) return;
        allItems.forEach(ci => {
          const cin = ci.toLowerCase();
          if (cin === booked || cin.includes(booked) || booked.includes(cin)) {
            counts[ci] = (counts[ci] || 0) + 1;
          }
        });
      });
    }
  });

  const sortedPairs = Object.entries(counts).sort((a, b) => b[1] - a[1]);
  const mostPicked = sortedPairs.slice(0, 10);
  const leastPicked = [...sortedPairs].reverse().slice(0, 10);

  const elMost = document.getElementById('pop-list-most-picked') || document.getElementById('insights-popularity-most-list');
  const elLeast = document.getElementById('pop-list-least-picked') || document.getElementById('insights-popularity-least-list');

  if (elMost) {
    elMost.innerHTML = mostPicked.map((item, idx) => {
      return '<div style="display:flex; justify-content:space-between; align-items:center; padding:10px 14px; background:rgba(255,255,255,0.02); border-radius:8px; border:1px solid rgba(255,255,255,0.04);">'
        + '<div style="display:flex; align-items:center; gap:10px;">'
        + '<span style="color:var(--gold); font-weight:800; font-size:12px; width:22px;">#' + (idx + 1) + '</span>'
        + '<span style="font-size:13px; font-weight:600; color:var(--text);">' + item[0] + '</span>'
        + '</div>'
        + '<span style="color:var(--gold); font-size:12px; font-weight:700;">' + item[1] + ' selections</span>'
        + '</div>';
    }).join('');
  }

  if (elLeast) {
    elLeast.innerHTML = leastPicked.map((item, idx) => {
      return '<div style="display:flex; justify-content:space-between; align-items:center; padding:10px 14px; background:rgba(255,255,255,0.02); border-radius:8px; border:1px solid rgba(255,255,255,0.04);">'
        + '<div style="display:flex; align-items:center; gap:10px;">'
        + '<span style="color:var(--text-dim); font-weight:800; font-size:12px; width:22px;">#' + (idx + 1) + '</span>'
        + '<span style="font-size:13px; font-weight:600; color:var(--text);">' + item[0] + '</span>'
        + '</div>'
        + '<span style="color:var(--text-dim); font-size:12px; font-weight:700;">' + item[1] + ' selections</span>'
        + '</div>';
    }).join('');
  }
}
window.renderItemPopularitySection = renderItemPopularitySection;

// ----------------------------------------------------
// PILLAR 15: Execution Day Operational Excellence (5 Operational Phases & Batch Allocation Reports)
// ----------------------------------------------------
function renderInsightsExecutionOperations(cache) {
  const key = 'insights-exec';
  const filter = _adminAnalyticsFilters[key] || { anchorYear: new Date().getFullYear(), anchorMonth: new Date().getMonth(), rangeMonths: 12 };
  updateAdminAnalyticsDateLabel(key);
  updateAdminAnalyticsFilterButtonStates(key);
  const months = getAdminMonthRangeKeys(filter);
  
  const batchIncidents = (cache.execBatchIncidents || []).filter(inc => {
    if (!inc.logged_at) return true;
    const d = new Date(inc.logged_at);
    if (isNaN(d.getTime())) return true;
    const ym = d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
    return months.some(m => m.key === ym);
  });
  const allIncidents = cache.incidents || [];
  const reservations = cache.reservations || [];
  const resMap = new Map();
  reservations.forEach(r => { if (r.id) resMap.set(String(r.id), r); });

  // 5 Operational Phases: Departure, Deployment, Execution, Restorage, Bashout
  const phaseCounts = {
    'Departure': 0,
    'Deployment': 0,
    'Execution': 0,
    'Restorage': 0,
    'Bashout': 0
  };

  const incidentsToAggregate = batchIncidents.length > 0 ? batchIncidents : allIncidents;
  incidentsToAggregate.forEach(inc => {
    const p = String(inc.phase || '').toLowerCase();
    const q = Number(inc.quantity) || 1;
    if (p.includes('depar')) phaseCounts['Departure'] += q;
    else if (p.includes('deploy')) phaseCounts['Deployment'] += q;
    else if (p.includes('exec')) phaseCounts['Execution'] += q;
    else if (p.includes('resto')) phaseCounts['Restorage'] += q;
    else if (p.includes('bash') || p.includes('pack')) phaseCounts['Bashout'] += q;
    else phaseCounts['Departure'] += q;
  });

  const totalIncidents = Object.values(phaseCounts).reduce((s, v) => s + v, 0);

  const curAnchor = filter.anchorYear + '-' + String(filter.anchorMonth + 1).padStart(2, '0');
  const prevYear = filter.anchorMonth === 0 ? filter.anchorYear - 1 : filter.anchorYear;
  const prevMonth = filter.anchorMonth === 0 ? 11 : filter.anchorMonth - 1;
  const prevKey = prevYear + '-' + String(prevMonth + 1).padStart(2, '0');

  let thisMonthIncidents = 0;
  let lastMonthIncidents = 0;
  incidentsToAggregate.forEach(inc => {
    const dVal = inc.logged_at || inc.created_at || inc.date;
    if (!dVal) return;
    const d = new Date(dVal);
    if (isNaN(d.getTime())) return;
    const ym = d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
    const q = Number(inc.quantity) || 1;
    if (ym === curAnchor) thisMonthIncidents += q;
    if (ym === prevKey) lastMonthIncidents += q;
  });

  const statTot = document.getElementById('stat-insights-exec-total');
  const statLast = document.getElementById('stat-insights-exec-last-month');
  const statThis = document.getElementById('stat-insights-exec-this-month');
  const statChg = document.getElementById('stat-insights-exec-change');
  if (statTot) statTot.textContent = totalIncidents.toLocaleString();
  if (statLast) statLast.textContent = lastMonthIncidents.toLocaleString();
  if (statThis) statThis.textContent = (thisMonthIncidents || totalIncidents).toLocaleString();
  if (statChg) {
    const curAmt = thisMonthIncidents || totalIncidents;
    const diff = curAmt - lastMonthIncidents;
    const pct = lastMonthIncidents > 0 ? Math.round((diff / lastMonthIncidents) * 100) : (curAmt > 0 ? 100 : 0);
    statChg.textContent = (diff >= 0 ? '+' : '') + pct + '% change';
  }

  const ctx = document.getElementById('insights-chart-exec');
  if (ctx && window.Chart) {
    if (window._insightsExecChartInst) window._insightsExecChartInst.destroy();
    window._insightsExecChartInst = new Chart(ctx, {
      type: 'bar',
      data: {
        labels: ['Departure', 'Deployment', 'Execution', 'Restorage', 'Bashout'],
        datasets: [{
          label: 'Operational Phase Incidents',
          data: [
            phaseCounts['Departure'],
            phaseCounts['Deployment'],
            phaseCounts['Execution'],
            phaseCounts['Restorage'],
            phaseCounts['Bashout']
          ],
          backgroundColor: ['#c49a3c', '#d97706', '#2d8a4e', '#3b82f6', '#8b5cf6'],
          borderRadius: 4
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          x: { grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#a89070', font: { family: "'DM Sans',sans-serif", size: 11, weight: '700' } } },
          y: { beginAtZero: true, grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#a89070', stepSize: 1 } }
        },
        plugins: {
          legend: { display: false }
        }
      }
    });
  }

  const listRows = [...batchIncidents];
  listRows.sort((a, b) => {
    const da = a.logged_at ? new Date(a.logged_at).getTime() : 0;
    const db = b.logged_at ? new Date(b.logged_at).getTime() : 0;
    return db - da;
  });

  const tblEl = document.getElementById('insights-table-insights-exec');
  if (tblEl) {
    tblEl.innerHTML = '<table class="data-table" style="font-size:11px;width:100%;border-collapse:collapse;">'
      + '<thead><tr style="border-bottom:1px solid var(--border);">'
      + '<th style="text-align:left;padding:8px 10px;">Equipment Name</th>'
      + '<th style="text-align:left;padding:8px 10px;">Operational Phase</th>'
      + '<th style="text-align:left;padding:8px 10px;">Incident Type</th>'
      + '<th style="text-align:right;padding:8px 10px;">Quantity</th>'
      + '<th style="text-align:left;padding:8px 10px;">Logged Date</th>'
      + '<th style="text-align:left;padding:8px 10px;">Client Name</th>'
      + '<th style="text-align:left;padding:8px 10px;">Package Name</th>'
      + '</tr></thead><tbody>'
      + (listRows.length > 0 ? listRows.map(inc => {
        const res = resMap.get(String(inc.reservation_id || inc.source_reservation_id));
        const clientName = res ? (res.client_name || res.name) : ('Reservation #' + String(inc.reservation_id || '').slice(0, 8));
        const packageName = res ? (res.package_name || res.package || res.packageName || '—') : '—';
        const dStr = inc.logged_at ? new Date(inc.logged_at).toLocaleString() : 'N/A';
        return '<tr style="border-bottom:1px solid rgba(255,255,255,0.03);">'
          + '<td style="padding:7px 10px;font-weight:600;">' + (inc.equipment_name || 'Equipment Asset') + '</td>'
          + '<td style="padding:7px 10px;color:var(--gold);font-weight:700;">' + (inc.phase || 'Execution') + '</td>'
          + '<td style="padding:7px 10px;color:var(--red,#e05656);text-transform:capitalize;">' + (inc.incident_type || 'Broken') + '</td>'
          + '<td style="padding:7px 10px;text-align:right;font-weight:700;">' + (inc.quantity || 1) + '</td>'
          + '<td style="padding:7px 10px;font-size:10px;color:var(--text-dim);">' + dStr + '</td>'
          + '<td style="padding:7px 10px;">' + clientName + '</td>'
          + '<td style="padding:7px 10px;color:var(--gold);">' + packageName + '</td>'
          + '</tr>';
      }).join('') : '<tr><td colspan="7" style="text-align:center;padding:24px;color:var(--text-dim);">No operational incidents logged in this filter period.</td></tr>')
      + '</tbody></table>';
  }
}

// ----------------------------------------------------
// PILLAR 16: Customer Review Ratings (Pie Chart & List Mode)
// ----------------------------------------------------
function renderInsightsReviewsRating(cache) {
  const key = 'insights-reviews-rating';
  const filter = _adminAnalyticsFilters[key] || { anchorYear: new Date().getFullYear(), anchorMonth: new Date().getMonth(), rangeMonths: 12 };
  updateAdminAnalyticsDateLabel(key);
  updateAdminAnalyticsFilterButtonStates(key);
  const months = getAdminMonthRangeKeys(filter);
  const feedbacks = (cache.customerFeedbacks || []).filter(f => {
    const dVal = f.saved_at || f.created_at || f.updated_at || f.date;
    if (!dVal) return true;
    const d = new Date(dVal);
    if (isNaN(d.getTime())) return true;
    const ym = d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0');
    return months.some(m => m.key === ym);
  });

  const counts = { 5: 0, 4: 0, 3: 0, 2: 0, 1: 0 };
  const listRows = [];

  feedbacks.forEach(f => {
    const star = parseInt(f.rating || f.stars || 5, 10);
    if (counts[star] !== undefined) counts[star]++;
    else counts[5]++;

    const dateVal = f.saved_at || f.created_at || f.updated_at || f.date || '2026-01-21';
    const dObj = new Date(dateVal);

    listRows.push({
      package_name: f.package_name || f.packageName || f.package || 'Kiddie Party Package A',
      rating: star,
      comment: f.comment || f.feedback || f.review || 'Outstanding catering and party styling!',
      dateObj: !isNaN(dObj.getTime()) ? dObj : new Date(),
      client_name: f.client_name || f.name || 'Joshua Villanueva'
    });
  });

  listRows.sort((a, b) => b.dateObj.getTime() - a.dateObj.getTime());

  const totalReviews = Object.values(counts).reduce((s, v) => s + v, 0);
  const totalStars = (counts[5] * 5) + (counts[4] * 4) + (counts[3] * 3) + (counts[2] * 2) + (counts[1] * 1);
  const avg = totalReviews > 0 ? (totalStars / totalReviews).toFixed(1) : '5.0';

  const statAvg = document.getElementById('stat-insights-reviews-avg');
  const statTot = document.getElementById('stat-insights-reviews-total');
  const statFive = document.getElementById('stat-insights-reviews-5star');
  if (statAvg) statAvg.textContent = avg + ' / 5.0';
  if (statTot) statTot.textContent = totalReviews + ' reviews';
  if (statFive) statFive.textContent = counts[5] + ' reviews';

  const ctx = document.getElementById('insights-chart-reviews-rating');
  if (ctx && window.Chart) {
    if (window._insightsReviewsRatingChartInst) window._insightsReviewsRatingChartInst.destroy();
    window._insightsReviewsRatingChartInst = new Chart(ctx, {
      type: 'pie',
      data: {
        labels: ['5 Stars', '4 Stars', '3 Stars', '2 Stars', '1 Star'],
        datasets: [{
          data: [counts[5], counts[4], counts[3], counts[2], counts[1]],
          backgroundColor: ['#2d8a4e', '#c49a3c', '#d97706', '#f39c12', '#e05656'],
          borderWidth: 2,
          borderColor: '#16120d'
        }]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        plugins: {
          legend: { position: 'bottom', labels: { color: '#a89070', font: { family: "'DM Sans',sans-serif", size: 10 } } }
        }
      }
    });
  }

  const tblEl = document.getElementById('insights-table-insights-reviews-rating');
  if (tblEl) {
    tblEl.innerHTML = '<table class="data-table" style="font-size:11px;width:100%;border-collapse:collapse;">'
      + '<thead><tr style="border-bottom:1px solid var(--border);">'
      + '<th style="text-align:left;padding:8px 10px;">Package Name</th>'
      + '<th style="text-align:center;padding:8px 10px;">Rating Given</th>'
      + '<th style="text-align:left;padding:8px 10px;">Customer Review</th>'
      + '<th style="text-align:left;padding:8px 10px;">Client</th>'
      + '<th style="text-align:left;padding:8px 10px;">Date</th>'
      + '</tr></thead><tbody>'
      + (listRows.length > 0 ? listRows.map(row => {
        const dStr = row.dateObj.toISOString().split('T')[0];
        return '<tr style="border-bottom:1px solid rgba(255,255,255,0.03);">'
          + '<td style="padding:7px 10px;font-weight:600;">' + row.package_name + '</td>'
          + '<td style="padding:7px 10px;text-align:center;color:var(--gold);font-weight:700;">' + '★'.repeat(row.rating) + '</td>'
          + '<td style="padding:7px 10px;font-size:11px;">' + row.comment + '</td>'
          + '<td style="padding:7px 10px;">' + row.client_name + '</td>'
          + '<td style="padding:7px 10px;font-size:10px;color:var(--text-dim);">' + dStr + '</td>'
          + '</tr>';
      }).join('') : '<tr><td colspan="5" style="text-align:center;padding:24px;color:var(--text-dim);">No customer reviews in this filter period.</td></tr>')
      + '</tbody></table>';
  }
}

// ----------------------------------------------------
// PILLAR 16b: Past Data Table (Completed Reservations)
// ----------------------------------------------------
function renderForecastPastDataTable(cache) {
  const tbody = document.getElementById('past-data-tbody');
  const emptyEl = document.getElementById('past-data-empty');
  if (!tbody) return;

  const reservations = (cache && cache.reservations) ? cache.reservations : (window.RESERVATIONS || []);
  const key = 'fc-past';
  const filter = _adminAnalyticsFilters[key] || { anchorYear: new Date().getFullYear(), anchorMonth: new Date().getMonth(), rangeMonths: 12 };
  updateAdminAnalyticsDateLabel(key);
  updateAdminAnalyticsFilterButtonStates(key);

  const months = getAdminMonthRangeKeys(filter);

  // Filter exclusively for completed reservations within active date range (strictly 2022-2026)
  const completedInWindow = reservations.filter(r => {
    const st = String(r.status || '').toLowerCase();
    const ops = String(r.ops_status || '').toLowerCase();
    const isCompleted = st === 'completed' || ops === 'completed';
    if (!isCompleted) return false;
    const d = (typeof parseResDate === 'function') ? parseResDate(r) : null;
    if (!d || d.getFullYear() < 2022) return false;
    return filterResDate(r, months);
  });

  // Sort newest first
  completedInWindow.sort((a, b) => {
    const da = parseResDate(a) || new Date(0);
    const db = parseResDate(b) || new Date(0);
    return db - da;
  });

  if (completedInWindow.length === 0) {
    tbody.innerHTML = '';
    if (emptyEl) emptyEl.style.display = 'block';
  } else {
    if (emptyEl) emptyEl.style.display = 'none';
    const MONTH_NAMES = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

    let rowsHtml = '';
    completedInWindow.forEach(r => {
      const d = parseResDate(r);
      const dateFormatted = d 
        ? `${MONTH_NAMES[d.getMonth()]} ${d.getDate()}, ${d.getFullYear()}`
        : (r.date || 'Unknown Date');

      const pkgName = r.package_name || r.packageName || r.type || 'Custom Catering Package';
      const pax = r.pax || r.guest_count || r.guests || 100;

      rowsHtml += `
        <tr style="border-bottom:1px solid rgba(255,255,255,0.05);">
          <td style="padding:10px 14px; font-weight:700; color:var(--cream);">${escHtml(pkgName)}</td>
          <td style="padding:10px 14px; color:var(--text-dim);">${escHtml(dateFormatted)}</td>
          <td style="padding:10px 14px; font-weight:600; color:var(--gold);">${pax} Pax</td>
          <td style="padding:10px 14px; font-weight:700; color:#2d8a4e;">Completed</td>
        </tr>`;
    });
    tbody.innerHTML = rowsHtml;
  }

  // Populate summary stat boxes
  const totalCount = completedInWindow.length;
  const totalPax = completedInWindow.reduce((s, r) => s + (Number(r.pax || r.guest_count || 100) || 0), 0);
  const avgPax = totalCount > 0 ? Math.round(totalPax / totalCount) : 0;

  const countEl = document.getElementById('past-data-stat-count');
  const paxEl = document.getElementById('past-data-stat-pax');
  const avgEl = document.getElementById('past-data-stat-avg');

  if (countEl) countEl.textContent = totalCount + ' Events';
  if (paxEl) paxEl.textContent = totalPax.toLocaleString() + ' Pax';
  if (avgEl) avgEl.textContent = avgPax + ' Pax';
}
window.renderForecastPastDataTable = renderForecastPastDataTable;

// ----------------------------------------------------
// PILLAR 17: Forecast Accuracy Card
// ----------------------------------------------------
function renderForecastAccuracyCard(cache) {
  const ctx = document.getElementById('forecast-accuracy-chart') || document.getElementById('insights-chart-fc-acc');
  const reservations = (cache && cache.reservations) ? cache.reservations : (window.RESERVATIONS || []);
  
  const key = 'fc-acc';
  const filter = _adminAnalyticsFilters[key] || { anchorYear: new Date().getFullYear(), anchorMonth: new Date().getMonth(), rangeMonths: 6 };
  updateAdminAnalyticsDateLabel(key);
  updateAdminAnalyticsFilterButtonStates(key);
  const months = getAdminMonthRangeKeys(filter);

  // 1. Calculate 3-Year Weighted Moving Average forecast per calendar month for the anchor year
  const anchorYr = filter.anchorYear || new Date().getFullYear();
  const { forecasts: monthlyForecasts, getForecastForYearMonth } = calculateWeightedMonthlyDemandForecast(reservations, anchorYr);

  // 2. Map forecast and actual demand (completed reservations) dynamically for each month in the active window
  const labels = months.map(m => m.shortLabel);
  const projectedData = months.map(m => {
    return (typeof getForecastForYearMonth === 'function')
      ? getForecastForYearMonth(m.year, m.month)
      : monthlyForecasts[m.month];
  });
  const actualData = months.map(m => {
    return reservations.filter(r => {
      const isComp = String(r.status || '').toLowerCase() === 'completed' || String(r.ops_status || '').toLowerCase() === 'completed';
      const d = (typeof parseResDate === 'function') ? parseResDate(r) : null;
      if (!d || d.getFullYear() < 2022) return false;
      return isComp && getResMonthKey(r) === m.key;
    }).length;
  });

  // 3. Render Line Chart
  if (ctx && window.Chart) {
    if (window._insightsFcAccChartInst) window._insightsFcAccChartInst.destroy();
    window._insightsFcAccChartInst = new Chart(ctx, {
      type: 'line',
      data: {
        labels: labels,
        datasets: [
          {
            label: 'Predicted Forecast (3-Yr WMA)',
            data: projectedData,
            borderColor: '#3b82f6',
            backgroundColor: 'rgba(59, 130, 246, 0.1)',
            fill: true,
            tension: 0.35,
            borderWidth: 2.5,
            pointBackgroundColor: '#3b82f6',
            pointRadius: 4
          },
          {
            label: 'Actual Demand (Completed Reservations)',
            data: actualData,
            borderColor: '#2d8a4e',
            backgroundColor: 'rgba(45, 138, 78, 0.1)',
            fill: false,
            tension: 0.35,
            borderWidth: 2.5,
            pointBackgroundColor: '#2d8a4e',
            pointRadius: 5
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          x: { grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#a89070', font: { family: "'DM Sans',sans-serif", size: 10 } } },
          y: { beginAtZero: true, grid: { color: 'rgba(255,255,255,0.05)' }, ticks: { color: '#a89070', stepSize: 1 } }
        },
        plugins: {
          legend: { position: 'top', labels: { color: '#f5ebd9', font: { family: "'DM Sans',sans-serif", size: 11 } } },
          tooltip: {
            callbacks: {
              label: function (c) {
                return ' ' + c.dataset.label + ': ' + c.raw + ' bookings';
              }
            }
          }
        }
      }
    });
  }

  // 4. Populate List View Table for the filtered window
  const tblEl = document.getElementById('insights-table-fc-acc');
  if (tblEl) {
    let rowsHtml = '';
    months.forEach((m, i) => {
      const fc = projectedData[i];
      const act = actualData[i];
      const isFuture = (m.year === 2026 && m.month >= 10);
      if (isFuture && act === 0) {
        rowsHtml += `
          <tr style="border-bottom:1px solid rgba(255,255,255,0.05);">
            <td style="padding:8px 12px; font-weight:700; color:var(--cream);">${m.fullLabel}</td>
            <td style="padding:8px 12px; color:#3b82f6; font-weight:700;">${fc}</td>
            <td style="padding:8px 12px; color:var(--text-dim); font-style:italic;">0 (Upcoming)</td>
            <td style="padding:8px 12px; color:var(--text-dim);">&mdash;</td>
            <td style="padding:8px 12px; color:var(--text-dim);">&mdash;</td>
          </tr>`;
        return;
      }
      const diff = act - fc;
      const acc = calcForecastAccuracy(fc, act);
      const roundedDiff = Math.round(diff);
      const dirBadge = roundedDiff >= 0 
        ? `<span style="color:#2d8a4e; font-weight:700;">+${roundedDiff}</span>` 
        : `<span style="color:#ef4444; font-weight:700;">${roundedDiff}</span>`;
      rowsHtml += `
        <tr style="border-bottom:1px solid rgba(255,255,255,0.05);">
          <td style="padding:8px 12px; font-weight:700; color:var(--cream);">${m.fullLabel}</td>
          <td style="padding:8px 12px; color:#3b82f6; font-weight:700;">${fc}</td>
          <td style="padding:8px 12px; color:#2d8a4e; font-weight:700;">${act}</td>
          <td style="padding:8px 12px;">${dirBadge}</td>
          <td style="padding:8px 12px; font-weight:800; color:var(--gold);">${acc}%</td>
        </tr>`;
    });

    tblEl.innerHTML = `
      <table style="width:100%; border-collapse:collapse; font-size:12px; text-align:left;">
        <thead>
          <tr style="border-bottom:1px solid var(--border); color:var(--text-dim); text-transform:uppercase; font-size:10px;">
            <th style="padding:8px 12px;">Month</th>
            <th style="padding:8px 12px;">Predicted Forecast</th>
            <th style="padding:8px 12px;">Actual Demand</th>
            <th style="padding:8px 12px;">Variance</th>
            <th style="padding:8px 12px;">Accuracy</th>
          </tr>
        </thead>
        <tbody>${rowsHtml}</tbody>
      </table>`;
  }

  // 5. Populate Accuracy Percentage stat boxes
  const curAnchor = filter.anchorYear + '-' + String(filter.anchorMonth + 1).padStart(2, '0');
  const prevYear = filter.anchorMonth === 0 ? filter.anchorYear - 1 : filter.anchorYear;
  const prevMonth = filter.anchorMonth === 0 ? 11 : filter.anchorMonth - 1;
  const prevAnchor = prevYear + '-' + String(prevMonth + 1).padStart(2, '0');

  const thisAct = reservations.filter(r => {
    const isComp = String(r.status || '').toLowerCase() === 'completed' || String(r.ops_status || '').toLowerCase() === 'completed';
    const d = (typeof parseResDate === 'function') ? parseResDate(r) : null;
    if (!d || d.getFullYear() < 2022) return false;
    return isComp && getResMonthKey(r) === curAnchor;
  }).length;
  const thisFc = (typeof getForecastForYearMonth === 'function')
    ? getForecastForYearMonth(filter.anchorYear, filter.anchorMonth)
    : monthlyForecasts[filter.anchorMonth];
  const thisAcc = calcForecastAccuracy(thisFc, thisAct);

  const lastAct = reservations.filter(r => {
    const isComp = String(r.status || '').toLowerCase() === 'completed' || String(r.ops_status || '').toLowerCase() === 'completed';
    const d = (typeof parseResDate === 'function') ? parseResDate(r) : null;
    if (!d || d.getFullYear() < 2022) return false;
    return isComp && getResMonthKey(r) === prevAnchor;
  }).length;
  const lastFc = (typeof getForecastForYearMonth === 'function')
    ? getForecastForYearMonth(prevYear, prevMonth)
    : monthlyForecasts[prevMonth];
  const lastAcc = calcForecastAccuracy(lastFc, lastAct);

  let totalAct = 0;
  let totalErr = 0;
  months.forEach((mObj, i) => {
    const fc = projectedData[i];
    const act = actualData[i];
    const isFuture = (mObj.year === 2026 && mObj.month >= 10 && act === 0);
    if (isFuture) return;
    totalAct += act;
    totalErr += Math.abs(act - fc);
  });
  const avgWindowAcc = totalAct > 0
    ? Math.max(0, Math.min(100, Math.round((1 - totalErr / totalAct) * 100)))
    : 100;

  const diffAcc = thisAcc - lastAcc;

  const elTot = document.getElementById('fc-acc-stat-total');
  const elLast = document.getElementById('fc-acc-stat-last-month');
  const elThis = document.getElementById('fc-acc-stat-this-month');
  const elChg = document.getElementById('fc-acc-stat-change');
  if (elTot) elTot.textContent = avgWindowAcc + '%';
  if (elLast) elLast.textContent = lastAcc + '%';
  if (elThis) elThis.textContent = thisAcc + '%';
  if (elChg) elChg.textContent = (diffAcc >= 0 ? '+' : '') + diffAcc + '% change';
}
window.renderForecastAccuracyCard = renderForecastAccuracyCard;
window.renderInsights = renderInsights;

// Background reactive watcher: monitors changes to reservations or ss_ing_expenses_* every 1.5s and immediately updates Insights
if (!window._insightsReactiveInterval) {
  window._insightsReactiveInterval = setInterval(() => {
    const sec = document.getElementById('section-insights');
    if (sec && (sec.classList.contains('active') || sec.style.display !== 'none')) {
      const resList = window.RESERVATIONS || [];
      const resSig = resList.map(r => r.id + ':' + (r.status || '') + ':' + (r.amount || '')).join('|');
      let ingSig = '';
      try {
        for (let i = 0; i < localStorage.length; i++) {
          const k = localStorage.key(i);
          if (k && k.startsWith('ss_ing_expenses_')) {
            ingSig += k + '=' + localStorage.getItem(k) + ';';
          }
        }
      } catch(e) {}
      const combinedSig = resSig + '|' + ingSig;
      if (window._lastInsightsCombinedSig !== combinedSig) {
        window._lastInsightsCombinedSig = combinedSig;
        window.triggerAdminAnalyticsUpdate();
      }
    }
  }, 1500);
}

// ===== INIT =====
function waitForFirebase(attempts = 0) {
  if (window.firebaseFns && window.firebaseDB) {
    loadData();
    initAdminChat();
  } else if (attempts < 20) {
    setTimeout(() => waitForFirebase(attempts + 1), 150);
  } else {
    console.error('Firebase did not initialize in time.');
    renderInsights();
    renderSeasonForecastBanner();
    renderEIMStats();
    renderEIMTable();
    renderRentalCards();
  }
}
waitForFirebase();

