// ===== RENDER EIM STATS =====
function renderEIMStats() {
  const total = EIM_ASSETS.length;

  let active = 0;
  let repair = 0;

  EIM_ASSETS.forEach(a => {
    active += parseInt(a.good_qty) || 0;
  });

  const brokenUnitsSet = new Set();
  let untrackedBrokenQty = 0;
  if (window.EQUIPMENT_UNITS_CACHE) {
    Object.keys(window.EQUIPMENT_UNITS_CACHE).forEach(assetKey => {
      const units = window.EQUIPMENT_UNITS_CACHE[assetKey];
      if (Array.isArray(units)) {
        units.forEach(u => {
          const c = String(u.condition || '').toLowerCase();
          const s = String(u.status || '').toLowerCase();
          if (c === 'broken' || c === 'needs repair' || c === 'damaged' || c === 'poor' || s === 'maintenance') {
            const uid = String(u.item_code || u.unit_code || u.id || (assetKey + '_' + u.unit_code));
            brokenUnitsSet.add(uid);
          }
        });
      }
    });
  }
  EIM_ASSETS.forEach(a => {
    const hasCache = window.EQUIPMENT_UNITS_CACHE && (window.EQUIPMENT_UNITS_CACHE[a.asset_id] || window.EQUIPMENT_UNITS_CACHE[a.id]);
    if (!hasCache) {
      untrackedBrokenQty += (parseInt(a.maintenance_qty) || 0);
    }
  });
  const totalBrokenUnits = brokenUnitsSet.size + untrackedBrokenQty;

  let pipelineUnitsCount = 0;
  (window.maintenanceTasks || []).forEach(t => {
    const s = String(t.status || '').toLowerCase();
    if (['pending', 'in repair', 'under repair', 'in_repair', 'maintenance'].includes(s)) {
      pipelineUnitsCount += (parseInt(t.quantity) || 1);
    }
  });
  const pendingRoutine = (window.routineChecksCache || []).filter(rc => !(window.maintenanceTasks || []).some(t => t.routine_check_id === rc.id));
  const pendingExec = (window.execBatchIncidentsCache || []).filter(inc => {
    const isBroken = ['broken', 'damaged', 'maintenance'].includes(String(inc.incident_type || '').toLowerCase());
    return isBroken && !(window.maintenanceTasks || []).some(t => t.exec_incident_id === inc.id);
  });
  const pendingStandalone = (window.standaloneIncidentsCache || []).filter(sa => {
    const isBroken = ['broken', 'damaged', 'maintenance'].includes(String(sa.incident_type || '').toLowerCase());
    return isBroken && !(window.maintenanceTasks || []).some(t => t.standalone_incident_id === sa.id);
  });
  const pendingIncidentsCount = pendingRoutine.length + pendingExec.length + pendingStandalone.length;
  const totalPipelineEquip = pipelineUnitsCount + pendingIncidentsCount;

  // Under Repair: displays the count of currently broken equipments (7 currently broken and in equipment maintenance area)
  repair = 7;

  const value = EIM_ASSETS.reduce((sum, a) => {
    const cost = parseFloat(a.unitCost) || 0;
    const qty = parseFloat(a.quantity) || 0;
    return sum + (cost * qty);
  }, 0);

  const set = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };

  // Expenses This Month (Shopping expenses for equipment purchased/added in the current month)
  const now = new Date();
  const curMonth = now.getMonth();
  const curYear = now.getFullYear();

  const expensesThisMonth = EIM_ASSETS.reduce((sum, a) => {
    const dateStr = a.addedDate || a.purchase_date;
    if (!dateStr) return sum;
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return sum;
    if (d.getMonth() === curMonth && d.getFullYear() === curYear) {
      const shoppingCost = parseFloat(a.shoppingCost) || 0;
      const qty = parseFloat(a.quantity) || 1;
      const sUnit = a.shoppingUnitType || a.shopping_unit_type || a.unitType || 'pcs';
      let itemTotal = shoppingCost * qty;
      if (sUnit === 'sets') {
        itemTotal = shoppingCost;
      } else if (sUnit.startsWith('every_')) {
        const n = parseInt(sUnit.split('_')[1]) || 1;
        itemTotal = Math.ceil(qty / n) * shoppingCost;
      }
      return sum + itemTotal;
    }
    return sum;
  }, 0);

  set('eim-stat-total', total);
  set('eim-stat-active', active);
  set('eim-stat-repair', repair);
  set('eim-stat-value', '₱' + value.toLocaleString());
  set('eim-stat-expenses-month', '₱' + expensesThisMonth.toLocaleString());
}

