function switchEIMPnl(val) {
  const pnlList = document.getElementById('eim-pnl-list');
  const pnlLogs = document.getElementById('eim-pnl-logs');
  const pnlAlloc = document.getElementById('eim-pnl-allocations');
  const pnlRental = document.getElementById('eim-pnl-rental-history');
  const pnlAutoInclusion = document.getElementById('eim-pnl-autoinclusion');
  const pnlIncidentLogs = document.getElementById('eim-pnl-incident-logs');
  const pnlAllocHistory = document.getElementById('eim-pnl-alloc-history');

  if (pnlList) pnlList.style.display = val === 'list' ? 'block' : 'none';
  if (pnlLogs) pnlLogs.style.display = val === 'logs' ? 'block' : 'none';
  if (pnlAlloc) pnlAlloc.style.display = val === 'allocations' ? 'block' : 'none';
  if (pnlRental) pnlRental.style.display = val === 'rental-history' ? 'block' : 'none';
  if (pnlAutoInclusion) pnlAutoInclusion.style.display = val === 'autoinclusion' ? 'block' : 'none';
  if (pnlIncidentLogs) pnlIncidentLogs.style.display = val === 'incident-logs' ? 'block' : 'none';
  if (pnlAllocHistory) pnlAllocHistory.style.display = val === 'alloc-history' ? 'block' : 'none';

  const tList = document.getElementById('tab-eim-list');
  const tLogs = document.getElementById('tab-eim-logs');
  const tAlloc = document.getElementById('tab-eim-alloc');
  const tRental = document.getElementById('tab-eim-rental-history');
  const tAutoInclusion = document.getElementById('tab-eim-autoinclusion');
  const tIncidentLogs = document.getElementById('tab-eim-incident-logs');
  const tAllocHistory = document.getElementById('tab-eim-alloc-history');

  if (tList) tList.classList.toggle('active', val === 'list');
  if (tLogs) tLogs.classList.toggle('active', val === 'logs');
  if (tAlloc) tAlloc.classList.toggle('active', val === 'allocations');
  if (tRental) tRental.classList.toggle('active', val === 'rental-history');
  if (tAutoInclusion) tAutoInclusion.classList.toggle('active', val === 'autoinclusion');
  if (tIncidentLogs) tIncidentLogs.classList.toggle('active', val === 'incident-logs');
  if (tAllocHistory) tAllocHistory.classList.toggle('active', val === 'alloc-history');

  if (val === 'logs') {
    if (typeof loadEIMLogsFromSupabase === 'function') loadEIMLogsFromSupabase();
    renderEIMLogs();
  }
  if (val === 'allocations') switchAllocTab('availability');
  if (val === 'rental-history') renderEqRentalHistory();
  if (val === 'autoinclusion') renderEIMAutoInclusionTable();
  if (val === 'incident-logs') renderEIMIncidentLogs();
  if (val === 'alloc-history') renderEIMAllocationHistory();
}
window.switchEIMPnl = switchEIMPnl;

async function renderEIMAllocationHistory() {
  const container = document.getElementById('eim-alloc-history-list');
  if (!container) return;
  container.innerHTML = '<div style="text-align:center;padding:40px;color:var(--text-dim);font-size:13px;">Loading allocation history...</div>';

  const sb = window.supabaseClient;
  if (!sb) { container.innerHTML = '<div style="padding:20px;color:var(--red);">Supabase not available.</div>'; return; }

  try {
    const { data: rows, error } = await sb.from('allocation_history')
      .select('*')
      .order('recorded_at', { ascending: false });

    if (error) throw error;

    if (!rows || rows.length === 0) {
      container.innerHTML = '<div style="text-align:center;padding:40px;color:var(--text-dim);font-size:13px;">No allocation records found.</div>';
      return;
    }

    // Identify cancelled reservations to filter out their batch allocations
    const allRes = typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : [];
    const cancelledResIds = new Set(
      allRes.filter(r => {
        const st = (r.status || '').toLowerCase();
        const cst = (r.cancellation_status || r.cancellationStatus || '').toLowerCase();
        return st === 'cancelled' || cst === 'cancelled';
      }).map(r => String(r.id))
    );

    // Filter out rows belonging to cancelled reservations and venue-provided equipment batches
    const validRows = rows.filter(r => {
      const resId = String(r.reservation_id || '');
      if (resId && cancelledResIds.has(resId)) return false;
      const bName = String(r.allocation_batch || '').toUpperCase().trim();
      if (bName.startsWith('VENUE-') || bName.startsWith('VENUE_') || bName.includes('VENUE-BATCH') || r.is_venue === true) return false;
      return true;
    });

    if (validRows.length === 0) {
      container.innerHTML = '<div style="text-align:center;padding:40px;color:var(--text-dim);font-size:13px;">No active batch allocations found (cancelled reservations and venue batches excluded).</div>';
      return;
    }

    // Group rows by batch
    const batchMap = {};
    validRows.forEach(row => {
      const bKey = (row.allocation_batch || 'DEFAULT') + '_' + (row.reservation_id || row.reservation_name || 'RES');
      if (!batchMap[bKey]) {
        batchMap[bKey] = {
          batchName: row.allocation_batch || 'Batch Allocation',
          reservationId: row.reservation_id,
          reservationName: row.reservation_name,
          allocationDate: row.allocation_date,
          recordedAt: row.recorded_at,
          items: []
        };
      }
      batchMap[bKey].items.push(row);
    });

    const batches = Object.values(batchMap).filter(b => {
      const bName = String(b.batchName || '').toUpperCase().trim();
      return !bName.startsWith('VENUE-') && !bName.startsWith('VENUE_') && !bName.includes('VENUE-BATCH');
    });

    // Search query filter
    const searchVal = (document.getElementById('eim-alloc-history-search')?.value || '').toLowerCase().trim();
    const filteredBatches = batches.filter(b => {
      if (!searchVal) return true;
      const resObj = allRes.find(r => r.id === b.reservationId);
      const client = (resObj?.client || resObj?.name || b.reservationName || '').toLowerCase();
      const bName = (b.batchName || '').toLowerCase();
      const bDate = (b.allocationDate || '').toLowerCase();
      return client.includes(searchVal) || bName.includes(searchVal) || bDate.includes(searchVal);
    });

    if (filteredBatches.length === 0) {
      container.innerHTML = '<div style="text-align:center;padding:40px;color:var(--text-dim);font-size:13px;">No matching batch allocations found.</div>';
      return;
    }

    let html = '';
    filteredBatches.forEach(batch => {
      const resObj = allRes.find(r => r.id === batch.reservationId);
      const clientName = resObj?.client || resObj?.name || resObj?.client_name || batch.reservationName || 'Unnamed Client';
      const eventDate = batch.allocationDate || resObj?.date || 'N/A';
      const recordedDate = batch.recordedAt ? new Date(batch.recordedAt).toLocaleString('en-US', { dateStyle: 'medium', timeStyle: 'short' }) : 'N/A';
      const totalUnits = batch.items.reduce((sum, it) => sum + (parseInt(it.allocated_qty, 10) || 0), 0);

      html += `
        <div style="border:1px solid var(--border); border-radius:10px; margin-bottom:14px; overflow:hidden; background:var(--bg2, rgba(255,255,255,0.02));">
          <div style="padding:16px 20px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:12px; cursor:pointer;" onclick="toggleAllocHistoryDetail(this)">
            <div>
              <div style="display:flex; align-items:center; gap:8px;">
                <span style="font-weight:700; color:var(--gold); font-size:14px;">${escHtml(batch.batchName)}</span>
                <span style="font-size:11px; color:var(--text-dim); border:1px solid var(--border); padding:2px 8px; border-radius:4px;">${batch.items.length} item(s) · ${totalUnits} units</span>
              </div>
              <div style="font-size:12px; color:var(--cream); margin-top:4px;">${escHtml(clientName)} · Event Date: ${escHtml(eventDate)}</div>
              <div style="font-size:11px; color:var(--text-dim); margin-top:2px;">Recorded: ${escHtml(recordedDate)}</div>
            </div>
            <div style="display:flex; align-items:center; gap:10px;">
              ${batch.reservationId ? `<button type="button" class="btn-outline" style="font-size:11px; padding:5px 12px; cursor:pointer;" onclick="event.stopPropagation(); generateBatchQR('${escHtml(batch.batchName)}', '${batch.reservationId}')">View QR</button>` : ''}
              <span class="alloc-hist-chevron" style="color:var(--text-dim); font-size:16px; transition:transform 0.2s;">&#9662;</span>
            </div>
          </div>
          <div class="alloc-hist-detail" style="display:none; padding:12px 20px 18px; border-top:1px solid var(--border); background:rgba(0,0,0,0.15);">
            <table class="inv-table eim-table" style="width:100%; font-size:12px;">
              <thead>
                <tr>
                  <th style="padding:8px; text-align:left;">Equipment</th>
                  <th style="padding:8px; text-align:center;">Allocated Qty</th>
                  <th style="padding:8px; text-align:center;">Condition Counts</th>
                  <th style="padding:8px; text-align:center;">Unit Type</th>
                  <th style="padding:8px; text-align:center;">Type</th>
                </tr>
              </thead>
              <tbody>
                ${batch.items.map((it, itIdx) => {
                  const condCounts = (typeof window.getBatchItemConditionCounts === 'function') ? window.getBatchItemConditionCounts(it) : { good: it.allocated_qty || 0, broken: 0, missing: 0, retired: 0 };
                  const subItemHtml = (typeof window.renderAllocHistoryItemSubRow === 'function') ? window.renderAllocHistoryItemSubRow(it, itIdx) : '';
                  return `
                  <tr style="cursor:pointer;" onclick="if(typeof window.toggleAllocHistoryItemUnits==='function') window.toggleAllocHistoryItemUnits(this, ${itIdx}, '${it.asset_id}', ${it.allocated_qty || 20})" title="Click to view unique unit IDs and conditions">
                    <td style="padding:8px; color:var(--cream); font-weight:600;"><span style="color:var(--gold); margin-right:4px;">▾</span>${escHtml(it.equipment_name || 'Equipment')}</td>
                    <td style="padding:8px; text-align:center; color:var(--gold); font-weight:700;">${it.allocated_qty}</td>
                    <td style="padding:8px; text-align:center; font-size:11px;">
                      <span style="color:var(--green); font-weight:600;">Good: ${condCounts.good}</span> · 
                      <span style="color:var(--red); font-weight:600;">Broken: ${condCounts.broken}</span> · 
                      <span style="color:var(--orange); font-weight:600;">Missing: ${condCounts.missing}</span> · 
                      <span style="color:var(--text-dim); font-weight:600;">Retired: ${condCounts.retired}</span>
                    </td>
                    <td style="padding:8px; text-align:center; color:var(--text-dim);">${escHtml(it.unit_type || 'piece')}</td>
                    <td style="padding:8px; text-align:center; font-size:11px; color:${it.is_rental ? 'var(--orange)' : 'var(--text-dim)'};">${it.is_rental ? 'Rental' : 'Standard'}</td>
                  </tr>` + subItemHtml;
                }).join('')}
              </tbody>
            </table>
          </div>
        </div>
      `;
    });

    container.innerHTML = html;
  } catch(e) {
    console.error('Failed to render allocation history:', e);
    container.innerHTML = '<div style="padding:20px;color:var(--red);">Error loading allocation history: ' + escHtml(e.message || e) + '</div>';
  }
}
window.renderEIMAllocationHistory = renderEIMAllocationHistory;

function toggleAllocHistoryDetail(hdrEl) {
  const detail = hdrEl.nextElementSibling;
  const chevron = hdrEl.querySelector('.alloc-hist-chevron');
  if (!detail) return;
  const isHidden = detail.style.display === 'none';
  detail.style.display = isHidden ? 'block' : 'none';
  if (chevron) chevron.style.transform = isHidden ? 'rotate(180deg)' : 'rotate(0deg)';
}
window.toggleAllocHistoryDetail = toggleAllocHistoryDetail;

function resolveReporterDisplayName(rawIdentifier, usersList) {
  if (!rawIdentifier) return 'Administrator Admin';
  const rawStr = String(rawIdentifier).trim();
  const lower = rawStr.toLowerCase();
  if (
    lower === 'admin' ||
    lower === 'administrator' ||
    lower.startsWith('admin@') ||
    lower.includes('admin@gmail.com') ||
    lower.includes('local-admin') ||
    lower.includes('local admin') ||
    lower === 'local-admin@demo.com'
  ) {
    return 'Administrator Admin';
  }

  // If already formatted with role in parentheses, e.g. "Kinnit Bolesa (Staff)"
  if (/\([a-z\s]+\)$/i.test(rawStr)) {
    return rawStr;
  }

  const list = usersList || window.allStaff || window.USERS || [];
  const found = list.find(u => {
    if (!u) return false;
    const uEmail = (u.email || '').toLowerCase().trim();
    const uId = String(u.id || '').toLowerCase().trim();
    const uName = (u.name || u.full_name || '').toLowerCase().trim();
    return uEmail === lower || uId === lower || (uName && uName === lower);
  });
  if (found) {
    const fn = found.name || found.full_name || (found.fname ? (found.fname + ' ' + (found.lname || '')).trim() : '');
    if (fn) {
      const fnLower = fn.toLowerCase().trim();
      if (fnLower === 'admin' || fnLower === 'administrator' || fnLower.includes('local admin')) return 'Administrator Admin';
      const roleStr = (found.role && found.role.toLowerCase() !== 'customer') ? ` (${found.role.charAt(0).toUpperCase() + found.role.slice(1).toLowerCase()})` : '';
      return fn.split(' ').filter(Boolean).map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ') + roleStr;
    }
  }

  if (rawStr.includes('@')) {
    const userPart = rawStr.split('@')[0];
    if (userPart.toLowerCase() === 'admin' || userPart.toLowerCase() === 'local-admin') return 'Administrator Admin';
    return userPart.replace(/[._]/g, ' ').split(' ').filter(Boolean).map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ');
  }

  if (lower === 'staff') return 'Staff Member';

  if (!rawStr || rawStr === 'undefined' || rawStr === 'null') return 'Staff Member';

  return rawStr.split(' ').filter(Boolean).map(w => w.charAt(0).toUpperCase() + w.slice(1).toLowerCase()).join(' ');
}
window.resolveReporterDisplayName = resolveReporterDisplayName;

async function renderEIMIncidentLogs() {
  const tbody = document.getElementById('eim-incident-logs-tbody');
  if (!tbody) return;

  const searchInput = document.getElementById('eim-incident-search');
  const query = (searchInput?.value || '').toLowerCase().trim();

  try {
    const sb = window.supabaseClient;
    if (!sb) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;padding:24px;color:var(--text-dim);">Supabase client unavailable.</td></tr>';
      return;
    }

    // Fetch users for name mapping
    let usersData = [];
    try {
      const { data: uRes } = await sb.from('users').select('id, name, email, role');
      if (uRes) usersData = uRes;
    } catch(eUsers) {}

    // 1. Fetch execution batch incidents
    const { data: execLogs } = await sb
      .from('exec_batch_incidents')
      .select('*')
      .order('logged_at', { ascending: false });

    // 2. Fetch routine check incidents (identified during routine checks - preserve all incident records)
    const { data: rcRows } = await sb
      .from('routine_check')
      .select('*')
      .or('status.eq.incident,incidents.not.is.null')
      .order('checked_at', { ascending: false });

    // 3. Fetch standalone incident reports
    let standaloneRows = [];
    try {
      const { data: saData } = await sb
        .from('standalone_incident_reports')
        .select('*')
        .eq('is_reverted', false)
        .order('created_at', { ascending: false });
      if (saData) standaloneRows = saData;
    } catch (eSa) {
      console.warn('[renderEIMIncidentLogs] Standalone incidents fetch:', eSa);
    }

    // 4. Fetch equipment retired from the maintenance pipeline
    let mntRetiredRows = [];
    try {
      const { data: mntData } = await sb
        .from('equipment_maintenance')
        .select('*')
        .in('status', ['retired', 'disposed', 'Retired', 'Disposed'])
        .order('created_at', { ascending: false });
      if (mntData) mntRetiredRows = mntData;
    } catch (eMnt) {
      console.warn('[renderEIMIncidentLogs] Maintenance retired fetch:', eMnt);
    }

    const allIncidents = [];

    // Format execution day incidents
    (execLogs || []).forEach(l => {
      const res = (RESERVATIONS || []).find(r => r.id === l.reservation_id);
      const resName = res ? (res.packageName || res.client || res.name || res.id) : (l.reservation_id || 'Unknown Event');
      const dt = l.logged_at ? new Date(l.logged_at) : new Date();
      const timeStr = dt.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
      const incType = l.incident_type || 'Incident';
      const reporterName = resolveReporterDisplayName(l.logged_by || l.created_by || l.reported_by || 'Admin', usersData);

      let execItemCode = l.item_code || null;
      if (!execItemCode && l.equipment_name) {
        const hashM = l.equipment_name.match(/#(\d+)/);
        if (hashM) {
          const num = String(hashM[1]).padStart(3, '0');
          execItemCode = `${l.equipment_id || 'EQ-0001'}-${num}`;
        }
      }
      allIncidents.push({
        id: l.id,
        raw_id: l.id,
        source: 'execution',
        timestamp: dt.getTime(),
        dateStr: dt.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }),
        timeStr: timeStr,
        equipment_name: l.equipment_name || 'Equipment',
        equipment_id: l.equipment_id || '',
        item_code: execItemCode,
        incident_type: incType,
        quantity: l.quantity || 1,
        source_title: resName,
        source_sub: l.reservation_id || '',
        reporterName: reporterName,
        phase: l.phase || 'Execution',
        phase_badge_style: 'background:rgba(196,154,60,0.15);color:var(--gold);border:1px solid rgba(196,154,60,0.3);',
        summaryText: `${l.quantity || 1} ${incType.toLowerCase()} from "${resName}" execution day at ${timeStr} in ${l.phase || 'Execution'} (Reported by: ${reporterName})`,
        photo_url: l.photo_url || null,
        is_inspection: false
      });
    });

    // Format routine checking incidents
    (rcRows || []).forEach(rc => {
      if (rc.asset_id === 'SESSION-ACTIVE' || rc.notes === 'SESSION-ACTIVE' || rc.asset_id === 'MASTER-LOG') return;

      const dt = rc.checked_at ? new Date(rc.checked_at) : (rc.created_at ? new Date(rc.created_at) : new Date());
      const timeStr = dt.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
      const reporterName = resolveReporterDisplayName(rc.checked_by || 'Admin', usersData);

      let incList = [];
      if (Array.isArray(rc.incidents) && rc.incidents.length > 0) {
        incList = rc.incidents;
      } else if (typeof rc.incidents === 'string') {
        try { incList = JSON.parse(rc.incidents); } catch(e) {}
      }

      let rcParsedNotes = null;
      let rcIncidentUnits = [];
      if (rc.notes) {
        try {
          rcParsedNotes = JSON.parse(rc.notes);
          if (rcParsedNotes.brokenUnits && rcParsedNotes.brokenUnits.length) {
            rcIncidentUnits.push(...rcParsedNotes.brokenUnits.map(u => `${u} (broken)`));
          }
          if (rcParsedNotes.missingUnits && rcParsedNotes.missingUnits.length) {
            rcIncidentUnits.push(...rcParsedNotes.missingUnits.map(u => `${u} (missing)`));
          }
          if (rcParsedNotes.retiredUnits && rcParsedNotes.retiredUnits.length) {
            rcIncidentUnits.push(...rcParsedNotes.retiredUnits.map(u => `${u} (retired)`));
          }
        } catch(e) {}
      }

      if (incList && Array.isArray(incList) && incList.length > 0) {
        incList.forEach(itemInc => {
          const incType = itemInc.type || 'Incident';
          const qty = itemInc.qty || 1;
          const photo = itemInc.imageUrl || rc.incident_image_url || null;

          let targetCode = itemInc.item_code || rc.item_code;
          if (!targetCode && rcParsedNotes) {
            const incTLower = (itemInc.type || '').toLowerCase();
            if ((incTLower === 'broken' || incTLower === 'damaged') && rcParsedNotes.brokenUnits?.length) {
              targetCode = rcParsedNotes.brokenUnits.join(', ');
            } else if (incTLower === 'missing' && rcParsedNotes.missingUnits?.length) {
              targetCode = rcParsedNotes.missingUnits.join(', ');
            } else if ((incTLower === 'retired' || incTLower === 'trash') && rcParsedNotes.retiredUnits?.length) {
              targetCode = rcParsedNotes.retiredUnits.join(', ');
            }
          }
          if (!targetCode && rc.notes) {
            const m = rc.notes.match(/\b(EQ-[A-Za-z0-9]+-\d+)\b/i);
            if (m) targetCode = m[1];
          }

          let summaryClean = `${qty} ${incType.toLowerCase()} identified during Routine Check (Reported by: ${reporterName})`;
          if (targetCode) {
            summaryClean = `${qty} ${incType.toLowerCase()} (${targetCode}) identified during Routine Check (Reported by: ${reporterName})`;
          } else if (rcIncidentUnits.length > 0) {
            summaryClean += ` - [Incident Units: ${rcIncidentUnits.join(', ')}]`;
          } else if (rc.notes && !rc.notes.includes('"goodUnits"') && !rc.notes.includes('goodUnits')) {
            summaryClean += ` - ${rc.notes}`;
          }

          allIncidents.push({
            id: rc.id + '-' + (itemInc.type || 'inc'),
            raw_id: rc.id,
            sub_type: itemInc.type || incType,
            source: 'routine',
            timestamp: dt.getTime(),
            dateStr: dt.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }),
            timeStr: timeStr,
            equipment_name: rc.equipment_name || 'Equipment',
            equipment_id: rc.equipment_id || rc.asset_id || '',
            item_code: targetCode || null,
            incident_type: incType,
            quantity: qty,
            source_title: 'Routine Check',
            source_sub: 'Warehouse Inspection',
            reporterName: reporterName,
            phase: 'Inspection',
            phase_badge_style: 'background:rgba(59,130,246,0.15);color:#60a5fa;border:1px solid rgba(59,130,246,0.3);',
            summaryText: summaryClean,
            photo_url: photo,
            is_inspection: true
          });
        });
      } else {
        const qty = (rc.quantity != null && rc.good_qty != null) ? Math.max(1, rc.quantity - rc.good_qty) : (rc.quantity || 1);
        let targetCode = rc.item_code;
        if (!targetCode && rcParsedNotes) {
          if (rcParsedNotes.brokenUnits?.length) targetCode = rcParsedNotes.brokenUnits.join(', ');
          else if (rcParsedNotes.missingUnits?.length) targetCode = rcParsedNotes.missingUnits.join(', ');
          else if (rcParsedNotes.retiredUnits?.length) targetCode = rcParsedNotes.retiredUnits.join(', ');
        }
        let summaryClean = `${qty} incident identified during Routine Check (Reported by: ${reporterName})`;
        if (targetCode) {
          summaryClean = `${qty} incident (${targetCode}) identified during Routine Check (Reported by: ${reporterName})`;
        } else if (rcIncidentUnits.length > 0) {
          summaryClean += ` - [Incident Units: ${rcIncidentUnits.join(', ')}]`;
        } else if (rc.notes && !rc.notes.includes('"goodUnits"') && !rc.notes.includes('goodUnits')) {
          summaryClean += ` - ${rc.notes}`;
        }

        allIncidents.push({
          id: rc.id,
          raw_id: rc.id,
          sub_type: 'Incident',
          source: 'routine',
          timestamp: dt.getTime(),
          dateStr: dt.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }),
          timeStr: timeStr,
          equipment_name: rc.equipment_name || 'Equipment',
          equipment_id: rc.equipment_id || rc.asset_id || '',
          item_code: targetCode || null,
          incident_type: 'Incident',
          quantity: qty,
          source_title: 'Routine Check',
          source_sub: 'Warehouse Inspection',
          reporterName: reporterName,
          phase: 'Inspection',
          phase_badge_style: 'background:rgba(59,130,246,0.15);color:#60a5fa;border:1px solid rgba(59,130,246,0.3);',
          summaryText: summaryClean,
          photo_url: rc.incident_image_url || null,
          is_inspection: true
        });
      }
    });

    // Format standalone incident reports
    (standaloneRows || []).forEach(sa => {
      const dt = sa.created_at ? new Date(sa.created_at) : (sa.reported_at ? new Date(sa.reported_at) : new Date());
      const timeStr = dt.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
      const incType = sa.incident_type || 'Incident';
      const reporterName = resolveReporterDisplayName(sa.reported_by || 'Admin', usersData);

      allIncidents.push({
        id: 'standalone-' + sa.id,
        raw_id: sa.id,
        source: 'standalone',
        timestamp: dt.getTime(),
        dateStr: dt.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }),
        timeStr: timeStr,
        equipment_name: sa.equipment_name || 'Equipment',
        equipment_id: sa.asset_id || sa.equipment_id || '',
        item_code: sa.item_code || (sa.notes && (sa.notes.match(/\b(EQ-[A-Za-z0-9]+-\d+)\b/i) || [])[1]) || null,
        incident_type: incType,
        quantity: sa.quantity || 1,
        source_title: 'Direct Report',
        source_sub: 'Warehouse Direct Report',
        reporterName: reporterName,
        phase: sa.phase || 'Inspection',
        phase_badge_style: 'background:rgba(168,85,247,0.15);color:#c084fc;border:1px solid rgba(168,85,247,0.3);',
        summaryText: `${sa.quantity || 1} ${incType.toLowerCase()} reported (Reported by: ${reporterName})` + (sa.notes ? ` - ${sa.notes}` : ''),
        photo_url: sa.photo_url || null,
        is_inspection: true,
        notes: sa.notes || '',
        reporter: reporterName
      });
    });

    // Format equipment retired from the maintenance pipeline
    (mntRetiredRows || []).forEach(m => {
      const dt = m.date_out ? new Date(m.date_out) : (m.created_at ? new Date(m.created_at) : new Date());
      const timeStr = dt.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', hour12: true });
      const reporterName = resolveReporterDisplayName(m.created_by || 'Admin', usersData);
      let targetCode = m.item_code || null;
      if (!targetCode && m.repair_notes) {
        const match = m.repair_notes.match(/\b(EQ-[A-Za-z0-9]+-\d+)\b/i);
        if (match) targetCode = match[1];
      }

      // Check if already represented to avoid duplication
      const isAlreadyLogged = allIncidents.some(it => it.item_code === targetCode && it.incident_type === 'Retired');
      if (!isAlreadyLogged) {
        allIncidents.push({
          id: 'mnt-retired-' + m.id,
          raw_id: m.id,
          source: 'maintenance_retired',
          timestamp: dt.getTime(),
          dateStr: dt.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }),
          timeStr: timeStr,
          equipment_name: m.equipment_name || 'Equipment',
          equipment_id: m.asset_id || m.equipment_id || '',
          item_code: targetCode,
          incident_type: 'Retired',
          quantity: m.quantity || 1,
          source_title: 'Maintenance Pipeline',
          source_sub: 'Retired Equipment',
          reporterName: reporterName,
          phase: 'Maintenance',
          phase_badge_style: 'background:rgba(107,114,128,0.2);color:#9ca3af;border:1px solid rgba(107,114,128,0.4);',
          summaryText: `${m.quantity || 1} retired via maintenance pipeline (Reported by: ${reporterName})` + (m.repair_notes ? ` - ${m.repair_notes}` : ''),
          photo_url: null,
          is_inspection: false,
          notes: m.repair_notes || '',
          reporter: reporterName
        });
      }
    });

    window._cachedEIMIncidents = allIncidents;
    allIncidents.sort((a, b) => b.timestamp - a.timestamp);

    if (!allIncidents.length) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;padding:24px;color:var(--text-dim);">No equipment incidents reported yet.</td></tr>';
      return;
    }

    const filtered = allIncidents.filter(l => {
      if (!query) return true;
      const text = `${l.equipment_name} ${l.equipment_id} ${l.incident_type} ${l.phase} ${l.source_title} ${l.source_sub} ${l.reporterName} ${l.summaryText}`.toLowerCase();
      return text.includes(query);
    });

    if (!filtered.length) {
      tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;padding:24px;color:var(--text-dim);">No incident logs match your search.</td></tr>';
      return;
    }

    tbody.innerHTML = filtered.map(item => {
      const incType = item.incident_type || 'Incident';
      const incTypeLower = incType.toLowerCase();
      const incTypeColor = (incTypeLower === 'broken' || incTypeLower === 'damage' || incTypeLower === 'damaged')
        ? '#ef4444'
        : (incTypeLower === 'missing'
          ? '#f59e0b'
          : '#9ca3af');
      const phaseColor = (item.phase === 'Execution')
        ? 'var(--gold, #c49a3c)'
        : ((item.phase === 'Inspection') ? '#60a5fa' : '#c084fc');

      const photoHtml = item.photo_url
        ? `<img src="${escHtml(item.photo_url)}" alt="Incident Photo" onclick="openExecIncidentPhoto('${escHtml(item.photo_url)}')" style="width:36px;height:36px;object-fit:cover;border-radius:6px;border:1px solid var(--border);cursor:pointer;transition:transform 0.15s;" title="Click to view photo" />`
        : '<span style="color:var(--text-dim);font-size:11px;">None</span>';

      const actionHtml = item.is_inspection
        ? `<button class="btn-outline" style="font-size:11px;padding:3px 10px;border-radius:6px;cursor:pointer;" onclick="openIncidentReviewModal('${escHtml(item.id)}')">Review</button>`
        : '<span style="color:var(--text-dim);font-size:11px;">—</span>';

      let itemCode = item.item_code;
      if (!itemCode && item.equipment_name) {
        const hashMatch = item.equipment_name.match(/#(\d+)/);
        if (hashMatch) {
          const num = String(hashMatch[1]).padStart(3, '0');
          const baseId = item.equipment_id || 'EQ-0001';
          itemCode = `${baseId}-${num}`;
        }
      }
      if (!itemCode && item.summaryText) {
        const codeMatch = item.summaryText.match(/\b(EQ-[A-Za-z0-9]+-\d+)\b/i);
        if (codeMatch) itemCode = codeMatch[1];
      }
      if (!itemCode && item.notes) {
        const codeMatch = item.notes.match(/\b(EQ-[A-Za-z0-9]+-\d+)\b/i);
        if (codeMatch) itemCode = codeMatch[1];
      }
      if (!itemCode) {
        itemCode = item.equipment_id || '—';
      }
      const subRowId = `inc-log-subrow-${item.id}`;
      const subRowHtml = `<tr id="${subRowId}" class="inc-log-subrow" style="display:none; background:rgba(0,0,0,0.35);">
        <td colspan="8" style="padding:10px 18px; width:100%; box-sizing:border-box;">
          <div style="display:flex; justify-content:space-between; align-items:center;">
            <div>
              <span style="font-size:11px; font-weight:700; color:var(--gold); text-transform:uppercase;">Unique Equipment ID:</span>
              <span style="font-family:monospace; font-weight:700; color:var(--cream); margin-left:8px; font-size:12px;">${escHtml(itemCode)}</span>
              <span style="margin-left:14px; font-size:11px; color:var(--text-dim);">Status: ${escHtml(item.incident_type)} · Phase: ${escHtml(item.phase)}</span>
            </div>
            <div>
              <a href="scan.html?eq=${encodeURIComponent(itemCode)}" target="_blank" class="btn-outline" style="font-size:10px; padding:3px 10px; text-decoration:none;">Open Scan / QR</a>
            </div>
          </div>
        </td>
      </tr>`;

      return `<tr style="cursor:pointer;" onclick="window.toggleIncidentLogDetail('${subRowId}')" title="Click to view unique equipment ID">
        <td style="font-size:12px;color:var(--text-dim);white-space:nowrap;">
          <div style="font-weight:600;color:var(--cream);">${item.dateStr}</div>
          <div style="font-size:11px;">${item.timeStr}</div>
        </td>
        <td>
          <div style="font-weight:600;color:var(--cream);font-size:13px;">${escHtml(item.equipment_name)} ▾</div>
          <div style="font-size:11px;color:var(--gold);font-family:monospace;">${escHtml(itemCode)}</div>
        </td>
        <td>
          <span style="color:${incTypeColor};font-size:12px;font-weight:700;">
            ${item.quantity} ${escHtml(incType)}
          </span>
        </td>
        <td>
          <div style="font-size:13px;color:var(--cream);font-weight:500;">${escHtml(item.source_title)}</div>
          <div style="font-size:11px;color:var(--gold);font-weight:600;margin-top:2px;">Reported by: ${escHtml(item.reporterName || 'Staff Member')}</div>
        </td>
        <td>
          <span style="color:${phaseColor};font-size:12px;font-weight:600;">
            ${escHtml(item.phase)}
          </span>
        </td>
        <td style="font-size:12px;color:var(--text);max-width:320px;">
          ${escHtml(item.summaryText)}
        </td>
        <td style="text-align:center;" onclick="event.stopPropagation();">
          ${photoHtml}
        </td>
        <td style="text-align:center;" onclick="event.stopPropagation();">
          ${actionHtml}
        </td>
      </tr>` + subRowHtml;
    }).join('');
  } catch(e) {
    console.error('[renderEIMIncidentLogs]', e);
    tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;padding:24px;color:#ef4444;">Failed to load incident logs.</td></tr>';
  }
}
window.renderEIMIncidentLogs = renderEIMIncidentLogs;

// ===== INCIDENT REVIEW & UNDO ACTION =====
window.openIncidentReviewModal = function(id) {
  const modal = document.getElementById('modal-incident-review');
  const body = document.getElementById('incident-review-body');
  if (!modal || !body) return;

  const item = (window._cachedEIMIncidents || []).find(x => String(x.id) === String(id) || String(x.raw_id) === String(id));
  if (!item) {
    alert('Incident record not found.');
    return;
  }

  const photoBlock = item.photo_url
    ? `<div style="margin-bottom:18px;text-align:center;">
         <img src="${escHtml(item.photo_url)}" alt="Incident Photo" class="incident-review-photo-img" />
       </div>`
    : `<div class="incident-review-no-photo">No photo attached to this report</div>`;

  body.innerHTML = `
    ${photoBlock}
    <div class="incident-review-grid">
      <div>
        <div class="incident-review-cell-label">Equipment</div>
        <div class="incident-review-cell-val">${escHtml(item.equipment_name)}</div>
        <div class="incident-review-cell-sub">${escHtml(item.equipment_id || 'No ID')}</div>
      </div>
      <div>
        <div class="incident-review-cell-label">Reported Incident</div>
        <div class="incident-review-cell-val">${item.quantity} &times; ${escHtml(item.incident_type)}</div>
        <div class="incident-review-cell-sub">${item.dateStr} at ${item.timeStr}</div>
      </div>
      <div>
        <div class="incident-review-cell-label">Inspection Source</div>
        <div class="incident-review-cell-val" style="font-size:12px;">${escHtml(item.source_title)}</div>
        <div class="incident-review-cell-sub">${escHtml(item.source_sub)}</div>
      </div>
      <div>
        <div class="incident-review-cell-label">Inspection Phase</div>
        <div class="incident-review-phase-badge">${escHtml(item.phase)}</div>
      </div>
    </div>
    <div class="incident-review-notes">
      <div class="incident-review-cell-label" style="margin-bottom:4px;">Summary &amp; Notes</div>
      <div>${escHtml(item.summaryText)}</div>
    </div>
    <div>
      <button class="btn-danger" id="btn-undo-incident" style="width:100%;padding:12px 20px;font-size:13px;font-weight:700;border-radius:8px;cursor:pointer;" onclick="undoIncidentReport('${escHtml(item.id)}')">
        Undo Report
      </button>
      <div class="incident-review-revert-hint">
        Reverting this report will restore inventory quantities and update incident metrics automatically.
      </div>
    </div>
  `;

  modal.style.display = 'flex';
  modal.style.zIndex = '999999';
};

window.closeIncidentReviewModal = function() {
  const modal = document.getElementById('modal-incident-review');
  if (modal) modal.style.display = 'none';
};

window.undoIncidentReport = async function(id) {
  const item = (window._cachedEIMIncidents || []).find(x => x.id === id);
  if (!item) return;

  const btn = document.getElementById('btn-undo-incident');
  if (btn) {
    btn.disabled = true;
    btn.textContent = 'Reverting report...';
  }

  try {
    const sb = window.supabaseClient || window.supabase;
    if (!sb) throw new Error('Database client unavailable');

    const qtyToRestore = item.quantity || 1;
    const incTypeLower = (item.incident_type || '').toLowerCase();
    const eqId = item.equipment_id;

    // 1. Revert inventory quantities in equipment_inventory
    if (eqId) {
      const { data: eqRow } = await sb
        .from('equipment_inventory')
        .select('*')
        .or(`asset_id.eq.${eqId},id.eq.${eqId}`)
        .maybeSingle();

      if (eqRow) {
        const curGood = eqRow.good_qty != null ? eqRow.good_qty : (eqRow.available_qty || 0);
        const updatedGood = curGood + qtyToRestore;
        let updatedMaint = eqRow.maintenance_qty || 0;
        let updatedMiss = eqRow.missing_qty || 0;
        let updatedRet = eqRow.retired_qty || 0;

        if (incTypeLower.includes('broken') || incTypeLower.includes('maint') || incTypeLower.includes('damage')) {
          updatedMaint = Math.max(0, updatedMaint - qtyToRestore);
        } else if (incTypeLower.includes('miss')) {
          updatedMiss = Math.max(0, updatedMiss - qtyToRestore);
        } else if (incTypeLower.includes('ret') || incTypeLower.includes('trash') || incTypeLower.includes('dispose')) {
          updatedRet = Math.max(0, updatedRet - qtyToRestore);
        }

        await sb.from('equipment_inventory').update({
          good_qty: updatedGood,
          maintenance_qty: updatedMaint,
          missing_qty: updatedMiss,
          retired_qty: updatedRet
        }).eq('id', eqRow.id);

        // Update in-memory EQUIPMENT_INVENTORY cache if available
        if (Array.isArray(window.EQUIPMENT_INVENTORY)) {
          const inMem = window.EQUIPMENT_INVENTORY.find(x => x.id === eqRow.id || x.asset_id === eqRow.asset_id);
          if (inMem) {
            inMem.good_qty = updatedGood;
            inMem.maintenance_qty = updatedMaint;
            inMem.missing_qty = updatedMiss;
            inMem.retired_qty = updatedRet;
          }
        }
      }
    }

    // 2. Revert the report record
    if (item.source === 'standalone') {
      await sb.from('standalone_incident_reports').update({ is_reverted: true }).eq('id', item.raw_id);
    } else if (item.source === 'routine') {
      const { data: rcRow } = await sb.from('routine_check').select('*').eq('id', item.raw_id).maybeSingle();
      if (rcRow) {
        let incs = [];
        if (Array.isArray(rcRow.incidents)) incs = rcRow.incidents;
        else if (typeof rcRow.incidents === 'string') {
          try { incs = JSON.parse(rcRow.incidents); } catch(e) {}
        }

        // Filter out the reverted incident
        const remIncs = incs.filter(i => (i.type || '').toLowerCase() !== (item.sub_type || incTypeLower));
        const updatedStatus = remIncs.length > 0 ? 'incident' : 'good';
        await sb.from('routine_check').update({
          incidents: remIncs.length > 0 ? JSON.stringify(remIncs) : null,
          status: updatedStatus
        }).eq('id', item.raw_id);
      }
    } else if (item.source === 'execution') {
      try {
        await sb.from('exec_batch_incidents').delete().eq('id', item.raw_id);
      } catch(eExec) {
        console.warn('[undoIncidentReport] Error deleting execution incident:', eExec);
      }
    }

    closeIncidentReviewModal();
    if (typeof showAdminToast === 'function') {
      showAdminToast('Incident report reverted and inventory quantities restored.');
    } else {
      alert('Incident report reverted and inventory quantities restored.');
    }

    // Refresh logs and inventory
    if (typeof renderEIMIncidentLogs === 'function') renderEIMIncidentLogs();
    if (typeof renderEquipmentInventory === 'function') renderEquipmentInventory();
    if (typeof renderEIMAnalytics === 'function') renderEIMAnalytics();
  } catch(err) {
    console.error('[undoIncidentReport]', err);
    alert('Failed to undo report: ' + (err.message || err));
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.textContent = 'Undo Report';
    }
  }
};

