window.switchAllocTab = switchAllocTab;

function toggleAllocDetail(hdr) {
  const det = hdr.parentElement.querySelector('.alloc-detail');
  if (det) det.style.display = det.style.display === 'none' ? 'block' : 'none';
}
window.toggleAllocDetail = toggleAllocDetail;

async function loadViewAllocations() {
  const container = document.getElementById('eim-alloc-list-inner');
  if (!container) return;
  container.innerHTML = '<div style="text-align:center;padding:40px;color:var(--text-dim);font-size:13px;">Loading allocations...</div>';
  const sb = window.supabaseClient;
  if (!sb) { container.innerHTML = '<div style="padding:20px;color:var(--red);">Supabase not available.</div>'; return; }

  // Read from allocation_history : each reservation's batch is stored as separate INSERT rows,
  // so multiple reservations on the same date/client each have their own independent records.
  const { data, error } = await sb
    .from('allocation_history')
    .select('allocation_batch,reservation_id,reservation_name,asset_id,equipment_name,allocated_qty,recorded_at,is_rental')
    .not('allocation_batch', 'is', null)
    .order('recorded_at', { ascending: false });

  if (error || !data || !data.length) {
    container.innerHTML = '<div style="text-align:center;padding:40px;color:var(--text-dim);font-size:13px;">No allocations found. Allocate equipment in Equipment Cycle first.</div>';
    return;
  }

  let allocs = data;
  const dedupMap = {};
  allocs.forEach(h => {
    if (!h.reservation_id) return;
    const isVenue = h.allocation_batch && h.allocation_batch.startsWith('VENUE-');
    const key = `${h.reservation_id}_${h.equipment_name || h.asset_id}_${h.is_rental}_${!!isVenue}`;
    const time = h.recorded_at ? new Date(h.recorded_at).getTime() : 0;
    if (!dedupMap[key] || time > dedupMap[key].time) {
      dedupMap[key] = { row: h, time };
    }
  });
  allocs = Object.values(dedupMap).map(d => d.row);

  // Group by reservation_id (unique per reservation even if batch names collide)
  const batches = {};
  allocs.forEach(row => {
    const bKey = row.reservation_id || row.allocation_batch;
    if (!batches[bKey]) {
      batches[bKey] = { batchName: row.allocation_batch, reservationId: row.reservation_id, allocatedTo: row.reservation_name, items: [] };
    }
    batches[bKey].items.push({ name: row.equipment_name, category: '', assetId: row.asset_id, qty: row.allocated_qty, is_rental: row.is_rental, is_venue: row.allocation_batch && row.allocation_batch.startsWith('VENUE-') });
  });

  const batchList = Object.values(batches).sort((a, b) => a.batchName.localeCompare(b.batchName));

  // Filter out batches that belong to cancelled reservations, and wipe them from equipment_inventory
  const validBatchList = [];
  batchList.forEach(batch => {
    const res = RESERVATIONS ? RESERVATIONS.find(r => r.id === batch.reservationId || (r.client || r.name || '').toLowerCase() === (batch.allocatedTo || '').toLowerCase()) : null;
    if (res && res.status === 'cancelled') {
      if (sb && batch.reservationId) {
        sb.from('equipment_inventory')
          .update({ allocated_qty: 0, allocation_batch: null, allocated_to: null, allocated_reservation_id: null, allocation_date: null })
          .eq('allocated_reservation_id', batch.reservationId)
          .then(() => console.log('Cleaned up orphaned batch for cancelled reservation:', batch.reservationId))
          .catch(e => console.warn('Failed to clean up orphaned batch:', e));
      }
      return; // Skip rendering
    }
    validBatchList.push(batch);
  });

  container.innerHTML = validBatchList.map(batch => {
    const res = RESERVATIONS ? RESERVATIONS.find(r => r.id === batch.reservationId || (r.client || r.name || '').toLowerCase() === (batch.allocatedTo || '').toLowerCase()) : null;
    const resName = res ? (res.packageName || res.type || 'Event') : (batch.allocatedTo || 'Unknown');
    const customer = res ? (res.client || res.customerName || batch.allocatedTo || ':') : (batch.allocatedTo || ':');
    const timeRange = res ? ((res.eventTimeStart || res.startTime || '') + (res.eventTimeEnd || res.endTime ? ' : ' + (res.eventTimeEnd || res.endTime) : '')) : ':';
    const formatResDate = (dStr) => {
      if (!dStr) return null;
      const d = new Date(dStr);
      if (!isNaN(d.getTime())) return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
      return dStr;
    };
    const dateStr = res ? formatResDate(res.date || res.eventDate || null) : '';
    const venue = res ? (res.venue || res.venueAddress || res.location || '') : '';
    const mapUrl = venue ? 'https://maps.google.com/maps?q=' + encodeURIComponent(venue) + '&output=embed' : '';
    let isModified = false;
    if (res && typeof _genBatchName === 'function' && typeof _getBatchModificationString === 'function') {
      const expectedBatch = _genBatchName(res);
      if (batch.batchName !== expectedBatch) {
        const changeStr = _getBatchModificationString(batch.batchName, expectedBatch);
        if (changeStr && changeStr !== 'No significant changes detected.') {
          isModified = true;
        }
      }
    }

    const itemRows = batch.items.map((i, iIdx) => {
      let badgeHtml = '';
      if (i.is_venue) {
        badgeHtml = ' <span class="badge confirmed" style="font-size:9px;margin-left:4px;color:var(--green);">Venue Provided</span>';
      } else if (i.is_rental) {
        badgeHtml = ' <span class="badge confirmed" style="font-size:9px;margin-left:4px;color:var(--gold);">Rental</span>';
      }
      const cleanBatchId = (batch.batchName || 'batch').replace(/[^a-zA-Z0-9]/g, '_');
      const cleanAssetId = (i.assetId || ('item_' + iIdx)).replace(/[^a-zA-Z0-9]/g, '_');
      const subRowId = 'alloc-subrow-' + cleanBatchId + '-' + cleanAssetId + '-' + iIdx;
      return '<tr style="cursor:pointer;" onclick="window.toggleBatchAllocItemUnits(\'' + subRowId + '\', \'' + (i.assetId || '') + '\', \'' + (batch.batchName || '') + '\', ' + (i.qty || 1) + ')" title="Click to view allocated unique equipment IDs">' +
        '<td style="font-size:12px;padding:6px 10px;"><span style="color:var(--gold);font-weight:700;font-family:monospace;">' + (i.assetId || '') + ' ▾</span></td>' +
        '<td style="font-size:12px;padding:6px 10px;color:var(--cream);font-weight:600;">' + (i.name || '') + badgeHtml + '</td>' +
        '<td style="font-size:11px;padding:6px 10px;"><span style="color:var(--text);">' + (i.category || '') + '</span></td>' +
        '<td style="font-size:13px;font-weight:700;padding:6px 10px;color:var(--gold);">' + (i.qty || 0) + '</td>' +
        '</tr>' +
        '<tr id="' + subRowId + '" class="batch-alloc-item-subrow" style="display:none; background:rgba(0,0,0,0.35);">' +
        '<td colspan="4" style="padding:10px 16px;">' +
        '<div style="font-size:11px; color:var(--text-dim);">Loading allocated unique IDs...</div>' +
        '</td></tr>';
    }).join('');
    return '<div class="panel" style="margin-bottom:14px;border:1px solid var(--border);border-radius:12px;overflow:hidden;">' +
      '<div style="display:flex;align-items:center;justify-content:space-between;padding:14px 18px;cursor:pointer;gap:12px;" onclick="toggleAllocDetail(this)">' +
      '<div>' +
      '<div style="display:flex;align-items:center;gap:10px;margin-bottom:4px;">' +
      '<span style="font-size:12px;font-weight:700;color:var(--gold);text-transform:uppercase;">' + batch.batchName + '</span>' +
      (dateStr ? '<span style="font-size:11px;color:var(--text-dim);">' + dateStr + '</span>' : '') +
      '</div>' +
      '<div style="font-size:13px;font-weight:600;color:var(--cream);">' + customer + ' : ' + resName + '</div>' +
      (timeRange && timeRange !== ':' ? '<div style="font-size:11px;color:var(--text-dim);margin-top:2px;">' + timeRange + '</div>' : '') +
      (isModified ? '<div style="font-size:11px;color:var(--gold);margin-top:4px;font-weight:600;">\u26a0\ufe0f Package significantly modified, allocation needs an update</div>' : '') +
      '</div>' +
      '<div style="display:flex;gap:8px;flex-shrink:0;">' +
      '<button class="btn-primary" style="font-size:11px;padding:5px 10px;" onclick="event.stopPropagation();generateBatchQR(&quot;' + batch.batchName + '&quot;, &quot;' + batch.reservationId + '&quot;)">View QR</button>' +
      '<button class="btn-outline" style="font-size:11px;padding:5px 10px;" onclick="event.stopPropagation();jumpToEqcForBatch(&quot;' + (batch.reservationId || batch.allocatedTo) + '&quot;)">Modify</button>' +
      '<span style="font-size:11px;color:var(--text-dim);align-self:center;">' + batch.items.length + ' items</span>' +
      '</div>' +
      '</div>' +
      '<div class="alloc-detail" style="display:none;border-top:1px solid var(--border);">' +
      (mapUrl ? '<iframe src="' + mapUrl + '" width="100%" height="200" style="border:none;display:block;"></iframe>' : (venue ? '<div style="padding:10px 18px;font-size:12px;color:var(--text-dim);">Venue: ' + venue + '</div>' : '')) +
      '<div style="padding:10px 18px;">' +
      '<table style="width:100%;border-collapse:collapse;">' +
      '<thead><tr style="border-bottom:1px solid var(--border);"><th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Asset ID</th><th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Equipment</th><th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Category</th><th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Qty</th></tr></thead>' +
      '<tbody>' + itemRows + '</tbody>' +
      '</table>' +
      '</div>' +
      '</div>' +
      '</div>';
  }).join('');
}

// ====== VENUE LAYOUT TABLE COUNTS HELPER ======
/**
 * Retrieves the count of round tables and rectangular tables placed in the venue layout
 * for a given reservation ID.
 * @param {string} resId
 * @returns {{ roundCount: number, rectCount: number, totalCount: number, hasLayout: boolean }}
 */
function getVenueLayoutTableCounts(resId) {
  if (!resId) return { roundCount: 0, rectCount: 0, totalCount: 0, hasLayout: false };
  let elements = [];
  const extra = typeof reservationExtraDetails !== 'undefined' ? reservationExtraDetails[resId] : null;
  if (extra && Array.isArray(extra.seatingElements) && extra.seatingElements.length > 0) {
    elements = extra.seatingElements;
  } else if (typeof activeResDetailId !== 'undefined' && resId === activeResDetailId && typeof seatingElements !== 'undefined' && Array.isArray(seatingElements) && seatingElements.length > 0) {
    elements = seatingElements;
  } else {
    const res = (typeof RESERVATIONS !== 'undefined' && Array.isArray(RESERVATIONS)) ? RESERVATIONS.find(r => r.id === resId) : null;
    if (res && Array.isArray(res.seating_elements) && res.seating_elements.length > 0) {
      elements = res.seating_elements;
    } else if (res && Array.isArray(res.seatingLayout) && res.seatingLayout.length > 0) {
      elements = res.seatingLayout;
    }
  }

  // Fallback to localStorage
  if (!elements || elements.length === 0) {
    try {
      const lsKey = 'smartserve_seating_layout_' + resId;
      const raw = localStorage.getItem(lsKey) || localStorage.getItem('smartserve_seating_' + resId) || localStorage.getItem('seating_layout_' + resId);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) elements = parsed;
        else if (parsed && Array.isArray(parsed.elements)) elements = parsed.elements;
        else if (parsed && Array.isArray(parsed.seatingElements)) elements = parsed.seatingElements;
      }
    } catch (_e) {}
  }

  let roundCount = elements.filter(e => e && e.type && (e.type === 'table-round' || (typeof e.type === 'string' && e.type.includes('round')))).length;
  let rectCount = elements.filter(e => e && e.type && (e.type === 'table-rect' || (typeof e.type === 'string' && e.type.includes('rect')))).length;

  // Fallback to directly cached table counts if elements array was not retrieved
  if (roundCount === 0 && rectCount === 0) {
    const res = (typeof RESERVATIONS !== 'undefined' && Array.isArray(RESERVATIONS)) ? RESERVATIONS.find(r => r.id === resId) : null;
    const rRound = (extra && extra.roundTablesCount != null) ? extra.roundTablesCount : (res && res.roundTablesCount != null ? res.roundTablesCount : 0);
    const rRect = (extra && extra.rectTablesCount != null) ? extra.rectTablesCount : (res && res.rectTablesCount != null ? res.rectTablesCount : 0);
    if (rRound > 0 || rRect > 0) {
      roundCount = parseInt(rRound) || 0;
      rectCount = parseInt(rRect) || 0;
    }
  }

  return {
    roundCount: roundCount,
    rectCount: rectCount,
    totalCount: roundCount + rectCount,
    hasLayout: (roundCount + rectCount > 0) || elements.length > 0
  };
}
window.getVenueLayoutTableCounts = getVenueLayoutTableCounts;

function isRoundTableItem(item) {
  if (!item) return false;
  const cat = ((item.category || item.cat || '') + '').toLowerCase();
  if (cat.includes('linen') || cat.includes('cloth') || cat.includes('decoration')) return false;
  const id = ((item.assetId || item.id || item.asset_id || '') + '').toUpperCase().trim();
  const name = ((item.name || '') + '').toLowerCase().trim();
  if (name.includes('tablecloth') || name.includes('runner') || name.includes('cloth')) return false;
  if (id === 'EQ-0005' || id === 'EQ7') return true;
  if (name.includes('round banquet table') || name.includes('round table')) return true;
  return false;
}
window.isRoundTableItem = isRoundTableItem;

function isRectTableItem(item) {
  if (!item) return false;
  const cat = ((item.category || item.cat || '') + '').toLowerCase();
  if (cat.includes('linen') || cat.includes('cloth') || cat.includes('decoration')) return false;
  const id = ((item.assetId || item.id || item.asset_id || '') + '').toUpperCase().trim();
  const name = ((item.name || '') + '').toLowerCase().trim();
  if (name.includes('tablecloth') || name.includes('runner') || name.includes('cloth')) return false;
  if (id === 'EQ-0008' || id === 'EQ-F002') return true;
  if (name.includes('rectangular table') || name.includes('rect table') || name.includes('rectangular banquet table')) return true;
  return false;
}
window.isRectTableItem = isRectTableItem;

// ====== AVAILABILITY VIEW ======
async function loadAvailabilityView() {
  const container = document.getElementById('eim-avail-list');
  if (!container) return;
  container.innerHTML = '<div style="text-align:center;padding:40px;color:var(--text-dim);font-size:13px;">Loading availability...</div>';
  const sb = window.supabaseClient;
  if (!sb) { container.innerHTML = '<div style="padding:20px;color:var(--red);">Supabase not available.</div>'; return; }

  let eqRows = [];
  let venueConfigMap = {};

  // Decorations only — never hide tableware/linens that live in the equipment catalog.
  const isDecoration = (assetId, cat, name) => {
    const c = String(cat || '').toLowerCase();
    if (c.includes('decoration')) return true;
    const id = String(assetId || '').toUpperCase().trim();
    const n = String(name || '').toLowerCase().trim();
    const a = (window.EIM_ASSETS || []).find(x =>
      (x.asset_id && String(x.asset_id).toUpperCase() === id) ||
      (x.id && String(x.id).toUpperCase() === id) ||
      (n && x.name && x.name.toLowerCase().trim() === n)
    );
    return !!(a && String(a.category || '').toLowerCase().includes('decoration'));
  };

  // Helper to format dates consistently
  const formatResDate = (dStr) => {
    if (!dStr) return null;
    const d = new Date(dStr);
    if (!isNaN(d.getTime())) return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
    return dStr;
  };

  window._availCurrentFilter = window._availCurrentFilter || 'All';
  let targetRes = (RESERVATIONS || []).filter(r => {
    const s = (r.status || '').toLowerCase();
    const isApproved = s.includes('confirm') || s.includes('planning') || s.includes('procurement') || s.includes('preparation') || s.includes('on-going');
    const isPending = s.includes('pending') || s.includes('review');

    if (window._availCurrentFilter === 'Approved') return isApproved;
    if (window._availCurrentFilter === 'Pending') return isPending;
    return isApproved || isPending;
  });

  let baseEq = [];
  try {
    // Find all reservations occurring on the same dates as our target reservations
    const targetDates = new Set(targetRes.map(r => formatResDate(r.date || r.eventDate || null)).filter(Boolean));
    const allNeededResIds = (RESERVATIONS || [])
      .filter(r => targetDates.has(formatResDate(r.date || r.eventDate || null)))
      .map(r => r.id);

    const [resEq, resHist, resVenue] = await Promise.all([
      sb.from('equipment_inventory').select('id,asset_id,name,category,total_qty,maintenance_qty,parent_asset_id,is_disabled,extra_buffer'),
      sb.from('allocation_history')
        .select('asset_id,equipment_name,allocated_qty,reservation_id,reservation_name,allocation_batch,is_rental,recorded_at')
        .not('allocation_batch', 'is', null)
        .in('reservation_id', allNeededResIds.length > 0 ? allNeededResIds : ['NONE']), // Avoid empty array error
      sb.from('venue_equipment').select('*').in('reservation_id', allNeededResIds.length > 0 ? allNeededResIds : ['NONE'])
    ]);
    if (resEq.error) throw resEq.error;
    if (resHist.error) throw resHist.error;

    baseEq = resEq.data || [];
    let histData = resHist.data || [];
    const venueData = resVenue.data || [];

    // Map venue buffers per reservation
    venueConfigMap = {};
    venueData.forEach(v => {
      venueConfigMap[v.reservation_id] = {
        items: v.items || []
      };
    });

    // Deduplicate existing history data to self-heal old duplicate batches
    const dedupMap = {};
    histData.forEach(h => {
      if (!h.reservation_id) return;
      const isVenue = h.allocation_batch && h.allocation_batch.startsWith('VENUE-');
      const key = `${h.reservation_id}_${h.equipment_name || h.asset_id}_${h.is_rental}_${!!isVenue}`;
      const time = h.recorded_at ? new Date(h.recorded_at).getTime() : 0;
      if (!dedupMap[key] || time > dedupMap[key].time) {
        dedupMap[key] = { row: h, time };
      }
    });
    histData = Object.values(dedupMap).map(d => d.row);

    // Push base unallocated rows so every asset exists (for total_qty reference)
    baseEq.forEach(eq => {
      if (isDecoration(eq.asset_id || eq.id, eq.category, eq.name)) return;
      
      eqRows.push({
        ...eq,
        allocated_qty: 0,
        rented_qty: 0,
        allocated_reservation_id: null,
        allocated_to: null,
        allocation_batch: null
      });
    });

    // Push historical allocation rows
    histData.forEach(h => {
      let eq = null;
      if (h.asset_id) {
        eq = baseEq.find(e => (e.asset_id || '').toUpperCase() === (h.asset_id || '').toUpperCase());
      }
      if (!eq && h.equipment_name) {
        eq = baseEq.find(e => (e.name || '').toLowerCase().trim() === (h.equipment_name || '').toLowerCase().trim());
      }
      eq = eq || {};
      
      if (isDecoration(h.asset_id || eq.asset_id || eq.id, eq.category, h.equipment_name || eq.name)) return;
      
      const isVenue = h.allocation_batch && h.allocation_batch.startsWith('VENUE-');
      eqRows.push({
        id: eq.id || h.asset_id,
        asset_id: h.asset_id || eq.asset_id || eq.id, // recover missing asset_id for rentals
        name: h.equipment_name || eq.name,
        category: eq.category,
        total_qty: eq.total_qty,
        allocated_qty: (h.is_rental || isVenue) ? 0 : h.allocated_qty,
        rented_qty: h.is_rental ? h.allocated_qty : 0,
        venue_qty: isVenue ? h.allocated_qty : 0,
        allocated_reservation_id: h.reservation_id,
        allocated_to: h.reservation_name,
        allocation_batch: h.allocation_batch
      });
    });
  } catch (err) {
    console.warn('[Availability] Supabase fetch failed:', err);
    container.innerHTML = '<div style="padding:20px;color:var(--red);">Failed to load equipment data from Supabase.</div>';
    return;
  }
  const allEquip = eqRows || [];

  const byAssetId = {};
  allEquip.forEach(row => {
    const key = (row.asset_id || '').toUpperCase().trim();
    if (key) {
      if (!byAssetId[key]) byAssetId[key] = [];
      byAssetId[key].push(row);
    }
  });

  // Build a family-total map: for every root asset, sum its total_qty + all its batch children's total_qty
  // This ensures the availability column shows the FULL stock pool (original + splits + normals)
  const familyTotalQtyMap = {}; // rootAssetId.toUpperCase() -> aggregated total_qty
  const childToRootMap = {};    // childAssetId.toUpperCase() -> rootAssetId.toUpperCase()
  {
    // First pass: build childToRootMap from baseEq (now includes parent_asset_id from Supabase)
    // This is the primary source - it's fresh from the DB and doesn't depend on EIM_ASSETS being loaded
    baseEq.forEach(eq => {
      if (eq.parent_asset_id && !eq.is_disabled) {
        const rootKey = (eq.parent_asset_id || '').toUpperCase();
        const childKey = (eq.asset_id || '').toUpperCase();
        if (childKey) childToRootMap[childKey] = rootKey;
      }
    });
    // Also pull from EIM_ASSETS as supplemental (in case any were not returned by the above query)
    const eimAssets = window.EIM_ASSETS || [];
    eimAssets.forEach(a => {
      if (a.parent_asset_id && !a.is_disabled) {
        const rootKey = (a.parent_asset_id || '').toUpperCase();
        const childKey = (a.asset_id || a.id || '').toUpperCase();
        if (childKey && !childToRootMap[childKey]) childToRootMap[childKey] = rootKey;
      }
    });
    // Second pass: build family totals directly from baseEq (live fresh Supabase data)
    // Now that childToRootMap is correct, each child row will roll up into its parent bucket
    baseEq.forEach(eq => {
      if (eq.is_disabled) return;
      const key = (eq.asset_id || '').toUpperCase();
      if (!key) return;
      const rootKey = childToRootMap[key] || key; // if child, map to root; otherwise self
      const usableQty = (parseInt(eq.total_qty) || 0) - (parseInt(eq.maintenance_qty) || 0);
      familyTotalQtyMap[rootKey] = (familyTotalQtyMap[rootKey] || 0) + Math.max(0, usableQty);
    });
    console.log('[Avail] familyTotalQtyMap (EQ-0038 should be 140):', JSON.stringify(familyTotalQtyMap).substring(0, 500));
  }
  // Helper: get the combined total_qty for an asset's entire family
  const getFamilyTotal = (assetIdKey) => {
    const key = (assetIdKey || '').toUpperCase();
    const rootKey = childToRootMap[key] || key;

    // PRIMARY: familyTotalQtyMap is built from fresh baseEq data (always available)
    if (familyTotalQtyMap[rootKey] != null) {
      return familyTotalQtyMap[rootKey];
    }

    // FALLBACK: EIM_ASSETS (in case item wasn't in the equipment_inventory query)
    const eimFamily = (window.EIM_ASSETS || [])
      .filter(a => !a.is_disabled && ((a.asset_id || a.id || '').toUpperCase() === rootKey || (a.parent_asset_id || '').toUpperCase() === rootKey));
    if (eimFamily.length > 0) {
      return eimFamily.reduce((sum, a) => sum + Math.max(0, (parseInt(a.quantity) || 0) - (parseInt(a.maintenance_qty) || 0)), 0);
    }

    const byAss = byAssetId[key] && byAssetId[key][0];
    return byAss ? Math.max(0, (parseInt(byAss.total_qty) || 0) - (parseInt(byAss.maintenance_qty) || 0)) : 0;
  };
  // Helper: get all family asset keys for cross-date allocation deduction
  const getFamilyKeys = (assetIdKey) => {
    const rootKey = (childToRootMap[(assetIdKey || '').toUpperCase()] || (assetIdKey || '').toUpperCase());
    const eimAssets = window.EIM_ASSETS || [];
    const childKeys = eimAssets
      .filter(a => a.parent_asset_id && (a.parent_asset_id || '').toUpperCase() === rootKey && !a.is_disabled)
      .map(a => (a.asset_id || a.id || '').toUpperCase())
      .filter(Boolean);
    return new Set([rootKey, ...childKeys]);
  };

  // ── Build a "standard equipment template" from all batches ever saved ──
  // Keyed by asset_id → Supabase row. Used for unallocated reservations so
  // they show the same complete item list as allocated ones.
  const standardEqTemplate = {}; // asset_id.toUpperCase() → { eq, templateAllocQty }
  allEquip.forEach(e => {
    if (!e.allocation_batch || !e.asset_id || e.allocation_batch.startsWith('VENUE-')) return;
    const key = e.asset_id.toUpperCase();
    // Keep the first occurrence (or the one with largest allocated_qty as reference)
    const combinedQty = (parseInt(e.allocated_qty) || 0) + (parseInt(e.rented_qty) || 0);
    if (!standardEqTemplate[key] || combinedQty > (standardEqTemplate[key].templateAllocQty || 0)) {
      standardEqTemplate[key] = { eq: e, templateAllocQty: combinedQty };
    }
  });

  // Find the pax for the reservation that provided the template
  // We use this to scale Required quantities proportionally for other reservations.
  let templatePax = 0;
  const templateResIds = new Set(Object.values(standardEqTemplate).map(t => t.eq.allocated_reservation_id).filter(Boolean));
  templateResIds.forEach(rid => {
    if (templatePax) return;
    const tRes = (RESERVATIONS || []).find(r => r.id === rid);
    if (tRes && parseInt(tRes.pax) > 0) templatePax = parseInt(tRes.pax);
  });
  if (!templatePax) templatePax = 1; // safe fallback



  // Sort by date chronologically
  targetRes.sort((a, b) => {
    const da = a.date || a.eventDate || '';
    const db = b.date || b.eventDate || '';
    const timeA = da ? new Date(da).getTime() : 0;
    const timeB = db ? new Date(db).getTime() : 0;
    if (!isNaN(timeA) && !isNaN(timeB)) return timeA - timeB;
    return da.localeCompare(db);
  });

  if (!targetRes.length) {
    container.innerHTML = '<div style="text-align:center;padding:40px;color:var(--text-dim);font-size:13px;">No reservations found for the selected filter.</div>';
    return;
  }

  let lastDateGroup = null;
  const detectedAvailShortages = [];
  const cards = targetRes.map(res => {
    const resDate = formatResDate(res.date || res.eventDate || null);
    const resId = res.id;
    const pax = parseInt(res.pax) || 0;
    const tablesNeeded = Math.ceil(pax / 8);

    let menuItemCount = 1;
    if (res.packageItems && typeof CAT !== 'undefined') {
      menuItemCount = res.packageItems.map(n => CAT.find(c => c.name === (typeof n === 'string' ? n : n.name))).filter(i => i && i.cat === 'food').length || 1;
    }

    const _rawVip = res.vipCount != null ? res.vipCount : (res.vip && typeof res.vip === 'object' ? res.vip.count : (res.vip_count != null ? res.vip_count : res.vip));
    const resHasVip = (parseInt(_rawVip) || 0) > 0 || !!(res.hasVip || res.isVip);

    const calcQty = (aKey, assetRuleFallback) => {
      const realAsset = typeof window.findAssetForRule === 'function' ? window.findAssetForRule({ assetId: aKey }) : null;
      const fallback = assetRuleFallback || (realAsset ? realAsset.allocationRule || realAsset.allocation_type : 'fixed');
      const r = (fallback || 'fixed').toLowerCase();
      const mPerItem = r.match(/^per_(\d+)_per_item:(.+)$/i);
      if (mPerItem) return parseInt(mPerItem[1]) || 1;
      if (r === 'per_pax') return pax;
      else if (r === 'per_5_pax') return Math.ceil(pax / 5);
      else if (r === 'per_8_pax') return Math.ceil(pax / 8);
      else if (r === 'per_10_pax') return Math.ceil(pax / 10);
      else if (r === 'per_table') return tablesNeeded;
      else if (r === 'per_menu_item') return menuItemCount;
      else if (r === 'every_vip') return resHasVip ? 1 : 0;
      else if (r === 'fixed' || r === 'flat') return 1;
      return pax; // ultimate fallback
    };

    const vConfig = venueConfigMap[resId] || { items: [] };

    const getVenueQty = (aKey) => {
      if (!aKey) return 0;
      const vItem = vConfig.items.find(i => (i.assetId || '').toUpperCase() === aKey);
      return vItem ? (parseInt(vItem.quantity) || 0) : 0;
    };

    // Safety buffer is driven by the extra_buffer column in Supabase (equipment_inventory)
    const calcBuffer = (qty, aKey, venueQty = 0) => {
      const eqList = aKey ? (byAssetId[aKey] || []) : [];
      const asset = eqList[0] || {};
      return asset.extra_buffer || 0;
    };

    // ── Step 1: Items ACTUALLY in this reservation's Supabase batch ──────
    // These are the ground truth : whatever was saved by Equipment Cycle.
    const rawBatchItems = allEquip.filter(e => e.allocated_reservation_id === resId && (e.asset_id || '').toUpperCase() !== 'VENUE');

    // Aggregate by ROOT asset_id to combine inventory, rental quantities AND collapse batch children.
    // A batch child (e.g. EQ-0042-BATCH-2) should roll up into its parent (EQ-0042) for display.
    const aggregatedBatchItems = {};
    rawBatchItems.forEach(eq => {
      let rawKey = (eq.asset_id || '').toUpperCase().trim();

      if (!rawKey) {
        const match = allEquip.find(e => (e.name || '').toLowerCase() === (eq.name || '').toLowerCase() && e.asset_id && e.asset_id.toUpperCase() !== 'VENUE');
        if (match) {
          rawKey = (match.asset_id || '').toUpperCase().trim();
          eq.asset_id = match.asset_id;
          eq.total_qty = match.total_qty;
        } else {
          rawKey = 'NAME-' + (eq.name || '').toUpperCase().trim();
        }
      }

      // Map batch children to their root parent key so they collapse into one row
      const aKey = childToRootMap[rawKey] || rawKey;

      if (!aggregatedBatchItems[aKey]) {
        // Seed with root's eq row if possible, otherwise use this row
        const rootEqRow = allEquip.find(e => (e.asset_id || '').toUpperCase() === aKey) || eq;
        aggregatedBatchItems[aKey] = { ...rootEqRow, asset_id: aKey, allocated_qty: 0, rented_qty: 0, venue_qty: 0 };
      }
      aggregatedBatchItems[aKey].allocated_qty += (parseInt(eq.allocated_qty) || 0);
      aggregatedBatchItems[aKey].rented_qty += (parseInt(eq.rented_qty) || 0);
      aggregatedBatchItems[aKey].venue_qty += (parseInt(eq.venue_qty) || 0);
    });
    const batchItems = Object.values(aggregatedBatchItems);

    // Build a set of asset_ids already covered by the batch
    const batchAssetIds = new Set(batchItems.map(e => (e.asset_id || '').toUpperCase().trim()).filter(Boolean));

    // ── Step 2: Build the supplemental item list for items NOT in batch ──
    // Priority order (highest fidelity first):
    //   2a) res.equipmentManifest  - exact quantities saved by Equipment Cycle
    //   2b) res.packageItems       - name strings from the reservation's package
    //   2c) standardEqTemplate     - inferred from other reservations' batches
    //   2d) ALLOC_RULES            - global rules as last resort
    const supplementRows = [];
    const seenInSupplement = new Set(batchAssetIds);

    // 2a) reservation's own equipmentManifest : highest fidelity, has exact asset IDs + qty
    if (res.equipmentManifest && res.equipmentManifest.length) {
      res.equipmentManifest.forEach(mItem => {
        const mKey = (mItem.assetId || '').toUpperCase().trim();
        if (mKey === 'VENUE' || (mKey && seenInSupplement.has(mKey))) return; // already in batch or legacy VENUE row
        
        // Skip decorations from showing up in the Availability tab's supplemental list
        const realAsset = (window.EIM_ASSETS || []).find(a => (a.asset_id || a.id || '').toUpperCase().trim() === mKey);
        if (realAsset && (realAsset.category || '').toLowerCase().includes('decoration')) return;

        const eqList = mKey ? (byAssetId[mKey] || []) : [];
        const eq = eqList[0] || { asset_id: mItem.assetId, name: mItem.name, total_qty: 0 };
        const needed = calcQty(mKey, eq.allocationRule || eq.allocation_type);
        if (needed <= 0) return;
        if (mKey) seenInSupplement.add(mKey);
        const buffer = calcBuffer(needed, mKey);
        supplementRows.push({ assetId: mItem.assetId || ':', name: mItem.name || ':', needed, buffer, eq });
      });
    }

    // 2b) res.packageItems : name strings from the reservation's package (fallback if manifest not yet generated)
    if (res.packageItems && res.packageItems.length) {
      const assets = window.EIM_ASSETS || [];
      res.packageItems.forEach(itemEntry => {
        const itemName = typeof itemEntry === 'string' ? itemEntry : (itemEntry.name || '');
        if (!itemName) return;
        // Match by name against EIM_ASSETS
        const asset = assets.find(a => (a.name || '').toLowerCase().trim() === itemName.toLowerCase().trim())
          || (typeof window.findAssetForRule === 'function' ? window.findAssetForRule({ name: itemName }) : null);
        if (!asset) return;
        const aKey = (asset.id || asset.asset_id || '').toUpperCase().trim();
        if (aKey && seenInSupplement.has(aKey)) return; // already covered
        
        // Skip decorations from showing up in the Availability tab
        if (asset && (asset.category || '').toLowerCase().includes('decoration')) return;

        let qty = calcQty(aKey, asset.allocationRule);
        if (qty <= 0) return;
        const eqList = aKey ? (byAssetId[aKey] || []) : [];
        const eq = eqList[0] || { asset_id: asset.id || asset.asset_id, name: asset.name, total_qty: asset.quantity || 0 };
        if (aKey) seenInSupplement.add(aKey);
        const buffer = calcBuffer(qty, aKey);
        supplementRows.push({ assetId: asset.id || asset.asset_id || ':', name: asset.name || itemName, needed: qty, buffer, eq });
      });
    }

    // 2c) standardEqTemplate : items inferred from other reservations' allocation batches
    // ONLY include template items that are actually in THIS reservation's packageItems.
    // This prevents equipment allocated to OTHER packages from leaking into unrelated reservations.
    const resPackageItemNames = new Set(
      (res.packageItems || []).map(n => (typeof n === 'string' ? n : (n && n.name) || '').toLowerCase().trim()).filter(Boolean)
    );
    Object.entries(standardEqTemplate).forEach(([key, tmpl]) => {
      if (seenInSupplement.has(key)) return; // Already covered by manifest/packageItems/batch
      const eq = tmpl.eq;
      // If this reservation has packageItems defined, only include template items that match
      if (resPackageItemNames.size > 0) {
        const tmplNameLower = (eq.name || '').toLowerCase().trim();
        if (!resPackageItemNames.has(tmplNameLower)) return; // Not in this reservation's package : skip
      }
      
      // Skip decorations
      if (eq && (eq.category || '').toLowerCase().includes('decoration')) return;
      
      seenInSupplement.add(key);

      let needed = calcQty(key, eq.allocationRule || eq.allocation_type);
      if (!needed) needed = Math.ceil((tmpl.templateAllocQty / templatePax) * pax);

      if (needed <= 0) return;
      const buffer = calcBuffer(needed, key);
      supplementRows.push({ assetId: eq.asset_id || ':', name: eq.name || ':', needed, buffer, eq });
    });

    // 2d) ALLOC_RULES : global rules as last resort for items not yet seen
    // Only include if the item is actually in this reservation's packageItems (same gate as Step 2c)
    (ALLOC_RULES || []).forEach(rule => {
      if (!rule || !rule.name) return;
      const ruleKey = (rule.assetId || '').toUpperCase().trim();
      if (seenInSupplement.has(ruleKey)) return;
      // If this reservation has packageItems, skip ALLOC_RULES items not in the package
      if (resPackageItemNames.size > 0) {
        const ruleNameLower = (rule.name || '').toLowerCase().trim();
        if (!resPackageItemNames.has(ruleNameLower)) return;
      }
      seenInSupplement.add(ruleKey);
      const eqList = ruleKey ? (byAssetId[ruleKey] || []) : [];
      if (!eqList.length) return; // Not in Supabase, skip
      
      // Skip decorations
      if (eqList[0] && (eqList[0].category || '').toLowerCase().includes('decoration')) return;

      let qty = calcQty(ruleKey, 'fixed');
      if (qty <= 0) return;
      const buffer = calcBuffer(qty, ruleKey);
      supplementRows.push({ assetId: rule.assetId, name: rule.name, needed: qty, buffer, eq: eqList[0] });
    });

    // 2e) If reservation has VIP, ensure every_vip equipment is added to supplement
    if (resHasVip) {
      allEquip.forEach(eq => {
        if (!eq || eq.is_disabled || (eq.category || '').toLowerCase().includes('decoration')) return;
        const r = ((eq.allocationRule || eq.allocation_type || '') + '').toLowerCase();
        if (r === 'every_vip') {
          const key = (eq.asset_id || '').toUpperCase().trim();
          if (key && !seenInSupplement.has(key)) {
            seenInSupplement.add(key);
            const buffer = calcBuffer(1, key);
            supplementRows.push({ assetId: eq.asset_id || ':', name: eq.name || ':', needed: 1, buffer, eq });
          }
        }
      });
    }

    // 2f) Equipment tied to specific menu items (Other: Per N Per Menu Item)
    allEquip.forEach(eq => {
      if (!eq || eq.is_disabled || (eq.category || '').toLowerCase().includes('decoration')) return;
      const r = ((eq.allocationRule || eq.allocation_type || '') + '').toLowerCase();
      const m = r.match(/^per_(\d+)_per_item:(.+)$/i);
      if (m) {
        const targetDishName = m[2].trim().toLowerCase();
        let dishPresent = resPackageItemNames.has(targetDishName);
        if (!dishPresent && Array.isArray(res.dishes)) {
          dishPresent = res.dishes.some(d => (typeof d === 'string' ? d : (d && d.name) || '').trim().toLowerCase() === targetDishName);
        }
        if (!dishPresent && Array.isArray(res.custom_package_items)) {
          dishPresent = res.custom_package_items.some(d => (typeof d === 'string' ? d : (d && d.name) || '').trim().toLowerCase() === targetDishName);
        }
        if (!dishPresent && Array.isArray(res.customPackageItems)) {
          dishPresent = res.customPackageItems.some(d => (typeof d === 'string' ? d : (d && d.name) || '').trim().toLowerCase() === targetDishName);
        }
        if (dishPresent) {
          const key = (eq.asset_id || '').toUpperCase().trim();
          if (key && !seenInSupplement.has(key)) {
            seenInSupplement.add(key);
            const reqN = parseInt(m[1]) || 1;
            const buffer = calcBuffer(reqN, key);
            supplementRows.push({ assetId: eq.asset_id || ':', name: eq.name || ':', needed: reqN, buffer, eq });
          }
        }
      }
    });


    // ── Step 3: Build unified display rows ───────────────────────────────
    // Pre-compute the set of other reservation IDs that share the same event date.
    // This is more reliable than comparing allocation_date on equipment rows because
    // that column may not exist or may be null in equipment_inventory.
    const sameDateResIds = new Set(
      (RESERVATIONS || [])
        .filter(r => r.id !== resId && formatResDate(r.date || r.eventDate || null) === resDate)
        .map(r => r.id)
    );
    const rows = [];

    // a) Batch items (this reservation's actual allocation : ground truth)
    batchItems.forEach(eq => {
      const aKey = (eq.asset_id || '').toUpperCase().trim();
      if (isDecoration(aKey, eq.category, eq.name)) return; // Forceful final check
      
      let needed = calcQty(aKey, eq.allocation_type || eq.allocationRule);
      const custInfo = getEquipmentCustomizationDelta(eq, res, needed);
      const custDelta = custInfo.delta;
      const venueToThis = parseInt(eq.venue_qty) || getVenueQty(aKey);
      const buffer = calcBuffer(needed, aKey, venueToThis);
      const effectiveNeeded = Math.max(0, needed + custDelta);
      const afterVenue = Math.max(0, effectiveNeeded - venueToThis);
      const totalReq = afterVenue + buffer;
      const total = getFamilyTotal(aKey);  // ← aggregated across all batches
      const allocatedToThis = parseInt(eq.allocated_qty) || 0;
      const rentedToThis = parseInt(eq.rented_qty) || 0;
      
      const familyKeys = getFamilyKeys(aKey);
      const allocatedToOthers = allEquip
        .filter(e2 =>
          familyKeys.has((e2.asset_id || '').toUpperCase()) &&
          e2.allocated_reservation_id &&
          sameDateResIds.has(e2.allocated_reservation_id)
        )
        .reduce((s, e2) => s + (parseInt(e2.allocated_qty) || 0), 0);
      const available = Math.max(0, total - allocatedToOthers);
      rows.push({ assetId: eq.asset_id || ':', name: eq.name || ':', needed, buffer, custDelta, totalReq, total, allocatedToThis, rentedToThis, venueToThis, available });
    });

    // b) Supplement rows (items not yet in the batch for this reservation)
    supplementRows.forEach(nr => {
      const eq = nr.eq;
      const aKey = (eq.asset_id || '').toUpperCase();
      if (isDecoration(aKey, eq.category, nr.name)) return; // Forceful final check
      
      const total = getFamilyTotal(aKey);  // ← aggregated across all batches
      const familyKeys = getFamilyKeys(aKey);
      const allocatedToOthers = allEquip
        .filter(e2 =>
          familyKeys.has((e2.asset_id || '').toUpperCase()) &&
          e2.allocated_reservation_id &&
          sameDateResIds.has(e2.allocated_reservation_id)
        )
        .reduce((s, e2) => s + (parseInt(e2.allocated_qty) || 0), 0);
      const available = Math.max(0, total - allocatedToOthers);
      const venueToThis = getVenueQty(aKey);
      const custInfo = getEquipmentCustomizationDelta(nr.eq, res, nr.needed);
      const custDelta = custInfo.delta;
      const effectiveNeeded = Math.max(0, nr.needed + custDelta);
      const afterVenue = Math.max(0, effectiveNeeded - venueToThis);
      // Recalculate buffer since it might not have been done with venueQty in step 2
      const buffer = calcBuffer(nr.needed, aKey, venueToThis);
      const totalReq = afterVenue + buffer;
      rows.push({ assetId: nr.assetId || ':', name: nr.name, needed: nr.needed, buffer, custDelta, totalReq, total, allocatedToThis: 0, rentedToThis: 0, venueToThis, available });
    });

    // ── Venue Layout Table Counts Comparison for Availability ──
    const layoutCounts = typeof getVenueLayoutTableCounts === 'function' ? getVenueLayoutTableCounts(resId) : { roundCount: 0, rectCount: 0 };

    // 1. Round Banquet Table
    let availRoundRow = rows.find(r => isRoundTableItem(r));
    if (!availRoundRow && layoutCounts.roundCount > 0) {
      const match = allEquip.find(e => isRoundTableItem(e));
      const aKey = match ? (match.asset_id || '').toUpperCase() : 'EQ-0005';
      const total = getFamilyTotal(aKey);
      const familyKeys = getFamilyKeys(aKey);
      const allocatedToOthers = allEquip
        .filter(e2 =>
          familyKeys.has((e2.asset_id || '').toUpperCase()) &&
          e2.allocated_reservation_id &&
          sameDateResIds.has(e2.allocated_reservation_id)
        )
        .reduce((s, e2) => s + (parseInt(e2.allocated_qty) || 0), 0);
      const available = Math.max(0, total - allocatedToOthers);
      availRoundRow = {
        assetId: match?.asset_id || 'EQ-0005',
        name: match?.name || 'Round Banquet Table (80")',
        needed: 0,
        buffer: 0,
        totalReq: 0,
        total,
        allocatedToThis: 0,
        rentedToThis: 0,
        venueToThis: 0,
        available
      };
      rows.push(availRoundRow);
    }
    if (availRoundRow && layoutCounts.roundCount > availRoundRow.totalReq) {
      const extra = layoutCounts.roundCount - availRoundRow.totalReq;
      availRoundRow.extraBufferFromLayout = extra;
      availRoundRow.bufferDisplay = `+${availRoundRow.buffer} (+${extra} from venue layout)`;
      availRoundRow.totalReq += extra;
      availRoundRow.buffer += extra;
    }

    // 2. Rectangular Table
    let availRectRow = rows.find(r => isRectTableItem(r));
    if (!availRectRow && layoutCounts.rectCount > 0) {
      const match = allEquip.find(e => isRectTableItem(e));
      const aKey = match ? (match.asset_id || '').toUpperCase() : 'EQ-0008';
      const total = getFamilyTotal(aKey);
      const familyKeys = getFamilyKeys(aKey);
      const allocatedToOthers = allEquip
        .filter(e2 =>
          familyKeys.has((e2.asset_id || '').toUpperCase()) &&
          e2.allocated_reservation_id &&
          sameDateResIds.has(e2.allocated_reservation_id)
        )
        .reduce((s, e2) => s + (parseInt(e2.allocated_qty) || 0), 0);
      const available = Math.max(0, total - allocatedToOthers);
      availRectRow = {
        assetId: match?.asset_id || 'EQ-0008',
        name: match?.name || 'Rectangular Banquet Table 6ft',
        needed: 0,
        buffer: 0,
        totalReq: 0,
        total,
        allocatedToThis: 0,
        rentedToThis: 0,
        venueToThis: 0,
        available
      };
      rows.push(availRectRow);
    }
    if (availRectRow && layoutCounts.rectCount > availRectRow.totalReq) {
      const extra = layoutCounts.rectCount - availRectRow.totalReq;
      availRectRow.extraBufferFromLayout = extra;
      availRectRow.bufferDisplay = `+${availRectRow.buffer} (+${extra} from venue layout)`;
      availRectRow.totalReq += extra;
      availRectRow.buffer += extra;
    }

    const hasBatchForRes = allEquip.some(e => e.allocated_reservation_id === resId && e.allocation_batch);
    const hasNeeds = rows.some(r => r.totalReq > 0);
    const allAllocated = hasBatchForRes && hasNeeds && rows.every(r => r.totalReq === 0 || (r.allocatedToThis + r.rentedToThis + r.venueToThis) >= r.totalReq);
    const anyShort = rows.some(r => r.totalReq > 0 && (r.available + r.rentedToThis + r.venueToThis) < r.totalReq);
    // Check if any allocated item still falls short of the requirement (batch exists but under-allocated)
    const anyAllocatedShort = hasBatchForRes && rows.some(r => r.totalReq > 0 && (r.allocatedToThis + r.rentedToThis + r.venueToThis) < r.totalReq);

    let isModified = false;
    if (hasBatchForRes && typeof _genBatchName === 'function' && typeof _getBatchModificationString === 'function') {
      const batchItem = allEquip.find(e => e.allocated_reservation_id === resId && e.allocation_batch);
      if (batchItem) {
        const expectedBatch = _genBatchName(res);
        if (batchItem.allocation_batch !== expectedBatch) {
          const changeStr = _getBatchModificationString(batchItem.allocation_batch, expectedBatch);
          if (changeStr && changeStr !== 'No significant changes detected.') {
            isModified = true;
          }
        }
      }
    }
    // A batch existing does NOT mean all items are covered — if any item is under-allocated, flag as short
    const cardStatus = (allAllocated && !anyAllocatedShort) ? 'green' : (anyAllocatedShort || anyShort) ? 'red' : (hasBatchForRes ? 'green' : 'yellow');
    const borderColor = cardStatus === 'green' ? 'rgba(45,138,78,0.5)' : cardStatus === 'red' ? 'rgba(192,57,43,0.5)' : 'rgba(196,154,60,0.4)';
    const statusText = allAllocated ? 'Fully Allocated' : anyAllocatedShort ? 'Short : Under-Allocated' : anyShort ? 'Short : Cannot Fulfill' : hasBatchForRes ? 'Allocated (Partial)' : 'Can Be Fulfilled';
    const statusColor = cardStatus === 'green' ? 'var(--green)' : cardStatus === 'red' ? 'var(--red)' : 'var(--gold)';

    const tableRows = rows.map(r => {
      let fulfillable, fColor;
      const totalSecured = r.allocatedToThis + r.rentedToThis + r.venueToThis;

      if (totalSecured >= r.totalReq && r.totalReq > 0) {
        if (r.allocatedToThis > 0 && r.venueToThis > 0 && r.rentedToThis > 0) {
          fulfillable = 'Allocated, Rented & Venue'; fColor = 'var(--green)';
        } else if (r.allocatedToThis > 0 && r.venueToThis > 0) {
          fulfillable = 'Allocated & Venue provided'; fColor = 'var(--green)';
        } else if (r.allocatedToThis > 0 && r.rentedToThis > 0) {
          fulfillable = 'Allocated & Rented'; fColor = 'var(--green)';
        } else if (r.rentedToThis > 0) {
          fulfillable = 'Rented'; fColor = 'var(--green)';
        } else if (r.venueToThis > 0) {
          fulfillable = 'Venue Provided'; fColor = 'var(--green)';
        } else {
          fulfillable = 'Allocated'; fColor = 'var(--green)';
        }
      } else if (r.available + r.rentedToThis + r.venueToThis >= r.totalReq) {
        fulfillable = 'Yes'; fColor = 'var(--gold)';
      } else {
        fulfillable = 'Short'; fColor = 'var(--red)';
      }

      let allocatedDisplay = r.allocatedToThis;
      if (r.rentedToThis > 0 && r.venueToThis > 0) allocatedDisplay += ' <span style="color:var(--gold);font-size:10px;">(+' + r.rentedToThis + ' rented, +' + r.venueToThis + ' venue)</span>';
      else if (r.rentedToThis > 0) allocatedDisplay += ' <span style="color:var(--gold);font-size:10px;">(+' + r.rentedToThis + ' rented)</span>';
      else if (r.venueToThis > 0) allocatedDisplay += ' <span style="color:var(--amber);font-size:10px;">(+' + r.venueToThis + ' venue)</span>';


      const shortAmt = Math.max(0, r.totalReq - (r.available + r.rentedToThis + r.venueToThis));
      if (shortAmt > 0) {
        detectedAvailShortages.push({
          reservation_id: resId,
          reservation_name: res.client || res.name || resId,
          asset_id: r.assetId,
          equipment_name: r.name,
          needed_qty: shortAmt,
          available_stock: r.available,
          event_date: resDate,
          reason: 'Reservation Shortage: ' + (res.client || res.name || resId)
        });
      }
      const shortDisplay = shortAmt > 0
        ? '<span style="font-weight:700;color:var(--red);">' + shortAmt + '</span>'
        : '<span style="color:var(--green);">0</span>';

      return '<tr>' +
        '<td style="font-size:11px;padding:6px 10px;color:var(--text);">' + (r.assetId || ':') + '</td>' +
        '<td style="font-size:12px;padding:6px 10px;">' + r.name + '</td>' +
        '<td style="font-size:12px;padding:6px 10px;font-weight:700;">' + r.needed + '</td>' +
        '<td style="font-size:12px;padding:6px 10px;color:var(--amber);">' + (r.bufferDisplay || ('+' + r.buffer)) + '</td>' +
        '<td style="font-size:12px;padding:6px 10px;">' + (r.custDelta > 0 ? ('<span style="font-weight:700;color:var(--gold);">+' + r.custDelta + '</span>') : (r.custDelta < 0 ? ('<span style="font-weight:700;color:var(--red);">' + r.custDelta + '</span>') : '<span style="color:var(--text-dim);">-</span>')) + '</td>' +
        '<td style="font-size:12px;padding:6px 10px;font-weight:700;color:var(--cream);">' + r.totalReq + '</td>' +
        '<td style="font-size:12px;padding:6px 10px;">' + allocatedDisplay + '</td>' +
        '<td style="font-size:12px;padding:6px 10px;">' + (resDate ? r.available + ' on ' + resDate : r.total + ' total') + '</td>' +
        '<td style="font-size:12px;padding:6px 10px;text-align:center;">' + shortDisplay + '</td>' +
        '<td style="font-size:12px;padding:6px 10px;font-weight:700;color:' + fColor + ';">' + fulfillable + '</td>' +
        '</tr>';
    }).join('');

    return '<div style="margin-bottom:14px;border:1px solid ' + borderColor + ';border-radius:12px;overflow:hidden;">' +
      '<div style="display:flex;align-items:center;justify-content:space-between;padding:14px 18px;cursor:pointer;" onclick="this.parentElement.querySelector(&quot;.avail-detail&quot;).style.display=this.parentElement.querySelector(&quot;.avail-detail&quot;).style.display===&quot;none&quot;?&quot;block&quot;:&quot;none&quot;">' +
      '<div>' +
      '<div style="display:flex;align-items:center;gap:10px;margin-bottom:4px;">' +
      '<span style="font-size:12px;font-weight:700;color:var(--gold);">' + resId + '</span>' +
      (resDate ? '<span style="font-size:11px;color:var(--text-dim);">' + resDate + '</span>' : '') +
      '</div>' +
      '<div style="font-size:13px;font-weight:600;color:var(--cream);">' + (res.client || 'Client') + ' : ' + (res.packageName || res.type || 'Event') + '</div>' +
      '<div style="font-size:11px;color:' + statusColor + ';margin-top:3px;font-weight:600;">' + statusText + '</div>' +
      (isModified ? `<div style="font-size:11px;color:var(--gold);margin-top:4px;font-weight:600;">\u26a0\ufe0f Package significantly modified, allocation needs an update</div>` : '') +
      '</div>' +
      '<div style="display:flex;gap:8px;flex-shrink:0;">' +
      '<button class="btn-outline" style="font-size:11px;padding:5px 12px;" onclick="event.stopPropagation();jumpToEqcForBatch(&quot;' + resId + '&quot;)">Allocate</button>' +
      '</div>' +
      '</div>' +
      '<div class="avail-detail" style="display:none;border-top:1px solid var(--border);">' +
      '<div style="padding:10px 18px;">' +
      '<table style="width:100%;border-collapse:collapse;">' +
      '<thead><tr style="border-bottom:1px solid var(--border);">' +
      '<th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Asset ID</th>' +
      '<th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Equipment</th>' +
      '<th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Required</th>' +
      '<th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Buffer</th>' +
      '<th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Customization</th>' +
      '<th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Total</th>' +
      '<th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Allocated to This</th>' +
      '<th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Available (Date)</th>' +
      '<th style="text-align:center;font-size:11px;color:var(--red);padding:4px 10px;font-weight:700;">Short</th>' +
      '<th style="text-align:left;font-size:11px;color:var(--text-dim);padding:4px 10px;">Fulfillable</th>' +
      '</tr></thead>' +
      '<tbody>' + tableRows + '</tbody>' +
      '</table>' +
      '</div>' +
      '</div>' +
      '</div>';

    let finalHtml = '';
    const groupDate = resDate ? new Date(resDate).toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' }) : 'Unscheduled';
    if (groupDate !== lastDateGroup && groupDate !== 'Invalid Date') {
      finalHtml += '<div style="font-size:13px; font-weight:700; color:var(--text-dim); margin:20px 0 10px 0; border-bottom:1px solid var(--border); padding-bottom:4px;">' + groupDate + '</div>';
      lastDateGroup = groupDate;
    }
    finalHtml += cardHtml;
    return finalHtml;
  });

  window.availabilityDetectedShortages = detectedAvailShortages;
  container.innerHTML = cards.join('');
}
window.loadAvailabilityView = loadAvailabilityView;

window.filterAvailability = function (filter, btn) {
  window._availCurrentFilter = filter;
  document.querySelectorAll('#eim-avail-filters .btn-outline').forEach(b => b.classList.remove('active'));
  if (btn) btn.classList.add('active');
  loadAvailabilityView();
};

window.loadViewAllocations = loadViewAllocations;

function jumpToEqcForBatch(reservationId) {
  const navEl = document.getElementById('nav-equip-cycle');
  if (navEl) navEl.click();
  else if (typeof showSection === 'function') showSection('equip-cycle', document.getElementById('nav-equip-cycle'));
  setTimeout(() => {
    if (reservationId) {
      const dropdown = document.getElementById('eqc-reservation-select');
      if (dropdown) {
        const found = Array.from(dropdown.options).find(o =>
          o.value === String(reservationId) ||
          o.text.toLowerCase().includes(String(reservationId).toLowerCase())
        );
        if (found) { dropdown.value = found.value; dropdown.dispatchEvent(new Event('change')); }
      }
      if (typeof currentEqcReservationId !== 'undefined') currentEqcReservationId = String(reservationId);
      if (typeof renderAllocationSection === 'function') renderAllocationSection();
    }
    setTimeout(() => {
      const mp = document.getElementById('alloc-manifest-panel');
      if (mp) mp.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 500);
  }, 400);
}
window.jumpToEqcForBatch = jumpToEqcForBatch;

// ===== ADD EQUIPMENT MODAL =====
let eimAddIdCounter = { F: 0, T: 0, G: 0, L: 0, C: 0, A: 0 };
function updateEIMAddId() {
  const cat = document.getElementById('eim-add-category').value;
  const prefixMap = { Furniture: 'F', Tableware: 'T', Glassware: 'G', Linens: 'L', 'Catering Equipment': 'C', 'AV & Lighting': 'A' };
  const p = prefixMap[cat] || 'X';
  const count = EIM_ASSETS.filter(a => a.id.startsWith('EQ-' + p)).length + 1;
  document.getElementById('eim-add-id').value = 'EQ-' + p + String(count).padStart(3, '0');
}
function toggleBatchField() { /* deprecated - batch field removed from new modal */ }
function openAddEquipmentModal() {
  ['eim-add-id', 'eim-add-name', 'eim-add-category', 'eim-add-type', 'eim-add-qty', 'eim-add-unit', 'eim-add-cost', 'eim-add-shopping-cost', 'eim-add-supplier', 'eim-add-notes', 'eim-add-rule-other', 'eim-add-rule-menu-n', 'eim-add-rule-menu-item'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
  const _addRuleType = document.getElementById('eim-add-rule-type'); if (_addRuleType) _addRuleType.value = 'none';
  const _addRuleOther = document.getElementById('eim-add-rule-other'); if (_addRuleOther) _addRuleOther.style.display = 'none';
  const _addRuleMenuWrap = document.getElementById('eim-add-rule-menu-item-wrap'); if (_addRuleMenuWrap) _addRuleMenuWrap.style.display = 'none';
  const _addRuleEquipWrap = document.getElementById('eim-add-rule-equipment-wrap'); if (_addRuleEquipWrap) _addRuleEquipWrap.style.display = 'none';
  const _addRuleLinkedEq = document.getElementById('eim-add-rule-linked-equipment'); if (_addRuleLinkedEq) _addRuleLinkedEq.value = '';
  const _consEl = document.getElementById('eim-add-consumable'); if (_consEl) _consEl.value = 'false';
  const _pdEl = document.getElementById('eim-add-purchase-date');
  if (_pdEl) {
    const todayStr = new Date().toLocaleDateString('en-CA');
    _pdEl.max = todayStr;
    _pdEl.value = todayStr;
  }
  const _descEl = document.getElementById('eim-add-description'); if (_descEl) _descEl.value = '';
  document.getElementById('eim-add-overlay').classList.add('on');
  document.getElementById('eim-add-modal').classList.add('open');
}
function closeAddEquipmentModal() {
  document.getElementById('eim-add-overlay').classList.remove('on');
  document.getElementById('eim-add-modal').classList.remove('open');
}
async function submitAddEquipment() {
  const name = document.getElementById('eim-add-name').value.trim();
  const cat = document.getElementById('eim-add-category').value;
  const typeEl = document.getElementById('eim-add-type');
  let type = typeEl ? typeEl.value : '';
  if (type === 'Other') {
    type = document.getElementById('eim-add-type-other').value.trim();
  }
  let qty = parseInt(document.getElementById('eim-add-qty').value) || 0;
  if (!name || !cat || !type || qty <= 0) { alert('Please fill in Name, Category, Type, and Quantity.'); return; }

  const bufferLimitEl = document.getElementById('eim-add-limit');
  const alertLimit = bufferLimitEl && bufferLimitEl.value !== '' ? parseInt(bufferLimitEl.value) : 0;
  const bufferExtraEl = document.getElementById('eim-add-buffer');
  const extraBuffer = bufferExtraEl && bufferExtraEl.value !== '' ? parseInt(bufferExtraEl.value) : 0;
  const consumableAdd = document.getElementById('eim-add-consumable')?.value === 'true';

  const condVal = 'Good';
  const statVal = 'Available';
  const unitCost = parseFloat(document.getElementById('eim-add-cost').value) || 0;
  const shoppingCostAdd = parseFloat(document.getElementById('eim-add-shopping-cost')?.value) || 0;
  let shoppingUnitAdd = document.getElementById('eim-add-shopping-unit') ? document.getElementById('eim-add-shopping-unit').value : 'pcs';
  if (shoppingUnitAdd === 'every_n') {
    let n = document.getElementById('eim-add-shopping-unit-n')?.value || '1';
    shoppingUnitAdd = 'every_' + n;
  }
  const supplier = document.getElementById('eim-add-supplier').value.trim() || null;
  const srcEl = document.getElementById('eim-add-source');
  const source = srcEl ? srcEl.value.trim() : null;
  const notesVal = document.getElementById('eim-add-notes').value.trim() || null;

  const ruleTypeEl = document.getElementById('eim-add-rule-type');
  let rType = ruleTypeEl ? ruleTypeEl.value : 'none';
  if (rType === 'Other') {
    const paxVal = parseInt(document.getElementById('eim-add-rule-other').value) || 1;
    rType = `per_${paxVal}_pax`;
  } else if (rType === 'other_per_menu_item') {
    const nVal = parseInt(document.getElementById('eim-add-rule-menu-n')?.value) || 1;
    const itemVal = (document.getElementById('eim-add-rule-menu-item')?.value || '').trim();
    if (!itemVal) {
      alert('Please select a menu item for the allocation rule.');
      return;
    }
    rType = `per_${nVal}_per_item:${itemVal}`;
  } else if (rType === 'every_certain_equipment') {
    const linkedEq = (document.getElementById('eim-add-rule-linked-equipment')?.value || '').trim();
    if (!linkedEq) {
      alert('Please select a main equipment for the allocation rule.');
      return;
    }
    rType = `every_certain_equipment:${linkedEq}`;
  }
  const rRatio = document.getElementById('eim-add-rule-ratio') ? document.getElementById('eim-add-rule-ratio').value : 'per_unit';

  const _purchDate = (() => { const el = document.getElementById('eim-add-purchase-date'); return el && el.value ? el.value : new Date().toISOString().split('T')[0]; })();
  const _liVal = _purchDate;
  const _descVal = (() => { const el = document.getElementById('eim-add-description'); return el && el.value.trim() ? el.value.trim() : null; })();

  const btn = document.getElementById('btn-submit-eim');
  if (btn) { btn.disabled = true; btn.textContent = 'Saving...'; }

  try {
    const sb = window.supabaseClient;
    if (!sb) throw new Error('Supabase client not available.');

    const { data: maxAsset } = await sb.from('equipment_inventory')
      .select('asset_id')
      .order('asset_id', { ascending: false })
      .limit(1);

    let nextNum = 1;
    if (maxAsset && maxAsset.length > 0 && maxAsset[0].asset_id) {
      const m = maxAsset[0].asset_id.match(/EQ-(\d+)/);
      if (m) nextNum = parseInt(m[1]) + 1;
      else nextNum = EIM_ASSETS.length + 1;
    } else {
      nextNum = EIM_ASSETS.length + 1;
    }
    const assetIdStr = `EQ-${String(nextNum).padStart(4, '0')}`;

    const trackingMode = document.getElementById('eim-add-tracking')?.value || 'quantity';
    const purchaseSets = (typeof window.getAddEquipmentPurchaseSets === 'function')
      ? window.getAddEquipmentPurchaseSets()
      : [{ qty, unitCost, shoppingCost: shoppingCostAdd, unitType: shoppingUnitAdd, supplier, date: _purchDate }];

    if (trackingMode === 'individual') {
      let sumSets = 0;
      purchaseSets.forEach(s => { sumSets += parseInt(s.qty) || 0; });
      if (sumSets !== qty) {
        alert('Total quantity of purchase sets (' + sumSets + ') must match the initial equipment quantity (' + qty + ').');
        if (btn) { btn.disabled = false; btn.textContent = 'Save Equipment'; }
        return;
      }
    }

    const newRow = {
      tracking_mode: trackingMode,
      purchase_history: purchaseSets.map((st, sIdx) => ({
        set_id: `SET-${sIdx + 1}`,
        date: st.date || _purchDate,
        supplier: st.supplier || supplier || 'Not specified',
        qty: parseInt(st.qty) || qty,
        cost: st.unitCost || unitCost,
        shopping_cost: st.shoppingCost || shoppingCostAdd,
        shopping_unit_type: st.unitType || shoppingUnitAdd
      })),
      asset_id: assetIdStr,
      name: name,
      category: cat,
      type: type,
      total_qty: qty,
      available_qty: qty,
      fragility: document.getElementById('eim-add-fragility')?.value || 'non-fragile',
      status: statVal,
      condition: condVal,
      value: unitCost,
      shopping_cost: shoppingCostAdd,
      shopping_unit_type: shoppingUnitAdd,
      supplier: supplier,
      source_location: supplier,
      pricing_type: rRatio,
      allocation_type: rType,
      description: notesVal || '',
      purchase_date: _purchDate,
      time_purchased: (() => { const el = document.getElementById('eim-add-time-purchased'); return el && el.value ? el.value : (new Date().toTimeString().slice(0, 5)); })(),
      last_inspected: _liVal,
      is_batch: false,
      limit: alertLimit,
      extra_buffer: extraBuffer,
      consumable: consumableAdd,
      image_url: document.getElementById('ae-img-url').value.trim() || null,
      unit_type: (() => {
        let val = document.getElementById('eim-add-unit') ? document.getElementById('eim-add-unit').value : 'pcs';
        if (val === 'every_n') {
          let n = document.getElementById('eim-add-unit-n')?.value || '1';
          val = 'every_' + n;
        }
        return val;
      })()
    };

    let inserted;
    let { data: insData, error: insertErr } = await sb
      .from('equipment_inventory')
      .insert(newRow)
      .select()
      .single();

    if (insertErr && (insertErr.message || '').includes('time_purchased')) {
      console.warn('time_purchased column not found in equipment_inventory, retrying insert without it...');
      const fallbackRow = { ...newRow };
      delete fallbackRow.time_purchased;
      const res = await sb.from('equipment_inventory').insert(fallbackRow).select().single();
      insData = res.data;
      insertErr = res.error;
    }
    if (insertErr && (insertErr.message || '').includes('shopping_unit_type')) {
      console.warn('shopping_unit_type column not found in equipment_inventory, retrying insert without it...');
      const fallbackRow = { ...newRow };
      delete fallbackRow.shopping_unit_type;
      const res = await sb.from('equipment_inventory').insert(fallbackRow).select().single();
      insData = res.data;
      insertErr = res.error;
    }

    if (insertErr) throw insertErr;
    inserted = insData;

    // Generate individual unit items
    const units = (typeof window.buildUnitsFromSets === 'function')
      ? window.buildUnitsFromSets(assetIdStr, purchaseSets, inserted.id)
      : [];
    if (units.length > 0) {
      if (typeof window.HalServeUnitTracker?.persistEquipmentUnits === 'function') {
        await window.HalServeUnitTracker.persistEquipmentUnits(units);
      }
      window.EQUIPMENT_UNITS_CACHE[assetIdStr] = units;
    }

    const scanUrl = window.location.origin + '/scan.html?eq=' + encodeURIComponent(inserted.asset_id || inserted.id);
    const qrUrl = 'https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=' + encodeURIComponent(scanUrl);
    await sb.from('equipment_inventory').update({ qr_code: qrUrl }).eq('id', inserted.id);

    if (rType !== 'none' && typeof ALLOC_RULES !== 'undefined') {
      ALLOC_RULES.push({
        assetId: inserted.id,
        name: inserted.name,
        category: inserted.category,
        isFragile: (inserted.category === 'Glassware' || inserted.category === 'Tableware'),
        ruleType: rType,
        ratio: 1,
        note: 'Added dynamically'
      });
    }

    inserted.consumable = consumableAdd;
    inserted.shoppingUnitType = shoppingUnitAdd;
    inserted.shopping_unit_type = shoppingUnitAdd;
    saveShoppingUnitMapping(inserted.asset_id || assetIdStr, shoppingUnitAdd);
    EIM_ASSETS.push(inserted);

    if (typeof recordEIMLog === 'function') {
      recordEIMLog({
        action: 'Added Equipment',
        eqId: inserted.asset_id || assetIdStr,
        eqName: name,
        shoppingCost: shoppingCostAdd,
        shoppingUnitType: shoppingUnitAdd,
        supplier: supplier || 'Not specified',
        details: `Added new equipment "${name}" (Qty: ${qty}, Unit: ${newRow.unit_type}).`
      });
    }

    alert('Equipment successfully added and saved to database!');
    closeAddEquipmentModal();
    try {
      new BroadcastChannel('eim_realtime_channel').postMessage({ type: 'EQUIPMENT_UPDATED', asset_id: assetIdStr });
    } catch(e) {}
    if (typeof loadEIMAssets === 'function') loadEIMAssets();
    if (typeof loadEIMFromSupabase === 'function') await loadEIMFromSupabase();
  } catch (e) {
    console.error('Error adding equipment:', e);
    alert('Failed to add equipment: ' + (e.message || e));
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'Add Equipment'; }
  }
}

window.submitAddEquipment = submitAddEquipment;

function toggleAddTypeOther(selectEl) {
  const otherInput = document.getElementById('eim-add-type-other');
  if (selectEl && otherInput) {
    if (selectEl.value === 'Other') otherInput.style.display = '';
    else otherInput.style.display = 'none';
  }
}
window.toggleAddTypeOther = toggleAddTypeOther;

function populateLinkedEquipmentDropdown(selectId, selectedId, excludeAssetId) {
  const sel = document.getElementById(selectId);
  if (!sel) return;
  const curVal = (selectedId != null ? selectedId : (sel.value || '')).toString().trim();
  const mainAssets = (typeof EIM_ASSETS !== 'undefined' ? EIM_ASSETS : []).filter(a => {
    if (!a || a.is_disabled) return false;
    if (a.parent_asset_id) return false;
    if (a.is_batch) return false;
    const aId = (a.asset_id || a.id || '').toUpperCase();
    if (excludeAssetId && (aId === (excludeAssetId + '').toUpperCase() || a.id === excludeAssetId || a.supabaseId === excludeAssetId)) return false;
    return true;
  });

  sel.innerHTML = '<option value="">-- Select Main Equipment --</option>' +
    mainAssets.map(a => {
      const val = a.asset_id || a.id;
      const isSel = (val && curVal && (val.toUpperCase() === curVal.toUpperCase() || a.name.toLowerCase() === curVal.toLowerCase())) ? 'selected' : '';
      return `<option value="${escHtml(val)}" ${isSel}>${escHtml(a.name)} (${escHtml(a.asset_id || val)})</option>`;
    }).join('');
}
window.populateLinkedEquipmentDropdown = populateLinkedEquipmentDropdown;

function toggleAddRuleOther(selectEl) {
  const otherInput = document.getElementById('eim-add-rule-other');
  const menuWrap = document.getElementById('eim-add-rule-menu-item-wrap');
  const equipWrap = document.getElementById('eim-add-rule-equipment-wrap');
  if (selectEl) {
    if (otherInput) otherInput.style.display = selectEl.value === 'Other' ? '' : 'none';
    if (menuWrap) menuWrap.style.display = selectEl.value === 'other_per_menu_item' ? '' : 'none';
    if (equipWrap) {
      equipWrap.style.display = selectEl.value === 'every_certain_equipment' ? '' : 'none';
      if (selectEl.value === 'every_certain_equipment') {
        populateLinkedEquipmentDropdown('eim-add-rule-linked-equipment', document.getElementById('eim-add-rule-linked-equipment')?.value);
      }
    }
  }
}
window.toggleAddRuleOther = toggleAddRuleOther;

// ===== EIM MENU ITEM PICKER MODAL =====
let _eimMenuPickerTarget = 'add';
let _eimMenuPickerSelected = '';
let _eimMenuPickerFilter = '';

function openEimMenuPicker(targetMode) {
  _eimMenuPickerTarget = targetMode || 'add';
  const currentVal = _eimMenuPickerTarget === 'add'
    ? (document.getElementById('eim-add-rule-menu-item')?.value || '')
    : (document.getElementById('eim-edit-rule-menu-item')?.value || '');
  _eimMenuPickerSelected = currentVal.trim();
  _eimMenuPickerFilter = '';
  const searchInput = document.getElementById('eim-menu-picker-search');
  if (searchInput) searchInput.value = '';

  renderEimMenuPickerList();

  const overlay = document.getElementById('eim-menu-picker-overlay');
  const modal = document.getElementById('eim-menu-picker-modal');
  if (overlay) overlay.classList.add('on');
  if (modal) modal.classList.add('open');
}
window.openEimMenuPicker = openEimMenuPicker;

function closeEimMenuPicker() {
  const overlay = document.getElementById('eim-menu-picker-overlay');
  const modal = document.getElementById('eim-menu-picker-modal');
  if (overlay) overlay.classList.remove('on');
  if (modal) modal.classList.remove('open');
}
window.closeEimMenuPicker = closeEimMenuPicker;

function filterEimMenuPicker(query) {
  _eimMenuPickerFilter = (query || '').toLowerCase().trim();
  renderEimMenuPickerList();
}
window.filterEimMenuPicker = filterEimMenuPicker;

function selectEimMenuPickerItem(name) {
  if (_eimMenuPickerSelected.toLowerCase() === (name || '').toLowerCase()) {
    _eimMenuPickerSelected = '';
  } else {
    _eimMenuPickerSelected = name;
  }
  renderEimMenuPickerList();
}
window.selectEimMenuPickerItem = selectEimMenuPickerItem;

function saveEimMenuPickerSelection() {
  if (!_eimMenuPickerSelected) {
    alert('Please select a menu item or click Close.');
    return;
  }
  if (_eimMenuPickerTarget === 'add') {
    const itemEl = document.getElementById('eim-add-rule-menu-item');
    if (itemEl) itemEl.value = _eimMenuPickerSelected;
    const nEl = document.getElementById('eim-add-rule-menu-n');
    if (nEl && !nEl.value) nEl.value = '1';
  } else {
    const itemEl = document.getElementById('eim-edit-rule-menu-item');
    if (itemEl) itemEl.value = _eimMenuPickerSelected;
    const nEl = document.getElementById('eim-edit-rule-menu-n');
    if (nEl && !nEl.value) nEl.value = '1';
  }
  closeEimMenuPicker();
}
window.saveEimMenuPickerSelection = saveEimMenuPickerSelection;

function renderEimMenuPickerList() {
  const container = document.getElementById('eim-menu-picker-list');
  if (!container) return;

  const seen = new Set();
  const pool = [];
  const sourceItems = [];
  if (Array.isArray(window.CAT)) sourceItems.push(...window.CAT);
  else if (typeof CAT !== 'undefined' && Array.isArray(CAT)) sourceItems.push(...CAT);
  if (Array.isArray(window.sbMenuItems)) sourceItems.push(...window.sbMenuItems);

  sourceItems.forEach(item => {
    if (!item || !item.name) return;
    const nm = (item.name || '').trim();
    const nmLower = nm.toLowerCase();
    if (seen.has(nmLower)) return;

    const rawCat = (item.cat || item.category || '').toLowerCase();
    const rawIdent = (item.identify || '').toLowerCase();
    const isFood = rawCat === 'food' || rawCat.includes('food');
    const isDessert = rawCat === 'dessert' || rawCat.includes('dessert') || rawIdent === 'desserts' || rawIdent === 'ice_cream' || rawIdent === 'ice_cream_option';
    const isDrink = rawCat === 'drink' || rawCat.includes('drink') || rawIdent === 'drinks' || rawIdent === 'drinks_package' || rawIdent === 'mobile_bar' || rawIdent === 'mobile_bar_option';

    if (!isFood && !isDessert && !isDrink) return;

    // Strictly exclude special items
    const isSpecial = item.is_special || item.isSpecialMaster || item.isMasterSpecial ||
      rawCat === 'special' || rawIdent === 'special' || rawIdent === 'mobile_bar' ||
      rawIdent === 'drinks_package' || rawIdent === 'ice_cream' ||
      nmLower.includes('mobile bar') || nmLower.includes('unlimited drinks') || nmLower.includes('ice cream machine');

    if (isSpecial) return;

    seen.add(nmLower);
    let displayCat = 'Food';
    if (isDessert) displayCat = 'Dessert';
    else if (isDrink) displayCat = 'Drink';

    pool.push({
      name: nm,
      category: displayCat
    });
  });

  pool.sort((a, b) => a.name.localeCompare(b.name));

  const filtered = _eimMenuPickerFilter
    ? pool.filter(p => p.name.toLowerCase().includes(_eimMenuPickerFilter) || p.category.toLowerCase().includes(_eimMenuPickerFilter))
    : pool;

  if (filtered.length === 0) {
    container.innerHTML = '<div style="text-align:center; padding:24px; color:var(--text-dim); font-size:12px;">No matching menu items found.</div>';
    return;
  }

  const categoryColors = {
    Food: { bg: 'rgba(234, 179, 8, 0.15)', text: '#eab308', border: 'rgba(234, 179, 8, 0.3)' },
    Dessert: { bg: 'rgba(236, 72, 153, 0.15)', text: '#ec4899', border: 'rgba(236, 72, 153, 0.3)' },
    Drink: { bg: 'rgba(59, 130, 246, 0.15)', text: '#60a5fa', border: 'rgba(59, 130, 246, 0.3)' }
  };

  container.innerHTML = filtered.map(item => {
    const isSelected = _eimMenuPickerSelected.toLowerCase() === item.name.toLowerCase();
    const col = categoryColors[item.category] || categoryColors.Food;
    const safeName = item.name.replace(/'/g, "\\'").replace(/"/g, '&quot;');
    return `
      <div onclick="selectEimMenuPickerItem('${safeName}')"
        style="display:flex; align-items:center; justify-content:space-between; padding:10px 14px; border-radius:8px; border:1px solid ${isSelected ? 'var(--gold)' : 'var(--border)'}; background:${isSelected ? 'rgba(196,154,60,0.12)' : 'rgba(255,255,255,0.02)'}; cursor:pointer; transition:all 0.15s ease;">
        <div style="display:flex; align-items:center; gap:12px;">
          <input type="checkbox" ${isSelected ? 'checked' : ''} onclick="event.stopPropagation(); selectEimMenuPickerItem('${safeName}')" style="cursor:pointer; width:16px; height:16px; accent-color:var(--gold);" />
          <span style="font-size:13px; font-weight:600; color:var(--cream);">${item.name}</span>
        </div>
        <span style="font-size:10px; font-weight:700; text-transform:uppercase; letter-spacing:0.5px; padding:3px 8px; border-radius:4px; background:${col.bg}; color:${col.text}; border:1px solid ${col.border};">${item.category}</span>
      </div>
    `;
  }).join('');
}
window.renderEimMenuPickerList = renderEimMenuPickerList;

window.updateEIMAddId = updateEIMAddId;
window.toggleBatchField = toggleBatchField;

// ===== EDIT EQUIPMENT =====
function openEditEquipmentModal(idx) {
  const a = EIM_ASSETS[idx];
  if (!a) return;

  // Intercept edit clicks for split batch children and open the split modal instead
  if (a.parent_asset_id && (a.asset_id || a.id || '').includes('SPLIT-BATCH')) {
    openSplitModal(a.parent_asset_id);
    return;
  }

  document.getElementById('eim-edit-idx').value = idx;
  document.getElementById('eim-edit-id').value = a.id;
  document.getElementById('eim-edit-name').value = a.name;
  const catSelect = document.getElementById('eim-edit-category');
  if (catSelect && a.category) {
    let exists = false;
    for (let i = 0; i < catSelect.options.length; i++) {
      if (catSelect.options[i].value === a.category) { exists = true; break; }
    }
    if (!exists) {
      const opt = document.createElement('option');
      opt.value = a.category;
      opt.textContent = a.category;
      catSelect.appendChild(opt);
    }
    catSelect.value = a.category;
  }
  document.getElementById('eim-edit-type').value = a.type;
  document.getElementById('eim-edit-qty').value = a.quantity;
  const trackSel = document.getElementById('eim-edit-tracking');
  if (trackSel) {
    trackSel.value = a.trackingMode || a.tracking_mode || 'quantity';
    trackSel.onchange = function() {
      _updateSplitButtonVisibility(a);
    };
  }
  if (a.unitType && a.unitType.startsWith('every_')) {
    document.getElementById('eim-edit-unit').value = 'every_n';
    document.getElementById('eim-edit-unit-n').style.display = 'block';
    document.getElementById('eim-edit-unit-n').value = a.unitType.split('_')[1] || '1';
  } else {
    document.getElementById('eim-edit-unit').value = a.unitType || 'pcs';
    document.getElementById('eim-edit-unit-n').style.display = 'none';
  }

  const limitEl = document.getElementById('eim-edit-limit');
  if (limitEl) {
    limitEl.value = a.limit || 0;
  }
  
  const bufferEl = document.getElementById('eim-edit-buffer');
  if (bufferEl) {
    bufferEl.value = a.extra_buffer || 0;
    bufferEl.disabled = !!a.parent_asset_id; // locked for batches
  }

  // Consumable classification dropdown
  const consumableEl = document.getElementById('eim-edit-consumable');
  if (consumableEl) {
    consumableEl.value = (a.consumable === true || a.consumable === 'true') ? 'true' : 'false';
  }

  const fragilityEl = document.getElementById('eim-edit-fragility');
  if (fragilityEl) {
    fragilityEl.value = a.fragility || 'non-fragile';
  }

  // Set Rule fields
  const rType = document.getElementById('eim-edit-rule-type');
  const rOther = document.getElementById('eim-edit-rule-other');
  const rRatio = document.getElementById('eim-edit-rule-ratio');
  const rMenuWrap = document.getElementById('eim-edit-rule-menu-item-wrap');
  const rMenuN = document.getElementById('eim-edit-rule-menu-n');
  const rMenuItem = document.getElementById('eim-edit-rule-menu-item');

  if (rType) {
    const knownTypes = ['none', 'per_pax', 'per_table', 'per_menu_item', 'fixed', 'every_vip'];
    const perNItemMatch = a.allocationRule && a.allocationRule.match(/^per_(\d+)_per_item:(.+)$/i);
    const perNPaxMatch = a.allocationRule && a.allocationRule.match(/^per_(\d+)_pax$/i);
    const perEquipMatch = a.allocationRule && a.allocationRule.match(/^every_certain_equipment:(.+)$/i);
    const rEquipWrap = document.getElementById('eim-edit-rule-equipment-wrap');
    if (perEquipMatch) {
      rType.value = 'every_certain_equipment';
      if (rOther) { rOther.style.display = 'none'; rOther.value = ''; }
      if (rMenuWrap) { rMenuWrap.style.display = 'none'; }
      if (rMenuN) rMenuN.value = '';
      if (rMenuItem) rMenuItem.value = '';
      if (rEquipWrap) rEquipWrap.style.display = 'block';
      populateLinkedEquipmentDropdown('eim-edit-rule-linked-equipment', perEquipMatch[1], a.asset_id || a.id || a.supabaseId);
    } else if (perNItemMatch) {
      rType.value = 'other_per_menu_item';
      if (rOther) { rOther.style.display = 'none'; rOther.value = ''; }
      if (rMenuWrap) rMenuWrap.style.display = '';
      if (rMenuN) rMenuN.value = perNItemMatch[1];
      if (rMenuItem) rMenuItem.value = perNItemMatch[2];
      if (rEquipWrap) rEquipWrap.style.display = 'none';
    } else if (perNPaxMatch) {
      if (rEquipWrap) rEquipWrap.style.display = 'none';
      if (rMenuWrap) { rMenuWrap.style.display = 'none'; }
      if (rMenuN) rMenuN.value = '';
      if (rMenuItem) rMenuItem.value = '';
      if (parseInt(perNPaxMatch[1]) === 1) {
        rType.value = 'per_pax';
        if (rOther) { rOther.style.display = 'none'; rOther.value = ''; }
      } else {
        rType.value = 'Other';
        if (rOther) { rOther.style.display = 'block'; rOther.value = perNPaxMatch[1]; }
      }
    } else if (knownTypes.includes(a.allocationRule)) {
      rType.value = a.allocationRule;
      if (rOther) { rOther.style.display = 'none'; rOther.value = ''; }
      if (rMenuWrap) { rMenuWrap.style.display = 'none'; }
      if (rEquipWrap) { rEquipWrap.style.display = 'none'; }
      if (rMenuN) rMenuN.value = '';
      if (rMenuItem) rMenuItem.value = '';
    } else if (a.allocationRule && a.allocationRule.startsWith('Other:')) {
      // Legacy format fallback
      rType.value = 'Other';
      if (rOther) { rOther.style.display = 'block'; rOther.value = a.allocationRule.split(':')[1]; }
      if (rMenuWrap) { rMenuWrap.style.display = 'none'; }
      if (rMenuN) rMenuN.value = '';
      if (rMenuItem) rMenuItem.value = '';
    } else {
      rType.value = 'none';
      if (rOther) { rOther.style.display = 'none'; rOther.value = ''; }
      if (rMenuWrap) { rMenuWrap.style.display = 'none'; }
      if (rMenuN) rMenuN.value = '';
      if (rMenuItem) rMenuItem.value = '';
    }
  }
  if (rRatio) {
    rRatio.value = a.pricingRule || 'per_unit';
  }

  document.getElementById('eim-edit-cost').value = a.unitCost;
  const _scEditEl = document.getElementById('eim-edit-shopping-cost'); if (_scEditEl) _scEditEl.value = a.shoppingCost || 0;
  const sUnit = a.shoppingUnitType || a.shopping_unit_type || a.unitType || 'pcs';
  const editShopUnitEl = document.getElementById('eim-edit-shopping-unit');
  const editShopUnitNEl = document.getElementById('eim-edit-shopping-unit-n');
  if (editShopUnitEl) {
    if (sUnit.startsWith('every_')) {
      editShopUnitEl.value = 'every_n';
      if (editShopUnitNEl) {
        editShopUnitNEl.style.display = 'block';
        editShopUnitNEl.value = sUnit.split('_')[1] || '1';
        editShopUnitNEl.disabled = false;
      }
    } else {
      editShopUnitEl.value = sUnit === 'sets' ? 'sets' : 'pcs';
      if (editShopUnitNEl) {
        editShopUnitNEl.style.display = 'none';
        editShopUnitNEl.value = '';
      }
    }
    // Shopping unit type is always customizable even for child batches
    editShopUnitEl.disabled = false;
    editShopUnitEl.style.opacity = '1';
    editShopUnitEl.style.background = '';
  }
  document.getElementById('eim-edit-supplier').value = a.supplier || a.sourceLocation || '';
  const _pdEditEl = document.getElementById('eim-edit-purchase-date');
  if (_pdEditEl) {
    _pdEditEl.max = new Date().toLocaleDateString('en-CA');
    _pdEditEl.value = a.addedDate || '';
  }
  const _ptEditEl = document.getElementById('eim-edit-time-purchased');
  if (_ptEditEl) {
    _ptEditEl.value = a.timePurchased || a.time_purchased || (a.purchase_history && a.purchase_history[0] && a.purchase_history[0].time) || '';
  }

  document.getElementById('eim-edit-notes').value = a.notes || '';

  const imgUrl = a.image_url || '';
  if (imgUrl) {
    document.getElementById('ee-img-url').value = imgUrl;
    _showImagePreview('ee-img-preview', 'ee-img-preview-wrap', 'ee-img-drop-zone', imgUrl);
  } else {
    _clearImagePreview('ee-img-preview-wrap', 'ee-img-drop-zone', 'ee-img-url');
  }
  // Lock fields if child batch (unit type is fixed, but shopping unit type remains editable)
  const isChildBatch = !!a.parent_asset_id;
  const lockFields = [
    'eim-edit-name', 'eim-edit-category', 'eim-edit-type', 
    'eim-edit-rule-type', 'eim-edit-rule-other', 'eim-edit-rule-ratio',
    'eim-edit-fragility', 'eim-edit-consumable', 'eim-edit-cost', 'ee-img-file-input', 'eim-edit-limit',
    'eim-edit-unit', 'eim-edit-unit-n'
  ];
  lockFields.forEach(id => {
    const el = document.getElementById(id);
    if (el) {
      el.disabled = isChildBatch;
      if (isChildBatch) {
        el.style.opacity = '0.6';
        el.style.background = 'var(--bg3)';
        el.title = 'This property is inherited from the parent equipment.';
      } else {
        el.style.opacity = '1';
        el.style.background = '';
        el.title = '';
      }
    }
  });



  document.getElementById('eim-edit-overlay').classList.add('on');
  document.getElementById('eim-edit-modal').classList.add('open');

  // Show/configure the Split button
  if (typeof _updateSplitButtonVisibility === 'function') _updateSplitButtonVisibility(a);
}

function closeEditEquipmentModal() {
  document.getElementById('eim-edit-overlay').classList.remove('on');
  document.getElementById('eim-edit-modal').classList.remove('open');
}

async function submitEditEquipment() {
  const idxEl = document.getElementById('eim-edit-idx');
  const idx = idxEl ? parseInt(idxEl.value) : -1;
  if (isNaN(idx) || idx < 0 || !EIM_ASSETS[idx]) return;
  const a = EIM_ASSETS[idx];

  const name = document.getElementById('eim-edit-name') ? document.getElementById('eim-edit-name').value.trim() : a.name;
  const category = document.getElementById('eim-edit-category') ? document.getElementById('eim-edit-category').value : a.category;
  const type = document.getElementById('eim-edit-type') ? document.getElementById('eim-edit-type').value.trim() : a.type;
  const quantity = document.getElementById('eim-edit-qty') ? (parseInt(document.getElementById('eim-edit-qty').value) || a.quantity) : a.quantity;
  let unitType = document.getElementById('eim-edit-unit') ? document.getElementById('eim-edit-unit').value : (a.unitType || 'pcs');
  if (unitType === 'every_n') {
    let n = document.getElementById('eim-edit-unit-n')?.value || '1';
    unitType = 'every_' + n;
  }
  const unitCost = document.getElementById('eim-edit-cost') ? (parseFloat(document.getElementById('eim-edit-cost').value) || 0) : (a.unitCost || 0);
  const shoppingCostEdit = document.getElementById('eim-edit-shopping-cost') ? (parseFloat(document.getElementById('eim-edit-shopping-cost').value) || 0) : (a.shoppingCost || 0);
  let shoppingUnitEdit = document.getElementById('eim-edit-shopping-unit') ? document.getElementById('eim-edit-shopping-unit').value : 'pcs';
  if (shoppingUnitEdit === 'every_n') {
    let n = document.getElementById('eim-edit-shopping-unit-n')?.value || '1';
    shoppingUnitEdit = 'every_' + n;
  }
  const supplierEl = document.getElementById('eim-edit-supplier');
  const supplier = supplierEl ? (supplierEl.value.trim() || null) : (a.supplier || null);
  const sourceEl = document.getElementById('eim-edit-source');
  const sourceLocation = sourceEl ? (sourceEl.value.trim() || null) : supplier;
  const notesEl = document.getElementById('eim-edit-notes');
  const notes = notesEl ? notesEl.value.trim() : (a.notes || '');

  let allocationRule = document.getElementById('eim-edit-rule-type') ? document.getElementById('eim-edit-rule-type').value : 'none';
  if (allocationRule === 'Other') {
    const n = parseInt(document.getElementById('eim-edit-rule-other')?.value) || 1;
    allocationRule = `per_${n}_pax`;
  } else if (allocationRule === 'other_per_menu_item') {
    const n = parseInt(document.getElementById('eim-edit-rule-menu-n')?.value) || 1;
    const itemVal = (document.getElementById('eim-edit-rule-menu-item')?.value || '').trim();
    if (!itemVal) {
      alert('Please select a menu item for the allocation rule.');
      return;
    }
    allocationRule = `per_${n}_per_item:${itemVal}`;
  } else if (allocationRule === 'every_certain_equipment') {
    const linkedEq = (document.getElementById('eim-edit-rule-linked-equipment')?.value || '').trim();
    if (!linkedEq) {
      alert('Please select a main equipment for the allocation rule.');
      return;
    }
    allocationRule = `every_certain_equipment:${linkedEq}`;
  }
  const pricingRule = document.getElementById('eim-edit-rule-ratio') ? document.getElementById('eim-edit-rule-ratio').value : 'per_unit';


  const purchaseDateEdit = (() => { const el = document.getElementById('eim-edit-purchase-date'); return el && el.value ? el.value : null; })();
  const limitEdit = document.getElementById('eim-edit-limit') ? (parseInt(document.getElementById('eim-edit-limit').value) || 0) : (a.limit || 0);
  const bufferEdit = document.getElementById('eim-edit-buffer') ? (parseInt(document.getElementById('eim-edit-buffer').value) || 0) : (a.extra_buffer || 0);
  const consumableEdit = document.getElementById('eim-edit-consumable') ? (document.getElementById('eim-edit-consumable').value === 'true') : (a.consumable === true || a.consumable === 'true');

  // Update Supabase
  const sb = window.supabaseClient;
  if (!sb) return alert('Database connection not available.');

  const btn = document.getElementById('btn-submit-eim-edit');
  if (btn) { btn.disabled = true; btn.textContent = 'Saving...'; }

  try {
    const cleanNotes = (notes || '').replace(/\s*\[SHOPPING_UNIT:[^\]]+\]/gi, '').trim();
    const dbDescription = cleanNotes || '';

    const trackingEdit = document.getElementById('eim-edit-tracking')?.value || a.trackingMode || 'quantity';
    const purchaseTimeEdit = (() => { const el = document.getElementById('eim-edit-time-purchased'); return el && el.value ? el.value : null; })();
    const updatePayload = {
      tracking_mode: trackingEdit,
      name: name,
      category: category,
      type: type,
      total_qty: quantity,
      value: unitCost,
      shopping_cost: shoppingCostEdit,
      shopping_unit_type: shoppingUnitEdit,
      supplier: supplier,
      source_location: supplier,
      description: dbDescription,
      fragility: document.getElementById('eim-edit-fragility')?.value || 'non-fragile',
      allocation_type: allocationRule,
      pricing_type: pricingRule,
      image_url: document.getElementById('ee-img-url').value.trim() || null,
      unit_type: unitType,
      purchase_date: purchaseDateEdit,
      time_purchased: purchaseTimeEdit,
      limit: limitEdit,
      extra_buffer: bufferEdit,
      consumable: consumableEdit
    };

    let { error } = await sb.from('equipment_inventory').update(updatePayload).eq('asset_id', a.id);
    if (error && (error.message || '').includes('time_purchased')) {
      console.warn('time_purchased column not found in equipment_inventory, retrying update without it...');
      delete updatePayload.time_purchased;
      const retryRes = await sb.from('equipment_inventory').update(updatePayload).eq('asset_id', a.id);
      error = retryRes.error;
    }
    if (error && (error.message || '').includes('shopping_unit_type')) {
      console.warn('shopping_unit_type column not found in equipment_inventory, retrying update without it...');
      delete updatePayload.shopping_unit_type;
      const retryRes = await sb.from('equipment_inventory').update(updatePayload).eq('asset_id', a.id);
      error = retryRes.error;
    }

    if (error) throw error;

    // Calculate exact field changes for transparent activity logging
    const changeList = [];
    if (name !== a.name) changeList.push(`Name: "${a.name}" → "${name}"`);
    if (category !== a.category) changeList.push(`Category: "${a.category}" → "${category}"`);
    if (type !== a.type) changeList.push(`Type: "${a.type}" → "${type}"`);
    if (quantity !== a.quantity) changeList.push(`Qty: ${a.quantity} → ${quantity}`);
    if (unitType !== (a.unitType || 'pcs')) changeList.push(`Unit: ${a.unitType || 'pcs'} → ${unitType}`);
    if (shoppingCostEdit !== (a.shoppingCost || 0)) changeList.push(`Shopping Cost: ₱${a.shoppingCost || 0} → ₱${shoppingCostEdit}`);
    if (shoppingUnitEdit !== (a.shoppingUnitType || a.shopping_unit_type || 'pcs')) changeList.push(`Shopping Unit: ${a.shoppingUnitType || a.shopping_unit_type || 'pcs'} → ${shoppingUnitEdit}`);
    if (unitCost !== (a.unitCost || 0)) changeList.push(`Value: ₱${a.unitCost || 0} → ₱${unitCost}`);
    if ((supplier || '') !== (a.supplier || '')) changeList.push(`Supplier: "${a.supplier || 'None'}" → "${supplier || 'None'}"`);
    if (limitEdit !== (a.limit || 0)) changeList.push(`Limit: ${a.limit || 0} → ${limitEdit}`);
    if (bufferEdit !== (a.extra_buffer || 0)) changeList.push(`Buffer: ${a.extra_buffer || 0} → ${bufferEdit}`);
    if (consumableEdit !== (a.consumable === true || a.consumable === 'true')) changeList.push(`Consumable: ${a.consumable ? 'Yes' : 'No'} → ${consumableEdit ? 'Yes' : 'No'}`);

    const editDetailsText = changeList.length > 0 
      ? `Updated "${name}": ${changeList.join('; ')}`
      : `Updated details for "${name}" (Qty: ${quantity}, Shopping Unit: ${shoppingUnitEdit}).`;

    // Update local cache
    a.name = name;
    a.category = category;
    a.type = type;
    a.quantity = quantity;
    a.limit = limitEdit;
    a.extra_buffer = bufferEdit;
    a.consumable = consumableEdit;
    a.unitType = unitType;
    a.shoppingUnitType = shoppingUnitEdit;
    a.shopping_unit_type = shoppingUnitEdit;
    a.trackingMode = trackingEdit;
    a.tracking_mode = trackingEdit;
    saveShoppingUnitMapping(a.id, shoppingUnitEdit);
    a.unitCost = unitCost;
    a.shoppingCost = shoppingCostEdit;
    a.supplier = supplier;
    a.rentalSupplier = supplier || a.rentalSupplier || 'General Rental Partner';
    a.image_url = document.getElementById('ee-img-url').value.trim() || null;
    a.sourceLocation = sourceLocation;
    a.notes = cleanNotes;
    a.addedDate = purchaseDateEdit || a.addedDate;
    a.timePurchased = purchaseTimeEdit || a.timePurchased;
    a.time_purchased = purchaseTimeEdit || a.time_purchased;
    a.allocationRule = allocationRule;
    a.pricingRule = pricingRule;
    a.fragility = document.getElementById('eim-edit-fragility')?.value || 'non-fragile';

    // --- Sync properties to all batch children ---
    const batchChildrenToSync = (EIM_ASSETS || []).filter(x => x.parent_asset_id === a.id);
    if (batchChildrenToSync.length > 0) {
      // Create individual updates for DB
      const updates = [];
      batchChildrenToSync.forEach(child => {
        let newChildName = name;
        const aid = (child.asset_id || child.id || '').toUpperCase();
        if (aid.includes('-SPLIT-BATCH-')) {
           newChildName = name + ' (SPLIT-BATCH-' + aid.split('-SPLIT-BATCH-').pop() + ')';
        } else if (aid.includes('-BATCH-')) {
           newChildName = name + ' (BATCH-' + aid.split('-BATCH-').pop() + ')';
        } else {
           newChildName = name + ' (Batch)';
        }

        updates.push(sb.from('equipment_inventory').update({
          name: newChildName,
          category: category,
          type: type,
          value: unitCost,
          limit: limitEdit,
          extra_buffer: bufferEdit,
          consumable: consumableEdit,
          fragility: document.getElementById('eim-edit-fragility')?.value || 'non-fragile',
          allocation_type: allocationRule,
          pricing_type: pricingRule,
          image_url: document.getElementById('ee-img-url').value.trim() || null
        }).eq('asset_id', child.asset_id || child.id));

        // Update local cache
        child.name = newChildName;
        child.category = category;
        child.type = type;
        child.unitCost = unitCost;
        child.limit = limitEdit;
        child.extra_buffer = bufferEdit;
        child.consumable = consumableEdit;
        child.fragility = document.getElementById('eim-edit-fragility')?.value || 'non-fragile';
        child.allocationRule = allocationRule;
        child.pricingRule = pricingRule;
        child.image_url = document.getElementById('ee-img-url').value.trim() || null;
      });

      Promise.all(updates).then(() => {
        console.log('Successfully synced all properties to child batches.');
      }).catch(err => {
        console.error('Failed to sync properties to batch children:', err);
      });
    }
    // -----------------------------------------------

    if (typeof recordEIMLog === 'function') {
      recordEIMLog({
        action: 'Edited Equipment',
        eqId: a.id,
        eqName: name,
        shoppingCost: shoppingCostEdit,
        shoppingUnitType: shoppingUnitEdit,
        supplier: supplier || a.supplier || 'Not specified',
        details: editDetailsText
      });
    }
    closeEditEquipmentModal();
    renderEIMTable();
    renderDashboard();
    try {
      new BroadcastChannel('eim_realtime_channel').postMessage({ type: 'EQUIPMENT_UPDATED', asset_id: a.id, supabaseId: a.supabaseId });
    } catch(e) {}

    // Also trigger reload of equipment list to ensure full sync
    if (typeof loadEIMData === 'function') loadEIMData();

  } catch (err) {
    console.error('Error updating equipment:', err);
    alert('Failed to update equipment: ' + err.message);
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'Save Changes'; }
  }
}

window.openEditEquipmentModal = openEditEquipmentModal;
window.closeEditEquipmentModal = closeEditEquipmentModal;
window.submitEditEquipment = submitEditEquipment;

// ===== DELETE EQUIPMENT =====
let _pendingDelete = null;

async function toggleDisableEquipment(idx) {
  const a = EIM_ASSETS[idx];
  if (!a) return;

  // If we are ENABLING (currently is_disabled === true), skip the usage check and just enable.
  if (a.is_disabled) {
    a.is_disabled = false;
    if (window.supabaseClient || window.supabase) {
      const sb = window.supabaseClient || window.supabase;
      try {
        await sb.from('equipment_inventory').update({ is_disabled: false }).eq('id', a.supabaseId || a.id);
        recordEIMLog('Equipment Enabled', a.id + ' status changed to Active');
      } catch (e) { console.error('Failed to update status', e); }
    }
    renderEIMTable();
    return;
  }

  // === We are DISABLING : check if equipment is part of any event setup or premade package ===
  const eqName = (a.name || '').toLowerCase().trim();
  const eqId   = (a.id || '').toUpperCase().trim();

  // Check event setups (equipment_items is a JSON array of name strings or objects)
  const matchingSetups = (window.sbEventSetups || []).filter(s => {
    let items = [];
    try { items = typeof s.equipment_items === 'string' ? JSON.parse(s.equipment_items) : (s.equipment_items || []); } catch(e) {}
    return items.some(i => {
      const iName = (typeof i === 'string' ? i : (i.name || '')).toLowerCase().trim();
      return iName === eqName || iName.includes(eqName) || eqName.includes(iName);
    });
  });

  // Check premade packages via sbPremadePackageItems (item_name field)
  const matchingPackages = (window.sbPremadePackages || []).filter(pkg => {
    const pkgItems = (window.sbPremadePackageItems || []).filter(i => i.package_id === pkg.id);
    return pkgItems.some(i => {
      const iName = (i.item_name || '').toLowerCase().trim();
      return iName === eqName || iName.includes(eqName) || eqName.includes(iName);
    });
  });

  const inSetup   = matchingSetups.length > 0;
  const inPackage = matchingPackages.length > 0;

  // Check confirmed (active) reservations that include this equipment by name
  const activeStatuses = ['Confirmed', 'Approved', 'Ongoing', 'Pending', 'Awaiting Payment'];
  const matchingReservations = (window.RESERVATIONS || RESERVATIONS || []).filter(r => {
    if (!activeStatuses.includes(r.status)) return false;
    const items = (r.packageItems || r.items || []).map(i => (typeof i === 'string' ? i : (i.name || '')).toLowerCase().trim());
    const hasItem = items.some(n => n === eqName || n.includes(eqName) || eqName.includes(n));
    // Also check equipmentManifest
    const manifest = r.equipmentManifest || [];
    const inManifest = manifest.some(m => {
      const mName = (m.name || '').toLowerCase().trim();
      const mId   = (m.assetId || '').toUpperCase().trim();
      return mName === eqName || mName.includes(eqName) || eqName.includes(mName) || mId === eqId;
    });
    return hasItem || inManifest;
  });
  const inReservation = matchingReservations.length > 0;

  if (inSetup || inPackage || inReservation) {
    // Build context parts for the message
    let contextParts = [];
    if (inSetup && inPackage && inReservation)      contextParts = ['an event setup', 'a premade package', 'a confirmed reservation'];
    else if (inSetup && inPackage)                  contextParts = ['an event setup', 'a premade package'];
    else if (inSetup && inReservation)              contextParts = ['an event setup', 'a confirmed reservation'];
    else if (inPackage && inReservation)            contextParts = ['a premade package', 'a confirmed reservation'];
    else if (inSetup)                               contextParts = ['an event setup'];
    else if (inPackage)                             contextParts = ['a premade package'];
    else                                            contextParts = ['a confirmed reservation'];

    const msg = document.getElementById('eq-disable-blocked-message');
    const sub = document.getElementById('eq-disable-blocked-subtitle');
    const lists = document.getElementById('eq-disable-blocked-lists');

    if (sub)  sub.textContent = a.name + ' (' + a.id + ')';
    const lastPart = contextParts.length > 1 ? contextParts.slice(0,-1).join(', ') + ' and ' + contextParts[contextParts.length-1] : contextParts[0];
    if (msg)  msg.innerHTML = '<strong>"' + a.name + '"</strong> cannot be disabled because it is currently part of '
      + lastPart + '. Remove it from the following before disabling:';

    let listsHtml = '';
    if (inSetup) {
      listsHtml += `
        <div>
          <div style="font-size:11px; font-weight:800; color:var(--gold); text-transform:uppercase; letter-spacing:0.8px; margin-bottom:6px;">Event Setups</div>
          <div style="display:flex; flex-direction:column; gap:5px;">
            ${matchingSetups.map(s => `
              <div style="display:flex; align-items:center; gap:10px; padding:8px 12px; background:rgba(196,154,60,0.07); border:1px solid rgba(196,154,60,0.18); border-radius:8px;">
                <div style="width:7px; height:7px; border-radius:50%; background:var(--gold); flex-shrink:0;"></div>
                <span style="font-size:13px; font-weight:600; color:var(--cream);">${s.name || 'Unnamed Setup'}</span>
              </div>`).join('')}
          </div>
        </div>`;
    }
    if (inPackage) {
      listsHtml += `
        <div>
          <div style="font-size:11px; font-weight:800; color:var(--gold); text-transform:uppercase; letter-spacing:0.8px; margin-bottom:6px;">Premade Packages</div>
          <div style="display:flex; flex-direction:column; gap:5px;">
            ${matchingPackages.map(p => `
              <div style="display:flex; align-items:center; gap:10px; padding:8px 12px; background:rgba(196,154,60,0.07); border:1px solid rgba(196,154,60,0.18); border-radius:8px;">
                <div style="width:7px; height:7px; border-radius:50%; background:var(--gold); flex-shrink:0;"></div>
                <span style="font-size:13px; font-weight:600; color:var(--cream);">${p.name || 'Unnamed Package'}</span>
              </div>`).join('')}
          </div>
        </div>`;
    }
    if (inReservation) {
      listsHtml += `
        <div>
          <div style="font-size:11px; font-weight:800; color:#ef4444; text-transform:uppercase; letter-spacing:0.8px; margin-bottom:6px;">Active Reservations</div>
          <div style="display:flex; flex-direction:column; gap:5px;">
            ${matchingReservations.map(r => {
              const resLabel = r.packageName || r.name || r.client || 'Reservation';
              const resDate  = r.date ? (' &mdash; ' + r.date) : '';
              const resStat  = r.status ? (' <span style="font-size:10px; color:var(--text-dim); font-weight:400;">[' + r.status + ']</span>') : '';
              return `<div style="display:flex; align-items:flex-start; gap:10px; padding:9px 12px; background:rgba(239,68,68,0.06); border:1px solid rgba(239,68,68,0.22); border-radius:8px;">
                <div style="width:7px; height:7px; border-radius:50%; background:#ef4444; flex-shrink:0; margin-top:4px;"></div>
                <div>
                  <div style="font-size:13px; font-weight:600; color:var(--cream);">${resLabel}${resStat}</div>
                  <div style="font-size:11px; color:var(--text-dim); margin-top:2px;">Disabling this equipment may cause issues for the duration of this reservation&rsquo;s process${resDate}.</div>
                </div>
              </div>`;
            }).join('')}
          </div>
        </div>`;
    }
    if (lists) lists.innerHTML = listsHtml;

    // Show modal
    const overlay = document.getElementById('eq-disable-blocked-overlay');
    const modal   = document.getElementById('eq-disable-blocked-modal');
    if (overlay) overlay.classList.add('on');
    if (modal)   modal.classList.add('open');
    return; // Abort disable
  }

  // === No conflicts : proceed with disable ===
  a.is_disabled = true;
  if (window.supabaseClient || window.supabase) {
    const sb = window.supabaseClient || window.supabase;
    try {
      await sb.from('equipment_inventory').update({ is_disabled: true }).eq('id', a.supabaseId || a.id);
      recordEIMLog('Equipment Disabled', a.id + ' status changed to Disabled');
    } catch (e) { console.error('Failed to update status', e); }
  }
  renderEIMTable();
}
window.toggleDisableEquipment = toggleDisableEquipment;

function closeEqDisableBlockedPanel() {
  const overlay = document.getElementById('eq-disable-blocked-overlay');
  const modal   = document.getElementById('eq-disable-blocked-modal');
  if (overlay) overlay.classList.remove('on');
  if (modal)   modal.classList.remove('open');
}
window.closeEqDisableBlockedPanel = closeEqDisableBlockedPanel;


function confirmDeleteEquipment(idx) {
  const a = EIM_ASSETS[idx];
  if (!a) return;
  _pendingDelete = { type: 'equipment', idx };
  document.getElementById('del-message').textContent =
    `Are you sure you want to remove "${a.name}" (${a.id}) from the inventory? This action cannot be undone.`;
  document.getElementById('del-confirm-btn').onclick = () => {
    EIM_ASSETS.splice(idx, 1);
    closeDeleteModal();
    renderEIMTable();
  };
  document.getElementById('del-overlay').classList.add('on');
  document.getElementById('del-modal').classList.add('open');
}

function closeDeleteModal() {
  document.getElementById('del-overlay').classList.remove('on');
  document.getElementById('del-modal').classList.remove('open');
  _pendingDelete = null;
}

window.confirmDeleteEquipment = confirmDeleteEquipment;
window.closeDeleteModal = closeDeleteModal;

