// ---- Called by saveAllocAssignment to also save rental items ----
async function saveRentalAllocItems(ev, batchName) {
  const resId = ev ? ev.id : null;
  if (!resId) return;
  const order = window._rentalOrderCache[resId];
  if (!order || order.status === 'draft') return; // only save if at least request_sent (they created an order)

  const sb = window.supabaseClient;
  if (!sb) return;
  const evLabel = ev.packageName || ev.client || ev.name || ev.id;

  // Clear old rental rows for this reservation before inserting
  try {
    await sb.from('allocation_history').delete().eq('reservation_id', resId).eq('is_rental', true);
  } catch (e) { console.warn('[RentalAlloc] Failed to clear old rentals:', e); }

  for (const item of (order.items || [])) {
    const qty = parseInt(item.qty_needed, 10) || 0;
    if (qty <= 0) continue;
    try {
      const assetMatch = typeof window.findAssetForRule === 'function' ? window.findAssetForRule({ name: item.name }) : null;
      const { error: rErr } = await sb.from('allocation_history').insert({
        equipment_id: assetMatch ? (assetMatch.supabaseId || null) : null,
        asset_id: assetMatch ? (assetMatch.asset_id || assetMatch.id || null) : null,
        equipment_name: item.name,
        allocation_batch: batchName,
        reservation_id: resId,
        reservation_name: evLabel,
        allocation_date: ev.date || ev.eventDate || null,
        allocated_qty: qty,
        unit_type: item.unit_type || (assetMatch ? (assetMatch.unit_type || assetMatch.unitType) : 'pcs'),
        is_rental: true
      });
      if (rErr) console.warn('[RentalAlloc] Insert failed:', rErr);
    } catch (e) { console.warn('[RentalAlloc] Insert failed:', e); }
  }
}

