window.deleteRentalOrderForRes = async function (resId) {
  if (!confirm("Are you sure you want to cancel and delete this rental order entirely?")) return;
  const sb = window.supabaseClient;
  if (!sb) { showToast('Database connection missing', 'error'); return; }

  const btn = document.activeElement;
  if (btn && btn.tagName === 'BUTTON') { btn.disabled = true; btn.textContent = 'Cancelling...'; }

  try {
    const { error: err1 } = await sb.from('rental_orders').delete().eq('reservation_id', resId);
    if (err1) throw err1;

    // Also delete any allocation history rows where is_rental = true for this resId
    await sb.from('allocation_history').delete().eq('reservation_id', resId).eq('is_rental', true);

    // Clear cache
    window._rentalOrderCache[resId] = undefined;
    setStagedShortages(resId, []);

    showToast("Rental order deleted successfully.");

    // Refresh manifest to reflect missing rentals
    if (typeof generateAllocationManifest === 'function') {
      await generateAllocationManifest();
    }

    // Re-render
    renderRentalHub();
  } catch (err) {
    console.error('[RentalHub] Delete failed:', err);
    showToast('Failed to delete rental order: ' + err.message, 'error');
    if (btn && btn.tagName === 'BUTTON') { btn.disabled = false; btn.textContent = 'Cancel Order'; }
  }
};

