window.adminChatInitialized = window.adminChatInitialized || false;

async function initAdminChat() {
  if (window.adminChatInitialized) return;
  window.adminChatInitialized = true;
  const sb = window.supabaseClient;
  if (!sb) return;

  const loadInbox = async () => {
    try {
      const { data: usersData, error: usersErr } = await sb.from('users').select('id, name, email, role').eq('role', 'customer');
      if (usersErr) throw usersErr;
      const { data: msgData, error: msgErr } = await sb.from('support_messages').select('*').order('created_at', { ascending: false });
      if (msgErr) throw msgErr;

      const convoMap = new Map();
      (usersData || []).forEach(u => {
        convoMap.set(u.id, {
          uid: u.id, name: u.name || 'Customer', email: u.email || '',
          lastMsg: 'No messages yet', time: 0, hasNew: false
        });
      });

      (msgData || []).forEach(msg => {
        const cId = msg.customer_id;
        if (convoMap.has(cId)) {
          const convo = convoMap.get(cId);
          if (convo.time === 0) {
            convo.lastMsg = msg.message;
            convo.time = new Date(msg.created_at).getTime();
            convo.hasNew = msg.sender_role === 'customer';
          }
        }
      });

      const convos = Array.from(convoMap.values()).sort((a, b) => b.time - a.time);
      renderChatInbox(convos);
      const anyNew = convos.some(c => c.hasNew);
      const notif = document.getElementById('chat-notif');
      if (notif) notif.style.display = anyNew ? 'inline-block' : 'none';
    } catch (e) {
      console.error('Error loading admin chat inbox:', e);
    }
  };

  await loadInbox();
  
  if (!window.adminChatChannel) {
    window.adminChatChannel = sb.channel('admin_inbox')
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'support_messages' }, payload => {
        loadInbox();
      }).subscribe();
  }
}

function renderChatInbox(convos) {
  const list = document.getElementById('chat-inbox-list');
  if (!list) return;
  if (convos.length === 0) {
    list.innerHTML = `<div style="padding:20px; text-align:center; color:var(--text-dim); font-size:12px;">No customers found.</div>`;
    return;
  }
  list.innerHTML = convos.map(c => {
    const timeStr = c.time ? new Date(c.time).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '';
    return `
      <div class="inbox-item ${activeCustomerId === c.uid ? 'active' : ''} ${c.hasNew ? 'unread' : ''}" onclick="openConversation('${c.uid}', '${c.name.replace(/'/g, "\\'")}')">
        <div class="ii-name">${c.name} ${c.hasNew ? '<span class="ii-dot"></span>' : ''}</div>
        <div class="ii-msg">${c.lastMsg}</div>
        <div class="ii-time">${timeStr}</div>
      </div>`;
  }).join('');
}

window.filterAdminChatCustomers = function(val) {
  const q = (val || '').toLowerCase();
  const items = document.querySelectorAll('#chat-inbox-list .inbox-item');
  items.forEach(el => {
    const nameEl = el.querySelector('.ii-name');
    if (nameEl) {
      const name = nameEl.textContent.toLowerCase();
      el.style.display = name.includes(q) ? '' : 'none';
    }
  });
};

window.backToAdminChatList = function() {
  const listView = document.getElementById('admin-chat-list-view');
  if (listView) listView.style.display = 'flex';
  const convView = document.getElementById('admin-chat-conversation-view');
  if (convView) convView.style.display = 'none';
  activeCustomerId = null;
  if (window.chatPollInterval) {
    clearInterval(window.chatPollInterval);
    window.chatPollInterval = null;
  }
  if (window.activeChatChannel && window.supabaseClient) {
    window.supabaseClient.removeChannel(window.activeChatChannel);
    window.activeChatChannel = null;
  }
  document.querySelectorAll('#chat-inbox-list .inbox-item').forEach(el => el.classList.remove('active'));
};

async function openConversation(uid, name) {
  activeCustomerId = uid;
  document.querySelector('.ach-name').textContent = name;
  
  // Find active reservation for this customer (not pending, completed, or cancelled)
  const custObj = (window.CUSTOMERS || []).find(c => c.id === uid) || (window.USERS || []).find(u => u.id === uid) || {};
  const custEmail = (custObj.email || '').toLowerCase().trim();
  const activeRes = (window.RESERVATIONS || []).find(r => {
    const isThisCust = (r.userId === uid || r.user_id === uid || (custEmail && String(r.email || r.clientEmail || '').toLowerCase().trim() === custEmail) || (r.client && r.client.toLowerCase() === name.toLowerCase()));
    const s = String(r.status || '').toLowerCase().trim();
    return isThisCust && !['pending', 'completed', 'cancelled'].includes(s);
  });

  const achStatus = document.querySelector('.ach-status');
  if (achStatus) {
    if (activeRes) {
      const resName = activeRes.packageName || activeRes.package_name || activeRes.type || 'Event';
      const resDate = activeRes.date || '';
      const resStat = (activeRes.status || 'Active').toUpperCase();
      achStatus.textContent = `Active Event: ${resName}${resDate ? ' • ' + resDate : ''} [${resStat}]`;
      achStatus.style.color = 'var(--gold)';
    } else {
      achStatus.textContent = 'Direct Support Channel';
      achStatus.style.color = 'var(--text-dim)';
    }
  }

  document.getElementById('admin-chat-input-row').style.display = 'flex';
  
  const listView = document.getElementById('admin-chat-list-view');
  if (listView) listView.style.display = 'none';
  const convView = document.getElementById('admin-chat-conversation-view');
  if (convView) convView.style.display = 'flex';
  
  document.querySelectorAll('#chat-inbox-list .inbox-item').forEach(el => el.classList.remove('active'));
  const currentItem = Array.from(document.querySelectorAll('#chat-inbox-list .inbox-item')).find(el => {
    return el.querySelector('.ii-name') && el.querySelector('.ii-name').textContent.includes(name);
  });
  if (currentItem) currentItem.classList.add('active');

  const sb = window.supabaseClient;
  if (!sb) return;

  // Clear any existing polling interval
  if (window.chatPollInterval) {
    clearInterval(window.chatPollInterval);
    window.chatPollInterval = null;
  }
  if (window.activeChatChannel) {
    sb.removeChannel(window.activeChatChannel);
    window.activeChatChannel = null;
  }

  // Track the set of already-rendered message IDs to avoid duplicates
  const renderedIds = new Set();

  const appendMessage = (msg) => {
    if (renderedIds.has(msg.id)) return;
    renderedIds.add(msg.id);
    const box = document.getElementById('admin-chat-box');
    if (!box) return;
    const time = new Date(msg.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    const senderClass = msg.sender_role === 'admin' ? 'staff' : 'customer';
    const bubble = document.createElement('div');
    bubble.className = `chat-bubble ${senderClass}`;
    bubble.innerHTML = `<div class="chat-text">${escHtml(msg.message)}</div><div class="chat-time">${time}</div>`;
    box.appendChild(bubble);
    box.scrollTop = box.scrollHeight;
  };
  // Expose so sendAdminMsg can call it immediately after insert (avoids waiting for the next poll tick
  // and avoids the old duplication caused by optimistic render + poll re-fetching the same message)
  window._adminChatAppend = appendMessage;

  // Initial load
  const box = document.getElementById('admin-chat-box');
  if (box) box.innerHTML = '';
  try {
    const { data, error } = await sb.from('support_messages').select('*').eq('customer_id', uid).order('created_at', { ascending: true });
    if (!error) (data || []).forEach(msg => appendMessage(msg));
  } catch(e) { console.error('Error loading messages:', e); }

  // Poll every 4s for new messages (ensures real-time without needing Supabase Realtime enabled)
  window.chatPollInterval = setInterval(async () => {
    if (document.hidden) return;
    if (activeCustomerId !== uid) {
      clearInterval(window.chatPollInterval);
      return;
    }
    try {
      const { data } = await sb.from('support_messages').select('*').eq('customer_id', uid).order('created_at', { ascending: true });
      (data || []).forEach(msg => appendMessage(msg));
    } catch(e) {}
  }, 4000);

  // Also try Supabase Realtime as a fast-path bonus
  try {
    window.activeChatChannel = sb.channel(`chat_${uid}`)
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'support_messages', filter: `customer_id=eq.${uid}` }, payload => {
        if (payload.new) appendMessage(payload.new);
      }).subscribe();
  } catch(e) {}
}
window.openConversation = openConversation;

async function sendAdminMsg() {
  const input = document.getElementById('admin-chat-input');
  const text = input.value.trim();
  if (!text || !activeCustomerId) return;
  const sb = window.supabaseClient;
  if (!sb) return;

  // Clear the input immediately so the user gets instant feedback
  input.value = '';

  try {
    const { data: { session } } = await sb.auth.getSession();
    const sender_id = session?.user?.id || (typeof activeCustomerId !== 'undefined' ? activeCustomerId : null) || (typeof uid !== 'undefined' ? uid : null) || 'b2700254-57b5-4b91-bef2-d0228531fb95';

    await sb.from('support_messages').insert({
      customer_id: activeCustomerId,
      sender_role: 'admin',
      sender_id: sender_id,
      message: text
    });

    // Immediately reload messages so the sent message appears without waiting for the next poll tick
    // (the renderedIds set in openConversation deduplicates any concurrent poll)
    try {
      const uid = activeCustomerId;
      const { data } = await sb.from('support_messages').select('*').eq('customer_id', uid).order('created_at', { ascending: true });
      if (data) {
        // appendMessage is closure-scoped inside openConversation; trigger poll-style via a direct call
        const box = document.getElementById('admin-chat-box');
        if (box && window._adminChatAppend) {
          data.forEach(msg => window._adminChatAppend(msg));
        }
      }
    } catch(e) {}
  } catch (err) { console.error('Send error:', err); input.value = text; /* restore on error */ }
}
window.sendAdminMsg = sendAdminMsg;

