// Initialize with any saved logs from local storage (if running locally)
try {
  const localLogs = JSON.parse(localStorage.getItem('rc_saved_logs') || '[]');
  if (Array.isArray(localLogs)) {
    // Deduplicate by id before loading : only push entries not already present
    localLogs.forEach(l => {
      if (l && l.id && !ROUTINE_CHECK_LOGS.find(existing => existing.id === l.id)) {
        ROUTINE_CHECK_LOGS.push(l);
      }
    });
    // Write the deduplicated list back to localStorage to clean it up
    const deduped = [];
    const seen = new Set();
    localLogs.forEach(l => { if (l && l.id && !seen.has(l.id)) { seen.add(l.id); deduped.push(l); } });
    if (deduped.length !== localLogs.length) localStorage.setItem('rc_saved_logs', JSON.stringify(deduped));
  }
} catch (e) { }

let lastRoutineCheckDate = localStorage.getItem('rc_last_check_date') || null;
let activeRoutineCheck = null; // stores current in-progress check

// ----- HELPERS -----
function daysSinceLastCheck() {
  if (!lastRoutineCheckDate) {
    const submittedLogs = (ROUTINE_CHECK_LOGS || []).filter(l => l && l.date);
    if (submittedLogs.length) {
      const mostRecent = submittedLogs.reduce((a, b) => new Date(a.date) > new Date(b.date) ? a : b);
      lastRoutineCheckDate = mostRecent.date;
      try { localStorage.setItem('rc_last_check_date', lastRoutineCheckDate); } catch(e) {}
    }
  }
  if (!lastRoutineCheckDate) return 0;
  const dStr = String(lastRoutineCheckDate).includes('T') ? lastRoutineCheckDate : (lastRoutineCheckDate + 'T00:00:00');
  const dVal = new Date(dStr).getTime();
  if (isNaN(dVal)) return 0;
  const diff = Date.now() - dVal;
  return Math.max(0, Math.floor(diff / (1000 * 60 * 60 * 24)));
}
function isRoutineCheckOverdue() { return daysSinceLastCheck() >= 7; }

function getAssetAvailStatus(asset) {
  const hasFlag = EQUIPMENT_FLAGS.find(f => f.assetId === asset.id && f.status !== 'Resolved');
  if (hasFlag) return { label: 'Flagged', cls: 'critical', icon: '' };
  switch (asset.status) {
    case 'Active': return { label: 'Available', cls: 'confirmed', icon: '' };
    case 'In Use': return { label: 'Deployed', cls: 'pending', icon: '' };
    case 'Under Repair': return { label: 'Under Repair', cls: 'critical', icon: '' };
    case 'Retired': return { label: 'Retired', cls: 'cancelled', icon: '' };
    default: return { label: asset.status, cls: 'pending', icon: '' };
  }
}

// ----- DASHBOARD ALERT BANNER & SIDEBAR GLOW INDICATORS -----
function updateRoutineAlertBanner() {
  const alertEl = document.getElementById('dash-routine-alert');
  const badge = document.getElementById('routine-sidebar-badge');
  const overdue = typeof isRoutineCheckOverdue === 'function' ? isRoutineCheckOverdue() : false;
  if (badge) badge.style.display = overdue ? 'inline-flex' : 'none';
  if (alertEl) {
    alertEl.style.display = overdue ? 'block' : 'none';
    if (overdue) {
      const days = daysSinceLastCheck();
      const sub = document.getElementById('routine-alert-sub');
      if (sub) sub.textContent =
        `Last inspection was ${days} day${days !== 1 ? 's' : ''} ago : weekly check required. Click here to begin. →`;
    }
  }
  updateSidebarGlowIndicators();
  if (typeof renderAdminNotifications === 'function') {
    renderAdminNotifications();
  }
}

/**
 * Updates static red glow indicators on admin sidebar tabs:
 * 1. "Routine Checks" glows red when an inspection is overdue (> 7 days).
 * 2. "Execution Day" glows red when an event execution is scheduled for today.
 * Strictly static glow with NO animation or movement.
 */
function updateSidebarGlowIndicators() {
  // 1. Routine Checks tab
  const navRoutine = document.getElementById('nav-routine-check');
  if (navRoutine) {
    const overdue = typeof isRoutineCheckOverdue === 'function' ? isRoutineCheckOverdue() : false;
    if (overdue) {
      navRoutine.classList.add('static-red-glow');
    } else {
      navRoutine.classList.remove('static-red-glow');
    }
  }

  // 2. Execution Day tab
  const navExec = document.getElementById('nav-execution-day');
  if (navExec) {
    const d = new Date();
    const todayLocal = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    const todayIso = d.toISOString().split('T')[0];
    const resList = (Array.isArray(window.RESERVATIONS) && window.RESERVATIONS.length) ? window.RESERVATIONS : (Array.isArray(RESERVATIONS) ? RESERVATIONS : []);
    const hasTodayExec = resList.some(r => {
      const isToday = (r.date === todayLocal || r.date === todayIso);
      const isOngoing = String(r.status || '').toLowerCase() === 'on-going';
      const isNotCanceled = !['cancelled', 'canceled', 'rejected'].includes(String(r.status || '').toLowerCase());
      return (isToday || isOngoing) && isNotCanceled;
    });

    if (hasTodayExec) {
      navExec.classList.add('static-red-glow');
    } else {
      navExec.classList.remove('static-red-glow');
    }
  }
}
window.updateSidebarGlowIndicators = updateSidebarGlowIndicators;
if (!window._sidebarGlowIntervalSet) {
  window._sidebarGlowIntervalSet = true;
  document.addEventListener('DOMContentLoaded', () => {
    setTimeout(updateSidebarGlowIndicators, 1000);
    setTimeout(updateSidebarGlowIndicators, 3000);
  });
  setInterval(updateSidebarGlowIndicators, 10000);
}

