// EQUIPMENT CYCLE - GLOBAL STATE & DROPDOWN
// =====================================================================
let currentEqcReservationId = null;
let currentAllocEvent = null;

window.onEqcReservationChange = function () {
  const sel = document.getElementById('eqc-reservation-select');
  const newResId = sel ? sel.value : null;

  // Clear rental cache for old reservation so it re-fetches on demand
  if (currentEqcReservationId && currentEqcReservationId !== newResId) {
    // Keep cache but mark as stale by deleting : will re-fetch from Supabase
    delete window._rentalOrderCache[currentEqcReservationId];
  }
  currentEqcReservationId = newResId;

  // Sync typable input
  const input = document.getElementById('eqc-approved-input');
  if (input) {
    const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(r => r.id === newResId);
    if (res) {
      input.value = `${res.client || 'Client'} : ${res.packageName || res.type || 'Custom Package'} (${res.date || 'TBD'})`;
    } else {
      input.value = '';
    }
  }

  // Re-render the active eq-cycle tab
  const activeTab = document.querySelector('.eq-cycle-tab.active');
  if (activeTab) {
    if (activeTab.id === 'eqc-tab-allocation' && typeof renderAllocationSection === 'function') renderAllocationSection();
    if (activeTab.id === 'eqc-tab-scheduling' && typeof renderSchedulingSection === 'function') renderSchedulingSection();
    if (activeTab.id === 'eqc-tab-lifecycle' && typeof renderLifecycleSection === 'function') renderLifecycleSection();
    if (activeTab.id === 'eqc-tab-issues' && typeof renderEquipIssues === 'function') renderEquipIssues();
    if (activeTab.id === 'eqc-tab-rentals') renderRentalHub();
  }
};


window.populateEqcDropdown = function () {
  const sel = document.getElementById('eqc-reservation-select');
  const input = document.getElementById('eqc-approved-input');
  if (!sel) return;
  const confirmed = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).filter(function (r) {
    return ['confirmed', 'preparing', 'procurement', 'procuring', 'on-going'].includes(String(r.status || '').toLowerCase());
  });

  sel.innerHTML = '<option value="">Choose a confirmed reservation...</option>' +
    confirmed.map(r => {
      const evName = r.packageName || r.name || r.client || '(Unnamed)';
      const evDate = r.date || r.eventDate || '';
      const evPax = r.pax || r.guests || '';
      return `<option value="${r.id}">${evName}${evDate ? ' : ' + evDate : ''}${evPax ? ' (' + evPax + ' pax)' : ''}</option>`;
    }).join('');

  const activeRes = currentEqcReservationId ? confirmed.find(r => r.id === currentEqcReservationId) : null;
  if (activeRes) {
    sel.value = currentEqcReservationId;
    if (input) {
      input.value = `${activeRes.client || 'Client'} : ${activeRes.packageName || activeRes.type || 'Custom Package'} (${activeRes.date || 'TBD'})`;
    }
  } else {
    currentEqcReservationId = null;
    sel.value = "";
    if (input) {
      input.value = "";
    }
  }
};

function renderAllocationSection() {
  if (typeof populateEqcDropdown === 'function') populateEqcDropdown();

  if (currentEqcReservationId) {
    const still = RESERVATIONS.find(r => r.id === currentEqcReservationId);
    if (still) {
      currentAllocEvent = still;
      _showEquipmentNeededList(still);
      _hideAllocResults();
      cancelAllocMode(); // Reset any active allocation mode
      ['venue-tables', 'venue-chairs', 'venue-chafing', 'venue-dispensers',
        'venue-plates', 'venue-forks', 'venue-spoons', 'venue-knives', 'venue-glasses'].forEach(id => {
          const el = document.getElementById(id); if (el) el.value = 0;
        });
      const otherEl = document.getElementById('venue-other'); if (otherEl) otherEl.value = '';
      const si = document.getElementById('venue-save-status'); if (si) si.style.display = 'none';
      const ai = document.getElementById('venue-autofill-status'); if (ai) { ai.textContent = ''; ai.style.display = 'none'; }
      loadVenueEquipment(still.id);
      loadVenueEquipment(still.id);
      
      const isDecoActive = document.getElementById('alloc-subtab-decorations') && document.getElementById('alloc-subtab-decorations').classList.contains('active');
      if (isDecoActive && typeof renderDecorationAllocationPanel === 'function') {
        renderDecorationAllocationPanel();
      }

      // Auto-generate manifest after a short delay to allow async equipment fetch to complete
      setTimeout(() => { if (currentAllocEvent) generateAllocationManifest(); }, 800);
    } else {
      currentAllocEvent = null;
      _hideAllocResults();
      _clearEquipmentNeededList();
    }
  } else {
    currentAllocEvent = null;
    _hideAllocResults();
    _clearEquipmentNeededList();
  }
}

window.findAssetForRule = function (rule) {
  if (!EIM_ASSETS || !EIM_ASSETS.length) return null;
  let asset = null;

  // 1. Exact asset_id / supabaseId match (highest confidence)
  if (rule.assetId) {
    asset = EIM_ASSETS.find(a => a.id === rule.assetId || a.supabaseId === rule.assetId || a.asset_id === rule.assetId || a.batchTrackingId === rule.assetId);
    if (asset) return asset;
  }

  const rName = (rule.name || '').toLowerCase().trim();
  if (!rName) return null;

  // 2. Exact name match (case-insensitive) - MUST NOT BE A BATCH CHILD
  asset = EIM_ASSETS.find(a => !a.parent_asset_id && a.name && a.name.toLowerCase().trim() === rName);
  if (asset) return asset;

  // 3. Specific well-known fuzzy matches : only fire when both sides contain the key phrase
  //    (ordered from most-specific to least-specific to avoid cross-asset contamination)
  for (const a of EIM_ASSETS) {
    if (!a.name || a.parent_asset_id) continue;
    const aName = a.name.toLowerCase().trim();

    // Specific compound names must match each other fully before broad keywords
    if (rName.includes('chafing dish lid') && aName.includes('chafing dish lid')) return a;
    if (rName.includes('chafing dish') && !rName.includes('lid') && aName.includes('chafing dish') && !aName.includes('lid')) return a;
    if (rName.includes('food pan') && aName.includes('food pan')) return a;
    if (rName.includes('serving tray') && aName.includes('serving tray')) return a;
    if (rName.includes('serving fork') && aName.includes('serving fork')) return a;
    if (rName.includes('serving spoon') && aName.includes('serving spoon')) return a;
    if (rName.includes('serving tong') && aName.includes('serving tong')) return a;
    if (rName.includes('round banquet table') && aName.includes('round banquet table')) return a;
    if (rName.includes('tiffany') && aName.includes('tiffany')) return a;
    if (rName.includes('dinner plate') && aName.includes('dinner plate')) return a;
    if (rName.includes('dinner knife') && aName.includes('dinner knife')) return a;
    if (rName.includes('monoblock') && aName.includes('monoblock')) return a;
    if (rName.includes('dispenser') && aName.includes('dispenser')) return a;
    if (rName.includes('tablecloth') && (aName.includes('table cloth') || aName.includes('tablecloth'))) return a;
    if (rName.includes('speaker') && aName.includes('speaker')) return a;
    if (rName.includes('uplight') && (aName.includes('lighting') || aName.includes('uplight'))) return a;
  }

  // 4. Generic substring fallback (only when name is long enough to avoid false matches)
  for (const a of EIM_ASSETS) {
    if (!a.name || a.parent_asset_id) continue;
    const aName = a.name.toLowerCase().trim();
    if (rName.length > 5 && aName === rName) return a; // already handled above, safety
    if (rName.length > 7 && aName.includes(rName)) return a;
    if (aName.length > 7 && rName.includes(aName)) return a;
  }

  return null;
}

async function _showEquipmentNeededList(ev) {
  const container = document.getElementById('alloc-equipment-needed-list');
  if (!container) return;

  const pax = parseInt(ev.pax) || 0;
  container.innerHTML = '<div style="text-align:center; padding:20px; color:var(--text-dim); font-size:12px;">Loading equipment list...</div>';

  let riRows = [];
  try {
    const sb = window.supabaseClient;
    if (sb && typeof isUuidString === 'function' && isUuidString(ev.id)) {
      const { data, error } = await sb
        .from('reservation_items')
        .select('item_id, name, cat, is_free')
        .eq('reservation_id', ev.id);
      if (!error && data) riRows = data;
    }
  } catch (e) {
    console.warn('[EqcNeeded] reservation_items fetch failed:', e);
  }

  let menuItemCount = 1;
  if (riRows.length > 0) {
    menuItemCount = riRows.filter(r => r.cat === 'food').length || 1;
  } else if (ev.packageItems && typeof CAT !== 'undefined') {
    menuItemCount = ev.packageItems.map(n => CAT.find(c => c.name === (typeof n === 'string' ? n : n.name))).filter(i => i && i.cat === 'food').length || 1;
  }

  const _rawVip = ev.vipCount != null ? ev.vipCount : (ev.vip && typeof ev.vip === 'object' ? ev.vip.count : (ev.vip_count != null ? ev.vip_count : ev.vip));
  const hasVip = (parseInt(_rawVip) || 0) > 0 || !!(ev.hasVip || ev.isVip);

  function _allocLabel(rule) {
    if (typeof window.formatAllocationRuleLabel === 'function') {
      return window.formatAllocationRuleLabel(rule);
    }
    if (rule) {
      const mItem = (rule + '').match(/^per_(\d+)_per_item:(.+)$/i);
      if (mItem) return `${mItem[1]} / ${mItem[2]}`;
      const mPax = (rule + '').match(/^per_(\d+)_pax$/i);
      if (mPax) return `Per ${mPax[1]} Pax`;
    }
    if (rule === 'per_pax') return 'Per Pax';
    if (rule === 'per_5_pax') return 'Per 5 Pax';
    if (rule === 'per_8_pax') return 'Per 8 Pax';
    if (rule === 'per_10_pax') return 'Per 10 Pax';
    if (rule === 'per_table') return 'Per Table';
    if (rule === 'per_unit') return 'Per Unit';
    if (rule === 'per_menu_item') return 'Per Menu Item';
    if (rule === 'every_vip') return 'Every VIP';
    return 'Fixed';
  }

  function _calcQty(rule, pax, menuItemCount) {
    if (rule) {
      const mItem = (rule + '').match(/^per_(\d+)_per_item:(.+)$/i);
      if (mItem) return parseInt(mItem[1]) || 1;
      const mPax = (rule + '').match(/^per_(\d+)_pax$/i);
      if (mPax) return Math.ceil(pax / (parseInt(mPax[1]) || 1));
    }
    if (rule === 'per_pax') return pax;
    if (rule === 'per_5_pax') return Math.ceil(pax / 5);
    if (rule === 'per_8_pax') return Math.ceil(pax / 8);
    if (rule === 'per_10_pax') return Math.ceil(pax / 10);
    if (rule === 'per_table') return Math.ceil(pax / 8);
    if (rule === 'per_menu_item') return menuItemCount;
    if (rule === 'every_vip') return hasVip ? 1 : 0;
    return 1;
  }

  const layoutTableCounts = typeof getVenueLayoutTableCounts === 'function' ? getVenueLayoutTableCounts(ev.id) : { roundCount: 0, rectCount: 0 };

  const seen = new Set();
  const needed = [];

  const processItem = (itemName, itemId) => {
    const key = (itemName || '').toLowerCase().trim();
    if (!key || seen.has(key)) return;
    seen.add(key);

    let asset = null;
    if (itemId && EIM_ASSETS && EIM_ASSETS.length) {
      const sbId = itemId.replace(/^eq-sb-/, '');
      asset = EIM_ASSETS.find(a => a.supabaseId === sbId);
    }
    if (!asset) {
      asset = window.findAssetForRule({ name: itemName });
    }
    if (!asset || asset.is_disabled) return;

    const rule = (asset.allocationRule || 'fixed').toLowerCase();
    let qty = _calcQty(rule, pax, menuItemCount);
    if (typeof isRoundTableItem === 'function' && isRoundTableItem(asset) && layoutTableCounts.roundCount > qty) {
      qty = layoutTableCounts.roundCount;
    } else if (typeof isRectTableItem === 'function' && isRectTableItem(asset) && layoutTableCounts.rectCount > qty) {
      qty = layoutTableCounts.rectCount;
    }
    
    const family = typeof getAssetFamily === 'function' ? getAssetFamily(asset) : [asset];
    let remaining = qty;
    
    for (let i = 0; i < family.length; i++) {
      const famAsset = family[i];
      if (remaining <= 0 && i > 0) break;
      
      const famStock = famAsset.availableQty !== undefined ? parseInt(famAsset.availableQty) : (parseInt(famAsset.quantity) || 0);
      
      let take = 0;
      if (remaining > 0) {
        take = Math.min(remaining, famStock);
        if (i === family.length - 1 && remaining > famStock) {
          take = remaining; // Absorb shortfall in the last batch
        }
      }
      if (i === 0 && take === 0 && remaining === 0) { take = 0; } // Keep parent with 0 if no req
      
      needed.push({
        displayName: famAsset.name,
        displayId: famAsset.asset_id || famAsset.id || '',
        allocLabel: i === 0 ? _allocLabel(rule) : 'Batch Spillover',
        qty: take,
        inStock: famStock,
        sufficient: famStock >= take
      });
      remaining -= take;
    }
  };

  if (riRows.length > 0) {
    riRows.filter(r => r.cat === 'equipment').forEach(item => processItem(item.name, item.item_id));
  } else if (ev.packageItems && ev.packageItems.length) {
    ev.packageItems.forEach(itemStr => {
      const name = typeof itemStr === 'string' ? itemStr : (itemStr.name || '');
      processItem(name, null);
    });
  }
  if (hasVip && typeof EIM_ASSETS !== 'undefined') {
    EIM_ASSETS.forEach(ast => {
      if (!ast || ast.is_disabled || (ast.category || '').toLowerCase().includes('decoration')) return;
      const r = ((ast.allocationRule || ast.allocation_type || '') + '').toLowerCase();
      if (r === 'every_vip') processItem(ast.name, ast.asset_id || ast.id);
    });
  }
  if (typeof EIM_ASSETS !== 'undefined') {
    const resDishNames = new Set();
    (riRows || []).forEach(r => {
      if (r && r.name) resDishNames.add(r.name.trim().toLowerCase());
    });
    (ev.packageItems || []).forEach(n => {
      const s = typeof n === 'string' ? n : (n && n.name) || '';
      if (s) resDishNames.add(s.trim().toLowerCase());
    });
    if (Array.isArray(ev.dishes)) {
      ev.dishes.forEach(d => {
        const s = typeof d === 'string' ? d : (d && d.name) || '';
        if (s) resDishNames.add(s.trim().toLowerCase());
      });
    }
    if (Array.isArray(ev.custom_package_items)) {
      ev.custom_package_items.forEach(d => {
        const s = typeof d === 'string' ? d : (d && d.name) || '';
        if (s) resDishNames.add(s.trim().toLowerCase());
      });
    }
    if (Array.isArray(ev.customPackageItems)) {
      ev.customPackageItems.forEach(d => {
        const s = typeof d === 'string' ? d : (d && d.name) || '';
        if (s) resDishNames.add(s.trim().toLowerCase());
      });
    }

    EIM_ASSETS.forEach(ast => {
      if (!ast || ast.is_disabled || (ast.category || '').toLowerCase().includes('decoration')) return;
      const r = ((ast.allocationRule || ast.allocation_type || '') + '').toLowerCase();
      const m = r.match(/^per_(\d+)_per_item:(.+)$/i);
      if (m && resDishNames.has(m[2].trim().toLowerCase())) {
        processItem(ast.name, ast.asset_id || ast.id);
      }
    });
  }
  if (layoutTableCounts.roundCount > 0) {
    const roundAsset = typeof window.findAssetForRule === 'function' ? (window.findAssetForRule({ assetId: 'EQ-0005' }) || window.findAssetForRule({ name: 'Round Banquet Table' })) : null;
    if (roundAsset) processItem(roundAsset.name, roundAsset.asset_id || roundAsset.id);
  }
  if (layoutTableCounts.rectCount > 0) {
    const rectAsset = typeof window.findAssetForRule === 'function' ? (window.findAssetForRule({ assetId: 'EQ-0008' }) || window.findAssetForRule({ assetId: 'EQ-F002' }) || window.findAssetForRule({ name: 'Rectangular Table' })) : null;
    if (rectAsset) processItem(rectAsset.name, rectAsset.asset_id || rectAsset.id);
  }

  // Handle every_certain_equipment rules:
  // Allocate each equipment with rule every_certain_equipment:<target> matching how many times
  // the target selected equipment is allocated for that reservation.
  if (typeof EIM_ASSETS !== 'undefined') {
    EIM_ASSETS.forEach(ast => {
      if (!ast || ast.is_disabled || (ast.category || '').toLowerCase().includes('decoration')) return;
      const r = ((ast.allocationRule || ast.allocation_type || '') + '').trim();
      const m = r.match(/^every_certain_equipment:(.+)$/i);
      if (m) {
        const targetKey = m[1].trim().toUpperCase();
        const targetItem = needed.find(n => 
          (n.displayId && n.displayId.toUpperCase() === targetKey) || 
          (n.displayName && n.displayName.toUpperCase() === targetKey)
        );
        const targetQty = targetItem ? targetItem.qty : 0;
        if (targetQty > 0) {
          const key = (ast.name || '').toLowerCase().trim();
          if (!seen.has(key)) {
            seen.add(key);
            const famStock = ast.availableQty !== undefined ? parseInt(ast.availableQty) : (parseInt(ast.quantity) || 0);
            needed.push({
              displayName: ast.name,
              displayId: ast.asset_id || ast.id || '',
              allocLabel: `Every ${targetItem.displayName}`,
              qty: targetQty,
              inStock: famStock,
              sufficient: famStock >= targetQty
            });
          }
        }
      }
    });
  }

  if (needed.length === 0) {
    container.innerHTML = '<div style="text-align:center; padding:20px; color:var(--text-dim); font-size:12px;">No equipment items found for this reservation.</div>';
    return;
  }

  container.innerHTML = needed.map(item => {
    const stockColor = item.sufficient ? 'var(--green)' : 'var(--red)';
    const stockLabel = item.inStock + ' in stock';
    const qtyColor = item.sufficient ? 'var(--gold)' : 'var(--red)';
    const name = typeof escHtml === 'function' ? escHtml(item.displayName) : item.displayName;
    return '<div style="display:flex; justify-content:space-between; align-items:center; padding:10px 14px; background:rgba(255,255,255,0.02); border:1px solid rgba(255,255,255,0.05); border-radius:8px; margin-bottom:4px;">'
      + '<div>'
      + '<div style="font-size:12px; font-weight:600; color:var(--cream);">' + name + '</div>'
      + '<div style="font-size:10px; color:var(--text-dim); margin-top:2px;">' + (item.displayId || '') + ' &nbsp;&#183;&nbsp; ' + item.allocLabel + ' &nbsp;&#183;&nbsp; <span style=\'color:' + stockColor + ';\' >' + stockLabel + '</span></div>'
      + '</div>'
      + '<div style="font-size:16px; font-weight:800; color:' + qtyColor + ';">' + item.qty + '</div>'
      + '</div>';
  }).join('');
}

function _clearEquipmentNeededList() {
  const container = document.getElementById('alloc-equipment-needed-list');
  if (container) {
    container.innerHTML = '<div style="text-align:center; padding:20px; color:var(--text-dim); font-size:12px;">Select an active reservation from the top dropdown to view required equipment.</div>';
  }
}

function _hideAllocResults() {
  ['alloc-manifest-panel', 'alloc-shortage-panel', 'alloc-status-banner'].forEach(id => {
    const el = document.getElementById(id); if (el) el.style.display = 'none';
  });
  const empty = document.getElementById('alloc-empty-state');
  if (empty) empty.style.display = currentAllocEvent ? 'none' : 'block';
}

function getAssetFamily(rootAsset) {
  if (!rootAsset) return [];
  if (rootAsset.parent_asset_id) return [rootAsset];
  
  const children = (EIM_ASSETS || []).filter(a => a.parent_asset_id === (rootAsset.asset_id || rootAsset.id) && !a.is_disabled);
  
  const splits = children.filter(c => (c.name || '').includes('SPLIT BATCH'));
  const normals = children.filter(c => !(c.name || '').includes('SPLIT BATCH'));
  
  normals.sort((a, b) => {
    const numA = parseInt(((a.asset_id || '').match(/-BATCH-(\d+)$/) || [])[1] || '99');
    const numB = parseInt(((b.asset_id || '').match(/-BATCH-(\d+)$/) || [])[1] || '99');
    return numA - numB;
  });

  return [rootAsset, ...splits, ...normals];
}

async function generateAllocationManifest() {
  if (!currentAllocEvent) { alert('Please select an event first.'); return; }
  const ev = currentAllocEvent;
  const pax = parseInt(ev.pax) || 0;

  let otherAllocs = [];
  let thisAlloc = [];
  let latestBatchName = null;
  if (window.supabaseClient && typeof RESERVATIONS !== 'undefined') {
    try {
      const formatResDate = (dStr) => {
        if (!dStr) return null;
        const d = new Date(dStr);
        if (!isNaN(d.getTime())) return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
        return dStr;
      };
      const evD = formatResDate(ev.date || ev.eventDate);
      const sameDateResIds = evD ? RESERVATIONS.filter(r => formatResDate(r.date || r.eventDate) === evD && r.id !== ev.id).map(r => r.id) : [];

      const validResUuids = [ev.id, ...sameDateResIds].filter(id => typeof isUuidString === 'function' ? isUuidString(id) : Boolean(id));
      let data = null;
      if (validResUuids.length > 0) {
        const res = await window.supabaseClient
          .from('allocation_history')
          .select('asset_id,allocated_qty,reservation_id,allocation_batch,is_rental,recorded_at')
          .in('reservation_id', validResUuids);
        data = res.data;
      }

      if (data) {
        otherAllocs = data.filter(r => r.reservation_id !== ev.id && !r.is_rental);

        const thisData = data.filter(r => r.reservation_id === ev.id);
        if (thisData.length > 0) {
          // Exclude VENUE- prefix and rentals when finding latest allocation batch
          const nonVenueData = thisData.filter(r => !r.is_rental && !(r.allocation_batch || '').startsWith('VENUE-'));
          if (nonVenueData.length > 0) {
            const latest = nonVenueData.reduce((prev, curr) => (new Date(curr.recorded_at).getTime() > new Date(prev.recorded_at).getTime()) ? curr : prev);
            latestBatchName = latest.allocation_batch;
            thisAlloc = thisData.filter(r => r.allocation_batch === latestBatchName);
          } else {
            const latest = thisData.reduce((prev, curr) => (new Date(curr.recorded_at).getTime() > new Date(prev.recorded_at).getTime()) ? curr : prev);
            latestBatchName = latest.allocation_batch;
            thisAlloc = thisData.filter(r => r.allocation_batch === latestBatchName);
          }
        }
      }
    } catch (e) { console.warn('Failed to fetch allocs for manifest:', e); }
  }

  // Package Modification Detection
  const expectedBatchName = _genBatchName(ev);
  const dismissKey = `dismiss_mod_${ev.id}_${latestBatchName}_${expectedBatchName}`;
  const isDismissed = localStorage.getItem(dismissKey) === 'true';
  const isPackageModified = !isDismissed && latestBatchName && expectedBatchName && latestBatchName !== expectedBatchName;

  let changeStr = '';

  let bannerTitle = '';
  let bannerText = '';
  let modBanner = document.getElementById('alloc-modification-banner');
  if (modBanner) modBanner.style.display = 'none';
  // -----------------------------------------------------------------------------------

  let menuItemCount = 1;
  if (ev.packageItems && typeof CAT !== 'undefined') {
    menuItemCount = ev.packageItems.map(n => CAT.find(c => c.name === (typeof n === 'string' ? n : n.name))).filter(i => i && i.cat === 'food').length || 1;
  }

  // Helper to look up venue provided equipment from the live active map
  const getVenueProvForAsset = (ast) => {
    if (!ast || !window.currentVenueEquipmentMap) return 0;
    const directId = (ast.asset_id || ast.id || '').toUpperCase().trim();
    const parentId = (ast.parent_asset_id || '').toUpperCase().trim();
    const lowName = (ast.name || '').toLowerCase().trim();

    // 1. Direct match on asset_id or parent_asset_id in currentVenueEquipmentMap
    for (const [k, v] of Object.entries(window.currentVenueEquipmentMap)) {
      const ku = k.toUpperCase().trim();
      if (ku && (ku === directId || (parentId && ku === parentId))) {
        return parseInt(v) || 0;
      }
    }

    // 2. Match by asset name
    for (const [k, v] of Object.entries(window.currentVenueEquipmentMap)) {
      const match = typeof window.findAssetForRule === 'function' ? window.findAssetForRule({ assetId: k, name: k }) : null;
      if (match) {
        const mName = (match.name || '').toLowerCase().trim();
        if (mName === lowName || (lowName && mName.includes(lowName)) || (mName && lowName.includes(mName))) {
          return parseInt(v) || 0;
        }
      }
    }
    return 0;
  };

  const tablesNeeded = Math.ceil(pax / 8);
  const manifest = [];
  const shortages = [];
  _lastGeneratedManifest = []; // Reset

  // Core sequential batch allocation function
  // Handles requirement deduction, venue deduction, and extra buffer distribution across batches
  const allocateAssetFamily = (asset, exact, rule) => {
    if (!asset || asset.is_disabled || (asset.category || '').toLowerCase().includes('decoration')) return;

    const custInfo = getEquipmentCustomizationDelta(asset, ev, exact);
    const custDelta = custInfo.delta;
    const effectiveExact = Math.max(0, exact + custDelta);

    // Read raw venue provided count from venue_equipment.items (window.currentVenueEquipmentMap)
    const rawVenueProv = getVenueProvForAsset(asset);
    const venueProvDeduction = Math.min(rawVenueProv, effectiveExact);
    const afterVenue = Math.max(0, effectiveExact - venueProvDeduction);
    const buffer = parseInt(asset.extra_buffer) || 0;
    const finalReq = afterVenue + buffer;
    const isFragile = !!(asset.fragility === 'fragile' || asset.isFragile);

    const family = getAssetFamily(asset);
    let remainingAfterVenue = afterVenue;
    let remainingBuffer = buffer;

    for (let i = 0; i < family.length; i++) {
      const famAsset = family[i];

      const famBaseQty = parseInt(famAsset.quantity) || 0;
      const famAllocOthers = otherAllocs
        .filter(r => (r.asset_id || '').toUpperCase() === (famAsset.asset_id || famAsset.id || '').toUpperCase())
        .reduce((s, r) => s + (parseInt(r.allocated_qty) || 0), 0);
      const famStockQty = Math.max(0, famBaseQty - famAllocOthers);

      const famSavedAlloc = thisAlloc
        .filter(a => !a.is_rental && (
          (a.asset_id && (famAsset.asset_id || famAsset.id) && String(a.asset_id).toUpperCase() === String(famAsset.asset_id || famAsset.id).toUpperCase()) ||
          (a.equipment_id && famAsset.supabaseId && String(a.equipment_id) === String(famAsset.supabaseId)) ||
          (a.equipment_name && famAsset.name && String(a.equipment_name).toLowerCase().trim() === String(famAsset.name).toLowerCase().trim())
        ))
        .reduce((s, a) => s + (parseInt(a.allocated_qty) || 0), 0);

      // 1. Take requirement first from this batch
      let takeAfterVenue = Math.min(remainingAfterVenue, famStockQty);
      let availForBuffer = Math.max(0, famStockQty - takeAfterVenue);

      // 2. Take extra buffer from whatever available stock is left in this batch
      let takeBuffer = Math.min(remainingBuffer, availForBuffer);

      // Deduct from remaining pools
      remainingAfterVenue -= takeAfterVenue;
      remainingBuffer -= takeBuffer;

      // 3. Last batch absorbs any remaining shortfall in requirement or buffer
      if (i === family.length - 1) {
        takeAfterVenue += remainingAfterVenue;
        takeBuffer += remainingBuffer;
        remainingAfterVenue = 0;
        remainingBuffer = 0;
      }

      // 4. Venue provides is attributed to the parent batch (i === 0) with full raw count
      let thisVenue = 0;
      if (i === 0) {
        thisVenue = rawVenueProv;
      }

      let take = takeAfterVenue + takeBuffer;

      // Hide batch if it contributes nothing to requirement or buffer
      if (take === 0 && thisVenue === 0 && i > 0) continue;

      let thisExact = (i === 0) ? (family.length > 1 ? (takeAfterVenue + venueProvDeduction) : exact) : takeAfterVenue;
      const famShortfall = Math.max(0, take - famStockQty);
      const famUnavail = famAsset.is_disabled || famAsset.status === 'Under Repair' || famAsset.status === 'Retired' || famAsset.status === 'under_repair' || famAsset.status === 'retired';

      manifest.push({
        assetId: famAsset.asset_id || famAsset.id,
        name: famAsset.name,
        category: famAsset.category || asset.category,
        ruleDesc: rule || asset.allocationRule || 'fixed',
        exactReq: thisExact,
        venueProv: thisVenue,
        afterVenue: takeAfterVenue,
        buffer: takeBuffer,
        custDelta: (i === 0 ? custDelta : 0),
        finalReq: take,
        inStock: famStockQty,
        allocatedQty: famSavedAlloc > 0 ? famSavedAlloc : Math.min(take, famStockQty),
        hasSavedAlloc: famSavedAlloc > 0,
        shortfall: famShortfall,
        sufficient: famShortfall <= 0,
        isFragile: isFragile,
        unavail: famUnavail,
        isBatchChild: i > 0,
        parentAssetId: i > 0 ? (asset.asset_id || asset.id) : null
      });
    }
  };

  const rawVip = ev.vipCount != null ? ev.vipCount : (ev.vip && typeof ev.vip === 'object' ? ev.vip.count : (ev.vip_count != null ? ev.vip_count : ev.vip));
  const hasVip = (parseInt(rawVip) || 0) > 0 || !!(ev.hasVip || ev.isVip);

  if (ev.equipmentManifest && ev.equipmentManifest.length > 0) {
    const seenRootIds = new Set();
    ev.equipmentManifest.forEach(saved => {
      let asset = window.findAssetForRule({ assetId: saved.assetId }) || window.findAssetForRule({ name: saved.name });
      if (!asset || asset.is_disabled || (asset.category || '').toLowerCase().includes('decoration')) return;

      let rootAsset = asset;
      if (asset.parent_asset_id) {
        rootAsset = window.findAssetForRule({ assetId: asset.parent_asset_id }) || asset;
      }
      const rootKey = (rootAsset.asset_id || rootAsset.id || '').toUpperCase();
      if (seenRootIds.has(rootKey)) return;
      seenRootIds.add(rootKey);

      let exact = saved.exactReq || saved.exact || saved.finalReq || 1;
      allocateAssetFamily(rootAsset, exact, saved.ruleDesc);
    });
  } else if (ev.packageItems && ev.packageItems.length) {
    const seenRootIds = new Set();
    ev.packageItems.forEach(itemStr => {
      const ruleName = typeof itemStr === 'string' ? itemStr : (itemStr.name || 'Unknown');
      let asset = window.findAssetForRule({ name: ruleName });
      if (!asset || asset.is_disabled || (asset.category || '').toLowerCase().includes('decoration')) return;

      let rootAsset = asset;
      if (asset.parent_asset_id) {
        rootAsset = window.findAssetForRule({ assetId: asset.parent_asset_id }) || asset;
      }
      const rootKey = (rootAsset.asset_id || rootAsset.id || '').toUpperCase();
      if (seenRootIds.has(rootKey)) return;
      seenRootIds.add(rootKey);

      let exact = 1;
      const rule = (rootAsset.allocationRule || rootAsset.allocation_type || 'fixed').toLowerCase();
      const mPerItem = rule.match(/^per_(\d+)_per_item:(.+)$/i);
      const mPax = rule.match(/^per_(\d+)_pax$/i);
      if (mPerItem) exact = parseInt(mPerItem[1]) || 1;
      else if (mPax) exact = Math.ceil(pax / (parseInt(mPax[1]) || 1));
      else if (rule === 'per_pax') exact = pax;
      else if (rule === 'per_5_pax') exact = Math.ceil(pax / 5);
      else if (rule === 'per_8_pax') exact = Math.ceil(pax / 8);
      else if (rule === 'per_10_pax') exact = Math.ceil(pax / 10);
      else if (rule === 'per_table') exact = tablesNeeded;
      else if (rule === 'per_menu_item') exact = menuItemCount;
      else if (rule === 'every_vip') exact = hasVip ? 1 : 0;

      allocateAssetFamily(rootAsset, exact, rule);
    });
  }

  // If reservation has VIP, ensure every_vip equipment is added to manifest
  if (hasVip && typeof EIM_ASSETS !== 'undefined') {
    EIM_ASSETS.forEach(ast => {
      if (!ast || ast.is_disabled || (ast.category || '').toLowerCase().includes('decoration')) return;
      const r = ((ast.allocationRule || ast.allocation_type || '') + '').toLowerCase();
      if (r === 'every_vip') {
        let rootAsset = ast;
        if (ast.parent_asset_id) {
          rootAsset = window.findAssetForRule({ assetId: ast.parent_asset_id }) || ast;
        }
        const rootKey = (rootAsset.asset_id || rootAsset.id || '').toUpperCase();
        const alreadyIn = manifest.some(m => (m.assetId || '').toUpperCase() === rootKey);
        if (!alreadyIn) {
          allocateAssetFamily(rootAsset, 1, 'every_vip');
        }
      }
    });
  }

  // If reservation dishes match equipment per_N_per_item rules, ensure they are added to manifest
  if (typeof EIM_ASSETS !== 'undefined') {
    const resDishNames = new Set(
      (ev.packageItems || []).map(n => (typeof n === 'string' ? n : (n && n.name) || '').toLowerCase().trim()).filter(Boolean)
    );
    if (Array.isArray(ev.dishes)) {
      ev.dishes.forEach(d => {
        const s = typeof d === 'string' ? d : (d && d.name) || '';
        if (s) resDishNames.add(s.trim().toLowerCase());
      });
    }
    if (Array.isArray(ev.custom_package_items)) {
      ev.custom_package_items.forEach(d => {
        const s = typeof d === 'string' ? d : (d && d.name) || '';
        if (s) resDishNames.add(s.trim().toLowerCase());
      });
    }
    if (Array.isArray(ev.customPackageItems)) {
      ev.customPackageItems.forEach(d => {
        const s = typeof d === 'string' ? d : (d && d.name) || '';
        if (s) resDishNames.add(s.trim().toLowerCase());
      });
    }

    EIM_ASSETS.forEach(ast => {
      if (!ast || ast.is_disabled || (ast.category || '').toLowerCase().includes('decoration')) return;
      const r = ((ast.allocationRule || ast.allocation_type || '') + '').toLowerCase();
      const m = r.match(/^per_(\d+)_per_item:(.+)$/i);
      if (m && resDishNames.has(m[2].trim().toLowerCase())) {
        let rootAsset = ast;
        if (ast.parent_asset_id) {
          rootAsset = window.findAssetForRule({ assetId: ast.parent_asset_id }) || ast;
        }
        const rootKey = (rootAsset.asset_id || rootAsset.id || '').toUpperCase();
        const alreadyIn = manifest.some(mItem => (mItem.assetId || '').toUpperCase() === rootKey);
        if (!alreadyIn) {
          const reqN = parseInt(m[1]) || 1;
          allocateAssetFamily(rootAsset, reqN, ast.allocationRule || r);
        }
      }
    });

    // Every Certain Equipment: allocated for how many times the selected equipment is allocated as well for that reservation
    EIM_ASSETS.forEach(ast => {
      if (!ast || ast.is_disabled || (ast.category || '').toLowerCase().includes('decoration')) return;
      const r = ((ast.allocationRule || ast.allocation_type || '') + '').trim();
      const m = r.match(/^every_certain_equipment:(.+)$/i);
      if (m) {
        const targetKey = m[1].trim().toUpperCase();
        const targetLine = manifest.find(l => 
          (l.assetId && l.assetId.toUpperCase() === targetKey) || 
          (l.name && l.name.toUpperCase() === targetKey)
        );
        const targetQty = targetLine ? (targetLine.exactReq || targetLine.finalReq || targetLine.allocatedQty || 0) : 0;
        if (targetQty > 0) {
          let rootAsset = ast;
          if (ast.parent_asset_id) {
            rootAsset = window.findAssetForRule({ assetId: ast.parent_asset_id }) || ast;
          }
          const rootKey = (rootAsset.asset_id || rootAsset.id || '').toUpperCase();
          const alreadyIn = manifest.some(mItem => (mItem.assetId || '').toUpperCase() === rootKey);
          if (!alreadyIn) {
            allocateAssetFamily(rootAsset, targetQty, ast.allocationRule || r);
          }
        }
      }
    });
  }

  // ── Venue Layout Table Counts Comparison for Deployment Manifest ──
  const layoutTableCounts = typeof getVenueLayoutTableCounts === 'function' ? getVenueLayoutTableCounts(ev.id) : { roundCount: 0, rectCount: 0 };

  // 1. Round Banquet Table
  let roundLine = manifest.find(l => isRoundTableItem(l));
  if (!roundLine && layoutTableCounts.roundCount > 0) {
    const roundAsset = (typeof window.findAssetForRule === 'function' ? (window.findAssetForRule({ assetId: 'EQ-0005' }) || window.findAssetForRule({ name: 'Round Banquet Table' })) : null);
    if (roundAsset) {
      allocateAssetFamily(roundAsset, 0, 'per_table');
      roundLine = manifest.find(l => isRoundTableItem(l));
    }
  }
  if (roundLine && layoutTableCounts.roundCount > roundLine.finalReq) {
    const extraRound = layoutTableCounts.roundCount - roundLine.finalReq;
    roundLine.extraBufferFromLayout = extraRound;
    roundLine.bufferDisplay = `+${roundLine.buffer} (+${extraRound} from venue layout)`;
    roundLine.finalReq += extraRound;
    roundLine.buffer += extraRound;
    roundLine.shortfall = Math.max(0, roundLine.finalReq - roundLine.inStock);
    roundLine.sufficient = roundLine.shortfall <= 0;
  }

  // 2. Rectangular Table
  let rectLine = manifest.find(l => isRectTableItem(l));
  if (!rectLine && layoutTableCounts.rectCount > 0) {
    const rectAsset = (typeof window.findAssetForRule === 'function' ? (window.findAssetForRule({ assetId: 'EQ-0008' }) || window.findAssetForRule({ assetId: 'EQ-F002' }) || window.findAssetForRule({ name: 'Rectangular Table' })) : null);
    if (rectAsset) {
      allocateAssetFamily(rectAsset, 0, 'fixed');
      rectLine = manifest.find(l => isRectTableItem(l));
    }
  }
  if (rectLine && layoutTableCounts.rectCount > rectLine.finalReq) {
    const extraRect = layoutTableCounts.rectCount - rectLine.finalReq;
    rectLine.extraBufferFromLayout = extraRect;
    rectLine.bufferDisplay = `+${rectLine.buffer} (+${extraRect} from venue layout)`;
    rectLine.finalReq += extraRect;
    rectLine.buffer += extraRect;
    rectLine.shortfall = Math.max(0, rectLine.finalReq - rectLine.inStock);
    rectLine.sufficient = rectLine.shortfall <= 0;
  }

  const tbody = document.getElementById('alloc-manifest-tbody');
  if (tbody) {
    tbody.innerHTML = manifest.map((line, idx) => {
      const okCls = line.unavail ? 'critical' : (line.sufficient ? 'confirmed' : 'critical');
      const okLbl = line.unavail ? 'Unavailable' : (line.sufficient ? 'Covered' : `Short ${line.shortfall}`);
      const dqClr = line.sufficient ? 'var(--cream)' : 'var(--red)';
      const cleanAssetId = (line.assetId || '').trim();
      const subRowHtml = `<tr id="manifest-subrow-${cleanAssetId}" class="manifest-unit-subrow" style="display:none; background:rgba(0,0,0,0.35);">
        <td colspan="12" style="padding:10px 18px;">
          <div style="font-size:11px; color:var(--text-dim);">Loading allocated unique units for ${cleanAssetId}...</div>
        </td>
      </tr>`;
      return `<tr style="cursor:pointer;" onclick="if(typeof window.toggleManifestUnitSubRow==='function') window.toggleManifestUnitSubRow('${cleanAssetId}', ${idx})" title="Click row to view allocated unique units">
        <td><code style="font-size:11px;color:var(--gold);">${line.assetId} ▾</code></td>
        <td><div class="item-name">${line.name}</div><div class="item-cat">${line.isFragile ? 'Fragile' : 'Sturdy'} \u00b7 ${line.note || ''}</div></td>
        <td><span class="badge pending" style="font-size:10px;">${line.category}</span></td>
        <td style="font-size:13px;font-weight:600;">${line.exactReq}</td>
        <td style="font-size:12px;color:var(--amber);">${line.bufferDisplay || ('+' + line.buffer)}</td>
        <td style="font-size:14px;font-weight:700;color:${dqClr};">${line.finalReq != null ? line.finalReq : (line.exactReq + line.buffer)}</td>
        <td style="font-size:13px;color:${line.inStock < line.finalReq ? 'var(--red)' : 'var(--text)'};">${line.inStock}</td>
        <td style="font-size:13px;color:var(--amber);">${line.venueProv > 0 ? line.venueProv : '\u2014'}</td>
        <td style="font-size:14px;font-weight:700;color:${dqClr};">${line.finalReq != null ? line.finalReq : (line.exactReq + line.buffer)}</td>
        <td style="font-size:14px;font-weight:700;color:${line.hasSavedAlloc ? 'var(--green)' : '#eab308'};">${line.hasSavedAlloc ? line.allocatedQty : (line.finalReq || '\u2014')}</td>
        <td style="font-size:13px;font-weight:700;color:#eab308;">${line.rentalQty > 0 ? line.rentalQty : '\u2014'}</td>
        <td><span class="badge ${okCls}" style="font-size:10px;white-space:nowrap;">${okLbl}</span></td>
      </tr>` + subRowHtml;
    }).join('');
  }

  const okCount = manifest.filter(l => l.shortfall <= 0 && !l.unavail).length;
  const shortCount = manifest.filter(l => l.shortfall > 0 || l.unavail).length;
  const venueCount = manifest.filter(l => l.venueProv > 0).length;
  const st = (id, v) => { const el = document.getElementById(id); if (el) el.textContent = v; };
  st('alloc-sum-items', manifest.length);
  st('alloc-sum-ok', okCount);
  st('alloc-sum-short', shortCount);
  st('alloc-sum-venue', venueCount);

  const badge = document.getElementById('alloc-manifest-badge');
  if (badge) {
    badge.textContent = shortCount > 0
      ? `${shortCount} SHORTAGE${shortCount > 1 ? 'S' : ''}`
      : 'FULLY COVERED';
    badge.className = '';
    badge.style.cssText = 'font-size:11px; font-weight:800; color:var(--gold); text-transform:uppercase; letter-spacing:1px;';
  }
  const sub = document.getElementById('alloc-manifest-sub');
  if (sub) sub.textContent = `${ev.client} \u2014 ${ev.date} \u00b7 ${pax} pax \u00b7 ${manifest.length} equipment lines`;

  const stbody = document.getElementById('alloc-shortage-tbody');
  if (stbody) {
    stbody.innerHTML = manifest.filter(l => l.shortfall > 0 || l.unavail).map(line => `<tr>
      <td><div class="item-name">${line.name}</div><div class="item-cat">${line.note || ''}</div></td>
      <td><span class="badge pending" style="font-size:10px;">${line.category}</span></td>
      <td style="font-size:13px;font-weight:700;">${line.finalReq}${line.unavail ? ' <span style="color:var(--red);font-size:10px;">(unavailable)</span>' : ''}</td>
      <td style="font-size:13px;color:var(--red);">${line.inStock}</td>
      <td style="font-size:14px;font-weight:700;color:var(--red);">${line.unavail ? 'All' : line.shortfall}</td>
      <td><button class="btn-reject" style="font-size:11px;" onclick="switchEqCycleTab('rentals', document.getElementById('eqc-tab-rentals'))">Go to Rental Hub</button></td>
    </tr>`).join('');
  }

  const banner = document.getElementById('alloc-status-banner');
  if (banner) {
    banner.innerHTML = '';
    banner.style.display = 'none';
  }

  const show = (id, v) => { const el = document.getElementById(id); if (el) el.style.display = v ? 'block' : 'none'; };
  show('alloc-empty-state', false);
  show('alloc-manifest-panel', true);
  show('alloc-shortage-panel', shortCount > 0);

  // Store manifest for allocation buttons
  _lastGeneratedManifest = manifest.slice();

  // Apply any rental quantities that might already be confirmed for this reservation
  await checkAndApplyRentalQty(ev.id);

  // Update allocation button states based on current Supabase data
  updateAllocButtons();

  // Re-render venue equipment list with populated manifest data
  if (typeof renderVenueEquipmentList === 'function') {
    renderVenueEquipmentList();
  }
}

// Print / export manifest
function printAllocationManifest() {
  if (!currentAllocEvent) return;
  const ev = currentAllocEvent;
  const tbl = document.getElementById('alloc-manifest-table');
  if (!tbl) return;
  const html = `<!DOCTYPE html><html><head><title>Deployment Manifest \u2014 ${ev.client}</title>
  <style>
  :root { --gold: #eab308; }
  body{font-family:Arial,sans-serif;font-size:12px;color:#111;padding:20px;}
  h1{font-size:18px;margin-bottom:4px;}
  p{color:#555;margin-bottom:16px;}
  table{border-collapse:collapse;width:100%;}
  th{background:#1a1007;color:#f5ede0;padding:8px 10px;text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.5px;}
  td{padding:7px 10px;border-bottom:1px solid #ddd;font-size:12px;}
  /* Explicitly enforce yellow for Allocated Quantity and Rentals columns */
  th:nth-child(11), td:nth-child(11), th:nth-child(11) *, td:nth-child(11) *,
  th:nth-child(12), td:nth-child(12), th:nth-child(12) *, td:nth-child(12) * {
    color: #eab308 !important;
    font-weight: 700 !important;
  }
  @media print {
    th:nth-child(11), td:nth-child(11), th:nth-child(11) *, td:nth-child(11) *,
    th:nth-child(12), td:nth-child(12), th:nth-child(12) *, td:nth-child(12) * {
      color: #ca8a04 !important;
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
  }
  </style></head><body>
  <h1>Deployment Manifest \u2014 ${ev.client}</h1>
  <p>${ev.date} \u00b7 ${ev.pax} pax \u00b7 ${ev.type} \u00b7 Generated: ${new Date().toLocaleString()}</p>
  ${tbl.outerHTML}
  <script>window.print();<\/script></body></html>`;
  const win = window.open('', '_blank');
  win.document.write(html);
  win.document.close();
}

// ====================================================================
// ALLOCATION MODE : module-level state
// ====================================================================
let _lastGeneratedManifest = []; // set by generateAllocationManifest
let _allocMode = null;           // null | 'auto' | 'manual' | 'modify'

// Parse differences between two batch names for the banner
function _getBatchModificationString(latestBatchName, expectedBatchName) {
  if (!latestBatchName || !expectedBatchName || latestBatchName === expectedBatchName) return '';

  const isLegacy = !latestBatchName.startsWith('BATCH-');
  if (isLegacy) return 'Legacy allocation detected. Please review and re-allocate to sync with new format.';

  let changes = [];

  const latestPaxMatch = latestBatchName.match(/-P(\d+)/);
  const expectedPaxMatch = expectedBatchName.match(/-P(\d+)/);
  if (latestPaxMatch && expectedPaxMatch && latestPaxMatch[1] !== expectedPaxMatch[1]) {
    const pOld = parseInt(latestPaxMatch[1]);
    const pNew = parseInt(expectedPaxMatch[1]);
    changes.push(`Pax ${pNew > pOld ? 'increased' : 'decreased'} from ${pOld} to ${pNew}`);
  }

  const getPkg = (batch) => {
    const pMatch = batch.match(/-P\d+-([^-]+)/);
    return pMatch ? pMatch[1] : null;
  };
  const latestPkg = getPkg(latestBatchName);
  const expectedPkg = getPkg(expectedBatchName);
  if (latestPkg && expectedPkg && latestPkg !== expectedPkg) {
    changes.push(`Package type modified`);
  }

  const latestItemsMatch = latestBatchName.match(/-I([A-Z0-9]+)$/);
  const expectedItemsMatch = expectedBatchName.match(/-I([A-Z0-9]+)$/);
  if (latestItemsMatch && expectedItemsMatch && latestItemsMatch[1] !== expectedItemsMatch[1]) {
    changes.push(`Package items added or removed`);
  } else if (!latestItemsMatch && expectedItemsMatch) {
    changes.push(`Package items modified`);
  }

  if (changes.length > 0) {
    return 'Detected changes: ' + changes.join(', ') + '. Please review and re-allocate.';
  }

  return 'The reservation requirements have changed since the last allocation. Please review and re-allocate.';
}

// Generate a batch name from reservation client name + event date
function _genBatchName(ev) {
  const initials = (ev.client || ev.name || 'EVT')
    .split(/\s+/).map(w => w[0] || '').join('').toUpperCase().slice(0, 4);
  const datePart = (ev.date || '').replace(/-/g, '');
  const resShort = (ev.id || '').replace(/-/g, '').slice(0, 6).toUpperCase();
  const pax = parseInt(ev.pax || ev.guests) || 0;
  const pkgName = (ev.packageName || 'CUST').toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 10);

  const items = ev.packageItems || [];
  const itemsStr = items.map(i => typeof i === 'string' ? i : (i.name || '')).sort().join('|');
  let hash = 5381;
  for (let i = 0; i < itemsStr.length; i++) {
    hash = (hash * 33) ^ itemsStr.charCodeAt(i);
  }
  const itemsHash = Math.abs(hash).toString(16).toUpperCase();

  return `BATCH-${initials}-${datePart}-${resShort}-P${pax}-${pkgName}-I${itemsHash}`;
}

// Re-render the manifest tbody : optionally with an allocation qty column
function _renderManifestWithAllocCol(mode) {
  const manifest = _lastGeneratedManifest;
  const tbody = document.getElementById('alloc-manifest-tbody');
  const thead = document.querySelector('#alloc-manifest-table thead tr');
  if (!tbody || !thead) return;

  // Clean up any stray dynamic th to ensure exactly the 12 permanent columns in admin.html
  const existingAllocTh = document.getElementById('alloc-th-qty');
  if (existingAllocTh) existingAllocTh.remove();

  tbody.innerHTML = manifest.map((line, idx) => {
    const okCls = line.unavail ? 'critical' : (line.shortfall <= 0 ? 'confirmed' : 'critical');
    const okLbl = line.unavail ? 'Unavailable' : (line.shortfall <= 0 ? 'Covered' : `Short ${line.shortfall}`);
    const dqClr = line.shortfall <= 0 ? 'var(--cream)' : 'var(--red)';
    const cleanAssetId = (line.assetId || '').trim();

    // Determine prefilled value for allocation input
    let prefill = '';
    if (mode === 'auto') {
      prefill = Math.min(Math.max(0, line.finalReq - (line.rentalQty || 0)), line.inStock);
    }
    else if (mode === 'modify') {
      prefill = line.hasSavedAlloc ? line.allocatedQty : line.finalReq;
    } else {
      prefill = line.hasSavedAlloc ? line.allocatedQty : Math.min(line.finalReq, line.inStock);
    }

    const allocColContent = mode
      ? `<input type="number" id="alloc-qty-input-${idx}" class="input-field" value="${prefill}" min="0" max="${line.inStock}" style="width:80px;padding:4px 8px;font-size:12px;" oninput="if(parseInt(this.value)>${line.inStock}){this.value=${line.inStock};if(typeof showToast==='function')showToast('Cannot exceed in-stock quantity of ${line.inStock}','warning');} if(typeof window.onManifestMainQtyChanged==='function') window.onManifestMainQtyChanged('${cleanAssetId}', this.value, ${idx});" />`
      : `<span style="font-weight:700;color:${line.hasSavedAlloc ? 'var(--green)' : '#eab308'};">${line.hasSavedAlloc ? line.allocatedQty : (line.finalReq || '\u2014')}</span>`;

    const subRowHtml = `<tr id="manifest-subrow-${cleanAssetId}" class="manifest-unit-subrow" style="display:none; background:rgba(0,0,0,0.35);">
      <td colspan="13" style="padding:10px 18px; width:100%; box-sizing:border-box;">
        <div style="font-size:11px; color:var(--text-dim);">Loading allocated unique units for ${cleanAssetId}...</div>
      </td>
    </tr>`;

    return `<tr style="cursor:pointer;" onclick="if(typeof window.toggleManifestUnitSubRow==='function') window.toggleManifestUnitSubRow('${cleanAssetId}', ${idx})" title="Click row to view allocated unique units">
      <td><code style="font-size:11px;color:var(--gold);">${line.assetId} ▾</code></td>
      <td><div class="item-name">${line.name}</div><div class="item-cat">${line.isFragile ? 'Fragile' : 'Sturdy'} \u00b7 ${line.note || ''}</div></td>
      <td><span class="badge pending" style="font-size:10px;">${line.category}</span></td>
      <td style="font-size:13px;font-weight:600;">${line.exactReq}</td>
      <td style="font-size:12px;color:var(--amber);">${line.bufferDisplay || ('+' + line.buffer)}</td>
      <td style="font-size:12px;">${line.custDelta > 0 ? `<span style="font-weight:700;color:var(--gold);">+${line.custDelta}</span>` : (line.custDelta < 0 ? `<span style="font-weight:700;color:var(--red);">${line.custDelta}</span>` : `<span style="color:var(--text-dim);">-</span>`)}</td>
      <td style="font-size:14px;font-weight:700;color:${dqClr};">${line.finalReq != null ? line.finalReq : (line.exactReq + line.buffer)}</td>
      <td style="font-size:13px;color:${line.inStock < line.finalReq ? 'var(--red)' : 'var(--text)'};">${line.inStock}</td>
      <td style="font-size:13px;color:var(--amber);">${line.venueProv > 0 ? line.venueProv : '\u2014'}</td>
      <td style="font-size:14px;font-weight:700;color:${dqClr};">${line.finalReq != null ? line.finalReq : (line.exactReq + line.buffer)}</td>
      <td style="font-size:14px;font-weight:700;color:${line.hasSavedAlloc ? 'var(--green)' : '#eab308'};" onclick="event.stopPropagation();">${allocColContent}</td>
      <td style="font-size:13px;font-weight:700;color:#eab308;">${line.rentalQty > 0 ? line.rentalQty : '\u2014'}</td>
      <td><span class="badge ${okCls}" style="font-size:10px;white-space:nowrap;">${okLbl}</span></td>
    </tr>` + subRowHtml;
  }).join('');
}

// Update button states based on current alloc data
function updateAllocButtons() {
  const ev = currentAllocEvent;
  const modifyBtn = document.getElementById('btn-alloc-modify');
  const saveBtn = document.getElementById('btn-alloc-save');
  const cancelBtn = document.getElementById('btn-alloc-cancel');
  if (!modifyBtn) return;

  // Check if any manifest item is allocated to THIS reservation
  let allocatedToThis = false;
  if (ev && _lastGeneratedManifest.length) {
    for (const line of _lastGeneratedManifest) {
      if (line.hasSavedAlloc) {
        allocatedToThis = true;
        break;
      }
    }
  }

  const isAllocated = allocatedToThis;
  
  modifyBtn.disabled = false;
  modifyBtn.style.opacity = '1';
  modifyBtn.style.cursor = 'pointer';
  modifyBtn.title = '';
  modifyBtn.textContent = isAllocated ? 'Modify Assign' : 'Assign Allocation';

  const delBtn = document.getElementById('btn-alloc-delete');
  const vModifyBtn = document.getElementById('venue-btn-modify');
  const bModifyBtn = document.getElementById('buffers-btn-modify');

  if (isAllocated) {
    if (delBtn) delBtn.style.display = 'inline-block';
    
    // Lock venue and buffers
    if (vModifyBtn) { vModifyBtn.disabled = true; vModifyBtn.style.opacity = '0.4'; vModifyBtn.style.cursor = 'not-allowed'; vModifyBtn.title = 'Cannot modify while batch is allocated'; }
    if (bModifyBtn) { bModifyBtn.disabled = true; bModifyBtn.style.opacity = '0.4'; bModifyBtn.style.cursor = 'not-allowed'; bModifyBtn.title = 'Cannot modify while batch is allocated'; }
  } else {
    if (delBtn) delBtn.style.display = 'none';
    
    // Unlock venue and buffers
    if (vModifyBtn) { vModifyBtn.disabled = false; vModifyBtn.style.opacity = '1'; vModifyBtn.style.cursor = 'pointer'; vModifyBtn.title = ''; }
    if (bModifyBtn) { bModifyBtn.disabled = false; bModifyBtn.style.opacity = '1'; bModifyBtn.style.cursor = 'pointer'; bModifyBtn.title = ''; }
  }
}

// Enter an allocation mode (auto / manual / modify)
function enterAllocMode(mode) {
  if (!_lastGeneratedManifest.length) { showToast('Generate the manifest first.', 'error'); return; }
  _allocMode = mode;
  window._allocMode = mode;
  window._isAssignAllocationMode = true;
  window._manifestAllocState = {}; // reset so every row auto-allocates to target quantity cleanly
  _renderManifestWithAllocCol(mode);

  // Show/hide action row
  const saveBtn = document.getElementById('btn-alloc-save');
  const cancelBtn = document.getElementById('btn-alloc-cancel');
  const modBtn = document.getElementById('btn-alloc-modify');
  
  if (saveBtn) saveBtn.style.display = 'inline-flex';
  if (cancelBtn) cancelBtn.style.display = 'inline-flex';
  if (modBtn) modBtn.style.display = 'none';
  
  const delBtn = document.getElementById('btn-alloc-delete');
  if (delBtn) delBtn.style.display = 'none';
  
  // Force unlock if modifying
  if (mode === 'modify') {
    const vModifyBtn = document.getElementById('venue-btn-modify');
    const bModifyBtn = document.getElementById('buffers-btn-modify');
    if (vModifyBtn) { vModifyBtn.disabled = false; vModifyBtn.style.opacity = '1'; vModifyBtn.style.cursor = 'pointer'; vModifyBtn.title = ''; }
    if (bModifyBtn) { bModifyBtn.disabled = false; bModifyBtn.style.opacity = '1'; bModifyBtn.style.cursor = 'pointer'; bModifyBtn.title = ''; }
  }
}

// Cancel allocation mode : restore table without the column
function cancelAllocMode() {
  window._abortAllocSave = true;
  _allocMode = null;
  window._isAssignAllocationMode = false;
  if (_lastGeneratedManifest.length) _renderManifestWithAllocCol(null);
  const saveBtn = document.getElementById('btn-alloc-save');
  const cancelBtn = document.getElementById('btn-alloc-cancel');
  const modBtn = document.getElementById('btn-alloc-modify');
  
  if (saveBtn) {
    saveBtn.style.display = 'none';
    saveBtn.textContent = 'Save Allocation';
    saveBtn.disabled = false;
  }
  if (cancelBtn) cancelBtn.style.display = 'none';
  if (modBtn) modBtn.style.display = 'inline-flex';
  
  updateAllocButtons();
}

// Save the allocation to Supabase
window.deleteAllocAssignment = async function() {
  const ev = currentAllocEvent;
  if (!ev) return;
  const sb = window.supabaseClient;
  if (!sb) { showToast('Supabase not available.', 'error'); return; }

  if (!confirm(`Are you sure you want to delete the batch allocation for ${ev.client || 'this reservation'}?`)) {
    return;
  }

  try {
    const equipAssets = (EIM_ASSETS || []).filter(a => !(a.category || '').toLowerCase().includes('decoration'));
    const equipIds = [...new Set(equipAssets.map(a => a.supabaseId || a.id).filter(Boolean))];
    const assetIds = [...new Set(equipAssets.flatMap(a => [a.asset_id, a.id, a.parent_asset_id]).filter(Boolean))];
    
    for (let i = 0; i < equipIds.length; i += 100) {
      await sb.from('allocation_history').delete().eq('reservation_id', ev.id).eq('is_rental', false).in('equipment_id', equipIds.slice(i, i + 100));
    }
    for (let i = 0; i < assetIds.length; i += 100) {
      await sb.from('allocation_history').delete().eq('reservation_id', ev.id).eq('is_rental', false).in('asset_id', assetIds.slice(i, i + 100));
    }

    // Clear lock status
    ev.is_locked = false;
    ev.locked_at = null;

    try {
      await sb.from('reservations').update({ is_locked: false, locked_at: null }).eq('id', ev.id);
    } catch (lockErr) {
      console.warn('[deleteAlloc] Supabase unlock notice:', lockErr);
    }

    const { doc, updateDoc } = window.firebaseFns || {};
    if (doc && updateDoc && window.firebaseDB) {
      try {
        await updateDoc(doc(window.firebaseDB, 'reservations', ev.id), {
          is_locked: false,
          locked_at: null
        });
      } catch (fbErr) {
        console.warn('[deleteAlloc] Firebase unlock notice:', fbErr);
      }
    }

    const resInMem = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(r => r.id === ev.id || String(r.id) === String(ev.id));
    if (resInMem) {
      resInMem.is_locked = false;
      resInMem.locked_at = null;
    }

    if (typeof activeResDetailId !== 'undefined' && (activeResDetailId === ev.id || String(activeResDetailId) === String(ev.id))) {
      const lockedTag = document.getElementById('resd-locked-tag');
      if (lockedTag) lockedTag.style.display = 'none';
      const editBtn = document.getElementById('resd-btn-modify-pkg') || document.getElementById('resd-btn-edit');
      if (editBtn) {
        editBtn.disabled = false;
        editBtn.style.opacity = '1';
        editBtn.style.cursor = 'pointer';
        editBtn.title = '';
      }
    }
    
    showToast('Allocation successfully deleted. Reservation unlocked.', 'success');
    if (typeof setProcSorted === 'function') await setProcSorted(ev.id, 'equipment', false);
    
    _allocMode = null;
    const saveBtn = document.getElementById('btn-alloc-save');
    const cancelBtn = document.getElementById('btn-alloc-cancel');
    const modBtn = document.getElementById('btn-alloc-modify');
    if (saveBtn) {
      saveBtn.style.display = 'none';
      saveBtn.textContent = 'Save Allocation';
      saveBtn.disabled = false;
    }
    if (cancelBtn) cancelBtn.style.display = 'none';
    if (modBtn) modBtn.style.display = 'inline-flex';

    await generateAllocationManifest();
    updateAllocButtons();
    
  } catch (e) {
    console.error('Failed to delete allocation:', e);
    showToast('Failed to delete allocation.', 'error');
  }
};

function saveAllocAssignment() {
  const ev = currentAllocEvent;
  if (!ev || !_lastGeneratedManifest.length) return;

  // Validate that no allocated quantity exceeds current in-stock
  for (let idx = 0; idx < _lastGeneratedManifest.length; idx++) {
    const line = _lastGeneratedManifest[idx];
    const inputEl = document.getElementById(`alloc-qty-input-${idx}`);
    const allocated = inputEl ? (parseInt(inputEl.value, 10) || 0) : (line.hasSavedAlloc ? (parseInt(line.allocatedQty, 10) || 0) : line.finalReq);
    if (allocated > line.inStock) {
      alert(`Allocated quantity for "${line.name}" (${allocated}) cannot be higher than currently in stock (${line.inStock}). Please adjust the quantity.`);
      return;
    }
  }

  const existingModal = document.getElementById('alloc-save-confirm');
  if (existingModal) existingModal.remove();

  // Detect shortages where allocated quantity is less than total required
  const shortages = [];
  _lastGeneratedManifest.forEach((line, idx) => {
    const inputEl = document.getElementById(`alloc-qty-input-${idx}`);
    const allocated = inputEl
      ? (parseInt(inputEl.value, 10) || 0)
      : (line.hasSavedAlloc ? (parseInt(line.allocatedQty, 10) || 0) : Math.min(line.finalReq, line.inStock));
    const required = parseInt(line.finalReq, 10) || 0;
    if (allocated < required) {
      shortages.push({
        name: line.name,
        totalRequired: required,
        allocatedQty: allocated
      });
    }
  });

  if (shortages.length > 0) {
    const confirmDiv = document.createElement('div');
    confirmDiv.id = 'alloc-save-confirm';
    confirmDiv.style.cssText = 'position:fixed;inset:0;z-index:95000;background:rgba(0,0,0,0.75);display:flex;align-items:center;justify-content:center;padding:20px;box-sizing:border-box;';
    
    const rowsHtml = shortages.map(s => `
      <tr style="border-bottom:1px solid var(--border);">
        <td style="padding:8px 12px;font-size:13px;color:var(--cream);text-align:left;">${escHtml(s.name)}</td>
        <td style="padding:8px 12px;font-size:13px;color:var(--text-dim);text-align:center;">${s.totalRequired}</td>
        <td style="padding:8px 12px;font-size:13px;font-weight:700;color:#ef4444;text-align:center;">${s.allocatedQty}</td>
      </tr>
    `).join('');

    confirmDiv.innerHTML = `
      <div style="background:var(--bg2);border:1px solid var(--border);border-radius:16px;padding:28px 32px;max-width:540px;width:100%;box-shadow:0 12px 32px rgba(0,0,0,0.5);">
        <div style="font-size:17px;font-weight:700;color:var(--cream);margin-bottom:10px;">Shortage Detected</div>
        <div style="font-size:13px;line-height:1.6;color:var(--text-mid);margin-bottom:16px;">this allocation has some shortages that are allocated, are we sure we want to force allocate?</div>
        <div style="max-height:220px;overflow-y:auto;border:1px solid var(--border);border-radius:8px;margin-bottom:18px;">
          <table style="width:100%;border-collapse:collapse;">
            <thead>
              <tr style="background:var(--bg3);border-bottom:1px solid var(--border);">
                <th style="padding:8px 12px;font-size:11px;font-weight:700;color:var(--gold);text-transform:uppercase;text-align:left;">Equipment</th>
                <th style="padding:8px 12px;font-size:11px;font-weight:700;color:var(--gold);text-transform:uppercase;text-align:center;">Total Required</th>
                <th style="padding:8px 12px;font-size:11px;font-weight:700;color:var(--gold);text-transform:uppercase;text-align:center;">Qty Allocated</th>
              </tr>
            </thead>
            <tbody>
              ${rowsHtml}
            </tbody>
          </table>
        </div>
        <div style="font-size:13px;font-weight:600;color:var(--cream);margin-bottom:20px;text-align:center;">please confirm</div>
        <div style="display:flex;gap:12px;justify-content:flex-end;">
          <button onclick="document.getElementById('alloc-save-confirm').remove()"
            style="padding:10px 22px;border-radius:8px;border:1px solid var(--border);background:var(--bg3);color:var(--cream);font-size:13px;font-weight:600;cursor:pointer;">
            no
          </button>
          <button id="alloc-save-confirm-yes" onclick="document.getElementById('alloc-save-confirm').remove(); executeSaveAllocAssignment();"
            style="padding:10px 24px;border-radius:8px;border:none;background:var(--gold);color:#000;font-size:13px;font-weight:700;cursor:pointer;">
            yes
          </button>
        </div>
      </div>`;
    document.body.appendChild(confirmDiv);
    return;
  }

  const confirmDiv = document.createElement('div');
  confirmDiv.id = 'alloc-save-confirm';
  confirmDiv.style.cssText = 'position:fixed;inset:0;z-index:95000;background:rgba(0,0,0,0.75);display:flex;align-items:center;justify-content:center;padding:20px;box-sizing:border-box;';
  confirmDiv.innerHTML = `
    <div style="background:var(--bg2);border:1px solid var(--border);border-radius:16px;padding:28px 32px;max-width:480px;width:100%;box-shadow:0 12px 32px rgba(0,0,0,0.5);">
      <div style="font-size:18px;font-weight:700;color:var(--cream);margin-bottom:12px;">Confirm & Lock Allocation</div>
      <div style="font-size:13px;line-height:1.6;color:var(--text-dim);margin-bottom:24px;">Proceeding with this allocation is assumed that all modifications are completely done, this will now lock the reservation's contents apart from some of its details to be completely locked and no longer modifyable as we are nearing the execution day for this reservation. Are we sure we want to proceed?</div>
      <div style="display:flex;gap:12px;justify-content:flex-end;">
        <button onclick="document.getElementById('alloc-save-confirm').remove()"
          style="padding:10px 20px;border-radius:8px;border:1px solid var(--border);background:var(--bg3);color:var(--cream);font-size:13px;font-weight:600;cursor:pointer;">
          No
        </button>
        <button id="alloc-save-confirm-yes" onclick="document.getElementById('alloc-save-confirm').remove(); executeSaveAllocAssignment();"
          style="padding:10px 22px;border-radius:8px;border:none;background:var(--gold);color:#000;font-size:13px;font-weight:700;cursor:pointer;">
          Yes
        </button>
      </div>
    </div>`;
  document.body.appendChild(confirmDiv);
}

async function executeSaveAllocAssignment() {
  const ev = currentAllocEvent;
  if (!ev || !_lastGeneratedManifest.length) return;
  const sb = window.supabaseClient;
  if (!sb) { showToast('Supabase not available.', 'error'); return; }

  const batchName = _genBatchName(ev);
  const evLabel = ev.packageName || ev.client || ev.name || ev.id;
  const saveBtn = document.getElementById('btn-alloc-save');
  const cancelBtn = document.getElementById('btn-alloc-cancel');
  if (saveBtn) { saveBtn.textContent = 'Saving...'; saveBtn.disabled = true; }
  if (cancelBtn) { cancelBtn.disabled = true; }

  // Check if save was aborted
  window._abortAllocSave = false;

  // Load existing rental order to check for decreased rentals later
  let existingRentalOrder = null;
  if (typeof _loadRentalOrderForRes === 'function') {
    existingRentalOrder = await _loadRentalOrderForRes(ev.id);
  }

  let anyError = false;
  // Replace this reservation's equipment history so a new save overrides the old batch
  // (not just rows whose equipment_id happens to match EIM_ASSETS).
  try {
    const equipAssets = (EIM_ASSETS || []).filter(a => !(a.category || '').toLowerCase().includes('decoration'));
    const equipIds = [...new Set(equipAssets.map(a => a.supabaseId || a.id).filter(Boolean))];
    const assetIds = [...new Set(equipAssets.flatMap(a => [a.asset_id, a.id, a.parent_asset_id]).filter(Boolean))];
    for (let i = 0; i < equipIds.length; i += 100) {
      await sb.from('allocation_history').delete().eq('reservation_id', ev.id).eq('is_rental', false).in('equipment_id', equipIds.slice(i, i + 100));
    }
    for (let i = 0; i < assetIds.length; i += 100) {
      await sb.from('allocation_history').delete().eq('reservation_id', ev.id).eq('is_rental', false).in('asset_id', assetIds.slice(i, i + 100));
    }
  } catch (e) { console.warn('[AllocSave] Pre-save history clear failed:', e); }
  try {
    const updatePromises = [];
    const historyInserts = [];
    
    let otherAllocs = [];
    try {
      const formatResDate = (dStr) => {
        if (!dStr) return null;
        const d = new Date(dStr);
        if (!isNaN(d.getTime())) return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
        return dStr;
      };
      const evD = formatResDate(ev.date || ev.eventDate);
      const sameDateResIds = evD ? (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).filter(r => formatResDate(r.date || r.eventDate) === evD && r.id !== ev.id).map(r => r.id) : [];
      const { data } = await sb
        .from('allocation_history')
        .select('asset_id,allocated_qty,reservation_id,allocation_batch,is_rental,recorded_at')
        .in('reservation_id', [ev.id, ...sameDateResIds]);
      if (data) otherAllocs = data.filter(r => r.reservation_id !== ev.id && !r.is_rental);
    } catch (e) {}

    // Check consumable column from public.equipment_inventory for assets in manifest
    const consumableMap = {};
    try {
      const invIds = _lastGeneratedManifest.map(l => {
        const a = window.findAssetForRule({ name: l.name, assetId: l.assetId });
        return a ? (a.supabaseId || a.id) : null;
      }).filter(Boolean);
      if (invIds.length > 0 && sb) {
        const { data: invCons } = await sb.from('equipment_inventory').select('id, consumable').in('id', invIds);
        if (invCons) {
          invCons.forEach(c => { consumableMap[c.id] = !!c.consumable; });
        }
      }
    } catch(e) {
      console.warn('[AllocSave] consumable query failed:', e);
    }

    for (let idx = 0; idx < _lastGeneratedManifest.length; idx++) {
      if (window._abortAllocSave) throw new Error('aborted');
      const line = _lastGeneratedManifest[idx];
      // Skip rental-only lines (no real inventory asset)
      if (line.rentalQty > 0 && line.inStock === 0) continue;
      const asset = window.findAssetForRule({ name: line.name, assetId: line.assetId });
      if (!asset || !asset.supabaseId) continue;

      const isConsumable = (asset.supabaseId && consumableMap[asset.supabaseId] !== undefined)
        ? consumableMap[asset.supabaseId]
        : (asset.consumable === true);

      const inputEl = document.getElementById(`alloc-qty-input-${idx}`);
      // When input exists, read it; when not (view-only mode), prefer the already-saved
      // allocatedQty over finalReq to avoid overwriting a previously set quantity.
      const qty = inputEl
        ? Math.min(parseInt(inputEl.value) || 0, line.inStock)
        : (line.hasSavedAlloc
            ? Math.min(line.allocatedQty, line.inStock)
            : Math.min(line.finalReq, line.inStock));

      // Now that manifest rows are split strictly by exact batch, we don't need to distribute
      // across the family anymore. We just assign exactly to the asset identified by line.assetId
      const familyUpdates = new Map();
      
      // Clear previous assignment for this exact asset if it was assigned
      if (asset.allocatedReservationId === ev.id || asset.allocated_reservation_id === ev.id) {
        familyUpdates.set(asset, {
          allocated_qty: 0,
          allocation_batch: null,
          allocated_to: null,
          allocated_reservation_id: null,
          allocation_date: null
        });
      }

      if (qty > 0) {
        familyUpdates.set(asset, {
          allocated_qty: qty,
          allocation_batch: batchName,
          allocated_to: evLabel,
          allocated_reservation_id: ev.id,
          allocation_date: ev.date || ev.eventDate || null
        });
        
        let allocatedItemCodes = [];
        const cleanAId = (asset.id || asset.asset_id || '').trim();
        if (window._manifestAllocState && window._manifestAllocState[cleanAId]) {
          allocatedItemCodes = window._manifestAllocState[cleanAId].filter(u => u.allocatedQty > 0).map(u => u.item_code);
          try {
            if (allocatedItemCodes.length > 0) {
              await sb.from('equipment_unit_items').update({
                status: 'Allocated',
                allocation_batch: batchName,
                allocated_reservation_id: ev.id,
                allocated_date: new Date().toISOString()
              }).in('item_code', allocatedItemCodes);
            }
          } catch(eUnitUp) {
            console.warn('[Alloc] Unit persistence notice:', eUnitUp);
          }
        } else if (typeof window.HalServeUnitTracker?.allocateUnitsFIFO === 'function') {
          try {
            allocatedItemCodes = await window.HalServeUnitTracker.allocateUnitsFIFO(
              cleanAId,
              qty,
              ev.id,
              batchName
            );
          } catch(eAlloc) {
            console.warn('[Alloc] FIFO allocation error:', eAlloc);
          }
        }

        historyInserts.push({
          equipment_id: asset.supabaseId,
          asset_id: asset.id || asset.asset_id,
          equipment_name: asset.name,
          allocation_batch: batchName,
          reservation_id: ev.id,
          reservation_name: evLabel,
          allocation_date: ev.date || ev.eventDate || null,
          allocated_qty: qty,
          unit_type: asset.unit_type || asset.unitType || 'pcs',
          is_rental: false,
          consumable: isConsumable,
          allocated_item_ids: allocatedItemCodes
        });
      }

      for (const [famAsset, payload] of familyUpdates.entries()) {
        const updatePromise = sb
          .from('equipment_inventory')
          .update(payload)
          .eq('id', famAsset.supabaseId)
          .then(({ error }) => {
            if (error) {
              console.error('[AllocSave] Supabase update failed:', error);
              anyError = true;
            } else {
              famAsset.allocatedQty = payload.allocated_qty;
              famAsset.allocationBatch = payload.allocation_batch;
              famAsset.allocatedTo = payload.allocated_to;
              famAsset.allocatedReservationId = payload.allocated_reservation_id;
              famAsset.allocated_reservation_id = payload.allocated_reservation_id;
            }
          });
        updatePromises.push(updatePromise);
      }

      if (line.venueProv > 0) {
        historyInserts.push({
          equipment_id: asset.supabaseId,
          asset_id: asset.asset_id || asset.id,
          equipment_name: line.name,
          allocation_batch: 'VENUE-' + batchName,
          reservation_id: ev.id,
          reservation_name: evLabel,
          allocation_date: ev.date || ev.eventDate || null,
          allocated_qty: line.venueProv,
          unit_type: asset.unit_type || asset.unitType || 'pcs',
          is_rental: false,
          consumable: isConsumable
        });
      }
    }

    // Execute all updates concurrently
    await Promise.all(updatePromises);
    
    // Bulk insert history
    if (historyInserts.length > 0) {
      const { error: histErr } = await sb.from('allocation_history').insert(historyInserts);
      if (histErr) console.warn('[AllocHistory] Bulk insert failed:', histErr);
    }

    // Save rental items to allocation_history with is_rental: true
    if (typeof saveRentalAllocItems === 'function') {
      await saveRentalAllocItems(ev, batchName);
    }

    if (anyError) {
      showToast('Some items failed to save. Check console.', 'error');
    } else {
      const modBanner = document.getElementById('alloc-modification-banner');
      if (modBanner) modBanner.style.display = 'none';

      // Clear venue_mod flag if it exists
      localStorage.removeItem('venue_mod_' + ev.id);

      if (modBanner) modBanner.style.display = 'none';

      // Clear venue_mod flag if it exists
      localStorage.removeItem('venue_mod_' + ev.id);

      // Comprehensive Admin Activity Logging for equipment allocation
      try {
        if (typeof window.logAdminActivity === 'function') {
          window.logAdminActivity(
            'Allocated Equipment Assets',
            `Allocated equipment assets for reservation #${ev.id} (${evLabel}) - Batch: ${batchName}.`,
            { category: 'Equipment Assets', reservation_id: ev.id, client_name: evLabel, batch: batchName }
          );
        }
      } catch (_logErr) {
        console.warn('Logging saveAllocAssignment failed:', _logErr);
      }

      // Lock reservation
      ev.is_locked = true;
      ev.locked_at = new Date().toISOString();

      try {
        await sb.from('reservations').update({ is_locked: true, locked_at: ev.locked_at }).eq('id', ev.id);
      } catch (lockErr) {
        console.warn('[saveAlloc] Supabase lock notice:', lockErr);
      }

      const { doc, updateDoc } = window.firebaseFns || {};
      if (doc && updateDoc && window.firebaseDB) {
        try {
          await updateDoc(doc(window.firebaseDB, 'reservations', ev.id), {
            is_locked: true,
            locked_at: ev.locked_at
          });
        } catch (fbErr) {
          console.warn('[saveAlloc] Firebase lock notice:', fbErr);
        }
      }

      const resInMem = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(r => r.id === ev.id || String(r.id) === String(ev.id));
      if (resInMem) {
        resInMem.is_locked = true;
        resInMem.locked_at = ev.locked_at;
      }

      if (typeof activeResDetailId !== 'undefined' && (activeResDetailId === ev.id || String(activeResDetailId) === String(ev.id))) {
        const lockedTag = document.getElementById('resd-locked-tag');
        if (lockedTag) lockedTag.style.display = 'inline-flex';
        const editBtn = document.getElementById('resd-btn-modify-pkg') || document.getElementById('resd-btn-edit');
        if (editBtn) {
          editBtn.disabled = true;
          editBtn.style.opacity = '0.5';
          editBtn.style.cursor = 'not-allowed';
          editBtn.title = 'Reservation is locked because equipment allocations have been assigned.';
        }
        if (typeof resdModifyMode !== 'undefined' && resdModifyMode) {
          resdModifyMode = false;
          const saveModBtn = document.getElementById('resd-btn-save-mod');
          if (saveModBtn) saveModBtn.style.display = 'none';
          const curRes = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(r => r.id === activeResDetailId || String(r.id) === String(activeResDetailId));
          if (curRes && typeof renderReservationDetailContent === 'function') {
            renderReservationDetailContent(curRes);
          }
        }
      }

      if (typeof recordEIMLog === 'function') {
        recordEIMLog({
          action: 'Assigned Batch Allocation',
          eqId: batchName,
          eqName: evLabel,
          details: `Assigned and locked equipment allocation for reservation "${evLabel}" (Batch: ${batchName}).`
        });
      }

      showToast(`Allocation saved! Batch: ${batchName}`);
      if (typeof setProcSorted === 'function') await setProcSorted(ev.id, 'equipment', true); // Auto-sort equipment in resource prep

      _allocMode = null;
      if (saveBtn) {
        saveBtn.style.display = 'none';
        saveBtn.textContent = 'Save Allocation';
        saveBtn.disabled = false;
      }
      if (cancelBtn) cancelBtn.style.display = 'none';
      const modBtn = document.getElementById('btn-alloc-modify');
      if (modBtn) modBtn.style.display = 'inline-flex';

      await generateAllocationManifest();
      updateAllocButtons();
    }
  } catch (err) {
    if (err.message === 'aborted') {
      showToast('Save aborted.', 'warning');
    } else {
      console.error('[AllocSave] Unexpected error:', err);
      showToast('Save failed: ' + (err.message || 'Unknown error'), 'error');
    }
  } finally {
    // Always restore the button : no matter what threw
    const cancelBtn = document.getElementById('btn-alloc-cancel');
    if (saveBtn) { saveBtn.textContent = 'Save Allocation'; saveBtn.disabled = false; }
    if (cancelBtn) { cancelBtn.disabled = false; }
  }
}

// ====================================================================
// VENUE EQUIPMENT (SUPABASE MIGRATION)
// ====================================================================

window.currentVenueEquipmentMap = {};

window.isVenueEditMode = false;

window.toggleVenueEditAll = function(show) {
  window.isVenueEditMode = show;
  const btnMod = document.getElementById('venue-btn-modify');
  const btnApp = document.getElementById('venue-btn-apply');
  const btnCan = document.getElementById('venue-btn-cancel');
  if (btnMod) btnMod.style.display = show ? 'none' : 'inline-block';
  if (btnApp) btnApp.style.display = show ? 'inline-block' : 'none';
  if (btnCan) btnCan.style.display = show ? 'inline-block' : 'none';
  renderVenueEquipmentList(document.getElementById('venue-equipment-search')?.value || '');
};

window.applyVenueEditAll = async function() {
  const inputs = document.querySelectorAll('.venue-qty-inp');
  inputs.forEach(inp => {
    const assetId = inp.getAttribute('data-id');
    const val = parseInt(inp.value) || 0;
    if (val > 0) {
      window.currentVenueEquipmentMap[assetId] = val;
    } else {
      delete window.currentVenueEquipmentMap[assetId];
    }
  });
  
  await saveVenueEquipmentToDb();
  generateAllocationManifest(); // Recalculate manifest
  toggleVenueEditAll(false);
};

window.renderVenueEquipmentList = function(filterText = '') {
  if (typeof filterText !== 'string') filterText = '';
  const searchInput = document.getElementById('venue-equipment-search');
  const search = (filterText || (searchInput ? searchInput.value : '')).toLowerCase().trim();
  
  const listEl = document.getElementById('venue-equipment-list');
  if (!listEl) return;
  
  if (!currentAllocEvent) {
    listEl.innerHTML = '<div style="padding:24px;text-align:center;color:var(--text-dim);font-size:13px;">Select an active reservation to load venue equipment</div>';
    return;
  }

  // If manifest not populated yet, trigger generation to auto-fill
  if (!_lastGeneratedManifest || _lastGeneratedManifest.length === 0) {
    if (typeof generateAllocationManifest === 'function') {
      generateAllocationManifest();
    }
    return;
  }
  
  // Deduplicate manifest by parent assetId to get the base requirement items
  const uniqueItems = [];
  const seenAssets = new Map();
  
  _lastGeneratedManifest.forEach(line => {
    let parentId = line.assetId;
    const asset = window.findAssetForRule({ assetId: line.assetId }) || window.findAssetForRule({ name: line.name });
    if (asset && asset.parent_asset_id) parentId = asset.parent_asset_id;
    
    if (seenAssets.has(parentId)) {
      seenAssets.get(parentId).exactReq += (line.exactReq || line.needed || 0);
      return;
    }
    const mergedLine = { ...line, assetId: parentId, exactReq: (line.exactReq || line.needed || 0) };
    seenAssets.set(parentId, mergedLine);
    uniqueItems.push(mergedLine);
  });
  
  // Sort: Items with venue provided > 0 at top, then alphabetical
  uniqueItems.sort((a, b) => {
    const aProv = parseInt(window.currentVenueEquipmentMap[a.assetId]) || 0;
    const bProv = parseInt(window.currentVenueEquipmentMap[b.assetId]) || 0;
    if (aProv > 0 && bProv === 0) return -1;
    if (bProv > 0 && aProv === 0) return 1;
    return (a.name || '').localeCompare(b.name || '');
  });
  
  let html = '';
  uniqueItems.forEach(line => {
    if (search && !(line.name || '').toLowerCase().includes(search) && !(line.assetId || '').toLowerCase().includes(search)) return;
    
    const prov = parseInt(window.currentVenueEquipmentMap[line.assetId]) || 0;
    const req = line.exactReq || 0;
    
    html += `
      <div class="req-item" style="display:flex; justify-content:space-between; align-items:center; padding:12px 16px; background:rgba(255,255,255,0.02); border:1px solid rgba(255,255,255,0.06); border-radius:8px; margin-bottom:8px;">
        <div class="req-info" style="flex:1;">
          <span class="req-name" style="font-weight:600; font-size:13px; display:block; color:var(--text);">${escHtml(line.name)}</span>
          <span class="req-cat" style="font-size:11px; color:var(--text-dim); margin-top:2px; display:block;">${escHtml(line.assetId)} &bull; ${req} Total Required</span>
        </div>
        <div style="display:flex; align-items:center; gap:12px;">
          ${window.isVenueEditMode 
            ? `<input type="number" class="venue-qty-inp" data-id="${line.assetId}" value="${prov}" min="0" max="999" style="width:70px; padding:6px 10px; border:1px solid var(--border); border-radius:6px; background:var(--bg); color:var(--text); font-size:13px; font-weight:600; text-align:center;" oninput="this.value=this.value.slice(0,3)">`
            : `<div style="font-weight:700; font-size:15px; color:${prov > 0 ? 'var(--green)' : 'var(--text-dim)'}; min-width:30px; text-align:right;">${prov > 0 ? prov : '&mdash;'}</div>`
          }
        </div>
      </div>
    `;
  });
  
  if (!html) html = '<div style="padding:24px;text-align:center;color:var(--text-dim);font-size:13px;">No equipment found matching filter.</div>';
  listEl.innerHTML = html;
};

// --- Deployment Standards Edit Mode ---
// (Buffer edit functionality removed, now driven by extra_buffer)
async function saveVenueEquipmentToDb() {
  if (!currentAllocEvent || !window.supabaseClient) return;
  const ev = currentAllocEvent;
  const sb = window.supabaseClient;
  
  const ai = document.getElementById('venue-autofill-status');
  if (ai) { ai.textContent = 'Saving...'; ai.style.display = 'inline-block'; ai.style.color = 'var(--text-dim)'; }
  
  const itemsArr = Object.keys(window.currentVenueEquipmentMap).map(assetId => ({
    assetId: assetId,
    quantity: window.currentVenueEquipmentMap[assetId]
  }));
  
  const payload = {
    reservation_id: ev.id,
    items: itemsArr,
    saved_at: new Date().toISOString()
  };
  
  const { error } = await sb.from('venue_equipment').upsert(payload, { onConflict: 'reservation_id' });
  
  if (error) {
    console.error('Venue Equipment save failed:', error);
    if (ai) { ai.textContent = 'Failed to save'; ai.style.color = 'var(--red)'; }
  } else {
    if (ai) { ai.textContent = 'Saved ✓'; ai.style.color = 'var(--green)'; }
  }
}

async function loadVenueEquipment(eventId) {
  window.currentVenueEquipmentMap = {};
  if (!window.supabaseClient) return;
  const sb = window.supabaseClient;
  
  const ai = document.getElementById('venue-autofill-status');
  if (ai) { ai.textContent = 'Loading...'; ai.style.display = 'inline-block'; ai.style.color = 'var(--text-dim)'; }

  const { data, error } = await sb
    .from('venue_equipment')
    .select('*')
    .eq('reservation_id', eventId)
    .maybeSingle();

  if (error || !data) {
    if (ai) ai.style.display = 'none';
    renderVenueEquipmentList();
    if (typeof generateAllocationManifest === 'function') generateAllocationManifest();
    return;
  }

  if (data.items && Array.isArray(data.items)) {
    data.items.forEach(item => {
      let finalId = item.assetId;
      const asset = typeof window.findAssetForRule === 'function' ? window.findAssetForRule({ assetId: finalId }) : null;
      if (asset && asset.parent_asset_id) {
        finalId = asset.parent_asset_id;
      }
      window.currentVenueEquipmentMap[finalId] = (window.currentVenueEquipmentMap[finalId] || 0) + (parseInt(item.quantity) || 0);
    });
  } else {
    // Fallback for legacy columns
    const legacy = ['tables', 'chairs', 'chafing', 'dispensers', 'plates', 'forks', 'spoons', 'knives', 'glasses'];
    // Cannot accurately map legacy without asset IDs, but we can assume they migrate it manually or they no longer exist.
  }

  if (ai) { ai.textContent = 'Auto-filled from saved venue data ✓'; ai.style.color = 'var(--green)'; }
  renderVenueEquipmentList();
  if (typeof generateAllocationManifest === 'function') generateAllocationManifest();
}

async function applyVenueEquipment() {
  await saveVenueEquipmentToDb();
  generateAllocationManifest();
}

async function removeVenueEquipment() {
  window.currentVenueEquipmentMap = {};
  await saveVenueEquipmentToDb();
  generateAllocationManifest();
  renderVenueEquipmentList();
}

window.applyVenueEquipment = applyVenueEquipment;
window.removeVenueEquipment = removeVenueEquipment;
window.loadVenueEquipment = loadVenueEquipment;

