let currentDecoFilter = 'all';

window.switchAllocSubTab = function (subTab, btn) {
  document.querySelectorAll('#alloc-subtab-equipments').forEach(b => b.classList.toggle('active', subTab === 'equipments'));
  document.querySelectorAll('#alloc-subtab-decorations').forEach(b => b.classList.toggle('active', subTab === 'decorations'));

  document.querySelectorAll('#alloc-subpnl-equipments').forEach(p => p.style.display = subTab === 'equipments' ? 'block' : 'none');
  document.querySelectorAll('#alloc-subpnl-decorations').forEach(p => p.style.display = subTab === 'decorations' ? 'block' : 'none');

  if (subTab === 'decorations') {
    renderDecorationAllocationPanel();
  }
};

window.filterDecoSubCategory = function (cat, btn) {
  currentDecoFilter = cat;
  if (btn && btn.parentElement) {
    btn.parentElement.querySelectorAll('button').forEach(b => b.classList.remove('active'));
    btn.classList.add('active');
  }
  renderDecoEquipmentTable();
};

window.renderDecorationAllocationPanel = async function () {
  const ev = currentAllocEvent || (RESERVATIONS && RESERVATIONS.find(r => r.id === currentEqcReservationId));
  const designContainers = document.querySelectorAll('#alloc-deco-design-container');
  const inventoryContainers = document.querySelectorAll('#alloc-deco-inventory-container');

  if (!designContainers.length && !inventoryContainers.length) return;

  if (!ev) {
    const emptyHTML = `
      <div class="panel" style="background:var(--bg3); padding:40px; text-align:center; border:1px solid var(--border); border-radius:12px;">
        <div style="font-size:16px; font-weight:700; color:var(--gold); margin-bottom:8px;">No Reservation Selected</div>
        <div style="font-size:13px; color:var(--text-dim);">Please choose a confirmed reservation from the active dropdown above to view customer design selections and allocate decoration equipment.</div>
      </div>
    `;
    designContainers.forEach(c => c.innerHTML = emptyHTML);
    inventoryContainers.forEach(c => c.innerHTML = '');
    return;
  }

  designContainers.forEach(c => c.innerHTML = `<div style="text-align:center; padding:30px; color:var(--text-dim); font-size:13px;">Loading customer design requirements...</div>`);

  let decorData = [];
  let uploadedPhotos = [];

  try {
    const sb = window.supabaseClient;
    if (sb) {
      const { data: dData } = await sb
        .from('reservation_decorations')
        .select('*')
        .eq('reservation_id', ev.id)
        .order('created_at', { ascending: false });
      if (dData) decorData = dData;

      const { data: mtRows } = await sb
        .from('meetings')
        .select('shared_documents')
        .or(`reservation_id.eq.${ev.id},reservationId.eq.${ev.id}`);
      if (mtRows) {
        const seen = new Set();
        mtRows.forEach(row => {
          (row.shared_documents || []).forEach(doc => {
            if (doc && doc.url && (doc.agenda === 'design' || doc.agenda !== 'res') && !seen.has(doc.url)) {
              seen.add(doc.url);
              uploadedPhotos.push(doc);
            }
          });
        });
      }
      
      // Also grab from memory (Firebase) if it hasn't synced to Supabase yet
      if (window.MEETINGS && window.MEETINGS.length > 0) {
        window.MEETINGS
          .filter(m => m.reservationId === ev.id || m.reservation_id === ev.id)
          .forEach(m => {
            (m.sharedDocuments || m.shared_documents || []).forEach(doc => {
              if (doc && doc.url && (doc.agenda === 'design' || doc.agenda !== 'res') && !seen.has(doc.url)) {
                seen.add(doc.url);
                uploadedPhotos.push(doc);
              }
            });
          });
      }
    }
  } catch (e) {
    console.warn('[renderDecorationAllocationPanel] Error loading design data:', e);
  }

  const latestByItem = {};
  decorData.forEach(d => { if (!latestByItem[d.item_name]) latestByItem[d.item_name] = d; });
  const selectedDecos = Object.values(latestByItem);

  let designHTML = `
    <div class="panel" style="background:var(--bg3); padding:24px; border:1px solid var(--border); border-radius:12px;">
      <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:16px; flex-wrap:wrap; gap:10px;">
        <div>
          <div style="font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:1.5px; color:var(--gold);">Customer Design Specifications & Reference Photos</div>
          <div style="font-size:15px; font-weight:700; color:var(--cream); margin-top:2px;">${ev.name || 'Reservation #' + ev.id} &bull; ${ev.theme || 'Custom Theme'} (${ev.occasion || 'Event'})</div>
        </div>
        <span style="font-size:12px; font-weight:700; color:var(--gold);">
          ${selectedDecos.length} Decor Selection(s) &bull; ${uploadedPhotos.length} Photo(s)
        </span>
      </div>
  `;

  if (selectedDecos.length === 0) {
    designHTML += `<div style="font-size:13px; color:var(--text-dim); font-style:italic; padding:12px 0;">No specific design assessment items selected by customer.</div>`;
  } else {
    designHTML += `
      <div style="display:grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap:14px; margin-bottom:16px;">
        ${selectedDecos.map(item => `
          <div style="display:flex; gap:12px; padding:12px; background:var(--bg2); border:1px solid var(--border); border-radius:8px;">
            <div style="width:60px; height:60px; flex-shrink:0; background:var(--bg3); border-radius:6px; overflow:hidden; display:flex; align-items:center; justify-content:center;">
              ${(() => {
                let imgUrl = item.selected_image_url;
                if (imgUrl && imgUrl.startsWith('http')) {
                  return `<img src="${imgUrl}" style="width:100%; height:100%; object-fit:contain; background:#ffffff; padding:2px; box-sizing:border-box;" />`;
                }
                if (imgUrl) {
                  const catItem = (typeof sbMenuItems !== 'undefined' ? sbMenuItems.find(c => c.name === item.item_name) : null) || (typeof CAT !== 'undefined' ? CAT.find(c => c.name === item.item_name) : null);
                  let opts = catItem ? (Array.isArray(catItem.options) ? catItem.options : (typeof catItem.options === 'string' ? JSON.parse(catItem.options || '[]') : [])) : [];
                  if (opts.length === 0 && catItem && catItem.ingredients && typeof catItem.ingredients === 'string' && catItem.ingredients.includes('| options:')) {
                    try {
                      const parsed = JSON.parse(catItem.ingredients.split('| options:')[1].trim());
                      if (Array.isArray(parsed)) opts = parsed;
                    } catch (e) {}
                  }
                  let matchedOpt = null;
                  if (imgUrl.startsWith('Option ')) {
                    const optIdx = parseInt(imgUrl.replace('Option ', '')) - 1;
                    if (opts[optIdx] && opts[optIdx].image_url) matchedOpt = opts[optIdx];
                  }
                  if (!matchedOpt) matchedOpt = opts.find(o => o.title === imgUrl || o.image_url === imgUrl);
                  if (matchedOpt && matchedOpt.image_url) {
                    return `<img src="${matchedOpt.image_url}" style="width:100%; height:100%; object-fit:contain; background:#ffffff; padding:2px; box-sizing:border-box;" />`;
                  }
                  return `<span style="font-size:10px; color:var(--gold); font-weight:700; text-align:center; padding:4px;">${escHtml(imgUrl)}</span>`;
                }
                return '<span style="font-size:10px; color:var(--text-dim);">ITEM</span>';
              })()}
            </div>
            <div>
              <div style="font-size:15px; font-weight:700; color:var(--cream);">${item.item_name}</div>
              <div style="font-size:13px; color:var(--text-mid); font-style:italic; margin-top:3px;">"${item.notes || 'No specific notes.'}"</div>
            </div>
          </div>
        `).join('')}
      </div>
    `;
  }

  if (uploadedPhotos.length > 0) {
    designHTML += `
      <div style="border-top:1px solid var(--border); padding-top:16px; margin-top:12px;">
        <div style="font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:1px; color:var(--gold); margin-bottom:10px;">Reference Photos Uploaded by Customer</div>
        <div style="display:grid; grid-template-columns: repeat(auto-fill, minmax(130px, 1fr)); gap:12px;">
          ${uploadedPhotos.map(p => `
            <a href="${p.url}" target="_blank" style="display:block; border:1px solid var(--border); border-radius:6px; overflow:hidden; background:var(--bg2);">
              <img src="${p.url}" style="width:100%; height:120px; object-fit:contain; background:#ffffff; padding:4px; box-sizing:border-box;" />
              <div style="font-size:11px; color:var(--text-dim); padding:6px; text-align:center; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${p.name || 'Photo'}</div>
            </a>
          `).join('')}
        </div>
      </div>
    `;
  }

  designHTML += `</div>`;
  designContainers.forEach(c => c.innerHTML = designHTML);

  renderDecoEquipmentTable();
};

window._isDecoEditMode = false;

window.renderDecoEquipmentTable = async function () {
  const containers = document.querySelectorAll('#alloc-deco-inventory-container');
  if (!containers.length) return;

  const ev = currentAllocEvent || (RESERVATIONS && RESERVATIONS.find(r => r.id === currentEqcReservationId));
  if (!ev) return;

  let decos = (EIM_ASSETS || []).filter(a => (a.category || '').toLowerCase().includes('decoration'));

  if (currentDecoFilter === 'cloths') {
    decos = decos.filter(a => (a.type || '').toLowerCase().includes('cloth'));
  } else if (currentDecoFilter === 'lighting') {
    decos = decos.filter(a => (a.type || '').toLowerCase().includes('light'));
  } else if (currentDecoFilter === 'misc') {
    decos = decos.filter(a => !(a.type || '').toLowerCase().includes('cloth') && !(a.type || '').toLowerCase().includes('light'));
  }

  // Calculate Date-Based Availability
  const eventDate = ev.date || ev.eventDate || null;
  const dateAllocatedMap = {};
  
  if (eventDate && window.supabaseClient) {
    try {
      const { data: dateHist, error: dateErr } = await window.supabaseClient
        .from('allocation_history')
        .select('equipment_id, allocated_qty, reservation_id')
        .eq('allocation_date', eventDate);
        
      if (!dateErr && dateHist) {
        dateHist.forEach(r => {
          if (r.reservation_id !== ev.id) {
            dateAllocatedMap[r.equipment_id] = (dateAllocatedMap[r.equipment_id] || 0) + (r.allocated_qty || 0);
          }
        });
      }
    } catch (e) {
      console.warn('[renderDecoEquipmentTable] Error fetching date availability:', e);
    }
  }

  // Check if current reservation already has allocations
  let hasAnyAllocations = false;
  decos.forEach(asset => {
    if (asset.allocatedReservationId === ev.id && (asset.allocatedQty || 0) > 0) {
      hasAnyAllocations = true;
    }
  });

  // If there are no existing allocations, default to edit mode
  if (!hasAnyAllocations) {
    window._isDecoEditMode = true;
  }

  let html = `
    <div class="panel" style="background:var(--bg2); border:1px solid var(--border); border-radius:12px; overflow:hidden;">
      <div class="panel-hdr" style="flex-wrap:wrap; gap:12px; padding:16px 20px; background:var(--bg3);">
        <div>
          <div class="panel-title" style="font-size:15px;">Decoration Equipment Allocation</div>
          <div class="panel-sub" style="color:var(--cream);">Select quantities of decorative cloths, lighting, and props for this reservation</div>
        </div>
        <div style="display:flex; gap:12px; align-items:center; flex-wrap:wrap;">
          <div class="eim-cat-filter">
            <button class="btn-outline ${currentDecoFilter === 'all' ? 'active' : ''}" style="font-size:11px; padding:4px 12px;" onclick="filterDecoSubCategory('all', this)">All Decor (${(EIM_ASSETS || []).filter(a => (a.category || '').toLowerCase().includes('decoration')).length})</button>
            <button class="btn-outline ${currentDecoFilter === 'cloths' ? 'active' : ''}" style="font-size:11px; padding:4px 12px;" onclick="filterDecoSubCategory('cloths', this)">Cloths</button>
            <button class="btn-outline ${currentDecoFilter === 'lighting' ? 'active' : ''}" style="font-size:11px; padding:4px 12px;" onclick="filterDecoSubCategory('lighting', this)">Lighting</button>
            <button class="btn-outline ${currentDecoFilter === 'misc' ? 'active' : ''}" style="font-size:11px; padding:4px 12px;" onclick="filterDecoSubCategory('misc', this)">Misc Decor</button>
          </div>
          ${!window._isDecoEditMode ? `
             <button class="btn-outline" onclick="window._isDecoEditMode = true; renderDecoEquipmentTable();" style="padding:8px 20px; font-size:12px;">Edit Allocation</button>
          ` : `
             <button class="btn-outline" onclick="window._isDecoEditMode = false; renderDecoEquipmentTable();" style="padding:8px 20px; font-size:12px;">Cancel</button>
             <button class="btn-primary" onclick="saveDecorationAllocation()" style="padding:8px 20px; font-size:12px;">Save Decoration Allocation</button>
          `}
        </div>
      </div>
      <div class="panel-body" style="padding:0; overflow-x:auto;">
        <table class="inv-table">
          <thead>
            <tr>
              <th>Decoration Asset</th>
              <th>Category & Type</th>
              <th style="text-align:center;">Total Stock</th>
              <th style="text-align:center;">Available</th>
              <th style="text-align:center;">Allocated</th>
              ${window._isDecoEditMode ? `<th style="text-align:center;">Action</th>` : ''}
            </tr>
          </thead>
          <tbody>
  `;

  if (decos.length === 0) {
    html += `<tr><td colspan="${window._isDecoEditMode ? '6' : '5'}" style="text-align:center; padding:30px; color:var(--text-dim); font-size:13px;">No decoration assets found in inventory. Add decoration items in Equipment Assets tab.</td></tr>`;
  } else {
    decos.forEach(asset => {
      const othersAllocQty = dateAllocatedMap[asset.supabaseId || asset.id] || 0;
      const maxQty = asset.quantity || asset.totalQty || asset.total_qty || 0;
      // Date-based availability instead of global availability
      const availQty = Math.max(0, maxQty - (asset.maintenanceQty || 0) - (asset.retiredQty || 0) - othersAllocQty);
      const currentAllocQty = (asset.allocatedReservationId === ev.id) ? (asset.allocatedQty || 0) : 0;
      const isAllocated = currentAllocQty > 0;

      html += `
        <tr>
          <td>
            <div style="display:flex; align-items:center; gap:10px;">
              ${asset.imageUrl && asset.imageUrl.startsWith('http') ? `
              <div style="width:36px; height:36px; border-radius:6px; background:var(--bg3); border:1px solid var(--border); overflow:hidden; display:flex; align-items:center; justify-content:center; flex-shrink:0;">
                <img src="${asset.imageUrl}" style="width:100%; height:100%; object-fit:contain; background:#ffffff; padding:2px; box-sizing:border-box;" />
              </div>` : ''}
              <div>
                <div class="item-name" style="font-size:13px; font-weight:700;">${asset.name}</div>
                <div class="item-cat" style="font-size:11px;">ID: ${asset.asset_id || asset.id}</div>
              </div>
            </div>
          </td>
          <td>
            <span class="badge pending" style="font-size:10px;">${asset.category || 'Decoration'}</span>
            ${asset.type ? `<span style="font-size:11px; color:var(--text-dim); margin-left:6px;">(${asset.type})</span>` : ''}
          </td>
          <td style="text-align:center; font-weight:700;">${maxQty} ${asset.unitType || 'pcs'}</td>
          <td style="text-align:center; font-weight:700; color:${availQty > 0 ? 'var(--green)' : 'var(--red)'};">${availQty} ${asset.unitType || 'pcs'}</td>
          <td style="text-align:center; font-weight:700; color:${isAllocated ? 'var(--gold)' : 'var(--text-dim)'};">${currentAllocQty} ${asset.unitType || 'pcs'}</td>
          ${window._isDecoEditMode ? `
          <td style="text-align:center;">
               <div style="display:flex; justify-content:center; align-items:center; gap:6px;">
                 <input type="number" id="deco-input-${asset.supabaseId || asset.id}" min="0" max="${availQty}" value="${currentAllocQty}" oninput="if(parseInt(this.value) > parseInt(this.max)) this.value = this.max;"
                  style="width:80px; padding:6px 10px; background:var(--bg3); border:1px solid var(--border); border-radius:6px; color:var(--cream); font-weight:700; text-align:center;" />
                 <span style="font-size:11px; color:var(--text-dim);">${asset.unitType || 'pcs'}</span>
               </div>
          </td>
          ` : ''}
        </tr>
      `;
    });
  }

  html += `
          </tbody>
        </table>
      </div>
    </div>
  `;

  containers.forEach(c => c.innerHTML = html);
};

window.saveDecorationAllocation = async function () {
  const ev = currentAllocEvent || (RESERVATIONS && RESERVATIONS.find(r => r.id === currentEqcReservationId));
  if (!ev) { alert('No active reservation selected.'); return; }

  const sb = window.supabaseClient;
  if (!sb) { alert('Supabase client not available.'); return; }

  const evLabel = ev.name || ev.customerName || ev.client || `Reservation ${ev.id}`;
  const batchName = typeof _genBatchName === 'function' ? _genBatchName(ev) : `BATCH-${(ev.name || ev.id).toString().replace(/\s+/g, '-').toUpperCase()}-${ev.id.slice(0, 6)}`;

  let decos = (EIM_ASSETS || []).filter(a => (a.category || '').toLowerCase().includes('decoration'));
  let updatedCount = 0;

  try {
    const updatePromises = [];
    const historyInserts = [];

    // Validation Pass: Ensure no inputs exceed their max available amount
    for (const asset of decos) {
      const inputEl = document.querySelector(`#deco-input-${asset.supabaseId || asset.id}`) || document.getElementById(`deco-input-${asset.supabaseId || asset.id}`);
      if (!inputEl) continue;
      
      const qty = parseInt(inputEl.value) || 0;
      const maxQty = parseInt(inputEl.max) || 0;
      
      if (qty > maxQty) {
        if (typeof showToast === 'function') {
          showToast(`Cannot allocate ${qty} of ${asset.name}. Only ${maxQty} available!`, 'error');
        } else {
          alert(`Cannot allocate ${qty} of ${asset.name}. Only ${maxQty} available!`);
        }
        return; // Abort the entire save process
      }
    }

    // Clear existing decoration history for this reservation to prevent duplicates
    const decoIds = decos.map(a => a.supabaseId || a.id);
    for (let i = 0; i < decoIds.length; i += 100) {
      await sb.from('allocation_history').delete().eq('reservation_id', ev.id).in('equipment_id', decoIds.slice(i, i + 100));
    }

    for (const asset of decos) {
      const inputEl = document.querySelector(`#deco-input-${asset.supabaseId || asset.id}`) || document.getElementById(`deco-input-${asset.supabaseId || asset.id}`);
      if (!inputEl) continue;

      const qty = parseInt(inputEl.value) || 0;

      if (qty > 0) {
        const updatePromise = sb.from('equipment_inventory').update({
          allocated_qty: qty,
          allocation_batch: batchName,
          allocated_to: evLabel,
          allocated_reservation_id: ev.id,
          allocation_date: ev.date || ev.eventDate || null
        }).eq('id', asset.supabaseId || asset.id)
        .then(({ error: upErr }) => {
          if (!upErr) {
            asset.allocatedQty = qty;
            asset.allocationBatch = batchName;
            asset.allocatedTo = evLabel;
            asset.allocatedReservationId = ev.id;
            updatedCount++;
          }
        });
        updatePromises.push(updatePromise);

        historyInserts.push({
          equipment_id: asset.supabaseId || asset.id,
          asset_id: asset.id || asset.asset_id,
          equipment_name: asset.name,
          allocation_batch: batchName,
          allocated_qty: qty,
          unit_type: asset.unit_type || asset.unitType || 'pcs',
          reservation_id: ev.id,
          reservation_name: evLabel,
          allocation_date: ev.date || ev.eventDate || null,
          consumable: !!(asset.consumable || asset.is_consumable)
        });
      }
    }

    await Promise.all(updatePromises);
    if (historyInserts.length > 0) {
      try {
        await sb.from('allocation_history').insert(historyInserts);
      } catch (e) { console.warn('[AllocHistory] Bulk insert failed:', e); }
    }

    // Comprehensive Admin Activity Logging for decoration allocation
    try {
      if (typeof window.logAdminActivity === 'function') {
        window.logAdminActivity(
          'Allocated Decoration Items',
          `Saved decoration allocations for reservation #${ev.id} (${ev.packageName || ev.client || ev.id}).`,
          { category: 'Equipment Assets', reservation_id: ev.id }
        );
      }
    } catch (_logErr) {
      console.warn('Logging saveDecorationAllocation failed:', _logErr);
    }

    if (typeof showToast === 'function') showToast(`Successfully saved decoration allocation for ${updatedCount} item(s)!`, 'success');
    else alert(`Successfully saved decoration allocation for ${updatedCount} item(s)!`);

    if (typeof setProcSorted === 'function') await setProcSorted(ev.id, 'decoration', true); // Auto-sort decoration in resource prep

    window._isDecoEditMode = false;
    renderDecoEquipmentTable();
  } catch (e) {
    console.error('Error saving decoration allocation:', e);
    alert('Failed to save decoration allocation.');
  }
};

// ====================================================================
// EN COLLECTION : Equipment Needs per Reservation
// Firestore path: EN/{reservationId}
// Schema: { eventId, eventName, eventDate, eventPax, savedAt,
//           venueEquipment: {tables,chairs,chafing,dispensers,
//                            plates,forks,spoons,knives,glasses,other},
//           manifest: [{ assetId, name, category, source, requiredExact,
//                         venueQty, bufferAdded, deployQty, inStock,
//                         shortfall, sufficient }] }
// ====================================================================

async function saveENRecord(ev, manifest, vdMap) {
  if (!window.firebaseFns || !window.firebaseDB) return;
  const si = document.getElementById('venue-save-status');
  try {
    const { doc, setDoc } = window.firebaseFns;
    const db = window.firebaseDB;
    const gvStr = id => parseInt((document.getElementById(id) || {}).value || '0') || 0;
    const record = {
      eventId: ev.id,
      eventName: ev.client,
      eventDate: ev.date,
      eventPax: ev.pax,
      savedAt: new Date().toISOString(),
      venueEquipment: {
        tables: gvStr('venue-tables'),
        chairs: gvStr('venue-chairs'),
        chafing: gvStr('venue-chafing'),
        dispensers: gvStr('venue-dispensers'),
        plates: gvStr('venue-plates'),
        forks: gvStr('venue-forks'),
        spoons: gvStr('venue-spoons'),
        knives: gvStr('venue-knives'),
        glasses: gvStr('venue-glasses'),
        other: (document.getElementById('venue-other') || {}).value || ''
      },
      manifest: manifest.map(l => ({
        assetId: l.assetId,
        name: l.name,
        category: l.category,
        // source tells downstream (scheduling/EN) which pool covers this item
        source: l.venueProv > 0 ? 'venue'
          : l.sufficient ? 'inventory'
            : 'rented',
        requiredExact: l.exact,
        venueQty: l.venueProv,
        bufferAdded: l.bufAmt,
        deployQty: l.deployQty,
        inStock: l.inStock,
        shortfall: l.shortfall,
        sufficient: l.sufficient
      }))
    };
    await setDoc(doc(db, 'EN', ev.id), record);
    if (si) { si.textContent = '\u2705 Saved to Firebase'; si.style.color = 'var(--green)'; si.style.display = 'inline'; }
  } catch (err) {
    console.error('[EN] Save failed:', err);
    if (si) { si.textContent = '\u26a0 Save failed: ' + err.message; si.style.color = 'var(--red)'; si.style.display = 'inline'; }
  }
}

async function loadENRecord(eventId) {
  if (!window.firebaseFns || !window.firebaseDB) return;
  const ai = document.getElementById('venue-autofill-status');
  if (ai) { ai.textContent = '\u23f3 Loading saved venue data...'; ai.style.color = 'var(--text-dim)'; ai.style.display = 'inline'; }
  try {
    const { doc, getDoc } = window.firebaseFns;
    const db = window.firebaseDB;
    const snap = await getDoc(doc(db, 'EN', eventId));
    if (!snap.exists()) {
      if (ai) { ai.textContent = 'No saved venue data yet : fill in and generate to save.'; ai.style.color = 'var(--text-dim)'; ai.style.display = 'inline'; }
      return;
    }
    const data = snap.data();
    const ve = data.venueEquipment || {};
    const fields = {
      'venue-tables': ve.tables || 0,
      'venue-chairs': ve.chairs || 0,
      'venue-chafing': ve.chafing || 0,
      'venue-dispensers': ve.dispensers || 0,
      'venue-plates': ve.plates || 0,
      'venue-forks': ve.forks || 0,
      'venue-spoons': ve.spoons || 0,
      'venue-knives': ve.knives || 0,
      'venue-glasses': ve.glasses || 0,
    };
    Object.entries(fields).forEach(([id, val]) => { const el = document.getElementById(id); if (el) el.value = val; });
    const otherEl = document.getElementById('venue-other'); if (otherEl) otherEl.value = ve.other || '';
    if (ai) {
      const d = new Date(data.savedAt);
      ai.textContent = '\u2705 Auto-filled from ' + d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
      ai.style.color = 'var(--green)';
    }
  } catch (err) {
    console.error('[EN] Load failed:', err);
    if (ai) { ai.textContent = '\u26a0 Could not load saved data.'; ai.style.color = 'var(--red)'; }
  }
}

// Standalone save without needing to generate manifest
async function saveVenueEquipmentOnly() {
  if (!currentAllocEvent) { alert('Please select an event first.'); return; }
  await saveENRecord(currentAllocEvent, [], {});
}

window.saveENRecord = saveENRecord;
window.loadENRecord = loadENRecord;
window.saveVenueEquipmentOnly = saveVenueEquipmentOnly;

