window.toggleResupplyPanel = function(panelId, hdrEl) {
  const panel = document.getElementById(panelId);
  if (!panel) return;
  const icon = hdrEl.querySelector('.rs-panel-icon');
  if (panel.style.display === 'none') {
    panel.style.display = 'block';
    if (icon) icon.style.transform = 'rotate(0deg)';
  } else {
    panel.style.display = 'none';
    if (icon) icon.style.transform = 'rotate(-90deg)';
  }
};

window.switchResupplyTab = function(tab) {
  const viewDashboard = document.getElementById('rs-dashboard-view');
  const viewLogs = document.getElementById('rs-logs-view');
  const btnDashboard = document.getElementById('btn-rs-tab-dashboard');
  const btnLogs = document.getElementById('btn-rs-tab-logs');

  if (tab === 'logs') {
    if (viewDashboard) viewDashboard.style.display = 'none';
    if (viewLogs) viewLogs.style.display = 'block';
    if (btnDashboard) btnDashboard.style.display = 'inline-block';
    if (btnLogs) btnLogs.style.display = 'none';
    if (typeof renderResupplyLogsTable === 'function') renderResupplyLogsTable();
  } else {
    if (viewDashboard) viewDashboard.style.display = 'block';
    if (viewLogs) viewLogs.style.display = 'none';
    if (btnDashboard) btnDashboard.style.display = 'none';
    if (btnLogs) btnLogs.style.display = 'inline-block';
  }
};

async function renderResupplySection() {
  const rsAlloc = document.getElementById('rs-allocations-container');
  const rsMissing = document.getElementById('rs-missing-tbody');
  const rsShop = document.getElementById('rs-shopping-tbody');
  const rsLogs = document.getElementById('rs-logs-tbody');

  if (rsAlloc) rsAlloc.innerHTML = '<div style="text-align:center;padding:30px;color:var(--text-dim);font-size:13px;">Loading reservations...</div>';
  if (rsMissing) rsMissing.innerHTML = '<tr><td colspan="3" style="text-align:center;padding:30px;color:var(--text-dim);font-size:13px;">Loading missing/retired...</td></tr>';
  if (rsShop) rsShop.innerHTML = '<tr><td colspan="4" style="text-align:center;padding:30px;color:var(--text-dim);font-size:13px;">Loading shopping list...</td></tr>';
  if (rsLogs) rsLogs.innerHTML = '<tr><td colspan="5" style="text-align:center;padding:30px;color:var(--text-dim);font-size:13px;">Loading logs...</td></tr>';

  const sb = window.supabaseClient;
  if (!sb) return;

  try {
    const catchErr = err => ({ data: [] });
    const [resEq, resLogsReq, resMntReq, resHistReq, resVenueReq, resUnitsReq] = await Promise.all([
      sb.from('equipment_inventory').select('*'),
      sb.from('resupply_logs').select('*').order('created_at', { ascending: false }).then(res => res.error ? { data: [] } : res, catchErr),
      sb.from('equipment_maintenance').select('*').then(res => res.error ? { data: [] } : res, catchErr),
      sb.from('allocation_history').select('asset_id,equipment_name,allocated_qty,reservation_id,reservation_name,allocation_batch,is_rental,recorded_at').not('allocation_batch', 'is', null).then(res => res.error ? { data: [] } : res, catchErr),
      sb.from('venue_equipment').select('*').then(res => res.error ? { data: [] } : res, catchErr),
      sb.from('equipment_unit_items').select('*').or('condition.ilike.retired,condition.ilike.missing,status.ilike.retired,status.ilike.missing').then(res => res.error ? { data: [] } : res, catchErr)
    ]);

    const baseEq = resEq.data || [];
    const mntData = resMntReq.data || [];
    const histData = (resHistReq && resHistReq.data) ? resHistReq.data : [];
    const venueData = (resVenueReq && resVenueReq.data) ? resVenueReq.data : [];
    const unitsData = (resUnitsReq && resUnitsReq.data) ? resUnitsReq.data : [];
    window.resupplyLogs = (resLogsReq && resLogsReq.data) ? resLogsReq.data : [];

    // --- PREDICTED EQUIPMENT DEMAND FOR NEXT MONTH ---
    const rsPredTbody = document.getElementById('rs-predicted-tbody');
    const rsPredTitle = document.getElementById('rs-predicted-title');
    const rsPredSub = document.getElementById('rs-predicted-subtitle');
    window.resupplyPredictedDemand = [];

    const MONTH_LABELS_FULL = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
    const now = new Date();
    const currentMonthIdx = now.getMonth();
    const nextMonthIdx = (currentMonthIdx + 1) % 12;
    const nextMonthName = MONTH_LABELS_FULL[nextMonthIdx];

    // Fetch all reservations if not in window.RESERVATIONS
    let allReservations = (typeof window.RESERVATIONS !== 'undefined' && Array.isArray(window.RESERVATIONS)) ? window.RESERVATIONS : [];
    if (allReservations.length === 0 && sb) {
      try {
        const { data: resAll } = await sb.from('reservations').select('*');
        if (resAll) allReservations = resAll;
      } catch (e) {}
    }

    // 1. Calculate next month's predicted bookings (Seasonal Weighted Average)
    const actualsByMonth = new Array(12).fill(0);
    const nextMonthPaxList = [];
    const allPaxList = [];

    allReservations.forEach(r => {
      const dStr = r.date || r.event_date || r.created_at;
      const paxVal = parseInt(r.pax || r.guest_count || r.guests || 0);
      if (paxVal > 0) allPaxList.push(paxVal);

      if (dStr) {
        const d = new Date(dStr);
        if (!isNaN(d.getTime())) {
          const m = d.getMonth();
          actualsByMonth[m]++;
          if (m === nextMonthIdx && paxVal > 0) {
            nextMonthPaxList.push(paxVal);
          }
        }
      }
    });

    const fcMeta = (typeof calculateWeightedMonthlyDemandForecast === 'function')
      ? calculateWeightedMonthlyDemandForecast(allReservations)
      : null;
    const predictedNextMonthBookings = (fcMeta && fcMeta.forecasts && fcMeta.forecasts[nextMonthIdx] > 0)
      ? fcMeta.forecasts[nextMonthIdx]
      : Math.max(1, Math.round(allReservations.length / 48));

    // 2. Calculate predicted average pax for next month using PA-WMA weighted pax
    let predictedAvgPax = (fcMeta && fcMeta.forecastPax && fcMeta.forecastPax[nextMonthIdx] > 0)
      ? fcMeta.forecastPax[nextMonthIdx]
      : 100;
    if (!fcMeta && nextMonthPaxList.length > 0) {
      predictedAvgPax = Math.round(nextMonthPaxList.reduce((s, v) => s + v, 0) / nextMonthPaxList.length);
    }

    if (rsPredTitle) {
      rsPredTitle.textContent = `Predicted Equipment Demand for ${nextMonthName}`;
    }
    if (rsPredSub) {
      rsPredSub.innerHTML = `Forecast: <strong>${predictedNextMonthBookings} bookings</strong> &bull; Predicted Baseline: <strong>${predictedAvgPax} pax</strong>/reservation based on historical Supabase data.`;
    }

    // 3. Find all equipment with allocation rule "per_pax" or "per_N_pax"
    let predDemandHTML = '';
    let predDeficitCount = 0;

    baseEq.forEach(eq => {
      if (eq.is_disabled || String(eq.status || '').toLowerCase() === 'retired') return;
      // Skip child batch sets and split batches so we only forecast demand for the root parent equipment
      if (eq.parent_asset_id) return;

      const rule = String(eq.allocation_type || eq.allocationRule || eq.rule_type || '').toLowerCase().trim();
      let ruleLabel = '';
      let neededQty = 0;

      if (rule === 'per_pax' || rule === 'per_1_pax') {
        neededQty = predictedAvgPax;
        ruleLabel = 'Per Pax (1 unit / pax)';
      } else {
        const match = rule.match(/^per_(\d+)_pax$/);
        if (match) {
          const n = parseInt(match[1]) || 1;
          neededQty = Math.ceil(predictedAvgPax / n);
          ruleLabel = `Per ${n} Pax (1 unit / ${n} pax)`;
        }
      }

      if (neededQty <= 0) return; // Not a per-pax or per-N-pax equipment

      // Calculate stock available: good_qty (or total_qty) aggregated across whole family (parent + all sets/batches)
      const eqIdUpper = String(eq.asset_id || eq.id || '').toUpperCase().trim();
      const eqNameLower = String(eq.name || '').toLowerCase().trim();
      const familyEqs = baseEq.filter(e => {
        if (e.is_disabled || String(e.status || '').toLowerCase() === 'retired') return false;
        const eAssetId = String(e.asset_id || e.id || '').toUpperCase().trim();
        const eParent = String(e.parent_asset_id || '').toUpperCase().trim();
        const eName = String(e.name || '').toLowerCase().trim();
        return eAssetId === eqIdUpper ||
               eParent === eqIdUpper ||
               (eq.id && eParent === String(eq.id).toUpperCase().trim()) ||
               (eqNameLower && (eName === eqNameLower || eName.startsWith(eqNameLower + ' batch-') || eName.startsWith(eqNameLower + ' set')));
      });

      const totalStock = familyEqs.reduce((s, e) => {
        const gQty = e.good_qty != null ? parseInt(e.good_qty) : (parseInt(e.total_qty != null ? e.total_qty : e.quantity) || 0);
        return s + Math.max(0, isNaN(gQty) ? 0 : gQty);
      }, 0);

      const maintQty = familyEqs.reduce((s, e) => s + (parseInt(e.maintenance_qty) || 0), 0);
      const retiredQty = familyEqs.reduce((s, e) => s + (parseInt(e.retired_qty) || 0), 0);
      const availableStock = Math.max(0, totalStock - maintQty - retiredQty);

      // If warehouse stock meets or exceeds demand, do not display
      if (availableStock < neededQty) {
        predDeficitCount++;
        const deficit = neededQty - availableStock;
        const aId = eq.asset_id || eq.id || '';
        const aName = eq.name || 'Equipment';

        window.resupplyPredictedDemand.push({
          asset_id: aId,
          equipment_name: aName,
          allocation_rule: ruleLabel,
          predicted_pax: predictedAvgPax,
          needed_qty: neededQty,
          available_stock: availableStock,
          shortage: deficit,
          reason: 'Predicted Forecast'
        });

        predDemandHTML += `<tr>
          <td>
            <div style="font-weight:600;color:var(--cream);">${aName}</div>
            <div style="font-size:11px;color:var(--text-dim);">${aId}</div>
          </td>
          <td><span style="font-size:12px;color:var(--gold);font-weight:600;">${ruleLabel}</span></td>
          <td style="text-align:center;font-weight:600;">${predictedAvgPax}</td>
          <td style="text-align:center;font-weight:700;color:var(--cream);">${neededQty}</td>
          <td style="text-align:center;font-weight:600;">${availableStock}</td>
          <td style="text-align:center;font-weight:700;color:var(--red);">${deficit}</td>
        </tr>`;
      }
    });

    if (predDeficitCount === 0) {
      predDemandHTML = `<tr><td colspan="6" style="text-align:center;padding:30px;color:var(--text-dim);font-size:13px;">No equipment shortages predicted for ${nextMonthName}! Warehouse stock meets all predicted demands (${predictedAvgPax} pax).</td></tr>`;
    }
    if (rsPredTbody) rsPredTbody.innerHTML = predDemandHTML;

    // --- APPROVED RESERVATIONS & EQUIPMENT NEEDS (SHORTAGES) ---
    window.resupplyShortages = [];
    window.resupplyMissing = [];

    // Filter approved / confirmed reservations
    const approvedRes = allReservations.filter(r => {
      const s = String(r.status || '').toLowerCase();
      return s.includes('confirm') || s.includes('planning') || s.includes('procurement') || s.includes('preparation') || s.includes('on-going') || s.includes('approved');
    });

    // Helper map of child asset IDs to root parent asset IDs
    const childToRootMap = {};
    baseEq.forEach(eq => {
      if (eq.parent_asset_id && !eq.is_disabled) {
        childToRootMap[String(eq.asset_id || eq.id || '').toUpperCase().trim()] = String(eq.parent_asset_id).toUpperCase().trim();
      }
    });
    (window.EIM_ASSETS || []).forEach(a => {
      if (a.parent_asset_id && !a.is_disabled) {
        const cKey = String(a.asset_id || a.id || '').toUpperCase().trim();
        if (!childToRootMap[cKey]) childToRootMap[cKey] = String(a.parent_asset_id).toUpperCase().trim();
      }
    });

    const getFamTotal = (assetKey) => {
      const k = String(assetKey || '').toUpperCase().trim();
      const root = childToRootMap[k] || k;
      const fam = baseEq.filter(e => !e.is_disabled && (String(e.asset_id || e.id || '').toUpperCase().trim() === root || String(e.parent_asset_id || '').toUpperCase().trim() === root));
      if (fam.length > 0) {
        return fam.reduce((sum, e) => sum + Math.max(0, (parseInt(e.good_qty != null ? e.good_qty : (e.total_qty || e.quantity || 0)) || 0) - (parseInt(e.maintenance_qty || 0)) - (parseInt(e.retired_qty || 0))), 0);
      }
      const match = baseEq.find(e => (e.name || '').toLowerCase().trim() === String(assetKey || '').toLowerCase().trim());
      return match ? Math.max(0, (parseInt(match.good_qty != null ? match.good_qty : (match.total_qty || match.quantity || 0)) || 0) - (parseInt(match.maintenance_qty || 0)) - (parseInt(match.retired_qty || 0))) : 0;
    };

    const getFamKeys = (assetKey) => {
      const k = String(assetKey || '').toUpperCase().trim();
      const root = childToRootMap[k] || k;
      const set = new Set([root]);
      baseEq.forEach(e => {
        if (!e.is_disabled && String(e.parent_asset_id || '').toUpperCase().trim() === root) {
          set.add(String(e.asset_id || e.id || '').toUpperCase().trim());
        }
      });
      return set;
    };

    const resShortageMap = new Map();

    // 1. Incorporate any shortages already detected by the Availability view
    (window.availabilityDetectedShortages || []).forEach(item => {
      const aId = item.asset_id || item.equipment_id || '';
      const aName = item.equipment_name || item.name || 'Equipment';
      const rId = item.reservation_id || '';
      const rName = item.reservation_name || ('Reservation #' + rId);
      const needed = parseInt(item.needed_qty || item.shortfall || 0);
      if (needed > 0) {
        const curStock = getFamTotal(aId || aName);
        const mapKey = `${rId}___${aId || aName}`.toLowerCase();
        resShortageMap.set(mapKey, {
          reservation_id: rId,
          reservation_name: rName,
          asset_id: aId,
          equipment_name: aName,
          needed_qty: needed,
          available_stock: curStock,
          event_date: item.event_date || '',
          reason: item.reason || ('Reservation Shortage: ' + rName)
        });
      }
    });

    // 2. Dynamically calculate shortages for all approved reservations
    approvedRes.forEach(res => {
      const resId = res.id;
      const resName = res.client || res.name || res.reservation_name || ('Reservation #' + resId);
      const resDate = res.date || res.event_date || res.eventDate || '';
      const pax = parseInt(res.pax || res.guest_count || res.guests || 50) || 50;

      const sameDateResIds = new Set(
        allReservations
          .filter(r => r.id !== resId && (r.date || r.event_date || r.eventDate) === resDate)
          .map(r => r.id)
      );

      // Manifest items
      let manifest = [];
      try { manifest = typeof res.equipment_manifest === 'string' ? JSON.parse(res.equipment_manifest) : (res.equipment_manifest || res.equipmentManifest || []); } catch(e){}

      // Manifest shortfall check
      manifest.forEach(item => {
        const short = parseInt(item.shortfall || item.short_qty || 0);
        if (short > 0) {
          const aId = item.assetId || item.asset_id || '';
          const aName = item.name || item.equipment_name || 'Equipment';
          const stock = getFamTotal(aId || aName);
          const mapKey = `${resId}___${aId || aName}`.toLowerCase();
          if (!resShortageMap.has(mapKey)) {
            resShortageMap.set(mapKey, {
              reservation_id: resId,
              reservation_name: resName,
              asset_id: aId,
              equipment_name: aName,
              needed_qty: short,
              available_stock: stock,
              event_date: resDate,
              reason: 'Reservation Shortage: ' + resName
            });
          }
        }
      });

      // Package items & allocation rules check
      const itemsToCheck = new Map();
      manifest.forEach(m => {
        const k = (m.assetId || m.asset_id || m.name || '').toUpperCase().trim();
        if (k && !itemsToCheck.has(k)) {
          itemsToCheck.set(k, { assetId: m.assetId || m.asset_id, name: m.name || m.equipment_name, needed: parseInt(m.quantity || m.needed || m.qty || 0) });
        }
      });

      let pkgItems = [];
      try { pkgItems = typeof res.package_items === 'string' ? JSON.parse(res.package_items) : (res.package_items || res.packageItems || []); } catch(e){}
      if (Array.isArray(pkgItems)) {
        pkgItems.forEach(p => {
          const pName = typeof p === 'string' ? p : (p && p.name);
          if (!pName) return;
          const matchEq = baseEq.find(e => (e.name || '').toLowerCase().trim() === pName.toLowerCase().trim());
          if (matchEq) {
            const k = String(matchEq.asset_id || matchEq.id || pName).toUpperCase().trim();
            if (!itemsToCheck.has(k)) {
              const rule = String(matchEq.allocation_type || matchEq.allocationRule || 'fixed').toLowerCase().trim();
              let needed = 1;
              if (rule === 'per_pax' || rule === 'per_1_pax') needed = pax;
              else if (rule.startsWith('per_') && rule.endsWith('_pax')) {
                const m = rule.match(/^per_(\d+)_pax$/);
                needed = m ? Math.ceil(pax / parseInt(m[1])) : pax;
              } else if (rule === 'per_table') needed = Math.ceil(pax / 10);
              itemsToCheck.set(k, { assetId: matchEq.asset_id || matchEq.id, name: matchEq.name, needed });
            }
          }
        });
      }

      itemsToCheck.forEach((req, aKey) => {
        const isDec = baseEq.some(e => String(e.asset_id || e.id || '').toUpperCase().trim() === aKey && (e.category || '').toLowerCase().includes('decoration'));
        if (isDec) return;

        const famKeys = getFamKeys(aKey);
        const famTotal = getFamTotal(aKey);

        const allocatedToOthers = histData
          .filter(h => sameDateResIds.has(h.reservation_id) && famKeys.has(String(h.asset_id || '').toUpperCase().trim()) && !h.is_rental)
          .reduce((s, h) => s + (parseInt(h.allocated_qty) || 0), 0);

        const availableOnDate = Math.max(0, famTotal - allocatedToOthers);

        const allocatedToThis = histData
          .filter(h => h.reservation_id === resId && famKeys.has(String(h.asset_id || '').toUpperCase().trim()) && !h.is_rental)
          .reduce((s, h) => s + (parseInt(h.allocated_qty) || 0), 0);

        const rentedToThis = histData
          .filter(h => h.reservation_id === resId && famKeys.has(String(h.asset_id || '').toUpperCase().trim()) && h.is_rental)
          .reduce((s, h) => s + (parseInt(h.allocated_qty) || 0), 0);

        const vItems = (venueData || []).filter(v => v.reservation_id === resId).flatMap(v => v.items || []);
        const venueToThis = vItems
          .filter(vi => famKeys.has(String(vi.assetId || vi.asset_id || '').toUpperCase().trim()))
          .reduce((s, vi) => s + (parseInt(vi.quantity || vi.qty) || 0), 0);

        const eqObj = baseEq.find(e => famKeys.has(String(e.asset_id || e.id || '').toUpperCase().trim()));
        const buffer = eqObj ? (parseInt(eqObj.extra_buffer) || 0) : 0;
        const totalReq = Math.max(0, req.needed - venueToThis) + buffer;

        const dateShort = Math.max(0, totalReq - (availableOnDate + rentedToThis + venueToThis));
        if (dateShort > 0) {
          const mapKey = `${resId}___${req.assetId || req.name}`.toLowerCase();
          if (!resShortageMap.has(mapKey)) {
            resShortageMap.set(mapKey, {
              reservation_id: resId,
              reservation_name: resName,
              asset_id: req.assetId || aKey,
              equipment_name: req.name || (eqObj ? eqObj.name : aKey),
              needed_qty: dateShort,
              available_stock: availableOnDate,
              event_date: resDate,
              reason: 'Reservation Shortage: ' + resName
            });
          }
        }
      });
    });

    window.resupplyShortages = Array.from(resShortageMap.values()).filter(s => s.needed_qty > 0);

    let allocHTML = '<table class="inv-table"><thead><tr><th>Reservation</th><th>Equipment</th><th style="text-align:center;">Required (Shortage)</th><th style="text-align:center;">Stock Available</th><th>Status</th></tr></thead><tbody>';

    if (window.resupplyShortages.length === 0) {
      allocHTML += '<tr><td colspan="5" style="text-align:center;padding:30px;color:var(--text-dim);font-size:13px;">No shortages for approved reservations! All set.</td></tr>';
    } else {
      window.resupplyShortages.forEach(item => {
        allocHTML += `<tr>
          <td>
            <div style="font-weight:600;color:var(--cream);">${item.reservation_name || 'Reservation'}</div>
            <div style="font-size:11px;color:var(--text-dim);">${item.event_date ? item.event_date : (item.reservation_id || '')}</div>
          </td>
          <td>
            <div style="font-weight:600;color:var(--cream);">${item.equipment_name || 'Equipment'}</div>
            <div style="font-size:11px;color:var(--text-dim);">${item.asset_id || ''}</div>
          </td>
          <td style="text-align:center; font-weight:700; color:var(--red); font-size:13px;">${item.needed_qty}</td>
          <td style="text-align:center; font-weight:600;">${item.available_stock != null ? item.available_stock : 0}</td>
          <td><span style="color:var(--red); font-weight:600; font-size:12px;">Short (${item.needed_qty})</span></td>
        </tr>`;
      });
    }
    allocHTML += '</tbody></table>';
    if (rsAlloc) rsAlloc.innerHTML = allocHTML;

    // Build Missing/Retired (Auto-expanded, individual unit item representation)
    let missingHTML = '';
    const displayedUnitCodes = new Set();
    const unitsMapByAsset = {};
    (unitsData || []).forEach(u => {
      const aKey = u.asset_id || u.equipment_id;
      if (!unitsMapByAsset[aKey]) unitsMapByAsset[aKey] = [];
      unitsMapByAsset[aKey].push(u);
    });

    baseEq.forEach(eq => {
      const aId = eq.asset_id || eq.id;
      const eqUnits = unitsMapByAsset[aId] || [];

      if (eqUnits.length > 0) {
        // Individual unit-based equipment: display each specific unit item with its real unit ID and quantity 1
        eqUnits.forEach(u => {
          const c = String(u.condition || '').toLowerCase();
          const s = String(u.status || '').toLowerCase();
          const isRetired = (c === 'retired' || s === 'retired');
          const isMissing = (c === 'missing' || s === 'missing');
          if (isRetired) {
            displayedUnitCodes.add(u.item_code);
            window.resupplyMissing.push({ asset_id: aId, item_code: u.item_code, equipment_name: eq.name, reason: 'Retired', needed_qty: 1 });
            missingHTML += `<tr>
              <td>${eq.name}</td>
              <td><code style="font-size:11px; color:var(--gold); font-family:monospace;">${escHtml(u.item_code)}</code></td>
              <td><span style="color:var(--amber);font-weight:600;">Retired</span></td>
              <td style="text-align:center;font-weight:bold;">1</td>
            </tr>`;
          } else if (isMissing) {
            displayedUnitCodes.add(u.item_code);
            window.resupplyMissing.push({ asset_id: aId, item_code: u.item_code, equipment_name: eq.name, reason: 'Missing', needed_qty: 1 });
            missingHTML += `<tr>
              <td>${eq.name}</td>
              <td><code style="font-size:11px; color:var(--gold); font-family:monospace;">${escHtml(u.item_code)}</code></td>
              <td><span style="color:var(--red);font-weight:600;">Missing</span></td>
              <td style="text-align:center;font-weight:bold;">1</td>
            </tr>`;
          }
        });
      } else {
        // Aggregate/quantity-based equipment without unit items: display base asset ID with aggregate lost quantity
        let retiredQty = parseInt(eq.retired_qty) || 0;
        if (retiredQty === 0 && String(eq.status).toLowerCase() === 'retired') {
          retiredQty = parseInt(eq.total_qty) || 0;
        }
        if (retiredQty > 0) {
          window.resupplyMissing.push({ asset_id: aId, equipment_name: eq.name, reason: 'Retired', needed_qty: retiredQty });
          missingHTML += `<tr>
            <td>${eq.name}</td>
            <td><code style="font-size:11px; color:var(--gold); font-family:monospace;">${escHtml(aId)}</code></td>
            <td><span style="color:var(--amber);font-weight:600;">Retired</span></td>
            <td style="text-align:center;font-weight:bold;">${retiredQty}</td>
          </tr>`;
        }

        const missingQty = parseInt(eq.missing_qty) || 0;
        if (missingQty > 0) {
          window.resupplyMissing.push({ asset_id: aId, equipment_name: eq.name, reason: 'Missing', needed_qty: missingQty });
          missingHTML += `<tr>
            <td>${eq.name}</td>
            <td><code style="font-size:11px; color:var(--gold); font-family:monospace;">${escHtml(aId)}</code></td>
            <td><span style="color:var(--red);font-weight:600;">Missing</span></td>
            <td style="text-align:center;font-weight:bold;">${missingQty}</td>
          </tr>`;
        }
      }
    });

    mntData.forEach(mnt => {
      if (mnt.status === 'pending' && (String(mnt.issue || '').toLowerCase().includes('missing') || String(mnt.issue || '').toLowerCase().includes('lost'))) {
        const eqName = mnt.equipment_name || 'Unknown';
        const aId = mnt.equipment_id || '';
        const mntCode = mnt.item_code || null;
        if (mntCode && displayedUnitCodes.has(mntCode)) return;
        const qty = parseInt(mnt.qty) || 1;
        const alreadyShownFromEq = (window.resupplyMissing || []).some(m => m.asset_id === aId && m.reason === 'Missing' && (!m.item_code || m.item_code === mntCode));
        if (!alreadyShownFromEq) {
          window.resupplyMissing.push({ asset_id: aId, item_code: mntCode, equipment_name: eqName, reason: 'Missing', needed_qty: qty });
          missingHTML += `<tr>
            <td>${eqName}</td>
            <td><code style="font-size:11px; color:var(--gold); font-family:monospace;">${escHtml(mntCode || aId || '—')}</code></td>
            <td><span style="color:var(--red);font-weight:600;">Missing</span></td>
            <td style="text-align:center;font-weight:bold;">${qty}</td>
          </tr>`;
        }
      }
    });
    
    if (!missingHTML) missingHTML = '<tr><td colspan="4" style="text-align:center;padding:30px;color:var(--text-dim);font-size:13px;">No missing or retired items requiring attention.</td></tr>';
    if (rsMissing) rsMissing.innerHTML = missingHTML;

    // --- LOW STOCK ALERT ---
    const rsLowStock = document.getElementById('rs-low-stock-tbody');
    let lowStockHTML = '';
    const lowStockItems = baseEq.filter(e => {
        if (e.is_disabled || (e.category || '').toLowerCase().includes('decoration')) return false;
        const availableCount = (e.good_qty != null ? e.good_qty : (e.quantity || 0)) - (e.maintenance_qty || 0);
        const limitCount = parseInt(e.limit) || 0;
        return limitCount > 0 && availableCount <= limitCount;
    });
    window._lastLowStockItems = lowStockItems;

    lowStockItems.forEach(e => {
        const availableCount = (e.good_qty != null ? e.good_qty : (e.quantity || 0)) - (e.maintenance_qty || 0);
        const limitCount = parseInt(e.limit) || 0;
        lowStockHTML += `<tr>
            <td><code style="font-size:10px;">${e.asset_id || e.id}</code></td>
            <td><div class="item-name">${e.name}</div><div class="item-cat">${e.category}</div></td>
            <td style="text-align:center;"><span style="color:var(--red); font-weight:700;">${availableCount}</span></td>
            <td style="text-align:center;"><span style="color:var(--amber);">${limitCount}</span></td>
        </tr>`;
    });

    if (lowStockItems.length === 0) lowStockHTML = '<tr><td colspan="4" style="text-align:center;padding:30px;color:var(--text-dim);font-size:13px;">No items are currently low on stock.</td></tr>';
    
    const subTitle = document.getElementById('rs-low-stock-sub');
    if (subTitle) subTitle.textContent = `${lowStockItems.length} equipments have reached their alert limit.`;
    if (rsLowStock) rsLowStock.innerHTML = lowStockHTML;

    // --- AUTOMATIC RESUPPLY SHOPPING LIST MERGE ---
    const mergedMap = new Map();

    function addToMergedShopping(assetId, name, reason, qty) {
      if (!qty || qty <= 0) return;
      const key = (assetId || name || '').toLowerCase().trim();
      if (!key) return;

      if (mergedMap.has(key)) {
        const existing = mergedMap.get(key);
        existing.needed_qty += qty;
        existing.remaining_qty += qty;
        const rArr = existing.reason.split(', ').map(r => r.trim());
        if (!rArr.some(r => r.toLowerCase() === reason.toLowerCase())) {
          existing.reason = existing.reason + ', ' + reason;
        }
      } else {
        mergedMap.set(key, {
          id: 'auto-' + key,
          asset_id: assetId || '',
          equipment_name: name || 'Equipment',
          reason: reason,
          needed_qty: qty,
          remaining_qty: qty
        });
      }
    }

    (window.resupplyShortages || []).forEach(s => {
      addToMergedShopping(s.asset_id, s.equipment_name, 'Reservation Shortage', s.needed_qty);
    });

    (window.resupplyMissing || []).forEach(m => {
      addToMergedShopping(m.asset_id, m.equipment_name, m.reason, m.needed_qty);
    });

    (window.resupplyPredictedDemand || []).forEach(p => {
      addToMergedShopping(p.asset_id, p.equipment_name, 'Predicted Forecast', p.shortage);
    });

    lowStockItems.forEach(e => {
      const availableCount = (e.good_qty != null ? e.good_qty : (e.quantity || 0)) - (e.maintenance_qty || 0);
      const limitCount = parseInt(e.limit) || 0;
      const needed = Math.max(1, limitCount - availableCount);
      addToMergedShopping(e.asset_id || e.id, e.name, 'Low Stock', needed);
    });

    window.resupplyShoppingList = Array.from(mergedMap.values()).filter(i => i.needed_qty > 0);

    renderShoppingListTable();
    renderResupplyLogsTable();
    if (typeof updateResupplyBadge === 'function') updateResupplyBadge();

  } catch (e) {
    console.error('[renderResupplySection]', e);
  }
}
window.renderResupplySection = renderResupplySection;

window.renderShoppingListTable = function() {
  const tbody = document.getElementById('rs-shopping-tbody');
  if (!tbody) return;
  
  if (!window.resupplyShoppingList || window.resupplyShoppingList.length === 0) {
    tbody.innerHTML = '<tr><td colspan="4" style="text-align:center;padding:30px;color:var(--text-dim);font-size:13px;">No items requiring resupply currently.</td></tr>';
    return;
  }
  
  let html = '';
  window.resupplyShoppingList.forEach((item) => {
    html += `<tr>
      <td>
        <div style="font-weight:600;color:var(--cream);font-size:13px;">${item.equipment_name}</div>
        <div style="font-size:11px;color:var(--text-dim);">${item.asset_id}</div>
      </td>
      <td><span style="font-size:12px;color:var(--gold);font-weight:600;">${item.reason}</span></td>
      <td style="text-align:center;font-weight:700;color:var(--cream);font-size:13px;">${item.needed_qty}</td>
      <td style="text-align:center;color:var(--amber);font-weight:700;font-size:13px;">${item.remaining_qty}</td>
    </tr>`;
  });
  tbody.innerHTML = html;
};

window.renderResupplyLogsTable = function() {
  const tbody = document.getElementById('rs-logs-tbody');
  if (!tbody) return;

  const combinedLogs = [];

  // 1. Logs of equipments placed in equipment resupply:
  // Reservation shortages
  (window.resupplyShortages || []).forEach(s => {
    combinedLogs.push({
      created_at: new Date().toISOString(),
      action: 'Placed in Resupply (Shortage)',
      equipment_name: s.equipment_name || '-',
      asset_id: s.asset_id || '',
      qty: s.needed_qty || 1,
      details: s.reason || 'Reservation shortage'
    });
  });

  // Low stock alerts
  (window._lastLowStockItems || []).forEach(e => {
    const availableCount = (e.good_qty != null ? e.good_qty : (e.quantity || 0)) - (e.maintenance_qty || 0);
    const limitCount = parseInt(e.limit) || 0;
    const needed = Math.max(1, limitCount - availableCount);
    combinedLogs.push({
      created_at: new Date().toISOString(),
      action: 'Placed in Resupply (Low Stock Alert)',
      equipment_name: e.name || '-',
      asset_id: e.asset_id || e.id || '',
      qty: needed,
      details: `Stock level (${availableCount}) reached alert limit (${limitCount})`
    });
  });

  // Missing items
  (window.resupplyMissing || []).filter(m => m.reason === 'Missing').forEach(m => {
    combinedLogs.push({
      created_at: new Date().toISOString(),
      action: 'Placed in Resupply (Missing)',
      equipment_name: m.equipment_name || '-',
      asset_id: m.asset_id || '',
      qty: m.needed_qty || 1,
      details: 'Equipment flagged missing/lost from event operations'
    });
  });

  // Retired items
  (window.resupplyMissing || []).filter(m => m.reason === 'Retired').forEach(m => {
    combinedLogs.push({
      created_at: new Date().toISOString(),
      action: 'Placed in Resupply (Retired)',
      equipment_name: m.equipment_name || '-',
      asset_id: m.asset_id || '',
      qty: m.needed_qty || 1,
      details: 'Equipment retired due to wear or damage'
    });
  });

  // Predicted Demand shortages
  (window.resupplyPredictedDemand || []).forEach(p => {
    combinedLogs.push({
      created_at: new Date().toISOString(),
      action: 'Placed in Resupply (Predicted Forecast)',
      equipment_name: p.equipment_name || '-',
      asset_id: p.asset_id || '',
      qty: p.shortage || 1,
      details: `Predicted demand shortfall for next month (${p.needed_qty} required vs ${p.available_stock} warehouse stock)`
    });
  });

  // 2. Logs of equipments leaving equipment resupply (recorded in resupplyLogs)
  (window.resupplyLogs || []).forEach(l => {
    combinedLogs.push({
      created_at: l.created_at || new Date().toISOString(),
      action: l.action || 'Resupply Activity',
      equipment_name: l.equipment_name || '-',
      asset_id: l.asset_id || '',
      qty: l.qty || '-',
      details: l.details || ''
    });
  });

  if (combinedLogs.length === 0) {
    tbody.innerHTML = '<tr><td colspan="5" style="text-align:center;padding:30px;color:var(--text-dim);font-size:13px;">No logs found.</td></tr>';
    return;
  }

  // Sort newest first
  combinedLogs.sort((a, b) => new Date(b.created_at || 0) - new Date(a.created_at || 0));

  let html = '';
  combinedLogs.forEach((l) => {
    let actionColor = 'var(--cream)';
    const act = (l.action || '').toLowerCase();
    if (act.includes('shortage') || act.includes('missing')) actionColor = 'var(--red, #ef4444)';
    else if (act.includes('low stock') || act.includes('retired')) actionColor = 'var(--amber, #d97706)';
    else if (act.includes('cleared') || act.includes('leaving') || act.includes('added')) actionColor = 'var(--green, #22c55e)';

    const timeStr = l.created_at ? new Date(l.created_at).toLocaleString() : '-';
    html += `<tr>
      <td style="font-size:12px; color:var(--text-dim); white-space:nowrap;">${timeStr}</td>
      <td style="font-weight:700; color:${actionColor};">${escHtml(l.action)}</td>
      <td>${escHtml(l.equipment_name || '-')} <span style="font-size:10px; color:var(--gold); font-family:monospace;">${escHtml(l.asset_id || '')}</span></td>
      <td style="text-align:center; font-weight:700;">${escHtml(String(l.qty || '-'))}</td>
      <td style="font-size:12px; color:var(--text-dim);">${escHtml(l.details || '')}</td>
    </tr>`;
  });
  tbody.innerHTML = html;
};

