/* ===== EQUIPMENT MAINTENANCE PIPELINE (EIM 9)
   Functions: renderMaintenanceSection, switchMaintenanceTab,
   loadMaintenanceDataFromSupabase, updateMaintenanceStats, renderMaintenanceGrid,
   retireMaintenanceEquipment, sendToRepair, returnToService
   ==================================================================== */

window.maintenanceTasks = window.maintenanceTasks || [];
window.routineChecksCache = window.routineChecksCache || [];
window.execBatchIncidentsCache = window.execBatchIncidentsCache || [];

async function loadMaintenanceDataFromSupabase() {
  try {
    const sb = window.supabaseClient;
    if (!sb) return;

    // Load active maintenance tasks and hydrate linked incident IDs stored in issue column
    const { data: mntData } = await sb.from('equipment_maintenance').select('*');
    if (mntData) {
      window.maintenanceTasks = mntData.map(t => {
        const issueStr = String(t.issue || '');
        if (!t.exec_incident_id && issueStr.startsWith('EXEC_INC:')) {
          t.exec_incident_id = issueStr.slice(9).split('|')[0].trim();
        }
        if (!t.standalone_incident_id && issueStr.startsWith('SA_INC:')) {
          t.standalone_incident_id = issueStr.slice(7).split('|')[0].trim();
        }
        return t;
      });
    }

    // Load routine checks to find reported dates and pending incidents
    const { data: rcData } = await sb.from('routine_check').select('*').eq('status', 'incident');
    if (rcData) {
      window.routineChecksCache = rcData;
    }

    // Load batch equipment incidents from execution day
    try {
      const { data: execIncData } = await sb.from('exec_batch_incidents').select('*');
      if (execIncData) {
        window.execBatchIncidentsCache = execIncData;
      }
    } catch (eIncErr) {
      console.warn('[loadMaintenanceDataFromSupabase] Could not load exec_batch_incidents:', eIncErr);
    }

    // Load normal inspection reports (standalone incident reports outside routine checks)
    try {
      const { data: saData } = await sb.from('standalone_incident_reports').select('*').eq('is_reverted', false);
      if (saData) {
        window.standaloneIncidentsCache = saData;
      }
    } catch (eSaErr) {
      console.warn('[loadMaintenanceDataFromSupabase] Could not load standalone_incident_reports:', eSaErr);
    }

    // Ensure all maintenance tasks have item_code hydrated from linked sources if missing
    (window.maintenanceTasks || []).forEach(t => {
      if (!t.item_code) {
        if (t.standalone_incident_id) {
          const sa = (window.standaloneIncidentsCache || []).find(s => s.id === t.standalone_incident_id);
          if (sa && sa.item_code) t.item_code = sa.item_code;
        } else if (t.exec_incident_id) {
          const ex = (window.execBatchIncidentsCache || []).find(e => e.id === t.exec_incident_id);
          if (ex && ex.item_code) t.item_code = ex.item_code;
        } else if (t.routine_check_id) {
          const rc = (window.routineChecksCache || []).find(r => r.id === t.routine_check_id);
          if (rc) {
            if (rc.item_code) t.item_code = rc.item_code;
            else if (rc.incidents) {
              try {
                const incs = typeof rc.incidents === 'string' ? JSON.parse(rc.incidents) : rc.incidents;
                if (Array.isArray(incs)) {
                  const f = incs.find(i => i.item_code);
                  if (f) t.item_code = f.item_code;
                }
              } catch(e) {}
            }
          }
        }
      }
    });

    updateMaintenanceStats();
    if (document.getElementById('section-maintenance')?.classList.contains('active')) {
      renderMaintenanceSection();
    }
    if (document.getElementById('section-disposed')?.classList.contains('active') && typeof renderDisposedSection === 'function') {
      renderDisposedSection();
    }
    if (typeof renderDashboard === 'function') {
      renderDashboard();
    }
  } catch (e) {
    console.error('Error loading maintenance data:', e);
  }
}
window.loadMaintenanceDataFromSupabase = loadMaintenanceDataFromSupabase;

// Real-time dynamic refresher for Equipment Maintenance and Archived Retired Equipment
if (!window._mntDynamicRefresherSet) {
  window._mntDynamicRefresherSet = true;
  setInterval(async () => {
    if (document.hidden) return;
    const dspSec = document.getElementById('section-disposed');
    const mntSec = document.getElementById('section-maintenance');
    const isDspActive = dspSec && dspSec.classList.contains('active');
    const isMntActive = mntSec && mntSec.classList.contains('active');
    // Only query Supabase when the user is viewing the maintenance or disposed fleet sections
    if (!isDspActive && !isMntActive) return;

    await loadMaintenanceDataFromSupabase();
    if (isDspActive && typeof renderDisposedSection === 'function') {
      renderDisposedSection();
    }
  }, 25000);
}

function renderMaintenanceSection() {
  updateMaintenanceStats();
  renderMaintenanceGrid();
  renderMaintenanceHistory();
  renderMaintenanceAnalytics();
  if (typeof renderEIMTable === 'function') renderEIMTable();
}
window.renderMaintenanceSection = renderMaintenanceSection;

// ===== ADMIN ANALYTICS CHART FILTERS (MAINTENANCE, DISPOSED & BUSINESS INSIGHTS) =====
const ADMIN_ANALYTICS_KEYS = [
  'mnt-broken', 'mnt-monthly', 'dsp-broken', 'dsp-monthly', 'dsp-missing', 'dsp-monthly-missing',
  'insights-fin-bar', 'insights-fin-line', 'insights-tips-line', 'insights-add-charges',
  'insights-booking-vol', 'insights-comp-vs-canc',
  'insights-canc-origin', 'insights-asset-status',
  'insights-rental-orders', 'insights-geo',
  'insights-geo-venues', 'insights-geo-local',
  'insights-pkg-occ', 'insights-pkg-premade', 'insights-pkg-themes',
  'insights-expenses-ingredients', 'insights-expenses-all', 'insights-food-approvals',
  'insights-exec', 'insights-reviews-rating',
  'fc-acc', 'fc-past'
];
const _LINE_CHART_KEYS = [
  'insights-fin-line', 'insights-tips-line', 'insights-booking-vol', 'insights-comp-vs-canc', 'insights-canc-origin',
  'insights-rental-orders', 'insights-expenses-all',
  'fc-acc', 'mnt-monthly', 'dsp-monthly', 'dsp-monthly-missing'
];
window._adminAnalyticsFilters = window._adminAnalyticsFilters || {}; var _adminAnalyticsFilters = window._adminAnalyticsFilters;
const _initNowD = new Date();
const _default6MonthKeys = ['insights-fin-line', 'insights-tips-line', 'insights-add-charges', 'insights-rental-orders', 'insights-expenses-all', 'insights-booking-vol'];
ADMIN_ANALYTICS_KEYS.forEach(k => {
  _adminAnalyticsFilters[k] = {
    anchorMonth: _initNowD.getMonth(),
    anchorYear: _initNowD.getFullYear(),
    rangeMonths: _default6MonthKeys.includes(k) ? 6 : 12
  };
});
var ADMIN_SHORT_MONTHS = window.ADMIN_SHORT_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
var ADMIN_MONTH_NAMES = window.ADMIN_MONTH_NAMES = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

function getAdminMonthRangeKeys(filter) {
  const nBack = Math.max(0, filter.rangeMonths === 1 ? 0 : (filter.rangeMonths || 12));
  const list = [];
  for (let i = nBack; i >= 0; i--) {
    const d = new Date(filter.anchorYear, filter.anchorMonth - i, 1);
    const y = d.getFullYear();
    const m = d.getMonth();
    const key = y + '-' + String(m + 1).padStart(2, '0');
    const shortLabel = ADMIN_SHORT_MONTHS[m] + (y !== filter.anchorYear ? (" '" + String(y).slice(-2)) : '');
    const fullLabel = ADMIN_MONTH_NAMES[m] + ' ' + y;
    list.push({ key, year: y, month: m, shortLabel, fullLabel });
  }
  return list;
}

function updateAdminAnalyticsDateLabel(key) {
  const f = _adminAnalyticsFilters[key];
  if (!f) return;
  const el = document.getElementById('admin-date-label-' + key);
  if (el) el.textContent = ADMIN_MONTH_NAMES[f.anchorMonth] + ' ' + f.anchorYear;
}

function updateAdminAnalyticsFilterButtonStates(key) {
  const f = _adminAnalyticsFilters[key];
  if (!f) return;
  const r = f.rangeMonths;
  const predefined = [1, 3, 6, 12];
  const isPredefined = predefined.includes(r);
  
  predefined.forEach(pv => {
    const b = document.getElementById('btn-range-' + key + '-' + pv);
    if (b) {
      if (r === pv) b.classList.add('active');
      else b.classList.remove('active');
    }
  });

  const bCust = document.getElementById('btn-range-' + key + '-custom');
  if (bCust) {
    if (!isPredefined) {
      bCust.classList.add('active');
      bCust.textContent = r + ' Mos';
    } else {
      bCust.classList.remove('active');
      bCust.textContent = 'Custom Range';
    }
  }
}

function navAdminAnalyticsMonth(key, delta) {
  const f = _adminAnalyticsFilters[key];
  if (!f) return;
  f.anchorMonth += delta;
  if (f.anchorMonth < 0) {
    f.anchorMonth = 11;
    f.anchorYear--;
  } else if (f.anchorMonth > 11) {
    f.anchorMonth = 0;
    f.anchorYear++;
  }
  updateAdminAnalyticsDateLabel(key);
  refreshAdminAnalyticsByKey(key);
}
window.navAdminAnalyticsMonth = navAdminAnalyticsMonth;

function setAdminAnalyticsRange(key, rangeVal) {
  const f = _adminAnalyticsFilters[key];
  if (!f) return;
  f.rangeMonths = parseInt(rangeVal, 10) || 12;
  updateAdminAnalyticsFilterButtonStates(key);
  refreshAdminAnalyticsByKey(key);
}
window.setAdminAnalyticsRange = setAdminAnalyticsRange;

function promptAdminAnalyticsCustomRange(key) {
  const cur = (_adminAnalyticsFilters[key] && _adminAnalyticsFilters[key].rangeMonths) || 12;
  let val = prompt('Enter number of months (max 3 digits, e.g. 1 to 999):', cur);
  if (val === null) return;
  val = val.trim();
  if (!/^\d{1,3}$/.test(val) || parseInt(val, 10) <= 0) {
    alert('Please enter a valid positive number up to 3 digits (1 - 999).');
    return;
  }
  setAdminAnalyticsRange(key, parseInt(val, 10));
}
window.promptAdminAnalyticsCustomRange = promptAdminAnalyticsCustomRange;

let _activeAdminPickerKey = 'insights-fin-line';
let _tempPickerMonth = new Date().getMonth();
let _tempPickerYear = new Date().getFullYear();

