// Format small and regular percentages for analytics cards without truncating to 0%
function formatAnalyticsPct(val) {
  if (val == null || isNaN(val)) return '0%';
  const num = Number(val);
  if (num === 0) return '0%';
  if (Math.abs(num) > 0 && Math.abs(num) < 0.01) return num > 0 ? '<0.01%' : '>-0.01%';
  if (Math.abs(num) < 1) {
    return num.toFixed(2) + '%';
  }
  const s = num.toFixed(1);
  return (s.endsWith('.0') ? s.slice(0, -2) : s) + '%';
}

// Format percentage difference (+/-) for trend change stats
function formatAnalyticsDiffPct(diff) {
  if (diff == null || isNaN(diff)) return '+0% change';
  const num = Number(diff);
  if (num === 0) return '+0% change';
  const prefix = num > 0 ? '+' : '';
  if (Math.abs(num) > 0 && Math.abs(num) < 0.01) return prefix + '<0.01% change';
  if (Math.abs(num) < 1) {
    return prefix + num.toFixed(2) + '% change';
  }
  const s = num.toFixed(1);
  return prefix + (s.endsWith('.0') ? s.slice(0, -2) : s) + '% change';
}
window.formatAnalyticsPct = formatAnalyticsPct;
window.formatAnalyticsDiffPct = formatAnalyticsDiffPct;

