function onExportRangeModeChange(mode) {
  const badge = document.getElementById('exp-period-selected-badge');
  const monthNames = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];
  const now = new Date();
  const curMonth = now.getMonth();
  const curYear = now.getFullYear();

  if (mode === 'specific') {
    // Uncheck presets and custom
    document.querySelectorAll('#exp-preset-grid input[type="radio"]').forEach(r => { r.checked = false; });
    const radioSpec = document.getElementById('exp-range-specific');
    if (radioSpec) radioSpec.checked = true;
    const radioCust = document.getElementById('exp-range-custom');
    if (radioCust) radioCust.checked = false;

    const mSel = document.getElementById('exp-specific-month');
    const yInput = document.getElementById('exp-specific-year');
    const m = mSel ? parseInt(mSel.value, 10) : curMonth;
    const y = yInput ? parseInt(yInput.value, 10) : curYear;
    if (badge) badge.textContent = `Active: ${monthNames[m]} ${y}`;
  } else if (mode === 'custom') {
    // Uncheck presets and specific
    document.querySelectorAll('#exp-preset-grid input[type="radio"]').forEach(r => { r.checked = false; });
    const radioSpec = document.getElementById('exp-range-specific');
    if (radioSpec) radioSpec.checked = false;
    const radioCust = document.getElementById('exp-range-custom');
    if (radioCust) radioCust.checked = true;

    const k = _customExportMonths || 12;
    if (badge) badge.textContent = `Active: Last ${k} Months`;
  } else {
    // Preset mode: uncheck specific and custom
    const radioSpec = document.getElementById('exp-range-specific');
    if (radioSpec) radioSpec.checked = false;
    const radioCust = document.getElementById('exp-range-custom');
    if (radioCust) radioCust.checked = false;

    const labels = {
      this_month: 'This Month (' + monthNames[curMonth] + ')',
      last_month: 'Last Month',
      last_2_months: 'Last 2 Months',
      last_4_months: 'Last 4 Months',
      last_6_months: 'Last 6 Months',
      last_12_months: 'Last 12 Months'
    };
    if (badge) badge.textContent = 'Active: ' + (labels[mode] || mode);
  }
}
window.onExportRangeModeChange = onExportRangeModeChange;

