function openEditUserModal() {
  if (!selectedUserId) return;
  const list = currentUserTab === 'staff' ? USERS : CUSTOMERS;
  const user = list.find(u => u.id === selectedUserId);
  if (!user) return;

  const titleEl = document.getElementById('user-modal-title');
  if (titleEl) titleEl.textContent = 'Edit User Details';

  const idEl = document.getElementById('user-modal-id');
  if (idEl) idEl.value = user.id;

  const nameParts = (user.name || '').trim().split(' ');
  const fname = user.fname || nameParts[0] || '';
  const lname = user.lname || nameParts.slice(1).join(' ') || '';

  const fnameEl = document.getElementById('user-fname');
  if (fnameEl) fnameEl.value = fname;

  const lnameEl = document.getElementById('user-lname');
  if (lnameEl) lnameEl.value = lname;

  const mnameEl = document.getElementById('user-mname');
  if (mnameEl) mnameEl.value = user.mname || '';

  const phoneEl = document.getElementById('user-phone');
  if (phoneEl) {
    let p = (user.phone || '').trim();
    if (p.startsWith('+63')) p = p.substring(3);
    p = p.replace(/^0+/, ''); // Visually strip leading 0 (as +63 represents the 0)
    phoneEl.value = p;
  }

  const emailEl = document.getElementById('user-email');
  if (emailEl) emailEl.value = user.email || '';

  const roleEl = document.getElementById('user-role');
  if (roleEl) roleEl.value = user.role || 'Staff';

  // In edit mode, hide password area completely
  const passGrp = document.getElementById('user-password-group');
  if (passGrp) passGrp.style.display = 'none';

  const overlay = document.getElementById('user-modal-overlay');
  if (overlay) overlay.classList.add('on');
  const modal = document.getElementById('user-modal');
  if (modal) modal.classList.add('open');
}


function toggleUserModalPassword() {
  const input = document.getElementById('user-password');
  input.type = input.type === 'password' ? 'text' : 'password';
}

function autoGeneratePassword() {
  const chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
  const nums = "0123456789";
  const specs = "!@#$%^&*()";
  let pass = "";
  pass += nums[Math.floor(Math.random() * nums.length)];
  pass += specs[Math.floor(Math.random() * specs.length)];
  for (let i = 0; i < 6; i++) pass += chars[Math.floor(Math.random() * chars.length)];
  pass = pass.split('').sort(() => 0.5 - Math.random()).join('');
  document.getElementById('user-password').value = pass;
  document.getElementById('user-password').type = 'text';
}


async function fetchCustomers() {
  try {
    const sb = window.supabaseClient;
    if (sb) {
      const { data: rows, error } = await sb
        .from('users')
        .select('*');

      if (!error && rows) {
        const filteredRows = rows.filter(r => {
          const role = (r.role || '').toLowerCase().trim();
          return role === 'customer';
        });

        CUSTOMERS = filteredRows.map(data => {
          let lastLoginStr = 'Never';
          if (data.last_login || data.created_at) {
            const d = data.last_login || data.created_at;
            lastLoginStr = new Date(d).toLocaleString();
          }

          return {
            id: data.id,
            name: data.name || (data.fname ? (data.fname + ' ' + (data.lname || '')).trim() : 'No Name'),
            fname: data.fname || '',
            lname: data.lname || '',
            mname: data.mname || '',
            email: data.email || 'No Email',
            phone: data.phone || '',
            password: data.password || '',
            role: data.role || 'customer',
            status: data.status || 'Active',
            lastLogin: lastLoginStr
          };
        });
        if (currentUserTab === 'customers') renderUsersSection();
        return;
      }
    }
  } catch (err) {
    console.warn('Supabase fetchCustomers failed, falling back:', err);
  }

  const { collection, getDocs, query, where } = window.firebaseFns || {};
  const db = window.firebaseDB;
  if (!db || !collection) return;

  try {
    const q = query(collection(db, 'users'), where('role', '==', 'customer'));
    const snap = await getDocs(q);
    CUSTOMERS = [];
    snap.forEach(doc => {
      const data = doc.data();
      let lastLoginStr = 'Never';
      if (data.lastLogin) {
        const d = data.lastLogin.toDate ? data.lastLogin.toDate() : new Date(data.lastLogin);
        lastLoginStr = d.toLocaleString();
      }

      CUSTOMERS.push({
        id: doc.id,
        name: data.name || 'No Name',
        fname: data.fname || '',
        lname: data.lname || '',
        mname: data.mname || '',
        email: data.email || 'No Email',
        phone: data.phone || '',
        password: data.password || '',
        role: data.role || 'customer',
        status: data.status || 'Active',
        lastLogin: lastLoginStr
      });
    });
    if (currentUserTab === 'customers') renderUsersSection();
  } catch (err) {
    console.error('Error fetching customers:', err);
  }
}

function switchUserTab(tab) {
  currentUserTab = tab;
  selectedUserId = null;

  // Update UI tabs
  document.querySelectorAll('#section-users .tab-btn').forEach(btn => btn.classList.remove('active'));
  if (tab === 'staff') {
    const b = document.getElementById('btn-tab-staff');
    if (b) b.classList.add('active');
    fetchStaff();
  } else {
    const b = document.getElementById('btn-tab-customers');
    if (b) b.classList.add('active');
    fetchCustomers();
  }

  window._usersPage = 1;
  const searchInput = document.getElementById('user-search-input');
  if (searchInput) {
    searchInput.value = '';
    searchInput.placeholder = tab === 'staff' ? 'Search staff/admin by name...' : 'Search customer by name...';
  }

  renderUsersSection();
}
window.switchUserTab = switchUserTab;

function renderUsersSection() {
  const tbody = document.getElementById('users-tbody');
  if (!tbody) return;

  const list = currentUserTab === 'staff' ? USERS : CUSTOMERS;

  const activeCount = list.filter(u => u.status === 'Active').length;
  const inactiveCount = list.length - activeCount;

  setElText('user-stat-total', list.length);
  setElText('user-stat-active', activeCount);
  setElText('user-stat-inactive', inactiveCount);

  // Update panel title
  const panelTitle = document.querySelector('#section-users .panel-title') || document.querySelector('#user-management .panel-title');
  if (panelTitle) {
    panelTitle.textContent = currentUserTab === 'staff' ? 'System Accounts' : 'Customer Database';
  }

  const query = ((document.getElementById('user-search-input') || {}).value || '').trim().toLowerCase();
  const filtered = list.filter(u => {
    if (!query) return true;
    const name = (u.name || '').toLowerCase();
    const email = (u.email || '').toLowerCase();
    const role = (u.role || '').toLowerCase();
    return name.includes(query) || email.includes(query) || role.includes(query);
  });

  const paginationEl = document.getElementById('users-pagination');

  if (!filtered.length) {
    if (paginationEl) {
      paginationEl.innerHTML = '';
      paginationEl.style.display = 'none';
    }
    tbody.innerHTML = `<tr><td colspan="3" style="text-align:center;padding:32px;color:var(--text-dim);">No users found${query ? ' matching "' + escHtml(query) + '"' : ''}.</td></tr>`;
    updateUserActionButtons();
    return;
  }

  const pageSize = 20;
  window._usersPage = window._usersPage || 1;
  const totalPages = Math.ceil(filtered.length / pageSize) || 1;
  if (window._usersPage > totalPages) window._usersPage = totalPages;
  if (window._usersPage < 1) window._usersPage = 1;
  const startIdx = (window._usersPage - 1) * pageSize;
  const pageItems = filtered.slice(startIdx, startIdx + pageSize);

  tbody.innerHTML = pageItems.map(u => `
    <tr onclick="selectUserRow(this, '${u.id}')" class="${selectedUserId === u.id ? 'selected' : ''}">
      <td class="item-name">${escHtml(u.name)}</td>
      <td style="text-transform: capitalize;">${u.role}</td>
      <td><span class="badge ${u.status ? u.status.toLowerCase() : 'active'}">${u.status || 'Active'}</span></td>
    </tr>
  `).join('');

  if (paginationEl) {
    if (filtered.length <= pageSize) {
      paginationEl.innerHTML = '';
      paginationEl.style.display = 'none';
    } else {
      paginationEl.style.display = 'flex';
      paginationEl.innerHTML = `
        <div style="display:flex; align-items:center; justify-content:space-between; width:100%; padding:14px 20px; border-top:1px solid var(--border);">
          <span style="font-size:12px; color:var(--text-dim);">Showing ${startIdx + 1}-${Math.min(startIdx + pageSize, filtered.length)} of ${filtered.length} ${currentUserTab === 'staff' ? 'accounts' : 'customers'}</span>
          <div style="display:flex; align-items:center; gap:10px;">
            <button class="btn-outline" style="padding:5px 12px; font-size:11.5px; font-weight:700; border-radius:6px; cursor:${window._usersPage > 1 ? 'pointer' : 'not-allowed'}; opacity:${window._usersPage > 1 ? '1' : '0.4'};" onclick="changeUsersPage(-1)" ${window._usersPage <= 1 ? 'disabled' : ''}>&larr; Prev</button>
            <span style="font-size:12px; font-weight:700; color:var(--text-mid);">Page ${window._usersPage} of ${totalPages}</span>
            <button class="btn-outline" style="padding:5px 12px; font-size:11.5px; font-weight:700; border-radius:6px; cursor:${window._usersPage < totalPages ? 'pointer' : 'not-allowed'}; opacity:${window._usersPage < totalPages ? '1' : '0.4'};" onclick="changeUsersPage(1)" ${window._usersPage >= totalPages ? 'disabled' : ''}>Next &rarr;</button>
          </div>
        </div>
      `;
    }
  }

  updateUserActionButtons();
}

function changeUsersPage(delta) {
  window._usersPage = (window._usersPage || 1) + delta;
  renderUsersSection();
}
window.changeUsersPage = changeUsersPage;

function selectUserRow(el, userId) {
  selectedUserId = userId;
  document.querySelectorAll('#users-tbody tr').forEach(tr => tr.classList.remove('selected'));
  el.classList.add('selected');
  updateUserActionButtons();
}

function updateUserActionButtons() {
  const editBtn = document.getElementById('user-edit-btn');
  const statusBtn = document.getElementById('user-status-btn');
  if (!editBtn || !statusBtn) return;

  if (selectedUserId) {
    const list = currentUserTab === 'staff' ? USERS : CUSTOMERS;
    const user = list.find(u => u.id === selectedUserId);
    const isAdmin = user && user.role && user.role.toLowerCase() === 'admin';

    editBtn.disabled = false;
    editBtn.style.display = currentUserTab === 'staff' ? 'inline-block' : 'none';

    // Admin accounts can never be deactivated
    if (isAdmin) {
      statusBtn.disabled = true;
      statusBtn.title = 'Admin accounts cannot be deactivated';
      statusBtn.style.opacity = '0.5';
      statusBtn.style.cursor = 'not-allowed';
    } else {
      statusBtn.disabled = false;
      statusBtn.title = '';
      statusBtn.style.opacity = '1';
      statusBtn.style.cursor = 'pointer';
    }

    statusBtn.innerHTML = user && user.status === 'Inactive' ? ' Activate Account' : ' Deactivate Account';
  } else {
    editBtn.disabled = true;
    statusBtn.disabled = true;
    statusBtn.title = '';
    statusBtn.style.opacity = '1';
    statusBtn.style.cursor = 'default';
    editBtn.style.display = 'inline-block';
  }
}

function openAddUserModal() {
  selectedUserId = null;
  document.querySelectorAll('#users-tbody tr').forEach(tr => tr.classList.remove('selected'));
  updateUserActionButtons();

  document.getElementById('user-modal-title').textContent = ' Add New User';
  document.getElementById('user-modal-id').value = '';
  document.getElementById('user-fname').value = '';
  document.getElementById('user-lname').value = '';
  document.getElementById('user-mname').value = '';
  document.getElementById('user-phone').value = '';
  document.getElementById('user-email').value = '';
  document.getElementById('user-password').value = '';
  document.getElementById('user-password').type = 'password';
  document.getElementById('user-role').value = 'Staff';

  // Ensure password input group is visible for Add New User
  const passGrp = document.getElementById('user-password-group');
  if (passGrp) passGrp.style.display = 'block';

  document.getElementById('user-modal-overlay').classList.add('on');
  document.getElementById('user-modal').classList.add('open');
}


function closeUserModal() {
  document.getElementById('user-modal-overlay').classList.remove('on');
  document.getElementById('user-modal').classList.remove('open');
}

async function saveUser() {
  const id = document.getElementById('user-modal-id').value;
  const fname = document.getElementById('user-fname').value.trim();
  const lname = document.getElementById('user-lname').value.trim();
  const mname = document.getElementById('user-mname').value.trim();
  const phoneDigits = document.getElementById('user-phone').value.trim().replace(/^0+/, '');
  const email = document.getElementById('user-email').value.trim();
  const pass = document.getElementById('user-password').value;
  const role = document.getElementById('user-role').value;

  if (!fname || !lname || !email || !phoneDigits) {
    alert('Please fill in all required fields (First Name, Last Name, Phone, Email).');
    return;
  }

  // Reject numbers and special characters in name fields
  const nameRegex = /^[a-zA-Z\u00C0-\u024F\s'-]+$/;
  if (!nameRegex.test(fname)) {
    alert('First Name must only contain letters, spaces, hyphens, and apostrophes (no numbers or special characters).');
    return;
  }
  if (!nameRegex.test(lname)) {
    alert('Last Name must only contain letters, spaces, hyphens, and apostrophes (no numbers or special characters).');
    return;
  }
  if (mname && !nameRegex.test(mname)) {
    alert('Middle Name must only contain letters, spaces, hyphens, and apostrophes (no numbers or special characters).');
    return;
  }

  // Standard format in Supabase: 09XXXXXXXXX
  const phone = '0' + phoneDigits;

  if (!/^09\d{9}$/.test(phone)) {
    alert("Please enter a valid 10-digit mobile number starting with 9 (e.g. 9123456789).");
    return;
  }

  const isDuplicateEmail = USERS.some(u => u.email && u.email.toLowerCase() === email.toLowerCase() && u.id !== id);
  if (isDuplicateEmail) {
    alert("This email address is already in use by another user. Please use a different email.");
    return;
  }

  if (id) {
    // Edit existing : update local array and Supabase (do NOT update password)
    const list = currentUserTab === 'staff' ? USERS : CUSTOMERS;
    const user = list.find(u => u.id === id);
    if (user) {
      user.name = fname + ' ' + lname;
      user.fname = fname;
      user.lname = lname;
      user.mname = mname;
      user.email = email;
      user.phone = phone;
      user.role = role;
    }

    // Persist to Supabase
    const sb = window.supabaseClient;
    if (sb) {
      try {
        const updatePayload = {
          name: fname + ' ' + lname,
          fname: fname,
          lname: lname,
          mname: mname,
          email: email,
          phone: phone,
          role: role
        };
        const { error: uErr } = await sb.from('users').update(updatePayload).eq('id', id);
        if (uErr) throw new Error(uErr.message);
        showToast('User updated successfully!', 'success');

        // Comprehensive Admin Activity Logging for user edit
        try {
          if (typeof window.logAdminActivity === 'function') {
            window.logAdminActivity(
              'Updated User Details',
              `Updated user profile for "${fname} ${lname}" (Role: ${role}, Email: ${email}).`,
              { category: 'Users', user_email: email, role: role }
            );
          }
        } catch (_logErr) {
          console.warn('Logging saveUser edit failed:', _logErr);
        }
      } catch (e) {
        console.error('[saveUser] Supabase update failed:', e);
        showToast('Saved locally but Supabase sync failed: ' + e.message, 'error');
      }
    }

    // Check if the edited user is the currently logged in admin/staff user and sync session
    const syncSessionUser = (storageKey) => {
      const stored = sessionStorage.getItem(storageKey) || localStorage.getItem(storageKey);
      if (stored) {
        try {
          const parsed = JSON.parse(stored);
          const parsedId = parsed.id || parsed.user_id;
          const parsedEmail = (parsed.email || '').toLowerCase().trim();
          if ((parsedId && parsedId === id) || (parsedEmail && parsedEmail === email.toLowerCase().trim())) {
            parsed.name = fname + ' ' + lname;
            parsed.fname = fname;
            parsed.lname = lname;
            parsed.mname = mname;
            parsed.email = email;
            parsed.phone = phone;
            parsed.role = role;
            if (parsed.user_metadata) {
              parsed.user_metadata.name = fname + ' ' + lname;
              parsed.user_metadata.fname = fname;
              parsed.user_metadata.lname = lname;
              parsed.user_metadata.phone = phone;
            }
            sessionStorage.setItem(storageKey, JSON.stringify(parsed));
            localStorage.setItem(storageKey, JSON.stringify(parsed));
            return parsed;
          }
        } catch (e) {}
      }
      return null;
    };

    const updatedAdmin = syncSessionUser('halden_admin');
    syncSessionUser('halden_staff');

    if (updatedAdmin) {
      if (window.currentUser) {
        Object.assign(window.currentUser, updatedAdmin);
      }
      const adminNameEl = document.getElementById('admin-name');
      if (adminNameEl) {
        adminNameEl.textContent = updatedAdmin.name || `${fname} ${lname}`;
      }
      const dashGreeting = document.getElementById('dash-greeting');
      if (dashGreeting) {
        const h = new Date().getHours();
        const greeting = h < 12 ? 'Good morning' : h < 17 ? 'Good afternoon' : 'Good evening';
        dashGreeting.textContent = `${greeting}, ${fname || 'Admin'} `;
      }
    }

    closeUserModal();
    renderUsersSection();
  } else {
    // Add new user via Supabase RPC
    if (!pass || pass.length < 8 || !/\d/.test(pass) || !/[!@#\$%\^\&\*\(\)\_\+\-\=\[\]\{\}\;\:\'\"\,\<\>\.\?\/\\]/.test(pass)) {
      alert("Password must be at least 8 characters with 1 number and 1 special character.");
      return;
    }

    const btn = document.getElementById('btn-save-user');
    if (btn) btn.innerHTML = 'Saving...';

    try {
      const { data, error } = await window.supabaseClient.rpc('admin_create_staff', {
        p_email: email,
        p_password: pass,
        p_fname: fname,
        p_lname: lname,
        p_mname: mname,
        p_phone: phone,
        p_role: role
      });

      if (error) throw new Error(error.message);

      USERS.push({
        id: data?.user_id || 'u' + Date.now(),
        name: fname + ' ' + lname,
        email: email,
        phone: phone,
        role: role,
        status: 'Active',
        lastLogin: 'Never'
      });

      // Comprehensive Admin Activity Logging for new user creation
      try {
        if (typeof window.logAdminActivity === 'function') {
          window.logAdminActivity(
            'Added New User',
            `Created new user "${fname} ${lname}" (Role: ${role}, Email: ${email}).`,
            { category: 'Users', user_email: email, role: role }
          );
        }
      } catch (_logErr) {
        console.warn('Logging saveUser new failed:', _logErr);
      }

      closeUserModal();
      renderUsersSection();
      showToast("Staff User created successfully!", "success");
    } catch (err) {
      console.error(err);
      alert('Failed to create user: ' + err.message);
    } finally {
      if (btn) btn.innerHTML = 'Save User Details';
    }
  }
}

async function toggleUserStatus() {
  if (!selectedUserId) return;

  const list = currentUserTab === 'staff' ? USERS : CUSTOMERS;
  const user = list.find(u => u.id === selectedUserId);
  if (!user) return;

  // Admin accounts can never be deactivated
  if (user.role && user.role.toLowerCase() === 'admin') {
    alert('Admin accounts cannot be deactivated.');
    return;
  }

  const newStatus = user.status === 'Active' ? 'Inactive' : 'Active';
  const action = newStatus === 'Active' ? 'activate' : 'deactivate';
  if (!confirm(`Are you sure you want to ${action} ${user.name}?`)) return;

  if (currentUserTab === 'staff') {
    // Update Supabase
    const sb = window.supabaseClient;
    if (sb) {
      try {
        showToast('Updating staff status...', 'info');
        const { error } = await sb.from('users').update({ status: newStatus }).eq('id', selectedUserId);
        if (error) throw new Error(error.message);
        user.status = newStatus;

        // Comprehensive Admin Activity Logging for user status change
        try {
          if (typeof window.logAdminActivity === 'function') {
            window.logAdminActivity(
              newStatus === 'Active' ? 'Activated User' : 'Deactivated User',
              `Changed status for user "${user.name}" (${user.email || user.role}) to ${newStatus}.`,
              { category: 'Users', user_id: selectedUserId, user_name: user.name, new_status: newStatus }
            );
          }
        } catch (_logErr) {
          console.warn('Logging toggleUserStatus failed:', _logErr);
        }

        renderUsersSection();
        showToast(`Account ${newStatus === 'Active' ? 'activated' : 'deactivated'} successfully!`, 'success');

        // Check if currently logged in user was deactivated
        const loggedInUserStr = sessionStorage.getItem('halden_admin') || localStorage.getItem('halden_admin');
        if (loggedInUserStr && newStatus === 'Inactive') {
          try {
            const loggedInUser = JSON.parse(loggedInUserStr);
            const loggedInId = loggedInUser.id || loggedInUser.user_id;
            if (loggedInId === selectedUserId) {
              alert('Your account has been deactivated. You will now be logged out.');
              if (typeof adminLogout === 'function') {
                adminLogout();
              } else {
                sessionStorage.clear();
                localStorage.removeItem('halden_admin');
                window.location.reload();
              }
              return;
            }
          } catch (e) {
            console.error('Error checking logged in user id:', e);
          }
        }
      } catch (err) {
        console.error('Error updating staff status:', err);
        showToast('Failed to update status: ' + err.message, 'error');
      }
    } else {
      // Fallback: local only
      user.status = newStatus;
      renderUsersSection();
    }
  } else {
    // Update Firebase and Supabase for customers
    const { doc, updateDoc } = window.firebaseFns || {};
    const db = window.firebaseDB;
    try {
      showToast('Updating customer status...', 'info');
      if (doc && updateDoc && db) {
        await updateDoc(doc(db, 'users', user.id), {
          status: newStatus
        });
      }
      const sb = window.supabaseClient;
      if (sb) {
        await sb.from('users').update({ status: newStatus }).eq('id', user.id);
      }
      user.status = newStatus;
      showToast('Customer status updated!', 'success');

      // Admin Activity Logging for customer account status change (previously missing)
      try {
        if (typeof window.logAdminActivity === 'function') {
          window.logAdminActivity(
            newStatus === 'Active' ? 'Activated User' : 'Deactivated User',
            `Changed status for customer "${user.name}" (${user.email || 'no email'}) to ${newStatus}.`,
            { category: 'Users', user_id: user.id, user_name: user.name, new_status: newStatus }
          );
        }
      } catch (_logErr) {
        console.warn('Logging customer status change failed:', _logErr);
      }
      renderUsersSection();
    } catch (err) {
      console.error('Error updating customer status:', err);
      showToast('Failed to update status', 'error');
    }
  }
}

// ===== REAL-TIME ACCOUNT DEACTIVATION WATCHDOG =====
function startAdminDeactivationWatchdog() {
  if (window._adminDeactWatchdogStarted) return;
  window._adminDeactWatchdogStarted = true;

  const checkAdminStatus = async () => {
    if (document.hidden) return;
    try {
      const loggedInStr = sessionStorage.getItem('halden_admin') || localStorage.getItem('halden_admin');
      if (!loggedInStr) return;
      const loggedInUser = JSON.parse(loggedInStr);
      const uid = loggedInUser.id || loggedInUser.user_id;
      if (!uid || !window.supabaseClient) return;

      const { data, error } = await window.supabaseClient
        .from('users')
        .select('status')
        .eq('id', uid)
        .maybeSingle();

      if (!error && data && data.status && data.status.toLowerCase() === 'inactive') {
        alert('Your account has been deactivated by an administrator. You will now be logged out.');
        if (typeof adminLogout === 'function') {
          adminLogout();
        } else {
          sessionStorage.clear();
          localStorage.removeItem('halden_admin');
          window.location.href = 'index.html';
        }
      }
    } catch (e) {
      // Ignore background network errors
    }
  };

  setInterval(checkAdminStatus, 30000);
  document.addEventListener('visibilitychange', () => {
    if (!document.hidden) checkAdminStatus();
  });
}
startAdminDeactivationWatchdog();

window.renderUsersSection = renderUsersSection;
window.selectUserRow = selectUserRow;
window.openAddUserModal = openAddUserModal;
window.openEditUserModal = openEditUserModal;
window.closeUserModal = closeUserModal;
window.saveUser = saveUser;
window.toggleUserStatus = toggleUserStatus;

// ===== EXECUTION DAY & SETTLEMENT =====
let activeExecutionResId = null;
let adhocCharges = [];
let execDayProcSorted = {};

const EXEC_PROC_CATS = [
  { key: 'food',             label: 'Dishes & Ingredients' },
  { key: 'equipment',        label: 'Event Equipment' },
  { key: 'decoration',       label: 'Aesthetic & Decor' },
  { key: 'personnel',        label: 'Talent & Personnel' },
  { key: 'staff_allocation', label: 'Staff Allocation' },
  { key: 'transportation',   label: 'Transportation' }
];

// ---- Month-grouped reservation list ----
// Exclude completed and cancelled reservations from Execution Day display
const EXEC_APPROVED_STATUSES = ['confirmed', 'preparing', 'procurement', 'procuring', 'on-going'];
const MONTH_NAMES = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

function renderExecutionDayReservations(skipAutoSelect) {
  const container = document.getElementById('execution-res-list');
  if (!container) return;

  // All approved reservations (same set as Reservation Details Handling)
  const approved = RESERVATIONS.filter(r => {
    const st = String(r.status || '').toLowerCase();
    return EXEC_APPROVED_STATUSES.includes(st) && st !== 'completed' && st !== 'cancelled';
  });

  if (approved.length === 0) {
    const emptyHtml = '<div style="padding:20px;color:var(--text-dim);font-size:12px;text-align:center;line-height:1.6;">No approved reservations found.<br>Approve a reservation first.</div>';
    container.innerHTML = emptyHtml;
    const mobContainer = document.getElementById('execution-res-list-mobile');
    if (mobContainer) mobContainer.innerHTML = emptyHtml;
    return;
  }

  // Group by year-month of event date
  const groups = {};
  const todayMid = new Date();
  todayMid.setHours(0, 0, 0, 0);
  approved.forEach(r => {
    const d = r.date ? new Date(r.date + 'T00:00:00') : null;
    if (d && !isNaN(d)) {
      const dl = Math.ceil((d - todayMid) / (1000 * 60 * 60 * 24));
      if (dl >= 0) {
        checkAndNotifyExecutionCountdown(r, dl);
      }
    }
    const key = d && !isNaN(d) ? `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}` : 'undated';
    if (!groups[key]) groups[key] = { label: d && !isNaN(d) ? MONTH_NAMES[d.getMonth()] + ' ' + d.getFullYear() : 'No Date', items: [] };
    groups[key].items.push(r);
  });

  // Sort groups chronologically
  const sortedKeys = Object.keys(groups).sort();

  let html = '';
  sortedKeys.forEach(key => {
    const grp = groups[key];
    // Determine if group contains the active selection
    const hasActive = grp.items.some(r => r.id === activeExecutionResId);
    html += `
      <div class="exec-month-group" style="border-bottom:1px solid var(--border);">
        <div class="exec-month-header" onclick="toggleExecMonthGroup(this)"
          style="display:flex;align-items:center;justify-content:space-between;padding:10px 14px;cursor:pointer;background:var(--bg3);user-select:none;gap:6px;">
          <span style="font-size:11px;font-weight:700;color:var(--gold);text-transform:uppercase;letter-spacing:1.2px;">${grp.label}</span>
          <div style="display:flex;align-items:center;gap:8px;">
            <span style="font-size:10px;font-weight:700;color:var(--gold);">${grp.items.length}</span>
            <span class="exec-month-arrow" style="font-size:11px;color:var(--text-dim);transition:transform 0.2s;">▾</span>
          </div>
        </div>
        <div class="exec-month-items" style="display:block;">
          ${grp.items.map(ev => {
      const isActive = activeExecutionResId === ev.id;
      const statusBadge = ev.status === 'on-going' ? '<span style="font-size:9px;background:transparent;color:var(--green);padding:1px 0;font-weight:700;margin-left:4px;">LIVE</span>'
        : ev.status === 'completed' ? '<span style="font-size:9px;background:transparent;color:var(--green);padding:1px 0;">done</span>'
          : '';
      return `<div onclick="selectExecutionEvent('${ev.id}')"
              style="padding:11px 14px;cursor:pointer;border-bottom:1px solid rgba(255,255,255,0.04);transition:background 0.15s;${isActive ? 'background:rgba(212,175,55,0.1);border-left:3px solid var(--gold);' : 'border-left:3px solid transparent;'}">
              <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:6px;">
                  <div style="font-weight:600;color:${isActive ? 'var(--gold)' : 'var(--cream)'};font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escHtml(ev.packageName || ev.package || ev.type || 'Package')}${statusBadge}</div>
                  <div style="font-size:11px;color:var(--text-dim);margin-top:2px;">${escHtml(ev.client || ':')} &middot; ${escHtml(ev.type || ':')}</div>
                  <div style="font-size:11px;color:var(--text-dim);">${escHtml(ev.date || ':')}</div>
              </div>
            </div>`;
    }).join('')}
        </div>
      </div>`;
  });

  container.innerHTML = html;
  const mobContainer = document.getElementById('execution-res-list-mobile');
  if (mobContainer) mobContainer.innerHTML = html;

  // Auto-select active, live, or soonest approved reservation if none selected (both Desktop & Mobile)
  if (approved.length > 0 && !skipAutoSelect) {
    let target = null;
    if (activeExecutionResId) {
      target = approved.find(r => r.id === activeExecutionResId);
    }
    if (!target) {
      const savedId = localStorage.getItem('activeExecResId') || sessionStorage.getItem('activeExecResId');
      if (savedId) target = approved.find(r => r.id === savedId);
    }
    if (!target) {
      // Prioritize ongoing LIVE reservation
      target = approved.find(r => String(r.status || '').toLowerCase() === 'on-going');
    }
    if (!target) {
      const todayStr = new Date().toISOString().slice(0, 10);
      const upcoming = approved.filter(r => r.date && r.date >= todayStr).sort((a, b) => (a.date > b.date ? 1 : -1));
      target = upcoming[0] || approved[0];
    }
    const emptyState = document.getElementById('execution-empty-state');
    const isEmptyVisible = emptyState && emptyState.style.display !== 'none';
    const mobDrawer = document.getElementById('exec-mobile-res-drawer');
    const isMobDrawerOpen = mobDrawer && mobDrawer.classList.contains('open');
    if (target && !isMobDrawerOpen && (!activeExecutionResId || target.id !== activeExecutionResId || isEmptyVisible)) {
      setTimeout(() => selectExecutionEvent(target.id), 50);
    }
  }
}

function toggleExecMonthGroup(headerEl) {
  const items = headerEl.nextElementSibling;
  const arrow = headerEl.querySelector('.exec-month-arrow');
  const isOpen = items.style.display !== 'none';
  items.style.display = isOpen ? 'none' : 'block';
  if (arrow) arrow.textContent = isOpen ? '▸' : '▾';
}
window.toggleExecMonthGroup = toggleExecMonthGroup;

function toggleExecMobileResDrawer(open) {
  const drawer = document.getElementById('exec-mobile-res-drawer');
  if (!drawer) return;
  if (open === undefined) open = !drawer.classList.contains('open') && drawer.style.display === 'none';
  if (open) {
    drawer.classList.add('open');
    drawer.style.display = 'block';
    // Dynamic re-render ensures approved reservations are freshly populated into the drawer without auto-closing it
    if (typeof renderExecutionDayReservations === 'function') {
      renderExecutionDayReservations(true);
    } else {
      const pcList = document.getElementById('execution-res-list');
      const mobList = document.getElementById('execution-res-list-mobile');
      if (pcList && mobList && pcList.innerHTML) {
        mobList.innerHTML = pcList.innerHTML;
      }
    }
  } else {
    drawer.classList.remove('open');
    drawer.style.display = 'none';
  }
}
window.toggleExecMobileResDrawer = toggleExecMobileResDrawer;

async function selectExecutionEvent(id) {
  activeExecutionResId = id;
  try {
    sessionStorage.setItem('activeExecResId', id);
    localStorage.setItem('activeExecResId', id);
  } catch (e) { }
  renderExecutionDayReservations(); // Refresh list to highlight active
  toggleExecMobileResDrawer(false); // Close mobile drawer if open

  const res = RESERVATIONS.find(r => r.id === id);
  if (!res) return;

  // Pre-load additional reservation details (guest list, seating elements, event flow)
  try {
    if (typeof loadAdditionalReservationDetailsFromSupabase === 'function') {
      await loadAdditionalReservationDetailsFromSupabase(id);
    }
  } catch (errArd) {
    console.warn('[selectExecutionEvent] Error preloading extra details:', errArd);
  }

  // Fetch sorted status from Supabase for this reservation
  execDayProcSorted = {};
  let execStrategyData = null;
  try {
    const sb = window.supabaseClient;
    if (sb) {
      // Automatically evaluate and sync sorted resource prep statuses to Supabase
      if (typeof evaluateAndSyncReservationExecSorted === 'function') {
        try { await evaluateAndSyncReservationExecSorted(id); } catch(e){}
      }
      // Fetch sorted resource prep statuses
      try {
        const { data: sortedData } = await sb.from('reservation_exec_sorted')
          .select('*')
          .eq('reservation_id', id)
          .maybeSingle();
        if (sortedData) {
          execDayProcSorted = {
            food:             sortedData.sorted_food             || false,
            equipment:        sortedData.sorted_equipment        || false,
            decoration:       sortedData.sorted_decoration       || false,
            personnel:        sortedData.sorted_personnel        || false,
            staff_allocation: sortedData.sorted_staff_allocation || false,
            transportation:   sortedData.sorted_transportation   || false
          };
        }
      } catch (errSort) {}

      // Fetch execution plan (flexibility + phases) from execution_plans table
      try {
        const { data: stratData } = await sb.from('execution_plans')
          .select('*')
          .eq('reservation_id', id)
          .maybeSingle();
        if (stratData) {
          execStrategyData = stratData;
          let parsedPhases = [];
          if (Array.isArray(stratData.phases)) parsedPhases = stratData.phases;
          else if (typeof stratData.phases === 'string') {
            try { parsedPhases = JSON.parse(stratData.phases); } catch(pe) { parsedPhases = []; }
          }
          if (!res.executionPlan) {
            res.executionPlan = {
              flexibility: stratData.flexibility || 'strict',
              phases: parsedPhases
            };
          } else if (!res.executionPlan.phases || !res.executionPlan.phases.length) {
            res.executionPlan.phases = parsedPhases;
          }
        }
      } catch (errStrat) {}

      if (!execStrategyData && res.executionPlan) {
        execStrategyData = res.executionPlan;
      }

      // Fetch assigned staff from reservation_staff_assignments
      try {
        const { data: staffData } = await sb.from('reservation_staff_assignments')
          .select('staff_id')
          .eq('reservation_id', id);
        if (staffData && staffData.length > 0) {
          if (!execStrategyData) execStrategyData = {};
          execStrategyData.staff_assigned = staffData.map(r => {
            const u = (typeof USERS !== 'undefined' ? USERS : (window.USERS || [])).find(user => user.id === r.staff_id);
            return u ? u.name : r.staff_id;
          });
        } else if (res.staffing && res.staffing.assignments && res.staffing.assignments.length > 0) {
          if (!execStrategyData) execStrategyData = {};
          execStrategyData.staff_assigned = res.staffing.assignments.map(a => a.staffName || a.staff_name || a.staffId);
        }
      } catch (errStaff) {}
    }
    if (!execStrategyData && res.executionPlan) {
      execStrategyData = res.executionPlan;
    }
  } catch (e) {
    // Silently ignore — sorted boxes and strategy will safely show defaults
    if (!execStrategyData && res.executionPlan) execStrategyData = res.executionPlan;
  }

  const todayStr = new Date().toISOString().split('T')[0];

  const eventDate = res.date || '';

  // Determine if today IS the execution day
  const isExecutionDay = (eventDate === todayStr) || (res.status === 'on-going');

  // Always hide all states first
  document.getElementById('execution-empty-state').style.display = 'none';
  document.getElementById('execution-upcoming-state').style.display = 'none';
  document.getElementById('execution-active-content').style.display = 'none';

  // Title = package name; subtitle = client name + date
  const execPkgName = res.packageName || res.package || res.type || (res.client + '\u2019s Event');
  document.getElementById('execution-res-title').textContent = execPkgName;
  document.getElementById('execution-res-subtitle').textContent = (res.client || 'Client') + ' \u00b7 ' + (eventDate || '\u2014');

  if (isExecutionDay) {
    // Show upcoming state with Start button (same card, just with "Today" countdown)
    document.getElementById('execution-upcoming-state').style.display = 'block';
    renderExecUpcomingCard(res, document.getElementById('execution-upcoming-state'), execStrategyData);
    return;
    // (original GPS/settlement panel kept below for direct invocation)
    document.getElementById('execution-active-content').style.display = 'block';

    const rawAmt = typeof res.amount === 'string' ? parseFloat(res.amount.replace(/[^0-9.]/g, '')) || 0 : (res.amount || 0);
    document.getElementById('settle-base-total').textContent = '\u20b1' + rawAmt.toLocaleString(undefined, { minimumFractionDigits: 2 });

    adhocCharges = res.adhocCharges || [];
    renderSettlementPanel();

    document.getElementById('res-exec-status').textContent = 'Tracker idle.';
    document.getElementById('res-exec-eta').textContent = '\u2014';
    document.getElementById('res-exec-distance').textContent = '\u2014';
    document.getElementById('res-exec-speed').textContent = '\u2014';
    document.getElementById('res-exec-live-status').textContent = 'idle';
  } else {
    // Show upcoming execution day card
    const upcomingEl = document.getElementById('execution-upcoming-state');
    upcomingEl.style.display = 'block';
    renderExecUpcomingCard(res, upcomingEl, execStrategyData);
  }
}

function checkAndNotifyExecutionCountdown(res, daysLeft) {
  if (!res || daysLeft === null || daysLeft === undefined || daysLeft < 0) return;
  const notifService = window.HalServeNotifications || window.SmartServeNotifications;
  if (!notifService) return;
  // If automated emails are disabled universally, never send countdown email
  if (typeof notifService.isEmailsDisabled === 'function' && notifService.isEmailsDisabled()) return;

  // Check if a general email notification template ID is set and is NOT the OTP template
  const cfg = typeof notifService.getConfig === 'function' ? notifService.getConfig() : null;
  const tplId = (cfg && cfg.templateId) || window.EMAILJS_NOTIFICATION_TEMPLATE_ID;
  if (!tplId || tplId === 'template_zwfupwo') {
    return; // Don't trigger if only OTP template or no template is configured
  }

  const resKey = res.id || res.reference_id || res.refId || ((res.client || res.client_name || res.name || 'client') + '_' + (res.date || 'date'));
  const storageKey = 'hal_exec_countdown_notified_' + resKey;
  const lastNotifiedStr = localStorage.getItem(storageKey);
  const lastNotified = lastNotifiedStr !== null ? parseInt(lastNotifiedStr, 10) : null;
  
  if (lastNotified === null || daysLeft < lastNotified) {
    localStorage.setItem(storageKey, String(daysLeft));
    if (typeof notifService.notifyExecutionDayCountdown === 'function') {
      notifService.notifyExecutionDayCountdown({
        res: res,
        daysLeft: daysLeft,
        customerEmail: res.email || res.client_email || res.customerEmail,
        customerName: res.client || res.name || res.client_name || res.customerName || 'Valued Client',
        eventDate: res.date,
        eventTime: (res.startTime || res.time || '') + (res.endTime ? ' - ' + res.endTime : ''),
        packageName: res.packageName || res.package || res.eventType || res.type || 'Catering Package',
        venue: res.venue || res.venueAddress || res.location || 'Client Venue',
        reservationId: res.id || res.reference_id || 'N/A'
      });
    }
  }
}
window.checkAndNotifyExecutionCountdown = checkAndNotifyExecutionCountdown;

function renderExecUpcomingCard(res, container, execStrategyData) {
  const todayMidnight = new Date();
  todayMidnight.setHours(0, 0, 0, 0);

  let daysLeft = null;
  let formattedDate = res.date || '\u2014';
  let eventDateObj = null;

  if (res.date) {
    eventDateObj = new Date(res.date + 'T00:00:00');
    if (!isNaN(eventDateObj)) {
      daysLeft = Math.ceil((eventDateObj - todayMidnight) / (1000 * 60 * 60 * 24));
      formattedDate = eventDateObj.toLocaleDateString('en-PH', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
      if (daysLeft >= 0) {
        checkAndNotifyExecutionCountdown(res, daysLeft);
      }
    }
  }

  let countdownHtml = '';
  if (daysLeft !== null) {
    if (daysLeft < 0) {
      countdownHtml = `<div style="margin:20px 0;padding:14px 20px;background:rgba(239,68,68,0.08);border:1px solid rgba(239,68,68,0.2);border-radius:10px;text-align:center;">
        <div style="font-size:12px;color:var(--text-dim);text-transform:uppercase;letter-spacing:1px;margin-bottom:4px;">Event Has Passed</div>
        <div style="font-size:22px;font-weight:700;color:var(--red);">${Math.abs(daysLeft)} day${Math.abs(daysLeft) !== 1 ? 's' : ''} ago</div>
      </div>`;
    } else if (daysLeft === 0) {
      countdownHtml = `<div style="margin:20px 0;padding:14px 20px;background:rgba(34,197,94,0.1);border:1px solid rgba(34,197,94,0.25);border-radius:10px;text-align:center;">
        <div style="font-size:12px;color:var(--text-dim);text-transform:uppercase;letter-spacing:1px;margin-bottom:4px;">Execution Day Status</div>
        <div style="font-size:22px;font-weight:700;color:var(--green);">TODAY</div>
      </div>`;
    } else {
      const urgencyColor = daysLeft <= 7 ? 'var(--amber)' : daysLeft <= 30 ? 'var(--gold)' : 'var(--cream)';
      const urgencyBg = daysLeft <= 7 ? 'rgba(217,119,6,0.08)' : daysLeft <= 30 ? 'rgba(212,175,55,0.08)' : 'rgba(255,255,255,0.04)';
      const urgencyBorder = daysLeft <= 7 ? 'rgba(217,119,6,0.25)' : daysLeft <= 30 ? 'rgba(212,175,55,0.2)' : 'rgba(255,255,255,0.08)';
      countdownHtml = `<div style="margin:20px 0;padding:20px;background:${urgencyBg};border:1px solid ${urgencyBorder};border-radius:12px;text-align:center;">
        <div style="font-size:11px;color:var(--text-dim);text-transform:uppercase;letter-spacing:1.2px;margin-bottom:8px;">Days Until Execution</div>
        <div style="font-size:52px;font-weight:800;color:${urgencyColor};line-height:1;">${daysLeft}</div>
        <div style="font-size:12px;color:var(--text-dim);margin-top:6px;">day${daysLeft !== 1 ? 's' : ''} remaining</div>
      </div>`;
    }
  }

  const statusMap = { confirmed: { label: 'Confirmed', cls: 'confirmed' }, preparing: { label: 'Preparing', cls: 'warning' }, procuring: { label: 'Procuring', cls: 'warning' }, procurement: { label: 'Procurement', cls: 'warning' }, 'on-going': { label: 'On-Going', cls: 'ok' }, completed: { label: 'Completed', cls: 'confirmed' } };
  const statusInfo = statusMap[String(res.status).toLowerCase()] || { label: res.status || 'Unknown', cls: 'pending' };

  const rawAmt = typeof res.amount === 'string' ? parseFloat(res.amount.replace(/[^0-9.]/g, '')) || 0 : (res.amount || 0);
  const _det = (typeof computePricingDetails === 'function') ? computePricingDetails(res, res.pax, rawAmt) : null;
  const isMalabon = ([res.venue, res.venueName, res.venueAddress, res.venueAddr, res.city, res.venueCity, res.fullAddress, res.gpsVenueAddress].map(s => String(s || '').toLowerCase()).join(' ').includes('malabon'));
  let otc = isMalabon ? 0 : (parseFloat(res.outOfTownCharge || res.out_of_town_charge) || 0);
  if (_det && _det.otc !== undefined) {
    otc = _det.otc;
  } else if (!isMalabon && otc <= 0 && rawAmt > 0) {
    otc = Math.round(rawAmt * 0.05);
  }
  
  const svcp = parseFloat(res.service_charge_pct || res.serviceChargePct || (_det ? _det.serviceChargePct : 0));
  const rawNoOtc = (otc > 0 && rawAmt >= otc) ? (rawAmt - otc) : rawAmt;
  const baseTotal = (_det && _det.basePrice > 0) ? _det.basePrice : ((res.basePrice || res.base_price) ? parseFloat(res.basePrice || res.base_price) : (svcp > 0 ? Math.round(rawNoOtc / (1 + svcp / 100)) : rawNoOtc));
  const extraItemsAmt = _det ? (_det.extraItemsTotal || 0) : (parseFloat(res.additional_items_charge || res.additionalItemsCharge || 0) || 0);
  const svcAmt = _det ? _det.serviceChargeAmt : (svcp > 0 ? Math.round((baseTotal + extraItemsAmt) * (svcp / 100)) : 0);
  const dpAmt = Math.round(baseTotal * 0.5);
  const finalBaseHalf = baseTotal - dpAmt;
  const finalAmt = finalBaseHalf + extraItemsAmt + otc + svcAmt;

  const amtStr = finalAmt > 0 ? '\u20b1' + finalAmt.toLocaleString() : '\u2014';

  // Format Execution Strategy
  let strategyHtml = '';
  const staffText = execStrategyData && execStrategyData.staff_assigned && execStrategyData.staff_assigned.length > 0 
    ? execStrategyData.staff_assigned.join(', ') 
    : 'No staff assigned';
  const flexText = execStrategyData && execStrategyData.flexibility === 'strict' 
    ? 'Strict Schedule (No Extension)' 
    : (execStrategyData && execStrategyData.flexibility === 'flexible' ? 'Flexible (Extension Allowed)' : (execStrategyData && execStrategyData.flexibility || 'Not specified'));

  // phases from execution_plans is an ARRAY: [{id:'departure', start:'05:08', end:'08:08'}, ...]
  const phasesArr = Array.isArray(execStrategyData && execStrategyData.phases)
    ? execStrategyData.phases
    : [];

  const fmt12exec = (hhmm) => {
    return formatTime12h(hhmm) || '--:--';
  };

  const renderPhase = (label, key, color) => {
    const p = phasesArr.find(ph => ph.id === key);
    const startTime = p && p.start ? fmt12exec(p.start) : '--:--';
    const endTime   = p && p.end   ? fmt12exec(p.end)   : '--:--';
    return `<div style="flex:1; border:1px solid ${color}; background:rgba(0,0,0,0.2); border-radius:8px; padding:10px; text-align:center;">
      <div style="font-size:10px; font-weight:700; color:${color}; text-transform:uppercase; margin-bottom:4px;">${label}</div>
      <div style="font-size:11px; color:var(--cream);">${startTime} - ${endTime}</div>
    </div>`;
  };

  const _stratDoneNow = isExecStrategyDone(res, execStrategyData);
  strategyHtml = `
    <div style="margin-top:16px; border-top:1px solid var(--border); padding-top:16px; border-radius:10px; ${!_stratDoneNow ? 'box-shadow:0 0 0 2px rgba(239,68,68,0.6), 0 0 18px rgba(239,68,68,0.25); padding:14px; border:1.5px solid rgba(239,68,68,0.7);' : ''}">
      ${!_stratDoneNow ? '<div style="font-size:11px;color:var(--red);font-weight:700;margin-bottom:8px;">Execution Day Strategy is not configured. Set up phases in Reservation Details to unlock Start Execution Day.</div>' : ''}
      <div onclick="const content = this.nextElementSibling; const icon = this.querySelector('i'); if(content.style.display==='none'){content.style.display='block'; icon.style.transform='rotate(180deg)';}else{content.style.display='none'; icon.style.transform='rotate(0deg)';}" style="display:flex; justify-content:space-between; align-items:center; cursor:pointer; user-select:none;">
        <div style="font-size:11px; font-weight:700; color:${!_stratDoneNow ? 'var(--red)' : 'var(--text-dim)'}; text-transform:uppercase; letter-spacing:1px;">Execution Day Strategy</div>
        <i class="fas fa-chevron-down" style="color:var(--text-dim); transition:transform 0.2s; font-size:12px;"></i>
      </div>
      <div style="display:none; margin-top:12px;">
        <div style="display:grid; grid-template-columns:1fr 1fr; gap:12px; margin-bottom:16px;">
          <div>
            <div style="font-size:10px; color:var(--text-dim); text-transform:uppercase; letter-spacing:0.8px; margin-bottom:3px;">Assigned Staff</div>
            <div style="font-size:12px; color:var(--cream); line-height:1.4;">${escHtml(staffText)}</div>
          </div>
          <div>
            <div style="font-size:10px; color:var(--text-dim); text-transform:uppercase; letter-spacing:0.8px; margin-bottom:3px;">Event Flexibility</div>
            <div style="font-size:12px; color:var(--cream); line-height:1.4;">${escHtml(flexText)}</div>
          </div>
        </div>
        <div style="font-size:10px; color:var(--text-dim); text-transform:uppercase; letter-spacing:0.8px; margin-bottom:8px;">Timeline Periods</div>
        <div class="exec-timeline-grid" style="display:flex; gap:8px; flex-wrap:wrap;">
          ${renderPhase('Departure', 'departure', 'var(--gold)')}
          ${renderPhase('Deployment', 'deployment', 'var(--blue)')}
          ${renderPhase('Execution', 'execution', 'var(--green)')}
          ${renderPhase('Bash-Out', 'bashout', 'var(--red)')}
          ${renderPhase('Restorage', 'restorage', 'var(--purple)')}
        </div>
      </div>
    </div>
  `;


  // Resource preparation sorted status boxes
  const allSorted = EXEC_PROC_CATS.every(c => execDayProcSorted[c.key]);
  const sortedBoxesHtml = `
    <div class="exec-res-prep-box" style="background:var(--bg3);border:1px solid var(--border);border-radius:12px;padding:16px 20px;margin-bottom:16px;">
      <div style="font-size:11px;font-weight:700;color:var(--text-dim);text-transform:uppercase;letter-spacing:1px;margin-bottom:12px;">Resource Preparation</div>
      <div class="exec-res-prep-grid" style="display:grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); gap:12px;">
        ${EXEC_PROC_CATS.map(c => {
          const isSorted = execDayProcSorted[c.key] || false;
          return `<div style="display:flex;flex-direction:column;align-items:center;justify-content:center;padding:12px 10px;border-radius:10px;background:var(--bg2);border:1px solid ${isSorted ? 'rgba(39,174,96,0.6)' : 'rgba(192,57,43,0.6)'};box-shadow:0 0 10px ${isSorted ? 'rgba(39,174,96,0.3)' : 'rgba(192,57,43,0.3)'};text-align:center;transition:all 0.2s;">
            <span style="font-size:12px;font-weight:600;color:var(--cream);margin-bottom:6px;line-height:1.2;">${c.label}</span>
            <span style="font-size:10px;font-weight:800;text-transform:uppercase;color:${isSorted ? 'var(--green)' : 'var(--red)'};">${isSorted ? 'SORTED' : 'NOT SORTED'}</span>
          </div>`;
        }).join('')}
      </div>
      ${!allSorted ? '<div style="font-size:11px;color:var(--text-dim);margin-top:10px;">Mark all categories as sorted in Resource Preparation to enable Start Execution Day.</div>' : ''}
    </div>`;

  container.innerHTML = `
    <div style="padding:4px 0;">
      ${countdownHtml}

      <!-- Event summary card -->
      <div class="exec-event-summary-card" style="background:var(--bg3);border:1px solid var(--border);border-radius:12px;padding:20px;margin-bottom:16px;">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;">
          <div style="font-size:11px;font-weight:700;color:var(--text-dim);text-transform:uppercase;letter-spacing:1px;">Event Details</div>
          <span class="badge ${statusInfo.cls}">${statusInfo.label}</span>
        </div>
        <div class="exec-event-details-grid" style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
          <div>
            <div style="font-size:10px;color:var(--text-dim);text-transform:uppercase;letter-spacing:0.8px;margin-bottom:3px;">Client</div>
            <div style="font-size:13px;font-weight:600;color:var(--cream);">${escHtml(res.client || '\u2014')}</div>
          </div>
          <div>
            <div style="font-size:10px;color:var(--text-dim);text-transform:uppercase;letter-spacing:0.8px;margin-bottom:3px;">Event Type</div>
            <div style="font-size:13px;font-weight:600;color:var(--cream);">${escHtml(res.type || '\u2014')}</div>
          </div>
          <div>
            <div style="font-size:10px;color:var(--text-dim);text-transform:uppercase;letter-spacing:0.8px;margin-bottom:3px;">Execution Date</div>
            <div style="font-size:12px;font-weight:600;color:var(--gold);">${formattedDate}</div>
          </div>
          <div>
            <div style="font-size:10px;color:var(--text-dim);text-transform:uppercase;letter-spacing:0.8px;margin-bottom:3px;">Time</div>
            <div style="font-size:12px;font-weight:600;color:var(--cream);">${escHtml(formatTime12h(res.time) || '\u2014')}</div>
          </div>
          <div>
            <div style="font-size:10px;color:var(--text-dim);text-transform:uppercase;letter-spacing:0.8px;margin-bottom:3px;">Package</div>
            <div style="font-size:12px;color:var(--cream);">${escHtml(res.packageName || res.package || '\u2014')}</div>
          </div>
          <div>
            <div style="font-size:10px;color:var(--text-dim);text-transform:uppercase;letter-spacing:0.8px;margin-bottom:3px;">Theme</div>
            <div style="font-size:12px;color:var(--cream);">${escHtml(res.theme || '\u2014')}</div>
          </div>
          <div>
            <div style="font-size:10px;color:var(--text-dim);text-transform:uppercase;letter-spacing:0.8px;margin-bottom:3px;">Call Time</div>
            <div style="font-size:12px;color:var(--cream);">${(function(t) {
              if (!t || !t.includes(':')) return escHtml(t || '\u2014');
              const [hStr, mStr] = t.split(':');
              let h = parseInt(hStr, 10);
              const ampm = h >= 12 ? 'PM' : 'AM';
              h = h % 12 || 12;
              return escHtml(`${h.toString().padStart(2, '0')}:${mStr.substring(0,2)} ${ampm}`);
            })(res.callTime)}</div>
          </div>
          <div>
            <div style="font-size:10px;color:var(--text-dim);text-transform:uppercase;letter-spacing:0.8px;margin-bottom:3px;">Guest Count (Pax)</div>
            <div style="font-size:12px;color:var(--cream);">${escHtml(res.pax || res.guestCount || '\u2014')}</div>
          </div>
          <div>
            <div style="font-size:10px;color:var(--text-dim);text-transform:uppercase;letter-spacing:0.8px;margin-bottom:3px;">VIP Count</div>
            <div style="font-size:12px;color:var(--cream);">${escHtml(res.vipCount || '0 VIP')}</div>
          </div>
        </div>
        ${res.venue ? `<div style="margin-top:12px;padding-top:12px;border-top:1px solid var(--border);">
          <div style="font-size:10px;color:var(--text-dim);text-transform:uppercase;letter-spacing:0.8px;margin-bottom:3px;">Venue</div>
          <div style="font-size:12px;color:var(--cream);">${escHtml(res.venue)}</div>
        </div>` : ''}
        ${res.eventSetup ? `<div style="margin-top:8px;padding-top:8px;border-top:1px solid var(--border);display:flex;align-items:center;gap:8px;">
          <div style="font-size:10px;color:var(--text-dim);text-transform:uppercase;letter-spacing:0.8px;">Event Setup:</div>
          <div style="font-size:12px;font-weight:700;color:var(--gold);">${escHtml(res.eventSetup)}</div>
        </div>` : ''}
        ${strategyHtml}
      </div>

      ${sortedBoxesHtml}

      <!-- Start Execution Day button — locked until all resource prep sorted AND strategy done -->
      ${(() => {
        const stratDone = isExecStrategyDone(res, execStrategyData);
        const canStart = allSorted && stratDone;
        const stratNotDoneMsg = !stratDone ? '<div style="font-size:11px;color:var(--red);text-align:center;margin-bottom:8px;font-weight:600;">Execution Day Strategy must be configured before starting. Go to Reservation Details to set up phases.</div>' : '';
        return `${stratNotDoneMsg}<button class="exec-start-day-btn" onclick="startExecDay('${res.id}')"
          ${canStart ? '' : 'disabled'}
          style="width:100%;padding:14px 20px;background:linear-gradient(135deg,#22c55e,#16a34a);color:#fff;font-weight:700;font-size:14px;border:none;border-radius:10px;display:flex;align-items:center;justify-content:center;gap:10px;transition:opacity 0.15s;letter-spacing:0.3px;margin-bottom:10px;box-shadow:0 4px 20px rgba(34,197,94,0.25);${canStart ? 'cursor:pointer;' : 'cursor:not-allowed;opacity:0.45;'}"
          ${canStart ? 'onmouseover="this.style.opacity=\'0.88\'" onmouseout="this.style.opacity=\'1\'"' : ''}>
          Start Execution Day
        </button>`;
      })()}

      <!-- CTA button to logistics timeline -->
      <button id="exec-view-logistics-btn" class="exec-logistics-btn" onclick="goToExecLogisticsTimeline('${res.id}')"
        style="width:100%;padding:14px 20px;background:linear-gradient(135deg,var(--gold),#c9983a);color:#000;font-weight:700;font-size:13px;border:none;border-radius:10px;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:10px;transition:opacity 0.15s;letter-spacing:0.3px;margin-bottom:10px;"
        onmouseover="this.style.opacity='0.88'" onmouseout="this.style.opacity='1'">
        View Logistics &amp; Timeline
      </button>
      <div id="exec-view-logistics-sub" style="font-size:11px;color:var(--text-dim);text-align:center;margin-bottom:10px;">Opens this reservation\u2019s timeline in Reservation Details Handling</div>

      <!-- Final Rundown print button -->
      ${res.finalRundown
        ? `<button class="exec-rundown-btn" onclick="printFinalRundown('${res.id}')"
            style="width:100%;padding:12px 20px;background:var(--gold, #c49a3c);color:#ffffff !important;font-weight:700;font-size:13px;border:none;border-radius:10px;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:10px;transition:opacity 0.15s;letter-spacing:0.3px;">
            Print Final Rundown
          </button>`
        : `<button class="exec-rundown-btn" disabled title="Complete the Final Program Rundown meeting to enable this."
            style="width:100%;padding:12px 20px;background:#4b5563;color:#ffffff !important;font-weight:700;font-size:13px;border:none;border-radius:10px;cursor:not-allowed;display:flex;align-items:center;justify-content:center;gap:10px;letter-spacing:0.3px;opacity:0.5;">
            Print Final Rundown
          </button>
          <div style="font-size:11px;color:var(--text-dim);text-align:center;margin-top:6px;">Available once Final Program Rundown meeting is completed</div>`
      }

      <!-- Conditional Export Guest List & Venue Layout Buttons -->
      ${(() => {
        const extra = typeof getActiveReservationExtra === 'function' ? getActiveReservationExtra(res.id) : null;
        const hasGuestList = (extra && extra.guests && extra.guests.some(g => (typeof g === 'string' ? g.trim().length > 0 : (g.name || '').trim().length > 0))) ||
          (res.guestList && (Array.isArray(res.guestList) ? res.guestList.some(g => (typeof g === 'string' ? g.trim().length > 0 : (g.name || '').trim().length > 0)) : !!res.guestList)) ||
          (res.guest_list && (Array.isArray(res.guest_list) ? res.guest_list.some(g => (typeof g === 'string' ? g.trim().length > 0 : (g.name || '').trim().length > 0)) : !!res.guest_list));
        const hasVenueLayout = (extra && extra.seatingElements && extra.seatingElements.length > 0) ||
          (res.seatingLayout && (Array.isArray(res.seatingLayout) ? res.seatingLayout.length > 0 : !!res.seatingLayout)) ||
          (res.seating_elements && (Array.isArray(res.seating_elements) ? res.seating_elements.length > 0 : !!res.seating_elements));

        let btns = '';
        if (hasGuestList) {
          btns += `<button class="exec-export-guest-btn" onclick="exportGuestListPDF('${res.id}')"
            style="width:100%;padding:12px 20px;background:var(--gold, #c49a3c);color:#ffffff !important;font-weight:700;font-size:13px;border:none;border-radius:10px;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:10px;transition:all 0.15s;letter-spacing:0.3px;margin-top:10px;">
            Export Guest List
          </button>`;
        }
        if (hasVenueLayout) {
          btns += `<button class="exec-export-layout-btn" onclick="exportVenueLayoutPDF('${res.id}')"
            style="width:100%;padding:12px 20px;background:var(--gold, #c49a3c);color:#ffffff !important;font-weight:700;font-size:13px;border:none;border-radius:10px;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:10px;transition:all 0.15s;letter-spacing:0.3px;margin-top:10px;">
            Export Venue Layout
          </button>`;
        }
        return btns;
      })()}
    </div>`;
}

function goToExecLogisticsTimeline(resId) {
  // Set the active reservation in the details module
  activeResDetailId = resId;
  resDetailMode = 'view';
  resDetailsActiveTab = 'timeline';

  // Navigate to the reservation details section
  const navBtn = document.getElementById('nav-res-details');
  showSection('res-details', navBtn);
}
window.goToExecLogisticsTimeline = goToExecLogisticsTimeline;

// Settlement Logic
function addAdhocCharge() {
  if (!activeExecutionResId) return alert('Select an event first.');

  const name = document.getElementById('settle-item-name').value;
  const qty = parseInt(document.getElementById('settle-item-qty').value) || 1;
  const price = parseFloat(document.getElementById('settle-item-price').value) || 0;

  if (!name || price <= 0) return alert('Please enter a valid item name and unit price.');

  adhocCharges.push({ name, qty, price, total: qty * price });

  // Clear inputs
  document.getElementById('settle-item-name').value = '';
  document.getElementById('settle-item-qty').value = '1';
  document.getElementById('settle-item-price').value = '';

  renderSettlementPanel();
}

function renderSettlementPanel() {
  const tbody = document.getElementById('settle-charges-list');

  if (adhocCharges.length === 0) {
    tbody.innerHTML = '<tr><td colspan="5" style="text-align:center; padding:12px; color:var(--text-dim);">No ad-hoc charges added yet.</td></tr>';
  } else {
    tbody.innerHTML = adhocCharges.map((charge, idx) => `
      <tr>
        <td>${charge.name}</td>
        <td>${charge.qty}</td>
        <td>₱${charge.price.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
        <td style="text-align:right;">₱${charge.total.toLocaleString(undefined, { minimumFractionDigits: 2 })}</td>
        <td style="text-align:center;"><button style="background:#dc2626; border:none; color:#ffffff; font-weight:700; border-radius:4px; padding:2px 8px; cursor:pointer;" onclick="removeAdhocCharge(${idx})">✖</button></td>
      </tr>
    `).join('');
  }

  // Calculate Grand Total
  const res = RESERVATIONS.find(r => r.id === activeExecutionResId);
  const rawAmt = res ? (typeof res.amount === 'string' ? parseFloat(res.amount.replace(/[^0-9.]/g, '')) || 0 : (res.amount || 0)) : 0;
  const adhocTotal = adhocCharges.reduce((sum, c) => sum + c.total, 0);
  const grandTotal = rawAmt + adhocTotal;

  document.getElementById('settle-final-total').textContent = `₱${grandTotal.toLocaleString(undefined, { minimumFractionDigits: 2 })}`;
}

function removeAdhocCharge(index) {
  adhocCharges.splice(index, 1);
  renderSettlementPanel();
}

async function markEventSettled() {
  if (!activeExecutionResId) return;
  try {
    const { doc, updateDoc } = window.firebaseFns;
    const grandTotalStr = document.getElementById('settle-final-total').textContent;

    await updateDoc(doc(window.firebaseDB, 'reservations', activeExecutionResId), {
      status: 'completed',
      adhocCharges: adhocCharges,
      finalSettledAmount: grandTotalStr
    });

    // Update local state
    const res = RESERVATIONS.find(r => r.id === activeExecutionResId);
    if (res) {
      res.status = 'completed';
      res.adhocCharges = adhocCharges;
    }

    alert('Event successfully settled and marked as completed!');
    activeExecutionResId = null;
    document.getElementById('execution-empty-state').style.display = 'block';
    document.getElementById('execution-active-content').style.display = 'none';
    renderExecutionDayReservations();
  } catch (e) {
    console.error(e);
    alert('Error settling event.');
  }
}

function generateFinalInvoice() {
  if (!activeExecutionResId) return;
  alert('Simulating PDF Generation...\\n\\nInvoice generated and saved to records.');
}
window.selectExecutionEvent = selectExecutionEvent;
window.closePosAndCancel = function () {
  document.getElementById('admin-pos-modal').style.display = 'none';
  window.cancelInitialFeePayment();
};

window.calcGcashConfirmChange = function () {
  const amountDue = 5000;
  const input = document.getElementById('gcash-confirm-amount');
  const changeEl = document.getElementById('gcash-confirm-change');
  const errorEl = document.getElementById('gcash-confirm-error');
  const confirmBtn = document.getElementById('btn-confirm-gcash-payment');
  if (!input) return;
  const received = parseFloat(input.value);
  if (isNaN(received) || received < amountDue) {
    if (changeEl) changeEl.innerHTML = '&#8369;0.00';
    if (errorEl) errorEl.style.display = 'block';
    if (confirmBtn) { confirmBtn.disabled = true; confirmBtn.style.opacity = '0.5'; confirmBtn.style.cursor = 'not-allowed'; }
  } else {
    const change = received - amountDue;
    if (changeEl) changeEl.innerHTML = '&#8369;' + change.toLocaleString('en-US', { minimumFractionDigits: 2 });
    if (errorEl) errorEl.style.display = 'none';
    if (confirmBtn) { confirmBtn.disabled = false; confirmBtn.style.opacity = '1'; confirmBtn.style.cursor = 'pointer'; }
  }
};

window.confirmGcashPayment = async function () {
  if (!activeMeeting || !window.supabaseClient) return;
  const btn = document.getElementById('btn-confirm-gcash-payment') || event.target.closest('button');
  if (btn) { btn.disabled = true; btn.innerHTML = 'Confirming...'; }
  try {
    const sb = window.supabaseClient;
    const now = new Date().toISOString();
    // Read admin-entered amount
    const amountInput = document.getElementById('gcash-confirm-amount');
    const cashReceived = amountInput ? parseFloat(amountInput.value) : 5000;
    const changeGiven = (cashReceived || 5000) - 5000;
    const loggedStr = sessionStorage.getItem('halden_admin');
    let adminName = 'Admin';
    if (loggedStr) { try { const p = JSON.parse(loggedStr); if (p.name) adminName = p.name; } catch (e) { } }

    const targetResId = activeMeeting.reservation_id || activeMeeting.reservationId || (activeMeetingResCache && activeMeetingResCache.id) || currentMeetingResId;
    const refId = activeMeeting.initial_fee_ref_id || activeMeeting.initialFeeRefId || ('PAY-INIT-' + String(targetResId || '000000').slice(-6).toUpperCase());

    const proofUrl = activeMeeting.initial_fee_received_by; // Grab the screenshot URL customer uploaded

    const gcashMeetingPayload = {
      initial_fee_status: 'paid',
      initial_fee_method: 'gcash',
      initial_fee_paid_at: now,
      initial_fee_received: cashReceived || 5000,
      initial_fee_change: changeGiven
    };

    if (activeMeeting.id) {
      try { await sb.from('meetings').update(gcashMeetingPayload).eq('id', activeMeeting.id); } catch (e) {}
    }
    const mtRoomCode = activeMeeting.meetingRoomId || activeMeeting.room_id || activeMeeting.roomId;
    if (mtRoomCode) {
      try { await sb.from('meetings').update(gcashMeetingPayload).or(`meetingRoomId.eq.${mtRoomCode},room_id.eq.${mtRoomCode}`); } catch (e) {}
    }
    if (targetResId) {
      try { await sb.from('meetings').update(gcashMeetingPayload).eq('reservation_id', targetResId); } catch (e) {}
    }

    if (window.firebaseDB && window.firebaseFns && activeMeeting.id) {
      try {
        const { doc, updateDoc } = window.firebaseFns;
        updateDoc(doc(window.firebaseDB, 'meetings', activeMeeting.id), gcashMeetingPayload).catch(() => {});
      } catch (fe) {}
    }

    // Flip button to confirmed state immediately (don't leave it spinning)
    if (btn) { btn.disabled = true; btn.innerHTML = 'Confirmed'; btn.style.background = 'rgba(46,160,67,0.2)'; btn.style.color = '#2ea043'; btn.style.border = '1px solid #2ea043'; }

    // Update activeMeeting locally so UI reflects paid state immediately
    activeMeeting.initial_fee_status = 'paid';
    activeMeeting.initial_fee_method = 'gcash';
    activeMeeting.initial_fee_paid_at = now;
    activeMeeting.initial_fee_received = cashReceived || 5000;
    activeMeeting.initial_fee_change = changeGiven;
    activeMeeting.initial_fee_ref_id = refId;
    activeMeeting.initialFeeRefId = refId;

    // Also update reservation and dedicated reservation_payments table
    if (targetResId) {
      if (activeMeetingResCache) {
        activeMeetingResCache.initial_fee_status = 'paid';
        activeMeetingResCache.initialFeeStatus = 'paid';
        activeMeetingResCache.initial_fee_method = 'gcash';
        activeMeetingResCache.initialFeeMethod = 'gcash';
        activeMeetingResCache.initial_fee_ref_id = refId;
        activeMeetingResCache.initialFeeRefId = refId;
        activeMeetingResCache.initial_fee_received = cashReceived || 5000;
        activeMeetingResCache.initial_fee_change = changeGiven;
        activeMeetingResCache.initial_fee_paid_at = now;
      }
      try {
        await sb.from('reservations').update({
          initial_fee_status: 'paid',
          initial_fee_paid: true,
          initial_fee_received: cashReceived || 5000
        }).eq('id', targetResId);
      } catch (err) {
        console.warn('Failed to update reservations table for initial fee:', err);
      }
      if (window.firebaseDB && window.firebaseFns) {
        try {
          const { doc, updateDoc } = window.firebaseFns;
          await updateDoc(doc(window.firebaseDB, 'reservations', targetResId), {
            initial_fee_status: 'paid',
            initialFeeStatus: 'paid',
            initial_fee_method: 'gcash',
            initialFeeMethod: 'gcash',
            initial_fee_ref_id: refId,
            initialFeeRefId: refId,
            initial_fee_paid_at: now,
            initial_fee_received: cashReceived || 5000,
            initial_fee_change: changeGiven
          });
        } catch (fe) {}
      }
      try {
        // Upsert into dedicated payments table
        await sb.from('reservation_payments').upsert({
          reservation_id: targetResId,
          initial_fee_amount: 5000,
          initial_fee_status: 'paid',
          initial_fee_method: 'gcash',
          initial_fee_paid_at: now,
          initial_fee_received: cashReceived || 5000,
          initial_fee_change: changeGiven,
          initial_fee_received_by: proofUrl, // Sync proof URL
          initial_fee_proof: proofUrl,
          initial_fee_proof_url: proofUrl,
          updated_at: now
        }, { onConflict: 'reservation_id' });
      } catch (err) {
        console.warn('Failed to sync payments table:', err);
      }
    }

    if (typeof updateBillingUI === 'function') {
      updateBillingUI(activeMeetingResCache);
    }

    // Trigger Automated Email Receipt for GCash Initial Fee
    try {
      if (window.SmartServeNotifications && targetResId) {
        const targetRes = activeMeetingResCache || (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS.find(r => String(r.id) === String(targetResId)) : null) || {};
        const custName = targetRes.customerName || targetRes.name || targetRes.client_name || activeMeeting.customerName || activeMeeting.customer_name || 'Valued Customer';
        const custEmail = targetRes.customerEmail || targetRes.email || targetRes.client_email || activeMeeting.customerEmail || activeMeeting.customer_email || '';
        window.SmartServeNotifications.notifyPaymentMade({
          customerEmail: custEmail,
          customerName: custName,
          reservationId: targetResId,
          amount: 5000,
          paymentMethod: 'GCash',
          feeType: 'Initial Fee',
          referenceNumber: refId,
          referenceId: refId,
          refId: refId,
          cashReceived: cashReceived || 5000,
          changeGiven: changeGiven,
          transactionDate: now,
          notes: `Amount Due: ₱5,000.00, GCash Received: ₱${Number(cashReceived || 5000).toLocaleString()}, Change: ₱${Number(changeGiven).toLocaleString()}, Verified By: ${adminName}`
        });
      }
    } catch (notifErr) {
      console.warn('[confirmGcashPayment] Notification error:', notifErr);
    }

    const toast = document.createElement('div');
    toast.style.cssText = 'position:fixed;bottom:24px;right:24px;background:#2ea043;color:#fff;padding:14px 20px;border-radius:10px;font-size:13px;font-weight:600;z-index:9999;box-shadow:0 4px 20px rgba(0,0,0,0.3);';
    toast.textContent = '\u2713 GCash payment confirmed and marked as paid. Ref: ' + refId;
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 4000);
  } catch (e) {
    alert('Failed to confirm payment: ' + e.message);
    if (btn) { btn.disabled = false; btn.innerHTML = 'Confirm Payment'; }
  }
};

// Resets every element inside the GCash proof panel to a blank/disabled state.
// Called on dismiss and as a safety guard on every fresh proof upload.
function _resetGcashProofPanel() {
  const proofPanel = document.getElementById('mt-gcash-proof-panel');
  const proofImg   = document.getElementById('mt-gcash-proof-img');
  const proofLink  = document.getElementById('mt-gcash-proof-link');
  const amountInput = document.getElementById('gcash-confirm-amount');
  const changeEl   = document.getElementById('gcash-confirm-change');
  const errorEl    = document.getElementById('gcash-confirm-error');
  const confirmBtn = document.getElementById('btn-confirm-gcash-payment');
  const dismissBtn = document.getElementById('btn-dismiss-gcash-payment');
  if (proofPanel)  proofPanel.style.display = 'none';
  if (proofImg)    proofImg.src = '';
  if (proofLink)   proofLink.href = '#';
  if (amountInput) amountInput.value = '';
  if (changeEl)    changeEl.innerHTML = '&#8369;0.00';
  if (errorEl)     errorEl.style.display = 'none';
  if (confirmBtn) {
    confirmBtn.disabled = true;
    confirmBtn.innerHTML = 'Confirm Payment';
    confirmBtn.style.background = 'var(--green,#2ea043)';
    confirmBtn.style.color = '#fff';
    confirmBtn.style.border = 'none';
    confirmBtn.style.opacity = '0.5';
    confirmBtn.style.cursor = 'not-allowed';
  }
  // Always restore the Dismiss button too : covers the race where the customer
  // re-uploads while the dismiss DB call is still in-flight
  if (dismissBtn) {
    dismissBtn.disabled = false;
    dismissBtn.innerHTML = 'Dismiss';
    dismissBtn.style.opacity = '1';
    dismissBtn.style.cursor = 'pointer';
  }
}

window.dismissGcashProof = async function () {
  if (!activeMeeting || !window.supabaseClient) return;
  const btn = event.target.closest('button');
  if (btn) { btn.disabled = true; btn.innerHTML = 'Dismissing...'; }
  try {
    const sb = window.supabaseClient;
    const resId = activeMeeting.reservationId || activeMeeting.reservation_id;
    const meetingUpd = {
      initial_fee_status: 'gcash_dismissed',
      initial_fee_received_by: null
    };

    // Clean payment documents from meetings shared_documents if present
    try {
      const { data: mtRow } = await sb.from('meetings').select('shared_documents').eq('id', activeMeeting.id).maybeSingle();
      if (mtRow && Array.isArray(mtRow.shared_documents)) {
        meetingUpd.shared_documents = mtRow.shared_documents.filter(d => {
          if (!d) return false;
          if (d.agenda === 'payment') return false;
          if (typeof d.name === 'string' && d.name.toLowerCase().includes('payment proof')) return false;
          return true;
        });
      }
    } catch (docErr) { /* ignore */ }

    const { error } = await sb.from('meetings').update(meetingUpd).eq('id', activeMeeting.id);
    if (error) throw error;

    if (resId) {
      const resUpd = {
        initial_fee_status: 'declined_24h',
        initial_fee_proof: null,
        initial_fee_proof_url: null
      };
      await sb.from('reservations').update(resUpd).eq('id', resId);
      try {
        await sb.from('reservation_payments').update({
          initial_fee_status: 'declined_24h',
          initial_fee_proof: null,
          initial_fee_proof_url: null,
          initial_fee_received_by: null
        }).eq('reservation_id', resId);
      } catch (rpErr) { /* ignore */ }

      if (window.firebaseDB && window.firebaseFns) {
        try {
          const { doc, updateDoc } = window.firebaseFns;
          const fbResUpd = {
            ...resUpd,
            initialFeeStatus: 'declined_24h',
            initialFeeProof: null,
            initial_fee_received_by: null,
            payment_approval_status: null
          };
          await updateDoc(doc(window.firebaseDB, 'reservations', resId), fbResUpd);
          await updateDoc(doc(window.firebaseDB, 'meetings', activeMeeting.id), meetingUpd);
        } catch (fsErr) { /* ignore */ }
      }
      const targetRes = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(r => r.id === resId);
      if (targetRes) Object.assign(targetRes, resUpd);
    }

    // Sync local state immediately so updateBillingUI reads the right status
    Object.assign(activeMeeting, meetingUpd);
    // Full panel reset : clears screenshot, amount, change, error, and both buttons
    _resetGcashProofPanel();
    // Re-render billing section → shows "Waiting for GCash Proof..." state
    if (typeof updateBillingUI === 'function') updateBillingUI(activeMeetingResCache);
  } catch (e) {
    alert('Failed to dismiss: ' + e.message);
    if (btn) { btn.disabled = false; btn.innerHTML = 'Dismiss'; }
  }
};

