window.triggerMeetingMode = async function () {
  if (typeof activeDetailsMtId === 'undefined' || !activeDetailsMtId) return;
  const mtId = activeDetailsMtId;

  // Signal live meeting for customer sync
  if (window.supabaseClient && mtId && mtId !== 'demo') {
    try {
      await window.supabaseClient.from('meetings').update({ status: 'live' }).eq('id', mtId);
    } catch (e) {
      console.warn('Supabase live trigger notice:', e);
    }
  }
  if (window.firebaseFns && window.firebaseFns.doc && window.firebaseFns.updateDoc && window.firebaseDB) {
    try {
      const { doc, updateDoc } = window.firebaseFns;
      await updateDoc(doc(window.firebaseDB, 'meetings', mtId), { status: 'live' });
    } catch (e) { console.error("Sync Error:", e); }
  }

  closeMtDetailsModal();
  initiateMeetingMode(mtId);
};

window.markPaymentConfirmed = async function () {
  if (!activeMeetingResCache) return;
  const btn = event.target;
  btn.disabled = true;
  try {
    const { doc, updateDoc } = window.firebaseFns;
    await updateDoc(doc(window.firebaseDB, 'reservations', activeMeetingResCache.id), {
      paymentStatus: 'paid',
      paymentRequested: false
    });
    alert('Payment confirmed for reservation.');
  } catch (e) { alert('Update failed'); }
  finally { btn.disabled = false; }
};

window.requestPaymongoPayment = async function () {
  if (!activeMeetingResCache || !activeMeeting) return;
  if (activeMeeting.id === 'demo') return alert('Payment flow is disabled in demo mode.');

  const btn = document.getElementById('btn-pay-initial');
  if (!btn) return;
  btn.disabled = true;
  btn.textContent = 'Sending...';

  try {
    const sb = window.supabaseClient;
    if (!sb) throw new Error('Supabase not ready');

    activeMeeting.initial_fee_status = 'triggered';
    activeMeeting.initialFeeStatus = 'triggered';
    if (activeMeetingResCache) {
      activeMeetingResCache.initial_fee_status = 'triggered';
      activeMeetingResCache.initialFeeStatus = 'triggered';
    }

    const effId = activeMeeting.id;
    const roomCode = activeMeeting.meetingRoomId || activeMeeting.room_id || activeMeeting.roomId;
    const resId = activeMeeting.reservationId || activeMeeting.reservation_id || (activeMeetingResCache && activeMeetingResCache.id);

    // 1. Update Supabase meetings table by id, meetingRoomId/room_id, and reservation_id
    if (effId) {
      try { await sb.from('meetings').update({ initial_fee_status: 'triggered' }).eq('id', effId); } catch (e) {}
    }
    if (roomCode) {
      try { await sb.from('meetings').update({ initial_fee_status: 'triggered' }).or(`meetingRoomId.eq.${roomCode},room_id.eq.${roomCode}`); } catch (e) {}
    }
    if (resId) {
      try { await sb.from('meetings').update({ initial_fee_status: 'triggered' }).eq('reservation_id', resId); } catch (e) {}
      try { await sb.from('reservations').update({ initial_fee_status: 'triggered' }).eq('id', resId); } catch (e) {}
      try { await sb.from('reservation_payments').update({ initial_fee_status: 'triggered' }).eq('reservation_id', resId); } catch (e) {}
    }

    // 2. Update Firebase
    if (window.firebaseFns && window.firebaseDB) {
      try {
        const { doc, updateDoc } = window.firebaseFns;
        if (effId) updateDoc(doc(window.firebaseDB, 'meetings', effId), { initial_fee_status: 'triggered', initialFeeStatus: 'triggered' }).catch(() => {});
        if (resId) updateDoc(doc(window.firebaseDB, 'reservations', resId), { initial_fee_status: 'triggered', initialFeeStatus: 'triggered' }).catch(() => {});
      } catch (fe) {
        console.warn('Firebase trigger sync warning:', fe);
      }
    }

    // Update button to reflect waiting state
    btn.textContent = 'Waiting for Customer...';
    btn.style.background = '#4b5563';
    btn.style.color = '#ffffff';
    btn.style.border = 'none';

    if (typeof startAdminPaymongoPoll === 'function') startAdminPaymongoPoll();

    const cancelBtn = document.getElementById('btn-cancel-pay-initial');
    if (cancelBtn) cancelBtn.style.display = 'flex';

    // Toast
    const toast = document.createElement('div');
    toast.style.cssText = 'position:fixed;bottom:24px;right:24px;background:var(--primary);color:#fff;padding:14px 20px;border-radius:10px;font-size:13px;font-weight:600;z-index:9999;box-shadow:0 4px 20px rgba(0,0,0,0.3);';
    toast.textContent = 'Payment panel sent to customer : awaiting their response.';
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 4000);

  } catch (e) {
    console.error('[requestPaymongoPayment]', e);
    alert('Failed to trigger payment panel: ' + e.message);
    btn.disabled = false;
    btn.textContent = 'Commence Initial Fee Payment';
  }
};

window.cancelInitialFeePayment = async function () {
  if (!activeMeeting) return;
  if (typeof stopAdminPaymongoPoll === 'function') stopAdminPaymongoPoll();
  const btn = document.getElementById('btn-cancel-pay-initial');
  if (btn) {
    btn.disabled = true;
    btn.textContent = 'Canceling...';
  }

  try {
    const sb = window.supabaseClient;
    if (!sb) throw new Error('Supabase not ready');

    const updateObj = {
      initial_fee_status: null,
      initial_fee_deadline: null,
      initial_fee_due_date: null
    };

    const meetingUpdateObj = {
      initial_fee_status: null,
      initial_fee_deadline: null
    };

    const effId = activeMeeting.id;
    const roomCode = activeMeeting.meetingRoomId || activeMeeting.room_id || activeMeeting.roomId;
    const resId = activeMeeting.reservationId || activeMeeting.reservation_id || (activeMeetingResCache && activeMeetingResCache.id);

    try {
      if (effId) await sb.from('meetings').update(meetingUpdateObj).eq('id', effId);
    } catch (sbMeetingErr) {}

    try {
      if (roomCode) await sb.from('meetings').update(meetingUpdateObj).or(`meetingRoomId.eq.${roomCode},room_id.eq.${roomCode}`);
    } catch (e) {}

    if (resId) {
      try { await sb.from('meetings').update(meetingUpdateObj).eq('reservation_id', resId); } catch (e) {}
      try { await sb.from('reservations').update(updateObj).eq('id', resId); } catch (e) {}
      try {
        await sb.from('reservation_payments').update({
          initial_fee_due_date: null,
          initial_fee_status: null
        }).eq('reservation_id', resId);
      } catch (e) {}
    }

    if (window.firebaseFns && window.firebaseDB) {
      try {
        const { doc, updateDoc } = window.firebaseFns;
        if (effId) await updateDoc(doc(window.firebaseDB, 'meetings', effId), updateObj);
        if (resId) {
          await updateDoc(doc(window.firebaseDB, 'reservations', resId), {
            initial_fee_status: null,
            initial_fee_deadline: null,
            initial_fee_due_date: null,
            initialFeeDueDate: null
          });
        }
      } catch (e) { }
    }

    // Update local state across meeting and reservation objects
    activeMeeting.initial_fee_status = null;
    activeMeeting.initial_fee_deadline = null;
    activeMeeting.initial_fee_due_date = null;

    if (activeMeetingResCache) {
      activeMeetingResCache.initial_fee_status = null;
      activeMeetingResCache.initial_fee_deadline = null;
      activeMeetingResCache.initial_fee_due_date = null;
      activeMeetingResCache.initialFeeDueDate = null;
    }

    const rMatch = (typeof RESERVATIONS !== 'undefined' && resId) ? RESERVATIONS.find(r => r.id === resId) : null;
    if (rMatch) {
      rMatch.initial_fee_status = null;
      rMatch.initial_fee_deadline = null;
      rMatch.initial_fee_due_date = null;
      rMatch.initialFeeDueDate = null;
    }

    // Reset schedule input and panel
    const initDueInput = document.getElementById('mt-initial-fee-due');
    if (initDueInput) initDueInput.value = '';
    const schedPanel = document.getElementById('mt-initial-fee-schedule-panel');
    if (schedPanel) schedPanel.style.display = 'none';

    // Hide cancel button
    if (btn) btn.style.display = 'none';

    if (window.updateBillingUI) window.updateBillingUI(activeMeetingResCache);

    // Toast
    const toast = document.createElement('div');
    toast.style.cssText = 'position:fixed;bottom:24px;right:24px;background:#e23636;color:#fff;padding:14px 20px;border-radius:10px;font-size:13px;font-weight:600;z-index:9999;box-shadow:0 4px 20px rgba(0,0,0,0.3);';
    toast.textContent = 'Payment request and scheduled due date cancelled.';
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 4000);

  } catch (e) {
    console.error('[cancelInitialFeePayment]', e);
    alert('Failed to cancel request: ' + e.message);
    if (btn) {
      btn.disabled = false;
      btn.textContent = 'Cancel Request';
    }
  }
};

