window.openPosModal = function () {
  document.getElementById('pos-cash-received').value = '';
  document.getElementById('pos-change-display').innerHTML = '&#8369;0.00';
  document.getElementById('pos-error-msg').style.display = 'none';
  document.getElementById('btn-pos-confirm').disabled = true;
  document.getElementById('admin-pos-modal').style.display = 'flex';
  document.getElementById('pos-cash-received').focus();
};

window.calculatePosChange = function () {
  const amountDue = 5000;
  const cashInput = document.getElementById('pos-cash-received');
  const changeDisplay = document.getElementById('pos-change-display');
  const errorMsg = document.getElementById('pos-error-msg');
  const confirmBtn = document.getElementById('btn-pos-confirm');

  if (cashInput && cashInput.value && cashInput.value.length > 6) {
    cashInput.value = cashInput.value.slice(0, 6);
  }

  const cashReceived = parseFloat(cashInput.value);

  if (isNaN(cashReceived) || cashReceived < amountDue) {
    changeDisplay.innerHTML = '&#8369;0.00';
    errorMsg.style.display = 'block';
    confirmBtn.disabled = true;
  } else {
    const change = cashReceived - amountDue;
    changeDisplay.innerHTML = '&#8369;' + change.toLocaleString('en-US', { minimumFractionDigits: 2 });
    errorMsg.style.display = 'none';
    confirmBtn.disabled = false;
  }
};

window.processPosPayment = async function () {
  if (!activeMeetingResCache || !activeMeeting) return;
  const btn = document.getElementById('btn-pos-confirm');
  btn.disabled = true;
  btn.textContent = 'Processing...';

  try {
    const sb = window.supabaseClient;
    if (!sb) throw new Error('Supabase not ready');

    const cashReceived = parseFloat(document.getElementById('pos-cash-received').value);
    if (isNaN(cashReceived) || cashReceived < 5000) throw new Error('Invalid cash amount');
    const changeGiven = cashReceived - 5000;

    const loggedStr = sessionStorage.getItem('halden_admin');
    let adminName = 'Admin';
    if (loggedStr) {
      const parsed = JSON.parse(loggedStr);
      if (parsed.name) adminName = parsed.name;
    }

    const now = new Date().toISOString();
    const targetResId = activeMeetingResCache?.id || activeMeeting?.reservation_id || activeMeeting?.reservationId || currentMeetingResId;
    const refId = activeMeeting.initial_fee_ref_id || activeMeeting.initialFeeRefId || ('PAY-INIT-' + String(targetResId || '000000').slice(-6).toUpperCase());

    const posMeetingPayload = {
      initial_fee_status: 'paid',
      initial_fee_method: 'cash',
      initial_fee_paid_at: now,
      initial_fee_received: cashReceived,
      initial_fee_change: changeGiven,
      initial_fee_received_by: adminName
    };

    if (activeMeeting.id) {
      try { await sb.from('meetings').update(posMeetingPayload).eq('id', activeMeeting.id); } catch (e) {}
    }
    const mtRoomCode = activeMeeting.meetingRoomId || activeMeeting.room_id || activeMeeting.roomId;
    if (mtRoomCode) {
      try { await sb.from('meetings').update(posMeetingPayload).or(`meetingRoomId.eq.${mtRoomCode},room_id.eq.${mtRoomCode}`); } catch (e) {}
    }
    if (targetResId) {
      try { await sb.from('meetings').update(posMeetingPayload).eq('reservation_id', targetResId); } catch (e) {}
    }

    if (window.firebaseDB && window.firebaseFns && activeMeeting.id) {
      try {
        const { doc, updateDoc } = window.firebaseFns;
        updateDoc(doc(window.firebaseDB, 'meetings', activeMeeting.id), posMeetingPayload).catch(() => {});
      } catch (fe) {}
    }

    // Update activeMeeting local state
    activeMeeting.initial_fee_status = 'paid';
    activeMeeting.initial_fee_method = 'cash';
    activeMeeting.initial_fee_paid_at = now;
    activeMeeting.initial_fee_received = cashReceived;
    activeMeeting.initial_fee_change = changeGiven;
    activeMeeting.initial_fee_received_by = adminName;
    activeMeeting.initial_fee_ref_id = refId;
    activeMeeting.initialFeeRefId = refId;

    if (activeMeetingResCache) {
      activeMeetingResCache.paymentStatus = 'paid';
      activeMeetingResCache.paymentAmount = '5000';
      activeMeetingResCache.initialFeeStatus = 'paid';
      activeMeetingResCache.initial_fee_status = 'paid';
      activeMeetingResCache.initialFeeMethod = 'cash';
      activeMeetingResCache.initial_fee_method = 'cash';
      activeMeetingResCache.initial_fee_received = cashReceived;
      activeMeetingResCache.initial_fee_change = changeGiven;
      activeMeetingResCache.initial_fee_paid_at = now;
      activeMeetingResCache.initial_fee_received_by = adminName;
      activeMeetingResCache.initial_fee_ref_id = refId;
      activeMeetingResCache.initialFeeRefId = refId;
    }

    if (window.firebaseDB && window.firebaseFns && activeMeetingResCache.id) {
      try {
        const { doc, updateDoc } = window.firebaseFns;
        await updateDoc(doc(window.firebaseDB, 'reservations', activeMeetingResCache.id), {
          paymentStatus: 'paid',
          paymentAmount: '5000',
          cashPaymentStatus: 'confirmed',
          initialFeeStatus: 'paid',
          initial_fee_status: 'paid',
          initialFeeMethod: 'cash',
          initial_fee_method: 'cash',
          initial_fee_received: cashReceived,
          initial_fee_change: changeGiven,
          initial_fee_paid_at: now,
          initial_fee_received_by: adminName,
          initial_fee_ref_id: refId,
          initialFeeRefId: refId
        });
      } catch (fe) {}
    }

    try {
      await sb.from('reservations').update({
        initial_fee_status: 'paid',
        initial_fee_paid: true,
        initial_fee_received: cashReceived
      }).eq('id', activeMeetingResCache.id);
    } catch (err) {
      console.warn('Failed to update reservations table:', err);
    }

    try {
      await sb.from('reservation_payments').upsert({
        reservation_id: activeMeetingResCache.id,
        initial_fee_amount: 5000,
        initial_fee_status: 'paid',
        initial_fee_method: 'cash',
        initial_fee_paid_at: now,
        initial_fee_received: cashReceived,
        initial_fee_change: changeGiven,
        initial_fee_received_by: adminName,
        updated_at: now
      }, { onConflict: 'reservation_id' });
    } catch (err) {
      console.warn('Failed to sync payments table:', err);
    }

    document.getElementById('admin-pos-modal').style.display = 'none';

    if (typeof updateBillingUI === 'function') {
      updateBillingUI(activeMeetingResCache);
    }

    // Trigger Automated Email Receipt for POS Initial Fee
    try {
      if (window.SmartServeNotifications && targetResId) {
        const targetRes = activeMeetingResCache || (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS.find(r => String(r.id) === String(targetResId)) : null) || {};
        const custName = targetRes.customerName || targetRes.name || targetRes.client_name || activeMeeting.customerName || activeMeeting.customer_name || 'Valued Customer';
        const custEmail = targetRes.customerEmail || targetRes.email || targetRes.client_email || activeMeeting.customerEmail || activeMeeting.customer_email || '';
        window.SmartServeNotifications.notifyPaymentMade({
          customerEmail: custEmail,
          customerName: custName,
          reservationId: targetResId,
          amount: 5000,
          paymentMethod: 'Cash',
          feeType: 'Initial Fee',
          referenceNumber: refId,
          referenceId: refId,
          refId: refId,
          cashReceived: cashReceived,
          changeGiven: changeGiven,
          transactionDate: now,
          notes: `Amount Due: ₱5,000.00, Cash Received: ₱${Number(cashReceived).toLocaleString()}, Change: ₱${Number(changeGiven).toLocaleString()}, Verified By: ${adminName}`
        });
      }
    } catch (notifErr) {
      console.warn('[processPosPayment] Notification error:', notifErr);
    }

    const toast = document.createElement('div');
    toast.style.cssText = 'position:fixed;bottom:24px;right:24px;background:#2e7d32;color:#fff;padding:14px 20px;border-radius:10px;font-size:13px;font-weight:600;z-index:9999;box-shadow:0 4px 20px rgba(0,0,0,0.3);';
    toast.textContent = 'POS Transaction Complete. Ref: ' + refId;
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 4000);

  } catch (e) {
    console.error('[processPosPayment]', e);
    alert('Failed to process payment: ' + e.message);
    btn.disabled = false;
    btn.textContent = 'Confirm Payment';
  }
};


window.declineInitialCashPayment = async function () {
  if (!activeMeetingResCache || !activeMeeting) return;
  const btn = event.target;
  btn.disabled = true;
  btn.textContent = 'Processing...';

  try {
    const sb = window.supabaseClient;
    if (!sb) throw new Error('Supabase not ready');

    // Set 24-hour deadline from now
    const deadline = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();

    const { error } = await sb.from('meetings').update({
      initial_fee_status: 'declined_24h',
      initial_fee_deadline: deadline
    }).eq('id', activeMeeting.id);

    if (error) throw error;

    // Automated rejection/deadline notice to customer
    const notifService = window.HalServeNotifications || window.SmartServeNotifications;
    if (notifService && typeof notifService.notifyPaymentRejected === 'function') {
      const custEmail = activeMeetingResCache.customerEmail || activeMeetingResCache.email || activeMeetingResCache.client_email;
      const custName = activeMeetingResCache.customerName || activeMeetingResCache.name || activeMeetingResCache.client_name || activeMeetingResCache.client || 'Valued Client';
      const syncedRefId = 'PAY-INIT-' + String(activeMeetingResCache.id || '000000').slice(-6).toUpperCase();
      if (custEmail) {
        notifService.notifyPaymentRejected({
          customerEmail: custEmail,
          customerName: custName,
          feeType: 'Initial Reservation Fee',
          referenceId: syncedRefId,
          reservationId: activeMeetingResCache.id,
          reason: 'Initial consultation cash collection was declined or uncollected. You have 24 hours to settle the initial fee online in your portal before automatic cancellation.'
        });
      }
    }

    const toast = document.createElement('div');
    toast.style.cssText = 'position:fixed;bottom:24px;right:24px;background:#7a2a2a;color:#fff;padding:14px 20px;border-radius:10px;font-size:13px;font-weight:600;z-index:9999;box-shadow:0 4px 20px rgba(0,0,0,0.3);';
    toast.textContent = 'Customer given 24 hours to settle the initial fee.';
    document.body.appendChild(toast);
    setTimeout(() => toast.remove(), 4000);

  } catch (e) {
    console.error('[declineInitialCashPayment]', e);
    alert('Failed to update: ' + e.message);
    btn.disabled = false;
  }
};

window.saveDownpaymentSchedule = async function () {
  if (!activeMeetingResCache) return;
  const res = activeMeetingResCache || {};
  const total = getReliableMtTotal();
  const _cName = (res.city || res.venueLocation || res.venueCity || '').toLowerCase();
  const _addr = (res.venue || res.venueName || '').toLowerCase();
  const _isOut = !(_cName.includes('malabon') || _addr.includes('malabon'));

  let _otc = parseFloat(res.outOfTownCharge || res.out_of_town_charge || 0);
  if (_otc <= 0 && _isOut) {
    _otc = Math.round(total * 0.05);
  } else if (!_isOut) {
    _otc = 0;
  }

  const svcp = window.mtServiceChargePct !== undefined && window.mtServiceChargePct !== null ? window.mtServiceChargePct : (parseFloat(res.service_charge_pct || res.serviceChargePct) || 0);
  const rawNoOtc = (_otc > 0 && total >= _otc) ? (total - _otc) : total;
  const baseTotal = (res.basePrice || res.base_price) ? parseFloat(res.basePrice || res.base_price) : (svcp > 0 ? Math.round(rawNoOtc / (1 + svcp / 100)) : rawNoOtc);
  const amount = Math.round(baseTotal * 0.5) || 0;
  const dueDate = document.getElementById('mt-downpayment-due').value;

  if (!dueDate) return alert('Please select a due date for the downpayment schedule.');

  const btn = document.getElementById('btn-save-downpayment');
  btn.disabled = true;
  btn.textContent = 'Saving Schedule...';

  try {
    const { doc, updateDoc } = window.firebaseFns;
    await updateDoc(doc(window.firebaseDB, 'reservations', activeMeetingResCache.id), {
      downpaymentAmount: amount,
      downpaymentDueDate: dueDate
    });
    // Also push to Supabase reservations table AND meetings design_notes
    if (window.supabaseClient) {
      try {
        await window.supabaseClient.from('reservations').update({
          downpayment_amount: amount,
          downpayment_due_date: dueDate
        }).eq('id', activeMeetingResCache.id);
      } catch (sbe) {
        console.warn('[saveDownpaymentSchedule] supabase reservations error:', sbe.message);
      }
      if (activeMeeting && activeMeeting.id && activeMeeting.id !== 'demo') {
        try {
          const curNotes = (typeof activeMeeting.design_notes === 'object' && activeMeeting.design_notes !== null) ? { ...activeMeeting.design_notes } : {};
          curNotes.downpayment_amount = amount;
          curNotes.downpayment_due_date = dueDate;
          await window.supabaseClient.from('meetings').update({
            design_notes: curNotes
          }).eq('id', activeMeeting.id);
        } catch (me) {
          console.warn('[saveDownpaymentSchedule] meetings design_notes error:', me.message);
        }
      }
    }
    activeMeetingResCache.downpaymentDueDate = dueDate;
    activeMeetingResCache.downpayment_due_date = dueDate;
    activeMeetingResCache.downpaymentAmount = amount;
    activeMeetingResCache.downpayment_amount = amount;
    if (typeof RESERVATIONS !== 'undefined' && Array.isArray(RESERVATIONS)) {
      const rM = RESERVATIONS.find(r => r.id === activeMeetingResCache.id);
      if (rM) {
        rM.downpaymentDueDate = dueDate;
        rM.downpayment_due_date = dueDate;
        rM.downpaymentAmount = amount;
        rM.downpayment_amount = amount;
      }
    }
    alert('Downpayment schedule saved.');
  } catch (e) {
    console.error(e);
    alert('Failed to save schedule');
  } finally {
    btn.disabled = false;
    btn.textContent = 'Save Downpayment Schedule';
  }
};

window.cancelDownpaymentSchedule = async function () {
  if (!activeMeetingResCache) return;
  const btn = document.getElementById('btn-cancel-downpayment');
  if (btn) {
    btn.disabled = true;
    btn.textContent = 'Canceling...';
  }

  try {
    const { doc, updateDoc } = window.firebaseFns;
    await updateDoc(doc(window.firebaseDB, 'reservations', activeMeetingResCache.id), {
      downpaymentAmount: null,
      downpaymentDueDate: null
    });
    if (window.supabaseClient) {
      try {
        await window.supabaseClient.from('reservations').update({
          downpayment_amount: null,
          downpayment_due_date: null
        }).eq('id', activeMeetingResCache.id);
      } catch (sbe) {}
      if (activeMeeting && activeMeeting.id && activeMeeting.id !== 'demo') {
        try {
          const curNotes = (typeof activeMeeting.design_notes === 'object' && activeMeeting.design_notes !== null) ? { ...activeMeeting.design_notes } : {};
          delete curNotes.downpayment_amount;
          delete curNotes.downpayment_due_date;
          await window.supabaseClient.from('meetings').update({
            design_notes: curNotes
          }).eq('id', activeMeeting.id);
        } catch (me) {}
      }
    }
    activeMeetingResCache.downpaymentDueDate = null;
    activeMeetingResCache.downpayment_due_date = null;
    activeMeetingResCache.downpaymentAmount = null;
    activeMeetingResCache.downpayment_amount = null;
    if (typeof RESERVATIONS !== 'undefined' && Array.isArray(RESERVATIONS)) {
      const rM = RESERVATIONS.find(r => r.id === activeMeetingResCache.id);
      if (rM) {
        rM.downpaymentDueDate = null;
        rM.downpayment_due_date = null;
        rM.downpaymentAmount = null;
        rM.downpayment_amount = null;
      }
    }
    const dueInput = document.getElementById('mt-downpayment-due');
    if (dueInput) dueInput.value = '';

    alert('Downpayment schedule canceled.');
  } catch (e) {
    console.error(e);
    alert('Failed to cancel schedule');
    if (btn) btn.disabled = false;
  } finally {
    if (btn) btn.textContent = 'Cancel Schedule';
  }
};

window.saveFinalPaymentSchedule = async function () {
  if (!activeMeetingResCache) return;
  const res = activeMeetingResCache || {};
  const total = getReliableMtTotal();
  const _details = (typeof computePricingDetails === 'function')
    ? computePricingDetails(res, res.pax, total)
    : null;

  const _cName = (res.city || res.venueLocation || res.venueCity || '').toLowerCase();
  const _addr = (res.venue || res.venueName || '').toLowerCase();
  const _isOut = !(_cName.includes('malabon') || _addr.includes('malabon'));

  let _otc = parseFloat(res.outOfTownCharge || res.out_of_town_charge || 0);
  if (_details && _details.otc !== undefined) {
    _otc = _details.otc;
  } else if (_otc <= 0 && _isOut) {
    _otc = Math.round(total * 0.05);
  } else if (!_isOut) {
    _otc = 0;
  }

  const svcp = window.mtServiceChargePct !== undefined && window.mtServiceChargePct !== null ? window.mtServiceChargePct : (parseFloat(res.service_charge_pct || res.serviceChargePct) || (_details ? _details.serviceChargePct : 0));
  const rawNoOtc = (_otc > 0 && total >= _otc) ? (total - _otc) : total;
  let baseTotal = (_details && _details.basePrice > 0) ? _details.basePrice : ((res.basePrice || res.base_price) ? parseFloat(res.basePrice || res.base_price) : 0);
  if (!baseTotal) {
    baseTotal = svcp > 0 ? Math.round(rawNoOtc / (1 + svcp / 100)) : rawNoOtc;
  }
  const extraItemsTotal = _details ? (_details.extraItemsTotal || 0) : (parseFloat(res.additional_items_charge || res.additionalItemsCharge || 0) || 0);
  const dpAmount = Math.round(baseTotal * 0.5) || 0;
  const serviceChargeAmt = _details ? _details.serviceChargeAmt : (svcp > 0 ? Math.round((baseTotal + extraItemsTotal) * (svcp / 100)) : 0);
  const finalAmount = (baseTotal - dpAmount) + extraItemsTotal + _otc + serviceChargeAmt;

  const dueInput = document.getElementById('mt-final-payment-due');
  const dueDate = dueInput ? dueInput.value : '';

  if (!dueDate) return alert('Please select a due date for the final payment schedule.');

  // Validate: min = today, max = eventDate - 3 days
  const todayStr = new Date().toISOString().split('T')[0];
  if (dueDate < todayStr) {
    return alert('Final payment due date cannot be in the past.');
  }

  const rawEventDate = (res && res.date) || '';
  if (rawEventDate) {
    const normalizedEventDate = (typeof normalizeDateKey === 'function') ? normalizeDateKey(rawEventDate) : rawEventDate;
    if (normalizedEventDate) {
      const evtDate = new Date(normalizedEventDate + 'T00:00:00');
      if (!isNaN(evtDate.getTime())) {
        const maxDate = new Date(evtDate);
        maxDate.setDate(maxDate.getDate() - 3);
        const maxDateStr = maxDate.toISOString().split('T')[0];
        if (dueDate > maxDateStr) {
          return alert(`Final payment due date must be at least 3 days before the event date (${rawEventDate}). Maximum allowed due date is ${maxDateStr}.`);
        }
      }
    }
  }

  const btn = document.getElementById('btn-save-final-payment');
  if (btn) { btn.disabled = true; btn.textContent = 'Saving Schedule...'; }

  try {
    const { doc, updateDoc } = window.firebaseFns;
    // 1. Firebase reservations
    await updateDoc(doc(window.firebaseDB, 'reservations', activeMeetingResCache.id), {
      finalPaymentAmount: finalAmount,
      final_payment_amount: finalAmount,
      finalPaymentDueDate: dueDate,
      final_payment_due_date: dueDate
    });

    // 2. Supabase reservations table
    if (window.supabaseClient) {
      await window.supabaseClient.from('reservations').update({
        final_payment_due_date: dueDate
      }).eq('id', activeMeetingResCache.id);

      // Also update reservation_payments if a final payment schedule record exists
      try {
        await window.supabaseClient.from('reservation_payments').update({
          due_date: dueDate
        }).eq('reservation_id', activeMeetingResCache.id).eq('payment_type', 'final');
      } catch (e) {}
    }

    // 3. Supabase meetings row (so customer meeting room picks it up in realtime)
    if (activeMeeting && activeMeeting.id && activeMeeting.id !== 'demo' && window.supabaseClient) {
      await window.supabaseClient.from('meetings').update({
        final_payment_due_date: dueDate
      }).eq('id', activeMeeting.id);
    }

    // Update local cache
    activeMeetingResCache.finalPaymentDueDate = dueDate;
    activeMeetingResCache.final_payment_due_date = dueDate;
    const rMatch = RESERVATIONS.find(r => r.id === activeMeetingResCache.id);
    if (rMatch) {
      rMatch.finalPaymentDueDate = dueDate;
      rMatch.final_payment_due_date = dueDate;
      rMatch.finalPaymentAmount = finalAmount;
      rMatch.final_payment_amount = finalAmount;
    }

    // Regenerate and save logistics milestones with updated final payment schedule
    const extra = getActiveReservationExtra(activeMeetingResCache.id);
    if (extra && extra.logisticsMilestones && extra.logisticsMilestones.length > 0) {
      const resForLogistics = { ...activeMeetingResCache, finalPaymentDueDate: dueDate, final_payment_due_date: dueDate, finalPaymentAmount: finalAmount, final_payment_amount: finalAmount };
      const _resMeetings = window.MEETINGS ? window.MEETINGS.filter(m => (m.reservationId === activeMeetingResCache.id || m.reservation_id === activeMeetingResCache.id)) : [];
      const logisticsData = generateAutoLogisticsMilestones(resForLogistics, _resMeetings);
      extra.logisticsMilestones = logisticsData.milestones;
      extra.timelineTasks = (extra.timelineTasks || []).filter(t => t.type !== 'auto' && !t.id.startsWith('auto-')).concat(logisticsData.tasks);
      await updateDoc(doc(window.firebaseDB, 'reservations', activeMeetingResCache.id), {
        logisticsMilestones: extra.logisticsMilestones,
        timelineTasks: extra.timelineTasks
      });
      if (rMatch) {
        rMatch.logisticsMilestones = extra.logisticsMilestones;
        rMatch.timelineTasks = extra.timelineTasks;
      }
    }

    const cancelFinalBtn = document.getElementById('btn-cancel-final-payment');
    if (cancelFinalBtn) cancelFinalBtn.disabled = false;

    alert('Final payment schedule saved successfully.');
  } catch (e) {
    console.error('saveFinalPaymentSchedule error:', e);
    alert('Failed to save final payment schedule: ' + (e.message || e));
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'Save Final Payment Schedule'; }
  }
};

