window.saveCancellationWindowSchedule = async function () {
  if (!activeMeetingResCache) return;
  const input = document.getElementById('mt-cancellation-window-date');
  const dueDate = input ? input.value : '';
  if (!dueDate) return alert('Please select a cancellation window date.');

  const today = new Date().toISOString().split('T')[0];
  if (dueDate < today) {
    return alert('Cancellation window date cannot be in the past.');
  }
  const rawEvt = activeMeetingResCache.date || activeMeetingResCache.eventDate || activeMeetingResCache.event_date;
  const evtNorm = (typeof normalizeDateKey === 'function') ? normalizeDateKey(rawEvt) : rawEvt;
  if (evtNorm && dueDate > evtNorm) {
    return alert('Cancellation window date cannot be past the event date (' + evtNorm + ').');
  }

  const btn = document.getElementById('btn-save-cancellation-window');
  if (btn) { btn.disabled = true; btn.textContent = 'Saving...'; }

  try {
    if (window.supabaseClient) {
      try {
        await window.supabaseClient.from('reservations').update({
          cancellation_window: dueDate
        }).eq('id', activeMeetingResCache.id);
      } catch (re) {
        console.warn('[saveCancellationWindowSchedule] reservations cw fallback:', re.message);
      }

      if (activeMeeting && activeMeeting.id && activeMeeting.id !== 'demo') {
        try {
          const curNotes = (typeof activeMeeting.design_notes === 'object' && activeMeeting.design_notes !== null) ? { ...activeMeeting.design_notes } : {};
          curNotes.cancellation_window = dueDate;
          await window.supabaseClient.from('meetings').update({
            cancellation_window: dueDate,
            cancellationNote: dueDate,
            design_notes: curNotes
          }).eq('id', activeMeeting.id);
        } catch (me) {
          console.warn('[saveCancellationWindowSchedule] meetings cw warning:', me.message);
        }
      }
    }

    if (window.firebaseFns && window.firebaseDB) {
      try {
        const { doc, updateDoc } = window.firebaseFns;
        await updateDoc(doc(window.firebaseDB, 'reservations', activeMeetingResCache.id), {
          cancellation_window: dueDate,
          cancellationWindow: dueDate
        });
        if (activeMeeting && activeMeeting.id) {
          await updateDoc(doc(window.firebaseDB, 'meetings', activeMeeting.id), {
            cancellation_window: dueDate
          });
        }
      } catch (e) {}
    }

    activeMeetingResCache.cancellation_window = dueDate;
    activeMeetingResCache.cancellationWindow = dueDate;
    if (activeMeeting) {
      activeMeeting.cancellation_window = dueDate;
      activeMeeting.cancellationWindow = dueDate;
      activeMeeting.cancellationNote = dueDate;
      if (!activeMeeting.design_notes) activeMeeting.design_notes = {};
      activeMeeting.design_notes.cancellation_window = dueDate;
    }

    const rMatch = (typeof RESERVATIONS !== 'undefined') ? RESERVATIONS.find(r => r.id === activeMeetingResCache.id) : null;
    if (rMatch) {
      rMatch.cancellation_window = dueDate;
      rMatch.cancellationWindow = dueDate;
    }

    const cancelCwBtn = document.getElementById('btn-cancel-cancellation-window');
    if (cancelCwBtn) cancelCwBtn.disabled = false;

    alert('Cancellation window saved.');
  } catch (err) {
    console.error('[saveCancellationWindowSchedule]', err);
    alert('Failed to save cancellation window: ' + err.message);
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'Save Cancellation Window'; }
  }
};

