window.openInitialFeeSchedulePanel = function () {
  const panel = document.getElementById('mt-initial-fee-schedule-panel');
  if (!panel) return;
  const isHidden = panel.style.display === 'none' || !panel.style.display;
  panel.style.display = isHidden ? 'block' : 'none';
  const input = document.getElementById('mt-initial-fee-due');
  if (input && activeMeetingResCache) {
    const today = new Date().toISOString().split('T')[0];
    input.min = today;
    const rawEvt = activeMeetingResCache.date || activeMeetingResCache.eventDate || activeMeetingResCache.event_date;
    const evtNorm = (typeof normalizeDateKey === 'function') ? normalizeDateKey(rawEvt) : rawEvt;
    if (evtNorm) input.max = evtNorm;
    if (activeMeetingResCache.initial_fee_due_date || activeMeetingResCache.initialFeeDueDate) {
      input.value = activeMeetingResCache.initial_fee_due_date || activeMeetingResCache.initialFeeDueDate;
    }
  }

  // If initial fee was currently in triggered state, dismiss customer payment modal immediately
  if (activeMeeting && activeMeeting.initial_fee_status === 'triggered') {
    activeMeeting.initial_fee_status = 'pending_schedule';
    if (window.supabaseClient) {
      window.supabaseClient.from('meetings').update({ initial_fee_status: 'pending_schedule' }).eq('id', activeMeeting.id).catch(() => {});
    }
    if (window.firebaseFns && window.firebaseDB) {
      try {
        const { doc, updateDoc } = window.firebaseFns;
        updateDoc(doc(window.firebaseDB, 'meetings', activeMeeting.id), { initial_fee_status: 'pending_schedule' }).catch(() => {});
      } catch(e) {}
    }
  }
};

