// ====================================================================
// ==================== RESERVATION DETAILS GPS MAP ===================
// ====================================================================
let resdMap = null;
let resdMarker = null;
const _geocodeCache = new Map();
let _geocodeCooldownUntil = 0;

async function initResdMap(address, existingCoords) {
  if (!address) return;
  const container = document.getElementById('resd-map');
  if (!container) return;

  // Cleanup old map if exists
  if (resdMap) {
    try {
      resdMap.remove();
    } catch(e) {}
    resdMap = null;
  }

  try {
    let coords = null;
    // 1. Use existingCoords if valid
    if (existingCoords) {
      if (typeof existingCoords === 'object') {
        const lat = existingCoords.lat ?? existingCoords.latitude ?? (Array.isArray(existingCoords) ? existingCoords[0] : null);
        const lon = existingCoords.lon ?? existingCoords.lng ?? existingCoords.longitude ?? (Array.isArray(existingCoords) ? existingCoords[1] : null);
        if (lat !== null && lon !== null && !isNaN(lat) && !isNaN(lon)) {
          coords = { lat: parseFloat(lat), lon: parseFloat(lon) };
        }
      }
    }

    // 2. If no coords yet, try geocode with caching & rate-limit protection
    if (!coords) {
      coords = await geocodeAddress(address);
    }

    // 3. Fallback to Metro Manila coordinates if unavailable
    const finalCoords = coords || { lat: 14.5995, lon: 120.9842 };

    if (!window.L || !L.map) return;

    resdMap = L.map('resd-map').setView([finalCoords.lat, finalCoords.lon], coords ? 16 : 12);
    L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}', {
      maxZoom: 19,
      attribution: '&copy; OpenStreetMap'
    }).addTo(resdMap);

    resdMarker = L.marker([finalCoords.lat, finalCoords.lon]).addTo(resdMap)
      .bindPopup(address + (coords ? '' : ' (Approximate Location)'))
      .openPopup();

    // Remove loading text
    const loadingText = container.querySelector('div');
    if (loadingText && loadingText.textContent.includes('Loading')) {
      loadingText.remove();
    }
  } catch (err) {
    container.innerHTML = `<div style="display:flex; align-items:center; justify-content:center; height:100%; color:var(--text-dim); font-size:12px; padding:20px; text-align:center;">
       Map unavailable.<br/><span style="opacity:0.6; margin-top:4px;">OSM could not locate: "${address}"</span>
    </div>`;
  }
}

async function geocodeAddress(address) {
  if (!address) return null;
  const rawKey = String(address).trim().toLowerCase();

  // 1. Check in-memory cache
  if (_geocodeCache.has(rawKey)) {
    return _geocodeCache.get(rawKey);
  }

  // 2. Check sessionStorage cache
  try {
    const cached = sessionStorage.getItem('geo_cache_' + rawKey);
    if (cached) {
      const parsed = JSON.parse(cached);
      _geocodeCache.set(rawKey, parsed);
      return parsed;
    }
  } catch(e) {}

  // 3. Check rate limit cooldown (do not spam if recently throttled)
  if (Date.now() < _geocodeCooldownUntil) {
    return null;
  }

  const tryFetch = async (query) => {
    try {
      const url = `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query)}&limit=1`;
      const response = await fetch(url, {
        headers: {
          'Accept-Language': 'en-US,en;q=0.5'
        }
      });
      if (response.status === 429) {
        _geocodeCooldownUntil = Date.now() + 60000;
        return null;
      }
      if (!response.ok) return null;
      const data = await response.json();
      if (Array.isArray(data) && data.length > 0) {
        return { lat: parseFloat(data[0].lat), lon: parseFloat(data[0].lon) };
      }
      return null;
    } catch (err) {
      return null;
    }
  };

  // Try full address
  let coords = await tryFetch(address);

  // If not found and not in cooldown, try stripping first part
  if (!coords && Date.now() >= _geocodeCooldownUntil && address.includes(',')) {
    const parts = address.split(',');
    if (parts.length > 1) {
      const fallback = parts.slice(1).join(',').trim();
      coords = await tryFetch(fallback);
    }
  }

  // Cache result (even if null, to avoid repeated requests in same session)
  _geocodeCache.set(rawKey, coords);
  try {
    sessionStorage.setItem('geo_cache_' + rawKey, JSON.stringify(coords));
  } catch(e) {}

  return coords;
}

window.initResdMap = initResdMap;

window.zoomDoc = function (btn, delta) {
  const container = btn.closest('.doc-zoom-container');
  const img = container.querySelector('.doc-zoom-img');
  if (!img) return;

  let scale = parseFloat(img.getAttribute('data-zoom') || '1');
  scale += delta;
  if (scale < 0.5) scale = 0.5;
  if (scale > 4.0) scale = 4.0;

  img.style.transform = `scale(${scale})`;
  img.setAttribute('data-zoom', scale);
};

window.changeContractSlide = function (dir, totalSlides) {
  const container = document.getElementById('contract-carousel-container');
  if (!container) return;
  const slides = container.querySelectorAll('.contract-slide-img');
  if (!slides || slides.length === 0) return;

  let currentIdx = 0;
  slides.forEach((slide) => {
    if (slide.style.display === 'block') {
      currentIdx = parseInt(slide.getAttribute('data-idx') || '0', 10);
      slide.style.display = 'none';
      // Reset zoom
      slide.style.transform = 'scale(1)';
      slide.setAttribute('data-zoom', '1');
    }
  });

  let nextIdx = currentIdx + dir;
  if (nextIdx < 0) nextIdx = slides.length - 1;
  if (nextIdx >= slides.length) nextIdx = 0;

  const nextSlide = container.querySelector(`.contract-slide-img[data-idx="${nextIdx}"]`);
  if (nextSlide) nextSlide.style.display = 'block';

  const indicator = document.getElementById('contract-slide-indicator');
  if (indicator) indicator.textContent = `${nextIdx + 1} / ${totalSlides}`;

  // Also update the view button's target to the newly visible slide's URL
  const activeImg = container.querySelector('.contract-slide-img[style*="display: block"]') || nextSlide;
  if (activeImg) {
    const viewBtn = document.querySelector('.panel-hdr button[onclick="openCurrentContractDoc()"]');
    if (viewBtn) viewBtn.setAttribute('data-current-url', activeImg.src);
  }
};

window.openCurrentContractDoc = function () {
  // First try to read the data attribute set by changeContractSlide
  const viewBtn = document.querySelector('button[onclick="openCurrentContractDoc()"]');
  if (viewBtn && viewBtn.getAttribute('data-current-url')) {
    window.open(viewBtn.getAttribute('data-current-url'), '_blank');
    return;
  }
  // Fallback: find whichever slide is currently visible
  const container = document.getElementById('contract-carousel-container');
  if (container) {
    const visible = container.querySelector('.contract-slide-img[style*="display: block"]')
      || container.querySelector('.contract-slide-img');
    if (visible && visible.src) {
      window.open(visible.src, '_blank');
      return;
    }
  }
  // Last resort: find any contract-slide-img on the page
  const anyImg = document.querySelector('.contract-slide-img');
  if (anyImg && anyImg.src) window.open(anyImg.src, '_blank');
};


// ====================================================================
// EXECUTION DAY PLANNING PANEL
// ====================================================================

let activeExecutionPlannerDate = null;
let activeExecPhaseIdx = 0;

// ── Execution Plan Time & Phase Construction Helpers ─────────────────────────
function parseExecTime(str) {
  if (!str) return null;
  var s = String(str).trim();
  if (/^\d{2}:\d{2}$/.test(s)) return s;
  var m = s.match(/(\d{1,2}):(\d{2})(?::\d{2})?\s*(AM|PM|am|pm)?/);
  if (!m) return null;
  var h = parseInt(m[1], 10);
  var min = m[2];
  var ap = (m[3] || '').toUpperCase();
  if (ap === 'PM' && h < 12) h += 12;
  if (ap === 'AM' && h === 12) h = 0;
  return String(h).padStart(2, '0') + ':' + min;
}
function addExecMins(hhmm, mins) {
  if (!hhmm) return '00:00';
  var p = hhmm.split(':').map(Number);
  var tot = Math.max(0, Math.min(1439, p[0] * 60 + p[1] + mins));
  return String(Math.floor(tot / 60)).padStart(2, '0') + ':' + String(tot % 60).padStart(2, '0');
}
function subExecMins(hhmm, mins) { return addExecMins(hhmm, -mins); }
function fmt12Exec(hhmm) {
  if (!hhmm) return '--:--';
  var p = hhmm.split(':').map(Number);
  var ap = p[0] >= 12 ? 'PM' : 'AM';
  return (p[0] % 12 || 12) + ':' + String(p[1]).padStart(2, '0') + ' ' + ap;
}

/**
 * Builds the standard 5-phase execution plan for any reservation:
 * Departure -> Deployment -> Execution -> Bash-out -> Restorage
 * Guarantees that an execution plan is always ready as long as a reservation is active.
 */
function buildDefaultPhasesForRes(res) {
  var execStart = '10:00', execEnd = '22:00';
  var rawTime = (res && (res.time || res.timeframe)) || '';
  if (rawTime) {
    var sep = rawTime.toLowerCase().includes(' to ') ? / to /i : (rawTime.includes(' - ') ? / - / : (rawTime.includes('-') ? /-/ : null));
    if (sep) {
      var parts = rawTime.split(sep);
      execStart = parseExecTime(parts[0].trim()) || execStart;
      execEnd   = parseExecTime(parts[1].trim()) || execEnd;
    } else {
      execStart = parseExecTime(rawTime.trim()) || execStart;
    }
  }
  var callTime = (res && parseExecTime(res.callTime || res.call_time)) || execStart;
  var deployStart = subExecMins(callTime, 60);
  var depStart    = subExecMins(deployStart, 60);
  var bashEnd     = addExecMins(execEnd, 180);
  var restEnd     = addExecMins(bashEnd, 150);

  return [
    { id: 'departure',  name: 'Departure',  start: depStart,    end: deployStart, locked: false,
      tasks: [{ text: 'Load transport & equipment', staffIds: [] }, { text: 'Depart confirmed', staffIds: [] }] },
    { id: 'deployment', name: 'Deployment', start: deployStart, end: callTime,    locked: false,
      tasks: [{ text: 'Venue dock check-in & unload', staffIds: [] }, { text: 'Setup tables & linens', staffIds: [] }, { text: 'Setup buffet & stations', staffIds: [] }, { text: 'Staff briefing', staffIds: [] }, { text: 'Deployment ready sign-off', staffIds: [] }] },
    { id: 'execution',  name: 'Execution',  start: callTime,    end: execEnd,     locked: true,
      tasks: [{ text: 'Guest arrival & reception', staffIds: [] }, { text: 'Buffet & service monitoring', staffIds: [] }, { text: 'Manager floor walk', staffIds: [] }], agenda: [] },
    { id: 'bashout',    name: 'Bash-out',   start: execEnd,     end: bashEnd,     locked: false,
      tasks: [{ text: 'Pack & inventory equipment', staffIds: [] }, { text: 'Venue sweep & cleanup', staffIds: [] }, { text: 'Load-out transport', staffIds: [] }] },
    { id: 'restorage',  name: 'Restorage',  start: bashEnd,     end: restEnd,     locked: false,
      tasks: [{ text: 'Return to office', staffIds: [] }, { text: 'Unload & inventory check', staffIds: [] }] }
  ];
}
window.buildDefaultPhasesForRes = buildDefaultPhasesForRes;

async function openExecutionPlanner(dateStr, options) {
  activeExecutionPlannerDate = dateStr;
  var panel = document.getElementById('resd-execution-planner');
  if (!panel) return;
  panel.style.display = 'block';

  var res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(function(r) {
    return r.id === activeResDetailId || String(r.id) === String(activeResDetailId);
  });
  if (!res) return;

  var parseTime = parseExecTime;
  var addMins = addExecMins;
  var subMins = subExecMins;
  var fmt12 = fmt12Exec;

  // ── Parse reservation time range from res.time ("10:00 AM to 10:00 PM") ──
  var execStart = '10:00', execEnd = '22:00';
  var rawTime = res.time || res.timeframe || '';
  if (rawTime) {
    var sep = rawTime.toLowerCase().includes(' to ') ? / to /i : (rawTime.includes(' - ') ? / - / : (rawTime.includes('-') ? /-/ : null));
    if (sep) {
      var parts = rawTime.split(sep);
      execStart = parseTime(parts[0].trim()) || execStart;
      execEnd   = parseTime(parts[1].trim()) || execEnd;
    } else {
      execStart = parseTime(rawTime.trim()) || execStart;
    }
  }
  // Call time = separate callTime field, or falls back to execStart
  var callTime = parseTime(res.callTime || res.call_time) || execStart;

  // ── Update range label ───────────────────────────────────────────────────
  var rangeEl = document.getElementById('exec-planner-range');
  if (rangeEl) rangeEl.textContent = 'Execution: ' + fmt12(callTime) + ' \u2013 ' + fmt12(execEnd);
  var subtitleEl = document.getElementById('exec-planner-subtitle');
  if (subtitleEl) subtitleEl.textContent = 'Plan strict timeframes for ' + (dateStr || res.date || 'event day');

  // ── Build default 5-phase plan ───────────────────────────────────────────
  function buildDefaultPhases() {
    return buildDefaultPhasesForRes(res);
  }

  // ── Try loading saved plan from Supabase ─────────────────────────────────
  var loadedPlan = null;
  try {
    if (window.supabaseClient) {
      var sbRes = await window.supabaseClient
        .from('execution_plans').select('*').eq('reservation_id', res.id).maybeSingle();
      if (sbRes && sbRes.data && Array.isArray(sbRes.data.phases) && sbRes.data.phases.length > 0) {
        loadedPlan = sbRes.data;
      }
    }
  } catch(e) { console.warn('Supabase execution_plans fetch:', e.message || e); }

  function normalizePhases(phases) {
    if (!Array.isArray(phases)) return buildDefaultPhases();
    return phases.map(function(p) {
      if (!Array.isArray(p.tasks)) p.tasks = [];
      p.tasks = p.tasks.map(function(t) { return typeof t === 'string' ? {text:t,staffIds:[]} : t; });
      
      // Cleanup unwanted tasks across all plans globally
      if (p.id === 'departure') {
        p.tasks = p.tasks.filter(t => t.text === 'Load transport & equipment' || t.text === 'Depart confirmed');
      } else if (p.id === 'execution') {
        p.tasks = p.tasks.filter(t => t.text !== 'VIP table management' && t.text !== 'Serve guests');
      } else if (p.id === 'bashout') {
        p.tasks = p.tasks.filter(t => t.text !== 'Soft-close buffet' && t.text !== 'Pack equipment');
      } else if (p.id === 'restorage') {
        p.tasks = p.tasks.filter(t => t.text !== 'Wash & store equipment' && t.text !== 'Mark storage closed');
        p.tasks.forEach(t => { if(t.text === 'Return to warehouse') t.text = 'Return to office'; });
      }

      if (!('locked' in p)) p.locked = (p.id === 'execution');
      return p;
    });
  }

  if (loadedPlan) {
    var phases = normalizePhases(loadedPlan.phases);
    if (res.executionPlan && res.executionPlan.phases) {
      var localExec = res.executionPlan.phases.find(function(p){ return p.id === 'execution'; });
      var loadExec = phases.find(function(p){ return p.id === 'execution'; });
      if (localExec && localExec.agenda && localExec.agenda.length > 0 && loadExec) {
        if (!loadExec.agenda || loadExec.agenda.length === 0) {
          loadExec.agenda = localExec.agenda;
        }
      }
    }
    // Always keep execution phase times locked to current reservation
    phases.forEach(function(p) {
      if (p.id === 'execution') { p.start = callTime; p.end = execEnd; p.locked = true; }
    });
    res.executionPlan = { flexibility: loadedPlan.flexibility || 'strict', phases: phases };
  } else if (!res.executionPlan) {
    res.executionPlan = { flexibility: 'strict', phases: buildDefaultPhases() };
  } else {
    // Sync existing local plan
    res.executionPlan.phases = normalizePhases(res.executionPlan.phases);
    res.executionPlan.phases.forEach(function(p) {
      if (p.id === 'execution') { p.start = callTime; p.end = execEnd; p.locked = true; }
    });
  }

  // Force domino sync around execution phase globally on load
  if (res.executionPlan && res.executionPlan.phases) {
    var ePlan = res.executionPlan.phases;
    var exe = ePlan.find(function(x){ return x.id === 'execution'; });
    var dep = ePlan.find(function(x){ return x.id === 'deployment'; });
    var bash = ePlan.find(function(x){ return x.id === 'bashout'; });
    if (exe && dep) dep.end = exe.start;
    if (exe && bash) bash.start = exe.end;
  }

  // Force sync agenda from additional_reservation_details directly just in case
  try {
    if (window.supabaseClient && res && res.executionPlan && res.executionPlan.phases) {
      var ardRes = await window.supabaseClient.from('additional_reservation_details')
        .select('event_flow').eq('reservation_id', res.id).maybeSingle();
      if (ardRes && ardRes.data && Array.isArray(ardRes.data.event_flow) && ardRes.data.event_flow.length > 0) {
        var execP = res.executionPlan.phases.find(function(p) { return p.id === 'execution'; });
        if (execP) {
          // Check if the event_flow is the old phase format or the new agenda array format
          if (ardRes.data.event_flow[0] && ardRes.data.event_flow[0].id === 'execution') {
            execP.agenda = ardRes.data.event_flow[0].agenda || execP.agenda;
          } else {
            execP.agenda = ardRes.data.event_flow;
          }
        }
      }
    }
  } catch(e) { console.warn('Supabase ard event_flow fetch:', e); }

  var flexEl = document.getElementById('exec-planner-flexibility');
  if (flexEl) flexEl.value = res.executionPlan.flexibility || 'strict';
  activeExecPhaseIdx = 0;

  await renderExecutionPlannerStaff();
  renderExecutionPlannerPhases();
  renderExecutionTimelineVisual();

  if (!options || !options.noScroll) {
    setTimeout(function() { try { panel.scrollIntoView({ behavior:'smooth', block:'nearest' }); } catch(e){} }, 150);
  }
}

function closeExecutionPlanner() {
  const panel = document.getElementById('resd-execution-planner');
  if (panel) panel.style.display = 'none';
  activeExecutionPlannerDate = null;
}

async function renderExecutionPlannerStaff() {
  var container = document.getElementById('exec-planner-staff');
  if (!container) return;

  var res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(function(r) {
    return r.id === activeResDetailId || String(r.id) === String(activeResDetailId);
  });
  if (!res) {
    container.innerHTML = '<div style="font-size:11px;color:var(--text-dim);">No reservation selected.</div>';
    return;
  }

  container.innerHTML = '<div style="font-size:11px;color:var(--text-dim);">Loading staff...</div>';

  var staffList = [];

  // 1. Try Supabase reservation_staff_assignments
  try {
    if (window.supabaseClient) {
      var result = await window.supabaseClient
        .from('reservation_staff_assignments')
        .select('staff_id, roles')
        .eq('reservation_id', res.id);
      if (result && result.data && result.data.length > 0) {
        const sIds = result.data.map(function(r) { return r.staff_id; });
        const { data: uRes } = await window.supabaseClient.from('users').select('id, name').in('id', sIds);
        const uMap = {};
        if (uRes) {
          uRes.forEach(function(u) { uMap[u.id] = u.name; });
        }
        staffList = result.data.map(function(r) {
          var n = uMap[r.staff_id];
          return { staffId: r.staff_id, staffName: n || r.staff_id, roles: Array.isArray(r.roles) ? r.roles : [] };
        });
      }
    }
  } catch(e) { console.warn('Staff fetch error:', e.message); }

  // 2. Fallback: window.currentStaffAssignments (populated by Staff Allocation tab)
  if (staffList.length === 0 && window.currentStaffAssignments && window.currentStaffAssignments.length > 0) {
    var nameMap = {};
    (window.allStaff || []).forEach(function(s) { nameMap[s.id] = s.name; });
    staffList = window.currentStaffAssignments.map(function(a) {
      return { staffId: a.staff_id, staffName: nameMap[a.staff_id] || a.staff_id, roles: Array.isArray(a.roles) ? a.roles.filter(Boolean) : [] };
    });
  }

  // 3. Fallback: res.staffing.assignments (local state)
  if (staffList.length === 0) {
    var assignments = (res.staffing && res.staffing.assignments) || [];
    staffList = assignments.map(function(a) {
      return { staffId: a.staffId || a.staff_id, staffName: a.staffName || a.staff_name || a.staffId, roles: Array.isArray(a.roles) ? a.roles : [] };
    });
  }

  if (staffList.length === 0) {
    container.innerHTML = '<div style="font-size:11px;color:var(--text-dim);font-style:italic;">No staff assigned yet. Go to Staff Allocation tab first.</div>';
    res._execStaffList = [];
    return;
  }

  var roleDescMap = {
    'Setup & Styling': 'Handles decor and spatial arrangements',
    'Food Service': 'Manages catering and guest dining',
    'Logistics & Transport': 'Coordinates delivery and heavy lifting',
    'Event Coordinator': 'Oversees timeline and client requests',
    'Technical Support': 'Manages AV and lighting'
  };

  container.innerHTML = staffList.map(function(a) {
    var rolesHtml = a.roles.filter(Boolean).map(function(r) {
      var desc = roleDescMap[r] || 'Assigned role';
      return '<div style="display:flex; flex-direction:column; gap:2px; margin-top:6px;">' +
             '<span style="color:var(--gold); font-size:10px; font-weight:bold;">' + r + '</span>' +
             '<span style="color:var(--text-dim); font-size:9px;">' + desc + '</span></div>';
    }).join('');

    return '<div style="background:var(--bg);border:1px solid var(--border);padding:8px 12px;border-radius:6px; margin-bottom: 8px;">' +
      '<div style="font-size:12px;font-weight:700;color:var(--cream);">' + (a.staffName || a.staffId) + '</div>' +
      rolesHtml +
      '</div>';
  }).join('');

  // Store for use in phase rendering
  res._execStaffList = staffList;
}

function renderExecutionPlannerPhases() {
  var container = document.getElementById('exec-planner-phases');
  if (!container) return;

  function fmt12(hhmm) {
    if (!hhmm) return '--:--';
    var p = hhmm.split(':').map(Number);
    var ap = p[0] >= 12 ? 'PM' : 'AM';
    return (p[0]%12||12) + ':' + String(p[1]).padStart(2,'0') + ' ' + ap;
  }

  var res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(function(r) {
    return r.id === activeResDetailId || String(r.id) === String(activeResDetailId);
  });
  if (!res) {
    container.innerHTML = '<div style="text-align:center;padding:40px;color:var(--text-dim);font-size:12px;">Please select an active reservation to view its execution plan.</div>';
    return;
  }

  // Auto-generate default 5 phases if not initialized yet so an active reservation always has an execution plan
  if (!res.executionPlan || !res.executionPlan.phases || res.executionPlan.phases.length === 0) {
    res.executionPlan = { flexibility: 'strict', phases: buildDefaultPhasesForRes(res) };
  }

  var phases   = res.executionPlan.phases;
  var staffList = res._execStaffList || [];

  var phaseColors = { departure: '#c49a3c', deployment: '#3b82f6', execution: '#22c55e', bashout: '#ef4444', restorage: '#a855f7' };

  // ── Phase tab row ────────────────────────────────────────────────────────
  var tabsHtml = '<div style="display:flex;gap:10px;overflow-x:auto;padding-bottom:12px;margin-bottom:20px;border-bottom:1px solid var(--border);">';
  phases.forEach(function(p, idx) {
    var isActive = idx === activeExecPhaseIdx;
    var tasks    = p.tasks || [];
    var filled   = tasks.filter(function(t) { return t.staffIds && t.staffIds.length > 0; }).length;
    var accent   = phaseColors[p.id] || '#c49a3c';
    var lockBadge = p.locked
      ? '<div style="font-size:9px;background:rgba(34,197,94,0.15);color:#22c55e;padding:2px 6px;border-radius:10px;margin-top:4px;display:inline-block;">LOCKED</div>'
      : '<div style="font-size:9px;background:rgba(255,255,255,0.05);color:var(--text-dim);padding:2px 6px;border-radius:10px;margin-top:4px;display:inline-block;">EDITABLE</div>';
    tabsHtml +=
      '<div onclick="selectExecPhase(' + idx + ')" style="min-width:160px;flex-shrink:0;' +
        'background:' + (isActive ? 'rgba(255,255,255,0.07)' : 'var(--bg2)') + ';' +
        'border:2px solid ' + (isActive ? accent : 'var(--border)') + ';' +
        'border-radius:12px;padding:14px;cursor:pointer;position:relative;overflow:hidden;transition:all 0.2s;">' +
        '<div style="position:absolute;left:0;top:0;bottom:0;width:4px;background:' + accent + ';"></div>' +
        '<div style="font-size:14px;font-weight:800;color:' + (isActive ? accent : 'var(--cream)') + ';text-transform:uppercase;margin-bottom:4px;">' + p.name + '</div>' +
        '<div style="font-size:12px;color:var(--text-dim);">' + fmt12(p.start) + ' &rarr; ' + fmt12(p.end) + '</div>' +
        '<div style="font-size:12px;color:var(--text-dim);">' + filled + '/' + tasks.length + ' staffed</div>' +
        lockBadge +
      '</div>';
  });
  tabsHtml += '</div>';

  // ── Active phase detail ──────────────────────────────────────────────────
  var p = phases[activeExecPhaseIdx] || phases[0];
  if (!p) { container.innerHTML = tabsHtml; return; }

  var locked = !!p.locked;
  var accent = phaseColors[p.id] || '#c49a3c';

  function mkTimeInput(field, val) {
    var isSoftLocked = false;
    if (!locked) {
       if (p.id === 'deployment' && field === 'end') isSoftLocked = true;
       if (p.id === 'bashout' && field === 'start') isSoftLocked = true;
    }
    if (locked || isSoftLocked) {
      return '<input type="time" value="' + (val || '') + '" readonly disabled title="Locked to execution bounds" ' +
        'style="padding:6px 10px;font-size:15px;width:120px;opacity:0.5;cursor:not-allowed;background:var(--bg);border:1px solid var(--border);border-radius:6px;color:var(--text-dim);">';
    }
    return '<input type="time" value="' + (val || '') + '" ' +
      'oninput="updateExecPhaseField(' + activeExecPhaseIdx + ',\'' + field + '\',this.value)" ' +
      'style="padding:6px 10px;font-size:15px;width:120px;background:var(--bg);border:1px solid var(--border);border-radius:6px;color:var(--cream);">';
  }

  var tasks = p.tasks || [];
  var tasksHtml = tasks.length === 0
    ? '<div style="font-size:12px;color:var(--text-dim);font-style:italic;padding:20px 0;">No activities defined for this phase.</div>'
    : tasks.map(function(t, tIdx) {
        var chipsHtml = staffList.length > 0
          ? staffList.map(function(a) {
              var assigned = (t.staffIds || []).indexOf(a.staffId) !== -1;
              return '<span onclick="toggleStaffInTask(' + activeExecPhaseIdx + ',' + tIdx + ',\'' + a.staffId + '\')" ' +
                'style="cursor:pointer;display:inline-block;padding:4px 12px;border-radius:20px;font-size:13px;margin:2px;' +
                'background:' + (assigned ? accent : 'rgba(255,255,255,0.04)') + ';' +
                'color:' + (assigned ? '#000' : 'var(--text-dim)') + ';' +
                'border:1px solid ' + (assigned ? accent : 'var(--border)') + ';' +
                'font-weight:' + (assigned ? '700' : '400') + ';">' +
                (assigned ? '&#10003; ' : '+ ') + a.staffName + '</span>';
            }).join('')
          : '<span style="font-size:11px;color:var(--text-dim);font-style:italic;">No staff assigned to reservation yet.</span>';

        return '<div style="background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.06);border-radius:10px;padding:14px;margin-bottom:10px;">' +
          '<div style="display:flex;align-items:center;gap:10px;margin-bottom:10px;">' +
            '<div style="width:8px;height:8px;border-radius:50%;background:' + accent + ';flex-shrink:0;"></div>' +
            '<input type="text" value="' + (t.text || '').replace(/"/g, '&quot;') + '" ' +
              'oninput="updateExecTaskField(' + activeExecPhaseIdx + ',' + tIdx + ',this.value)" ' +
              'style="flex:1;background:transparent;border:none;border-bottom:1px solid var(--border);padding:4px;font-size:15px;font-weight:700;color:var(--cream);" ' +
              'placeholder="Activity name...">' +
            '<button onclick="removeTaskFromPhase(' + activeExecPhaseIdx + ',' + tIdx + ')" ' +
              'style="background:none;border:none;color:var(--red);cursor:pointer;font-size:16px;opacity:0.6;">&#10005;</button>' +
          '</div>' +
          '<div style="padding-left:18px;display:flex;flex-wrap:wrap;gap:4px;">' + chipsHtml + '</div>' +
        '</div>';
      }).join('');

  var agendaSection = '';
  if (p.id === 'execution') {
    var _evTimeRange = typeof getResdEventTimeRange === 'function' ? getResdEventTimeRange(res) : { start: p.start, end: p.end };
    var anchorRow = function(time12, label) {
      return '<div style="background:rgba(212,175,55,0.06); border:1px solid rgba(212,175,55,0.3); border-radius:10px; padding:12px 15px; display:flex; align-items:center; gap:12px;">' +
        '<span style="font-size:15px; color:var(--gold); font-weight:800; min-width:80px; letter-spacing:0.5px;">' + time12 + '</span>' +
        '<span style="font-size:15px; color:var(--cream); font-style:italic; font-weight:600;">' + label + '</span>' +
      '</div>';
    };

    var _pAgenda = p.agenda;
    if ((!_pAgenda || _pAgenda.length === 0) && res && res.executionPlan && res.executionPlan.phases) {
      var _fbExecPhase = res.executionPlan.phases.find(function(xp) { return xp.id === 'execution'; });
      if (_fbExecPhase && _fbExecPhase.agenda && _fbExecPhase.agenda.length > 0) {
        _pAgenda = _fbExecPhase.agenda;
        p.agenda = _pAgenda;
      }
    }

    var agItems = (_pAgenda || []).map(function(a, aIdx) {
      var displayTime = fmt12(a.time || _evTimeRange.start);
      return '<div style="background:rgba(255,255,255,0.03); border:1px solid var(--border); border-radius:10px; padding:12px 15px; display:flex; align-items:center; gap:12px; flex-wrap:wrap;">' +
        '<div style="display:flex; flex-direction:column; align-items:center; gap:2px; min-width:90px;">' +
          '<span style="font-size:12px; color:var(--text-dim); text-transform:uppercase; letter-spacing:0.5px;">Time</span>' +
          '<input type="time" value="' + (a.time || _evTimeRange.start || '') + '" ' +
            'onchange="updateExecAgendaTime(' + activeExecPhaseIdx + ',' + aIdx + ',this.value)" ' +
            'style="background:rgba(0,0,0,0.2); border:1px solid var(--border); color:var(--gold); padding:4px 6px; border-radius:6px; font-size:14px; font-weight:700; width:100%;">' +
          '<span style="font-size:12px; color:var(--gold); margin-top:2px;">' + displayTime + '</span>' +
        '</div>' +
        '<select onchange="updateExecAgendaType(' + activeExecPhaseIdx + ',' + aIdx + ',this.value)" ' +
          'style="background:rgba(0,0,0,0.2); border:1px solid var(--border); color:var(--cream); padding:5px 8px; border-radius:6px; font-size:14px; width:100px;">' +
          ['Arrival','Program','Catering','Buffer','Custom'].map(function(type) {
            return '<option value="' + type + '"' + (a.type === type || (!a.type && type === 'Custom') ? ' selected' : '') + '>' + type + '</option>';
          }).join('') +
        '</select>' +
        '<div style="flex:1; display:flex; flex-direction:column; gap:6px;">' +
          '<input type="text" value="' + (a.text || '').replace(/"/g, '&quot;') + '" ' +
            'oninput="updateExecAgendaField(' + activeExecPhaseIdx + ',' + aIdx + ',this.value)" ' +
            'style="background:transparent; border:none; border-bottom:1px solid var(--border); padding:4px; font-size:15px; font-weight:700; color:var(--cream); width:100%;" placeholder="Enter agenda activity details...">' +
        '</div>' +
        '<button onclick="removeAgendaFromPhase(' + activeExecPhaseIdx + ',' + aIdx + ')" ' +
          'style="background:none; border:none; color:var(--red); font-size:18px; cursor:pointer; opacity:0.7; padding:4px;">&times;</button>' +
      '</div>';
    }).join('');

    agendaSection = '<div style="margin-top:30px;border-top:1px solid rgba(255,255,255,0.08);padding-top:24px;">' +
      '<div style="font-size:14px; color:var(--gold); font-weight:800; text-transform:uppercase; margin-bottom:10px;">Execution Agenda (Event Program Flow)</div>' +
      '<div style="display:flex;flex-direction:column;gap:8px;">' +
        anchorRow(fmt12(_evTimeRange.start), 'Beginning of Event') +
        agItems +
        anchorRow(fmt12(_evTimeRange.end), 'End of Event') +
        '<button onclick="addAgendaToPhase(' + activeExecPhaseIdx + ')" ' +
          'style="background:rgba(255,255,255,0.02);border:1px dashed var(--border);color:var(--gold);border-radius:10px;padding:14px;font-size:14px;cursor:pointer;font-weight:600;margin-top:8px;">+ Add Item</button>' +
      '</div></div>';
  }

  var detailHtml =
    '<div style="background:var(--bg3);border:1px solid var(--border);border-left:4px solid ' + accent + ';border-radius:12px;padding:24px;">' +
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px;padding-bottom:16px;border-bottom:1px solid var(--border);flex-wrap:wrap;gap:10px;">' +
        '<div>' +
          '<div style="font-size:12px;color:' + accent + ';text-transform:uppercase;font-weight:800;letter-spacing:1px;margin-bottom:4px;">Current Phase</div>' +
          '<div style="font-size:24px;font-weight:800;color:var(--cream);text-transform:uppercase;">' + p.name + '</div>' +
        '</div>' +
        '<div style="display:flex;gap:12px;align-items:center;flex-wrap:wrap;">' +
          '<div>' +
            '<div style="font-size:12px;color:var(--text-dim);margin-bottom:4px;">Start</div>' +
            mkTimeInput('start', p.start) +
          '</div>' +
          '<div style="color:var(--text-dim);align-self:flex-end;padding-bottom:6px;">&rarr;</div>' +
          '<div>' +
            '<div style="font-size:12px;color:var(--text-dim);margin-bottom:4px;">End</div>' +
            mkTimeInput('end', p.end) +
          '</div>' +
          (locked ? '<div style="font-size:12px;color:var(--text-dim);background:rgba(34,197,94,0.08);border:1px solid rgba(34,197,94,0.3);padding:6px 12px;border-radius:6px;white-space:nowrap;">Locked &mdash; change via reservation time range</div>' : '') +
        '</div>' +
      '</div>' +
      '<div style="font-size:13px;color:var(--text-dim);text-transform:uppercase;font-weight:700;letter-spacing:0.5px;margin-bottom:14px;">Activities &amp; Staff Assignment</div>' +
      tasksHtml +
      '<button onclick="addTaskToPhase(' + activeExecPhaseIdx + ')" ' +
        'style="width:100%;background:rgba(255,255,255,0.02);border:1px dashed var(--border);color:var(--gold);border-radius:10px;padding:14px;font-size:14px;cursor:pointer;margin-top:4px;font-weight:600;">+ Add Activity to ' + p.name + '</button>' +
      agendaSection +
    '</div>';

  container.innerHTML = tabsHtml + detailHtml;
}


window.selectExecPhase = function (idx) {
  activeExecPhaseIdx = idx;
  renderExecutionPlannerPhases();
};

window.updateExecPhaseField = function (pIdx, field, val) {
  const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(function (r) {
    return r.id === activeResDetailId || String(r.id) === String(activeResDetailId);
  });
  if (res && res.executionPlan && res.executionPlan.phases[pIdx]) {
    const phases = res.executionPlan.phases;
    if (phases[pIdx].locked) return;
    phases[pIdx][field] = val;

    const phaseId = phases[pIdx].id;

    // Domino Effect: strictly link adjacent phases
    if (phaseId === 'departure' && field === 'end') {
      const next = phases.find(p => p.id === 'deployment');
      if (next) next.start = val;
    }
    if (phaseId === 'deployment' && field === 'start') {
      const prev = phases.find(p => p.id === 'departure');
      if (prev) prev.end = val;
    }
    
    // In case deployment end was manually changed (even though soft-locked in UI):
    if (phaseId === 'deployment' && field === 'end') {
      const next = phases.find(p => p.id === 'execution');
      if (next && !next.locked) next.start = val;
    }
    
    if (phaseId === 'bashout' && field === 'end') {
      const next = phases.find(p => p.id === 'restorage');
      if (next) next.start = val;
    }
    if (phaseId === 'restorage' && field === 'start') {
      const prev = phases.find(p => p.id === 'bashout');
      if (prev) prev.end = val;
    }

    // Always enforce boundaries around the Execution (locked) phase
    const exe = phases.find(p => p.id === 'execution');
    const dep = phases.find(p => p.id === 'deployment');
    const bash = phases.find(p => p.id === 'bashout');
    if (exe && dep) dep.end = exe.start;
    if (exe && bash) bash.start = exe.end;

    renderExecutionTimelineVisual();
    if (typeof renderExecutionPlannerPhases === 'function') renderExecutionPlannerPhases();
  }
};

window.updateExecFlexibility = function (val) {
  const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(function (r) {
    return r.id === activeResDetailId || String(r.id) === String(activeResDetailId);
  });
  if (res && res.executionPlan) {
    res.executionPlan.flexibility = val;
    renderExecutionPlannerPhases();
  }
};

window.updateExecTaskField = function (pIdx, tIdx, val) {
  const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(function (r) {
    return r.id === activeResDetailId || String(r.id) === String(activeResDetailId);
  });
  if (res && res.executionPlan && res.executionPlan.phases[pIdx]) {
    const task = res.executionPlan.phases[pIdx].tasks[tIdx];
    if (task) task.text = val;
  }
};

function renderExecutionTimelineVisual() {
  var container = document.getElementById('exec-planner-visual-blocks');
  if (!container) return;

  var res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(function(r) {
    return r.id === activeResDetailId || String(r.id) === String(activeResDetailId);
  });
  if (!res || !res.executionPlan || !Array.isArray(res.executionPlan.phases)) return;

  function timeToPercent(t) {
    if (!t || typeof t !== 'string' || !t.includes(':')) return 0;
    var p = t.split(':').map(Number);
    return Math.min(100, Math.max(0, ((p[0]*60 + p[1]) / 1440) * 100));
  }

  var colors = {
    departure:  'rgba(196,154,60,0.75)',
    deployment: 'rgba(59,130,246,0.75)',
    execution:  'rgba(34,197,94,0.9)',
    bashout:    'rgba(239,68,68,0.75)',
    restorage:  'rgba(168,85,247,0.75)'
  };

  container.innerHTML = res.executionPlan.phases.map(function(p) {
    if (!p.start || !p.end) return '';
    var left  = timeToPercent(p.start);
    var right = timeToPercent(p.end);
    var width = right > left ? right - left : Math.max(2, 100 - left);
    var color = colors[p.id] || 'rgba(255,255,255,0.4)';
    return '<div style="position:absolute;left:' + left + '%;width:' + width + '%;height:100%;background:' + color + ';border-right:1px solid rgba(255,255,255,0.15);" title="' + p.name + ': ' + p.start + ' \u2013 ' + p.end + '"></div>';
  }).join('');
}

function toggleStaffInTask(pIdx, tIdx, staffId) {
  const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(function (r) {
    return r.id === activeResDetailId || String(r.id) === String(activeResDetailId);
  });
  if (!res || !res.executionPlan || !res.executionPlan.phases) return;

  const phase = res.executionPlan.phases[pIdx];
  if (!phase) return;
  const task = phase.tasks[tIdx];
  if (!task) return;

  if (!task.staffIds) task.staffIds = [];

  const idx = task.staffIds.indexOf(staffId);
  if (idx === -1) {
    task.staffIds.push(staffId);
  } else {
    task.staffIds.splice(idx, 1);
  }

  renderExecutionPlannerPhases();
}

function addTaskToPhase(pIdx) {
  const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(function (r) {
    return r.id === activeResDetailId || String(r.id) === String(activeResDetailId);
  });
  if (!res || !res.executionPlan || !res.executionPlan.phases) return;
  res.executionPlan.phases[pIdx].tasks.push({ text: 'New Activity', staffIds: [] });
  renderExecutionPlannerPhases();
}

function removeTaskFromPhase(pIdx, tIdx) {
  const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(function (r) {
    return r.id === activeResDetailId || String(r.id) === String(activeResDetailId);
  });
  if (!res || !res.executionPlan || !res.executionPlan.phases) return;
  res.executionPlan.phases[pIdx].tasks.splice(tIdx, 1);
  renderExecutionPlannerPhases();
}

window.toggleStaffInTask = toggleStaffInTask;
window.addTaskToPhase = addTaskToPhase;
window.removeTaskFromPhase = removeTaskFromPhase;

function autoAllocateStaffToPhases() {
  const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(function (r) {
    return r.id === activeResDetailId || String(r.id) === String(activeResDetailId);
  });
  if (!res || !res.executionPlan) return;

  const assignments = (res.staffing && res.staffing.assignments) || [];
  if (assignments.length === 0) {
    alert("No staff assigned to this event in 'Staff Allocation'.");
    return;
  }

  // Clear existing task-level staff
  res.executionPlan.phases.forEach(p => {
    p.tasks.forEach(t => t.staffIds = []);
  });

  // Smart & Even Distribution
  res.executionPlan.phases.forEach(p => {
    const tasks = p.tasks;
    if (tasks.length === 0) return;

    // Distribute staff across tasks
    assignments.forEach((a, aIdx) => {
      const name = a.staffName.toLowerCase();

      // Specific priority logic for Bolesa and Transport team
      let assignedToSpecific = false;
      tasks.forEach(t => {
        const txt = (t.text || '').toLowerCase();
        if (txt.includes('count equipment') && name.includes('bolesa')) {
          t.staffIds.push(a.staffId);
          assignedToSpecific = true;
        }
        if (txt.includes('load transport') && (name.includes('jake') || name.includes('comedia') || name.includes('martin') || name.includes('ecoy'))) {
          t.staffIds.push(a.staffId);
          assignedToSpecific = true;
        }
      });

      if (!assignedToSpecific) {
        // Round robin distribution for others
        const tIdx = aIdx % tasks.length;
        if (!tasks[tIdx].staffIds.includes(a.staffId)) {
          tasks[tIdx].staffIds.push(a.staffId);
        }
      }
    });

    // Ensure no task is left empty if staff exist
    tasks.forEach(t => {
      if (t.staffIds.length === 0 && assignments.length > 0) {
        // Pick the least busy staff or just first one
        t.staffIds.push(assignments[0].staffId);
      }
    });
  });

  renderExecutionPlannerPhases();
  showToast("Staff distributed evenly across all activities.");
}

function forceLogout() {
  localStorage.clear();
  sessionStorage.clear();
  window.location.href = 'index.html';
}

function checkSessionExpiry(error) {
  if (error && (error.code === '42501' || error.code === 'PGRST301' || (error.message && error.message.includes('JWT')))) {
    const overlay = document.getElementById('session-expired-overlay');
    if (overlay) overlay.style.display = 'flex';
    return true;
  }
  return false;
}
async function saveExecutionPlan() {
  const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(function (r) {
    return r.id === activeResDetailId || String(r.id) === String(activeResDetailId);
  });
  if (!res || !res.executionPlan) return;

  const flexEl = document.getElementById('exec-planner-flexibility');
  if (flexEl) res.executionPlan.flexibility = flexEl.value;

  // Show saving indicator
  const saveBtn = document.querySelector('button[onclick="saveExecutionPlan()"]');
  if (saveBtn) { saveBtn.textContent = 'Saving...'; saveBtn.disabled = true; }

  try {
    if (!window.supabaseClient) throw new Error('Supabase not available');

    // Upsert to execution_plans table
    const payload = {
      reservation_id: res.id,
      phases:         res.executionPlan.phases,
      flexibility:    res.executionPlan.flexibility || 'strict',
      updated_at:     new Date().toISOString()
    };

    const { error } = await window.supabaseClient
      .from('execution_plans')
      .upsert(payload, { onConflict: 'reservation_id' });

    if (error) throw error;

    // Also persist to Firebase as backup (if available)
    try {
      if (window.firebaseFns && window.firebaseDB) {
        const { updateDoc, doc } = window.firebaseFns;
        await updateDoc(doc(window.firebaseDB, 'reservations', res.id), {
          executionPlan: res.executionPlan
        });
      }
    } catch (fbErr) { console.warn('Firebase backup save skipped:', fbErr); }

    if (typeof showToast === 'function') showToast('Execution Plan saved to Supabase.');
    else alert('Execution Plan saved successfully.');
    closeExecutionPlanner();

  } catch (e) {
    console.error('Failed to save Execution Plan:', e);
    alert('Error saving Execution Plan: ' + (e.message || e));
  } finally {
    if (saveBtn) { saveBtn.textContent = 'Save Execution Plan'; saveBtn.disabled = false; }
  }
}

async function autoAssignStaffToRes() {
  const res = RESERVATIONS.find(r => r.id === activeResDetailId);
  if (!res) return;

  try {
    const { updateDoc, doc, collection, getDocs, query, where } = window.firebaseFns;
    const db = window.firebaseDB;

    // Fetch all staff
    const staffQuery = query(collection(db, 'users'), where('role', '==', 'staff'));
    const staffSnap = await getDocs(staffQuery);
    const allStaff = [];
    staffSnap.forEach(d => {
      allStaff.push({ id: d.id, ...d.data() });
    });

    // Busy staff
    const otherRes = RESERVATIONS.filter(d => d.date === res.date && d.id !== res.id);
    const busyStaffIds = new Set();
    otherRes.forEach(r => {
      if (r.staffing && r.staffing.assignments) {
        r.staffing.assignments.forEach(a => busyStaffIds.add(a.staffId));
      }
    });

    const available = allStaff.filter(s => !busyStaffIds.has(s.id));
    const autoPick = available.slice(0, 6);

    if (autoPick.length === 0) {
      alert("No available staff found for this date.");
      return;
    }

    const currentStaffing = res.staffing || { assignments: [], groups: [] };
    const newAssignments = autoPick.map(s => ({ staffId: s.id, staffName: s.name || s.email, task: 'General Support', group: 'Floor' }));

    // Replace current assignments to start fresh
    currentStaffing.assignments = newAssignments;

    await updateDoc(doc(db, 'reservations', res.id), { staffing: currentStaffing });
    res.staffing = currentStaffing;
    renderStaffAllocationTab();
  } catch (e) {
    console.error(e);
    alert("Error auto-assigning staff.");
  }
}

async function clearAllStaffAssignments() {
  const res = RESERVATIONS.find(r => r.id === activeResDetailId);
  if (!res) return;
  if (!confirm("Are you sure you want to clear all staff assignments for this reservation?")) return;

  try {
    const { updateDoc, doc } = window.firebaseFns;
    const staffing = { assignments: [], groups: [] };
    await updateDoc(doc(window.firebaseDB, 'reservations', res.id), { staffing: staffing });
    res.staffing = staffing;
    renderStaffAllocationTab();
  } catch (e) {
    console.error(e);
    alert("Error clearing assignments.");
  }
}

window.autoAssignStaffToRes = autoAssignStaffToRes;
window.clearAllStaffAssignments = clearAllStaffAssignments;
window.toggleStaffInPhase = toggleStaffInTask; // Providing alias for UI backward compatibility
window.autoAllocateStaffToPhases = autoAllocateStaffToPhases;


