// ── Execution Strategy Done Check ────────────────────────────────
function isExecStrategyDone(res, execStrategyData) {
  const plan = (res && res.executionPlan) || execStrategyData;
  if (!plan) return false;
  let phases = [];
  if (Array.isArray(plan.phases)) phases = plan.phases;
  else if (typeof plan.phases === 'string') {
    try { phases = JSON.parse(plan.phases); } catch(e) { phases = []; }
  }
  if (!phases || phases.length === 0) return false;
  return phases.some(p => p && (p.name || p.start || p.end || (Array.isArray(p.tasks) && p.tasks.length)));
}


