// ── Universal 12-Hour AM/PM Time Formatter ─────────────────────────
function formatTime12h(timeStr) {
  if (!timeStr) return '';
  timeStr = String(timeStr).trim();
  if (!timeStr || timeStr === ':' || timeStr === '--:--') return '';
  if (timeStr.includes(' - ') || timeStr.includes(' - ') || timeStr.includes(' to ')) {
    const sep = timeStr.includes(' - ') ? ' - ' : (timeStr.includes(' to ') ? ' to ' : ' - ');
    return timeStr.split(sep).map(t => formatTime12h(t.trim())).join(' - ');
  }
  if (/am|pm/i.test(timeStr)) return timeStr;
  const match = timeStr.match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);
  if (!match) return timeStr;
  let hh = parseInt(match[1], 10);
  const mm = match[2];
  const ampm = hh >= 12 ? 'PM' : 'AM';
  hh = hh % 12 || 12;
  return `${hh}:${mm} ${ampm}`;
}
window.formatTime12h = formatTime12h;

