// ── Personnel & Driver Name Resolution Cache ─────────────────────────────
window._personnelNameMap = window._personnelNameMap || {};

async function ensurePersonnelNameMap() {
  if (!window._personnelNameMap) window._personnelNameMap = {};
  const defaultDrivers = [
    { id: 'd1', full_name: 'Rodrigo "Rody" Dalisay' },
    { id: 'd2', full_name: 'Marco Antonio Santos' },
    { id: 'd3', full_name: 'Juan Carlo Reyes' },
    { id: 'd4', full_name: 'Ernesto "Ka Erning" Cruz' }
  ];
  defaultDrivers.forEach(d => {
    window._personnelNameMap[d.id] = d.full_name;
  });

  if (window.supabaseClient) {
    try {
      const { data } = await window.supabaseClient.from('personnel').select('*');
      if (data && data.length > 0) {
        data.forEach(p => {
          const name = p.full_name || p.name || p.email || 'Personnel';
          if (p.id) window._personnelNameMap[p.id] = name;
          if (p.email) window._personnelNameMap[p.email.toLowerCase()] = name;
        });
      }
    } catch(e) {}
    try {
      const { data: uData } = await window.supabaseClient.from('users').select('id, name, email');
      if (uData && uData.length > 0) {
        uData.forEach(u => {
          const name = u.name || u.email;
          if (u.id && !window._personnelNameMap[u.id]) window._personnelNameMap[u.id] = name;
          if (u.email && !window._personnelNameMap[u.email.toLowerCase()]) window._personnelNameMap[u.email.toLowerCase()] = name;
        });
      }
    } catch(e) {}
  }
  return window._personnelNameMap;
}
window.ensurePersonnelNameMap = ensurePersonnelNameMap;

function resolvePersonnelName(keyOrEmail) {
  if (!keyOrEmail) return '';
  const s = String(keyOrEmail).trim();
  if (window._personnelNameMap) {
    if (window._personnelNameMap[s]) return window._personnelNameMap[s];
    if (window._personnelNameMap[s.toLowerCase()]) return window._personnelNameMap[s.toLowerCase()];
  }
  return s;
}
window.resolvePersonnelName = resolvePersonnelName;

// ── Live Execution Panel ───────────────────────────────────────────
async function openExecLivePanel(resId) {
  await ensurePersonnelNameMap();
  const res = RESERVATIONS.find(r => r.id === resId);
  if (!res) return;
  activeExecDayResId = resId;
  execLiveLogEntries = [];
  execLiveActivities = [];
  
  if (window.supabaseClient) {
    try {
      const { data: planData } = await window.supabaseClient.from('execution_plans').select('*').eq('reservation_id', resId).maybeSingle();
      if (planData && planData.phases) {
        res.executionPlan = {
          flexibility: planData.flexibility || 'strict',
          phases: Array.isArray(planData.phases) ? planData.phases : JSON.parse(planData.phases)
        };
      }
    } catch (e) {
      console.warn('Failed to load execution_plans in live panel:', e);
    }

    if (!window._lastActiveExecPlan) window._lastActiveExecPlan = {};
    if (res.executionPlan) {
      window._lastActiveExecPlan[resId] = res.executionPlan;
    } else if (window._lastActiveExecPlan[resId]) {
      res.executionPlan = window._lastActiveExecPlan[resId];
    }

    try {
      const { data: ard } = await window.supabaseClient.from('additional_reservation_details')
        .select('event_flow')
        .eq('reservation_id', resId)
        .maybeSingle();
      if (ard && Array.isArray(ard.event_flow) && ard.event_flow.length > 0) {
        if (!res.executionPlan) res.executionPlan = { phases: [] };
        if (!res.executionPlan.phases) res.executionPlan.phases = [];
        let execPhase = res.executionPlan.phases.find(p => p.id === 'execution');
        if (execPhase) {
          execPhase.agenda = ard.event_flow;
        }
      }
    } catch (e) {
      console.warn('Failed to load additional_reservation_details in live panel:', e);
    }
  }
  
  execLiveActivePhaseIdx = 0;

  const overlay = document.getElementById('exec-live-overlay');
  if (overlay) overlay.style.display = 'flex';
  document.body.style.overflow = 'hidden';
  setExecDayHash(resId);

  // Broadcast active execution session to Supabase so customer portal sees session started
  if (window.supabaseClient) {
    try {
      window.supabaseClient.from('reservations').update({
        status: 'on-going',
        ops_status: 'on-going',
        execution_live_status: 'active'
      }).eq('id', resId).then(() => {});
    } catch(e) {}
  }
  res.status = 'on-going';
  res.ops_status = 'on-going';
  res.execution_live_status = 'active';

  const pkgDisplay = res.packageName || res.type || '';
  const titleEl = document.getElementById('exec-live-title');
  if (titleEl) titleEl.textContent = (pkgDisplay ? pkgDisplay + ' \u2013 ' : '') + (res.client || 'Client') + "'s Event";
  const subEl = document.getElementById('exec-live-subtitle');
  if (subEl) subEl.textContent = (res.date || '—') + ' · ' + (formatTime12h(res.time) || '—') + ' · ' + (res.venue || '—');

  const noteEl = document.getElementById('exec-live-status-note');
  if (noteEl) noteEl.value = res.statusNote || '';

  // Close chat drawer initially
  execLiveChatOpen = false;
  document.getElementById('exec-live-chat-drawer').style.right = '-420px';
  initExecLiveChat(res);
  toggleExecMobileLiveSidebar(false);
  setTimeout(() => {
    if (typeof execLiveMap !== 'undefined' && execLiveMap && typeof execLiveMap.invalidateSize === 'function') {
      execLiveMap.invalidateSize();
    }
  }, 350);

  
  // ── Populate Assigned Staff + Transportation + Personnel ─────────────
  const staffListContainer = document.getElementById('exec-live-staff-list');
  if (staffListContainer) {
    staffListContainer.innerHTML = '<div style="font-size:11px;color:var(--text-dim);">Loading...</div>';
    try {
      // Defaults for missing data
      const defaultDrivers = [
        { id: 'd1', full_name: 'Rodrigo "Rody" Dalisay', contact_number: '+63 917 555 1024', rate: 2500, description: 'Senior Logistics Driver - 10-Wheeler & Cold Chain' },
        { id: 'd2', full_name: 'Marco Antonio Santos', contact_number: '+63 920 888 4192', rate: 2000, description: 'Catering Van Driver - Fragile Decor Specialist' },
        { id: 'd3', full_name: 'Juan Carlo Reyes', contact_number: '+63 918 333 7711', rate: 1800, description: 'Express Delivery & Light Equipment Driver' },
        { id: 'd4', full_name: 'Ernesto "Ka Erning" Cruz', contact_number: '+63 929 444 9900', rate: 2200, description: 'Heavy Equipment Transporter & Mobile Kitchen Rig Driver' }
      ];

      // Fetch the latest reservation extra details
      let sbDriverId = res.transportationDriverId || res.transportation_driver_id || res.driverId;
      let sbHiredPersonnel = res.hiredPersonnel || res.hired_personnel || {};
      
      if (window.supabaseClient) {
        try {
          const { data: sbResData } = await window.supabaseClient.from('reservations').select('transportation_driver_id, hired_personnel').eq('id', resId).maybeSingle();
          if (sbResData) {
            if (sbResData.transportation_driver_id) sbDriverId = sbResData.transportation_driver_id;
            if (sbResData.hired_personnel) sbHiredPersonnel = typeof sbResData.hired_personnel === 'string' ? JSON.parse(sbResData.hired_personnel) : sbResData.hired_personnel;
          }
        } catch(e) { /* silent fail for uuid mismatch */ }
      }

      // 1. Fetch staff assignments
      let assignmentsData = [];
      if (window.supabaseClient) {
        try {
          const { data } = await window.supabaseClient.from('reservation_staff_assignments').select('staff_id, roles').eq('reservation_id', resId);
          if (data) assignmentsData = data;
        } catch(e) {}
      }

      // 2. Resolve normal staff names using direct Supabase query bypassing filters
      let staffHtml = '<div style="font-size:11px;color:var(--text-dim);font-style:italic;">No staff assigned</div>';
      if (assignmentsData && assignmentsData.length > 0) {
        const staffIds = assignmentsData.map(d => d.staff_id);
        const nameMap = {};
        
        // Try Firebase first since it has no RLS!
        const fns = window.firebaseFns || window.firebaseFirestore;
        if (window.firebaseDB && fns && fns.collection) {
          try {
            const { collection, getDocs, query, where } = fns;
            const usersRef = collection(window.firebaseDB, 'users');
            // Firestore 'in' query supports up to 10 items
            for (let i = 0; i < staffIds.length; i += 10) {
              const chunk = staffIds.slice(i, i + 10);
              const q = query(usersRef, where("id", "in", chunk));
              const snap = await getDocs(q);
              snap.forEach(doc => {
                const d = doc.data();
                nameMap[d.id] = { name: d.name || d.full_name || (d.fname ? d.fname + ' ' + (d.lname||'') : ''), email: d.email, phone: d.phone };
              });
            }
          } catch(e) { console.warn("Firebase users fetch failed", e); }
        }

        // Try Supabase as backup if missing names
        if (window.supabaseClient) {
          try {
            const missingIds = staffIds.filter(id => !nameMap[id]);
            if (missingIds.length > 0) {
              const { data: suData } = await window.supabaseClient.from('users').select('id, name, email, phone').in('id', missingIds);
              if (suData) {
                suData.forEach(u => { nameMap[u.id] = u; });
              }
            }
          } catch(e) {}
        }
        
        // Fallback to window.allStaff
        (window.allStaff || []).forEach(s => { 
          if (!nameMap[s.id]) nameMap[s.id] = s; 
        });

        const assignments = assignmentsData.map(d => {
          const matched = nameMap[d.staff_id] || {};
          return {
            staffId: d.staff_id,
            staffName: matched.name || d.staff_id,
            email: matched.email || '',
            phone: matched.phone || '',
            roles: Array.isArray(d.roles) ? d.roles : (d.roles ? JSON.parse(d.roles) : [])
          };
        });
        
        if (!res.staffing) res.staffing = {};
        res.staffing.assignments = assignments;
        window._activeExecStaffAssignments = assignments;

        staffHtml = assignments.map(a => {
          const roles = a.roles.length ? a.roles.join(', ') : 'Assigned';
          return `<div style="background:var(--bg3);border:1px solid var(--border);border-left:2px solid var(--gold);border-radius:6px;padding:8px 10px;margin-bottom:6px;">
            <div style="font-size:12px;color:var(--cream);font-weight:700;">${escHtml(a.staffName)}</div>
            <div style="font-size:10px;color:var(--gold);margin-top:1px;">${escHtml(roles)}</div>
            ${a.email ? `<div style="font-size:10px;color:var(--text-dim);margin-top:2px;">&#9993; ${escHtml(a.email)}</div>` : ''}
            ${a.phone ? `<div style="font-size:10px;color:var(--text-dim);">&#9742; ${escHtml(a.phone)}</div>` : ''}
          </div>`;
        }).join('');
      }

      // 3. Fetch driver/transportation
      let transHtml = '';
      if (sbDriverId) {
        let dn = 'Driver', dEmail = '', dPhone = '';
        const defMatch = defaultDrivers.find(d => d.id === sbDriverId);
        
        if (defMatch) {
          dn = defMatch.full_name;
          dPhone = defMatch.contact_number;
        } else if (window.supabaseClient) {
          try {
            const { data: driverData } = await window.supabaseClient.from('personnel').select('*').eq('id', sbDriverId).maybeSingle();
            if (driverData) {
              dn = driverData.full_name || driverData.name || 'Driver';
              dEmail = driverData.email || '';
              dPhone = driverData.contact_number || driverData.phone || '';
            }
          } catch(e) {}
        }
        res._resolvedDriverName = dn;
        if (sbDriverId) window._personnelNameMap[sbDriverId] = dn;
        const isLalamove = sbDriverId === 'Lalamove' || dn === 'Lalamove';
        const savedLalaPrice = (res && res.lalamove_price) || '';
        transHtml = `<div style="margin-top:10px;">
          <div style="font-size:9px;letter-spacing:2px;text-transform:uppercase;color:var(--text-dim);margin-bottom:6px;">Transportation</div>
          <div style="background:var(--bg3);border:1px solid var(--border);border-left:2px solid #3b82f6;border-radius:6px;padding:8px 10px;">
            <div style="font-size:12px;color:var(--cream);font-weight:700;">${escHtml(dn)}</div>
            <div style="font-size:10px;color:#3b82f6;margin-top:1px;">Driver / Transportation</div>
            ${dEmail ? `<div style="font-size:10px;color:var(--text-dim);margin-top:2px;">&#9993; ${escHtml(dEmail)}</div>` : ''}
            ${dPhone ? `<div style="font-size:10px;color:var(--text-dim);">&#9742; ${escHtml(dPhone)}</div>` : ''}
            ${isLalamove ? `
            <div style="margin-top:8px;padding-top:8px;border-top:1px solid rgba(255,255,255,0.08);">
              <div style="font-size:9px;color:#f59e0b;font-weight:700;text-transform:uppercase;letter-spacing:1px;margin-bottom:5px;">Lalamove Price</div>
              <div style="display:flex;gap:6px;align-items:center;">
                <span style="font-size:12px;color:var(--text-dim);">₱</span>
                <input type="number" id="exec-lalamove-price-input" placeholder="Enter amount" value="${escHtml(String(savedLalaPrice))}" min="0"
                  style="flex:1;padding:5px 8px;border-radius:6px;border:1px solid var(--border);background:var(--bg);color:var(--cream);font-size:12px;" />
                <button onclick="saveLalamovePrice('${resId}')" style="padding:5px 10px;border-radius:6px;border:none;background:#2563eb;color:#ffffff;font-size:11px;font-weight:700;cursor:pointer;">Save</button>
              </div>
              ${savedLalaPrice ? `<div style="font-size:10px;color:#f59e0b;margin-top:4px;">Saved: ₱${Number(savedLalaPrice).toLocaleString()}</div>` : ''}
            </div>` : ''}
          </div>
        </div>`;
      }

      // 4. Fetch hired personnel
      let personnelHtml = '';
      const hiredEmails = Object.values(sbHiredPersonnel || {}).map(h => h.email).filter(Boolean);
      if (hiredEmails.length > 0 && window.supabaseClient) {
        try {
          const { data: persData } = await window.supabaseClient.from('personnel').select('*').in('email', hiredEmails);
          if (persData && persData.length > 0) {
            personnelHtml = `<div style="margin-top:10px;">
              <div style="font-size:9px;letter-spacing:2px;text-transform:uppercase;color:var(--text-dim);margin-bottom:6px;">Hired Personnel</div>
              ${persData.map(p => {
                const pn = p.full_name || p.name || p.email;
                if (p.id) window._personnelNameMap[p.id] = pn;
                if (p.email) window._personnelNameMap[p.email.toLowerCase()] = pn;
                return `<div style="background:var(--bg3);border:1px solid var(--border);border-left:2px solid var(--green);border-radius:6px;padding:8px 10px;margin-bottom:6px;">
                  <div style="font-size:12px;color:var(--cream);font-weight:700;">${escHtml(pn)}</div>
                  <div style="font-size:10px;color:var(--green);margin-top:1px;">${escHtml(p.service_type || 'Personnel')}</div>
                  ${p.email ? `<div style="font-size:10px;color:var(--text-dim);margin-top:2px;">&#9993; ${escHtml(p.email)}</div>` : ''}
                  ${(p.contact_number||p.phone) ? `<div style="font-size:10px;color:var(--text-dim);">&#9742; ${escHtml(p.contact_number||p.phone)}</div>` : ''}
                </div>`;
              }).join('')}
            </div>`;
          }
        } catch(e) {}
      }

      staffListContainer.innerHTML = staffHtml + transHtml + personnelHtml;
    } catch (e) {
      console.warn('Failed to load staff/personnel:', e);
      staffListContainer.innerHTML = '<div style="font-size:11px;color:var(--text-dim);font-style:italic;">Could not load staff data.</div>';
    }
  }


  switchExecLiveView('departure');

  renderExecLivePhases(res);
  addExecLiveLog('active', 'Execution Day started');

  // Init map with venue
  setTimeout(() => initExecLiveMap(res), 400);
}

function stopExecLive() {
  openEndExecutionUI();
}
window.stopExecLive = stopExecLive;

// ── Map Circle Indicators ─────────────────────────────────────────
