// ── Execution Agenda in Reservation Details / Meeting Hub ──
// Helper: get current event time range from meeting context or reservation
function getResdEventTimeRange(res) {
  if (typeof mtTimeStart !== 'undefined' && mtTimeStart) {
    return { start: mtTimeStart, end: mtTimeEnd || mtTimeStart };
  }
  if (res && res.time) {
    const _sep = res.time.toLowerCase().includes(' to ') ? / to /i : /-/;
    const parts = res.time.split(_sep).map(p => p.trim());
    if (parts.length >= 2) {
      const extractTime = (str) => {
        if (!str) return '12:00';
        if (/^\d{1,2}:\d{2}$/.test(str)) return str;
        const match = str.match(/(\d{1,2}):?(\d{2})?\s*(AM|PM|am|pm)?/i);
        if (!match) return '12:00';
        let h = parseInt(match[1]);
        const m = match[2] || '00';
        const ap = (match[3] || '').toUpperCase();
        if (ap === 'PM' && h < 12) h += 12;
        if (ap === 'AM' && h === 12) h = 0;
        return `${h.toString().padStart(2, '0')}:${m}`;
      };
      return { start: extractTime(parts[0]), end: extractTime(parts[parts.length - 1]) };
    }
  }
  return { start: '08:00', end: '17:00' };
}

window.renderResdAgenda = function (res) {
  const section = document.getElementById('resd-execution-agenda-section');
  const list = document.getElementById('resd-agenda-list');
  if (!section || !list) return;

  if (!res) {
    section.style.display = 'none';
    return;
  }

  const timeRange = getResdEventTimeRange(res);
  const evStart = timeRange.start;
  const evEnd = timeRange.end;
  const evStart12 = formatTime12h(evStart);
  const evEnd12 = formatTime12h(evEnd);

  if (!res.executionPlan || !res.executionPlan.phases) {
    list.innerHTML = `
      <div style="background:rgba(255,255,255,0.02); border:1px solid rgba(212,175,55,0.25); border-radius:10px; padding:12px 15px; display:flex; align-items:center; gap:12px; opacity:0.7;">
        <span style="font-size:12px; color:var(--gold); font-weight:700; min-width:80px;">${evStart12}</span>
        <span style="font-size:12px; color:var(--text-dim); font-style:italic;">Beginning of Event</span>
      </div>
      <div style="text-align:center; padding:20px; border:1px dashed var(--border); border-radius:12px; background:rgba(255,255,255,0.02); color:var(--text-dim); font-size:13px;">
        No Execution Agenda found. Click Initialize to set up the event flow.
      </div>
      <div style="background:rgba(255,255,255,0.02); border:1px solid rgba(212,175,55,0.25); border-radius:10px; padding:12px 15px; display:flex; align-items:center; gap:12px; opacity:0.7;">
        <span style="font-size:12px; color:var(--gold); font-weight:700; min-width:80px;">${evEnd12}</span>
        <span style="font-size:12px; color:var(--text-dim); font-style:italic;">End of Event</span>
      </div>
      <div style="text-align:center; margin-top:10px;">
        <button class="btn-primary" onclick="initAgendaFromResd('${res.id}')">Initialize Execution Flow</button>
      </div>
    `;
    section.style.display = 'block';
    return;
  }

  const pIdx = res.executionPlan.phases.findIndex(p => p.id === 'execution');
  if (pIdx === -1) {
    section.style.display = 'none';
    return;
  }

  const p = res.executionPlan.phases[pIdx];
  p.start = evStart;
  p.end = evEnd;

  section.style.display = 'block';
  const agenda = p.agenda || [];

  const minTime = window.addMinutesToTime ? window.addMinutesToTime(evStart, 1) : evStart;
  const maxTime = window.addMinutesToTime ? window.addMinutesToTime(evEnd, -1) : evEnd;

  const anchorRow = (time12, label) => `
    <div style="background:rgba(212,175,55,0.06); border:1px solid rgba(212,175,55,0.3); border-radius:10px; padding:12px 15px; display:flex; align-items:center; gap:12px;">
      <span style="font-size:13px; color:var(--gold); font-weight:800; min-width:80px; letter-spacing:0.5px;">${time12}</span>
      <span style="font-size:13px; color:var(--cream); font-style:italic; font-weight:600;">${label}</span>
    </div>`;

  const itemRows = agenda.map((a, aIdx) => {
    const displayTime = formatTime12h(a.time || evStart);
    return `
    <div style="background:rgba(255,255,255,0.03); border:1px solid var(--border); border-radius:10px; padding:12px 15px; display:flex; align-items:center; gap:12px; flex-wrap:wrap;">
      <div style="display:flex; flex-direction:column; align-items:center; gap:2px; min-width:90px;">
        <span style="font-size:10px; color:var(--text-dim); text-transform:uppercase; letter-spacing:0.5px;">Time</span>
        <input type="time" value="${a.time || minTime}" min="${minTime}" max="${maxTime}"
               onchange="updateResdAgendaTime(${pIdx}, ${aIdx}, this.value)"
               style="background:rgba(0,0,0,0.2); border:1px solid var(--border); color:var(--gold); padding:4px 6px; border-radius:6px; font-size:11px; font-weight:700; width:100%;">
        <span style="font-size:10px; color:var(--gold); margin-top:2px;">${displayTime}</span>
      </div>
      <select onchange="updateResdAgendaType(${pIdx}, ${aIdx}, this.value)"
              style="background:rgba(0,0,0,0.2); border:1px solid var(--border); color:var(--cream); padding:5px 8px; border-radius:6px; font-size:12px; width:100px;">
        <option value="Arrival" ${a.type === 'Arrival' ? 'selected' : ''}>Arrival</option>
        <option value="Program" ${a.type === 'Program' ? 'selected' : ''}>Program</option>
        <option value="Catering" ${a.type === 'Catering' ? 'selected' : ''}>Catering</option>
        <option value="Buffer" ${a.type === 'Buffer' ? 'selected' : ''}>Buffer</option>
        <option value="Custom" ${a.type === 'Custom' || !a.type ? 'selected' : ''}>Custom</option>
      </select>
      <input type="text" value="${escHtml(a.text || '')}" oninput="updateResdAgendaField(${pIdx}, ${aIdx}, this.value)" class="input-field"
             style="padding:6px; font-size:13px; flex:1; min-width:150px; font-weight:600; background:transparent; border:none; border-bottom:1px solid var(--border); border-radius:0;" placeholder="Event activity...">
      <button onclick="removeAgendaFromPhase(${pIdx}, ${aIdx}); renderResdAgenda(RESERVATIONS.find(r=>r.id===activeResDetailId)); setEventFlowDirty(true);" style="background:none; border:none; color:var(--red); cursor:pointer; font-size:14px; opacity:0.6;">?</button>
    </div>`;
  }).join('');

  list.innerHTML = anchorRow(evStart12, 'Beginning of Event') + itemRows + anchorRow(evEnd12, 'End of Event');
};

window.addAgendaInResd = function () {
  let res = RESERVATIONS.find(r => r.id === activeResDetailId);
  if (!res) return;

  if (!res.executionPlan || !res.executionPlan.phases) {
    initAgendaFromResd(res.id);
    res = RESERVATIONS.find(r => r.id === activeResDetailId);
  }

  const pIdx = res.executionPlan.phases.findIndex(p => p.id === 'execution');
  if (pIdx === -1) return;
  const p = res.executionPlan.phases[pIdx];
  if (!p.agenda) p.agenda = [];

  const lastTime = p.agenda.length > 0 ? p.agenda[p.agenda.length - 1].time : p.start;
  const defaultTime = window.addMinutesToTime ? window.addMinutesToTime(lastTime || p.start, 30) : (lastTime || p.start);

  p.agenda.push({ text: 'New Agenda Item', time: defaultTime, type: 'Program' });
  renderResdAgenda(res);
  setEventFlowDirty(true);
};
window.updateResdAgendaTime = function (pIdx, aIdx, val) {
  updateExecAgendaTime(pIdx, aIdx, val);
  renderResdAgenda(RESERVATIONS.find(r => r.id === activeResDetailId));
  setEventFlowDirty(true);
};

window.updateResdAgendaType = function (pIdx, aIdx, val) {
  updateExecAgendaType(pIdx, aIdx, val);
  renderResdAgenda(RESERVATIONS.find(r => r.id === activeResDetailId));
  setEventFlowDirty(true);
};

window.saveAgendaInResd = async function () {
  const res = RESERVATIONS.find(r => r.id === activeResDetailId);
  if (!res) return;

  try {
    const { doc, updateDoc } = window.firebaseFns;
    await updateDoc(doc(window.firebaseDB, 'reservations', res.id), {
      executionPlan: res.executionPlan
    });
    showToast('Execution Agenda saved successfully!');
  } catch (err) {
    console.error(err);
    alert('Failed to save agenda.');
  }
};
window.updateResdAgendaField = function (pIdx, aIdx, val) {
  updateExecAgendaField(pIdx, aIdx, val);
  setEventFlowDirty(true);
};
window.initAgendaFromResd = function (resId) {
  const res = RESERVATIONS.find(r => r.id === resId);
  if (!res) return;

  const _trng = getResdEventTimeRange(res);
  const tStart = _trng.start || '08:00';
  const tEnd = _trng.end || '14:00';

  res.executionPlan = {
    flexibility: 'flexible',
    phases: [
      { id: 'departure', name: 'Departure', start: '05:00', end: '06:00', tasks: [{ text: 'Load transport & equipment', staffIds: [] }, { text: 'Depart confirmed', staffIds: [] }] },
      { id: 'deployment', name: 'Deployment', start: '06:00', end: tStart, tasks: [{ text: 'Venue dock check-in & unload', staffIds: [] }, { text: 'Setup tables & linens', staffIds: [] }, { text: 'Setup buffet & stations', staffIds: [] }, { text: 'Staff briefing', staffIds: [] }, { text: 'Deployment ready sign-off', staffIds: [] }] },
      { id: 'execution', name: 'Execution', start: tStart, end: tEnd, tasks: [{ text: 'Guest arrival & reception', staffIds: [] }, { text: 'Buffet & service monitoring', staffIds: [] }, { text: 'Manager floor walk', staffIds: [] }], agenda: [] },
      { id: 'bashout', name: 'Bashout', start: tEnd, end: '14:00', tasks: [{ text: 'Pack & inventory equipment', staffIds: [] }, { text: 'Venue sweep & cleanup', staffIds: [] }, { text: 'Load-out transport', staffIds: [] }] },
      { id: 'restorage', name: 'Restorage', start: '14:00', end: '15:00', tasks: [{ text: 'Return to office', staffIds: [] }, { text: 'Unload & inventory check', staffIds: [] }] }
    ]
  };
  renderResdAgenda(res);
};
window.addMinutesToTime = function (tStr, mins) {
  let [h, m] = tStr.split(':').map(Number);
  let total = h * 60 + m + mins;
  let nh = Math.floor(total / 60) % 24;
  let nm = total % 60;
  return `${nh.toString().padStart(2, '0')}:${nm.toString().padStart(2, '0')}`;
};

window.getTimeDiffMins = function (t1, t2) {
  let [h1, m1] = t1.split(':').map(Number);
  let [h2, m2] = t2.split(':').map(Number);
  return (h2 * 60 + m2) - (h1 * 60 + m1);
};
window.startExecLiveCountdownTimer = function () {
  if (window.execLiveCountdownInterval) clearInterval(window.execLiveCountdownInterval);

  const tick = () => {
    const res = RESERVATIONS.find(r => r.id === activeExecDayResId);
    if (!res || !res.executionPlan || !res.executionPlan.phases) return;
    const p = res.executionPlan.phases[execLiveActivePhaseIdx];
    if (!p) return;

    const now = new Date();
    const nowStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
    const diff = window.getTimeDiffMins(nowStr, p.end);

    const countdownEl = document.getElementById('exec-board-countdown');
    const detailCountdownEl = document.getElementById('exec-detail-countdown');

    let timeText = '';
    let isRed = diff < 15;

    if (diff > 0) {
      const h = Math.floor(diff / 60);
      const m = diff % 60;
      timeText = `${h > 0 ? h + 'h ' : ''}${m}m Remaining`;
    } else {
      timeText = 'OVERTIME';
      isRed = true;
    }

    if (countdownEl) {
      countdownEl.style.display = 'block';
      countdownEl.textContent = timeText;
      if (diff > 0) {
        countdownEl.style.color = isRed ? 'var(--red)' : 'var(--gold)';
        countdownEl.style.background = isRed ? 'rgba(239,68,68,0.1)' : 'rgba(196,154,60,0.1)';
        countdownEl.style.borderColor = isRed ? 'rgba(239,68,68,0.3)' : 'rgba(196,154,60,0.3)';
      } else {
        countdownEl.style.color = '#fff';
        countdownEl.style.background = 'var(--red)';
        countdownEl.style.borderColor = 'var(--red)';
      }
    }

    if (detailCountdownEl) {
      detailCountdownEl.style.display = 'inline';
      detailCountdownEl.textContent = '(' + timeText + ')';
      detailCountdownEl.style.color = isRed ? 'var(--red)' : 'var(--gold)';
    }
  };

  tick();
  window.execLiveCountdownInterval = setInterval(tick, 30000);
};

window.extendCurrentPhase = function (mins) {
  const res = RESERVATIONS.find(r => r.id === activeExecDayResId);
  if (!res || !res.executionPlan) return;

  if (!res.executionPlan.totalExtensionsAdded) res.executionPlan.totalExtensionsAdded = 0;
  res.executionPlan.totalExtensionsAdded += mins;

  const pIdx = execLiveActivePhaseIdx;
  const p = res.executionPlan.phases[pIdx];
  const newEnd = window.addMinutesToTime(p.end, mins);

  const oldId = activeResDetailId;
  activeResDetailId = res.id;
  window.updateExecPhaseField(pIdx, 'end', newEnd);
  activeResDetailId = oldId;

  renderExecLiveDeploymentBoard(res);
  renderExecLivePhases(res);
  showToast(`Event extended by ${mins} minutes. Total extensions: ${res.executionPlan.totalExtensionsAdded}m (${Math.floor(res.executionPlan.totalExtensionsAdded / 60)}h total).`);
};
window.updateActualPax = function (resId, val) {
  const res = RESERVATIONS.find(r => r.id === activeExecDayResId);
  if (res && res.executionPlan) {
    res.executionPlan.actualPaxReported = parseInt(val) || 0;
    renderExecLiveBashoutUI(res);
  }
};

window.updateBrokenFee = function (val) {
  const res = RESERVATIONS.find(r => r.id === activeExecDayResId);
  if (res && res.executionPlan) {
    res.executionPlan.brokenEquipFee = parseFloat(val) || 0;
    renderExecLiveBashoutUI(res);
  }
};

window.applyBashoutBilling = async function (resId) {
  const res = RESERVATIONS.find(r => r.id === resId);
  if (!res || !res.executionPlan) return;

  const extMins = res.executionPlan.totalExtensionsAdded || 0;
  const extHours = Math.floor(extMins / 60);

  const originalPax = parseInt(res.pax) || 0;
  const actualPax = res.executionPlan.actualPaxReported || originalPax;
  const extraPax = Math.max(0, actualPax - originalPax);
  const brokenFee = res.executionPlan.brokenEquipFee || 0;

  const assessmentData = {
    overtimeHrs: extHours,
    extraPax: extraPax,
    brokenEquipFee: brokenFee,
    notes: (res.paymentAssessment?.notes || '') + `\nAuto-billed from Bashout phase.`,
    lastUpdated: new Date().toISOString(),
    updatedBy: 'Bashout System'
  };

  try {
    const { doc, updateDoc } = window.firebaseFns;
    await updateDoc(doc(window.firebaseDB, 'reservations', res.id), {
      paymentAssessment: assessmentData
    });
    showToast('Billing applied. Final amount synced with Payment Assessment.');
  } catch (e) { console.error(e); alert('Failed to sync billing.'); }
};

window.renderExecLiveBashoutUI = function (res) {
  const container = document.getElementById('exec-board-bashout-ui');
  if (container) container.style.display = 'none';
};
window.renderExecLiveRestorageUI = function (res) {
  const container = document.getElementById('exec-board-restorage-ui');
  if (!container) return;

  const p = res.executionPlan.phases[execLiveActivePhaseIdx];
  if (!p || p.id !== 'restorage') {
    container.style.display = 'none';
    return;
  }

  container.style.display = 'block';
  container.innerHTML = `
    <div style="background:rgba(34,197,94,0.05); border:1px solid rgba(34,197,94,0.2); border-radius:15px; padding:30px; display:flex; flex-direction:column; align-items:center; text-align:center; box-shadow:0 8px 32px rgba(0,0,0,0.1);">
       <div style="font-size:40px; margin-bottom:15px;"></div>
       <div style="font-size:18px; font-weight:800; color:var(--cream); margin-bottom:8px;">Final Phase: Restorage & Cleanup</div>
       <div style="font-size:13px; color:var(--text-dim); max-width:450px; margin-bottom:25px;">Ensure all inventory is accounted for and transport is unloaded. Once done, mark the entire reservation as completed.</div>
       
       <button onclick="completeReservationExecution('${res.id}')" class="btn-primary" style="background:var(--green); color:#fff; padding:15px 40px; font-size:14px; font-weight:800; border-radius:12px; box-shadow:0 10px 25px rgba(34,197,94,0.3);">
         Mark Reservation as Completed
       </button>
    </div>
  `;
};

window.completeReservationExecution = async function (resId) { setTimeout(() => { if(typeof window.triggerAdminAnalyticsUpdate === 'function') window.triggerAdminAnalyticsUpdate(); }, 200);
  const res = RESERVATIONS.find(r => r.id === resId);
  if (!res) return;

  try {
    const { doc, updateDoc } = window.firebaseFns;
    await updateDoc(doc(window.firebaseDB, 'reservations', resId), {
      status: 'completed',
      'executionPlan.completedAt': new Date().toISOString()
    });

    // Update local state
    res.status = 'completed';
    if (!res.executionPlan) res.executionPlan = {};
    res.executionPlan.completedAt = new Date().toISOString();

    window.showCompletionSuccessModal(res);

  } catch (e) { console.error(e); alert('Failed to complete reservation.'); }
};



window.showCompletionSuccessModal = function (res) {
  const toast = document.createElement('div');
  toast.style = 'position:fixed;top:24px;left:50%;transform:translateX(-50%);z-index:99999;background:var(--green);color:#fff;padding:14px 32px;border-radius:12px;font-weight:700;font-size:14px;box-shadow:0 8px 32px rgba(0,0,0,0.4);transition:opacity 0.5s;white-space:nowrap;';
  toast.textContent = 'Reservation completed - redirecting to Final Summary...';
  document.body.appendChild(toast);
  setTimeout(() => { toast.style.opacity = '0'; }, 2200);
  setTimeout(() => {
    toast.remove();
    if (typeof stopExecLive === 'function') stopExecLive();
    activeResDetailId = res.id;
    showSection('res-details', document.getElementById('nav-res-details'));
    renderReservationDetailsHandling();
    setTimeout(() => {
      switchResDetailsTab('summary', document.getElementById('resd-tab-summary'));
    }, 150);
  }, 2600);
};

window.renderReservationSummary = async function (res) {
  const container = document.getElementById('resd-summary-content');
  if (!container || !res) return;

  await ensurePersonnelNameMap();

  const isCompleted = res.status === 'completed';

  // Read comprehensive saved summary from multiple sources
  let summary = res.exec_summary || (res.executionPlan && res.executionPlan.exec_summary) || (res.execution_plan && res.execution_plan.exec_summary) || null;
  if (!summary) {
    try { summary = JSON.parse(localStorage.getItem('exec_summary_' + res.id) || 'null'); } catch(e) {}
  }
  const storageKey = 'exec_end_' + (res.id || 'unknown');
  let savedEnd = {};
  try { savedEnd = JSON.parse(localStorage.getItem(storageKey) || '{}'); } catch(e) {}

  const pricing = typeof computePricingDetails === 'function' ? computePricingDetails(res) : {};
  const basePrice = pricing.basePrice || parseFloat(res.amount || res.totalPrice || res.total || res.price || 0) || 0;

  // 1. REVENUE CALCULATIONS
  const initFee = parseFloat(summary?.initFee || res.initial_fee || res.initialFeeAmount || 5000) || 5000;
  const dpAmt = parseFloat(summary?.dpAmt || res.downpayment || res.downpaymentAmount || (basePrice ? Math.round(basePrice * 0.5) : 0)) || 0;
  let finalAmt = parseFloat(summary?.finalAmt || res.finalPayment || res.final_payment || res.final_payment_amount || 0) || 0;
  if (!finalAmt && basePrice > 0) {
    finalAmt = Math.max(0, basePrice - dpAmt);
  }
  const extraItemsTotal = parseFloat(summary?.extraItemsTotal ?? pricing.extraItemsTotal ?? res.additional_items_charge ?? res.additionalItemsCharge ?? 0) || 0;
  const extraItemsBreakdown = (summary && Array.isArray(summary.extraItemsBreakdown)) ? summary.extraItemsBreakdown : ((pricing && Array.isArray(pricing.extraItemsBreakdown)) ? pricing.extraItemsBreakdown : []);
  const otcAmt = parseFloat(summary?.otcAmt || res.outOfTownCharge || res.out_of_town_charge || res.logisticsSurcharge || pricing.otc || 0) || 0;
  const svcAmt = parseFloat(summary?.svcAmt || res.serviceCharge || res.service_charge || pricing.serviceChargeAmt || 0) || 0;

  // Additional Charges itemized breakdown
  const overheadUnits = parseInt(summary?.overheadUnits ?? res.exec_extra_overhead_units ?? savedEnd.extraOverhead ?? 0, 10) || 0;
  const overheadAmt = parseFloat(summary?.overheadAmt ?? res.exec_extra_overhead_amount ?? (overheadUnits * 450)) || (overheadUnits * 450);

  const overtimeUnits = parseInt(summary?.overtimeUnits ?? res.exec_overtime_units ?? savedEnd.overtime ?? 0, 10) || 0;
  const overtimeAmt = parseFloat(summary?.overtimeAmt ?? res.exec_overtime_amount ?? (overtimeUnits * 1000)) || (overtimeUnits * 1000);

  const floorUnits = parseInt(summary?.floorUnits ?? res.exec_floor_access_units ?? savedEnd.venueFloor ?? 0, 10) || 0;
  const floorAmt = parseFloat(summary?.floorAmt ?? res.exec_floor_access_amount ?? (floorUnits * 100)) || (floorUnits * 100);

  const incCharge = parseFloat(summary?.incCharge ?? res.exec_incident_charges ?? savedEnd.incidentCharge ?? 0) || 0;
  const totCharges = parseFloat(summary?.totalCharges ?? res.exec_total_charges ?? (overheadAmt + overtimeAmt + floorAmt + incCharge)) || 0;
  const subtotalAdditionalCharges = parseFloat(summary?.subtotalAdditionalCharges ?? (totCharges + otcAmt + svcAmt + extraItemsTotal)) || (totCharges + otcAmt + svcAmt + extraItemsTotal);

  const chargePaymentStatus = summary?.chargePaymentStatus || res.exec_charges_payment_status || (savedEnd.chargesCantPay ? 'pending' : (totCharges === 0 ? 'none' : (savedEnd.chargesPaidAmt >= totCharges ? 'paid' : 'pending')));

  const clientTip = parseFloat(summary?.tip ?? res.exec_tip ?? savedEnd.tip ?? 0) || 0;
  const totRev = parseFloat(summary?.totalRevenue ?? res.exec_total_revenue ?? (initFee + dpAmt + finalAmt + subtotalAdditionalCharges + clientTip)) || 0;

  // 2. EXPENSES CALCULATIONS
  const rentalsAmt = parseFloat(summary?.rentalsAmt ?? res.exec_rentals_amount ?? savedEnd.rentals ?? 0) || 0;
  let driverName = summary?.driverName || res.exec_transport_driver_name || res._resolvedDriverName || resolvePersonnelName(res.transportationDriverId || res.transportation_driver_id || res.driverId) || 'Rodrigo "Rody" Dalisay';
  driverName = resolvePersonnelName(driverName) || driverName;
  const transportAmt = parseFloat(summary?.transportAmt ?? res.exec_transport_driver_amount ?? (savedEnd.transport && savedEnd.transport.driver) ?? 0) || 0;

  // Personnel Breakdown
  let personnelData = summary?.personnelData || res.exec_personnel_breakdown || savedEnd.personnel || res.hiredPersonnel || res.hired_personnel || {};
  let personnelTotal = 0;
  if (personnelData && typeof personnelData === 'object') {
    Object.values(personnelData).forEach(v => {
      personnelTotal += typeof v === 'object' ? (parseFloat(v.fee || v.rate || v.cost || 0) || 0) : (parseFloat(v) || 0);
    });
  }

  // Assigned Staff (@ ₱1,000 each)
  let assignments = (summary && summary.assignments) || (res.staffing && res.staffing.assignments) || [];
  if ((!assignments || assignments.length === 0) && window._activeExecStaffAssignments && window._activeExecStaffAssignments.length > 0) {
    assignments = window._activeExecStaffAssignments;
  }
  if ((!assignments || assignments.length === 0) && window.supabaseClient && res.id) {
    try {
      const { data: stData } = await window.supabaseClient.from('reservation_staff_assignments').select('staff_id, roles').eq('reservation_id', res.id);
      if (stData && stData.length > 0) {
        const staffIds = stData.map(d => d.staff_id);
        const nameMap = {};
        const { data: suData } = await window.supabaseClient.from('users').select('id, name, email, phone').in('id', staffIds);
        if (suData) suData.forEach(u => { nameMap[u.id] = u; });
        (window.allStaff || []).forEach(s => { if (!nameMap[s.id]) nameMap[s.id] = s; });
        assignments = stData.map(d => {
          const matched = nameMap[d.staff_id] || {};
          return {
            staffId: d.staff_id,
            staffName: matched.name || d.staff_id,
            email: matched.email || '',
            phone: matched.phone || '',
            roles: Array.isArray(d.roles) ? d.roles : (d.roles ? JSON.parse(d.roles) : [])
          };
        });
        if (!res.staffing) res.staffing = {};
        res.staffing.assignments = assignments;
      }
    } catch(e) {}
  }
  const staffTotal = parseFloat(summary?.staffTotal ?? res.exec_staff_expense_amount ?? (assignments.length * 1000)) || (assignments.length * 1000);

  // Dishes & Ingredients Expenses (Directly referenced from reservation_ingredient_expenses)
  let dishesIngredientsExpense = 0;
  if (window.supabaseClient && res.id) {
    try {
      const { data: ingData } = await window.supabaseClient.from('reservation_ingredient_expenses')
        .select('total_expense, expenses')
        .eq('reservation_id', String(res.id))
        .maybeSingle();
      if (ingData) {
        if (ingData.total_expense !== null && ingData.total_expense !== undefined && !isNaN(Number(ingData.total_expense))) {
          dishesIngredientsExpense = parseFloat(ingData.total_expense) || 0;
        } else if (ingData.expenses && typeof ingData.expenses === 'object') {
          dishesIngredientsExpense = Object.values(ingData.expenses).reduce((s, v) => s + (parseFloat(v) || 0), 0);
        }
      }
    } catch(e) {}
  }
  if (dishesIngredientsExpense === 0) {
    dishesIngredientsExpense = parseFloat(summary?.dishesIngredientsExpense ?? res.exec_dishes_ingredients_expense ?? 0) || 0;
  }
  if (dishesIngredientsExpense === 0) {
    const resPlanExp = (res.executionPlan && res.executionPlan.dishes_expenses) || 
                       (res.execution_plan && res.execution_plan.dishes_expenses);
    if (resPlanExp && resPlanExp.total_expense) {
      dishesIngredientsExpense = parseFloat(resPlanExp.total_expense) || 0;
    }
  }
  if (dishesIngredientsExpense === 0) {
    const cachedIng = (window._reservationIngredientExpenses && window._reservationIngredientExpenses[res.id]) ||
      JSON.parse(localStorage.getItem(`ss_ing_expenses_${res.id}`) || localStorage.getItem(`exec_ing_expenses_${res.id}`) || '{}');
    if (cachedIng.total_expense !== undefined && !isNaN(Number(cachedIng.total_expense))) {
      dishesIngredientsExpense = parseFloat(cachedIng.total_expense) || 0;
    } else if (cachedIng.expenses && typeof cachedIng.expenses === 'object') {
      dishesIngredientsExpense = Object.values(cachedIng.expenses).reduce((s, v) => s + (parseFloat(v) || 0), 0);
    }
  }
  if (dishesIngredientsExpense === 0) {
    const itemNames = (res.packageItems || []).map(ri => typeof ri === 'string' ? ri : (ri && ri.name ? ri.name : ''));
    const foodItems = itemNames.map(name => (typeof CAT !== 'undefined' ? CAT : []).find(c => c.name === name)).filter(c => c && c.cat === 'food');
    const pax = parseInt(res.pax) || 0;
    foodItems.forEach(dish => {
      if (typeof getIngredientsForDish === 'function') {
        const ings = getIngredientsForDish(dish.name, pax);
        ings.forEach(ing => { dishesIngredientsExpense += (ing.totalCost || 0); });
      }
    });
  }

  const totExp = parseFloat(summary?.totalExpenses ?? res.exec_total_expenses ?? (rentalsAmt + transportAmt + personnelTotal + staffTotal + dishesIngredientsExpense)) || 0;
  const profit = parseFloat(summary?.netProfit ?? res.exec_net_profit ?? (totRev - totExp)) || 0;
  const profitMargin = totRev > 0 ? ((profit / totRev) * 100).toFixed(1) : '0.0';

  // 3. FETCH INCIDENTS & BATCH ALLOCATIONS ASYNCHRONOUSLY
  let incidents = [];
  let batchAllocations = [];
  try {
    const sb = window.supabaseClient;
    if (sb && res.id) {
      const isUuid = typeof res.id === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(res.id);
      const incPromise = sb.from('exec_batch_incidents').select('*').eq('reservation_id', res.id).order('logged_at', { ascending: false });
      const allocPromise = isUuid ? sb.from('allocation_history').select('*').eq('reservation_id', res.id) : Promise.resolve({ data: [] });

      const [incRes, allocRes] = await Promise.all([incPromise, allocPromise]);
      if (incRes.data && incRes.data.length) incidents = incRes.data;
      if (allocRes.data && allocRes.data.length) batchAllocations = allocRes.data;
    }
  } catch (e) {
    console.warn('[renderReservationSummary] async fetch notice:', e);
  }

  if (!incidents.length && res.id && typeof getLocalIncidents === 'function') {
    incidents = getLocalIncidents(res.id);
  }

  // Safe fallback search for allocation history
  if (!batchAllocations.length && window.supabaseClient) {
    try {
      const sb = window.supabaseClient;
      const clientClean = String(res.client || '').trim();
      const pkgClean = String(res.packageName || res.package || '').trim();
      const dateClean = String(res.date || '').trim();
      const { data: allHist } = await sb.from('allocation_history').select('*').order('recorded_at', { ascending: false }).limit(200);
      if (allHist && allHist.length) {
        batchAllocations = allHist.filter(h => {
          if (String(h.reservation_id) === String(res.id)) return true;
          if (dateClean && String(h.allocation_date) === dateClean) return true;
          const hName = String(h.reservation_name || '').toLowerCase();
          if (clientClean && hName.includes(clientClean.toLowerCase())) return true;
          if (pkgClean && hName.includes(pkgClean.toLowerCase())) return true;
          return false;
        });
        if (!batchAllocations.length && allHist.length && !res.id) batchAllocations = allHist;
      }
    } catch(e) {}
  }

  if (!batchAllocations.length && res.equipment_manifest) {
    try {
      batchAllocations = typeof res.equipment_manifest === 'string' ? JSON.parse(res.equipment_manifest) : res.equipment_manifest;
    } catch(e) {}
  }

  // Header display: Package Name - Client's Event
  const packageName = res.packageName || res.package_name || res.package || 'Custom Package';
  const premadePackageName = res.premadePackageName || res.premade_package_name || '';
  const clientName = res.client || res.client_name || 'Client';

  const completedAt = res.exec_finalized_at || (summary && summary.finalizedAt)
    ? new Date(res.exec_finalized_at || summary.finalizedAt).toLocaleString('en-PH', { dateStyle: 'long', timeStyle: 'short' })
    : (isCompleted ? new Date().toLocaleString() : 'Pending Execution Finalization');

  // Time formatting
  let timeRangeStr = '—';
  if (res.timeStart && res.timeEnd) timeRangeStr = `${formatTime12h(res.timeStart)} - ${formatTime12h(res.timeEnd)}`;
  else if (res.time_start && res.time_end) timeRangeStr = `${formatTime12h(res.time_start)} - ${formatTime12h(res.time_end)}`;
  else if (res.time || res.timeframe) timeRangeStr = formatTime12h(res.time || res.timeframe);

  const callTimeRaw = res.callTime || res.call_time || res.calltime || (res.executionPlan && res.executionPlan.callTime) || (res.execution_plan && res.execution_plan.call_time) || '';
  const callTimeStr = callTimeRaw ? formatTime12h(callTimeRaw) : '—';

  // Helper row renderer
  const sRow = (label, valHtml) => `
    <div style="display:flex;justify-content:space-between;align-items:center;padding:9px 0;border-bottom:1px solid rgba(255,255,255,0.05);font-size:13px;">
      <span style="color:var(--text-dim);">${label}</span>
      <span style="color:var(--cream);font-weight:600;">${valHtml}</span>
    </div>`;

  container.innerHTML = `
    <div style="display:flex;flex-direction:column;gap:24px;max-width:1100px;margin:0 auto;">

      <!-- HEADER: Package Name - Client's Event -->
      <div style="padding-bottom:20px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:16px;">
        <div>
          <div style="font-size:11px;color:var(--gold);text-transform:uppercase;letter-spacing:2px;font-weight:800;margin-bottom:6px;">Final Event Report</div>
          <div style="font-size:26px;font-weight:800;color:var(--cream);line-height:1.2;">
            ${escHtml(packageName)} — ${escHtml(clientName)}'s Event
          </div>
          <div style="font-size:13px;color:var(--text-dim);margin-top:6px;">
            ${escHtml(res.date || '—')} &nbsp;·&nbsp; ${escHtml(res.venue || res.venueAddress || '—')} &nbsp;·&nbsp; Finalized: ${completedAt}
          </div>
        </div>
        <div>
          <button onclick="exportAdminFinalSummaryPdf('${res.id}')" style="padding:10px 22px;background:var(--gold, #c49a3c);color:#ffffff;border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer;letter-spacing:0.5px;transition:0.2s;" onmouseover="this.style.opacity='0.9'" onmouseout="this.style.opacity='1'">
            Export PDF
          </button>
        </div>
      </div>

      <!-- KPI ROW -->
      <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:16px;">
        <div style="background:var(--bg2);border:1px solid var(--border);border-radius:14px;padding:20px;text-align:center;">
          <div style="font-size:11px;color:var(--text-dim);text-transform:uppercase;letter-spacing:1px;font-weight:700;margin-bottom:8px;">Total Revenue</div>
          <div style="font-size:24px;font-weight:800;color:var(--gold);">₱${totRev.toLocaleString()}</div>
          <div style="font-size:11px;color:var(--text-dim);margin-top:4px;">Booking + All Additions</div>
        </div>
        <div style="background:var(--bg2);border:1px solid var(--border);border-radius:14px;padding:20px;text-align:center;">
          <div style="font-size:11px;color:var(--text-dim);text-transform:uppercase;letter-spacing:1px;font-weight:700;margin-bottom:8px;">Total Expenses</div>
          <div style="font-size:24px;font-weight:800;color:var(--red);">₱${totExp.toLocaleString()}</div>
          <div style="font-size:11px;color:var(--text-dim);margin-top:4px;">Ops, Staff, Logistics & Food</div>
        </div>
        <div style="background:var(--bg2);border:1px solid var(--border);border-radius:14px;padding:20px;text-align:center;">
          <div style="font-size:11px;color:var(--green);text-transform:uppercase;letter-spacing:1px;font-weight:800;margin-bottom:8px;">Net Profit</div>
          <div style="font-size:24px;font-weight:800;color:var(--green);">₱${profit.toLocaleString()}</div>
          <div style="font-size:11px;color:var(--green);font-weight:700;margin-top:4px;">Margin: ${profitMargin}%</div>
        </div>
        <div style="background:var(--bg2);border:1px solid var(--border);border-radius:14px;padding:20px;text-align:center;">
          <div style="font-size:11px;color:var(--text-dim);text-transform:uppercase;letter-spacing:1px;font-weight:700;margin-bottom:8px;">Incidents Logged</div>
          <div style="font-size:24px;font-weight:800;color:${incidents.length > 0 ? 'var(--amber)' : 'var(--cream)'};">${incidents.length}</div>
          <div style="font-size:11px;color:var(--text-dim);margin-top:4px;">Equipment Exceptions</div>
        </div>
      </div>

      <!-- MAIN 2-COLUMN FINANCIAL & DETAIL GRID -->
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:20px;">

        <!-- LEFT COLUMN: REVENUE SUMMARY & EVENT DETAILS -->
        <div style="display:flex;flex-direction:column;gap:20px;">

          <!-- 1. REVENUE SUMMARY CARD -->
          <div style="background:var(--bg2);border:1px solid var(--border);border-radius:14px;padding:22px;text-align:left;">
            <div style="font-size:11px;color:var(--gold);text-transform:uppercase;letter-spacing:1px;font-weight:800;margin-bottom:14px;">Revenue Summary</div>
            ${sRow('Initial Booking Fee', '₱' + initFee.toLocaleString())}
            ${sRow('Downpayment', '₱' + dpAmt.toLocaleString())}
            ${sRow('Base Final Payment', '₱' + finalAmt.toLocaleString())}

            <!-- Additional Charges Itemized Breakdown (Out of Town and Service Charge inside Additional Charges) -->
            <div style="padding:12px 14px;background:rgba(255,255,255,0.02);border:1px dashed var(--border);border-radius:8px;margin:12px 0;">
              <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">
                <span style="font-size:12px;font-weight:700;color:var(--cream);">Additional Charges</span>
                <span style="font-size:11px;font-weight:800;color:${chargePaymentStatus === 'paid' ? 'var(--green)' : 'var(--gold)'};text-transform:uppercase;">${(chargePaymentStatus || 'pending').toUpperCase()}</span>
              </div>
              <div style="display:flex;flex-direction:column;gap:5px;font-size:11px;color:var(--text-dim);">
                ${extraItemsBreakdown.length > 0
                  ? extraItemsBreakdown.map(it => `<div style="display:flex;justify-content:space-between;"><span>+ ${escHtml(it.name || 'Additional Item')}</span><span style="color:var(--cream);">₱${(it.price || 0).toLocaleString()}</span></div>`).join('')
                  : (extraItemsTotal > 0 ? `<div style="display:flex;justify-content:space-between;"><span>Additional Package Items</span><span style="color:var(--cream);">₱${extraItemsTotal.toLocaleString()}</span></div>` : '')}
                ${otcAmt > 0 ? `<div style="display:flex;justify-content:space-between;"><span>Out of Town Surcharge</span><span style="color:var(--cream);">₱${otcAmt.toLocaleString()}</span></div>` : ''}
                ${svcAmt > 0 ? `<div style="display:flex;justify-content:space-between;"><span>Service Charge</span><span style="color:var(--cream);">₱${svcAmt.toLocaleString()}</span></div>` : ''}
                <div style="display:flex;justify-content:space-between;">
                  <span>Extra Overhead (${overheadUnits} units @ ₱450)</span>
                  <span style="color:var(--cream);">₱${overheadAmt.toLocaleString()}</span>
                </div>
                <div style="display:flex;justify-content:space-between;">
                  <span>Overtime Charge (${overtimeUnits} hrs @ ₱1,000)</span>
                  <span style="color:var(--cream);">₱${overtimeAmt.toLocaleString()}</span>
                </div>
                <div style="display:flex;justify-content:space-between;">
                  <span>Venue Floor Accessibility (${floorUnits} floors @ ₱100)</span>
                  <span style="color:var(--cream);">₱${floorAmt.toLocaleString()}</span>
                </div>
                <div style="display:flex;justify-content:space-between;">
                  <span>Incident Charges</span>
                  <span style="color:var(--cream);">₱${incCharge.toLocaleString()}</span>
                </div>
                <div style="display:flex;justify-content:space-between;padding-top:6px;border-top:1px solid rgba(255,255,255,0.05);color:var(--cream);font-weight:700;">
                  <span>Subtotal Additional Charges</span>
                  <span style="color:var(--gold);">₱${subtotalAdditionalCharges.toLocaleString()}</span>
                </div>
              </div>
            </div>

            ${clientTip > 0 ? sRow('Client Tip', '₱' + clientTip.toLocaleString()) : ''}

            <div style="padding-top:14px;border-top:1px solid var(--border);margin-top:10px;display:flex;justify-content:space-between;align-items:center;">
              <span style="font-size:15px;font-weight:700;color:var(--cream);">Total Revenue</span>
              <span style="font-size:20px;font-weight:800;color:var(--gold);">₱${totRev.toLocaleString()}</span>
            </div>
          </div>

          <!-- 2. EVENT DETAILS CARD (No status row) -->
          <div style="background:var(--bg2);border:1px solid var(--border);border-radius:14px;padding:22px;text-align:left;">
            <div style="font-size:11px;color:var(--text-dim);text-transform:uppercase;letter-spacing:1px;font-weight:800;margin-bottom:14px;">Event Details</div>
            ${sRow('Package', escHtml(packageName))}
            ${premadePackageName ? sRow('Premade Package', escHtml(premadePackageName)) : ''}
            ${sRow('Client', escHtml(clientName))}
            ${sRow('Occasion', escHtml(res.type || res.occasion || '—'))}
            ${sRow('Theme', escHtml(res.theme || '—'))}
            ${res.eventSetup ? sRow('Event Setup', escHtml(res.eventSetup)) : ''}
            ${sRow('Guests', `${res.pax || '—'} pax${res.vipCount ? ' (' + res.vipCount + ' VIP)' : ''}`)}
            ${sRow('Event Date', escHtml(res.date || '—'))}
            ${sRow('Time Range', escHtml(timeRangeStr))}
            ${sRow('Call Time', escHtml(callTimeStr))}
            <div style="display:flex;justify-content:space-between;align-items:flex-start;padding:9px 0;border-bottom:1px solid rgba(255,255,255,0.05);gap:12px;">
              <span style="font-size:13px;color:var(--text-dim);flex-shrink:0;">Venue</span>
              <span style="font-size:13px;color:var(--cream);font-weight:600;text-align:right;word-break:break-word;">${escHtml(res.venue || res.venueAddress || '—')}</span>
            </div>
          </div>

        </div>

        <!-- RIGHT COLUMN: EXPENSES BREAKDOWN & NET PROFIT -->
        <div style="display:flex;flex-direction:column;gap:20px;">

          <!-- 3. EXPENSES BREAKDOWN CARD -->
          <div style="background:var(--bg2);border:1px solid var(--border);border-radius:14px;padding:22px;text-align:left;">
            <div style="font-size:11px;color:var(--red);text-transform:uppercase;letter-spacing:1px;font-weight:800;margin-bottom:14px;">Expenses Breakdown</div>
            ${sRow('Equipment Rentals', '₱' + rentalsAmt.toLocaleString())}
            ${sRow(`Transportation (${escHtml(driverName)})`, '₱' + transportAmt.toLocaleString())}
            ${Object.keys(personnelData || {}).map(k => {
              const val = typeof personnelData[k] === 'object' ? (parseFloat(personnelData[k].fee || personnelData[k].rate || personnelData[k].cost || 0) || 0) : (parseFloat(personnelData[k]) || 0);
              let pName = resolvePersonnelName(k);
              if ((!pName || pName === k) && typeof personnelData[k] === 'object' && (personnelData[k].name || personnelData[k].full_name)) {
                pName = personnelData[k].name || personnelData[k].full_name;
              }
              return sRow(`Personnel: ${escHtml(pName)}`, '₱' + val.toLocaleString());
            }).join('')}
            ${sRow(`Assigned Staff (${assignments.length} @ ₱1,000/head)`, '₱' + staffTotal.toLocaleString())}

            <!-- Staff List Itemized Detail -->
            ${assignments.length > 0 ? `
              <div style="padding:10px 12px;background:rgba(255,255,255,0.02);border:1px solid rgba(255,255,255,0.04);border-radius:8px;margin:8px 0;display:flex;flex-direction:column;gap:6px;">
                ${assignments.map(a => `
                  <div style="display:flex;justify-content:space-between;font-size:12px;">
                    <span style="color:var(--cream);">${escHtml(a.staffName || a.staff_name || a.staffId || 'Staff')}</span>
                    <span style="color:var(--gold);font-weight:600;">₱1,000</span>
                  </div>
                `).join('')}
              </div>
            ` : ''}

            ${sRow('Dishes & Ingredients Expenses', '₱' + dishesIngredientsExpense.toLocaleString())}

            <div style="padding-top:14px;border-top:1px solid var(--border);margin-top:10px;display:flex;justify-content:space-between;align-items:center;">
              <span style="font-size:15px;font-weight:700;color:var(--cream);">Total Expenses</span>
              <span style="font-size:20px;font-weight:800;color:var(--red);">₱${totExp.toLocaleString()}</span>
            </div>
          </div>

          <!-- 4. NET PROFIT HIGHLIGHT CARD -->
          <div style="background:var(--bg2);border:1px solid var(--border);border-radius:14px;padding:20px 24px;display:flex;justify-content:space-between;align-items:center;">
            <div>
              <div style="font-size:11px;color:var(--green);font-weight:800;text-transform:uppercase;letter-spacing:1px;">Net Profit</div>
              <div style="font-size:12px;color:var(--text-dim);margin-top:3px;">Total Revenue − Total Expenses</div>
            </div>
            <div style="text-align:right;">
              <div style="font-size:26px;font-weight:800;color:var(--green);">₱${profit.toLocaleString()}</div>
              <div style="font-size:12px;color:var(--green);font-weight:700;margin-top:2px;">Margin: ${profitMargin}%</div>
            </div>
          </div>

          <!-- 5. LOGGED INCIDENTS CARD (Clean text, no check icon) -->
          <div style="background:var(--bg2);border:1px solid var(--border);border-radius:14px;padding:22px;text-align:left;">
            <div style="font-size:11px;color:var(--red);text-transform:uppercase;letter-spacing:1px;font-weight:800;margin-bottom:14px;">Logged Incidents (${incidents.length})</div>
            ${incidents.length === 0 ? `
              <div style="color:var(--text-dim);font-size:13px;font-weight:500;padding:10px 0;">
                No incidents reported for this event. All equipment returned safely.
              </div>
            ` : `
              <div style="display:flex;flex-direction:column;gap:10px;">
                ${incidents.map(inc => {
                  const badgeColor = (inc.incident_type || '').toLowerCase() === 'broken' ? 'var(--red)' : ((inc.incident_type || '').toLowerCase() === 'missing' ? 'var(--amber)' : '#c084fc');
                  const timeStr = inc.logged_at ? new Date(inc.logged_at).toLocaleTimeString([], { hour:'numeric', minute:'2-digit', hour12:true }) : '';
                  return `
                    <div style="display:flex;justify-content:space-between;align-items:center;padding:10px 14px;background:var(--bg3);border-radius:8px;border-left:3px solid ${badgeColor};gap:10px;flex-wrap:wrap;">
                      <div>
                        <div style="font-size:13px;font-weight:700;color:var(--cream);">${escHtml(inc.equipment_name || 'Equipment')}</div>
                        <div style="font-size:11px;color:var(--text-dim);">${escHtml(inc.phase || 'Execution')} · ${timeStr}</div>
                      </div>
                      <div style="display:flex;align-items:center;gap:10px;">
                        <span style="font-size:12px;color:var(--cream);font-weight:600;">Qty: ${inc.quantity || 1}</span>
                        <span style="font-size:11px;font-weight:800;color:${badgeColor};text-transform:uppercase;">${escHtml(inc.incident_type || 'Broken')}</span>
                        ${inc.photo_url ? `<a href="javascript:void(0)" onclick="openExecIncidentPhoto('${inc.photo_url}')" style="font-size:11px;color:var(--gold);text-decoration:underline;">View Photo</a>` : ''}
                      </div>
                    </div>
                  `;
                }).join('')}
              </div>
            `}
          </div>

        </div>
      </div>

      <!-- 6. BATCH ALLOCATION EQUIPMENT MANIFEST CARD (Pure text, no colored pill background) -->
      <div style="background:var(--bg2);border:1px solid var(--border);border-radius:14px;padding:22px;text-align:left;">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;">
          <div>
            <div style="font-size:11px;color:var(--gold);text-transform:uppercase;letter-spacing:1px;font-weight:800;">Batch Allocation Manifest</div>
            <div style="font-size:13px;color:var(--text-dim);margin-top:2px;">Equipment deployed and tracked for this event</div>
          </div>
          <span style="font-size:12px;color:var(--gold);font-weight:700;">
            ${batchAllocations.length} Items Allocated
          </span>
        </div>

        ${batchAllocations.length === 0 ? `
          <div style="text-align:center;padding:30px;color:var(--text-dim);font-size:13px;">
            No equipment allocation recorded in history for this reservation yet.
          </div>
        ` : `
          <div style="overflow-x:auto;">
            <table style="width:100%;border-collapse:collapse;font-size:13px;text-align:left;">
              <thead>
                <tr style="border-bottom:1px solid var(--border);color:var(--text-dim);font-size:11px;text-transform:uppercase;">
                  <th style="padding:10px 12px;">Equipment Name</th>
                  <th style="padding:10px 12px;">Asset ID</th>
                  <th style="padding:10px 12px;text-align:center;">Allocated Qty</th>
                  <th style="padding:10px 12px;text-align:center;">Unit</th>
                  <th style="padding:10px 12px;text-align:right;">Type</th>
                </tr>
              </thead>
              <tbody>
                ${batchAllocations.map(item => {
                  const eqName = item.equipment_name || item.name || 'Equipment';
                  const assetId = item.equipment_id || item.asset_id || item.assetId || '—';
                  const qty = item.allocated_qty || item.quantity || 1;
                  const unit = item.unit_type || item.unit || 'sets';
                  const isCons = !!item.consumable;
                  return `
                    <tr style="border-bottom:1px solid rgba(255,255,255,0.04);">
                      <td style="padding:10px 12px;color:var(--cream);font-weight:600;">${escHtml(eqName)}</td>
                      <td style="padding:10px 12px;color:var(--text-dim);font-family:monospace;">${escHtml(assetId)}</td>
                      <td style="padding:10px 12px;color:var(--gold);font-weight:700;text-align:center;">${qty}</td>
                      <td style="padding:10px 12px;color:var(--text-dim);text-align:center;">${escHtml(unit)}</td>
                      <td style="padding:10px 12px;text-align:right;">
                        <span style="font-size:11px;font-weight:700;text-transform:uppercase;color:${isCons ? 'var(--amber)' : 'var(--green)'};">
                          ${isCons ? 'Consumable' : 'Equipment'}
                        </span>
                      </td>
                    </tr>
                  `;
                }).join('')}
              </tbody>
            </table>
          </div>
        `}
      </div>

    </div>
  `;
};

// =====================================================================
// EXPORT ADMIN FINAL SUMMARY REPORT (PDF)
// Generates a complete, high-fidelity printable document containing
// all KPIs, Revenue, Expenses, Event Details, Incidents, and Batch Manifest.
// Strictly adheres to safety protocols: no emoticons, clean professional typography.
// =====================================================================
window.exportAdminFinalSummaryPdf = async function(targetResId) {
  let resId = targetResId || activeResDetailId;
  let res = (window.RESERVATIONS || []).find(r => r.id === resId);

  // Fallback lookup in Supabase if not present in memory
  if (!res && window.supabaseClient && resId) {
    try {
      const { data } = await window.supabaseClient.from('reservations').select('*').eq('id', resId).maybeSingle();
      if (data) res = data;
    } catch(e) {
      console.warn('[exportAdminFinalSummaryPdf] Supabase fallback lookup error:', e);
    }
  }

  if (!res) {
    alert('No reservation details found to export.');
    return;
  }

  // Ensure personnel name resolver is ready
  if (typeof ensurePersonnelNameMap === 'function') {
    await ensurePersonnelNameMap();
  }

  // 1. Gather comprehensive saved summary and calculations
  let summary = res.exec_summary || (res.executionPlan && res.executionPlan.exec_summary) || (res.execution_plan && res.execution_plan.exec_summary) || null;
  if (!summary) {
    try { summary = JSON.parse(localStorage.getItem('exec_summary_' + res.id) || 'null'); } catch(e) {}
  }
  const storageKey = 'exec_end_' + (res.id || 'unknown');
  let savedEnd = {};
  try { savedEnd = JSON.parse(localStorage.getItem(storageKey) || '{}'); } catch(e) {}

  const pricing = typeof computePricingDetails === 'function' ? computePricingDetails(res) : {};
  const basePrice = pricing.basePrice || parseFloat(res.amount || res.totalPrice || res.total || res.price || 0) || 0;

  // Revenue computations
  const initFee = parseFloat(summary?.initFee || res.initial_fee || res.initialFeeAmount || 5000) || 5000;
  const dpAmt = parseFloat(summary?.dpAmt || res.downpayment || res.downpaymentAmount || (basePrice ? Math.round(basePrice * 0.5) : 0)) || 0;
  let finalAmt = parseFloat(summary?.finalAmt || res.finalPayment || res.final_payment || res.final_payment_amount || 0) || 0;
  if (!finalAmt && basePrice > 0) finalAmt = Math.max(0, basePrice - dpAmt);

  const extraItemsTotal = parseFloat(summary?.extraItemsTotal ?? pricing.extraItemsTotal ?? res.additional_items_charge ?? res.additionalItemsCharge ?? 0) || 0;
  const extraItemsBreakdown = (summary && Array.isArray(summary.extraItemsBreakdown)) ? summary.extraItemsBreakdown : ((pricing && Array.isArray(pricing.extraItemsBreakdown)) ? pricing.extraItemsBreakdown : []);
  const otcAmt = parseFloat(summary?.otcAmt || res.outOfTownCharge || res.out_of_town_charge || res.logisticsSurcharge || pricing.otc || 0) || 0;
  const svcAmt = parseFloat(summary?.svcAmt || res.serviceCharge || res.service_charge || pricing.serviceChargeAmt || 0) || 0;

  const overheadUnits = parseInt(summary?.overheadUnits ?? res.exec_extra_overhead_units ?? savedEnd.extraOverhead ?? 0, 10) || 0;
  const overheadAmt = parseFloat(summary?.overheadAmt ?? res.exec_extra_overhead_amount ?? (overheadUnits * 450)) || (overheadUnits * 450);

  const overtimeUnits = parseInt(summary?.overtimeUnits ?? res.exec_overtime_units ?? savedEnd.overtime ?? 0, 10) || 0;
  const overtimeAmt = parseFloat(summary?.overtimeAmt ?? res.exec_overtime_amount ?? (overtimeUnits * 1000)) || (overtimeUnits * 1000);

  const floorUnits = parseInt(summary?.floorUnits ?? res.exec_floor_access_units ?? savedEnd.venueFloor ?? 0, 10) || 0;
  const floorAmt = parseFloat(summary?.floorAmt ?? res.exec_floor_access_amount ?? (floorUnits * 100)) || (floorUnits * 100);

  const incCharge = parseFloat(summary?.incCharge ?? res.exec_incident_charges ?? savedEnd.incidentCharge ?? 0) || 0;
  const totCharges = parseFloat(summary?.totalCharges ?? res.exec_total_charges ?? (overheadAmt + overtimeAmt + floorAmt + incCharge)) || 0;
  const subtotalAdditionalCharges = parseFloat(summary?.subtotalAdditionalCharges ?? (totCharges + otcAmt + svcAmt + extraItemsTotal)) || (totCharges + otcAmt + svcAmt + extraItemsTotal);

  const chargePaymentStatus = summary?.chargePaymentStatus || res.exec_charges_payment_status || (savedEnd.chargesCantPay ? 'pending' : (totCharges === 0 ? 'none' : (savedEnd.chargesPaidAmt >= totCharges ? 'paid' : 'pending')));
  const clientTip = parseFloat(summary?.tip ?? res.exec_tip ?? savedEnd.tip ?? 0) || 0;
  const totRev = parseFloat(summary?.totalRevenue ?? res.exec_total_revenue ?? (initFee + dpAmt + finalAmt + subtotalAdditionalCharges + clientTip)) || 0;

  // Expenses computations
  const rentalsAmt = parseFloat(summary?.rentalsAmt ?? res.exec_rentals_amount ?? savedEnd.rentals ?? 0) || 0;
  let driverName = summary?.driverName || res.exec_transport_driver_name || res._resolvedDriverName || resolvePersonnelName(res.transportationDriverId || res.transportation_driver_id || res.driverId) || 'Rodrigo "Rody" Dalisay';
  driverName = resolvePersonnelName(driverName) || driverName;
  const transportAmt = parseFloat(summary?.transportAmt ?? res.exec_transport_driver_amount ?? (savedEnd.transport && savedEnd.transport.driver) ?? 0) || 0;

  let personnelData = summary?.personnelData || res.exec_personnel_breakdown || savedEnd.personnel || res.hiredPersonnel || res.hired_personnel || {};
  let personnelTotal = 0;
  if (personnelData && typeof personnelData === 'object') {
    Object.values(personnelData).forEach(v => {
      personnelTotal += typeof v === 'object' ? (parseFloat(v.fee || v.rate || v.cost || 0) || 0) : (parseFloat(v) || 0);
    });
  }

  let assignments = (summary && summary.assignments) || (res.staffing && res.staffing.assignments) || [];
  if ((!assignments || assignments.length === 0) && window._activeExecStaffAssignments && window._activeExecStaffAssignments.length > 0) {
    assignments = window._activeExecStaffAssignments;
  }
  if ((!assignments || assignments.length === 0) && window.supabaseClient && res.id) {
    try {
      const { data: stData } = await window.supabaseClient.from('reservation_staff_assignments').select('staff_id, roles').eq('reservation_id', res.id);
      if (stData && stData.length > 0) {
        const staffIds = stData.map(d => d.staff_id);
        const nameMap = {};
        const { data: suData } = await window.supabaseClient.from('users').select('id, name, email, phone').in('id', staffIds);
        if (suData) suData.forEach(u => { nameMap[u.id] = u; });
        (window.allStaff || []).forEach(s => { if (!nameMap[s.id]) nameMap[s.id] = s; });
        assignments = stData.map(d => {
          const matched = nameMap[d.staff_id] || {};
          return {
            staffId: d.staff_id,
            staffName: matched.name || d.staff_id,
            roles: Array.isArray(d.roles) ? d.roles : []
          };
        });
      }
    } catch(e) {}
  }
  const staffTotal = parseFloat(summary?.staffTotal ?? res.exec_staff_expense_amount ?? (assignments.length * 1000)) || (assignments.length * 1000);

  // Dishes & ingredients
  let dishesIngredientsExpense = parseFloat(summary?.dishesIngredientsExpense ?? res.exec_dishes_ingredients_expense ?? 0) || 0;
  if (dishesIngredientsExpense === 0 && window.supabaseClient && res.id) {
    try {
      const { data: ingData } = await window.supabaseClient.from('reservation_ingredient_expenses')
        .select('total_expense, expenses').eq('reservation_id', String(res.id)).maybeSingle();
      if (ingData) {
        if (ingData.total_expense !== null && ingData.total_expense !== undefined && !isNaN(Number(ingData.total_expense))) {
          dishesIngredientsExpense = parseFloat(ingData.total_expense) || 0;
        } else if (ingData.expenses && typeof ingData.expenses === 'object') {
          dishesIngredientsExpense = Object.values(ingData.expenses).reduce((s, v) => s + (parseFloat(v) || 0), 0);
        }
      }
    } catch(e) {}
  }

  const totExp = parseFloat(summary?.totalExpenses ?? res.exec_total_expenses ?? (rentalsAmt + transportAmt + personnelTotal + staffTotal + dishesIngredientsExpense)) || 0;
  const profit = parseFloat(summary?.netProfit ?? res.exec_net_profit ?? (totRev - totExp)) || 0;
  const profitMargin = totRev > 0 ? ((profit / totRev) * 100).toFixed(1) : '0.0';

  // Incidents & batch allocations
  let incidents = [];
  let batchAllocations = [];
  try {
    const sb = window.supabaseClient;
    if (sb && res.id) {
      const isUuid = typeof res.id === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(res.id);
      const incPromise = sb.from('exec_batch_incidents').select('*').eq('reservation_id', res.id).order('logged_at', { ascending: false });
      const allocPromise = isUuid ? sb.from('allocation_history').select('*').eq('reservation_id', res.id) : Promise.resolve({ data: [] });
      const [incRes, allocRes] = await Promise.all([incPromise, allocPromise]);
      if (incRes.data && incRes.data.length) incidents = incRes.data;
      if (allocRes.data && allocRes.data.length) batchAllocations = allocRes.data;
    }
  } catch (e) {}

  if (!incidents.length && res.id && typeof getLocalIncidents === 'function') {
    incidents = getLocalIncidents(res.id);
  }

  const packageName = res.packageName || res.package_name || res.package || 'Custom Package';
  const premadePackageName = res.premadePackageName || res.premade_package_name || '';
  const clientName = res.client || res.client_name || res.name || 'Client';
  const eventDate = res.date || res.eventDate || res.event_date || 'N/A';
  const venue = res.venue || res.venueAddress || 'N/A';
  const finalizedAt = res.exec_finalized_at || (summary && summary.finalizedAt)
    ? new Date(res.exec_finalized_at || summary.finalizedAt).toLocaleString('en-PH', { dateStyle: 'long', timeStyle: 'short' })
    : new Date().toLocaleString('en-PH', { dateStyle: 'long', timeStyle: 'short' });

  let timeRangeStr = 'N/A';
  if (res.timeStart && res.timeEnd) timeRangeStr = `${formatTime12h(res.timeStart)} - ${formatTime12h(res.timeEnd)}`;
  else if (res.time_start && res.time_end) timeRangeStr = `${formatTime12h(res.time_start)} - ${formatTime12h(res.time_end)}`;
  else if (res.time || res.timeframe) timeRangeStr = formatTime12h(res.time || res.timeframe);

  const callTimeRaw = res.callTime || res.call_time || res.calltime || (res.executionPlan && res.executionPlan.callTime) || (res.execution_plan && res.execution_plan.call_time) || '';
  const callTimeStr = callTimeRaw ? formatTime12h(callTimeRaw) : 'N/A';

  // 2. Open print window and inject comprehensive printable document
  const printWindow = window.open('', '_blank');
  if (!printWindow) {
    alert('Please allow popups to export the PDF report.');
    return;
  }

  const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Final Event Report - ${escHtml(clientName)} (${escHtml(packageName)})</title>
  <style>
    @page { size: A4 portrait; margin: 12mm 15mm; }
    * { box-sizing: border-box; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif; color: #111; background: #fff; margin: 0; padding: 0; font-size: 12px; line-height: 1.45; }
    .header-box { border-bottom: 2px solid #c49a3c; padding-bottom: 12px; margin-bottom: 18px; display: flex; justify-content: space-between; align-items: flex-start; }
    .brand-title { font-size: 18px; font-weight: 800; color: #1a1a1a; letter-spacing: 0.5px; text-transform: uppercase; margin: 0; }
    .brand-sub { font-size: 11px; color: #666; margin-top: 2px; }
    .report-meta { text-align: right; font-size: 11px; color: #555; }
    .event-title { font-size: 16px; font-weight: 800; color: #c49a3c; margin: 0 0 4px 0; }
    .kpi-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 18px; }
    .kpi-card { background: #fafafa; border: 1px solid #e0e0e0; border-radius: 8px; padding: 10px; text-align: center; }
    .kpi-label { font-size: 10px; text-transform: uppercase; color: #666; font-weight: 700; letter-spacing: 0.5px; margin-bottom: 4px; }
    .kpi-value { font-size: 18px; font-weight: 800; color: #111; }
    .kpi-sub { font-size: 9px; color: #888; margin-top: 2px; }
    .grid-2col { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 18px; }
    .card { background: #fff; border: 1px solid #e0e0e0; border-radius: 8px; padding: 14px; margin-bottom: 14px; page-break-inside: avoid; }
    .card-title { font-size: 11px; font-weight: 800; text-transform: uppercase; letter-spacing: 0.8px; color: #c49a3c; margin-bottom: 10px; border-bottom: 1px solid #eee; padding-bottom: 6px; }
    .row { display: flex; justify-content: space-between; padding: 5px 0; border-bottom: 1px solid #f4f4f4; font-size: 11px; }
    .row span:first-child { color: #555; }
    .row span:last-child { font-weight: 600; color: #111; text-align: right; }
    .total-row { display: flex; justify-content: space-between; padding-top: 8px; margin-top: 6px; border-top: 1.5px solid #111; font-weight: 800; font-size: 12px; }
    table { width: 100%; border-collapse: collapse; font-size: 11px; margin-top: 6px; }
    th { background: #f8f8f8; text-align: left; padding: 6px 8px; font-size: 10px; text-transform: uppercase; color: #555; border-bottom: 1px solid #ddd; }
    td { padding: 6px 8px; border-bottom: 1px solid #eee; vertical-align: top; }
    .highlight-profit { background: #f0fdf4; border: 1px solid #86efac; border-radius: 8px; padding: 12px 16px; display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; }
    .footer-note { text-align: center; font-size: 10px; color: #777; border-top: 1px solid #eee; padding-top: 12px; margin-top: 20px; }
  </style>
</head>
<body>
  <div class="header-box">
    <div>
      <h1 class="brand-title">Halden's Catering Services</h1>
      <div class="brand-sub">Comprehensive Final Event Execution & Settlement Report</div>
      <div style="font-size:13px; font-weight:700; color:#111; margin-top:8px;">
        ${escHtml(packageName)} - ${escHtml(clientName)}'s Event
      </div>
    </div>
    <div class="report-meta">
      <div><strong>Date:</strong> ${escHtml(eventDate)}</div>
      <div><strong>Venue:</strong> ${escHtml(venue)}</div>
      <div><strong>Finalized:</strong> ${escHtml(finalizedAt)}</div>
      <div><strong>Ref ID:</strong> ${escHtml(res.id || 'N/A')}</div>
    </div>
  </div>

  <!-- KPI SUMMARY ROW -->
  <div class="kpi-row">
    <div class="kpi-card">
      <div class="kpi-label">Total Revenue</div>
      <div class="kpi-value" style="color:#b45309;">PHP ${totRev.toLocaleString()}</div>
      <div class="kpi-sub">Contract + Additions</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Total Expenses</div>
      <div class="kpi-value" style="color:#b91c1c;">PHP ${totExp.toLocaleString()}</div>
      <div class="kpi-sub">Logistics, Staff, Food</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Net Profit</div>
      <div class="kpi-value" style="color:#15803d;">PHP ${profit.toLocaleString()}</div>
      <div class="kpi-sub">Margin: ${profitMargin}%</div>
    </div>
    <div class="kpi-card">
      <div class="kpi-label">Incidents Logged</div>
      <div class="kpi-value">${incidents.length}</div>
      <div class="kpi-sub">Equipment Exceptions</div>
    </div>
  </div>

  <!-- MAIN 2-COLUMN SECTION -->
  <div class="grid-2col">
    <!-- LEFT: REVENUE SUMMARY & EVENT DETAILS -->
    <div>
      <div class="card">
        <div class="card-title">Revenue Summary (Itemized Payments)</div>
        <div class="row"><span>Initial Booking Fee</span><span>PHP ${initFee.toLocaleString()} (PAID)</span></div>
        <div class="row"><span>Downpayment</span><span>PHP ${dpAmt.toLocaleString()} (PAID)</span></div>
        <div class="row"><span>Base Final Payment</span><span>PHP ${finalAmt.toLocaleString()} (PAID)</span></div>

        <div style="margin: 8px 0; padding: 8px; background: #fafafa; border: 1px dashed #ccc; border-radius: 6px;">
          <div style="font-weight: 700; font-size: 10px; text-transform: uppercase; color: #444; margin-bottom: 4px;">
            Additional Execution Charges (${(chargePaymentStatus || 'pending').toUpperCase()})
          </div>
          ${extraItemsBreakdown.length > 0
            ? extraItemsBreakdown.map(it => `<div class="row"><span>+ ${escHtml(it.name || 'Additional Item')}</span><span>PHP ${(it.price || 0).toLocaleString()}</span></div>`).join('')
            : (extraItemsTotal > 0 ? `<div class="row"><span>Additional Package Items</span><span>PHP ${extraItemsTotal.toLocaleString()}</span></div>` : '')}
          ${otcAmt > 0 ? `<div class="row"><span>Out of Town Surcharge</span><span>PHP ${otcAmt.toLocaleString()}</span></div>` : ''}
          ${svcAmt > 0 ? `<div class="row"><span>Service Charge</span><span>PHP ${svcAmt.toLocaleString()}</span></div>` : ''}
          <div class="row"><span>Extra Overhead (${overheadUnits} units @ PHP 450)</span><span>PHP ${overheadAmt.toLocaleString()}</span></div>
          <div class="row"><span>Overtime Charge (${overtimeUnits} hrs @ PHP 1,000)</span><span>PHP ${overtimeAmt.toLocaleString()}</span></div>
          <div class="row"><span>Venue Floor Accessibility (${floorUnits} floors @ PHP 100)</span><span>PHP ${floorAmt.toLocaleString()}</span></div>
          <div class="row"><span>Incident Charges</span><span>PHP ${incCharge.toLocaleString()}</span></div>
          <div class="row" style="font-weight:700;"><span>Subtotal Additional Charges</span><span>PHP ${subtotalAdditionalCharges.toLocaleString()}</span></div>
        </div>

        ${clientTip > 0 ? `<div class="row"><span>Client Gratuity / Tip</span><span>PHP ${clientTip.toLocaleString()} (PAID)</span></div>` : ''}
        <div class="total-row">
          <span>Total Revenue Received</span>
          <span style="color:#b45309;">PHP ${totRev.toLocaleString()}</span>
        </div>
      </div>

      <div class="card">
        <div class="card-title">Event Operational Details</div>
        <div class="row"><span>Client Name</span><span>${escHtml(clientName)}</span></div>
        <div class="row"><span>Catering Package</span><span>${escHtml(packageName)}</span></div>
        ${premadePackageName ? `<div class="row"><span>Premade Package</span><span>${escHtml(premadePackageName)}</span></div>` : ''}
        <div class="row"><span>Occasion / Type</span><span>${escHtml(res.type || res.occasion || 'Event')}</span></div>
        <div class="row"><span>Theme</span><span>${escHtml(res.theme || 'N/A')}</span></div>
        ${res.eventSetup ? `<div class="row"><span>Event Setup</span><span>${escHtml(res.eventSetup)}</span></div>` : ''}
        <div class="row"><span>Guest Count</span><span>${res.pax || 'N/A'} pax${res.vipCount ? ' (' + res.vipCount + ' VIP)' : ''}</span></div>
        <div class="row"><span>Event Date</span><span>${escHtml(eventDate)}</span></div>
        <div class="row"><span>Operational Time</span><span>${escHtml(timeRangeStr)}</span></div>
        <div class="row"><span>Call Time</span><span>${escHtml(callTimeStr)}</span></div>
        <div class="row"><span>Venue Address</span><span>${escHtml(venue)}</span></div>
      </div>
    </div>

    <!-- RIGHT: EXPENSES BREAKDOWN & NET PROFIT -->
    <div>
      <div class="card">
        <div class="card-title">Operational Expenses Breakdown</div>
        <div class="row"><span>Equipment Rentals</span><span>PHP ${rentalsAmt.toLocaleString()}</span></div>
        <div class="row"><span>Transportation (${escHtml(driverName)})</span><span>PHP ${transportAmt.toLocaleString()}</span></div>
        ${Object.keys(personnelData || {}).map(k => {
          const val = typeof personnelData[k] === 'object' ? (parseFloat(personnelData[k].fee || personnelData[k].rate || personnelData[k].cost || 0) || 0) : (parseFloat(personnelData[k]) || 0);
          let pName = resolvePersonnelName(k) || k;
          return `<div class="row"><span>Personnel: ${escHtml(pName)}</span><span>PHP ${val.toLocaleString()}</span></div>`;
        }).join('')}
        <div class="row"><span>Assigned Staff (${assignments.length} @ PHP 1,000/head)</span><span>PHP ${staffTotal.toLocaleString()}</span></div>

        ${assignments.length > 0 ? `
          <div style="padding: 6px 8px; background: #fafafa; border-radius: 6px; margin: 6px 0;">
            ${assignments.map(a => `
              <div style="display:flex; justify-content:space-between; font-size:10px; color:#555; padding:2px 0;">
                <span>${escHtml(a.staffName || a.staffId || 'Staff Member')}</span>
                <span>PHP 1,000</span>
              </div>
            `).join('')}
          </div>
        ` : ''}

        <div class="row"><span>Dishes & Ingredients Expenses</span><span>PHP ${dishesIngredientsExpense.toLocaleString()}</span></div>
        <div class="total-row">
          <span>Total Operational Expenses</span>
          <span style="color:#b91c1c;">PHP ${totExp.toLocaleString()}</span>
        </div>
      </div>

      <div class="highlight-profit">
        <div>
          <div style="font-size:10px; font-weight:800; text-transform:uppercase; color:#15803d; letter-spacing:0.5px;">Net Profit</div>
          <div style="font-size:10px; color:#555;">Total Revenue - Total Expenses</div>
        </div>
        <div style="text-align:right;">
          <div style="font-size:20px; font-weight:800; color:#15803d;">PHP ${profit.toLocaleString()}</div>
          <div style="font-size:10px; font-weight:700; color:#15803d;">Margin: ${profitMargin}%</div>
        </div>
      </div>

      <div class="card">
        <div class="card-title">Logged Equipment Incidents (${incidents.length})</div>
        ${incidents.length === 0 ? `
          <div style="color:#666; font-size:11px; padding:6px 0;">No incidents reported for this event. All equipment returned safely.</div>
        ` : `
          <table>
            <thead>
              <tr>
                <th>Equipment</th>
                <th>Phase</th>
                <th style="text-align:center;">Qty</th>
                <th style="text-align:right;">Type</th>
              </tr>
            </thead>
            <tbody>
              ${incidents.map(inc => `
                <tr>
                  <td><strong>${escHtml(inc.equipment_name || 'Equipment')}</strong></td>
                  <td>${escHtml(inc.phase || 'Execution')}</td>
                  <td style="text-align:center;">${inc.quantity || 1}</td>
                  <td style="text-align:right; font-weight:700; text-transform:uppercase;">${escHtml(inc.incident_type || 'Broken')}</td>
                </tr>
              `).join('')}
            </tbody>
          </table>
        `}
      </div>
    </div>
  </div>

  <!-- BATCH ALLOCATION EQUIPMENT MANIFEST TABLE -->
  <div class="card">
    <div class="card-title">Batch Allocation Equipment Manifest (${batchAllocations.length} Items Deployed)</div>
    ${batchAllocations.length === 0 ? `
      <div style="color:#666; font-size:11px; padding:8px 0; text-align:center;">No equipment allocation recorded for this event.</div>
    ` : `
      <table>
        <thead>
          <tr>
            <th>Equipment Name</th>
            <th>Asset ID</th>
            <th style="text-align:center;">Allocated Qty</th>
            <th style="text-align:center;">Unit</th>
            <th style="text-align:right;">Category Type</th>
          </tr>
        </thead>
        <tbody>
          ${batchAllocations.map(item => {
            const eqName = item.equipment_name || item.name || 'Equipment';
            const assetId = item.equipment_id || item.asset_id || item.assetId || '-';
            const qty = item.allocated_qty || item.quantity || 1;
            const unit = item.unit_type || item.unit || 'sets';
            const isCons = !!item.consumable;
            return `
              <tr>
                <td><strong>${escHtml(eqName)}</strong></td>
                <td style="font-family:monospace; color:#555;">${escHtml(assetId)}</td>
                <td style="text-align:center; font-weight:700;">${qty}</td>
                <td style="text-align:center; color:#555;">${escHtml(unit)}</td>
                <td style="text-align:right; font-weight:600; text-transform:uppercase;">${isCons ? 'Consumable' : 'Equipment'}</td>
              </tr>
            `;
          }).join('')}
        </tbody>
      </table>
    `}
  </div>

  <div class="footer-note">
    Official settlement and administrative record generated by Halden's Catering Services system.
    Printed on ${new Date().toLocaleString('en-PH', { dateStyle: 'full', timeStyle: 'short' })}.
  </div>

  <script>
    setTimeout(function() {
      window.print();
    }, 400);
  <\/script>
</body>
</html>`;

  printWindow.document.open();
  printWindow.document.write(html);
  printWindow.document.close();
};

// =====================================================================
// DECOR FULLSCREEN PANEL LOGIC
// =====================================================================
function openDecorPanel() {
  const res = RESERVATIONS.find(r => r.id === activeResDetailId);
  if (!res) { alert('Please select a reservation first.'); return; }
  const panel = document.getElementById('proc-decor-detail-panel');
  if (panel) panel.style.display = 'flex';
  renderDecorPanel();
}

function closeDecorPanel() {
  const panel = document.getElementById('proc-decor-detail-panel');
  if (panel) panel.style.display = 'none';
}

async function renderDecorPanel() {
  const res = RESERVATIONS.find(r => r.id === activeResDetailId);
  const subEl = document.getElementById('pdd-sub');
  const bodyEl = document.getElementById('pdd-body');
  if (!res || !subEl || !bodyEl) return;

  subEl.textContent = `${res.client} - ${res.type || 'Event'} (${res.date}) : ${res.pax} pax`;
  bodyEl.innerHTML = '<div style="text-align:center;padding:80px;color:var(--text-dim);">Loading...</div>';

  const procData = await fetchProcurementData(res.id);
  const itemNames = (res.packageItems || []).map(ri => typeof ri === 'string' ? ri : (ri && ri.name ? ri.name : ''));
  const items = itemNames.map(n => CAT.find(c => c.name === n)).filter(Boolean);
  const decorItems = items.filter(i => i.cat === 'decoration' && i.name !== 'Letter Standee');

  if (!decorItems.length) {
    bodyEl.innerHTML = '<div style="text-align:center;padding:100px;color:var(--text-dim);">No aesthetic items in this package.</div>';
    return;
  }

  const supplierGroups = {};
  const nonSupplierItems = [];
  let totalCost = 0;

  decorItems.forEach(item => {
    const components = DECOR_COMPONENTS[item.name] || [];
    if (components.length > 0) {
      components.forEach(c => {
        totalCost += c.cost;
        if (c.supplier) {
          if (!supplierGroups[c.supplier]) supplierGroups[c.supplier] = [];
          supplierGroups[c.supplier].push({ item: item.name, ...c });
        } else {
          nonSupplierItems.push({ item: item.name, ...c });
        }
      });
    } else {
      totalCost += item.price || 0;
      nonSupplierItems.push({ item: item.name, name: item.name, cost: item.price || 0 });
    }
  });

  const cancelledItems = [];
  Object.keys(procData.poStatuses || {}).forEach(sup => {
    if (procData.poStatuses[sup] === 'Cancelled' && supplierGroups[sup]) {
      supplierGroups[sup].forEach(c => cancelledItems.push({ ...c, originalSupplier: sup }));
      delete supplierGroups[sup];
    }
  });

  const finalizedCost = res.finalizedDecorCost || 0;

  let html = `
    <div style="display:grid; grid-template-columns: repeat(4, 1fr); gap:16px; margin-bottom:24px;">
      <div style="background:rgba(255,255,255,0.02); border:1px solid var(--border); padding:20px; border-radius:12px;">
        <div style="font-size:24px; font-weight:700; color:var(--cream);">₱${totalCost.toLocaleString()}</div>
        <div style="font-size:10px; color:var(--text-dim); text-transform:uppercase; letter-spacing:1px; margin-top:4px;">Est. Total Cost</div>
      </div>
      <div style="background:rgba(255,255,255,0.02); border:1px solid ${finalizedCost > 0 ? 'rgba(74,222,128,0.3)' : 'var(--border)'}; padding:20px; border-radius:12px;">
        <div style="font-size:24px; font-weight:700; color:${finalizedCost > 0 ? '#4ade80' : 'var(--cream)'};">${finalizedCost > 0 ? '₱' + finalizedCost.toLocaleString() : 'PENDING'}</div>
        <div style="font-size:10px; color:${finalizedCost > 0 ? '#4ade80' : 'var(--text-dim)'}; text-transform:uppercase; letter-spacing:1px; margin-top:4px;">PO Finalized Cost</div>
      </div>
      <div style="background:rgba(255,255,255,0.02); border:1px solid var(--border); padding:20px; border-radius:12px;">
        <div style="font-size:24px; font-weight:700; color:var(--cream);">${Object.keys(supplierGroups).length}</div>
        <div style="font-size:10px; color:var(--text-dim); text-transform:uppercase; letter-spacing:1px; margin-top:4px;">Suppliers</div>
      </div>
      <div style="background:rgba(255,255,255,0.02); border:1px solid var(--border); padding:20px; border-radius:12px;">
        <div style="font-size:24px; font-weight:700; color:var(--cream);">${nonSupplierItems.length + cancelledItems.length}</div>
        <div style="font-size:10px; color:var(--text-dim); text-transform:uppercase; letter-spacing:1px; margin-top:4px;">Shopping Items</div>
      </div>
    </div>
  `;

  html += `<div style="display:grid; grid-template-columns: 3fr 1fr; gap:32px;">`;

  // Left col
  html += `<div>`;

  html += `<div style="font-size:11px; color:var(--text-dim); text-transform:uppercase; letter-spacing:1px; margin-bottom:16px; border-bottom:1px solid var(--border); padding-bottom:8px;">Vendor Purchase Orders</div>`;

  if (Object.keys(supplierGroups).length === 0) {
    html += `<div style="padding:40px; text-align:center; color:var(--text-dim); border:1px dashed var(--border); border-radius:12px;">No 3rd-party vendor items for this package.</div>`;
  } else {
    html += `<div style="display:flex; flex-direction:column; gap:16px;">`;
    Object.keys(supplierGroups).sort().forEach(sup => {
      const items = supplierGroups[sup];
      let supTotal = 0;
      items.forEach(c => supTotal += c.cost);

      const status = procData.poStatuses?.[sup] || 'Draft';

      let badgeStyle = `background:rgba(255,255,255,0.1); color:var(--cream);`;
      if (status === 'Completed') badgeStyle = `background:rgba(74,222,128,0.2); color:#4ade80; border:1px solid rgba(74,222,128,0.3);`;
      else if (status === 'Cancelled') badgeStyle = `background:rgba(239,68,68,0.2); color:#ef4444; border:1px solid rgba(239,68,68,0.3);`;
      else if (status === 'Pending') badgeStyle = `background:rgba(250,204,21,0.2); color:#facc15; border:1px solid rgba(250,204,21,0.3);`;

      html += `<div style="background:rgba(196,154,60,0.03); border:1px solid rgba(196,154,60,0.2); border-radius:12px; padding:24px;">`;
      html += `
        <div style="display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:20px;">
          <div>
            <div style="font-size:18px; font-weight:700; color:var(--gold); margin-bottom:6px;">${escHtml(sup)}</div>
            <div style="display:inline-block; padding:4px 10px; border-radius:4px; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:1px; ${badgeStyle}">${status}</div>
          </div>
          <div style="background:rgba(196,154,60,0.1); padding:8px 16px; border-radius:8px; font-size:18px; font-weight:800; color:var(--cream);">₱${supTotal.toLocaleString()}</div>
        </div>
      `;

      html += `<table style="width:100%; border-collapse:collapse; margin-bottom:24px;">
        <thead>
          <tr style="border-bottom:1px solid rgba(255,255,255,0.1);">
            <th style="text-align:left; padding:8px 0; font-size:10px; color:var(--text-dim); text-transform:uppercase;">Component</th>
            <th style="text-align:left; padding:8px 0; font-size:10px; color:var(--text-dim); text-transform:uppercase;">Item</th>
            <th style="text-align:right; padding:8px 0; font-size:10px; color:var(--text-dim); text-transform:uppercase;">Cost</th>
          </tr>
        </thead>
        <tbody>
      `;
      items.forEach(c => {
        html += `<tr style="border-bottom:1px solid rgba(255,255,255,0.05);">
          <td style="padding:12px 0; font-size:13px; color:var(--cream);">${escHtml(c.name)}</td>
          <td style="padding:12px 0; font-size:12px; color:var(--text-mid);">${escHtml(c.item)}</td>
          <td style="padding:12px 0; font-size:13px; font-weight:700; color:var(--gold); text-align:right;">₱${c.cost.toLocaleString()}</td>
        </tr>`;
      });
      html += `</tbody></table>`;

      html += `<div style="border-top:1px solid rgba(255,255,255,0.1); padding-top:16px; display:flex; justify-content:space-between; align-items:center;">`;
      if (status === 'Pending') {
        html += `
          <div style="font-size:12px; color:var(--text-dim);">Awaiting supplier confirmation</div>
          <div style="display:flex; gap:10px;">
            <button onclick="handleDecorPOCancelled('${sup.replace(/'/g, "\\'")}')" style="background:#dc2626; border:none; color:#ffffff; padding:8px 16px; border-radius:6px; font-size:12px; font-weight:700; cursor:pointer;">✖ Order Cancelled</button>
            <button onclick="handleDecorPOReceived('${sup.replace(/'/g, "\\'")}')" style="background:#16a34a; border:none; color:#ffffff; padding:8px 16px; border-radius:6px; font-size:12px; font-weight:700; cursor:pointer;">✓ Order Received</button>
          </div>
        `;
      } else if (status === 'Completed') {
        html += `<div style="width:100%; background:rgba(74,222,128,0.1); color:#4ade80; padding:12px; border-radius:6px; text-align:center; font-size:12px; font-weight:700;">✓ PO Completed &amp; Cost Finalized at ₱${supTotal.toLocaleString()}</div>`;
      } else if (status === 'Cancelled') {
        html += `<div style="width:100%; background:rgba(239,68,68,0.1); color:#ef4444; padding:12px; border-radius:6px; text-align:center; font-size:12px; font-weight:700;">✖ PO Cancelled - Items moved to shopping list</div>`;
      } else {
        html += `
          <div style="font-size:12px; color:var(--text-dim);">Draft Stage</div>
          <button class="btn-primary" onclick="exportDecorPO('${sup.replace(/'/g, "\\'")}')">Generate &amp; Export PO</button>
        `;
      }
      html += `</div></div>`;
    });
    html += `</div>`;
  }
  html += `</div>`; // End left col

  // Right col (Shopping list)
  html += `<div>`;
  html += `<div style="font-size:11px; color:var(--text-dim); text-transform:uppercase; letter-spacing:1px; margin-bottom:16px; border-bottom:1px solid var(--border); padding-bottom:8px;">General Shopping / Market</div>`;

  const allShop = [...nonSupplierItems, ...cancelledItems];
  if (allShop.length === 0) {
    html += `<div style="padding:40px; text-align:center; color:var(--text-dim); border:1px dashed var(--border); border-radius:12px;">No shopping items needed.</div>`;
  } else {
    html += `<div style="display:flex; flex-direction:column; gap:12px;">`;
    allShop.forEach(c => {
      const isCancelled = !!c.originalSupplier;
      html += `
        <div style="background:rgba(255,255,255,0.02); border:1px solid ${isCancelled ? 'rgba(239,68,68,0.3)' : 'var(--border)'}; border-radius:8px; padding:12px;">
          <div style="display:flex; justify-content:space-between; margin-bottom:4px;">
            <div style="font-size:13px; font-weight:700; color:var(--cream);">${escHtml(c.name)}</div>
            <div style="font-size:13px; font-weight:700; color:var(--gold);">₱${c.cost.toLocaleString()}</div>
          </div>
          <div style="font-size:11px; color:var(--text-dim);">For: ${escHtml(c.item)}</div>
          ${isCancelled ? `<div style="font-size:10px; color:#ef4444; margin-top:6px;"> Cancelled from ${escHtml(c.originalSupplier)}</div>` : ''}
        </div>
      `;
    });
    html += `</div>`;
  }
  html += `</div>`; // End right col

  html += `</div>`; // End grid

  bodyEl.innerHTML = html;
}

window.openDecorPanel = openDecorPanel;
window.closeDecorPanel = closeDecorPanel;

async function exportDecorPO(supplierName) {
  const res = RESERVATIONS.find(r => r.id === activeResDetailId);
  if (!res) return;

  // Immediately set PO status to Pending
  try {
    const { updateDoc, doc } = window.firebaseFns;
    await updateDoc(doc(window.firebaseDB, 'procurement', res.id), {
      [`poStatuses.${supplierName}`]: 'Pending'
    });
  } catch (e) { console.error('Failed to set PO status to Pending:', e); }

  renderProcurementTab();
  if (document.getElementById('proc-decor-detail-panel').style.display === 'flex') {
    openDecorPanel();
  }

  alert(`Decor Purchase Order generated for ${supplierName}. Status set to PENDING.`);
}
window.exportDecorPO = exportDecorPO;

async function handleDecorPOReceived(supplier) {
  const res = RESERVATIONS.find(r => r.id === activeResDetailId);
  if (!res) return;
  if (!confirm(`Mark the decor order from "${supplier}" as RECEIVED and finalize its cost?`)) return;

  // Calculate cost
  const itemNames = (res.packageItems || []).map(ri => typeof ri === 'string' ? ri : (ri && ri.name ? ri.name : ''));
  const items = itemNames.map(n => CAT.find(c => c.name === n)).filter(Boolean);
  const decorItems = items.filter(i => i.cat === 'decoration' && i.name !== 'Letter Standee');

  let supplierTotal = 0;
  decorItems.forEach(item => {
    const components = DECOR_COMPONENTS[item.name] || [];
    components.forEach(c => {
      if (c.supplier === supplier) supplierTotal += c.cost;
    });
  });

  try {
    const { updateDoc, doc } = window.firebaseFns;

    await updateDoc(doc(window.firebaseDB, 'procurement', res.id), {
      [`poStatuses.${supplier}`]: 'Completed'
    });

    const currentTotal = res.finalizedDecorCost || 0;
    const newTotal = currentTotal + supplierTotal;

    await updateDoc(doc(window.firebaseDB, 'reservations', res.id), {
      finalizedDecorCost: newTotal
    });

    res.finalizedDecorCost = newTotal;

  } catch (e) {
    console.error('Failed to update PO status:', e);
    alert('Failed to update PO status. See console.');
  }

  renderProcurementTab();
  if (document.getElementById('proc-decor-detail-panel').style.display === 'flex') {
    openDecorPanel();
  }
}
window.handleDecorPOReceived = handleDecorPOReceived;

async function handleDecorPOCancelled(supplier) {
  const res = RESERVATIONS.find(r => r.id === activeResDetailId);
  if (!res) return;
  if (!confirm(`Cancel the decor order from "${supplier}"? Items will be moved to the General Shopping List.`)) return;

  try {
    const { updateDoc, doc } = window.firebaseFns;
    await updateDoc(doc(window.firebaseDB, 'procurement', res.id), {
      [`poStatuses.${supplier}`]: 'Cancelled'
    });
  } catch (e) {
    console.error('Failed to cancel PO:', e);
    alert('Failed to cancel PO. See console.');
  }

  renderProcurementTab();
  if (document.getElementById('proc-decor-detail-panel').style.display === 'flex') {
    openDecorPanel();
  }
}
window.handleDecorPOCancelled = handleDecorPOCancelled;

// =====================================================================
// CUSTOMER PROVIDED EQUIPMENT - SAVE
// =====================================================================
window.saveMtModeCustomerEquip = async function () {
  const res = RESERVATIONS.find(r => r.id === activeResDetailId);
  if (!res) { alert('No active reservation selected.'); return; }

  const getNum = id => parseInt(document.getElementById(id)?.value || '0') || 0;
  const getStr = id => document.getElementById(id)?.value?.trim() || '';

  const cpe = {
    tables: getNum('cpe-tables'),
    chairs: getNum('cpe-chairs'),
    plates: getNum('cpe-plates'),
    forks: getNum('cpe-forks'),
    spoons: getNum('cpe-spoons'),
    knives: getNum('cpe-knives'),
    glasses: getNum('cpe-glasses'),
    chafing: getNum('cpe-chafing'),
    dispensers: getNum('cpe-dispensers'),
    other: getStr('cpe-other'),
    savedAt: new Date().toISOString()
  };

  try {
    const { updateDoc, doc } = window.firebaseFns;
    await updateDoc(doc(window.firebaseDB, 'reservations', res.id), {
      customerProvidedEquip: cpe
    });
    res.customerProvidedEquip = cpe;
    alert('Customer provided equipment saved successfully!');
  } catch (e) {
    console.error('Failed to save customer equipment:', e);
    alert('Failed to save. See console for details.');
  }
};

// =====================================================================
// EQUIPMENT CYCLE - INNER SUB-TAB NAVIGATION
// =====================================================================
window.switchEqCycleTab = function (tabKey, btn) {
  // Update tab button styles
  document.querySelectorAll('.eq-cycle-tab').forEach(t => {
    t.classList.remove('active');
    t.style.borderBottomColor = 'transparent';
    t.style.color = 'var(--text-mid)';
  });
  if (btn) {
    btn.classList.add('active');
    btn.style.borderBottomColor = 'var(--gold)';
    btn.style.color = 'var(--gold)';
  }

  // Hide all panels
  document.querySelectorAll('.eqc-panel').forEach(p => p.style.display = 'none');

  // Show the selected panel
  const panel = document.getElementById(`eqc-panel-${tabKey}`);
  if (!panel) return;
  panel.style.display = 'block';

  // Copy HTML from standalone section if panel is empty, without destroying original HTML
  const source = document.getElementById(`section-${tabKey}`);
  if (source && (!panel.dataset.loaded || !panel.innerHTML.trim())) {
    panel.innerHTML = source.innerHTML;
    panel.dataset.loaded = 'true';
  }

  // Re-run any init functions that the section needs
  if (tabKey === 'allocation' && typeof renderAllocationSection === 'function') renderAllocationSection();
  if (tabKey === 'scheduling' && typeof renderSchedulingSection === 'function') renderSchedulingSection();
  if (tabKey === 'lifecycle' && typeof renderLifecycleSection === 'function') renderLifecycleSection();
  if (tabKey === 'equip-issues' && typeof renderEquipIssues === 'function') renderEquipIssues();
  if (tabKey === 'rentals') renderRentalHub();
};



// =====================================================================
// EQUIPMENT CYCLE - MANIFEST QR CODE GENERATOR
// =====================================================================
window.generateSchedQR = function () {
  const res = RESERVATIONS.find(r => r.id === currentEqcReservationId);
  if (!res) { alert('No reservation selected.'); return; }
  const manifest = res.equipmentManifest ||
    (_schedAssignRows.length > 0 ? _schedAssignRows.map(r => ({ name: r.name, assignedQty: r.assignQty })) : null);
  if (!manifest || manifest.length === 0) { alert('No equipment assignment found. Save an assignment first.'); return; }
  const lines = manifest.map(item => item.name + ': ' + (item.assignedQty !== undefined ? item.assignedQty : (item.assignQty || 0)) + ' unit(s)');
  const nl = String.fromCharCode(10);
  const payload = 'HALDENS-EQUIP-MANIFEST' + nl + 'Reservation: ' + (res.client || res.name) + nl + 'Date: ' + res.date + nl + 'Pax: ' + res.pax + nl + '---' + nl + lines.join(nl);
  document.getElementById('qrModalTitle').textContent = 'Equipment Manifest QR';
  document.getElementById('qrModalSubtitle').textContent = 'Assigned equipment for ' + (res.client || res.name);
  document.getElementById('qrLabelId').textContent = res.id;
  document.getElementById('qrLabelName').textContent = (res.client || res.name) + ' - Equipment Manifest';
  const metaRows = manifest.slice(0, 8).map(item => {
    const qty = item.assignedQty !== undefined ? item.assignedQty : (item.assignQty || 0);
    return '<div style="display:flex;justify-content:space-between;font-size:11px;">' +
      '<span style="color:var(--text-dim);">' + item.name + '</span>' +
      '<span style="color:var(--gold);font-weight:500;">' + qty + ' units</span></div>';
  });
  if (manifest.length > 8) metaRows.push('<div style="font-size:10px;color:var(--text-dim);text-align:center;margin-top:4px;">+' + (manifest.length - 8) + ' more items</div>');
  document.getElementById('qrModalMeta').innerHTML = metaRows.join('');
  const qrContainer = document.getElementById('qrcode');
  qrContainer.innerHTML = '';
  try {
    if (typeof QRCode !== 'undefined') {
      new QRCode(qrContainer, { text: payload, width: 200, height: 200, colorDark: '#111111', colorLight: '#ffffff', correctLevel: QRCode.CorrectLevel.L });
    } else if (typeof drawFallbackCanvas === 'function') { drawFallbackCanvas(qrContainer, payload); }
  } catch (e) { if (typeof drawFallbackCanvas === 'function') drawFallbackCanvas(qrContainer, payload); }
  currentQRData = { id: res.id, name: res.client || res.name, category: 'Equipment Manifest', isIndividual: false };
  const modal = document.getElementById('qrModal');
  const modalContent = document.getElementById('qrModalContent');
  if (modal) { modal.style.display = 'flex'; modal.classList.add('on'); }
  if (modalContent) modalContent.classList.add('open');
  document.body.style.overflow = 'hidden';
};

window.generateBatchQRForCurrentManifest = async function () {
  const ev = currentAllocEvent;
  if (!ev) { showToast('No reservation selected.', 'error'); return; }
  const batchName = _genBatchName(ev);
  await generateBatchQR(batchName, ev.id);
};

window.generateBatchQR = async function (batchName, resId) {
  const res = RESERVATIONS.find(r => r.id === resId);
  if (!res) { alert('No reservation found.'); return; }

  const sb = window.supabaseClient;
  if (!sb) { alert('Supabase not available.'); return; }

  const { data, error } = await sb
    .from('allocation_history')
    .select('equipment_name, allocated_qty, is_rental')
    .eq('allocation_batch', batchName)
    .eq('reservation_id', resId);

  if (error || !data || data.length === 0) {
    alert('No batch allocation found. Save the allocation first.');
    return;
  }

  // Generate direct URL pointing to scan.html with batch & reservation params
  const scanUrl = window.location.origin + window.location.pathname.replace(/admin\.html.*$/i, '') + 'scan.html?alloc_batch=' + encodeURIComponent(batchName) + (resId ? '&res_id=' + encodeURIComponent(resId) : '');
  const payload = scanUrl;

  document.getElementById('qrModalTitle').textContent = 'Batch Allocation QR';
  document.getElementById('qrModalSubtitle').textContent = 'Allocation batch: ' + batchName;
  document.getElementById('qrLabelId').textContent = batchName;
  document.getElementById('qrLabelName').textContent = (res.client || res.name) + ' - Batch Allocation';

  const metaRows = data.slice(0, 8).map(item => {
    return '<div style="display:flex;justify-content:space-between;font-size:11px;">' +
      '<span style="color:var(--text-dim);">' + item.equipment_name + (item.is_rental ? ' <span style="color:var(--gold);font-size:9px;">[RENTAL]</span>' : '') + '</span>' +
      '<span style="color:var(--gold);font-weight:500;">' + item.allocated_qty + ' units</span></div>';
  });
  if (data.length > 8) metaRows.push('<div style="font-size:10px;color:var(--text-dim);text-align:center;margin-top:4px;">+' + (data.length - 8) + ' more items</div>');

  // Redirection button to open scan area
  metaRows.push('<div style="margin-top:14px;text-align:center;"><a href="' + scanUrl + '" target="_blank" style="display:inline-flex;align-items:center;gap:6px;padding:8px 16px;background:var(--gold);color:#0e0b07;font-weight:700;font-size:12px;border-radius:6px;text-decoration:none;"><i class="fas fa-qrcode"></i> Open in Equipment Scan Area &rarr;</a></div>');

  document.getElementById('qrModalMeta').innerHTML = metaRows.join('');
  const qrContainer = document.getElementById('qrcode');
  qrContainer.innerHTML = '';
  try {
    if (typeof QRCode !== 'undefined') {
      new QRCode(qrContainer, { text: payload, width: 200, height: 200, colorDark: '#111111', colorLight: '#ffffff', correctLevel: QRCode.CorrectLevel.L });
    } else if (typeof drawFallbackCanvas === 'function') { drawFallbackCanvas(qrContainer, payload); }
  } catch (e) { if (typeof drawFallbackCanvas === 'function') drawFallbackCanvas(qrContainer, payload); }

  currentQRData = { id: batchName, name: res.client || res.name, category: 'Batch Allocation', isIndividual: false };
  const modal = document.getElementById('qrModal');
  const modalContent = document.getElementById('qrModalContent');
  if (modal) { modal.style.display = 'flex'; modal.classList.add('on'); }
  if (modalContent) modalContent.classList.add('open');
  document.body.style.overflow = 'hidden';
};

window.openEquipmentCycleScheduling = function (reservationId) {
  const navBtn = document.getElementById('nav-equip-cycle');
  if (typeof showSection === 'function' && navBtn) showSection('equip-cycle', navBtn);
  currentEqcReservationId = reservationId;
  const sel = document.getElementById('eqc-reservation-select');
  if (sel) {
    if (typeof populateEqcDropdown === 'function') populateEqcDropdown();
    sel.value = reservationId;
    currentEqcReservationId = reservationId;
  }
  setTimeout(function () {
    const allocBtn = document.getElementById('eqc-tab-allocation') || document.getElementById('eqc-tab-scheduling');
    if (allocBtn && typeof switchEqCycleTab === 'function') switchEqCycleTab('allocation', allocBtn);
  }, 150);
};

