let sbMenuItems = [];
let adminThemesData = [];
let sbPremadePackages = [];
let sbPremadePackageItems = [];
let sbEventSetups = [];

// Expose to window so equipment disable-check can reference them
window.sbPremadePackages = sbPremadePackages;
window.sbPremadePackageItems = sbPremadePackageItems;
window.sbEventSetups = sbEventSetups;

