let _adminReviewsFilterStar = 'all';

function setAdminReviewsFilter(star, btn) {
  _adminReviewsFilterStar = star || 'all';
  document.querySelectorAll('#reviews-filter-chips .cat-filter-chip').forEach(c => c.classList.remove('active'));
  if (btn) btn.classList.add('active');
  renderAdminReviewsList();
}
window.setAdminReviewsFilter = setAdminReviewsFilter;

async function renderAdminReviewsList() {
  const container = document.getElementById('admin-reviews-list-container');
  if (!container) return;

  const sb = window.supabaseClient;
  let reviews = [];

  if (sb) {
    // 1. Try customer_feedbacks table
    try {
      const { data, error } = await sb
        .from('customer_feedbacks')
        .select('*')
        .order('created_at', { ascending: false });
      if (data && data.length) {
        reviews = data;
      }
    } catch(e) {}

    // 2. Query reservations in Supabase where execution_plan has customer_feedback
    try {
      const { data: resList } = await sb
        .from('reservations')
        .select('id, client_name, package_name, execution_plan, created_at');
      if (Array.isArray(resList)) {
        resList.forEach(r => {
          if (!r.execution_plan) return;
          let exec = null;
          try {
            exec = typeof r.execution_plan === 'object' ? r.execution_plan : JSON.parse(r.execution_plan);
          } catch(e) {}
          if (exec && exec.customer_feedback) {
            const fb = exec.customer_feedback;
            const rId = String(r.id);
            if (!reviews.some(x => String(x.reservation_id || x.id) === rId)) {
              reviews.push({
                id: rId,
                reservation_id: rId,
                client_name: fb.client_name || r.client_name || 'Valued Client',
                package_name: fb.package_name || r.package_name || 'Catering Package',
                rating: fb.rating || 5,
                comment: fb.comment || '',
                created_at: fb.saved_at || r.created_at || new Date().toISOString(),
                is_hidden: fb.is_hidden === true
              });
            }
          }
        });
      }
    } catch(e) {
      console.warn('[renderAdminReviewsList] reservations fetch notice:', e);
    }
  }

  // Merge with localStorage
  try {
    const localFeedbacks = JSON.parse(localStorage.getItem('all_customer_feedbacks') || '[]');
    if (Array.isArray(localFeedbacks)) {
      localFeedbacks.forEach(lf => {
        if (!reviews.some(r => String(r.id || r.reservation_id) === String(lf.id || lf.reservation_id))) {
          reviews.push(lf);
        }
      });
    }
  } catch(e) {}

  // Read hidden IDs from localStorage
  let hiddenIds = new Set();
  try {
    const rawHidden = JSON.parse(localStorage.getItem('hidden_feedback_ids') || '[]');
    if (Array.isArray(rawHidden)) hiddenIds = new Set(rawHidden.map(String));
  } catch(e) {}

  // Filter by star rating
  if (_adminReviewsFilterStar !== 'all') {
    const targetStar = parseInt(_adminReviewsFilterStar, 10);
    reviews = reviews.filter(r => (parseInt(r.rating || r.stars, 10) || 5) === targetStar);
  }

  // Filter by search text
  const searchInput = document.getElementById('admin-reviews-search');
  const q = searchInput ? (searchInput.value || '').toLowerCase().trim() : '';
  if (q) {
    reviews = reviews.filter(r => {
      const cName = (r.client_name || r.name || '').toLowerCase();
      const pName = (r.package_name || r.packageName || '').toLowerCase();
      const comment = (r.comment || r.feedback || r.review || '').toLowerCase();
      return cName.includes(q) || pName.includes(q) || comment.includes(q);
    });
  }

  if (reviews.length === 0) {
    container.innerHTML = '<div style="text-align:center; padding:60px 20px; color:var(--text-dim); font-size:13px;">No customer reviews found matching filter.</div>';
    return;
  }

  let html = '<table class="data-table" style="font-size:12px; width:100%; border-collapse:collapse;">';
  html += '<thead><tr style="border-bottom:1px solid var(--border);">';
  html += '<th style="text-align:left; padding:10px 14px;">Client Name</th>';
  html += '<th style="text-align:left; padding:10px 14px;">Package</th>';
  html += '<th style="text-align:center; padding:10px 14px;">Rating</th>';
  html += '<th style="text-align:left; padding:10px 14px; min-width:240px;">Customer Review</th>';
  html += '<th style="text-align:left; padding:10px 14px;">Submitted Date</th>';
  html += '<th style="text-align:center; padding:10px 14px;">Web Visibility</th>';
  html += '<th style="text-align:right; padding:10px 14px;">Action</th>';
  html += '</tr></thead><tbody>';

  reviews.forEach(r => {
    const fId = String(r.id || r.reservation_id || '');
    const isHidden = r.is_hidden === true || r.hidden_from_web === true || hiddenIds.has(fId);
    const starCount = Math.max(1, Math.min(5, parseInt(r.rating || r.stars, 10) || 5));
    const starsStr = '★'.repeat(starCount) + '☆'.repeat(5 - starCount);
    const cName = r.client_name || r.name || 'Valued Customer';
    const pName = r.package_name || r.packageName || 'Catering Package';
    const comment = r.comment || r.feedback || r.review || 'No comment provided.';
    const dateVal = r.created_at || r.saved_at || r.date || new Date().toISOString().split('T')[0];
    const dStr = typeof dateVal === 'string' ? dateVal.split('T')[0] : new Date(dateVal).toISOString().split('T')[0];

    html += '<tr style="border-bottom:1px solid rgba(255,255,255,0.04);">';
    html += '<td style="padding:10px 14px; font-weight:700; color:var(--cream);">' + escHtml(cName) + '</td>';
    html += '<td style="padding:10px 14px; color:var(--gold);">' + escHtml(pName) + '</td>';
    html += '<td style="padding:10px 14px; text-align:center; color:#c49a3c; font-weight:700; letter-spacing:1px;">' + starsStr + ' <span style="font-size:11px; color:var(--text-dim);">(' + starCount + '.0)</span></td>';
    html += '<td style="padding:10px 14px; color:var(--text); font-style:italic;">"' + escHtml(comment) + '"</td>';
    html += '<td style="padding:10px 14px; color:var(--text-dim); font-size:11px;">' + dStr + '</td>';
    html += '<td style="padding:10px 14px; text-align:center;">' + (isHidden ? '<span style="color:var(--text-dim); font-size:11px; font-weight:600;">Hidden from Web</span>' : '<span style="color:var(--green,#2d8a4e); font-size:11px; font-weight:700;">Visible on Web</span>') + '</td>';
    html += '<td style="padding:10px 14px; text-align:right;">';
    if (isHidden) {
      html += '<button type="button" class="btn-primary" style="font-size:11px; padding:4px 12px; font-weight:700; background:#2563eb; color:#ffffff; border:none;" onclick="toggleReviewWebVisibility(\'' + fId + '\', false)">Unhide</button>';
    } else {
      html += '<button type="button" class="btn-secondary" style="font-size:11px; padding:4px 12px; font-weight:700; background:#4b5563; color:#ffffff; border:none;" onclick="toggleReviewWebVisibility(\'' + fId + '\', true)">Hide from web</button>';
    }
    html += '</td>';
    html += '</tr>';
  });

  html += '</tbody></table>';
  container.innerHTML = html;
}
window.renderAdminReviewsList = renderAdminReviewsList;

async function toggleReviewWebVisibility(feedbackId, shouldHide) {
  if (!feedbackId) return;

  // 1. Update localStorage hidden_feedback_ids
  try {
    const rawHidden = JSON.parse(localStorage.getItem('hidden_feedback_ids') || '[]');
    let hiddenSet = new Set(Array.isArray(rawHidden) ? rawHidden.map(String) : []);
    if (shouldHide) {
      hiddenSet.add(String(feedbackId));
    } else {
      hiddenSet.delete(String(feedbackId));
    }
    localStorage.setItem('hidden_feedback_ids', JSON.stringify(Array.from(hiddenSet)));
  } catch(e) {}

  // 2. Update Supabase if available (both customer_feedbacks table and reservations.execution_plan)
  const sb = window.supabaseClient;
  if (sb) {
    try {
      await sb.from('customer_feedbacks')
        .update({ is_hidden: shouldHide, updated_at: new Date().toISOString() })
        .or('id.eq.' + feedbackId + ',reservation_id.eq.' + feedbackId);
    } catch(e) {}

    try {
      const { data: curRes } = await sb.from('reservations').select('execution_plan').eq('id', feedbackId).maybeSingle();
      if (curRes && curRes.execution_plan) {
        let exec = typeof curRes.execution_plan === 'object' ? curRes.execution_plan : JSON.parse(curRes.execution_plan);
        if (exec.customer_feedback) {
          exec.customer_feedback.is_hidden = shouldHide;
          await sb.from('reservations').update({ execution_plan: exec }).eq('id', feedbackId);
        }
      }
    } catch(e) {
      console.warn('[toggleReviewWebVisibility] Supabase reservations update notice:', e);
    }
  }

  // 3. Re-render reviews list in Admin
  renderAdminReviewsList();

  // 4. Trigger landing page update if loaded
  if (typeof window.loadPublicClientReviews === 'function') {
    try { window.loadPublicClientReviews(); } catch(e) {}
  }
  if (typeof notifyLiveCatalogSync === 'function') {
    notifyLiveCatalogSync('REVIEWS_UPDATED');
  }
}
window.toggleReviewWebVisibility = toggleReviewWebVisibility;

