// ── SPECIAL ITEM PARENT CONNECTOR HELPER ─────────────────
function getSpecialParentName(item) {
  if (!item) return null;

  const nm = (item.name || '').toLowerCase();
  const ingRaw = typeof item.ingredients === 'string' ? item.ingredients : '';
  const isStandalone = ingRaw === 'standalone' || ingRaw.includes(' | standalone');

  // ── Step 1: True master-special items by name/identify ONLY ──
  const isMasterByIdentity =
    item.identify === 'drinks_package' ||
    item.identify === 'ice_cream' ||
    item.identify === 'special' ||
    nm.includes('mobile bar') ||
    nm.includes('unlimited drinks') ||
    nm.includes('halden\'s ice cream');

  if (isMasterByIdentity) return null;

  // ── Step 2: Hard keyword rules : ALWAYS win (Mobile Bar & Ice Cream) ──
  if (nm.includes('cocktail') || nm.includes('shooter') || nm.includes('mixes') || nm.includes('mocktail')) {
    return "Halden's Mobile Bar";
  }
  if (nm.includes('ice cream') || item.identify === 'ice_cream_option') {
    return "Halden's Ice Cream";
  }

  // ── Step 3: Master items per_ pax ──
  if (ingRaw.startsWith('per_')) return null;

  // ── Step 4: DB sub_items lookup (reads saved checkbox data from master items) ──
  for (const s of sbMenuItems) {
    const isParentMaster =
      (typeof s.ingredients === 'string' && s.ingredients.startsWith('per_')) ||
      s.identify === 'drinks_package' ||
      s.identify === 'special' ||
      s.identify === 'ice_cream' ||
      (s.name || '').toLowerCase().includes('mobile bar') ||
      (s.name || '').toLowerCase().includes('unlimited drinks') ||
      (s.name || '').toLowerCase().includes('ice cream');
    if (!isParentMaster || s.id === item.id) continue;

    if (typeof s.ingredients === 'string' && s.ingredients.includes(' | sub_items: ')) {
      const subStr = s.ingredients.split(' | sub_items: ')[1];
      if (subStr) {
        const list = subStr.split(', ').map(x => x.trim().toLowerCase());
        if (list.includes(nm)) return s.name;
      }
    }
  }

  // ── Step 5: Generic drinks fallback → Unlimited Drinks (UNLESS marked standalone) ──
  if (isStandalone) {
    return null; // Standalone flag only prevents auto-connecting to Unlimited Drinks
  }

  if ((item.identify === 'drinks' || (item.category || '').toLowerCase() === 'drinks') &&
    !nm.includes('mobile bar')) {
    return "Unlimited Drinks";
  }

  return null;
}


// ── CATALOG ITEMS & PACKAGES IMAGE RESOLVERS ─────────────
function resolveAdminItemImage(item) {
  if (!item) return 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&q=80&w=800';
  if (item.image_url) return item.image_url;
  if (item.image) return item.image;
  if (item.imageUrl) return item.imageUrl;
  if (item.photo) return item.photo;

  const itemNm = (item.name || '').trim().toLowerCase();

  // Check EIM_ASSETS array if available (priority for equipment with real uploaded images)
  if (typeof EIM_ASSETS !== 'undefined' && Array.isArray(EIM_ASSETS)) {
    const foundEq = EIM_ASSETS.find(e => e && (
      (e.id && item.id && e.id === item.id) ||
      (e.supabaseId && item.supabaseId && e.supabaseId === item.supabaseId) ||
      (e.supabaseId && item.id && String(e.supabaseId) === String(item.id)) ||
      (item.supabaseId && e.id && String(item.supabaseId) === String(e.id)) ||
      (e.name && e.name.trim().toLowerCase() === itemNm)
    ));
    if (foundEq && (foundEq.image_url || foundEq.image || foundEq.photo)) {
      return foundEq.image_url || foundEq.image || foundEq.photo;
    }
  }

  // Check CAT array if available
  if (typeof CAT !== 'undefined' && Array.isArray(CAT)) {
    const found = CAT.find(c => c && (
      (c.id && item.id && c.id === item.id) ||
      (c.supabaseId && item.supabaseId && c.supabaseId === item.supabaseId) ||
      (c.supabaseId && item.id && String(c.supabaseId) === String(item.id)) ||
      (item.supabaseId && c.id && String(item.supabaseId) === String(c.id)) ||
      (c.name && c.name.trim().toLowerCase() === itemNm)
    ));
    if (found && (found.image_url || found.image)) return found.image_url || found.image;
  }

  const ident = (item.identify || '').toLowerCase();
  const cat = (item.category || '').toLowerCase();

  // If equipment, furniture, tableware, serving, cutlery, misc
  if (ident === 'equipment' || cat === 'equipment' || cat.includes('furniture') || cat.includes('tableware') || cat.includes('serving') || cat.includes('cutlery') || cat.includes('misc')) {
    if (typeof getEquipmentImage === 'function') {
      const eqImg = getEquipmentImage(item.category, item.name);
      if (eqImg) return eqImg;
    }
  }

  // Food / Drinks / Desserts / Decor / Addon / Special
  if (typeof getFoodImage === 'function') {
    const fdImg = getFoodImage(item.category || item.identify, item.name);
    if (fdImg) return fdImg;
  }

  return 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&q=80&w=800';
}
window.resolveAdminItemImage = resolveAdminItemImage;

function resolveAdminPackageImage(p) {
  if (!p) return 'https://images.unsplash.com/photo-1464349095431-e9a21285b5ac?auto=format&fit=crop&q=80&w=800';
  if (p.image_url) return p.image_url;
  if (p.image) return p.image;
  if (p.cover_photo) return p.cover_photo;
  if (p.imageUrl) return p.imageUrl;

  // Check PKGS array if available
  if (typeof PKGS !== 'undefined' && Array.isArray(PKGS)) {
    const pkgNm = (p.name || '').trim().toLowerCase();
    const found = PKGS.find(pkg => pkg && (pkg.id === p.id || (pkg.name && pkg.name.trim().toLowerCase() === pkgNm)));
    if (found && (found.image || found.image_url)) return found.image || found.image_url;
  }

  const occ = (p.occasion || p.theme || p.name || '').toLowerCase();
  if (occ.includes('wedding')) return 'https://images.unsplash.com/photo-1511795409834-ef04bbd61622?auto=format&fit=crop&q=80&w=800';
  if (occ.includes('debut') || occ.includes('18th')) return 'https://images.unsplash.com/photo-1519225421980-715cb0215aed?auto=format&fit=crop&q=80&w=800';
  if (occ.includes('kiddie') || occ.includes('child')) return 'https://images.unsplash.com/photo-1530103043477-c7f44b4131de?auto=format&fit=crop&q=80&w=800';
  if (occ.includes('birthday')) return 'https://images.unsplash.com/photo-1464349095431-e9a21285b5ac?auto=format&fit=crop&q=80&w=800';
  if (occ.includes('corporate') || occ.includes('seminar') || occ.includes('conference')) return 'https://images.unsplash.com/photo-1511578314322-379afb476865?auto=format&fit=crop&q=80&w=800';
  if (occ.includes('christmas') || occ.includes('holiday')) return 'https://images.unsplash.com/photo-1512389142860-9c449e58a543?auto=format&fit=crop&q=80&w=800';
  if (occ.includes('baptism') || occ.includes('christening')) return 'https://images.unsplash.com/photo-1519225421980-715cb0215aed?auto=format&fit=crop&q=80&w=800';
  if (occ.includes('private') || occ.includes('dinner')) return 'https://images.unsplash.com/photo-1555244162-803834f70033?auto=format&fit=crop&q=80&w=800';

  return 'https://images.unsplash.com/photo-1464349095431-e9a21285b5ac?auto=format&fit=crop&q=80&w=800';
}
window.resolveAdminPackageImage = resolveAdminPackageImage;

// ── CATALOG ITEMS RENDERING ─────────────────────────────
function renderAdminCatalog() {
  const grid = document.getElementById('admin-catalog-grid');
  if (!grid) return;

  const searchQ = (document.getElementById('admin-cat-search')?.value || '').toLowerCase().trim();
  let items = [...sbMenuItems];
  if (typeof EIM_ASSETS !== 'undefined' && Array.isArray(EIM_ASSETS)) {
    const equipItems = (typeof EIM_ASSETS !== 'undefined' ? EIM_ASSETS : []).map(eq => ({
      id: eq.id,
      supabaseId: eq.supabaseId,
      name: eq.name,
      description: eq.notes || eq.category || '',
      identify: 'equipment',
      category: eq.category,
      price_per_pax: eq.unitCost || 0,
      is_available: !eq.is_disabled,
      image_url: eq.image_url || eq.image || null,
      image: eq.image_url || eq.image || null
    }));
    items.push(...equipItems);
  }

  if (adminCatFilter === 'special') {
    items = items.filter(i =>
      (i.ingredients || '').startsWith('per_') ||
      i.identify === 'special' ||
      i.identify === 'drinks_package' ||
      i.identify === 'ice_cream' ||
      (i.name || '').toLowerCase().includes('mobile bar') ||
      (i.name || '').toLowerCase().includes('unlimited drinks') ||
      (i.name || '').toLowerCase().includes('ice cream')
    );
  } else if (adminCatFilter !== 'all') {
    items = items.filter(i => (i.identify || '').toLowerCase() === adminCatFilter.toLowerCase());
  }

  if (searchQ) {
    items = items.filter(i =>
      String(i.name || '').toLowerCase().includes(searchQ) ||
      String(i.description || '').toLowerCase().includes(searchQ)
    );
  }

  if (items.length === 0) {
    grid.innerHTML = '<div style="text-align:center; padding:40px; color:var(--text-dim); grid-column:1/-1;">No catalog items found.</div>';
    return;
  }

  grid.innerHTML = items.map(item => {
    const isHidden = item.is_available === false;
    const isMasterSpecial = (item.ingredients || '').startsWith('per_') || item.identify === 'special' || item.identify === 'drinks_package' || item.identify === 'ice_cream' || (item.name || '').toLowerCase().includes('mobile bar') || (item.name || '').toLowerCase().includes('unlimited drinks') || (item.name || '').toLowerCase().includes('ice cream');
    const isFixedPrice = ['decoration', 'addon'].includes(item.identify);
    const itemPrice = parseFloat(item.price_per_pax) || 0;

    const connectedParent = getSpecialParentName(item);

    let priceLabel = '';
    if (connectedParent) {
      priceLabel = `Connected to ${connectedParent}`;
    } else if (isMasterSpecial) {
      const paxMatch = (item.ingredients || '').match(/per_(\d+)_pax/);
      const paxText = paxMatch ? `serves ${paxMatch[1]} pax` : 'Special Set';
      priceLabel = `₱${itemPrice.toLocaleString()} (${paxText})`;
    } else if (isFixedPrice) {
      priceLabel = `₱${itemPrice.toLocaleString()} (Fixed Price)`;
    } else {
      priceLabel = `₱${itemPrice.toLocaleString()} / pax`;
    }

    let categoryBadge = item.category || item.identify || 'General';

    const isDecor = item.identify === 'decoration' || item.category === 'Decorations';
    let ingStr = (item.ingredients || '').replace(' | standalone', '').replace(/^standalone$/, '').trim();
    let ingredientsDisplay = '';
    // Do not display raw ingredients/options box for decorations, fixed option strings, or per-pax sets
    if (!isDecor && ingStr && ingStr !== 'fixed' && !ingStr.startsWith('fixed') && !ingStr.startsWith('per_') && !ingStr.includes('options:')) {
      ingredientsDisplay = `<div style="font-size:11px; color:var(--text-dim); margin-top:6px; font-style:italic; word-break:break-word; overflow-wrap:anywhere;"><strong>Ingredients:</strong> ${ingStr}</div>`;
    }

    // Special items rendered as clean text only - colored backgrounds and badge tags removed system-wide
    let cardBorderColor = isHidden ? 'rgba(255,255,255,0.06)' : 'var(--border)';
    let cardBgColor = 'var(--bg2)';
    let specialBadgeHtml = '';
    if (isMasterSpecial) {
      let label = (item.name || "SPECIAL").toUpperCase();
      const ident = (item.identify || "").toLowerCase();
      const nm = (item.name || "").toLowerCase();
      if (ident === "mobile_bar" || nm.includes("mobile bar")) {
        label = "MOBILE BAR";
      } else if (ident === "drinks_package" || nm.includes("unlimited drinks")) {
        label = "UNLIMITED DRINKS";
      } else if (ident === "ice_cream" || nm.includes("ice cream")) {
        label = "ICE CREAM";
      }
      specialBadgeHtml = `<span style="display:inline-block; margin-bottom:8px; font-size:10px; font-weight:700; color:var(--gold); text-transform:uppercase; letter-spacing:0.8px;">★ ${label}</span><br>`;
    } else if (connectedParent) {
      specialBadgeHtml = `<span style="display:inline-block; margin-bottom:8px; font-size:10px; font-weight:700; color:var(--gold); text-transform:uppercase; letter-spacing:0.8px;">↳ ${connectedParent.toUpperCase()}</span><br>`;
    }

    const imgUrl = resolveAdminItemImage(item);

    return `
      <div class="admin-cat-card ${isHidden ? 'hidden' : ''}" style="background:${cardBgColor}; border:1.5px solid ${cardBorderColor}; border-radius:12px; padding:0; overflow:hidden; display:flex; flex-direction:column; justify-content:space-between; opacity:${isHidden ? '0.65' : '1'}; word-break:break-word; overflow-wrap:anywhere; min-width:0;">
        <div style="width:100%; height:160px; background:var(--bg3, #1e1e1e); position:relative; overflow:hidden; flex-shrink:0;">
          <img src="${imgUrl}" alt="${escHtml(item.name || '')}" style="width:100%; height:100%; object-fit:cover; display:block;" onerror="this.onerror=null; this.src='https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&q=80&w=800';" />
        </div>
        <div style="padding:16px 18px 18px; display:flex; flex-direction:column; justify-content:space-between; flex:1; min-width:0;">
          <div style="min-width:0; word-break:break-word; overflow-wrap:anywhere;">
            ${specialBadgeHtml}<div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:4px; gap:8px;"><span style="font-size:10px; color:var(--gold); text-transform:uppercase; font-weight:800; letter-spacing:0.5px;">${categoryBadge}</span>${(item.best_seller === true || item.best_seller === 'true') ? '<span class="tag-best-seller" style="font-size:10px; font-weight:700; color:var(--gold); text-transform:uppercase; letter-spacing:0.8px;">Best Seller</span>' : ''}</div>
            <div style="font-size:16px; font-weight:700; color:var(--cream); margin-bottom:6px; word-break:break-word;">${item.name}</div>
            <div style="font-size:14px; font-weight:600; color:var(--gold); margin-bottom:8px; word-break:break-word;">${priceLabel}</div>
            <div style="font-size:12px; color:var(--text-dim); line-height:1.4; word-break:break-word; overflow-wrap:anywhere;">${item.description || 'No description provided.'}</div>
            ${ingredientsDisplay}
          </div>
          <div style="display:flex; gap:8px; margin-top:16px; padding-top:12px; border-top:1px solid rgba(255,255,255,0.05);">
            <button class="btn-outline" style="flex:1; font-size:11px; padding:6px;" onclick="openEditCatalogModal('${item.id}')">Edit</button>
            <button class="btn-outline" style="flex:1; font-size:11px; padding:6px; font-weight:700; ${isHidden ? 'background:#16a34a !important; color:#ffffff !important; border:none !important;' : 'background:#4b5563 !important; color:#ffffff !important; border:none !important;'}" onclick="toggleCatalogVisibility('${item.id}', ${isHidden})">
              ${isHidden ? 'Unhide in Web' : 'Hide in Web'}
            </button>
          </div>
        </div>
      </div>
    `;
  }).join('');
}

// ── CATALOG ITEM ADD/EDIT MODAL ─────────────────────────
let editingSpecialSubitems = new Set();
let editingCatalogDecorOptions = [];

// ── DECOR OPTIONS MANAGEMENT (Catalog Add/Edit Modal) ──
function addCatalogDecorOption() {
  if (editingCatalogDecorOptions.length >= 10) {
    alert('Maximum 10 options can be added for a decor item.');
    return;
  }
  const nextNum = editingCatalogDecorOptions.length + 1;
  editingCatalogDecorOptions.push({
    id: 'opt_' + Date.now() + '_' + Math.random().toString(36).substr(2, 4),
    title: 'Option ' + nextNum,
    price_modifier: 0,
    image_url: ''
  });
  renderCatalogDecorOptions();
}

function removeCatalogDecorOption(idx) {
  editingCatalogDecorOptions.splice(idx, 1);
  renderCatalogDecorOptions();
}

function updateDecorOptionTitle(idx, val) {
  if (editingCatalogDecorOptions[idx]) {
    editingCatalogDecorOptions[idx].title = val;
  }
}

function updateDecorOptionPriceModifier(idx, val) {
  if (editingCatalogDecorOptions[idx]) {
    let num = parseFloat(val) || 0;
    if (num > 999999) num = 999999;
    editingCatalogDecorOptions[idx].price_modifier = num;
  }
}

async function handleDecorOptionFileSelect(e, idx) {
  const file = e.target.files && e.target.files[0];
  if (!file) return;
  if (file.size > 5 * 1024 * 1024) {
    alert('Image must be under 5MB.');
    e.target.value = '';
    return;
  }
  const barId = `ac-decor-opt-bar-${idx}`;
  const textId = `ac-decor-opt-text-${idx}`;
  const wrapId = `ac-decor-opt-wrap-${idx}`;
  try {
    const data = await uploadImageToCloudinary(file, barId, textId, wrapId);
    if (editingCatalogDecorOptions[idx]) {
      editingCatalogDecorOptions[idx].image_url = data.secure_url || data.url || '';
      renderCatalogDecorOptions();
    }
  } catch (err) {
    alert('Image upload failed: ' + err.message);
  }
  e.target.value = '';
}

function removeDecorOptionImage(idx) {
  if (editingCatalogDecorOptions[idx]) {
    editingCatalogDecorOptions[idx].image_url = '';
    renderCatalogDecorOptions();
  }
}

function renderCatalogDecorOptions() {
  const container = document.getElementById('ac-decor-options-list');
  const countEl = document.getElementById('ac-decor-options-count');
  const addBtn = document.getElementById('ac-add-decor-option-btn');
  if (!container) return;

  const count = editingCatalogDecorOptions.length;
  if (countEl) countEl.textContent = `${count} / 10 options`;
  if (addBtn) addBtn.style.display = count >= 10 ? 'none' : 'block';

  if (count === 0) {
    container.innerHTML = '<div style="font-size:12px; color:var(--text-dim); text-align:center; padding:12px; border:1px dashed var(--border); border-radius:8px;">No options added yet. Click "+ Add Another Option" below to add photo options.</div>';
    return;
  }

  container.innerHTML = editingCatalogDecorOptions.map((opt, idx) => {
    const hasImage = !!opt.image_url;
    return `
      <div style="background:var(--bg3); border:1px solid var(--border); border-radius:8px; padding:12px; display:flex; gap:12px; align-items:center; position:relative;">
        <div style="width:70px; height:70px; flex-shrink:0; background:var(--bg2); border-radius:6px; border:1px solid var(--border); overflow:hidden; display:flex; align-items:center; justify-content:center; position:relative;">
          ${hasImage
            ? `<img src="${opt.image_url}" alt="${escHtml(opt.title || 'Option')}" style="width:100%; height:100%; object-fit:contain; background:#ffffff; padding:2px; box-sizing:border-box;" />`
            : `<span style="font-size:11px; color:var(--text-dim); text-align:center; padding:4px;">No Photo</span>`
          }
        </div>
        <div style="flex:1; display:flex; flex-direction:column; gap:6px; min-width:0;">
          <div style="display:flex; gap:8px; align-items:center;">
            <input type="text" class="input-field" value="${escHtml(opt.title || 'Option ' + (idx + 1))}" placeholder="Option Name (e.g. Option 1)" style="font-size:12px; padding:6px 10px; height:auto; flex:1;" onchange="updateDecorOptionTitle(${idx}, this.value)" />
            <button type="button" onclick="removeCatalogDecorOption(${idx})" title="Remove this option" style="background:#dc2626; border:none; color:#ffffff; width:30px; height:30px; border-radius:6px; cursor:pointer; font-size:13px; font-weight:700; flex-shrink:0; display:flex; align-items:center; justify-content:center;">✕</button>
          </div>
          <div style="display:flex; align-items:center; gap:8px;">
            <input type="file" id="ac-decor-opt-file-${idx}" accept="image/*" style="display:none;" onchange="handleDecorOptionFileSelect(event, ${idx})" />
            <button type="button" class="btn-outline" style="font-size:11px; padding:4px 10px; cursor:pointer;" onclick="document.getElementById('ac-decor-opt-file-${idx}').click()">
              ${hasImage ? 'Change Photo' : 'Upload Photo'}
            </button>
            ${hasImage ? `<button type="button" class="btn-outline" style="font-size:11px; padding:4px 10px; background:#dc2626 !important; color:#ffffff !important; border:none !important; font-weight:700; cursor:pointer;" onclick="removeDecorOptionImage(${idx})">Remove Photo</button>` : ''}
          </div>
          <div id="ac-decor-opt-wrap-${idx}" style="display:none; margin-top:4px;">
            <div id="ac-decor-opt-text-${idx}" style="font-size:10px; color:var(--text-dim); margin-bottom:2px;">Uploading...</div>
            <div style="background:var(--bg2); border-radius:3px; height:4px; overflow:hidden;">
              <div id="ac-decor-opt-bar-${idx}" style="height:100%; background:var(--gold); width:0%; transition:width 0.2s;"></div>
            </div>
          </div>
        </div>
      </div>
    `;
  }).join('');
}

function onCatalogTypeChange() {
  const type = document.getElementById('ac-item-type').value;
  
  if (type === 'equipment') {
    closeAdminCatalogModal();
    if (typeof openAddEquipmentModal === 'function') {
      openAddEquipmentModal();
    }
    return;
  }

  const categoryInput = document.getElementById('ac-item-category');
  const autoNote = document.getElementById('ac-category-auto-note');

  if (type === 'decoration') {
    categoryInput.value = 'Decoration';
    categoryInput.readOnly = true;
    if (autoNote) autoNote.textContent = '(Auto)';
  } else if (type === 'addon') {
    categoryInput.value = 'Entertainment';
    categoryInput.readOnly = true;
    if (autoNote) autoNote.textContent = '(Auto)';
  } else if (type === 'drinks') {
    categoryInput.value = 'Drinks';
    categoryInput.readOnly = true;
    if (autoNote) autoNote.textContent = '(Auto)';
  } else if (type === 'desserts') {
    categoryInput.value = 'Dessert';
    categoryInput.readOnly = true;
    if (autoNote) autoNote.textContent = '(Auto)';
  } else {
    categoryInput.readOnly = false;
    if (autoNote) autoNote.textContent = '';
    if (['Decoration', 'Entertainment', 'Drinks', 'Dessert'].includes(categoryInput.value)) {
      categoryInput.value = '';
    }
  }

  updateCatalogModalFieldVisibilities();
}

function onCatalogSpecialToggle() {
  updateCatalogModalFieldVisibilities();
}

function onDrinkStandaloneToggle() {
  const isChecked = document.getElementById('ac-drink-standalone')?.checked;
  const pPaxGroup = document.getElementById('ac-price-per-pax-group');
  const pDrinkNote = document.getElementById('ac-price-drink-note');

  if (pPaxGroup) pPaxGroup.style.display = isChecked ? 'block' : 'none';
  if (pDrinkNote) pDrinkNote.style.display = isChecked ? 'none' : 'block';
}

function updateCatalogModalFieldVisibilities() {
  const type = document.getElementById('ac-item-type').value;
  const isSpecial = document.getElementById('ac-is-special').checked;

  const ingSec = document.getElementById('ac-ingredients-section');
  const pPaxGroup = document.getElementById('ac-price-per-pax-group');
  const pFixedGroup = document.getElementById('ac-price-fixed-group');
  const pDrinkContainer = document.getElementById('ac-price-drink-container');
  const pDrinkNote = document.getElementById('ac-price-drink-note');
  const pSpecialGroup = document.getElementById('ac-special-price-group');
  const subitemsSec = document.getElementById('ac-special-subitems-section');
  const addonSec = document.getElementById('ac-addon-personnel-section');
  const bestSellerCont = document.getElementById('ac-best-seller-container');
  const decorOptSec = document.getElementById('ac-decor-options-section');

  if (pPaxGroup) pPaxGroup.style.display = 'none';
  if (pFixedGroup) pFixedGroup.style.display = 'none';
  if (pDrinkContainer) pDrinkContainer.style.display = 'none';
  if (pDrinkNote) pDrinkNote.style.display = 'none';
  if (pSpecialGroup) pSpecialGroup.style.display = 'none';
  if (subitemsSec) subitemsSec.style.display = 'none';
  if (addonSec) addonSec.style.display = 'none';
  if (decorOptSec) decorOptSec.style.display = 'none';

  // Best seller toggle is only available for food (meals), drinks, and dessert, not for special bundles
  if (bestSellerCont) {
    if (!isSpecial && ['meals', 'drinks', 'desserts'].includes(type)) {
      bestSellerCont.style.display = 'flex';
    } else {
      bestSellerCont.style.display = 'none';
    }
  }

  if (isSpecial) {
    if (ingSec) ingSec.style.display = 'none';
    if (pSpecialGroup) pSpecialGroup.style.display = 'block';
    if (subitemsSec) subitemsSec.style.display = 'block';
    renderSpecialSubitemsList();
    return;
  }

  if (['decoration', 'addon'].includes(type)) {
    if (ingSec) ingSec.style.display = 'none';
    if (pFixedGroup) pFixedGroup.style.display = 'block';
    if (type === 'decoration' && decorOptSec) {
      decorOptSec.style.display = 'block';
      renderCatalogDecorOptions();
    }
    if (type === 'addon' && addonSec) addonSec.style.display = 'block';
  } else if (type === 'drinks') {
    if (ingSec) ingSec.style.display = 'block';
    if (pDrinkContainer) pDrinkContainer.style.display = 'block';
    onDrinkStandaloneToggle();
  } else {
    if (ingSec) ingSec.style.display = 'block';
    if (pPaxGroup) pPaxGroup.style.display = 'block';
  }
}

function updateSpecialPaxLabel() {
  const pax = parseInt(document.getElementById('ac-special-pax').value) || 0;
  const preview = document.getElementById('ac-special-pax-preview');
  if (preview) preview.textContent = `Stored as: per_${pax || 'X'}_pax`;
}

function addIngredientRow(val = '') {
  editingItemIngredients.push(val);
  renderIngredientRows();
}

function removeIngredientRow(idx) {
  editingItemIngredients.splice(idx, 1);
  renderIngredientRows();
}

function renderIngredientRows() {
  const list = document.getElementById('ac-ingredients-list');
  if (!list) return;

  if (editingItemIngredients.length === 0) {
    editingItemIngredients = [''];
  }

  list.innerHTML = editingItemIngredients.map((ing, idx) => `
    <div style="display:flex; gap:8px; align-items:center;">
      <input type="text" class="input-field ac-ing-input" value="${ing.replace(/"/g, '&quot;')}" placeholder="e.g. Garlic, Lemongrass, Soy Sauce" style="flex:1;" onchange="editingItemIngredients[${idx}] = this.value">
      <button type="button" onclick="removeIngredientRow(${idx})" style="background:#dc2626; border:none; color:#ffffff; width:32px; height:32px; border-radius:6px; cursor:pointer; font-size:14px; font-weight:700; display:flex; align-items:center; justify-content:center;">✕</button>
    </div>
  `).join('');
}

function toggleSpecialSubitem(itemName, isChecked) {
  if (isChecked) {
    editingSpecialSubitems.add(itemName);
  } else {
    editingSpecialSubitems.delete(itemName);
  }
  renderSpecialSubitemsList();
}

function renderSpecialSubitemsList() {
  const container = document.getElementById('ac-special-subitems-list');
  if (!container) return;

  const currentType = document.getElementById('ac-item-type').value;
  const currentSupabaseId = document.getElementById('ac-item-supabase-id').value;
  const currentItem = sbMenuItems.find(i => i.id === currentSupabaseId);
  const currentItemName = currentItem ? currentItem.name : '';
  const searchQ = (document.getElementById('ac-special-subitems-search')?.value || '').toLowerCase().trim();

  // 1. Exclude current special item itself
  let items = sbMenuItems.filter(i => i.id !== currentSupabaseId);

  // 2. EXCLUDE SPECIAL ITEMS (master bundles cannot be sub-items)
  items = items.filter(i => {
    const isMasterSpecial = (i.ingredients || '').startsWith('per_') ||
      i.identify === 'special' ||
      i.identify === 'drinks_package' ||
      i.identify === 'ice_cream' ||
      (i.name || '').toLowerCase().includes('mobile bar') ||
      (i.name || '').toLowerCase().includes('unlimited drinks') ||
      (i.name || '').toLowerCase().includes('ice cream');
    return !isMasterSpecial;
  });

  // 3. EXCLUDE ITEMS INCLUDED IN OTHER SPECIAL ITEMS
  items = items.filter(i => {
    if (editingSpecialSubitems.has(i.name)) return true;
    const parentName = getSpecialParentName(i);
    if (parentName && parentName.toLowerCase() !== currentItemName.toLowerCase()) {
      return false;
    }
    return true;
  });

  // 4. CATEGORY RESTRICTION
  if (currentType === 'drinks') {
    items = items.filter(i => i.identify === 'drinks' || (i.category || '').toLowerCase() === 'drinks');
  } else if (currentType === 'desserts') {
    items = items.filter(i =>
      ['desserts', 'dessert', 'ice_cream_option'].includes(i.identify) ||
      (i.category || '').toLowerCase().includes('dessert') ||
      (i.category || '').toLowerCase().includes('ice cream')
    );
  } else if (currentType === 'decoration') {
    items = items.filter(i =>
      ['decoration', 'decor'].includes(i.identify) ||
      (i.category || '').toLowerCase().includes('decor')
    );
  } else if (currentType === 'addon') {
    items = items.filter(i =>
      ['addon', 'entertainment', 'addons'].includes(i.identify) ||
      (i.category || '').toLowerCase().includes('entertainment')
    );
  } else if (currentType === 'meals') {
    items = items.filter(i =>
      ['meals', 'food', 'free_choice'].includes(i.identify) ||
      ['beef', 'pork', 'chicken', 'fish', 'shrimp', 'pasta', 'pancit', 'vegetables', 'soup', 'food'].includes((i.category || '').toLowerCase())
    );
  }

  if (searchQ) {
    items = items.filter(i => i.name.toLowerCase().includes(searchQ));
  }

  // SORTING REQUIREMENT: Checked items at the VERY TOP of the list!
  const checkedItems = [];
  const uncheckedItems = [];

  items.forEach(item => {
    if (editingSpecialSubitems.has(item.name)) {
      checkedItems.push(item);
    } else {
      uncheckedItems.push(item);
    }
  });

  const sortedItems = [...checkedItems, ...uncheckedItems];

  if (sortedItems.length === 0) {
    container.innerHTML = '<div style="font-size:12px; color:var(--text-dim); text-align:center; padding:12px;">No matching items available in this category.</div>';
    return;
  }

  container.innerHTML = sortedItems.map(item => {
    const isChecked = editingSpecialSubitems.has(item.name);
    return `
      <label style="display:flex; align-items:center; gap:10px; font-size:13px; color:var(--cream); cursor:pointer; padding:6px 8px; background:${isChecked ? 'rgba(196,154,60,0.12)' : 'var(--bg2)'}; border-radius:6px; border:1px solid ${isChecked ? 'rgba(196,154,60,0.4)' : 'var(--border)'}; font-weight:${isChecked ? '700' : '400'};">
        <input type="checkbox" class="ac-subitem-cb" value="${item.name.replace(/"/g, '&quot;')}" ${isChecked ? 'checked' : ''} onchange="toggleSpecialSubitem('${item.name.replace(/'/g, "\\'")}', this.checked)">
        <span>${item.name}</span>
        <span style="font-size:10px; color:${isChecked ? 'var(--gold)' : 'var(--text-dim)'}; margin-left:auto; text-transform:uppercase;">${item.category || item.identify}</span>
      </label>
    `;
  }).join('');
}

function filterSpecialSubitems() {
  renderSpecialSubitemsList();
}

function openAddCatalogModal() {
  document.getElementById('ac-item-id').value = '';
  document.getElementById('ac-item-supabase-id').value = '';
  document.getElementById('ac-is-special').checked = false;
  document.getElementById('ac-item-type').value = 'meals';
  document.getElementById('ac-item-category').value = '';
  document.getElementById('ac-item-name').value = '';
  document.getElementById('ac-item-desc').value = '';
  document.getElementById('ac-item-price').value = '';
  document.getElementById('ac-item-price-fixed').value = '';
  document.getElementById('ac-special-pax').value = '5';
  document.getElementById('ac-special-price').value = '';
  const drinkCb = document.getElementById('ac-drink-standalone');
  if (drinkCb) drinkCb.checked = false;
  const bsCb = document.getElementById('ac-is-best-seller');
  if (bsCb) bsCb.checked = false;
  editingItemIngredients = [''];
  editingSpecialSubitems.clear();
  window.editingAddonPersonnel = [];
  editingCatalogDecorOptions = [];
  renderCatalogDecorOptions();

  document.getElementById('admin-catalog-modal-title').textContent = 'Add Catalog Item';
  onCatalogTypeChange();
  renderIngredientRows();
  if (typeof renderAddonPersonnelRows === 'function') renderAddonPersonnelRows();

  // Reset image upload
  acClearImage();

  document.getElementById('admin-catalog-modal-overlay').classList.add('on');
  document.getElementById('admin-catalog-modal').classList.add('open');
}

function openEditCatalogModal(id) {
  if (typeof EIM_ASSETS !== 'undefined' && Array.isArray(EIM_ASSETS)) {
    const eqIdx = EIM_ASSETS.findIndex(eq => eq.id === id);
    if (eqIdx > -1) {
      if (typeof openEditEquipmentModal === 'function') {
        openEditEquipmentModal(eqIdx);
      }
      return;
    }
  }

  const item = sbMenuItems.find(i => i.id === id);
  if (!item) return;

  document.getElementById('ac-item-id').value = item.id;
  document.getElementById('ac-item-supabase-id').value = item.id;

  const isSpecial = (item.ingredients || '').startsWith('per_') || item.identify === 'special' || item.identify === 'drinks_package' || item.identify === 'ice_cream' || (item.name || '').toLowerCase().includes('mobile bar') || (item.name || '').toLowerCase().includes('ice cream');
  document.getElementById('ac-is-special').checked = isSpecial;

  document.getElementById('ac-item-type').value = (item.identify === 'drinks_package' ? 'drinks' : (item.identify === 'ice_cream' ? 'desserts' : item.identify)) || 'meals';
  document.getElementById('ac-item-category').value = item.category || '';
  document.getElementById('ac-item-name').value = item.name || '';
  document.getElementById('ac-item-desc').value = item.description || '';

  const bsCb = document.getElementById('ac-is-best-seller');
  if (bsCb) bsCb.checked = !!(item.best_seller === true || item.best_seller === 'true');

  const price = parseFloat(item.price_per_pax) || 0;
  document.getElementById('ac-item-price').value = price || '';
  document.getElementById('ac-item-price-fixed').value = price || '';
  document.getElementById('ac-special-price').value = price || '';

  const ingRaw = item.ingredients || '';
  const isDrinkStandalone = ingRaw === 'standalone' || ingRaw.includes(' | standalone');
  const drinkCb = document.getElementById('ac-drink-standalone');
  if (drinkCb) drinkCb.checked = isDrinkStandalone;

  if (isSpecial && item.ingredients && item.ingredients.startsWith('per_')) {
    const match = item.ingredients.match(/per_(\d+)_pax/);
    if (match) document.getElementById('ac-special-pax').value = match[1];
  } else {
    document.getElementById('ac-special-pax').value = '5';
  }

  // Pre-populate special sub-items set
  editingSpecialSubitems.clear();
  if (isSpecial) {
    if (item.ingredients && item.ingredients.includes(' | sub_items: ')) {
      const subStr = item.ingredients.split(' | sub_items: ')[1];
      if (subStr) {
        subStr.split(', ').map(s => s.trim()).filter(Boolean).forEach(sName => editingSpecialSubitems.add(sName));
      }
    } else {
      if (item.name.toLowerCase().includes('mobile bar')) {
        sbMenuItems.filter(i => (i.name || '').toLowerCase().includes('cocktail') || (i.name || '').toLowerCase().includes('shooter') || (i.name || '').toLowerCase().includes('mixes') || (i.name || '').toLowerCase().includes('mocktail')).forEach(d => editingSpecialSubitems.add(d.name));
      } else if (item.name.toLowerCase().includes('unlimited drinks') || item.identify === 'drinks_package') {
        sbMenuItems.filter(i => (i.identify === 'drinks' || i.category === 'Drinks') && i.id !== item.id && !i.name.toLowerCase().includes('mobile bar') && !i.name.toLowerCase().includes('cocktail') && !i.name.toLowerCase().includes('shooter')).forEach(d => editingSpecialSubitems.add(d.name));
      } else if (item.name.toLowerCase().includes('ice cream')) {
        sbMenuItems.filter(i => (i.name || '').toLowerCase().includes('ice cream') && i.id !== item.id).forEach(d => editingSpecialSubitems.add(d.name));
      }
    }
  }

  let cleanIng = ingRaw.replace(' | standalone', '').trim();
  if (cleanIng === 'standalone') cleanIng = '';
  if (cleanIng && cleanIng !== 'fixed' && !cleanIng.startsWith('per_')) {
    editingItemIngredients = cleanIng.split(',').map(s => s.trim()).filter(Boolean);
  } else {
    editingItemIngredients = [''];
  }

  document.getElementById('admin-catalog-modal-title').textContent = 'Edit Catalog Item';
  onCatalogTypeChange();
  renderIngredientRows();
  updateSpecialPaxLabel();

  window.editingAddonPersonnel = [];
  if (['addon'].includes(document.getElementById('ac-item-type').value)) {
    if (window.supabaseClient) {
      window.supabaseClient.from('personnel').select('*').eq('service_type', item.name).then(({ data, error }) => {
        if (!error && data) {
          window.editingAddonPersonnel = data;
          if (typeof renderAddonPersonnelRows === 'function') renderAddonPersonnelRows();
        }
      });
    }
  } else {
    if (typeof renderAddonPersonnelRows === 'function') renderAddonPersonnelRows();
  }
  updateSpecialPaxLabel();

  // Pre-populate existing image if any
  acClearImage();
  if (item.image_url) {
    document.getElementById('ac-img-url').value = item.image_url;
    _showImagePreview('ac-img-preview', 'ac-img-preview-wrap', 'ac-img-drop-zone', item.image_url);
  }

  // Pre-populate decor options if decoration item
  editingCatalogDecorOptions = [];
  if (item.options) {
    if (Array.isArray(item.options)) {
      editingCatalogDecorOptions = JSON.parse(JSON.stringify(item.options));
    } else if (typeof item.options === 'string') {
      try {
        const parsed = JSON.parse(item.options);
        if (Array.isArray(parsed)) editingCatalogDecorOptions = parsed;
      } catch (e) {}
    }
  }
  if (editingCatalogDecorOptions.length === 0 && item.ingredients && typeof item.ingredients === 'string' && item.ingredients.includes('| options:')) {
    try {
      const parsed = JSON.parse(item.ingredients.split('| options:')[1].trim());
      if (Array.isArray(parsed)) editingCatalogDecorOptions = parsed;
    } catch (e) {}
  }
  renderCatalogDecorOptions();

  document.getElementById('admin-catalog-modal-overlay').classList.add('on');
  document.getElementById('admin-catalog-modal').classList.add('open');
}

function closeAdminCatalogModal() {
  document.getElementById('admin-catalog-modal-overlay').classList.remove('on');
  document.getElementById('admin-catalog-modal').classList.remove('open');
}

// Persistent BroadcastChannel for real-time live sync across open tabs
let _adminLiveSyncBc = null;
function getAdminLiveSyncChannel() {
  if (!_adminLiveSyncBc) {
    try {
      _adminLiveSyncBc = new BroadcastChannel('halden_live_sync');
    } catch (e) {
      console.warn('[Live Sync] BroadcastChannel not supported:', e);
    }
  }
  return _adminLiveSyncBc;
}

function notifyLiveCatalogSync(type = 'CATALOG_UPDATED') {
  const syncType = type || 'CATALOG_UPDATED';
  try {
    const bc = getAdminLiveSyncChannel();
    if (bc) {
      bc.postMessage({ type: syncType, timestamp: Date.now() });
    }
  } catch (e) { }
  try {
    // Write unique payload each time to guarantee storage event triggers across tabs
    localStorage.setItem('halden_live_sync_trigger', JSON.stringify({
      type: syncType,
      timestamp: Date.now(),
      rand: Math.random()
    }));
  } catch (e) { }
}

async function saveAdminCatalogItem() {
  const sb = window.supabaseClient;
  if (!sb) return alert('Database connection not ready.');

  const id = document.getElementById('ac-item-id').value;
  const isSpecial = document.getElementById('ac-is-special').checked;
  const identify = document.getElementById('ac-item-type').value;
  const category = document.getElementById('ac-item-category').value.trim() || identify;
  const name = document.getElementById('ac-item-name').value.trim();
  const description = document.getElementById('ac-item-desc').value.trim();
  const isDrinkStandalone = (identify === 'drinks' && !isSpecial && document.getElementById('ac-drink-standalone')?.checked);

  if (!name) return alert('Item Name is required');

  let price_per_pax = 0;
  let ingredients = 'fixed';

  let finalIdentify = identify;
  if (isSpecial) {
    if (identify === 'drinks') finalIdentify = 'drinks_package';
    else if (identify === 'desserts') finalIdentify = 'ice_cream';
    else finalIdentify = identify;
    const pax = parseInt(document.getElementById('ac-special-pax').value) || 5;
    const subArr = Array.from(editingSpecialSubitems);
    if (subArr.length > 0) {
      ingredients = `per_${pax}_pax | sub_items: ${subArr.join(', ')}`;
    } else {
      ingredients = `per_${pax}_pax`;
    }
    price_per_pax = parseFloat(document.getElementById('ac-special-price').value) || 0;
  } else if (['decoration', 'addon'].includes(identify)) {
    ingredients = 'fixed';
    price_per_pax = parseFloat(document.getElementById('ac-item-price-fixed').value) || 0;
  } else if (identify === 'drinks') {
    const inputs = document.querySelectorAll('.ac-ing-input');
    const ingArr = Array.from(inputs).map(i => i.value.trim()).filter(Boolean);
    const baseIng = ingArr.join(', ');
    if (isDrinkStandalone) {
      price_per_pax = parseFloat(document.getElementById('ac-item-price').value) || 0;
      ingredients = baseIng ? `${baseIng} | standalone` : 'standalone';
    } else {
      ingredients = baseIng || 'Various ingredients';
      price_per_pax = 0;
    }
  } else {
    const inputs = document.querySelectorAll('.ac-ing-input');
    const ingArr = Array.from(inputs).map(i => i.value.trim()).filter(Boolean);
    if (ingArr.length === 0) return alert('Ingredients are mandatory for Food and Dessert items');
    ingredients = ingArr.join(', ');
    price_per_pax = parseFloat(document.getElementById('ac-item-price').value) || 0;
  }

  if (price_per_pax > 999999) {
    return alert('Price cannot exceed 6 digits (maximum ₱999,999).');
  }

  if (finalIdentify === 'decoration' && editingCatalogDecorOptions && editingCatalogDecorOptions.length > 0) {
    for (const opt of editingCatalogDecorOptions) {
      if ((parseFloat(opt.price_modifier) || 0) > 999999) {
        return alert('Option price modifier cannot exceed 6 digits (maximum ₱999,999).');
      }
    }
    ingredients = `fixed | options: ${JSON.stringify(editingCatalogDecorOptions)}`;
  }

  const imageUrl = (document.getElementById('ac-img-url')?.value || '').trim() || null;

  const isBestSeller = (!isSpecial && ['meals', 'drinks', 'desserts'].includes(identify))
    ? !!document.getElementById('ac-is-best-seller')?.checked
    : false;

  const payload = {
    name,
    category,
    identify: finalIdentify,
    ingredients,
    description,
    price_per_pax,
    is_available: true,
    image_url: imageUrl,
    best_seller: isBestSeller
  };

  if (finalIdentify === 'decoration' && editingCatalogDecorOptions && editingCatalogDecorOptions.length > 0) {
    payload.options = editingCatalogDecorOptions;
  }

  try {
    let res;
    if (id) {
      res = await sb.from('menu_items').update(payload).eq('id', id).select();
    } else {
      res = await sb.from('menu_items').insert([payload]).select();
    }

    if (res.error) {
      if (res.error.code === '42703' || (res.error.message && (res.error.message.includes('best_seller') || res.error.message.includes('options')))) {
        console.warn('Column not yet in menu_items table, retrying save without missing column(s)...', res.error.message);
        if (res.error.message.includes('options')) delete payload.options;
        if (res.error.message.includes('best_seller')) delete payload.best_seller;
        if (id) {
          res = await sb.from('menu_items').update(payload).eq('id', id).select();
        } else {
          res = await sb.from('menu_items').insert([payload]).select();
        }
        if (res.error && res.error.code === '42703') {
          delete payload.options;
          delete payload.best_seller;
          if (id) {
            res = await sb.from('menu_items').update(payload).eq('id', id).select();
          } else {
            res = await sb.from('menu_items').insert([payload]).select();
          }
          if (res.error) throw res.error;
        } else if (res.error) {
          throw res.error;
        }
      } else {
        throw res.error;
      }
    }

    if (res.error) throw res.error;

    if (finalIdentify === 'addon' && window.editingAddonPersonnel) {
      for (const p of window.editingAddonPersonnel) {
        if (!p.full_name) throw new Error('Full Name is required for all personnel');
        if (!p.email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(p.email)) throw new Error('Valid email address is required for all personnel');
        let phoneStr = (p.contact_number || '').replace('+63', '').replace(/^0/, '').trim();
        if (!/^9\d{9}$/.test(phoneStr)) throw new Error('Phone number must start with 9 and be exactly 10 digits after +63 for all personnel');
        if (p.rate && parseFloat(p.rate) > 999999) throw new Error('Personnel rate cannot exceed 6 digits (maximum ₱999,999).');
      }

      const oldItem = sbMenuItems.find(i => i.id === id);
      const searchName = oldItem ? oldItem.name : name;
      const { data: existingData } = await sb.from('personnel').select('id').eq('service_type', searchName);
      const existingDbPersonnelIds = new Set(existingData ? existingData.map(p => p.id) : []);

      const upserts = [];
      const currentIds = new Set();
      for (const p of window.editingAddonPersonnel) {
        let phoneStr = (p.contact_number || '').replace('+63', '').replace(/^0/, '').trim();
        const payload = {
          full_name: p.full_name,
          email: p.email,
          contact_number: '0' + phoneStr,
          rate: parseFloat(p.rate) || 0,
          description: p.description || '',
          service_type: name,
          pricing_type: 'per_event'
        };
        if (p.id) {
          payload.id = p.id;
          currentIds.add(p.id);
        } else {
          payload.availability_status = 'Available';
        }
        upserts.push(payload);
      }

      if (upserts.length > 0) {
        const { error: upsertErr } = await sb.from('personnel').upsert(upserts);
        if (upsertErr) throw upsertErr;
      }

      const idsToUnlink = Array.from(existingDbPersonnelIds).filter(pid => !currentIds.has(pid));
      if (idsToUnlink.length > 0) {
        await sb.from('personnel').update({ service_type: null }).in('id', idsToUnlink);
      }
    }

    // Keep decor options in memory
    const savedId = id || (res?.data?.[0]?.id);
    if (savedId && finalIdentify === 'decoration') {
      const localItem = sbMenuItems.find(i => i.id === savedId);
      if (localItem) localItem.options = editingCatalogDecorOptions;
    }

    // Activity logging
    if (typeof window.logCatalogActivity === 'function') {
      if (id) {
        window.logCatalogActivity('Updated Catalog Item', `Updated catalog item "${name}" (${category || finalIdentify})`, { item_id: id, item_name: name, type: finalIdentify, price: price_per_pax });
      } else {
        const newId = res?.data?.[0]?.id || null;
        window.logCatalogActivity('Created Catalog Item', `Created catalog item "${name}" (${category || finalIdentify})`, { item_id: newId, item_name: name, type: finalIdentify, price: price_per_pax });
      }
    }

    await initAdminPackages();
    closeAdminCatalogModal();
    notifyLiveCatalogSync();
  } catch (e) {
    console.error('Save error:', e);
    alert('Failed to save item: ' + e.message);
  }
}

async function toggleCatalogVisibility(id, isCurrentlyHidden) {
  const sb = window.supabaseClient;
  if (!sb) return;

  try {
    const newStatus = isCurrentlyHidden;
    const eqAsset = (typeof EIM_ASSETS !== 'undefined') && EIM_ASSETS.find(a => a.id === id || a.supabaseId === id || a.asset_id === id);

    if (eqAsset) {
      // Equipment item in equipment_inventory table
      const newDisabled = !newStatus; // is_disabled = true hides from web
      let updateQuery = sb.from('equipment_inventory').update({ is_disabled: newDisabled });
      if (eqAsset.supabaseId) {
        updateQuery = updateQuery.eq('id', eqAsset.supabaseId);
      } else {
        updateQuery = updateQuery.eq('asset_id', eqAsset.id);
      }
      const { error } = await updateQuery;
      if (error) throw error;

      eqAsset.is_disabled = newDisabled;

      if (typeof window.logCatalogActivity === 'function') {
        const actLabel = newStatus ? 'Unhid Equipment Item' : 'Hid Equipment Item';
        window.logCatalogActivity(actLabel, `${newStatus ? 'Unhid' : 'Hid'} equipment item "${eqAsset.name}"`, { item_id: eqAsset.id, item_name: eqAsset.name, is_available: newStatus });
      }
    } else {
      // Standard menu item in menu_items table
      const { error } = await sb.from('menu_items').update({ is_available: newStatus }).eq('id', id);
      if (error) throw error;

      const item = sbMenuItems.find(i => i.id === id);
      const itemName = item ? item.name : id;
      if (typeof window.logCatalogActivity === 'function') {
        const actLabel = newStatus ? 'Unhid Catalog Item' : 'Hid Catalog Item';
        window.logCatalogActivity(actLabel, `${newStatus ? 'Unhid' : 'Hid'} catalog item "${itemName}"`, { item_id: id, item_name: itemName, is_available: newStatus });
      }
    }

    await initAdminPackages();
    notifyLiveCatalogSync();
  } catch (e) {
    console.error('Toggle visibility error:', e);
    alert('Failed to update visibility: ' + e.message);
  }
}

// ── PREMADE PACKAGES RENDERING ───────────────────────────
function renderAdminPackages() {
  const grid = document.getElementById('admin-premade-grid');
  if (!grid) return;

  let pkgs = sbPremadePackages;

  if (adminPkgFilter !== 'all') {
    pkgs = pkgs.filter(p => (p.occasion || '').toLowerCase().includes(adminPkgFilter.toLowerCase()));
  }

  if (pkgs.length === 0) {
    grid.innerHTML = '<div style="text-align:center; padding:40px; color:var(--text-dim); grid-column:1/-1;">No packages found.</div>';
    return;
  }

  grid.innerHTML = pkgs.map(p => {
    const isHidden = p.is_active === false;
    const isDynamic = p.badge === 'Dynamically Set' || p.pricing_mode === 'per_head';

    let priceDisplay = '₱' + (parseFloat(p.price_per_head || p.fixed_price || 0)).toLocaleString();
    if (isDynamic) priceDisplay += ' / head';
    else if (p.price_tiers && Array.isArray(p.price_tiers) && p.price_tiers.length > 0) {
      priceDisplay = `Tiered (Starts ₱${(p.price_tiers[0].price || 0).toLocaleString()})`;
    } else {
      priceDisplay += ' (Fixed)';
    }

    const includedItems = sbPremadePackageItems.filter(i => i.package_id === p.id);
    const itemNames = includedItems.map(i => i.item_name).slice(0, 5);

    const pkgImgUrl = resolveAdminPackageImage(p);

    return `
      <div class="admin-cat-card ${isHidden ? 'hidden' : ''}" style="background:var(--bg2); border:1px solid ${isHidden ? 'rgba(255,255,255,0.06)' : 'var(--border)'}; border-radius:12px; padding:0; overflow:hidden; display:flex; flex-direction:column; justify-content:space-between; opacity:${isHidden ? '0.65' : '1'};">
        <div style="width:100%; height:160px; background:var(--bg3, #1e1e1e); position:relative; overflow:hidden; flex-shrink:0;">
          <img src="${pkgImgUrl}" alt="${escHtml(p.name || '')}" style="width:100%; height:100%; object-fit:cover; display:block;" onerror="this.onerror=null; this.src='https://images.unsplash.com/photo-1464349095431-e9a21285b5ac?auto=format&fit=crop&q=80&w=800';" />
        </div>
        <div style="padding:16px 18px 18px; display:flex; flex-direction:column; justify-content:space-between; flex:1; min-width:0;">
          <div>
            <div style="display:flex; justify-content:space-between; align-items:flex-start;">
              <div style="font-size:10px; color:var(--gold); text-transform:uppercase; font-weight:800; letter-spacing:0.5px; margin-bottom:4px;">${p.occasion || 'Event Package'}</div>
              <span style="font-size:10px; font-weight:700; color:var(--gold); text-transform:uppercase; letter-spacing:0.5px;">${p.badge || 'Majorly Set'}</span>
            </div>
            <div style="font-size:16px; font-weight:700; color:var(--cream); margin-bottom:6px;">${p.name}</div>
            <div style="font-size:14px; font-weight:600; color:var(--gold); margin-bottom:8px;">${priceDisplay}</div>
            <div style="font-size:12px; color:var(--text-dim); line-height:1.4;">${p.description || 'No description.'}</div>
            ${itemNames.length > 0 ? `<div style="font-size:11px; color:var(--text-dim); margin-top:10px;"><strong>Included:</strong> ${itemNames.join(', ')}${includedItems.length > 5 ? '...' : ''}</div>` : ''}
          </div>
          <div style="display:flex; gap:8px; margin-top:16px; padding-top:12px; border-top:1px solid rgba(255,255,255,0.05);">
            <button class="btn-outline" style="flex:1; font-size:11px; padding:6px;" onclick="openEditPremadeModal('${p.id}')">Edit</button>
            <button class="btn-outline" style="flex:1; font-size:11px; padding:6px; font-weight:700; ${isHidden ? 'background:#16a34a !important; color:#ffffff !important; border:none !important;' : 'background:#4b5563 !important; color:#ffffff !important; border:none !important;'}" onclick="togglePackageVisibility('${p.id}', ${isHidden})">
              ${isHidden ? 'Unhide in Web' : 'Hide in Web'}
            </button>
          </div>
        </div>
      </div>
    `;
  }).join('');
}

// ── PREMADE PACKAGE MODAL & COMPONENT BUILDER ────────────
function onPkgPricingModeChange() {
  const mode = document.getElementById('ap-pkg-pricing-mode').value;
  document.getElementById('ap-pkg-tiers-section').style.display = (mode === 'majorly_set') ? 'block' : 'none';
  document.getElementById('ap-pkg-pph-section').style.display = (mode === 'per_head') ? 'block' : 'none';
}

function addPkgTierRow(pax = '', price = '') {
  editingPkgTiers.push({ pax, price });
  renderPkgTiers();
}

function removePkgTierRow(idx) {
  editingPkgTiers.splice(idx, 1);
  renderPkgTiers();
}

function renderPkgTiers() {
  const container = document.getElementById('ap-pkg-tiers-list');
  if (!container) return;

  if (editingPkgTiers.length === 0) {
    editingPkgTiers = [{ pax: 50, price: 45000 }];
  }

  editingPkgTiers.sort((a, b) => (parseInt(a.pax) || 0) - (parseInt(b.pax) || 0));

  container.innerHTML = editingPkgTiers.map((t, idx) => `
    <div style="display:flex; gap:10px; align-items:center;">
      <input type="number" class="input-field" placeholder="Pax (e.g. 50)" value="${t.pax}" style="flex:1;" onchange="editingPkgTiers[${idx}].pax = this.value; renderPkgTiers();">
      <input type="number" class="input-field" placeholder="Price ₱ (e.g. 45000)" value="${t.price}" min="0" max="999999" maxlength="6" oninput="if(this.value.length>6) this.value=this.value.slice(0,6)" style="flex:1;" onchange="editingPkgTiers[${idx}].price = this.value;">
      <button type="button" onclick="removePkgTierRow(${idx})" style="background:#dc2626; border:none; color:#ffffff; width:32px; height:32px; border-radius:6px; cursor:pointer; font-size:14px; font-weight:700;">✕</button>
    </div>
  `).join('');
}

function setPkgCatalogFilter(cat, el) {
  pkgCatalogFilter = cat;
  document.querySelectorAll('#ap-catalog-filter-chips .cat-filter-chip').forEach(c => c.classList.remove('active'));
  if (el) el.classList.add('active');
  renderPkgCatalogBrowser();
  if (typeof syncPkgBrowserHeight === 'function') syncPkgBrowserHeight();
}

let inherentSetupEquipments = new Set();

function renderPkgSetupItemsSummary() {
  const container = document.getElementById('ap-pkg-setup-items');
  if (!container) return;

  const inherentBadges = Array.from(inherentSetupEquipments).map(eq =>
    `<span style="font-size:10px; font-weight:600; color:var(--gold);" title="Inherent to selected setup">${eq}</span>`
  );

  const extraBadges = [];
  editingPkgSelectedItems.forEach(name => {
    if (inherentSetupEquipments.has(name)) return;
    let found = sbMenuItems.find(m => m.name === name);
    if (!found && typeof CAT !== 'undefined') found = CAT.find(c => c.name === name);

    const cat = (found ? (found.category || found.cat || found.identify || '') : '').toLowerCase();
    const nameLower = name.toLowerCase();

    const isEquipment = cat.includes('equipment') || cat.includes('setup') ||
      nameLower.includes('plate') || nameLower.includes('spoon') || nameLower.includes('fork') || nameLower.includes('table') ||
      nameLower.includes('chair') || nameLower.includes('chafing') || nameLower.includes('glass') || nameLower.includes('napkin') ||
      nameLower.includes('runner') || nameLower.includes('skirt') || nameLower.includes('cover') || nameLower.includes('centerpiece') ||
      nameLower.includes('pitcher') || nameLower.includes('tray') || nameLower.includes('tongs') || nameLower.includes('sandok') || nameLower.includes('bucket') || nameLower.includes('sound');

    if (isEquipment) {
      extraBadges.push(
        `<span style="font-size:10px; font-weight:600; color:var(--cream); display:inline-flex; align-items:center; gap:4px;">` +
        `<span>${name}</span>` +
        `<span onclick="removeExtraPkgEquipment('${name.replace(/'/g, "\\'")}')" style="color:var(--red); cursor:pointer; font-weight:bold; margin-left:2px;" title="Remove extra equipment">✕</span>` +
        `</span>`
      );
    }
  });

  const allBadges = [...inherentBadges, ...extraBadges];
  container.innerHTML = allBadges.length > 0 ? allBadges.join('<span style="color:var(--text-dim); margin:0 6px;">&bull;</span>') : '<span style="color:var(--text-dim); font-size:11px;">No equipment selected</span>';
}

function removeExtraPkgEquipment(name) {
  editingPkgSelectedItems.delete(name);
  renderPkgSetupItemsSummary();
  renderPkgCatalogBrowser();
  renderPkgSelectedSummaries();
}

function renderPkgCatalogBrowser() {
  const list = document.getElementById('ap-catalog-browser-list');
  if (!list) return;

  const searchQ = (document.getElementById('ap-catalog-search')?.value || '').toLowerCase().trim();
  let items = [...sbMenuItems];

  // Filter out sub-items connected inside special items
  items = items.filter(i => {
    if (i.identify === 'ice_cream_option' || i.identify === 'mobile_bar_option') return false;
    if (typeof getSpecialParentName === 'function' && getSpecialParentName(i)) return false;
    return true;
  });

  if (pkgCatalogFilter === 'all') {
    // Show all catalog items: include equipment items from setups if not already in menu items
    let eqNames = new Set();
    sbEventSetups.forEach(s => {
      if (s.equipment_items) {
        try {
          const list = typeof s.equipment_items === 'string' ? JSON.parse(s.equipment_items) : s.equipment_items;
          if (Array.isArray(list)) list.forEach(eq => eqNames.add(eq));
        } catch (e) { }
      }
    });
    eqNames.forEach(eqName => {
      if (!items.some(i => i.name === eqName)) {
        items.push({ name: eqName, category: 'Equipment', identify: 'equipment' });
      }
    });
  } else if (pkgCatalogFilter === 'meals') {
    items = items.filter(i => {
      const cat = (i.category || i.cat || i.identify || '').toLowerCase();
      const name = (i.name || '').toLowerCase();
      if (cat.includes('dessert') || cat.includes('ice_cream') || name.includes('ice cream')) return false;
      if (cat.includes('drink') || cat.includes('beverage') || cat.includes('mobile_bar') || name.includes('mobile bar')) return false;
      if (cat.includes('equipment') || cat.includes('setup')) return false;
      return ['meals', 'food', 'free_choice'].includes(i.identify) || cat.includes('food') || cat.includes('meal') || cat.includes('dish');
    });
  } else if (pkgCatalogFilter === 'desserts') {
    items = items.filter(i => {
      const cat = (i.category || i.cat || i.identify || '').toLowerCase();
      const name = (i.name || '').toLowerCase();
      return ['desserts', 'dessert', 'ice_cream'].includes(i.identify) || cat.includes('dessert') || name.includes('ice cream');
    });
  } else if (pkgCatalogFilter === 'drinks') {
    items = items.filter(i => {
      const cat = (i.category || i.cat || i.identify || '').toLowerCase();
      const name = (i.name || '').toLowerCase();
      return ['drinks', 'drink', 'drinks_package', 'mobile_bar'].includes(i.identify) || cat.includes('drink') || cat.includes('beverage') || name.includes('mobile bar');
    });
  } else if (pkgCatalogFilter === 'decoration') {
    items = items.filter(i => {
      const cat = (i.category || i.cat || i.identify || '').toLowerCase();
      return ['decoration', 'decor'].includes(i.identify) || cat.includes('decor');
    });
  } else if (pkgCatalogFilter === 'equipment') {
    let eqNames = new Set();
    sbEventSetups.forEach(s => {
      if (s.equipment_items) {
        try {
          const list = typeof s.equipment_items === 'string' ? JSON.parse(s.equipment_items) : s.equipment_items;
          if (Array.isArray(list)) list.forEach(eq => eqNames.add(eq));
        } catch (e) { }
      }
    });

    items = items.filter(i => {
      const cat = (i.category || i.cat || i.identify || '').toLowerCase();
      const name = (i.name || '').toLowerCase();
      return eqNames.has(i.name) || cat.includes('equipment') || cat.includes('setup') ||
        name.includes('chair') || name.includes('table') || name.includes('cover') || name.includes('cloth') ||
        name.includes('runner') || name.includes('skirt') || name.includes('chafing') || name.includes('sound') ||
        name.includes('utensil') || name.includes('glass') || name.includes('centerpiece') || name.includes('setup');
    });

    eqNames.forEach(eqName => {
      if (!items.some(i => i.name === eqName)) {
        items.push({ name: eqName, category: 'Equipment', identify: 'equipment' });
      }
    });
  } else if (pkgCatalogFilter === 'addon') {
    items = items.filter(i => {
      const cat = (i.category || i.cat || i.identify || '').toLowerCase();
      const name = (i.name || '').toLowerCase();
      if (cat.includes('drink') || cat.includes('beverage') || cat.includes('mobile_bar') || name.includes('mobile bar')) return false;
      if (cat.includes('dessert') || cat.includes('ice_cream') || name.includes('ice cream')) return false;
      if (cat.includes('equipment') || cat.includes('setup')) return false;
      return ['addon', 'entertainment', 'addons', 'special'].includes(i.identify) || cat.includes('addon') || cat.includes('entertainment');
    });
  } else if (pkgCatalogFilter === 'freebies') {
    items = sbMenuItems.filter(i => {
      if (editingPkgSelectedItems.has(i.name)) return false;
      if (i.identify === 'ice_cream_option' || i.identify === 'mobile_bar_option') return false;
      if (typeof getSpecialParentName === 'function' && getSpecialParentName(i)) return false;
      return true;
    });
  }

  if (searchQ) {
    items = items.filter(i => i.name.toLowerCase().includes(searchQ));
  }

  list.innerHTML = items.map(item => {
    const isFreebie = pkgCatalogFilter === 'freebies';
    const isChecked = isFreebie ? editingPkgFreebies.has(item.name) : editingPkgSelectedItems.has(item.name);
    const isInherent = inherentSetupEquipments.has(item.name);

    if (isInherent) {
      return `
        <label style="display:flex; align-items:center; gap:8px; font-size:12px; color:var(--cream); cursor:not-allowed; padding:6px 8px; background:var(--bg2); border-radius:6px; border:1px solid var(--border); opacity:0.8;">
          <input type="checkbox" checked disabled style="cursor:not-allowed;">
          <span>${item.name}</span>
          <span style="font-size:10px; color:var(--gold); margin-left:auto;">Inherent Setup</span>
        </label>
      `;
    }

    return `
      <label style="display:flex; align-items:center; gap:8px; font-size:12px; color:var(--cream); cursor:pointer; padding:6px 8px; background:var(--bg2); border-radius:6px; border:1px solid var(--border);">
        <input type="checkbox" value="${item.name.replace(/"/g, '&quot;')}" ${isChecked ? 'checked' : ''} onchange="togglePkgItemSelection('${item.name.replace(/'/g, "\\'")}', '${item.identify}', ${isFreebie}, this.checked)">
        <span>${item.name}</span>
        <span style="font-size:10px; color:var(--gold); margin-left:auto;">${item.category || item.identify || 'Equipment'}</span>
      </label>
    `;
  }).join('');
}

function togglePkgItemSelection(itemName, identify, isFreebie, isChecked) {
  if (isFreebie) {
    if (isChecked) editingPkgFreebies.add(itemName);
    else editingPkgFreebies.delete(itemName);
  } else {
    if (isChecked) {
      editingPkgSelectedItems.add(itemName);
      if (identify === 'desserts' || identify === 'dessert') {
        editingPkgSelectedItems.add('Dessert Spoon');
        editingPkgSelectedItems.add('Dessert Plate');
      }
    } else {
      editingPkgSelectedItems.delete(itemName);
    }
  }

  renderPkgSetupItemsSummary();
  renderPkgSelectedSummaries();
}

function onPkgEventSetupChange() {
  const setupId = document.getElementById('ap-pkg-event-setup').value;

  // CLEANUP: Remove old inherent setup equipment items from editingPkgSelectedItems
  inherentSetupEquipments.forEach(eq => editingPkgSelectedItems.delete(eq));
  inherentSetupEquipments.clear();

  const found = sbEventSetups.find(s => String(s.id) === String(setupId));
  if (found && found.equipment_items) {
    let items = [];
    try {
      items = typeof found.equipment_items === 'string' ? JSON.parse(found.equipment_items) : found.equipment_items;
    } catch (e) { }

    items.forEach(eq => {
      inherentSetupEquipments.add(eq);
      editingPkgSelectedItems.add(eq);
    });
  }

  renderPkgSetupItemsSummary();
  renderPkgCatalogBrowser();
  renderPkgSelectedSummaries();
}

function renderPkgSelectedSummaries() {
  const foodBox = document.getElementById('ap-pkg-selected-food');
  const dessertBox = document.getElementById('ap-pkg-selected-desserts');
  const drinkBox = document.getElementById('ap-pkg-selected-drinks');
  const decorBox = document.getElementById('ap-pkg-selected-decor');
  const addonBox = document.getElementById('ap-pkg-selected-addons');
  const freebieBox = document.getElementById('ap-pkg-selected-freebies');

  const foodArr = [];
  const dessertArr = [];
  const drinkArr = [];
  const decorArr = [];
  const addonArr = [];

  // Build a set of all Equipment Setup item names & setup names to filter them out of food summary rows
  const equipmentNames = new Set();
  if (typeof sbEventSetups !== 'undefined' && Array.isArray(sbEventSetups)) {
    sbEventSetups.forEach(s => {
      if (s.name) equipmentNames.add(s.name);
      if (s.equipment_items) {
        try {
          const list = typeof s.equipment_items === 'string' ? JSON.parse(s.equipment_items) : s.equipment_items;
          if (Array.isArray(list)) list.forEach(eq => equipmentNames.add(eq));
        } catch (e) { }
      }
    });
  }

  editingPkgSelectedItems.forEach(name => {
    // 1. Skip equipment setup items & setup names (rendered at top under Equipment Setup)
    if (equipmentNames.has(name) || inherentSetupEquipments.has(name)) return;

    let found = sbMenuItems.find(m => m.name === name);
    if (!found && typeof CAT !== 'undefined') {
      found = CAT.find(c => c.name === name);
    }
    if (!found && typeof adminCatalog !== 'undefined') {
      found = adminCatalog.find(c => c.name === name);
    }

    const itemCat = (found ? (found.category || found.cat || found.identify || '') : '').toLowerCase();
    const itemIdentify = (found ? (found.identify || '') : '').toLowerCase();
    const nameLower = name.toLowerCase();

    // 2. Skip items categorized explicitly as equipment/setup/tableware
    if (
      itemCat.includes('equipment') || itemCat.includes('setup') || itemIdentify.includes('equipment') || itemIdentify.includes('setup') ||
      nameLower.includes('plate') || nameLower.includes('spoon') || nameLower.includes('fork') || nameLower.includes('table') ||
      nameLower.includes('chair') || nameLower.includes('chafing') || nameLower.includes('glass') || nameLower.includes('napkin') ||
      nameLower.includes('runner') || nameLower.includes('skirt') || nameLower.includes('cover') || nameLower.includes('centerpiece') ||
      nameLower.includes('pitcher') || nameLower.includes('tray') || nameLower.includes('tongs') || nameLower.includes('sandok') || nameLower.includes('bucket') || nameLower.includes('sound')
    ) {
      return;
    }

    if (
      itemCat.includes('dessert') || itemIdentify.includes('dessert') || itemIdentify.includes('ice_cream') || nameLower.includes('ice cream')
    ) {
      dessertArr.push(name);
    } else if (
      itemCat.includes('drink') || itemCat.includes('beverage') || itemIdentify.includes('drink') || itemIdentify.includes('mobile_bar') || nameLower.includes('mobile bar')
    ) {
      drinkArr.push(name);
    } else if (
      itemCat.includes('decor') || itemIdentify.includes('decor')
    ) {
      decorArr.push(name);
    } else if (
      itemCat.includes('addon') || itemCat.includes('entertainment') || ['addon', 'entertainment', 'special'].includes(itemIdentify)
    ) {
      addonArr.push(name);
    } else if (
      itemCat.includes('food') || itemCat.includes('meal') || itemCat.includes('dish') || ['meals', 'food', 'free_choice'].includes(itemIdentify)
    ) {
      foodArr.push(name);
    } else {
      // Fallbacks
      if (nameLower.includes('bar') || nameLower.includes('drink') || nameLower.includes('beverage') || nameLower.includes('juice') || nameLower.includes('tea')) {
        drinkArr.push(name);
      } else if (nameLower.includes('cake') || nameLower.includes('flan') || nameLower.includes('sweet') || nameLower.includes('ice cream')) {
        dessertArr.push(name);
      } else {
        foodArr.push(name);
      }
    }
  });

  const makeBadges = (arr, defaultText = 'None selected') => arr.length > 0
    ? arr.map(n => `<span style="font-size:10px; font-weight:600; color:var(--cream);">${n}</span>`).join('<span style="color:var(--text-dim); margin:0 6px;">&bull;</span>')
    : `<span style="color:var(--text-dim); font-size:11px;">${defaultText}</span>`;

  if (foodBox) foodBox.innerHTML = makeBadges(foodArr);
  if (dessertBox) dessertBox.innerHTML = makeBadges(dessertArr);
  if (drinkBox) drinkBox.innerHTML = makeBadges(drinkArr);
  if (decorBox) decorBox.innerHTML = makeBadges(decorArr);
  if (addonBox) addonBox.innerHTML = makeBadges(addonArr);

  const freebieArr = Array.from(editingPkgFreebies);
  if (freebieBox) freebieBox.innerHTML = makeBadges(freebieArr, 'None added');
  if (typeof syncPkgBrowserHeight === 'function') syncPkgBrowserHeight();
}

function syncPkgBrowserHeight() {
  const leftCol = document.getElementById('ap-pkg-left-col');
  const rightBox = document.getElementById('ap-pkg-right-col');
  const browserList = document.getElementById('ap-catalog-browser-list');
  if (!leftCol || !rightBox || !browserList) return;

  requestAnimationFrame(() => {
    const leftH = leftCol.offsetHeight;
    if (leftH > 80) {
      rightBox.style.height = leftH + 'px';
      rightBox.style.maxHeight = leftH + 'px';

      const chipsEl = document.getElementById('ap-catalog-filter-chips');
      const searchEl = document.getElementById('ap-catalog-search');
      const headerEl = rightBox.querySelector('div');

      const headerH = headerEl ? headerEl.offsetHeight : 20;
      const chipsH = chipsEl ? chipsEl.offsetHeight : 60;
      const searchH = searchEl ? searchEl.offsetHeight : 38;
      const nonListH = headerH + chipsH + searchH + 60;
      const targetListH = Math.max(120, leftH - nonListH);

      browserList.style.height = targetListH + 'px';
      browserList.style.maxHeight = targetListH + 'px';
      browserList.style.overflowY = 'auto';
    }
  });
}

let pkgLeftColObserver = null;
function initPkgBrowserHeightSync() {
  const leftCol = document.getElementById('ap-pkg-left-col');
  if (!leftCol) return;
  if (!pkgLeftColObserver && typeof ResizeObserver !== 'undefined') {
    pkgLeftColObserver = new ResizeObserver(() => {
      syncPkgBrowserHeight();
    });
  }
  if (pkgLeftColObserver) {
    try { pkgLeftColObserver.observe(leftCol); } catch (e) {}
  }
  syncPkgBrowserHeight();
  setTimeout(syncPkgBrowserHeight, 50);
  setTimeout(syncPkgBrowserHeight, 150);
  setTimeout(syncPkgBrowserHeight, 300);
}

function populateEventSetupDropdown() {
  const select = document.getElementById('ap-pkg-event-setup');
  if (!select) return;
  const activeSetups = sbEventSetups.filter(s => s.is_active !== false);
  select.innerHTML = '<option value="">: Select Event Setup :</option>' +
    activeSetups.map(s => `<option value="${s.id}">${s.name}</option>`).join('');
}

function openAddPremadeModal() {
  document.getElementById('ap-pkg-id').value = '';
  document.getElementById('ap-pkg-supabase-id').value = '';
  document.getElementById('ap-pkg-name').value = '';
  document.getElementById('ap-pkg-cat').value = 'Wedding';
  document.getElementById('ap-pkg-theme').value = '';
  document.getElementById('ap-pkg-pricing-mode').value = 'majorly_set';
  document.getElementById('ap-pkg-desc').value = '';
  document.getElementById('ap-pkg-price-per-head').value = '';

  editingPkgTiers = [{ pax: 50, price: 45000 }];
  editingPkgSelectedItems.clear();
  editingPkgFreebies.clear();
  inherentSetupEquipments.clear();

  // Reset catalog filter to 'all' and clear search input
  pkgCatalogFilter = 'all';
  document.querySelectorAll('#ap-catalog-filter-chips .cat-filter-chip').forEach(c => {
    if (c.getAttribute('data-filter') === 'all') c.classList.add('active');
    else c.classList.remove('active');
  });
  const searchInput = document.getElementById('ap-catalog-search');
  if (searchInput) searchInput.value = '';

  populateEventSetupDropdown();
  onPkgPricingModeChange();
  onPkgEventSetupChange();
  renderPkgTiers();
  renderPkgCatalogBrowser();
  renderPkgSelectedSummaries();

  document.getElementById('admin-pkg-modal-title').textContent = 'Add Pre-made Package';

  // Reset image upload
  apClearImage();

  document.getElementById('admin-pkg-modal-overlay').classList.add('on');
  document.getElementById('admin-pkg-modal').classList.add('open');
  initPkgBrowserHeightSync();
}

function openEditPremadeModal(id) {
  const p = sbPremadePackages.find(i => i.id === id);
  if (!p) return;

  document.getElementById('ap-pkg-id').value = p.id;
  document.getElementById('ap-pkg-supabase-id').value = p.id;
  document.getElementById('ap-pkg-name').value = p.name || '';
  document.getElementById('ap-pkg-cat').value = p.occasion || 'Wedding';
  document.getElementById('ap-pkg-theme').value = p.theme || '';
  document.getElementById('ap-pkg-desc').value = p.description || '';
  document.getElementById('ap-pkg-price-per-head').value = p.price_per_head || '';

  let pricingMode = 'majorly_set';
  if (p.pricing_mode === 'per_head' || p.badge === 'Dynamically Set') {
    pricingMode = 'per_head';
  } else {
    pricingMode = 'majorly_set';
  }
  document.getElementById('ap-pkg-pricing-mode').value = pricingMode;

  if (p.price_tiers && Array.isArray(p.price_tiers)) {
    editingPkgTiers = p.price_tiers;
  } else if (p.fixed_price) {
    editingPkgTiers = [{ pax: p.fixed_pax || 50, price: p.fixed_price }];
  } else {
    editingPkgTiers = [{ pax: 50, price: 45000 }];
  }

  editingPkgSelectedItems.clear();
  editingPkgFreebies.clear();

  // Build a normalized set of all event setup names to prevent setup titles from entering consumable items
  const allSetupNames = new Set((sbEventSetups || []).map(s => (s.name || '').toLowerCase().trim()).filter(Boolean));
  const items = sbPremadePackageItems.filter(i => i.package_id === p.id);
  const setupRow = items.find(i => i.item_source === 'event_setup');

  items.forEach(i => {
    // Exclude event setup title reference row from consumable selected items
    if (i.item_source === 'event_setup') return;
    if (allSetupNames.has((i.item_name || '').toLowerCase().trim())) return;
    if (i.is_freebie) editingPkgFreebies.add(i.item_name);
    else editingPkgSelectedItems.add(i.item_name);
  });

  populateEventSetupDropdown();
  onPkgPricingModeChange();

  // Dynamically detect matching setup from event_setup_id, setup link row, or items
  let matchedSetupId = '';
  if (p.event_setup_id) {
    matchedSetupId = String(p.event_setup_id);
  } else if (setupRow) {
    const foundSetup = (sbEventSetups || []).find(s => (s.name || '').toLowerCase() === (setupRow.item_name || '').toLowerCase());
    if (foundSetup) matchedSetupId = String(foundSetup.id);
  }
  if (!matchedSetupId) {
    // Infer matching setup from items or default to Complete Setup (1)
    if (editingPkgSelectedItems.has('Tiffany Chair') || editingPkgSelectedItems.has('Rectangular Table (6ft)')) {
      matchedSetupId = '1'; // Complete Setup
    } else if (editingPkgSelectedItems.has('Monoblock Chair')) {
      matchedSetupId = '2'; // Complete Setup w/ Basic Chairs
    } else if (editingPkgSelectedItems.has('Table Skirt')) {
      matchedSetupId = '3'; // Buffet + Styling
    } else if (editingPkgSelectedItems.has('Chafing Dish')) {
      matchedSetupId = '4'; // Buffet Only
    } else {
      matchedSetupId = '1'; // Default Complete Setup
    }
  }

  const setupSelect = document.getElementById('ap-pkg-event-setup');
  if (setupSelect) {
    setupSelect.value = matchedSetupId;
    onPkgEventSetupChange();
  }

  // Reset catalog filter to 'all' and clear search input
  pkgCatalogFilter = 'all';
  document.querySelectorAll('#ap-catalog-filter-chips .cat-filter-chip').forEach(c => {
    if (c.getAttribute('data-filter') === 'all') c.classList.add('active');
    else c.classList.remove('active');
  });
  const editSearchInput = document.getElementById('ap-catalog-search');
  if (editSearchInput) editSearchInput.value = '';

  renderPkgTiers();
  renderPkgCatalogBrowser();
  renderPkgSelectedSummaries();

  document.getElementById('admin-pkg-modal-title').textContent = 'Edit Pre-made Package';

  // Pre-populate existing image if any
  apClearImage();
  if (p.image_url) {
    document.getElementById('ap-img-url').value = p.image_url;
    _showImagePreview('ap-img-preview', 'ap-img-preview-wrap', 'ap-img-drop-zone', p.image_url);
  }

  document.getElementById('admin-pkg-modal-overlay').classList.add('on');
  document.getElementById('admin-pkg-modal').classList.add('open');
  initPkgBrowserHeightSync();
}

function closeAdminPkgModal() {
  if (pkgLeftColObserver) {
    try { pkgLeftColObserver.disconnect(); } catch (e) {}
    pkgLeftColObserver = null;
  }
  document.getElementById('admin-pkg-modal-overlay').classList.remove('on');
  document.getElementById('admin-pkg-modal').classList.remove('open');
}

async function saveAdminPkg() {
  const sb = window.supabaseClient;
  if (!sb) return alert('Database connection not ready.');

  const id = document.getElementById('ap-pkg-id').value;
  const name = document.getElementById('ap-pkg-name').value.trim();
  const occasion = document.getElementById('ap-pkg-cat').value;
  const theme = document.getElementById('ap-pkg-theme').value.trim();
  const pricing_mode = document.getElementById('ap-pkg-pricing-mode').value;
  const description = document.getElementById('ap-pkg-desc').value.trim();

  if (!name) return alert('Package Name is required');

  const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  const badge = pricing_mode === 'per_head' ? 'Dynamically Set' : 'Majorly Set';

  let fixed_price = null;
  let fixed_pax = null;
  let price_per_head = null;
  let price_tiers = null;

  if (pricing_mode === 'per_head') {
    price_per_head = parseFloat(document.getElementById('ap-pkg-price-per-head').value) || 0;
    if (price_per_head > 999999) return alert('Price per head cannot exceed 6 digits (maximum ₱999,999).');
  } else {
    editingPkgTiers.sort((a, b) => (parseInt(a.pax) || 0) - (parseInt(b.pax) || 0));
    for (const t of editingPkgTiers) {
      if (parseFloat(t.price) > 999999) {
        return alert('Tier price cannot exceed 6 digits (maximum ₱999,999).');
      }
    }
    if (editingPkgTiers.length === 1) {
      fixed_pax = parseInt(editingPkgTiers[0].pax) || 50;
      fixed_price = parseFloat(editingPkgTiers[0].price) || 0;
      if (fixed_price > 999999) return alert('Package price cannot exceed 6 digits (maximum ₱999,999).');
    } else {
      price_tiers = editingPkgTiers.map(t => ({ pax: parseInt(t.pax) || 0, price: parseFloat(t.price) || 0 }));
    }
  }

  const imageUrl = (document.getElementById('ap-img-url')?.value || '').trim() || null;

  const pkgPayload = {
    slug,
    name,
    badge,
    pricing_mode,
    fixed_price,
    fixed_pax,
    price_per_head,
    occasion,
    theme,
    description,
    price_tiers,
    is_active: true,
    image_url: imageUrl
  };

  try {
    let pkgId = id;
    if (id) {
      const { error: updErr } = await sb.from('premade_packages').update(pkgPayload).eq('id', id);
      if (updErr) throw updErr;
      await sb.from('premade_package_items').delete().eq('package_id', id);
    } else {
      const { data: insData, error: insErr } = await sb.from('premade_packages').insert([pkgPayload]).select();
      if (insErr) throw insErr;
      if (insData && insData.length > 0) pkgId = insData[0].id;
    }

    const eventSetupId = document.getElementById('ap-pkg-event-setup').value;
    const selectedSetupObj = sbEventSetups.find(s => String(s.id) === String(eventSetupId));

    const packageItems = [];
    let order = 1;

    // Save selected equipment setup reference row
    if (selectedSetupObj) {
      packageItems.push({
        package_id: pkgId,
        item_name: selectedSetupObj.name,
        item_source: 'event_setup',
        is_free: false,
        is_freebie: false,
        display_order: order++
      });
    }

    // Save selected catalog menu items (do not duplicate inherent setup equipments or setup name)
    editingPkgSelectedItems.forEach(name => {
      if (inherentSetupEquipments.has(name)) return;
      if (selectedSetupObj && name.toLowerCase().trim() === selectedSetupObj.name.toLowerCase().trim()) return;
      packageItems.push({
        package_id: pkgId,
        item_name: name,
        item_source: 'menu_items',
        is_free: false,
        is_freebie: false,
        display_order: order++
      });
    });

    // Save freebie items (excluding inherent setup equipments)
    editingPkgFreebies.forEach(name => {
      if (inherentSetupEquipments.has(name)) return;
      if (selectedSetupObj && name.toLowerCase().trim() === selectedSetupObj.name.toLowerCase().trim()) return;
      packageItems.push({
        package_id: pkgId,
        item_name: name,
        item_source: 'menu_items',
        is_free: true,
        is_freebie: true,
        display_order: order++
      });
    });

    if (packageItems.length > 0) {
      const { error: itemErr } = await sb.from('premade_package_items').insert(packageItems);
      if (itemErr) throw itemErr;
    }

    if (typeof window.logCatalogActivity === 'function') {
      if (id) {
        window.logCatalogActivity('Updated Pre-made Package', `Updated package "${name}" (${occasion})`, { package_id: id, package_name: name, occasion });
      } else {
        window.logCatalogActivity('Created Pre-made Package', `Created package "${name}" (${occasion})`, { package_id: pkgId, package_name: name, occasion });
      }
    }

    await initAdminPackages();
    closeAdminPkgModal();
    notifyLiveCatalogSync();
  } catch (e) {
    console.error('Package save error:', e);
    alert('Failed to save package: ' + e.message);
  }
}

async function togglePackageVisibility(id, isCurrentlyHidden) {
  const sb = window.supabaseClient;
  if (!sb) return;

  try {
    const { error } = await sb.from('premade_packages').update({ is_active: isCurrentlyHidden }).eq('id', id);
    if (error) throw error;

    const pkg = sbPremadePackages.find(p => p.id === id);
    const pkgName = pkg ? pkg.name : id;
    if (typeof window.logCatalogActivity === 'function') {
      const actLabel = isCurrentlyHidden ? 'Unhid Pre-made Package' : 'Hid Pre-made Package';
      window.logCatalogActivity(actLabel, `${isCurrentlyHidden ? 'Unhid' : 'Hid'} package "${pkgName}"`, { package_id: id, package_name: pkgName, is_active: isCurrentlyHidden });
    }

    await initAdminPackages();
    notifyLiveCatalogSync();
  } catch (e) {
    console.error('Toggle package visibility error:', e);
    alert('Failed to update package visibility: ' + e.message);
  }
}

// ── EVENT SETUPS STATE & RENDERING ──────────────────────────────
let editingEventSetupId = null;
let esEquipmentsCache = [];
let esSelectedEquipNames = new Set();
let esEquipCategoryFilter = 'all';

async function fetchEquipmentsForEventSetup() {
  const sb = window.supabaseClient || window.supabase;
  if (!sb) return [];
  if (esEquipmentsCache.length > 0) return esEquipmentsCache;
  try {
    const { data, error } = await sb.from('equipment_inventory')
      .select('id, name, category, type, status')
      .neq('status', 'disposed')
      .order('name', { ascending: true });
    if (data) esEquipmentsCache = data;
  } catch (e) {
    console.error('[EventSetup] Error fetching equipment inventory:', e);
  }
  return esEquipmentsCache;
}

function renderAdminEventSetups() {
  const container = document.getElementById('admin-eventsetups-grid');
  if (!container) return;

  const searchInput = document.getElementById('admin-eventsetups-search');
  const searchQ = searchInput ? searchInput.value.toLowerCase().trim() : '';

  let list = sbEventSetups;
  if (searchQ) {
    list = list.filter(s =>
      (s.name || '').toLowerCase().includes(searchQ) ||
      (s.description || '').toLowerCase().includes(searchQ)
    );
  }

  if (list.length === 0) {
    container.innerHTML = '<div style="text-align:center; padding:40px; color:var(--text-dim);">No event setups found.</div>';
    return;
  }

  container.innerHTML = list.map(s => {
    let items = [];
    try {
      items = typeof s.equipment_items === 'string' ? JSON.parse(s.equipment_items) : (s.equipment_items || []);
    } catch (e) { }

    const isActive = s.is_active !== false;

    return `
      <div style="background:var(--bg2); border:1px solid var(--border); border-radius:12px; padding:20px; ${!isActive ? 'opacity:0.6;' : ''}">
        <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:8px; flex-wrap:wrap; gap:8px;">
          <div style="display:flex; align-items:center; gap:10px;">
            <div style="font-size:18px; font-weight:700; color:var(--cream);">${s.name}</div>
            ${!isActive ? '<span style="font-size:10px; font-weight:700; color:var(--red); text-transform:uppercase;">Disabled</span>' : ''}
          </div>
          <span style="font-size:11px; color:var(--gold); font-weight:700;">${items.length} Equipment Included</span>
        </div>
        <div style="font-size:13px; color:var(--text-dim); margin-bottom:14px; line-height:1.5;">${s.description}</div>
        <div style="display:flex; flex-wrap:wrap; gap:6px; margin-bottom:16px;">
          ${items.map(i => `<span style="font-size:11px; font-weight:600; color:var(--cream);">${i}</span>`).join('<span style="color:var(--text-dim); margin:0 4px;">&bull;</span>')}
        </div>
        <div style="display:flex; justify-content:flex-end; gap:8px; border-top:1px solid var(--border); padding-top:12px;">
          <button class="btn-outline" style="font-size:12px; padding:4px 12px;" onclick="openEditEventSetupModal('${s.id}')">Edit Setup</button>
          <button class="btn-outline" style="font-size:12px; padding:4px 12px; font-weight:700; ${isActive ? 'background:#dc2626 !important; color:#ffffff !important; border:none !important;' : 'background:#16a34a !important; color:#ffffff !important; border:none !important;'}" onclick="toggleEventSetupActive('${s.id}', ${isActive})">
            ${isActive ? 'Disable Setup' : 'Enable Setup'}
          </button>
        </div>
      </div>
    `;
  }).join('');
}

async function toggleEventSetupActive(id, isCurrentlyActive) {
  const sb = window.supabaseClient || window.supabase;
  if (!sb) return;

  try {
    const { error } = await sb.from('event_setups').update({ is_active: !isCurrentlyActive }).eq('id', id);
    if (error) throw error;

    await initAdminPackages();
    notifyLiveCatalogSync();
  } catch (e) {
    console.error('Toggle event setup status error:', e);
    alert('Failed to update event setup status: ' + e.message);
  }
}

async function openAddEventSetupModal() {
  editingEventSetupId = null;
  document.getElementById('eventsetup-modal-title').innerText = 'Add Event Setup';
  document.getElementById('es-id').value = '';
  document.getElementById('es-name').value = '';
  document.getElementById('es-desc').value = '';
  esSelectedEquipNames.clear();
  esEquipCategoryFilter = 'all';
  const searchEl = document.getElementById('es-equip-search');
  if (searchEl) searchEl.value = '';

  await fetchEquipmentsForEventSetup();
  renderAdminEventSetupSelectedChips();
  renderAdminEventSetupEquipList();

  const overlay = document.getElementById('eventsetup-modal-overlay');
  const modal = document.getElementById('eventsetup-modal');
  if (overlay) { overlay.classList.add('on'); overlay.style.display = 'block'; }
  if (modal) { modal.classList.add('open'); modal.classList.add('on'); modal.style.display = 'block'; }
}

async function openEditEventSetupModal(id) {
  const setup = sbEventSetups.find(s => String(s.id) === String(id));
  if (!setup) return;

  editingEventSetupId = setup.id;
  document.getElementById('eventsetup-modal-title').innerText = 'Edit Event Setup';
  document.getElementById('es-id').value = setup.id;
  document.getElementById('es-name').value = setup.name || '';
  document.getElementById('es-desc').value = setup.description || '';
  esSelectedEquipNames.clear();

  let items = [];
  try {
    items = typeof setup.equipment_items === 'string' ? JSON.parse(setup.equipment_items) : (setup.equipment_items || []);
  } catch (e) { }
  items.forEach(i => esSelectedEquipNames.add(i));

  esEquipCategoryFilter = 'all';
  const searchEl = document.getElementById('es-equip-search');
  if (searchEl) searchEl.value = '';

  await fetchEquipmentsForEventSetup();
  renderAdminEventSetupSelectedChips();
  renderAdminEventSetupEquipList();

  const overlay = document.getElementById('eventsetup-modal-overlay');
  const modal = document.getElementById('eventsetup-modal');
  if (overlay) { overlay.classList.add('on'); overlay.style.display = 'block'; }
  if (modal) { modal.classList.add('open'); modal.classList.add('on'); modal.style.display = 'block'; }
}

function closeAdminEventSetupModal() {
  const overlay = document.getElementById('eventsetup-modal-overlay');
  const modal = document.getElementById('eventsetup-modal');
  if (overlay) { overlay.classList.remove('on'); overlay.style.display = 'none'; }
  if (modal) { modal.classList.remove('open'); modal.classList.remove('on'); modal.style.display = 'none'; }
}

function filterEsEquipCategory(cat) {
  esEquipCategoryFilter = cat;
  renderAdminEventSetupEquipList();
}

// Render the selected equipments chips list in Add/Edit Event Setup modal
function renderAdminEventSetupSelectedChips() {
  const container = document.getElementById('es-selected-container');
  const countEl = document.getElementById('es-selected-count');
  const chipsEl = document.getElementById('es-selected-chips');
  if (!container || !chipsEl) return;

  const names = Array.from(esSelectedEquipNames);
  if (countEl) countEl.textContent = names.length;

  if (names.length === 0) {
    container.style.display = 'none';
    chipsEl.innerHTML = '';
    return;
  }

  container.style.display = 'block';
  chipsEl.innerHTML = names.map(n => {
    // Check if this item is in current inventory cache
    const inInv = (esEquipmentsCache || []).some(eq => (eq.name || '').toLowerCase() === n.toLowerCase());
    const extraTag = inInv ? '' : ' <span style="font-size:9px; color:var(--text-dim); margin-left:2px;">(unlisted)</span>';
    return `<span style="display:inline-flex; align-items:center; gap:6px; font-size:11px; padding:3px 8px; background:var(--bg2); color:var(--cream); border:1px solid var(--border); border-radius:4px;">
      <span>${n}${extraTag}</span>
      <span onclick="removeEsEquipSelection('${n.replace(/'/g, "\\'")}')" style="cursor:pointer; color:var(--text-dim); font-size:13px; font-weight:700; margin-left:4px; line-height:1;" title="Remove this equipment">&times;</span>
    </span>`;
  }).join(' ');
}
window.renderAdminEventSetupSelectedChips = renderAdminEventSetupSelectedChips;

// Allow direct removal of any item from the event setup's selected equipments
function removeEsEquipSelection(eqName) {
  esSelectedEquipNames.delete(eqName);
  renderAdminEventSetupSelectedChips();
  renderAdminEventSetupEquipList();
}
window.removeEsEquipSelection = removeEsEquipSelection;

function toggleEsEquipSelection(eqName, isChecked) {
  if (isChecked) esSelectedEquipNames.add(eqName);
  else esSelectedEquipNames.delete(eqName);
  renderAdminEventSetupSelectedChips();
}

function renderAdminEventSetupEquipList() {
  const container = document.getElementById('es-equip-list');
  const filterContainer = document.getElementById('es-category-filters');
  if (!container) return;

  const categories = ['all'];
  esEquipmentsCache.forEach(eq => {
    const cat = (eq.category || eq.type || 'Equipment').trim();
    if (cat && !categories.includes(cat)) categories.push(cat);
  });

  if (filterContainer) {
    filterContainer.innerHTML = categories.map(cat => {
      const isSelected = esEquipCategoryFilter === cat;
      const label = cat === 'all' ? 'All' : cat;
      return `<button class="btn-outline" style="font-size:10px; padding:3px 8px; border:none; background:${isSelected ? 'var(--gold, #c49a3c)' : '#4b5563'} !important; color:#ffffff !important; font-weight:700;" onclick="filterEsEquipCategory('${cat.replace(/'/g, "\\'")}')">${label}</button>`;
    }).join(' ');
  }

  const searchEl = document.getElementById('es-equip-search');
  const searchQ = searchEl ? searchEl.value.toLowerCase().trim() : '';

  // Include any selected items that might not currently exist in esEquipmentsCache (e.g. unlisted/renamed)
  const missingSelected = [];
  esSelectedEquipNames.forEach(name => {
    if (!esEquipmentsCache.some(eq => (eq.name || '').toLowerCase() === name.toLowerCase())) {
      missingSelected.push({ name: name, category: 'Unlisted Equipment', type: 'Unlisted', isUnlisted: true });
    }
  });

  let list = [...missingSelected, ...esEquipmentsCache];
  if (esEquipCategoryFilter !== 'all') {
    list = list.filter(eq => (eq.category || eq.type || '').trim() === esEquipCategoryFilter);
  }
  if (searchQ) {
    list = list.filter(eq => (eq.name || '').toLowerCase().includes(searchQ));
  }

  if (list.length === 0) {
    container.innerHTML = '<div style="grid-column:1/-1; text-align:center; padding:20px; color:var(--text-dim); font-size:12px;">No equipment found.</div>';
    return;
  }

  container.innerHTML = list.map(eq => {
    const isChecked = esSelectedEquipNames.has(eq.name);
    return `
      <label style="display:flex; align-items:center; gap:8px; font-size:12px; color:var(--cream); cursor:pointer; padding:6px 8px; background:var(--bg3); border-radius:6px; border:1px solid var(--border);">
        <input type="checkbox" value="${eq.name.replace(/"/g, '&quot;')}" ${isChecked ? 'checked' : ''} onchange="toggleEsEquipSelection(this.value, this.checked)">
        <span>${eq.name}${eq.isUnlisted ? ' <em style="font-size:10px; color:var(--text-dim);">(unlisted)</em>' : ''}</span>
        <span style="font-size:10px; color:var(--gold); margin-left:auto;">${eq.category || eq.type || 'Equipment'}</span>
      </label>
    `;
  }).join('');
}

async function saveAdminEventSetup() {
  const name = document.getElementById('es-name').value.trim();
  const desc = document.getElementById('es-desc').value.trim();

  if (!name) {
    alert('Please enter a setup name.');
    return;
  }
  if (!desc) {
    alert('Please enter a setup description.');
    return;
  }

  const equipmentArr = Array.from(esSelectedEquipNames);
  const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');

  const sb = window.supabaseClient || window.supabase;
  if (!sb) return;

  try {
    const payload = {
      name: name,
      slug: slug,
      description: desc,
      equipment_items: JSON.stringify(equipmentArr),
      is_active: true
    };

    if (editingEventSetupId) {
      const { error } = await sb.from('event_setups').update(payload).eq('id', editingEventSetupId);
      if (error) throw error;
    } else {
      const nextSort = sbEventSetups.length > 0 ? Math.max(...sbEventSetups.map(s => s.sort_order || 0)) + 1 : 1;
      payload.sort_order = nextSort;

      const { error } = await sb.from('event_setups').insert(payload);
      if (error) throw error;
    }

    if (typeof window.logCatalogActivity === 'function') {
      if (editingEventSetupId) {
        window.logCatalogActivity('Updated Event Setup', `Updated event setup "${name}" with ${equipmentArr.length} equipment items`, { setup_id: editingEventSetupId, setup_name: name });
      } else {
        window.logCatalogActivity('Created Event Setup', `Created event setup "${name}" with ${equipmentArr.length} equipment items`, { setup_name: name });
      }
    }

    closeAdminEventSetupModal();
    await initAdminPackages();
    notifyLiveCatalogSync();
  } catch (e) {
    console.error('Save event setup error:', e);
    alert('Failed to save event setup: ' + e.message);
  }
}

// ==========================================
// TOP CUSTOMER ANALYTICS LOGIC
// ==========================================
// We'll calculate the top customer by finding the user with the most past/active reservations
function updateTopCustomerStat() {
  setTimeout(() => {
    // Assuming ALL_RESERVATIONS exists from admin.js
    if (typeof ALL_RESERVATIONS !== 'undefined' && ALL_RESERVATIONS.length > 0) {
      const counts = {};
      ALL_RESERVATIONS.forEach(r => {
        if (r.customer && r.customer.email) {
          counts[r.customer.email] = (counts[r.customer.email] || 0) + 1;
        }
      });
      let topUserEmail = null;
      let topCount = 0;
      for (const [email, count] of Object.entries(counts)) {
        if (count > topCount) {
          topCount = count;
          topUserEmail = email;
        }
      }
      if (topUserEmail) {
        // Find name
        const res = ALL_RESERVATIONS.find(r => r.customer && r.customer.email === topUserEmail);
        const name = res.customer.name || topUserEmail.split('@')[0];
        const nameEl = document.getElementById('top-customer-name');
        const countEl = document.getElementById('top-customer-bookings');
        if (nameEl) nameEl.textContent = name;
        if (countEl) countEl.textContent = topCount + ' return bookings';
      }
    }
  }, 3000); // Wait a bit for ALL_RESERVATIONS to be populated
}

// Hook into existing init
const oldInitData = window.initData;
if (typeof oldInitData === 'function') {
  window.initData = async function () {
    await oldInitData();
    updateTopCustomerStat();
    initAdminPackages(); // initialize in background
  }
} else {
  // if no initData, just run
  document.addEventListener('DOMContentLoaded', () => {
    updateTopCustomerStat();
    initAdminPackages();
  });
}


function toggleAdminChatPanel() {
  const panel = document.getElementById('admin-chat-drawer');
  if (panel) {
    if (panel.classList.contains('open')) {
      panel.classList.remove('open');
    } else {
      panel.classList.add('open');
      initAdminChat(); // Refresh chats when opened
    }
  }
}

function syncSbMenuItemsToCAT(rows) {
  if (!rows || !Array.isArray(rows) || rows.length === 0) return;

  const iceCreamSubNames = new Set();
  const mobileBarSubNames = new Set();

  rows.forEach(row => {
    const ing = row.ingredients || '';
    const rName = (row.name || '').toLowerCase();
    if (typeof ing === 'string' && ing.includes('sub_items:')) {
      const subStr = ing.split('sub_items:')[1];
      if (subStr) {
        const names = subStr.split(',').map(s => s.trim().toLowerCase());
        if (rName.includes('ice cream')) {
          names.forEach(n => iceCreamSubNames.add(n));
        } else if (rName.includes('mobile bar')) {
          names.forEach(n => mobileBarSubNames.add(n));
        }
      }
    }
  });

  const newCatItems = rows.map(row => {
    const nmLower = (row.name || '').toLowerCase();
    let cat = 'food';
    const rowCat = (row.category || '').toLowerCase();
    const rowIdent = (row.identify || '').toLowerCase();

    if (rowIdent === 'desserts' || rowIdent === 'ice_cream' || rowIdent === 'ice_cream_option' || rowCat.includes('dessert') || nmLower.includes('ice cream')) {
      cat = 'dessert';
    } else if (rowIdent === 'drinks' || rowIdent === 'drinks_package' || rowIdent === 'mobile_bar' || rowIdent === 'mobile_bar_option' || rowCat.includes('drink') || nmLower.includes('mobile bar') || nmLower.includes('unlimited drinks')) {
      cat = 'drink';
    } else if (rowIdent === 'decoration') {
      cat = 'decoration';
    } else if (rowIdent === 'addon') {
      cat = 'entertainment';
    }

    let identify = row.identify;
    const isIceCreamMaster = identify === 'ice_cream' || (nmLower.includes('ice cream') && (row.ingredients || '').startsWith('per_'));
    const isMobileBarMaster = identify === 'mobile_bar' || (nmLower.includes('mobile bar') && (row.ingredients || '').startsWith('per_'));

    if (isIceCreamMaster) {
      identify = 'ice_cream';
      cat = 'dessert';
    } else if (isMobileBarMaster) {
      identify = 'mobile_bar';
      cat = 'drink';
    } else if (identify === 'ice_cream_option' || iceCreamSubNames.has(nmLower)) {
      identify = 'ice_cream_option';
      cat = 'dessert';
    } else if (
      identify === 'mobile_bar_option' ||
      mobileBarSubNames.has(nmLower) ||
      (cat === 'drink' && (nmLower.includes('cocktail') || nmLower.includes('shooter') || nmLower.includes('mixes') || nmLower.includes('mocktail')))
    ) {
      identify = 'mobile_bar_option';
      cat = 'drink';
    }

    const isDrink = cat === 'drink';
    const isDecorOrAddon = ['decoration', 'entertainment'].includes(cat);
    const storedPricingType = (row.ingredients || '').trim();

    let allocationType = 'per_pax';
    if (isDecorOrAddon) allocationType = storedPricingType || 'fixed';
    else if (isDrink) allocationType = (identify === 'drinks_package' || identify === 'mobile_bar') ? 'per_5_pax' : 'per_10_pax';
    else if (identify === 'ice_cream') allocationType = 'per_5_pax';

    const rawIng = row.ingredients || '';
    const isMasterSpecial =
      row.is_special === true ||
      row.identify === 'special' ||
      row.identify === 'ice_cream' ||
      row.identify === 'mobile_bar' ||
      row.identify === 'drinks_package' ||
      (typeof rawIng === 'string' && (rawIng.includes('sub_items:') || rawIng.startsWith('per_'))) ||
      (nmLower.includes('mobile bar') && !identify.includes('option')) ||
      (nmLower.includes('unlimited drinks') && !identify.includes('option')) ||
      (nmLower.includes('ice cream') && !identify.includes('option'));

    return {
      id: `sb-${row.id}`,
      supabaseId: row.id,
      name: row.name,
      cat: cat,
      category: row.category || cat,
      identify: identify,
      image: typeof getFoodImage === 'function' ? getFoodImage(row.category, row.name) : '',
      price: parseFloat(row.price_per_pax) || 0,
      desc: row.description || '',
      rating: 4.8, reviews: 0,
      pricingType: isDecorOrAddon ? (storedPricingType || 'fixed') : allocationType,
      allocationType: allocationType,
      ingredients: row.ingredients ? (typeof row.ingredients === 'string' ? row.ingredients.split(',').map(s => s.trim()) : row.ingredients) : [],
      rawIngredients: row.ingredients || '',
      is_special: isMasterSpecial,
      isSpecialMaster: isMasterSpecial,
      isMasterSpecial: isMasterSpecial,
      is_available: row.is_available,
      best_seller: row.best_seller === true || row.best_seller === 'true',
      hidden: row.is_available === false
    };
  });

  CAT = CAT.filter(item => !['food', 'dessert', 'drink', 'decoration', 'entertainment'].includes(item.cat));
  CAT.push(...newCatItems);
}
window.syncSbMenuItemsToCAT = syncSbMenuItemsToCAT;

// ===== SUPABASE CATALOG LOADER (Admin) =====
// Replaces hardcoded CAT array with live data from Supabase
window.ADMIN_THEMES = ['Classic', 'Modern', 'Rustic', 'Vintage', 'Bohemian', 'Others'];

async function loadCatalogFromSupabase() {
  const sb = window.supabaseClient || window.supabase;
  if (!sb) return;

  try {
    const { data: menuRows } = await sb.from('menu_items')
      .select('*')
      .eq('is_available', true);

    const { data: equipRows } = await sb.from('equipment_inventory')
      .select('id, asset_id, name, category, type, total_qty, available_qty, status, condition, value, notes, price, pricing_type, allocation_type, description, parent_asset_id, is_disabled, extra_buffer, image_url')
      .neq('status', 'disposed');

    const { data: themeRows } = await sb.from('event_themes')
      .select('*')
      .order('sort_order', { ascending: true });

    if (themeRows) {
      adminThemesData = themeRows;
      const activeThemes = themeRows.filter(t => t.is_active);
      window.ADMIN_THEMES = [...activeThemes.map(t => t.name), 'Others'];
      if(document.getElementById('pkg-pane-themes') && document.getElementById('pkg-pane-themes').style.display !== 'none') {
        renderAdminThemesTab();
      }
    }

    if (menuRows && menuRows.length > 0) {
      syncSbMenuItemsToCAT(menuRows);
    }

    if (equipRows && equipRows.length > 0) {
      CAT = CAT.filter(item => item.cat !== 'equipment');
      
      const parents = equipRows.filter(r => !r.parent_asset_id);
      
      const equipItems = parents.map(row => {
        let avail = row.available_qty ?? row.total_qty ?? 0;
        let total = row.total_qty ?? 0;
        
        // Fold batch children totals
        const children = equipRows.filter(r => r.parent_asset_id === (row.asset_id || row.id) && !r.is_disabled);
        children.forEach(child => {
            avail += (child.available_qty ?? child.total_qty ?? 0);
            total += (child.total_qty ?? 0);
        });

        return {
          id: `eq-sb-${row.id}`,
          supabaseId: row.id,
          name: row.name,
          cat: 'equipment',
          category: row.category,
          type: row.type,
          image: row.image_url || getEquipmentImage(row.category, row.type, row.name),
          image_url: row.image_url || null,
          price: parseFloat(row.price) || 0,
          desc: row.description || `${row.type ? row.type + ' ' : ''}(${avail} units available)`,
          rating: 4.5, reviews: 0,
          pricingType: row.pricing_type || 'fixed',
          allocationType: row.allocation_type || 'fixed'
        };
      });
      CAT.push(...equipItems);
    }

    // After loading, if modify mode is open, re-render catalog
    if (typeof renderMtModeCatalog === 'function') renderMtModeCatalog();
    if (typeof renderMtModeCats === 'function') renderMtModeCats();

    console.log('[Admin Loader] ✅ Loaded catalog from Supabase.');
  } catch (e) {
    console.error('Failed to load catalog from Supabase:', e);
  }
}

function getFoodImage(paramA, paramB) {
  let c = (paramA || '').toLowerCase();
  let n = (paramB || '').toLowerCase();
  const knownCats = ['beef', 'pork', 'chicken', 'dessert', 'desserts', 'drinks', 'drink', 'decoration', 'decorations', 'entertainment', 'fish', 'shrimp', 'seafood', 'pasta', 'pancit', 'noodles', 'vegetables', 'soup', 'meals', 'food', 'serving', 'furniture', 'tableware'];
  if (!knownCats.some(k => c.includes(k)) && knownCats.some(k => n.includes(k))) {
    const tmp = c; c = n; n = tmp;
  }

  // Beef
  if (c.includes('beef') || n.includes('beef')) {
    if (n.includes('kare')) return 'https://images.unsplash.com/photo-1626509135521-e0066d40096d?auto=format&fit=crop&q=80&w=800';
    if (n.includes('roast') || n.includes('lengua') || n.includes('caldereta') || n.includes('mushroom') || n.includes('broccoli') || n.includes('pares')) return 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&q=80&w=800';
    return 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&q=80&w=800';
  }
  // Pork
  if (c.includes('pork') || n.includes('pork') || n.includes('lechon') || n.includes('liempo')) {
    if (n.includes('barbecue') || n.includes('bbq') || n.includes('liempo')) return 'https://images.unsplash.com/photo-1544333346-64e4fe1820af?auto=format&fit=crop&q=80&w=800';
    if (n.includes('kare')) return 'https://images.unsplash.com/photo-1626509135521-e0066d40096d?auto=format&fit=crop&q=80&w=800';
    if (n.includes('bicol')) return 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&q=80&w=800';
    return 'https://images.unsplash.com/photo-1606787366850-de6330128bfc?auto=format&fit=crop&q=80&w=800';
  }
  // Chicken
  if (c.includes('chicken') || n.includes('chicken')) {
    if (n.includes('teriyaki') || n.includes('galbi') || n.includes('bbq') || n.includes('glazed') || n.includes('creamy') || n.includes('baked') || n.includes('garlic butter')) return 'https://images.unsplash.com/photo-1598515214211-89d3c73ae83b?auto=format&fit=crop&q=80&w=800';
    if (n.includes('fried') || n.includes('crispy') || n.includes('oriental') || n.includes('strip')) return 'https://images.unsplash.com/photo-1562967914-608f82629710?auto=format&fit=crop&q=80&w=800';
    return 'https://images.unsplash.com/photo-1541696490-8744a5db0223?auto=format&fit=crop&q=80&w=800';
  }
  // Vegetables
  if (c.includes('vegetable') || c.includes('veggie') || n.includes('vegetable') || n.includes('corn') || n.includes('carrot') || n.includes('chopsuey')) {
    return 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&q=80&w=800';
  }
  // Soup
  if (c.includes('soup') || n.includes('soup') || n.includes('bulalo') || n.includes('sinigang') || n.includes('tinola')) {
    if (n.includes('bulalo') || n.includes('beef')) return 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&q=80&w=800';
    return 'https://images.unsplash.com/photo-1546548970-71785318a17b?auto=format&fit=crop&q=80&w=800';
  }
  // Shrimp / Seafood
  if (c.includes('shrimp') || c.includes('seafood') || n.includes('shrimp') || n.includes('rebosado') || n.includes('camaron') || n.includes('tempura')) {
    return 'https://images.unsplash.com/photo-1565680018434-b72f4e804e01?auto=format&fit=crop&q=80&w=800';
  }
  // Fish
  if (c.includes('fish') || n.includes('fish')) {
    return 'https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?auto=format&fit=crop&q=80&w=800';
  }
  // Pasta / Noodles
  if (c.includes('pasta') || c.includes('noodle') || c.includes('pancit') || n.includes('spaghetti') || n.includes('lasagna') || n.includes('bihon') || n.includes('canton')) {
    if (n.includes('bihon') || n.includes('canton') || n.includes('pancit') || n.includes('noodle')) return 'https://images.unsplash.com/photo-1585032226651-759b368d7246?auto=format&fit=crop&q=80&w=800';
    return 'https://images.unsplash.com/photo-1551183053-bf91a1d81141?auto=format&fit=crop&q=80&w=800';
  }
  // Dessert
  if (c.includes('dessert') || n.includes('dessert') || n.includes('ice cream') || n.includes('cake') || n.includes('flan') || n.includes('halo') || n.includes('buko') || n.includes('pandan')) {
    if (n.includes('cake') || n.includes('slice') || n.includes('bravo')) return 'https://images.unsplash.com/photo-1535141123063-3bb4cada2f59?auto=format&fit=crop&q=80&w=800';
    if (n.includes('ice cream') || n.includes('halo')) return 'https://images.unsplash.com/photo-1563729784474-d77dbb933a9e?auto=format&fit=crop&q=80&w=800';
    if (n.includes('buko') || n.includes('pandan')) return 'https://images.unsplash.com/photo-1517427294546-5aa121f68e8a?auto=format&fit=crop&q=80&w=800';
    if (n.includes('flan')) return 'https://images.unsplash.com/photo-1488477181946-6428a0291777?auto=format&fit=crop&q=80&w=800';
    if (n.includes('fruit')) return 'https://images.unsplash.com/photo-1490474418585-ba9bad8fd0ea?auto=format&fit=crop&q=80&w=800';
    return 'https://images.unsplash.com/photo-1551024709-8f23befc6f87?auto=format&fit=crop&q=80&w=800';
  }
  // Drinks
  if (c.includes('drink') || n.includes('drink') || n.includes('coffee') || n.includes('tea') || n.includes('juice') || n.includes('lemon') || n.includes('bar')) {
    if (n.includes('coffee') || n.includes('brew')) return 'https://images.unsplash.com/photo-1509042239860-f550ce710b93?auto=format&fit=crop&q=80&w=800';
    if (n.includes('tea') || n.includes('lemon')) return 'https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?auto=format&fit=crop&q=80&w=800';
    if (n.includes('juice') || n.includes('shake') || n.includes('mango')) return 'https://images.unsplash.com/photo-1546173159-315724a31696?auto=format&fit=crop&q=80&w=800';
    if (n.includes('bar') || n.includes('cocktail') || n.includes('shooter')) return 'https://images.unsplash.com/photo-1514362545857-3bc16c4c7d1b?auto=format&fit=crop&q=80&w=800';
    return 'https://images.unsplash.com/photo-1527960471264-932f39eb5846?auto=format&fit=crop&q=80&w=800';
  }
  // Decoration
  if (c.includes('decor') || n.includes('decor') || n.includes('balloon') || n.includes('centerpiece') || n.includes('standee') || n.includes('entrance')) {
    if (n.includes('balloon')) return 'https://images.unsplash.com/photo-1530103043477-c7f44b4131de?auto=format&fit=crop&q=80&w=800';
    if (n.includes('letter') || n.includes('standee')) return 'https://images.unsplash.com/photo-1513151233558-d860c5398176?auto=format&fit=crop&q=80&w=800';
    if (n.includes('centerpiece')) return 'https://images.unsplash.com/photo-1490750967868-88df5691cc1b?auto=format&fit=crop&q=80&w=800';
    return 'https://images.unsplash.com/photo-1519225421980-715cb0215aed?auto=format&fit=crop&q=80&w=800';
  }
  // Entertainment / Addon
  if (c.includes('entertainment') || c.includes('addon') || n.includes('photo booth') || n.includes('coordinator') || n.includes('host') || n.includes('emcee') || n.includes('magician')) {
    if (n.includes('photo booth')) return 'https://images.unsplash.com/photo-1540575467063-178a50c2df87?auto=format&fit=crop&q=80&w=800';
    if (n.includes('coordinator') || n.includes('emcee') || n.includes('host')) return 'https://images.unsplash.com/photo-1511795409834-ef04bbd61622?auto=format&fit=crop&q=80&w=800';
    if (n.includes('magician')) return 'https://images.unsplash.com/photo-1552196563-55cd4e45efb3?auto=format&fit=crop&q=80&w=800';
    return 'https://images.unsplash.com/photo-1511795409834-ef04bbd61622?auto=format&fit=crop&q=80&w=800';
  }
  return 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&q=80&w=800';
}

function getEquipmentImage(category, type, name) {
  const t = (type || '').toLowerCase();
  const c = (category || '').toLowerCase();
  const n = (name || '').toLowerCase();
  const combined = `${c} ${t} ${n}`;

  if (combined.includes('chair')) return 'https://images.unsplash.com/photo-1517705008128-361805f42e86?auto=format&fit=crop&q=80&w=800';
  if (combined.includes('table')) return 'https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&q=80&w=800';
  if (combined.includes('linen') || combined.includes('cloth') || combined.includes('napkin') || combined.includes('skirt') || combined.includes('runner') || combined.includes('cover')) return 'https://images.unsplash.com/photo-1530103043477-c7f44b4131de?auto=format&fit=crop&q=80&w=800';
  if (combined.includes('plate') || combined.includes('bowl') || combined.includes('saucer')) return 'https://images.unsplash.com/photo-1589923188900-85dae523342b?auto=format&fit=crop&q=80&w=800';
  if (combined.includes('glass') || combined.includes('cup') || combined.includes('pitcher') || combined.includes('dispenser') || combined.includes('goblet') || combined.includes('flute')) return 'https://images.unsplash.com/photo-1571506165871-ee72a35bc9d4?auto=format&fit=crop&q=80&w=800';
  if (combined.includes('spoon') || combined.includes('fork') || combined.includes('knife') || combined.includes('tong') || combined.includes('utensil') || combined.includes('cutlery') || combined.includes('silverware') || combined.includes('flatware')) return 'https://images.unsplash.com/photo-1578916171728-46686eac8d58?auto=format&fit=crop&q=80&w=800';
  if (combined.includes('chafing') || combined.includes('dish') || combined.includes('warmer') || combined.includes('roll top') || combined.includes('buffet') || combined.includes('pan')) return 'https://images.unsplash.com/photo-1555244162-803834f70033?auto=format&fit=crop&q=80&w=800';
  if (combined.includes('tray')) return 'https://images.unsplash.com/photo-1576402187878-974f70c890a5?auto=format&fit=crop&q=80&w=800';
  if (combined.includes('light') || combined.includes('sound') || combined.includes('speaker') || combined.includes('av') || combined.includes('microphone')) return 'https://images.unsplash.com/photo-1492691527719-9d1e07e534b4?auto=format&fit=crop&q=80&w=800';
  return 'https://images.unsplash.com/photo-1556910103-1c02745aae4d?auto=format&fit=crop&q=80&w=800';
}

