window.openMeetingPaymentTrigger = function() {
  const panel = document.getElementById('mt-payment-trigger-panel');
  const posPanel = document.getElementById('mt-pos-manual-panel');
  if (posPanel) posPanel.style.display = 'none';
  if (panel) panel.style.display = 'block';
};

window.closeMeetingPaymentTrigger = function() {
  const panel = document.getElementById('mt-payment-trigger-panel');
  if (panel) panel.style.display = 'none';
};

window.proceedMeetingOnlinePayment = function() {
  closeMeetingPaymentTrigger();
  if (typeof requestPaymongoPayment === 'function') {
    requestPaymongoPayment();
  }
};

window.proceedMeetingManualPos = function() {
  closeMeetingPaymentTrigger();
  const posPanel = document.getElementById('mt-pos-manual-panel');
  const btnPay = document.getElementById('btn-pay-initial');
  if (btnPay) btnPay.style.display = 'none';
  if (posPanel) {
    posPanel.style.display = 'block';
    const inp = document.getElementById('mt-pos-cash-input');
    if (inp) {
      inp.value = '';
      inp.focus();
    }
    updateMeetingPosChange();
  }
};

window.cancelMeetingManualPos = function() {
  const posPanel = document.getElementById('mt-pos-manual-panel');
  const btnPay = document.getElementById('btn-pay-initial');
  if (posPanel) posPanel.style.display = 'none';
  if (btnPay) btnPay.style.display = 'flex';
};

window.updateMeetingPosChange = function() {
  const inp = document.getElementById('mt-pos-cash-input');
  const changeEl = document.getElementById('mt-pos-change-val');
  const msgEl = document.getElementById('mt-pos-insufficient-msg');
  const confirmBtn = document.getElementById('mt-btn-pos-confirm');
  if (!inp) return;
  const val = parseFloat(inp.value) || 0;
  const due = 5000;
  if (val >= due) {
    const chg = val - due;
    if (changeEl) changeEl.textContent = '₱' + chg.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    if (msgEl) msgEl.style.display = 'none';
    if (confirmBtn) {
      confirmBtn.disabled = false;
      confirmBtn.style.opacity = '1';
      confirmBtn.style.cursor = 'pointer';
    }
  } else {
    if (changeEl) changeEl.textContent = '₱0.00';
    if (msgEl) {
      msgEl.textContent = 'Meeting Room policy requires full payment. Please enter at least ₱5,000.00.';
      msgEl.style.display = val > 0 ? 'block' : 'none';
    }
    if (confirmBtn) {
      confirmBtn.disabled = true;
      confirmBtn.style.opacity = '0.5';
      confirmBtn.style.cursor = 'not-allowed';
    }
  }
};

window.confirmMeetingManualPos = async function() {
  if (!activeMeeting) return;
  const inp = document.getElementById('mt-pos-cash-input');
  const amtPaid = parseFloat(inp?.value) || 0;
  if (amtPaid < 5000) return;
  const change = amtPaid - 5000;
  const confirmBtn = document.getElementById('mt-btn-pos-confirm');
  if (confirmBtn) { confirmBtn.disabled = true; confirmBtn.textContent = 'Processing...'; }

  const resId = activeMeeting.reservation_id || activeMeeting.reservationId || currentMeetingResId;
  const refId = activeMeeting.initial_fee_ref_id || activeMeeting.initialFeeRefId || ('PAY-INIT-' + String(resId || '000000').slice(-6).toUpperCase());
  const nowIso = new Date().toISOString();
  const adminName = (typeof currentAdminUser !== 'undefined' && currentAdminUser && (currentAdminUser.name || currentAdminUser.email)) ? (currentAdminUser.name || currentAdminUser.email) : 'Admin';

  try {
    const payload = {
      initial_fee_status: 'paid',
      initial_fee_method: 'cash',
      initial_fee_amount: 5000,
      initial_fee_received: amtPaid,
      initial_fee_change: change,
      initial_fee_paid_at: nowIso,
      initial_fee_received_by: adminName,
      initial_fee_ref_id: refId,
      initialFeeRefId: refId,
      status: 'paid'
    };

    // 1. Update active meeting doc in Firebase
    if (window.firebaseDB && window.firebaseFns && activeMeeting.id) {
      const { doc, updateDoc } = window.firebaseFns;
      await updateDoc(doc(window.firebaseDB, 'meetings', activeMeeting.id), payload);
    }

    // 2. Update reservation in Firebase
    if (window.firebaseDB && window.firebaseFns && resId) {
      const { doc, updateDoc } = window.firebaseFns;
      try {
        await updateDoc(doc(window.firebaseDB, 'reservations', resId), {
          initial_fee_status: 'paid',
          initial_fee_method: 'cash',
          initial_fee_received: amtPaid,
          initial_fee_change: change,
          initial_fee_paid_at: nowIso,
          initial_fee_received_by: adminName,
          initial_fee_ref_id: refId,
          initialFeeRefId: refId
        });
      } catch (fe) {}
    }

    // 3. Update Supabase
    if (window.supabaseClient && resId) {
      try {
        await window.supabaseClient.from('reservations').update({
          initial_fee_status: 'paid',
          initial_fee_paid: true,
          initial_fee_received: amtPaid
        }).eq('id', resId);
      } catch (se) {}

      try {
        await window.supabaseClient.from('reservation_payments').upsert({
          reservation_id: resId,
          initial_fee_amount: 5000,
          initial_fee_status: 'paid',
          initial_fee_method: 'cash',
          initial_fee_received: amtPaid,
          initial_fee_change: change,
          initial_fee_paid_at: nowIso,
          initial_fee_received_by: adminName,
          updated_at: nowIso
        }, { onConflict: 'reservation_id' });
      } catch (pe) {
        console.warn('reservation_payments upsert error in manual POS:', pe);
      }
    }

    // Update activeMeeting local state
    Object.assign(activeMeeting, payload);

    if (activeMeetingResCache) {
      activeMeetingResCache.paymentStatus = 'paid';
      activeMeetingResCache.paymentAmount = '5000';
      activeMeetingResCache.initialFeeStatus = 'paid';
      activeMeetingResCache.initial_fee_status = 'paid';
      activeMeetingResCache.initialFeeMethod = 'cash';
      activeMeetingResCache.initial_fee_method = 'cash';
      activeMeetingResCache.initial_fee_received = amtPaid;
      activeMeetingResCache.initial_fee_change = change;
      activeMeetingResCache.initial_fee_paid_at = nowIso;
      activeMeetingResCache.initial_fee_received_by = adminName;
      activeMeetingResCache.initial_fee_ref_id = refId;
      activeMeetingResCache.initialFeeRefId = refId;
    }

    // Hide POS manual panel
    const posPanel = document.getElementById('mt-pos-manual-panel');
    if (posPanel) posPanel.style.display = 'none';

    // Show receipt and paid badge
    const paidBadge = document.getElementById('mt-billing-paid-badge');
    const paidMethod = document.getElementById('mt-billing-paid-method');
    const posSummary = document.getElementById('mt-billing-pos-summary');
    const btnPay = document.getElementById('btn-pay-initial');
    const cantPayBtn = document.getElementById('btn-customer-cant-pay');

    if (btnPay) btnPay.style.display = 'none';
    if (cantPayBtn) cantPayBtn.style.display = 'none';
    if (paidBadge) paidBadge.style.display = 'flex';
    if (paidMethod) paidMethod.textContent = '(Cash)';

    if (posSummary) {
      posSummary.style.display = 'block';
      posSummary.innerHTML = `
        <div style="background:rgba(255,255,255,0.03); border:1px dashed var(--border); border-radius:8px; padding:12px; font-size:12px;">
          <div style="font-weight:700; color:var(--gold); margin-bottom:8px; text-transform:uppercase; letter-spacing:1px; font-size:10px;">POS Transaction Receipt</div>
          <div style="display:flex; justify-content:space-between; margin-bottom:4px;"><span style="color:var(--text-dim);">Reference ID</span><span style="font-family:monospace; font-weight:700; color:var(--gold);">${refId}</span></div>
          <div style="display:flex; justify-content:space-between; margin-bottom:4px;"><span style="color:var(--text-dim);">Amount Due</span><span>&#8369;5,000.00</span></div>
          <div style="display:flex; justify-content:space-between; margin-bottom:4px;"><span style="color:var(--text-dim);">Cash Received</span><span>&#8369;${amtPaid.toLocaleString('en-US', { minimumFractionDigits: 2 })}</span></div>
          <div style="display:flex; justify-content:space-between; margin-bottom:4px;"><span style="color:var(--text-dim);">Change Given</span><span>&#8369;${change.toLocaleString('en-US', { minimumFractionDigits: 2 })}</span></div>
          <div style="display:flex; justify-content:space-between; margin-bottom:4px;"><span style="color:var(--text-dim);">Payment Method</span><span>Cash</span></div>
          <div style="display:flex; justify-content:space-between; margin-bottom:4px;"><span style="color:var(--text-dim);">Received By</span><span>${adminName}</span></div>
        </div>`;
    }

    // Trigger Automated Email Receipt for POS Initial Fee
    try {
      if (window.SmartServeNotifications && resId) {
        const targetRes = activeMeetingResCache || (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS.find(r => String(r.id) === String(resId)) : null) || {};
        const custName = targetRes.customerName || targetRes.name || targetRes.client_name || activeMeeting.customerName || activeMeeting.customer_name || 'Valued Customer';
        const custEmail = targetRes.customerEmail || targetRes.email || targetRes.client_email || activeMeeting.customerEmail || activeMeeting.customer_email || '';
        window.SmartServeNotifications.notifyPaymentMade({
          customerEmail: custEmail,
          customerName: custName,
          reservationId: resId,
          amount: 5000,
          paymentMethod: 'Cash',
          feeType: 'Initial Fee',
          referenceNumber: refId,
          referenceId: refId,
          refId: refId,
          cashReceived: amtPaid,
          changeGiven: change,
          transactionDate: nowIso,
          notes: `Amount Due: ₱5,000.00, Cash Received: ₱${Number(amtPaid).toLocaleString()}, Change: ₱${Number(change).toLocaleString()}, Verified By: ${adminName}`
        });
      }
    } catch (notifErr) {
      console.warn('[confirmMeetingManualPos] Notification error:', notifErr);
    }

    showToast('Initial Fee payment recorded successfully! Ref: ' + refId, 'success');
  } catch (err) {
    console.error('Manual POS failed:', err);
    showToast('Failed to record payment: ' + (err.message || err), 'error');
    if (confirmBtn) { confirmBtn.disabled = false; confirmBtn.textContent = 'Confirm Payment'; }
  }
};

