// ====================================================================
// MANUAL GCASH PAYMENT MODAL FUNCTIONS
// ====================================================================
let _manualGcashResId = null;
let _manualGcashFeeType = null;
let _manualGcashDueAmt = 0;
let _manualGcashProofFile = null;
let _manualGcashProofUrl = null;
let _manualGcashSubChoice = null;

window.openManualGcashModal = function(resId, feeType, amount, preloadedProofUrl, subChoice) {
  _manualGcashResId = resId;
  _manualGcashFeeType = feeType;
  _manualGcashDueAmt = parseFloat(amount) || 0;
  _manualGcashProofFile = null;
  _manualGcashProofUrl = preloadedProofUrl || null;
  _manualGcashSubChoice = subChoice || (typeof activeMeeting !== 'undefined' ? (activeMeeting?.cancellation_fee_choice || activeMeeting?.cancellation_pay_choice) : null) || null;

  const modal = document.getElementById('admin-manual-gcash-modal');
  const subTitle = document.getElementById('manual-gcash-fee-subtitle');
  const dueEl = document.getElementById('manual-gcash-amount-due');
  const amtInp = document.getElementById('manual-gcash-amt-paid');
  const chgEl = document.getElementById('manual-gcash-change-display');
  const previewWrap = document.getElementById('manual-gcash-img-preview-wrap');
  const previewImg = document.getElementById('manual-gcash-img-preview');
  const fileInp = document.getElementById('manual-gcash-file-input');
  const confirmBtn = document.getElementById('btn-manual-gcash-confirm');

  if (fileInp) fileInp.value = '';
  if (_manualGcashProofUrl && previewImg && previewWrap) {
    previewImg.src = _manualGcashProofUrl;
    previewWrap.style.display = 'block';
  } else {
    if (previewImg) previewImg.src = '';
    if (previewWrap) previewWrap.style.display = 'none';
  }

  let typeLabel = 'Payment';
  if (feeType === 'downpayment') typeLabel = 'Downpayment Payment';
  else if (feeType === 'final') typeLabel = 'Final Payment';
  else if (feeType === 'initial_fee') typeLabel = 'Initial Reservation Fee';
  else if (feeType === 'additional_charges') typeLabel = 'Additional Execution Charges';
  else if (feeType === 'cancellation') {
    if (_manualGcashSubChoice === 'downpayment') typeLabel = 'Cancellation Settlement (Downpayment Only)';
    else if (_manualGcashSubChoice === 'final') typeLabel = 'Cancellation Settlement (Final Payment Only)';
    else typeLabel = 'Cancellation Settlement (Both Payments)';
  } else if (feeType === 'business_liability') {
    typeLabel = 'Business Compensation Payout (200%)';
  }

  if (subTitle) subTitle.textContent = typeLabel;
  if (dueEl) dueEl.textContent = '₱' + _manualGcashDueAmt.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  if (amtInp) amtInp.value = _manualGcashDueAmt;
  if (chgEl) chgEl.textContent = '₱0.00';

  if (confirmBtn) {
    confirmBtn.disabled = false;
    confirmBtn.textContent = 'Confirm Payment';
    confirmBtn.style.opacity = '1';
    confirmBtn.style.cursor = 'pointer';
  }

  const dismissBtn = document.getElementById('btn-manual-gcash-dismiss');
  if (dismissBtn) {
    dismissBtn.style.display = (feeType === 'cancellation' && preloadedProofUrl) ? 'block' : 'none';
  }

  if (modal) modal.style.display = 'flex';
  updateManualGcashChange();
};

window.closeManualGcashModal = function() {
  const modal = document.getElementById('admin-manual-gcash-modal');
  if (modal) modal.style.display = 'none';
  // Clear all state — uploaded screenshot NOT saved if modal is cancelled
  _manualGcashResId = null;
  _manualGcashFeeType = null;
  _manualGcashSubChoice = null;
  _manualGcashProofFile = null;
  _manualGcashProofUrl = null;
  // Reset file input and image preview
  const fileInp = document.getElementById('manual-gcash-file-input');
  const previewImg = document.getElementById('manual-gcash-img-preview');
  const previewWrap = document.getElementById('manual-gcash-img-preview-wrap');
  if (fileInp) fileInp.value = '';
  if (previewImg) previewImg.src = '';
  if (previewWrap) previewWrap.style.display = 'none';
  // Reset amount input and change display
  const amtInp = document.getElementById('manual-gcash-amt-paid');
  const chgEl = document.getElementById('manual-gcash-change-display');
  const errMsg = document.getElementById('manual-gcash-error-msg');
  const confirmBtn = document.getElementById('btn-manual-gcash-confirm');
  const dismissBtn = document.getElementById('btn-manual-gcash-dismiss');
  if (dismissBtn) dismissBtn.style.display = 'none';
  if (amtInp) amtInp.value = '';
  if (chgEl) chgEl.textContent = '₱0.00';
  if (errMsg) errMsg.style.display = 'none';
  if (confirmBtn) { confirmBtn.disabled = true; confirmBtn.style.opacity = '0.5'; }
};

window.dismissCancellationGcashProof = async function () {
  if (!activeMeeting || !window.supabaseClient) return;
  if (!confirm('Are you sure you want to dismiss this proof? The customer will be asked to re-upload.')) return;

  const btn = document.getElementById('btn-manual-gcash-dismiss');
  if (btn) { btn.disabled = true; btn.textContent = 'Dismissing...'; }

  const dismissPayload = {
    cancellation_fee_status: 'cancellation_gcash_dismissed',
    cancellation_fee_choice: activeMeeting.cancellation_fee_choice || activeMeeting.cancellation_pay_choice || 'both',
    cancellation_fee_amount: activeMeeting.cancellation_fee_amount || activeMeeting.cancellation_pay_amount || 0,
    cancellation_dp_amount: activeMeeting.cancellation_dp_amount || 0,
    cancellation_final_amount: activeMeeting.cancellation_final_amount || 0,
    cancellation_pay_triggered: true,
    cancellation_pay_choice: activeMeeting.cancellation_fee_choice || activeMeeting.cancellation_pay_choice || 'both',
    cancellation_pay_amount: activeMeeting.cancellation_fee_amount || activeMeeting.cancellation_pay_amount || 0,
    cancellation_fee_proof: null
  };

  try {
    const rawJson = JSON.stringify(dismissPayload);
    await window.supabaseClient.from('meetings').update({
      cancellationNote: rawJson,
      live_draft: { cancellation_pay: dismissPayload }
    }).eq('id', activeMeeting.id);

    Object.assign(activeMeeting, dismissPayload);
    activeMeeting.cancellationNote = rawJson;

    if (window.firebaseDB && window.firebaseFns && activeMeeting.id) {
      try {
        const { doc, updateDoc } = window.firebaseFns;
        await updateDoc(doc(window.firebaseDB, 'meetings', activeMeeting.id), {
          cancellationNote: rawJson,
          ...dismissPayload
        });
      } catch (e) {}
    }

    if (typeof closeManualGcashModal === 'function') closeManualGcashModal();
    if (typeof updateCancellationBillingUI === 'function') updateCancellationBillingUI(activeMeetingResCache);
    alert('GCash proof dismissed. The customer has been prompted to re-upload.');
  } catch (e) {
    console.error('Error dismissing cancellation GCash proof:', e);
    alert('Failed to dismiss proof: ' + e.message);
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = 'Dismiss Proof'; }
  }
};

window.updateManualGcashChange = function() {
  const amtInp = document.getElementById('manual-gcash-amt-paid');
  const chgEl = document.getElementById('manual-gcash-change-display');
  const errMsg = document.getElementById('manual-gcash-error-msg');
  const confirmBtn = document.getElementById('btn-manual-gcash-confirm');

  if (!amtInp) return;
  if (amtInp.value && amtInp.value.length > 6) {
    amtInp.value = amtInp.value.slice(0, 6);
  }
  const paid = parseFloat(amtInp.value) || 0;
  if (paid >= _manualGcashDueAmt) {
    const change = paid - _manualGcashDueAmt;
    if (chgEl) chgEl.textContent = '\u20B1' + change.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    if (errMsg) errMsg.style.display = 'none';
    if (confirmBtn) {
      confirmBtn.disabled = false;
      confirmBtn.style.opacity = '1';
      confirmBtn.style.cursor = 'pointer';
    }
  } else {
    if (chgEl) chgEl.textContent = '\u20B10.00';
    if (errMsg) errMsg.style.display = 'block';
    if (confirmBtn) {
      confirmBtn.disabled = true;
      confirmBtn.style.opacity = '0.5';
      confirmBtn.style.cursor = 'not-allowed';
    }
  }
};

window.handleManualGcashFileUpload = function(input) {
  if (input.files && input.files[0]) {
    _manualGcashProofFile = input.files[0];
    const reader = new FileReader();
    reader.onload = function(e) {
      const previewImg = document.getElementById('manual-gcash-img-preview');
      const previewWrap = document.getElementById('manual-gcash-img-preview-wrap');
      if (previewImg) previewImg.src = e.target.result;
      if (previewWrap) previewWrap.style.display = 'block';
    };
    reader.readAsDataURL(input.files[0]);
  }
};

window.removeManualGcashProofImage = function() {
  _manualGcashProofFile = null;
  _manualGcashProofUrl = null;
  const fileInp = document.getElementById('manual-gcash-file-input');
  const previewWrap = document.getElementById('manual-gcash-img-preview-wrap');
  const previewImg = document.getElementById('manual-gcash-img-preview');
  if (fileInp) fileInp.value = '';
  if (previewImg) previewImg.src = '';
  if (previewWrap) previewWrap.style.display = 'none';
};

window.confirmManualGcashPayment = async function() {
  if (!_manualGcashResId || !_manualGcashFeeType) return;
  const amtInp = document.getElementById('manual-gcash-amt-paid');
  const amtPaid = parseFloat(amtInp?.value) || 0;
  if (amtPaid < _manualGcashDueAmt) {
    showToast('Payment amount is less than required.', 'error');
    return;
  }
  const change = amtPaid - _manualGcashDueAmt;
  const confirmBtn = document.getElementById('btn-manual-gcash-confirm');
  if (confirmBtn) { confirmBtn.disabled = true; confirmBtn.textContent = 'Saving Payment...'; }

  try {
    let uploadedUrl = '';
    if (_manualGcashProofFile) {
      if (typeof uploadImageToCloudinary === 'function') {
        try {
          const upRes = await uploadImageToCloudinary(_manualGcashProofFile);
          uploadedUrl = typeof upRes === 'string' ? upRes : (upRes && (upRes.secure_url || upRes.url)) || '';
        } catch (uploadErr) {
          console.warn('Cloudinary upload fallback:', uploadErr);
        }
      }
      if (!uploadedUrl) {
        try {
          uploadedUrl = await new Promise((res, rej) => {
            const rd = new FileReader();
            rd.onload = e => res(e.target.result);
            rd.onerror = err => rej(err);
            rd.readAsDataURL(_manualGcashProofFile);
          });
        } catch(e) {}
      }
    }
    if (!uploadedUrl && _manualGcashProofUrl) {
      uploadedUrl = _manualGcashProofUrl;
    }

    const resId = _manualGcashResId;
    const feeType = _manualGcashFeeType;
    let refPrefix = 'PAY-DP-';
    if (feeType === 'final') refPrefix = 'PAY-FINAL-';
    else if (feeType === 'initial_fee') refPrefix = 'PAY-INIT-';
    else if (feeType === 'additional_charges') refPrefix = 'PAY-EXTRA-';
    else if (feeType === 'cancellation') refPrefix = 'PAY-CAN-';
    else if (feeType === 'business_liability') refPrefix = 'POS-BIZ-';
    const refId = refPrefix + String(resId || '000000').slice(-6).toUpperCase();
    const nowIso = new Date().toISOString();
    const adminName = (typeof currentAdminUser !== 'undefined' && currentAdminUser && (currentAdminUser.name || currentAdminUser.email)) ? (currentAdminUser.name || currentAdminUser.email) : 'Admin';

    let fbPayload = {};
    let sbPayload = {};

    if (feeType === 'downpayment') {
      fbPayload = {
        downpayment_status: 'paid',
        downpaymentStatus: 'paid',
        downpayment_paid: true,
        downpaymentPaid: true,
        downpayment_method: 'gcash',
        downpaymentMethod: 'gcash',
        downpayment_received: amtPaid,
        downpaymentReceived: amtPaid,
        downpayment_change: change,
        downpaymentChange: change,
        downpayment_paid_at: nowIso,
        downpaymentPaidAt: nowIso,
        downpayment_received_by: adminName,
        downpayment_ref_id: refId,
        downpaymentRefId: refId
      };
      if (uploadedUrl) {
        fbPayload.downpayment_proof = uploadedUrl;
        fbPayload.downpayment_proof_url = uploadedUrl;
        fbPayload.downpaymentProof = uploadedUrl;
      }
      sbPayload = {
        downpayment_status: 'paid',
        downpayment_method: 'gcash',
        downpayment_received: amtPaid,
        downpayment_change: change,
        downpayment_paid_at: nowIso,
        downpayment_received_by: adminName,
        downpayment_ref_id: refId
      };
      if (uploadedUrl) {
        sbPayload.downpayment_proof = uploadedUrl;
        sbPayload.downpayment_proof_url = uploadedUrl;
      }
      try {
        await window.supabaseClient.from('reservation_payments').upsert({
          reservation_id: resId,
          downpayment_amount: _manualGcashDueAmt,
          downpayment_status: 'paid',
          downpayment_method: 'gcash',
          downpayment_received: amtPaid,
          downpayment_change: change,
          downpayment_paid_at: nowIso,
          downpayment_received_by: adminName,
          downpayment_proof: uploadedUrl
        }, { onConflict: 'reservation_id' });
      } catch (pe) { console.warn('reservation_payments upsert error in manual GCash DP:', pe); }

    } else if (feeType === 'final') {
      fbPayload = {
        final_payment_status: 'paid',
        finalPaymentStatus: 'paid',
        final_paid: true,
        finalPaid: true,
        final_method: 'gcash',
        finalMethod: 'gcash',
        final_received: amtPaid,
        finalReceived: amtPaid,
        final_change: change,
        finalChange: change,
        final_paid_at: nowIso,
        finalPaidAt: nowIso,
        final_received_by: adminName,
        final_ref_id: refId,
        finalRefId: refId
      };
      if (uploadedUrl) {
        fbPayload.final_proof = uploadedUrl;
        fbPayload.final_proof_url = uploadedUrl;
        fbPayload.finalProof = uploadedUrl;
      }
      sbPayload = {
        final_payment_status: 'paid',
        final_method: 'gcash',
        final_received: amtPaid,
        final_change: change,
        final_paid_at: nowIso,
        final_received_by: adminName,
        final_ref_id: refId
      };
      if (uploadedUrl) {
        sbPayload.final_proof = uploadedUrl;
        sbPayload.final_proof_url = uploadedUrl;
      }
      try {
        await window.supabaseClient.from('reservation_payments').upsert({
          reservation_id: resId,
          final_payment_amount: _manualGcashDueAmt,
          final_payment_status: 'paid',
          final_method: 'gcash',
          final_received: amtPaid,
          final_change: change,
          final_paid_at: nowIso,
          final_received_by: adminName,
          final_proof: uploadedUrl
        }, { onConflict: 'reservation_id' });
      } catch (pe) { console.warn('reservation_payments upsert error in manual GCash Final:', pe); }

    } else if (feeType === 'initial_fee') {
      fbPayload = {
        initial_fee_status: 'paid',
        initialFeeStatus: 'paid',
        initial_fee_paid: true,
        initialFeePaid: true,
        initial_fee_method: 'gcash',
        initialFeeMethod: 'gcash',
        initial_fee_received: amtPaid,
        initialFeeReceived: amtPaid,
        initial_fee_change: change,
        initialFeeChange: change,
        initial_fee_paid_at: nowIso,
        initialFeePaidAt: nowIso,
        initial_fee_received_by: adminName,
        initial_fee_ref_id: refId,
        initialFeeRefId: refId
      };
      if (uploadedUrl) {
        fbPayload.initial_fee_proof = uploadedUrl;
        fbPayload.initial_fee_proof_url = uploadedUrl;
        fbPayload.initialFeeProof = uploadedUrl;
      }
      sbPayload = {
        initial_fee_status: 'paid',
        initial_fee_paid: true,
        initial_fee_received: amtPaid
      };
      if (uploadedUrl) {
        sbPayload.initial_fee_proof = uploadedUrl;
        sbPayload.initial_fee_proof_url = uploadedUrl;
      }
      try {
        await window.supabaseClient.from('reservation_payments').upsert({
          reservation_id: resId,
          initial_fee_amount: _manualGcashDueAmt,
          initial_fee_status: 'paid',
          initial_fee_method: 'gcash',
          initial_fee_received: amtPaid,
          initial_fee_change: change,
          initial_fee_paid_at: nowIso,
          initial_fee_received_by: adminName,
          initial_fee_proof: uploadedUrl
        }, { onConflict: 'reservation_id' });
      } catch (pe) { console.warn('reservation_payments upsert error in manual GCash Init:', pe); }

    } else if (feeType === 'additional_charges') {
      fbPayload = {
        exec_charges_payment_status: 'paid',
        exec_charges_amount_paid: amtPaid,
        exec_charges_change: change,
        exec_charges_paid_at: nowIso,
        exec_charges_method: 'gcash',
        exec_charges_received_by: adminName,
        exec_charges_ref_id: refId
      };
      if (uploadedUrl) {
        fbPayload.exec_charges_proof = uploadedUrl;
        fbPayload.exec_charges_proof_url = uploadedUrl;
      }
      sbPayload = {
        exec_charges_payment_status: 'paid',
        exec_charges_amount_paid: amtPaid,
        exec_charges_change: change
      };
      if (uploadedUrl) {
        sbPayload.exec_charges_proof = uploadedUrl;
        sbPayload.exec_charges_proof_url = uploadedUrl;
      }
      try {
        await window.supabaseClient.from('reservation_payments').upsert({
          reservation_id: resId,
          additional_charges_amount: _manualGcashDueAmt,
          additional_charges_status: 'paid',
          additional_charges_received: amtPaid,
          additional_charges_change: change,
          additional_charges_method: 'gcash',
          additional_charges_paid_at: nowIso,
          additional_charges_received_by: adminName,
          additional_charges_ref_id: refId,
          additional_charges_proof: uploadedUrl
        }, { onConflict: 'reservation_id' });
      } catch (pe) { console.warn('reservation_payments upsert error in manual GCash:', pe); }
    } else if (feeType === 'cancellation') {
      const subChoice = _manualGcashSubChoice || (typeof activeMeeting !== 'undefined' ? (activeMeeting?.cancellation_fee_choice || activeMeeting?.cancellation_pay_choice) : null) || 'both';

      const targetRes = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(r => r.id === resId || String(r.id) === String(resId)) || activeMeetingResCache;
      const b = (typeof getReservationCancellationBalances === 'function' && targetRes) ? getReservationCancellationBalances(targetRes) : null;
      const dpAmt = b ? b.dpAmount : 0;
      const finalAmt = b ? b.finalAmount : 0;

      if (subChoice === 'downpayment') {
        fbPayload = {
          downpayment_status: 'paid',
          downpaymentStatus: 'paid',
          downpayment_paid: true,
          downpayment_method: 'gcash',
          downpaymentMethod: 'gcash',
          downpayment_received: amtPaid,
          downpaymentReceived: amtPaid,
          downpayment_change: change,
          downpaymentChange: change,
          downpayment_paid_at: nowIso,
          downpaymentPaidAt: nowIso,
          downpayment_received_by: adminName,
          downpayment_ref_id: refId,
          downpaymentRefId: refId,
          cancellation_status: 'unsettled',
          cancellation_request_status: 'unsettled'
        };
        // Explicitly keep final payment as unpaid if not already paid
        if (!targetRes?.final_payment_status || targetRes.final_payment_status !== 'paid') {
          fbPayload.final_payment_status = 'unpaid';
          fbPayload.finalPaymentStatus = 'unpaid';
          fbPayload.settled = false;
        }
        if (uploadedUrl) {
          fbPayload.downpayment_proof = uploadedUrl;
          fbPayload.downpayment_proof_url = uploadedUrl;
          fbPayload.downpaymentProof = uploadedUrl;
          fbPayload.cancellation_proof = uploadedUrl;
        }

        sbPayload = {
          downpayment_status: 'paid',
          downpayment_method: 'gcash',
          downpayment_received: amtPaid,
          downpayment_change: change,
          downpayment_paid_at: nowIso,
          downpayment_received_by: adminName,
          downpayment_ref_id: refId,
          cancellation_status: 'unsettled',
          cancellation_request_status: 'unsettled'
        };
        if (!targetRes?.final_payment_status || targetRes.final_payment_status !== 'paid') {
          sbPayload.final_payment_status = 'unpaid';
          sbPayload.settled = false;
        }
        if (uploadedUrl) {
          sbPayload.downpayment_proof = uploadedUrl;
          sbPayload.cancellation_proof = uploadedUrl;
        }

        try {
          await window.supabaseClient.from('reservation_payments').upsert({
            reservation_id: resId,
            downpayment_amount: dpAmt,
            downpayment_status: 'paid',
            downpayment_method: 'gcash',
            downpayment_received: amtPaid,
            downpayment_change: change,
            downpayment_paid_at: nowIso,
            downpayment_received_by: adminName,
            downpayment_ref_id: refId,
            downpayment_proof: uploadedUrl,
            final_payment_status: (targetRes?.final_payment_status === 'paid') ? 'paid' : 'unpaid',
            cancellation_payment_status: 'unsettled',
            updated_at: nowIso
          }, { onConflict: 'reservation_id' });
        } catch (pe) { console.warn('reservation_payments upsert error in manual GCash DP:', pe); }

        if (window.supabaseClient) {
          try {
            const paidPayload = {
              cancellation_fee_status: 'downpayment_paid',
              cancellation_fee_choice: null,
              cancellation_pay_choice: null,
              cancellation_pay_triggered: false
            };
            await window.supabaseClient.from('meetings').update({
              cancellationNote: JSON.stringify(paidPayload),
              live_draft: { cancellation_pay: paidPayload }
            }).or(`reservationId.eq.${resId},reservation_id.eq.${resId}`);
          } catch (me) {}
        }
        if (typeof activeMeeting !== 'undefined' && activeMeeting && (activeMeeting.reservationId === resId || activeMeeting.reservation_id === resId)) {
          activeMeeting.cancellation_fee_status = 'downpayment_paid';
          activeMeeting.cancellation_pay_triggered = false;
          activeMeeting.cancellation_fee_choice = null;
          activeMeeting.cancellation_pay_choice = null;
        }
      } else if (subChoice === 'final') {
        const isDpPaid = (targetRes?.downpayment_status === 'paid' || targetRes?.downpaymentStatus === 'paid' || targetRes?.downpayment_paid);
        fbPayload = {
          final_payment_status: 'paid',
          finalPaymentStatus: 'paid',
          final_paid: true,
          settled: true,
          final_method: 'gcash',
          finalMethod: 'gcash',
          final_received: amtPaid,
          finalReceived: amtPaid,
          final_change: change,
          finalChange: change,
          final_paid_at: nowIso,
          finalPaidAt: nowIso,
          final_received_by: adminName,
          final_ref_id: refId,
          finalRefId: refId,
          cancellation_status: isDpPaid ? 'settled' : 'unsettled',
          cancellation_request_status: isDpPaid ? 'settled' : 'unsettled'
        };
        if (uploadedUrl) {
          fbPayload.final_proof = uploadedUrl;
          fbPayload.final_proof_url = uploadedUrl;
          fbPayload.finalProof = uploadedUrl;
          fbPayload.cancellation_proof = uploadedUrl;
        }

        sbPayload = {
          final_payment_status: 'paid',
          settled: true,
          final_method: 'gcash',
          final_received: amtPaid,
          final_change: change,
          final_paid_at: nowIso,
          final_received_by: adminName,
          final_ref_id: refId,
          cancellation_status: isDpPaid ? 'settled' : 'unsettled',
          cancellation_request_status: isDpPaid ? 'settled' : 'unsettled'
        };
        if (uploadedUrl) {
          sbPayload.final_proof = uploadedUrl;
          sbPayload.cancellation_proof = uploadedUrl;
        }

        try {
          await window.supabaseClient.from('reservation_payments').upsert({
            reservation_id: resId,
            final_payment_amount: finalAmt,
            final_payment_status: 'paid',
            final_method: 'gcash',
            final_received: amtPaid,
            final_change: change,
            final_paid_at: nowIso,
            final_received_by: adminName,
            final_ref_id: refId,
            final_proof: uploadedUrl,
            cancellation_payment_status: isDpPaid ? 'paid' : 'unsettled',
            updated_at: nowIso
          }, { onConflict: 'reservation_id' });
        } catch (pe) { console.warn('reservation_payments upsert error in manual GCash Final:', pe); }

        if (window.supabaseClient) {
          try {
            const paidPayload = {
              cancellation_fee_status: isDpPaid ? 'paid' : 'final_paid',
              cancellation_fee_choice: null,
              cancellation_pay_choice: null,
              cancellation_pay_triggered: false
            };
            await window.supabaseClient.from('meetings').update({
              cancellationNote: JSON.stringify(paidPayload),
              live_draft: { cancellation_pay: paidPayload }
            }).or(`reservationId.eq.${resId},reservation_id.eq.${resId}`);
          } catch (me) {}
        }
        if (typeof activeMeeting !== 'undefined' && activeMeeting && (activeMeeting.reservationId === resId || activeMeeting.reservation_id === resId)) {
          activeMeeting.cancellation_fee_status = isDpPaid ? 'paid' : 'final_paid';
          activeMeeting.cancellation_pay_triggered = false;
          activeMeeting.cancellation_fee_choice = null;
          activeMeeting.cancellation_pay_choice = null;
        }
      } else {
        // Both downpayment and final payment
        fbPayload = {
          downpayment_status: 'paid',
          downpaymentStatus: 'paid',
          downpayment_paid: true,
          final_payment_status: 'paid',
          finalPaymentStatus: 'paid',
          final_paid: true,
          settled: true,
          cancellation_status: 'settled',
          cancellation_request_status: 'settled',
          cancellation_fee_status: 'paid',
          cancellation_payment_method: 'gcash',
          cancellation_method: 'gcash',
          cancellation_amount_paid: amtPaid,
          cancellation_received: amtPaid,
          cancellation_change: change,
          cancellation_paid_at: nowIso,
          cancellation_received_by: adminName,
          cancellation_ref_id: refId,
          downpayment_method: 'gcash',
          final_method: 'gcash',
          downpayment_received: amtPaid,
          final_received: amtPaid,
          downpayment_change: change,
          final_change: change,
          downpayment_paid_at: nowIso,
          final_paid_at: nowIso,
          downpayment_ref_id: refId,
          final_ref_id: refId
        };
        if (uploadedUrl) {
          fbPayload.cancellation_proof = uploadedUrl;
          fbPayload.downpayment_proof = uploadedUrl;
          fbPayload.final_proof = uploadedUrl;
        }
        sbPayload = {
          downpayment_status: 'paid',
          final_payment_status: 'paid',
          settled: true,
          cancellation_status: 'settled',
          cancellation_request_status: 'settled',
          cancellation_payment_method: 'gcash',
          cancellation_method: 'gcash',
          cancellation_amount_paid: amtPaid,
          cancellation_received: amtPaid,
          cancellation_change: change,
          cancellation_paid_at: nowIso,
          cancellation_received_by: adminName,
          cancellation_ref_id: refId,
          downpayment_method: 'gcash',
          final_method: 'gcash',
          downpayment_received: amtPaid,
          final_received: amtPaid,
          downpayment_change: change,
          final_change: change,
          downpayment_paid_at: nowIso,
          final_paid_at: nowIso,
          downpayment_ref_id: refId,
          final_ref_id: refId
        };
        if (uploadedUrl) {
          sbPayload.cancellation_proof = uploadedUrl;
          sbPayload.downpayment_proof = uploadedUrl;
          sbPayload.final_proof = uploadedUrl;
        }
        try {
          await window.supabaseClient.from('reservation_payments').upsert({
            reservation_id: resId,
            cancellation_payment_status: 'paid',
            cancellation_method: 'gcash',
            cancellation_proof: uploadedUrl,
            cancellation_received: amtPaid,
            cancellation_change: change,
            cancellation_paid_at: nowIso,
            cancellation_received_by: adminName,
            cancellation_ref_id: refId,
            downpayment_status: 'paid',
            final_payment_status: 'paid',
            downpayment_method: 'gcash',
            final_method: 'gcash',
            downpayment_proof: uploadedUrl,
            final_proof: uploadedUrl,
            downpayment_received: amtPaid,
            final_received: amtPaid,
            downpayment_change: change,
            final_change: change,
            downpayment_paid_at: nowIso,
            final_paid_at: nowIso,
            downpayment_ref_id: refId,
            final_ref_id: refId,
            payment_method: 'gcash',
            amount_paid: amtPaid,
            updated_at: nowIso
          }, { onConflict: 'reservation_id' });
        } catch (pe) { console.warn('reservation_payments upsert error in manual GCash Cancellation:', pe); }
        if (window.supabaseClient) {
          try {
            const paidPayload = {
              cancellation_fee_status: 'paid',
              cancellation_pay_triggered: false
            };
            await window.supabaseClient.from('meetings').update({
              cancellationNote: JSON.stringify(paidPayload),
              live_draft: { cancellation_pay: paidPayload }
            }).or(`reservationId.eq.${resId},reservation_id.eq.${resId}`);
          } catch (me) { console.warn('meetings update error in manual GCash Cancellation:', me); }
        }
        if (typeof activeMeeting !== 'undefined' && activeMeeting && (activeMeeting.reservationId === resId || activeMeeting.reservation_id === resId)) {
          activeMeeting.cancellation_fee_status = 'paid';
          activeMeeting.cancellation_pay_triggered = false;
          activeMeeting.cancellationNote = JSON.stringify({ cancellation_fee_status: 'paid', cancellation_pay_triggered: false });
        }
      }
    } else if (feeType === 'business_liability') {
      fbPayload = {
        business_liability_paid: true,
        cancellation_business_paid: true,
        cancellation_status: 'settled',
        cancellation_request_status: 'settled',
        cancellation_payout_status: 'paid',
        cancellation_payout_method: 'gcash',
        cancellation_payout_amount: amtPaid,
        cancellation_payout_due: _manualGcashDueAmt,
        cancellation_payout_change: change,
        cancellation_payout_at: nowIso,
        cancellation_payout_by: adminName,
        cancellation_payout_ref: refId,
        downpayment_status: 'paid',
        final_payment_status: 'paid',
        settled: true
      };
      if (uploadedUrl) {
        fbPayload.cancellation_payout_proof = uploadedUrl;
        fbPayload.cancellation_proof = uploadedUrl;
      }
      sbPayload = {
        business_liability_paid: true,
        cancellation_business_paid: true,
        cancellation_status: 'settled',
        cancellation_request_status: 'settled',
        cancellation_payout_status: 'paid',
        cancellation_payout_method: 'gcash',
        cancellation_payout_amount: amtPaid,
        cancellation_payout_due: _manualGcashDueAmt,
        cancellation_payout_change: change,
        cancellation_payout_at: nowIso,
        cancellation_payout_by: adminName,
        cancellation_payout_ref: refId,
        downpayment_status: 'paid',
        final_payment_status: 'paid',
        settled: true
      };
      if (uploadedUrl) {
        sbPayload.cancellation_payout_proof = uploadedUrl;
        sbPayload.cancellation_proof = uploadedUrl;
      }
      try {
        await window.supabaseClient.from('reservation_payments').upsert({
          reservation_id: resId,
          business_liability_amount: _manualGcashDueAmt,
          business_liability_paid: true,
          cancellation_business_paid: true,
          cancellation_payment_status: 'paid',
          payment_method: 'gcash',
          amount_paid: amtPaid,
          cancellation_method: 'gcash',
          cancellation_payout_method: 'gcash',
          cancellation_payout_amount: amtPaid,
          cancellation_payout_due: _manualGcashDueAmt,
          cancellation_payout_change: change,
          cancellation_payout_at: nowIso,
          cancellation_payout_by: adminName,
          cancellation_payout_ref: refId,
          cancellation_payout_proof: uploadedUrl,
          downpayment_status: 'paid',
          final_payment_status: 'paid',
          updated_at: nowIso
        }, { onConflict: 'reservation_id' });
      } catch (pe) { console.warn('reservation_payments upsert error in manual GCash business liability:', pe); }
    }

    // 1. Update Firebase
    if (window.firebaseDB && window.firebaseFns && resId) {
      const { doc, updateDoc } = window.firebaseFns;
      try {
        await updateDoc(doc(window.firebaseDB, 'reservations', resId), fbPayload);
      } catch (fe) {
        console.warn('Firebase update failed in manual GCash:', fe);
      }
    }

    // 2. Update Supabase
    if (window.supabaseClient && resId) {
      try {
        await window.supabaseClient.from('reservations').update(sbPayload).eq('id', resId);
      } catch (se) {
        console.warn('Supabase update failed in manual GCash:', se);
      }
    }

    // Update in-memory RESERVATIONS item
    if (typeof RESERVATIONS !== 'undefined' && Array.isArray(RESERVATIONS)) {
      const resItem = RESERVATIONS.find(r => r.id === resId);
      if (resItem) {
        Object.assign(resItem, fbPayload);
      }
    }
    if (typeof activeMeetingResCache !== 'undefined' && activeMeetingResCache && (String(activeMeetingResCache.id) === String(resId) || !activeMeetingResCache.id)) {
      Object.assign(activeMeetingResCache, fbPayload);
    }

    closeManualGcashModal();
    showToast('GCash payment confirmed! Ref: ' + refId, 'success');

    // Trigger Automated Email Notification for Manual GCash Confirmation
    try {
      if (window.SmartServeNotifications && resId) {
        const targetRes = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(r => r.id === resId) || (typeof activeMeetingResCache !== 'undefined' ? activeMeetingResCache : null) || {};
        const custName = targetRes.customerName || targetRes.name || targetRes.client_name || 'Valued Customer';
        const custEmail = targetRes.customerEmail || targetRes.email || targetRes.client_email || '';
        const _feeLabels = { downpayment: 'Downpayment', final: 'Final Payment', initial_fee: 'Initial Fee', additional_charges: 'Additional Charges', cancellation: 'Cancellation Fee', business_liability: 'Business Liability Payout' };
        window.SmartServeNotifications.notifyPaymentMade({
          customerEmail: custEmail,
          customerName: custName,
          reservationId: resId,
          amount: amtPaid || _manualGcashDueAmt,
          paymentMethod: 'GCash',
          feeType: _feeLabels[feeType] || feeType,
          referenceNumber: refId,
          notes: `Amount Due: ₱${Number(_manualGcashDueAmt).toLocaleString()}, Amount Paid: ₱${Number(amtPaid).toLocaleString()}, Change: ₱${Number(change).toLocaleString()}, Verified By: ${adminName}`
        });
      }
    } catch(notifErr) {
      console.warn('[Manual GCash] Notification error:', notifErr);
    }

    try {
      const _feeLabels = { downpayment: 'Downpayment', final: 'Final Payment', initial_fee: 'Initial Fee', additional_charges: 'Additional Charges', cancellation: 'Cancellation Fee', business_liability: 'Business Liability Payout' };
      window.logResdActivity(resId, 'Recorded GCash Payment', `${_feeLabels[feeType] || feeType}: Unpaid -> Paid via GCash (Amount: ₱${Number(amtPaid).toLocaleString()}, Due: ₱${Number(_manualGcashDueAmt).toLocaleString()}, Change: ₱${Number(change).toLocaleString()}, Ref: ${refId})`);
    } catch (_logErr) {}

    // Refresh Payment Section overview and Payment Tab if active
    if (typeof renderPaymentSection === 'function') {
      renderPaymentSection();
    }
    if (typeof window.renderPaymentTab === 'function') {
      window.renderPaymentTab();
    }
    if (typeof window.renderResdCancellationTab === 'function') {
      window.renderResdCancellationTab();
    }
    if (typeof renderMeetingsSection === 'function') {
      renderMeetingsSection();
    }
    if (typeof renderMtModeCancellationPanel === 'function' && typeof activeMeetingResCache !== 'undefined' && activeMeetingResCache) {
      renderMtModeCancellationPanel(activeMeetingResCache);
    }
    if (typeof updateCancellationBillingUI === 'function') {
      updateCancellationBillingUI(activeMeetingResCache || (typeof resItem !== 'undefined' ? resItem : null));
    }
  } catch (err) {
    console.error('confirmManualGcashPayment error:', err);
    showToast('Failed to confirm GCash payment: ' + (err.message || err), 'error');
    if (confirmBtn) { confirmBtn.disabled = false; confirmBtn.textContent = 'Confirm Payment'; }
  }
};

// ====================================================================
// ADMIN HAL'SERVE QR CODE SCANNER (EXECUTION DAY MOBILE)
// ====================================================================
let adminQRStream = null;
let adminQRScanAnimId = null;
let adminQRIsScanning = false;
let adminQRFacingMode = 'environment';
let adminQRTorchActive = false;

window.openAdminQRScanner = async function() {
  const modal = document.getElementById('admin-qr-modal');
  const video = document.getElementById('admin-qr-video');
  const statusEl = document.getElementById('admin-qr-status');
  const resultBox = document.getElementById('admin-qr-result-box');
  const reticle = document.getElementById('admin-qr-reticle');
  const torchBtn = document.getElementById('admin-qr-torch-btn');

  if (!modal || !video) return;

  if (resultBox) resultBox.style.display = 'none';
  if (reticle) reticle.classList.remove('success');
  if (statusEl) statusEl.textContent = 'Starting camera...';
  if (torchBtn) torchBtn.style.display = 'none';
  adminQRTorchActive = false;

  modal.style.display = 'flex';
  document.body.style.overflow = 'hidden';

  await startAdminCameraFeed();
};

async function startAdminCameraFeed() {
  const video = document.getElementById('admin-qr-video');
  const statusEl = document.getElementById('admin-qr-status');
  const torchBtn = document.getElementById('admin-qr-torch-btn');

  stopAdminCameraTracks();

  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    if (statusEl) statusEl.textContent = 'Camera not supported in this browser. Please use image upload below.';
    return;
  }

  try {
    const stream = await navigator.mediaDevices.getUserMedia({
      video: {
        facingMode: adminQRFacingMode,
        width: { ideal: 1280 },
        height: { ideal: 720 }
      },
      audio: false
    });

    adminQRStream = stream;
    video.srcObject = stream;
    await video.play();

    if (statusEl) statusEl.textContent = 'Align QR code within frame';

    const track = stream.getVideoTracks()[0];
    if (track && typeof track.getCapabilities === 'function') {
      const caps = track.getCapabilities();
      if (caps && 'torch' in caps && torchBtn) {
        torchBtn.style.display = 'flex';
      }
    }

    adminQRIsScanning = true;
    runAdminQRScanLoop();

  } catch (err) {
    console.warn('Admin QR camera access error:', err);
    if (statusEl) {
      statusEl.textContent = 'Camera access blocked or unavailable. Use upload image option below.';
    }
  }
}

function stopAdminCameraTracks() {
  if (adminQRScanAnimId) {
    cancelAnimationFrame(adminQRScanAnimId);
    adminQRScanAnimId = null;
  }
  adminQRIsScanning = false;
  if (adminQRStream) {
    adminQRStream.getTracks().forEach(track => {
      try { track.stop(); } catch(e) {}
    });
    adminQRStream = null;
  }
}

window.closeAdminQRScanner = function() {
  stopAdminCameraTracks();
  const modal = document.getElementById('admin-qr-modal');
  if (modal) modal.style.display = 'none';
  document.body.style.overflow = '';
};

window.switchAdminCameraFacing = async function() {
  adminQRFacingMode = (adminQRFacingMode === 'environment') ? 'user' : 'environment';
  await startAdminCameraFeed();
};

window.toggleAdminCameraTorch = async function() {
  if (!adminQRStream) return;
  const track = adminQRStream.getVideoTracks()[0];
  if (!track || typeof track.applyConstraints !== 'function') return;

  try {
    adminQRTorchActive = !adminQRTorchActive;
    await track.applyConstraints({
      advanced: [{ torch: adminQRTorchActive }]
    });
    const label = document.getElementById('admin-torch-label');
    if (label) label.textContent = adminQRTorchActive ? 'Torch: On' : 'Flashlight';
  } catch(e) {
    console.warn('Torch toggle failed:', e);
  }
};

window.handleAdminQRFileUpload = function(event) {
  const file = event.target.files?.[0];
  if (!file) return;

  const reader = new FileReader();
  reader.onload = function(e) {
    const img = new Image();
    img.onload = function() {
      const canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d');
      ctx.drawImage(img, 0, 0, img.width, img.height);
      const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);

      let found = null;
      if (typeof jsQR === 'function') {
        found = jsQR(imgData.data, imgData.width, imgData.height);
      }

      if (found && found.data) {
        handleAdminQRRedirect(found.data);
      } else {
        alert('No readable QR code found in the selected image.');
      }
    };
    img.src = e.target.result;
  };
  reader.readAsDataURL(file);
};

async function runAdminQRScanLoop() {
  if (!adminQRIsScanning) return;
  const video = document.getElementById('admin-qr-video');
  const canvas = document.getElementById('admin-qr-canvas');

  if (!video || video.readyState < 2) {
    adminQRScanAnimId = requestAnimationFrame(runAdminQRScanLoop);
    return;
  }

  let detectedData = null;

  if ('BarcodeDetector' in window) {
    try {
      const detector = new BarcodeDetector({ formats: ['qr_code'] });
      const barcodes = await detector.detect(video);
      if (barcodes && barcodes.length > 0 && barcodes[0].rawValue) {
        detectedData = barcodes[0].rawValue;
      }
    } catch(e) {}
  }

  if (!detectedData && canvas && typeof jsQR === 'function') {
    const width = video.videoWidth;
    const height = video.videoHeight;
    if (width > 0 && height > 0) {
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d', { willReadFrequently: true });
      ctx.drawImage(video, 0, 0, width, height);
      const imgData = ctx.getImageData ? ctx.getImageData(0, 0, width, height) : null;
      if (imgData) {
        const code = jsQR(imgData.data, width, height, {
          inversionAttempts: 'dontInvert'
        });
        if (code && code.data) {
          detectedData = code.data;
        }
      }
    }
  }

  if (detectedData) {
    adminQRIsScanning = false;
    handleAdminQRRedirect(detectedData);
    return;
  }

  adminQRScanAnimId = requestAnimationFrame(runAdminQRScanLoop);
}

function handleAdminQRRedirect(scannedText) {
  const trimmed = (scannedText || '').trim();
  if (!trimmed) return;

  const reticle = document.getElementById('admin-qr-reticle');
  const statusEl = document.getElementById('admin-qr-status');
  const resultBox = document.getElementById('admin-qr-result-box');
  const resultText = document.getElementById('admin-qr-result-text');

  if (reticle) reticle.classList.add('success');
  if (statusEl) statusEl.textContent = 'QR Code detected!';
  if (resultBox) resultBox.style.display = 'block';
  if (resultText) resultText.textContent = trimmed;

  try { if (navigator.vibrate) navigator.vibrate(100); } catch(e) {}

  setTimeout(() => {
    closeAdminQRScanner();

    // Direct Web URLs or local files
    if (/^(https?:\/\/|mailto:|tel:|\/|\.\/)/i.test(trimmed)) {
      window.location.href = trimmed;
      return;
    }

    if (trimmed.endsWith('.html') || trimmed.includes('.html?') || trimmed.includes('.html#')) {
      window.location.href = trimmed;
      return;
    }

    // Reservation match in Execution Day
    const matched = (window.RESERVATIONS || []).find(r => r.id === trimmed || (r.id && r.id.toLowerCase() === trimmed.toLowerCase()));
    if (matched) {
      showSection('execution-day');
      if (typeof selectExecutionEvent === 'function') {
        selectExecutionEvent(matched.id);
      }
      if (typeof toggleExecMobileResDrawer === 'function') {
        toggleExecMobileResDrawer(false);
      }
      return;
    }

    // Fallback URL or notice
    try {
      new URL(trimmed);
      window.location.href = trimmed;
    } catch(e) {
      if (trimmed.includes('.') && !trimmed.includes(' ')) {
        window.location.href = 'https://' + trimmed;
      } else {
        alert('Scanned QR Content: ' + trimmed);
      }
    }
  }, 650);
}

// ============================================================================
// EMAIL NOTIFICATION TEMPLATES CONTROLLER
// ============================================================================

window._activeEmailTemplateKey = 'meeting_scheduled';

window.openEmailTemplatesModal = function() {
  const modal = document.getElementById('email-templates-modal');
  if (!modal) return;

  const notifService = window.HalServeNotifications || window.SmartServeNotifications;
  if (notifService) {
    const cfg = notifService.getConfig();
    const admInput = document.getElementById('cfg-admin-email');
    const testInput = document.getElementById('email-test-recipient');

    if (admInput) admInput.value = cfg.adminEmail || '';
    if (testInput && !testInput.value) {
      const logged = sessionStorage.getItem('halden_admin');
      if (logged) {
        try {
          const parsed = JSON.parse(logged);
          if (parsed.email) testInput.value = parsed.email;
        } catch(e) {}
      }
      if (!testInput.value && cfg.adminEmail) testInput.value = cfg.adminEmail;
    }

    // Refresh email configuration from Supabase system_settings in the background
    if (typeof notifService.syncEmailConfig === 'function') {
      notifService.syncEmailConfig().then(syncedCfg => {
        if (syncedCfg) {
          if (admInput && !admInput.value) admInput.value = syncedCfg.adminEmail || '';
        }
      }).catch(() => {});
    }
  }

  const select = document.getElementById('email-tpl-select');
  if (select) select.value = 'meeting_scheduled';
  window.onSelectEmailTemplate('meeting_scheduled');

  const disInput = document.getElementById('cfg-disable-emails');
  if (disInput) {
    // 1. Immediately reflect current local / in-memory state
    const currentDis = (notifService && typeof notifService.isEmailsDisabled === 'function')
      ? notifService.isEmailsDisabled()
      : (localStorage.getItem('smartserve_emails_disabled') === 'true');
    disInput.checked = !!currentDis;

    // 2. Fetch fresh state from Supabase system_settings
    if (notifService && typeof notifService.syncUniversalEmailSetting === 'function') {
      notifService.syncUniversalEmailSetting().then(isDis => {
        if (disInput) disInput.checked = !!isDis;
      }).catch(() => {});
    }

    disInput.onchange = function() {
      const isChecked = this.checked;
      try {
        localStorage.setItem('smartserve_emails_disabled', isChecked ? 'true' : 'false');
      } catch(e) {}
      if (notifService && typeof notifService.setEmailsDisabled === 'function') {
        notifService.setEmailsDisabled(isChecked);
      }
      if (typeof showToast === 'function') {
        showToast(isChecked ? 'Automated emails disabled across all devices.' : 'Automated emails enabled across all devices.', 'info');
      }
    };
  }

  modal.style.display = 'flex';
};

window.closeEmailTemplatesModal = function() {
  const modal = document.getElementById('email-templates-modal');
  if (modal) modal.style.display = 'none';
};

window.onSelectEmailTemplate = function(key) {
  window._activeEmailTemplateKey = key;
  if (!window.SmartServeNotifications) return;

  const templates = window.SmartServeNotifications.getTemplates();
  const tpl = templates[key] || window.SmartServeNotifications.DEFAULT_TEMPLATES[key] || {};

  const subjEl = document.getElementById('email-tpl-subject');
  const bodyEl = document.getElementById('email-tpl-body');
  if (subjEl) subjEl.value = tpl.subject || '';
  if (bodyEl) bodyEl.value = tpl.body || '';

  // Render clickable tags
  const tagsMap = {
    meeting_scheduled: ['client_name', 'date', 'time', 'agenda', 'room_id', 'reservation_id'],
    proposed_times_sent: ['client_name', 'agenda', 'proposed_slots', 'deadline', 'reservation_id'],
    meeting_confirmed_by_admin: ['client_name', 'date', 'time', 'agenda', 'room_id', 'reservation_id'],
    meeting_time_chosen_by_customer: ['client_name', 'date', 'time', 'agenda', 'reservation_id'],
    proposed_times_expired: ['client_name', 'agenda', 'reservation_id'],
    payment_receipt_customer: ['client_name', 'payment_type', 'amount', 'payment_method', 'reference_id', 'transaction_date', 'transaction_details', 'reservation_id'],
    payment_received_admin: ['client_name', 'payment_type', 'amount', 'payment_method', 'reference_id', 'transaction_date', 'transaction_details', 'reservation_id'],
    execution_countdown: ['client_name', 'package_name', 'event_date', 'event_time', 'venue', 'days_left', 'days_left_text', 'reservation_id'],
    logistics_task_completed: ['client_name', 'task_title', 'task_date', 'milestone_name', 'package_name', 'event_date', 'reservation_id'],
    equipment_incident_report: ['equipment_name', 'asset_id', 'incident_type', 'quantity', 'source', 'reported_by', 'date_time', 'reservation_id', 'notes'],
    payment_rejected_customer: ['client_name', 'payment_type', 'reference_id', 'reservation_id', 'reason', 'admin_email']
  };

  const tags = tagsMap[key] || ['client_name', 'date', 'time', 'agenda', 'reservation_id'];
  const container = document.getElementById('email-tags-container');
  if (container) {
    container.innerHTML = tags.map(tag => {
      return `<button type="button" class="email-tag-chip" onclick="insertEmailTag('${tag}')">+ {${tag}}</button>`;
    }).join('');
  }
};

window.insertEmailTag = function(tag) {
  const bodyEl = document.getElementById('email-tpl-body');
  if (!bodyEl) return;
  const tagText = `{${tag}}`;
  const start = bodyEl.selectionStart || bodyEl.value.length;
  const end = bodyEl.selectionEnd || bodyEl.value.length;
  const val = bodyEl.value;
  bodyEl.value = val.substring(0, start) + tagText + val.substring(end);
  bodyEl.focus();
  bodyEl.selectionStart = bodyEl.selectionEnd = start + tagText.length;
};

window.saveAllEmailTemplatesFromModal = async function() {
  const notifService = window.HalServeNotifications || window.SmartServeNotifications;
  if (!notifService) return;

  const admInput = document.getElementById('cfg-admin-email');
  const disInput = document.getElementById('cfg-disable-emails');

  const isDis = disInput ? !!disInput.checked : false;

  // Persist immediately to localStorage
  try {
    localStorage.setItem('smartserve_emails_disabled', isDis ? 'true' : 'false');
  } catch(e) {}

  // Await Supabase update and tab broadcast
  if (typeof notifService.setEmailsDisabled === 'function') {
    await notifService.setEmailsDisabled(isDis);
  }

  const cfg = {
    templateId: 'template_2v5slsl',
    serviceId: 'service_8hcbt1e',
    adminEmail: admInput ? admInput.value.trim() : '',
    emails_disabled: isDis
  };
  notifService.saveConfig(cfg);

  const activeKey = window._activeEmailTemplateKey || 'meeting_scheduled';
  const subjEl = document.getElementById('email-tpl-subject');
  const bodyEl = document.getElementById('email-tpl-body');

  const templates = notifService.getTemplates();
  if (templates[activeKey]) {
    if (subjEl) templates[activeKey].subject = subjEl.value;
    if (bodyEl) templates[activeKey].body = bodyEl.value;
  }
  notifService.saveTemplates(templates);

  if (typeof showToast === 'function') {
    showToast('Email notification settings saved!', 'success');
  } else {
    alert('Email notification settings saved successfully!');
  }

  window.closeEmailTemplatesModal();
};

window.resetSelectedEmailTemplate = function() {
  const activeKey = window._activeEmailTemplateKey || 'meeting_scheduled';
  if (!window.SmartServeNotifications) return;

  if (confirm(`Reset the "${activeKey}" template to its default content?`)) {
    const def = window.SmartServeNotifications.resetTemplate(activeKey);
    const subjEl = document.getElementById('email-tpl-subject');
    const bodyEl = document.getElementById('email-tpl-body');
    if (subjEl && def) subjEl.value = def.subject;
    if (bodyEl && def) bodyEl.value = def.body;
    if (typeof showToast === 'function') showToast('Template reset to default.', 'info');
  }
};

window.triggerTestEmailSend = async function() {
  const activeKey = window._activeEmailTemplateKey || 'meeting_scheduled';
  const recipientInput = document.getElementById('email-test-recipient');
  const recipient = recipientInput ? recipientInput.value.trim() : '';

  if (!recipient || !recipient.includes('@')) {
    alert('Please enter a valid recipient email address for testing.');
    if (recipientInput) recipientInput.focus();
    return;
  }

  const btn = document.getElementById('btn-send-test-email');
  const origText = btn ? btn.textContent : '';
  if (btn) { btn.disabled = true; btn.textContent = 'Sending Test...'; }

  try {
    const subjEl = document.getElementById('email-tpl-subject');
    const bodyEl = document.getElementById('email-tpl-body');
    const customSubject = subjEl ? subjEl.value : null;
    const customBody = bodyEl ? bodyEl.value : null;

    // Temporarily save current form values so the test reflects current edits
    const notif = window.HalServeNotifications || window.SmartServeNotifications;
    if (notif && typeof notif.getTemplates === 'function') {
      const templates = notif.getTemplates();
      if (!templates[activeKey]) templates[activeKey] = {};
      if (subjEl) templates[activeKey].subject = subjEl.value;
      if (bodyEl) templates[activeKey].body = bodyEl.value;
      if (typeof notif.saveTemplates === 'function') notif.saveTemplates(templates);
    }

    const admInput = document.getElementById('cfg-admin-email');
    if (notif && typeof notif.saveConfig === 'function') {
      notif.saveConfig({
        templateId: 'template_2v5slsl',
        serviceId: 'service_8hcbt1e',
        adminEmail: admInput ? admInput.value.trim() : undefined
      });
    }

    const res = await (notif ? notif.sendTestEmail(activeKey, recipient, { subject: customSubject, body: customBody }) : { success: false, reason: 'Notifications service not loaded.' });
    const ok = res === true || (res && res.success === true);

    if (ok) {
      const successMsg = 'Test email successfully sent to ' + recipient + '! Please check your inbox and spam/junk folder.';
      if (typeof showToast === 'function') {
        showToast(successMsg, 'success');
      } else {
        alert(successMsg);
      }
    } else {
      const reason = (res && res.reason) || (notif && typeof notif.getLastSendError === 'function' ? notif.getLastSendError() : null) || 'Please verify your internet connection.';
      alert('Could not send test email:\n\n' + reason);
    }
  } catch(e) {
    console.error('[triggerTestEmailSend]', e);
    alert('Error sending test email: ' + (e.message || e));
  } finally {
    if (btn) { btn.disabled = false; btn.textContent = origText; }
  }
};

