// ADMIN NOTIFICATIONS DRAWER (STEP 5D)
// ====================================================================

window._adminNotifPage = 1;
window._lastAdminNotifs = [];

function getAdminSeenNotifs() {
  try {
    const raw = localStorage.getItem('admin_seen_notif_ids');
    return raw ? JSON.parse(raw) : [];
  } catch (e) {
    return [];
  }
}
window.getAdminSeenNotifs = getAdminSeenNotifs;

function saveAdminSeenNotifs(ids) {
  try {
    localStorage.setItem('admin_seen_notif_ids', JSON.stringify(ids || []));
  } catch (e) { }
}
window.saveAdminSeenNotifs = saveAdminSeenNotifs;

function toggleAdminNotifDrawer(show) {
  const drawer = document.getElementById('admin-notif-drawer');
  const backdrop = document.getElementById('admin-notif-drawer-backdrop');
  if (!drawer) return;
  const isCurrentlyOpen = drawer.style.right === '0px' || drawer.classList.contains('open');
  let targetOpen;
  if (typeof show === 'boolean') {
    targetOpen = show;
  } else if (show && show.target) {
    if (show.stopPropagation) show.stopPropagation();
    targetOpen = !isCurrentlyOpen;
  } else {
    targetOpen = !isCurrentlyOpen;
  }

  if (targetOpen) {
    drawer.style.right = '0px';
    drawer.style.left = 'auto';
    drawer.classList.add('open');
    if (backdrop) backdrop.style.display = 'block';
    renderAdminNotifications();
  } else {
    drawer.style.right = '-440px';
    drawer.style.left = 'auto';
    drawer.classList.remove('open');
    if (backdrop) backdrop.style.display = 'none';
  }
}
window.toggleAdminNotifDrawer = toggleAdminNotifDrawer;

function markAllAdminNotifsSeen() {
  if (!window._lastAdminNotifs || !Array.isArray(window._lastAdminNotifs)) return;
  const allIds = window._lastAdminNotifs.map(n => n.id);
  saveAdminSeenNotifs(allIds);
  const badge = document.getElementById('admin-notif-badge');
  if (badge) {
    badge.textContent = '0';
    badge.style.display = 'none';
  }
  const drawerBadge = document.getElementById('admin-drawer-count-badge');
  if (drawerBadge) drawerBadge.textContent = '0';
  renderAdminNotifications();
  if (typeof showToast === 'function') showToast('All notifications marked as seen', 'success');
}
window.markAllAdminNotifsSeen = markAllAdminNotifsSeen;

function gatherAdminNotifications() {
  const notifs = [];
  const resList = (typeof RESERVATIONS !== 'undefined' && Array.isArray(RESERVATIONS)) ? RESERVATIONS : (window.RESERVATIONS || []);
  const today = new Date();
  today.setHours(0, 0, 0, 0);

  // 1. Pending cancellation requests
  const cancelRequests = resList.filter(r => {
    if (r.status === 'cancelled' || r.status === 'rejected') return false;
    return r.cancellation_requested === true || r.cancellation_request_status === 'pending';
  });
  cancelRequests.forEach(r => {
    const clientName = r.client || r.name || 'Client';
    const pkgName = r.packageName || r.type || 'Event';
    notifs.push({
      id: 'cancel-' + r.id,
      category: 'cancellation',
      badgeText: 'Cancellation Request',
      badgeStyle: 'color:#ef4444; font-weight:700;',
      title: `${clientName} requested cancellation`,
      detail: `${pkgName} · Event Date: ${r.date || 'TBD'}`,
      timestamp: new Date(r.cancellation_requested_at || r.updated_at || r.date || Date.now()).getTime(),
      targetId: r.id,
      actionType: 'cancel_res'
    });
  });

  // 2. Scheduled & Upcoming Meetings
  const meetingsList = (typeof MEETINGS !== 'undefined' && Array.isArray(MEETINGS)) ? MEETINGS : (window.MEETINGS || []);
  meetingsList.forEach(m => {
    if (typeof isMeetingInPast === 'function' && isMeetingInPast(m)) return;
    const mDate = m.date || '';
    const mTime = m.time || '';
    const dt = new Date(mDate ? (mDate + 'T' + (mTime || '09:00')) : Date.now());
    const clientName = m.clientName || m.client || (m.reservationId && resList.find(r => r.id === m.reservationId)?.client) || 'Client';
    notifs.push({
      id: 'meeting-' + (m.id || m.reservationId || (mDate + mTime)),
      category: 'meeting',
      badgeText: 'Meeting Scheduled',
      badgeStyle: 'color:#60a5fa; font-weight:700;',
      title: `Scheduled Meeting: ${clientName}`,
      detail: `${mDate} at ${mTime || 'TBD'} · ${m.topic || m.agenda || 'Event Consultation'}`,
      timestamp: dt.getTime() || Date.now(),
      targetId: m.reservationId || m.id,
      actionType: 'meeting'
    });
  });

  // 3. New Pending Reservations
  const pendingRes = resList.filter(r => r.status === 'pending' || r.status === 'awaiting_approval' || r.status === 'under_review');
  pendingRes.forEach(r => {
    const clientName = r.client || r.name || 'Client';
    const pkgName = r.packageName || r.type || 'Event';
    const dt = r.created_at ? new Date(r.created_at) : new Date(r.date || Date.now());
    notifs.push({
      id: 'pending-res-' + r.id,
      category: 'pending_res',
      badgeText: 'Pending Review',
      badgeStyle: 'color:#f59e0b; font-weight:700;',
      title: `New Reservation: ${clientName}`,
      detail: `${pkgName} · ${r.date || 'TBD'} (${r.pax || r.guests || 0} pax)`,
      timestamp: dt.getTime() || Date.now(),
      targetId: r.id,
      actionType: 'res_detail'
    });
  });

  // 4. Approved Reservation Countdowns (events happening in <= 30 days)
  const upcomingConfirmed = resList.filter(r => (r.status === 'confirmed' || r.status === 'approved') && r.date);
  upcomingConfirmed.forEach(r => {
    const evDate = new Date(r.date + 'T00:00:00');
    const diffMs = evDate - today;
    const diffDays = Math.ceil(diffMs / (1000 * 60 * 60 * 24));
    if (diffDays >= 0 && diffDays <= 30) {
      const clientName = r.client || r.name || 'Client';
      const pkgName = r.packageName || r.type || 'Event';
      const countdownLabel = diffDays === 0 ? 'Today!' : diffDays === 1 ? 'Tomorrow (1 day away)' : `${diffDays} days away`;
      notifs.push({
        id: 'countdown-' + r.id + '-' + r.date,
        category: 'countdown',
        badgeText: diffDays === 0 ? 'Event Today' : 'Event Countdown',
        badgeStyle: diffDays <= 3 ? 'color:#ef4444; font-weight:700;' : 'color:var(--gold); font-weight:700;',
        title: `Event Countdown: ${countdownLabel}`,
        detail: `${clientName} · ${pkgName} · ${r.date}`,
        timestamp: evDate.getTime(),
        targetId: r.id,
        actionType: 'res_detail'
      });
    }
  });

  // 5. Overdue Routine Equipment Check
  if (typeof isRoutineCheckOverdue === 'function' && isRoutineCheckOverdue()) {
    const days = typeof daysSinceLastCheck === 'function' ? daysSinceLastCheck() : 8;
    notifs.push({
      id: 'overdue-routine-check',
      category: 'routine_check',
      badgeText: 'Inspection Overdue',
      badgeStyle: 'color:#ef4444; font-weight:700;',
      title: 'Routine Equipment Check Overdue',
      detail: `Last check was ${days} days ago. Weekly equipment inspection is required.`,
      timestamp: Date.now(),
      targetId: 'routine-check',
      actionType: 'routine_check'
    });
  }

  // Sort priority: Cancellation requests and overdue checks first, then latest/closest events
  notifs.sort((a, b) => {
    const priorityScore = (item) => {
      if (item.category === 'cancellation') return 1;
      if (item.category === 'routine_check') return 2;
      if (item.category === 'pending_res') return 3;
      if (item.category === 'countdown') return 4;
      return 5;
    };
    const pA = priorityScore(a);
    const pB = priorityScore(b);
    if (pA !== pB) return pA - pB;
    return b.timestamp - a.timestamp;
  });

  return notifs;
}
window.gatherAdminNotifications = gatherAdminNotifications;

function handleAdminNotifClick(notifId, actionType, targetId) {
  toggleAdminNotifDrawer(false);
  if (actionType === 'cancel_res') {
    if (typeof openCancellationRequestModal === 'function') {
      openCancellationRequestModal(targetId);
    } else if (typeof openResModal === 'function') {
      openResModal(targetId);
    }
  } else if (actionType === 'meeting') {
    const nav = document.getElementById('nav-meetings');
    if (nav) nav.click();
    else if (typeof openMeetingModal === 'function') {
      openMeetingModal(targetId);
    }
  } else if (actionType === 'res_detail') {
    if (typeof openResModal === 'function') {
      openResModal(targetId);
    }
  } else if (actionType === 'routine_check') {
    const nav = document.getElementById('nav-routine-check');
    if (nav) nav.click();
  }
}
window.handleAdminNotifClick = handleAdminNotifClick;

window.changeAdminNotifPage = function(delta) {
  const notifs = window._lastAdminNotifs || [];
  const totalPages = Math.ceil(notifs.length / 20) || 1;
  const targetPage = (window._adminNotifPage || 1) + delta;
  if (targetPage >= 1 && targetPage <= totalPages) {
    window._adminNotifPage = targetPage;
    renderAdminNotifications();
  }
};

function renderAdminNotifications() {
  const notifs = gatherAdminNotifications();
  window._lastAdminNotifs = notifs;

  const seenIds = new Set(getAdminSeenNotifs());
  const unseenCount = notifs.filter(n => !seenIds.has(n.id)).length;

  // Update topbar badge
  const badge = document.getElementById('admin-notif-badge');
  if (badge) {
    if (unseenCount > 0) {
      badge.textContent = unseenCount > 99 ? '99+' : String(unseenCount);
      badge.style.display = 'inline-block';
    } else {
      badge.textContent = '0';
      badge.style.display = 'none';
    }
  }

  // Update drawer count badge
  const drawerCountBadge = document.getElementById('admin-drawer-count-badge');
  if (drawerCountBadge) {
    drawerCountBadge.textContent = String(unseenCount);
    drawerCountBadge.style.background = unseenCount > 0 ? '#dc2626' : 'var(--gold, #c49a3c)';
    drawerCountBadge.style.color = '#ffffff';
  }

  const listContainer = document.getElementById('admin-notif-list');
  const paginationContainer = document.getElementById('admin-notif-pagination');
  if (!listContainer) return;

  if (notifs.length === 0) {
    listContainer.innerHTML = '<div style="text-align:center; padding:48px 20px; color:var(--text-dim); font-size:13px;">No notifications found. All clear!</div>';
    if (paginationContainer) {
      paginationContainer.innerHTML = '';
      paginationContainer.style.display = 'none';
    }
    return;
  }

  // Pagination: 20 per page
  const pageSize = 20;
  const totalPages = Math.ceil(notifs.length / pageSize) || 1;
  if (window._adminNotifPage > totalPages) window._adminNotifPage = totalPages;
  if (window._adminNotifPage < 1) window._adminNotifPage = 1;
  const page = window._adminNotifPage;

  const startIdx = (page - 1) * pageSize;
  const pageItems = notifs.slice(startIdx, startIdx + pageSize);

  listContainer.innerHTML = pageItems.map(item => {
    const isSeen = seenIds.has(item.id);
    return `
      <div onclick="handleAdminNotifClick('${escHtml(item.id)}', '${escHtml(item.actionType)}', '${escHtml(item.targetId)}')"
        style="background:rgba(255,255,255,0.02); border:1px solid ${isSeen ? 'rgba(255,255,255,0.05)' : 'rgba(196,154,60,0.25)'}; border-radius:8px; padding:12px 14px; cursor:pointer; transition:all 0.15s ease; display:flex; flex-direction:column; gap:6px;">
        <div style="display:flex; justify-content:space-between; align-items:center; gap:8px;">
          <span style="${item.badgeStyle} font-size:10px; text-transform:uppercase; letter-spacing:0.5px;">${escHtml(item.badgeText)}</span>
          ${!isSeen ? '<span style="width:7px; height:7px; border-radius:50%; background:#dc2626; display:inline-block; box-shadow:0 0 6px rgba(220,38,38,0.7);" title="Unread"></span>' : ''}
        </div>
        <div style="font-size:13px; font-weight:700; color:var(--cream); line-height:1.35;">${escHtml(item.title)}</div>
        <div style="font-size:11.5px; color:var(--text-dim); line-height:1.4;">${escHtml(item.detail)}</div>
      </div>
    `;
  }).join('');

  if (paginationContainer) {
    if (totalPages > 1) {
      paginationContainer.innerHTML = `
        <button class="btn-primary" style="padding:4px 10px; font-size:11px; font-weight:700; background:rgba(196,154,60,0.12); border:1px solid var(--gold, #c49a3c); color:var(--gold, #c49a3c); border-radius:5px; cursor:${page > 1 ? 'pointer' : 'not-allowed'}; opacity:${page > 1 ? '1' : '0.4'};" onclick="changeAdminNotifPage(-1)" ${page <= 1 ? 'disabled' : ''}>&larr; Prev</button>
        <span style="font-size:11.5px; font-weight:700; color:var(--text-mid);">Page ${page} of ${totalPages}</span>
        <button class="btn-primary" style="padding:4px 10px; font-size:11px; font-weight:700; background:rgba(196,154,60,0.12); border:1px solid var(--gold, #c49a3c); color:var(--gold, #c49a3c); border-radius:5px; cursor:${page < totalPages ? 'pointer' : 'not-allowed'}; opacity:${page < totalPages ? '1' : '0.4'};" onclick="changeAdminNotifPage(1)" ${page >= totalPages ? 'disabled' : ''}>Next &rarr;</button>
      `;
      paginationContainer.style.display = 'flex';
    } else {
      paginationContainer.innerHTML = '';
      paginationContainer.style.display = 'none';
    }
  }
}
window.renderAdminNotifications = renderAdminNotifications;

