function renderMaintenancePipelineList() {
  const listEl = document.getElementById('mnt-pipeline-list');
  if (!listEl) return;

  const records = [];
  (window.routineChecksCache || []).forEach(rc => {
    if (rc.status === 'incident') {
      const asset = (EIM_ASSETS || []).find(a => a.supabaseId === rc.equipment_id || a.id === rc.equipment_id || a.asset_id === rc.asset_id);
      let rcCode = rc.item_code || null;
      if (!rcCode && rc.incidents) {
        try {
          const incs = typeof rc.incidents === 'string' ? JSON.parse(rc.incidents) : rc.incidents;
          if (Array.isArray(incs)) {
            const f = incs.find(i => i.item_code);
            if (f) rcCode = f.item_code;
          }
        } catch(e) {}
      }
      if (!rcCode && rc.notes) {
        const m = rc.notes.match(/\b(EQ-[A-Za-z0-9]+-\d+)\b/i);
        if (m) rcCode = m[1];
      }
      if (!rcCode) rcCode = asset ? (asset.asset_id || asset.id) : (rc.equipment_id || '—');
      records.push({
        id: rc.id,
        item_code: rcCode,
        name: rc.equipment_name || (asset ? asset.name : 'Equipment'),
        issue: 'Damage reported during routine inspection',
        date: rc.checked_at ? new Date(rc.checked_at).toLocaleDateString() : 'Recent',
        reporter: rc.checked_by || 'Admin',
        status: 'Review Pending'
      });
    }
  });

  (window.maintenanceTasks || []).forEach(t => {
    const asset = (EIM_ASSETS || []).find(a => a.supabaseId === t.equipment_id || a.id === t.equipment_id || a.asset_id === t.equipment_id);
    let tCode = t.item_code || null;
    if (!tCode && t.repair_notes) {
      const m = t.repair_notes.match(/\b(EQ-[A-Za-z0-9]+-\d+)\b/i);
      if (m) tCode = m[1];
    }
    if (!tCode) tCode = asset ? (asset.asset_id || asset.id) : (t.equipment_id || '—');
    records.push({
      id: t.id,
      item_code: tCode,
      name: t.equipment_name || t.name || (asset ? asset.name : 'Equipment'),
      issue: t.issue || 'Ongoing maintenance repair',
      date: t.date_in ? new Date(t.date_in).toLocaleDateString() : 'Recent',
      reporter: t.reported_by || 'Staff',
      status: t.status || 'In Repair'
    });
  });

  if (!records.length) {
    listEl.innerHTML = '<div style="padding:32px; text-align:center; color:var(--text-dim); font-size:13px;">No equipment currently in maintenance pipeline.</div>';
    return;
  }

  let rowsHtml = '';
  records.forEach(r => {
    rowsHtml += `
      <tr style="border-bottom:1px solid rgba(255,255,255,0.05);">
        <td style="padding:10px 14px; font-family:monospace; color:var(--gold); font-weight:700;">${escHtml(r.item_code)}</td>
        <td style="padding:10px 14px; font-weight:600; color:var(--cream);">${escHtml(r.name)}</td>
        <td style="padding:10px 14px; font-size:12px; color:var(--text-mid);">${escHtml(r.issue)}</td>
        <td style="padding:10px 14px; font-size:12px; color:var(--text-dim);">${escHtml(r.date)}</td>
        <td style="padding:10px 14px; font-size:12px; color:var(--cream);">${escHtml(r.reporter)}</td>
        <td style="padding:10px 14px; font-size:11px; font-weight:700; color:var(--orange);">${escHtml(r.status)}</td>
        <td style="padding:10px 14px; text-align:right;">
          <a href="scan.html?eq=${encodeURIComponent(r.item_code)}" target="_blank" class="btn-outline" style="font-size:10px; padding:3px 8px; text-decoration:none;">Open Scan</a>
        </td>
      </tr>
    `;
  });

  listEl.innerHTML = `
    <table class="inv-table" style="width:100%; border-collapse:collapse; font-size:12px;">
      <thead>
        <tr style="background:rgba(255,255,255,0.03);">
          <th>UNIT ID</th>
          <th>EQUIPMENT NAME</th>
          <th>INCIDENT / ISSUE</th>
          <th>REPORTED DATE</th>
          <th>REPORTED BY</th>
          <th>STAGE</th>
          <th style="text-align:right;">ACTIONS</th>
        </tr>
      </thead>
      <tbody>${rowsHtml}</tbody>
    </table>
  `;
}

