function renderDisposedListTable() {
  const tbody = document.getElementById('dsp-list-tbody');
  if (!tbody) return;

  const records = typeof getDisposedRecords === 'function' ? getDisposedRecords() : [];
  if (!records.length) {
    tbody.innerHTML = '<tr><td colspan="7" style="text-align:center;padding:28px;color:var(--text-dim);">No archived retired equipment found.</td></tr>';
    return;
  }

  let html = '';
  records.forEach(r => {
    let itemCode = r.item_code;
    if (!itemCode && r.name) {
      const hashMatch = r.name.match(/#(\d+)/);
      if (hashMatch) {
        const num = String(hashMatch[1]).padStart(3, '0');
        const baseId = r.assetId || 'EQ-0001';
        itemCode = `${baseId}-${num}`;
      }
    }
    if (!itemCode && r.reason) {
      const m = r.reason.match(/\b(EQ-[A-Za-z0-9]+-\d+)\b/i);
      if (m) itemCode = m[1];
    }
    if (!itemCode) itemCode = r.assetId || '—';
    html += `
      <tr style="border-bottom:1px solid rgba(255,255,255,0.05);">
        <td style="padding:10px 14px; font-family:monospace; color:var(--gold); font-weight:700;">${escHtml(itemCode)}</td>
        <td style="padding:10px 14px; font-weight:600; color:var(--cream);">${escHtml(r.name)}</td>
        <td style="padding:10px 14px; font-size:12px; color:var(--text-mid);">${escHtml(r.reason)}</td>
        <td style="padding:10px 14px; font-size:12px; color:var(--text-dim);">${new Date(r.date).toLocaleDateString()}</td>
        <td style="padding:10px 14px; font-size:12px; color:var(--cream);">${escHtml(r.loggedBy || 'Admin')}</td>
        <td style="padding:10px 14px; text-align:right; font-weight:700; color:var(--red);">₱${(r.valueLoss || 0).toLocaleString()}</td>
        <td style="padding:10px 14px; text-align:right;">
          <a href="scan.html?eq=${encodeURIComponent(itemCode)}" target="_blank" class="btn-outline" style="font-size:10px; padding:3px 8px; text-decoration:none;">Open Scan</a>
        </td>
      </tr>
    `;
  });
  tbody.innerHTML = html;
}


