let _equipmentRealtimeChannel = null;

async function refreshAllIncidentAndMaintenanceAreas() {
  try {
    if (typeof loadMaintenanceDataFromSupabase === 'function') {
      await loadMaintenanceDataFromSupabase();
    }
    if (typeof renderMaintenanceSection === 'function') {
      renderMaintenanceSection();
    }
    if (typeof renderResupplySection === 'function') {
      await renderResupplySection();
    }
    if (typeof updateResupplyBadge === 'function') {
      updateResupplyBadge();
    }
    if (typeof renderDisposedSection === 'function') {
      renderDisposedSection();
    }
    if (typeof renderEIMTable === 'function') {
      renderEIMTable();
    }
    if (typeof renderEIMIncidentLogs === 'function') {
      renderEIMIncidentLogs();
    }
  } catch(e) {
    console.warn('[refreshAllIncidentAndMaintenanceAreas] error:', e);
  }
}
window.refreshAllIncidentAndMaintenanceAreas = refreshAllIncidentAndMaintenanceAreas;

try {
  const _eimBc = new BroadcastChannel('eim_realtime_channel');
  _eimBc.onmessage = async function(evt) {
    if (evt && (evt.data?.type === 'INCIDENT_REPORTED' || evt.data?.type === 'ROUTINE_CHECK_SAVED' || evt.data?.type === 'EQUIPMENT_UPDATED' || evt.data?.type === 'MAINTENANCE_UPDATED')) {
      if (typeof loadEquipmentDataFromSupabase === 'function') await loadEquipmentDataFromSupabase();
      await refreshAllIncidentAndMaintenanceAreas();
      if (typeof renderEIMTable === 'function') renderEIMTable();
    }
  };
} catch(e) {}

function subscribeToEquipmentRealtime() {
  if (_equipmentRealtimeChannel) return;
  const sb = window.supabaseClient || (typeof rcSupabase === 'function' ? rcSupabase() : null);
  if (!sb) return;
  try {
    _equipmentRealtimeChannel = sb.channel('admin-equipment-inventory-realtime')
      .on('postgres_changes', { event: '*', schema: 'public', table: 'equipment_inventory' }, async function(payload) {
        console.log('[Realtime] equipment_inventory changed:', payload);
        if (payload.eventType === 'UPDATE' && payload.new) {
          const row = payload.new;
          const found = (EIM_ASSETS || []).find(a => a.supabaseId === row.id || a.id === row.asset_id || a.asset_id === row.asset_id);
          if (found) {
            found.quantity = parseInt(row.total_qty) || found.quantity;
            found.total_qty = row.total_qty;
            found.good_qty = row.good_qty;
            found.maintenance_qty = row.maintenance_qty;
            found.missing_qty = row.missing_qty;
            found.retired_qty = row.retired_qty;
            found.availableQty = row.available_qty != null ? parseInt(row.available_qty) : found.availableQty;
            found.condition = row.condition || found.condition;
            found.status = row.status || found.status;
            found.tracking_mode = row.tracking_mode || found.tracking_mode;
            found.trackingMode = row.tracking_mode || found.trackingMode;
            found.supplier = row.supplier || found.supplier;
            found.purchase_history = row.purchase_history || found.purchase_history;
          }
          if (typeof renderEIMTable === 'function') renderEIMTable();
          if (typeof renderDashboard === 'function') renderDashboard();
          if (typeof updateMaintenanceStats === 'function') updateMaintenanceStats();
        } else if (payload.eventType === 'INSERT' || payload.eventType === 'DELETE') {
          if (typeof loadEquipmentDataFromSupabase === 'function') {
            await loadEquipmentDataFromSupabase();
          }
        }
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'equipment_unit_items' }, async function(payload) {
        console.log('[Realtime] equipment_unit_items changed:', payload);
        const u = payload.new || payload.old;
        if (u && u.asset_id) {
          if (window.EQUIPMENT_UNITS_CACHE) {
            delete window.EQUIPMENT_UNITS_CACHE[u.asset_id];
          }
          if (typeof window.HalServeUnitTracker?.getEquipmentUnits === 'function') {
            await window.HalServeUnitTracker.getEquipmentUnits(u.asset_id, true);
          }
          if (typeof window.syncParentEquipmentWithUnits === 'function') {
            await window.syncParentEquipmentWithUnits(u.asset_id);
          }
          if (typeof renderEIMTable === 'function') renderEIMTable();
          if (typeof renderDashboard === 'function') renderDashboard();
          if (typeof renderActiveChecklist === 'function') renderActiveChecklist();
        }
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'routine_check' }, async function(payload) {
        console.log('[Realtime] routine_check changed:', payload);
        if (typeof fetchSupabaseScanLogs === 'function') {
          await fetchSupabaseScanLogs();
        }
        if (typeof renderRoutineCheckSection === 'function') {
          renderRoutineCheckSection();
        }
        await refreshAllIncidentAndMaintenanceAreas();
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'equipment_maintenance' }, async function(payload) {
        console.log('[Realtime] equipment_maintenance changed:', payload);
        await refreshAllIncidentAndMaintenanceAreas();
      })
      .on('postgres_changes', { event: '*', schema: 'public', table: 'standalone_incident_reports' }, async function(payload) {
        console.log('[Realtime] standalone_incident_reports changed:', payload);
        await refreshAllIncidentAndMaintenanceAreas();
      })
      .subscribe();
  } catch(e) {
    console.warn('[Realtime] subscribeToEquipmentRealtime notice:', e);
  }
}
window.subscribeToEquipmentRealtime = subscribeToEquipmentRealtime;

window.markMaintenanceEquipmentMissing = async function(recordId, assetId) {
  const asset = (EIM_ASSETS || []).find(a => (a.id === assetId || a.asset_id === assetId || a.supabaseId === assetId));
  if (!asset) return;

  let missingQty = 1;
  let targetItemCode = null;

  const rc = (window.routineChecksCache || []).find(r => r.id === recordId);
  const sa = (window.standaloneIncidentsCache || []).find(s => s.id === recordId);
  const inc = (window.execBatchIncidentsCache || []).find(i => i.id === recordId);
  const task = (window.maintenanceTasks || []).find(t => t.id === recordId);

  if (rc) {
    targetItemCode = rc.item_code;
    missingQty = parseInt(rc.quantity) || 1;
  } else if (sa) {
    targetItemCode = sa.item_code;
    missingQty = parseInt(sa.quantity) || 1;
  } else if (inc) {
    targetItemCode = inc.item_code;
    missingQty = parseInt(inc.quantity) || 1;
  } else if (task) {
    targetItemCode = task.item_code;
    missingQty = parseInt(task.quantity) || 1;
  }

  const cleanAssetId = asset.asset_id || asset.id;
  const newMntQty = Math.max(0, (asset.maintenance_qty || 0) - missingQty);
  const newMissQty = (asset.missing_qty || 0) + missingQty;

  const sb = window.supabaseClient || (typeof rcSupabase === 'function' ? rcSupabase() : null);
  if (sb) {
    try {
      if (targetItemCode) {
        await sb.from('equipment_unit_items').update({
          condition: 'Missing',
          status: 'Missing',
          allocated_reservation_id: null,
          allocation_batch: null
        }).eq('item_code', targetItemCode);
      }

      await sb.from('equipment_inventory').update({
        maintenance_qty: newMntQty,
        missing_qty: newMissQty
      }).eq('id', asset.supabaseId || asset.id);

      if (rc) await sb.from('routine_check').update({ status: 'good' }).eq('id', rc.id);
      if (sa) await sb.from('standalone_incident_reports').update({ is_reverted: true }).eq('id', sa.id);
      if (task) await sb.from('equipment_maintenance').update({ status: 'missing', repair_notes: 'Marked as missing' }).eq('id', task.id);

      if (typeof window.syncParentEquipmentWithUnits === 'function') {
        await window.syncParentEquipmentWithUnits(cleanAssetId);
      }
    } catch(err) {
      console.warn('[markMaintenanceEquipmentMissing] notice:', err);
    }
  }

  asset.maintenance_qty = newMntQty;
  asset.missing_qty = newMissQty;

  if (typeof recordEIMLog === 'function') {
    recordEIMLog({
      action: 'Marked Equipment Missing',
      eqId: targetItemCode || cleanAssetId,
      item_code: targetItemCode || '',
      equipment_id: cleanAssetId,
      eqName: asset.name + (targetItemCode ? ` (${targetItemCode})` : ''),
      details: `Marked ${missingQty} unit(s) of "${asset.name}" (${targetItemCode || cleanAssetId}) as missing. Removed from active fleet.`
    });
  }

  showToast('Equipment marked as missing and removed from active fleet.');
  if (typeof renderMaintenanceSection === 'function') renderMaintenanceSection();
  if (typeof renderEIMTable === 'function') renderEIMTable();
  if (typeof renderDashboard === 'function') renderDashboard();
};

window.decideMaintenance = async function(decision) {
  const taskId = document.getElementById('mnt-modal-task-id')?.value;
  if (!taskId) return;
  const task = (window.maintenanceTasks || []).find(t => t.id === taskId);
  if (!task) return;

  const asset = (EIM_ASSETS || []).find(a => (a.supabaseId === task.equipment_id || a.id === task.equipment_id || a.asset_id === task.equipment_id));
  const assetId = asset ? (asset.asset_id || asset.id) : task.equipment_id;

  if (decision === 'repair') {
    const revEl = document.getElementById('mnt-review-actions');
    const logEl = document.getElementById('mnt-log-form');
    if (revEl) revEl.style.display = 'none';
    if (logEl) logEl.style.display = 'block';
  } else if (decision === 'retire') {
    if (confirm('Are you sure you want to retire this item? It will be archived to retired disposed equipment.')) {
      if (typeof retireMaintenanceEquipment === 'function') {
        await retireMaintenanceEquipment(task.routine_check_id || task.id, assetId);
      }
      if (typeof closeMaintenanceModal === 'function') closeMaintenanceModal();
    }
  } else if (decision === 'missing') {
    if (confirm('Mark this equipment as missing? It will be removed from active circulation.')) {
      if (typeof markMaintenanceEquipmentMissing === 'function') {
        await markMaintenanceEquipmentMissing(task.id, assetId);
      }
      if (typeof closeMaintenanceModal === 'function') closeMaintenanceModal();
    }
  }
};


// Auto-schedules contract finalization meeting for any semi-approved / pending reservation that has a chosen meeting slot
async function autoSchedulePendingReservationMeetings() {
  if (!Array.isArray(RESERVATIONS) || RESERVATIONS.length === 0) return;
  const meetings = Array.isArray(MEETINGS) ? MEETINGS : [];
  const sb = window.supabaseClient || window.supabase;

  for (const res of RESERVATIONS) {
    const st = String(res.status || '').toLowerCase().trim();
    if (st === 'cancelled' || st === 'rejected') continue;
    
    // Check if contract finalization is already scheduled
    const hasScheduled = meetings.some(m => {
      const rId = String(m.reservationId || m.reservation_id || '');
      const stM = String(m.status || '').toLowerCase();
      const topic = String(m.topic || m.agenda || '').toLowerCase();
      return rId === String(res.id) && stM !== 'cancelled' && topic.includes('contract');
    });
    if (hasScheduled) continue;

    // Check if customer chose a meeting slot
    const rawTimes = res.meeting_times || res.proposedMeetingTimes || res.proposed_meeting_times;
    let times = rawTimes;
    if (typeof times === 'string') {
      try { times = JSON.parse(times); } catch (e) { times = []; }
    }
    if (!Array.isArray(times) || times.length === 0) continue;

    const chosen = times[0];
    if (!chosen || !chosen.date) continue;

    const dateIso = (typeof _normalizeDateKey === 'function' ? _normalizeDateKey(chosen.date) : null) || chosen.date;
    const startTime = chosen.start || (chosen.time ? chosen.time.split(' to ')[0] : '1:00 PM');
    const endTime = chosen.end || (chosen.time && chosen.time.includes(' to ') ? chosen.time.split(' to ')[1] : '5:00 PM');
    const pkgName = res.packageName || res.package_name || 'Custom Package';
    const clientName = res.client || res.client_name || 'Client';

    const isUuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
    const meetingUid = (typeof crypto !== 'undefined' && crypto.randomUUID) ? crypto.randomUUID() : ('mt_' + Date.now());

    const autoMeeting = {
      id: meetingUid,
      reservationId: String(res.id),
      packageName: pkgName,
      package_name: pkgName,
      topic: `${pkgName} - Contract finalization`,
      agenda: 'Contract finalization',
      status: 'scheduled',
      date: dateIso,
      time: startTime,
      timeEnd: endTime,
      time_end: endTime,
      clientName: clientName,
      customerName: clientName,
      customerEmail: res.email || res.client_email || '',
      created_at: new Date().toISOString()
    };
    if (isUuidPattern.test(String(res.id))) {
      autoMeeting.reservation_id = String(res.id);
    }

    if (sb) {
      try {
        await sb.from('meetings').insert(autoMeeting);
      } catch (e) {}
    }
    MEETINGS.push(autoMeeting);
    window.MEETINGS = MEETINGS;
  }
}
window.autoSchedulePendingReservationMeetings = autoSchedulePendingReservationMeetings;


// ===== RESERVATION LOGS & AUDIT TRAIL TAB (ADMIN) =====
window._resdAdminLogsPage = 1;

window.changeResdAdminLogsPage = function(delta) {
  window._resdAdminLogsPage = Math.max(1, (window._resdAdminLogsPage || 1) + delta);
  if (typeof renderResdLogsTab === 'function') renderResdLogsTab();
};

window.renderResdLogsTab = function() {
  const container = document.getElementById('resd-admin-logs-content');
  if (!container) return;

  const res = (typeof RESERVATIONS !== 'undefined' ? RESERVATIONS : []).find(r => r.id === activeResDetailId || String(r.id) === String(activeResDetailId));
  if (!res) {
    container.innerHTML = '<div style="text-align:center; padding:50px 20px; color:var(--text-dim); font-size:13px;">Please select an active reservation to view its logs.</div>';
    return;
  }

  const resIdStr = String(res.id);
  const combinedLogs = [];

  // 1. Modification history (combines res.activity_logs from Supabase, res.modification_history, and local storage)
  let modHist = [];
  if (Array.isArray(res.activity_logs)) modHist.push(...res.activity_logs);
  if (Array.isArray(res.modification_history)) {
    res.modification_history.forEach(m => {
      if (!modHist.some(ex => ex.id === m.id || (ex.timestamp === m.timestamp && ex.details === m.details))) {
        modHist.push(m);
      }
    });
  }
  if (res.execution_plan && Array.isArray(res.execution_plan.modification_history)) {
    res.execution_plan.modification_history.forEach(m => {
      if (!modHist.some(ex => ex.id === m.id || (ex.timestamp === m.timestamp && ex.details === m.details))) {
        modHist.push(m);
      }
    });
  }
  try {
    const rawLocal = localStorage.getItem('halden_res_mod_history_' + resIdStr);
    if (rawLocal) {
      const parsedLocal = JSON.parse(rawLocal);
      if (Array.isArray(parsedLocal)) {
        parsedLocal.forEach(pl => {
          if (!modHist.some(m => m.id === pl.id || (m.timestamp === pl.timestamp && m.summary === pl.summary))) {
            modHist.push(pl);
          }
        });
      }
    }
  } catch (e) {}

  modHist.forEach(m => {
    combinedLogs.push({
      id: m.id || ('mod-' + Math.random()),
      timestamp: m.timestamp || new Date().toISOString(),
      date_str: m.date_str || new Date(m.timestamp || Date.now()).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' }),
      time_str: m.time_str || new Date(m.timestamp || Date.now()).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true }),
      modified_by: m.modified_by || 'Admin',
      action: 'Package / Reservation Modification',
      badge_color: m.modified_by === 'Customer' ? 'var(--blue, #3b82f6)' : 'var(--gold, #c49a3c)',
      items_added: m.items_added || [],
      items_removed: m.items_removed || [],
      items_customized: m.items_customized || [],
      field_changes: m.field_changes || [],
      details: m.summary || 'Reservation details updated.'
    });
  });

  // 2. Logging of Activities in Logistics Timeline (completed tasks)
  const timelineTasks = Array.isArray(res.timelineTasks) ? res.timelineTasks : [];
  timelineTasks.forEach((t, tIdx) => {
    if (t.status === 'done' || t.autoCheck) {
      const logTime = t.logAt ? new Date(t.logAt) : (t.date ? new Date(t.date + 'T09:00:00') : new Date());
      combinedLogs.push({
        id: 'timeline-' + (t.id || tIdx),
        timestamp: isNaN(logTime.getTime()) ? new Date().toISOString() : logTime.toISOString(),
        date_str: isNaN(logTime.getTime()) ? (t.date || '—') : logTime.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' }),
        time_str: isNaN(logTime.getTime()) ? '' : logTime.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true }),
        modified_by: 'Logistics / Operations',
        action: 'Logistics Activity Completed',
        badge_color: 'var(--green, #22c55e)',
        items_added: [],
        items_removed: [],
        items_customized: [],
        field_changes: [],
        details: `Milestone: ${(t.milestoneId || 'Logistics Preparation').toUpperCase()} — "${t.title || 'Operational Task'}" completed and verified.`
      });
    }
  });

  // 3. Admin Activity Logs from global store filtered STRICTLY for this reservation only (never broad client match)
  const globalLogs = (window.ADMIN_ACTIVITY_LOGS || []).filter(l => {
    if (!l) return false;
    if (l.reservation_id && (String(l.reservation_id) === resIdStr || l.reservation_id === res.id)) return true;
    const det = String(l.details || '');
    return det.includes('#' + resIdStr) || det.includes(resIdStr);
  });

  globalLogs.forEach(gl => {
    const logTime = gl.time ? new Date(gl.time) : (gl.created_at ? new Date(gl.created_at) : new Date());
    // Avoid exact duplicate with modHist
    if (!combinedLogs.some(c => c.timestamp === gl.time && c.details === gl.details)) {
      combinedLogs.push({
        id: gl.id || ('act-' + Math.random()),
        timestamp: isNaN(logTime.getTime()) ? new Date().toISOString() : logTime.toISOString(),
        date_str: isNaN(logTime.getTime()) ? '—' : logTime.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' }),
        time_str: isNaN(logTime.getTime()) ? '' : logTime.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true }),
        modified_by: gl.admin_name || gl.actor || 'Admin',
        action: gl.action || 'Activity Log',
        badge_color: 'var(--gold, #c49a3c)',
        items_added: [],
        items_removed: [],
        items_customized: [],
        field_changes: [],
        details: gl.details || 'Operational activity logged.'
      });
    }
  });

  // Sort chronologically descending
  combinedLogs.sort((a, b) => new Date(b.timestamp) - new Date(a.timestamp));

  // Sync to database if reservation in Supabase has empty activity_logs
  if (combinedLogs.length > 0 && (!res.activity_logs || res.activity_logs.length === 0) && window.supabaseClient && res.id) {
    res.activity_logs = combinedLogs;
    window.supabaseClient.from('reservations').update({ activity_logs: combinedLogs }).eq('id', res.id).then(() => {}).catch(() => {});
  }

  if (combinedLogs.length === 0) {
    container.innerHTML = `
      <div style="text-align:center; padding:50px 20px; color:var(--text-dim);">
        <div style="font-size:15px; font-weight:600; color:var(--cream);">No Logs Recorded Yet</div>
        <div style="font-size:12px; margin-top:6px;">Package modifications and completed logistics tasks will be tracked here automatically.</div>
      </div>`;
    return;
  }

  // 20 rows per page pagination
  const pageSize = 20;
  const totalLogs = combinedLogs.length;
  const totalPages = Math.ceil(totalLogs / pageSize);
  let currentPage = window._resdAdminLogsPage || 1;
  if (currentPage > totalPages) currentPage = totalPages;
  if (currentPage < 1) currentPage = 1;
  window._resdAdminLogsPage = currentPage;

  const startIdx = (currentPage - 1) * pageSize;
  const endIdx = Math.min(startIdx + pageSize, totalLogs);
  const pagedLogs = combinedLogs.slice(startIdx, endIdx);

  const rowsHtml = pagedLogs.map((log, rowIdx) => {
    let changeBreakdownHtml = '';
    const parts = [];

    if (log.field_changes && log.field_changes.length > 0) {
      log.field_changes.forEach(fc => {
        parts.push(`<div style="margin-bottom:4px; font-size:12px; color:var(--text, #f0e8d8); line-height:1.4;"><span style="font-weight:700; color:var(--cream, #fff);">&bull; </span>${escHtml(fc)}</div>`);
      });
    }
    if (log.items_added && log.items_added.length > 0) {
      parts.push(`<div style="margin-bottom:4px; font-size:12px; color:#22c55e; line-height:1.4;"><span style="font-weight:700;">&bull; Added Items: </span>${escHtml(log.items_added.join(', '))}</div>`);
    }
    if (log.items_removed && log.items_removed.length > 0) {
      parts.push(`<div style="margin-bottom:4px; font-size:12px; color:#ef4444; line-height:1.4;"><span style="font-weight:700;">&bull; Removed Items: </span>${escHtml(log.items_removed.join(', '))}</div>`);
    }
    if (log.items_customized && log.items_customized.length > 0) {
      log.items_customized.forEach(c => {
        parts.push(`<div style="margin-bottom:4px; font-size:12px; color:var(--gold, #c49a3c); line-height:1.4;"><span style="font-weight:700;">&bull; Customization: </span>${escHtml(c)}</div>`);
      });
    }

    if (parts.length > 0) {
      changeBreakdownHtml = parts.join('');
    } else {
      changeBreakdownHtml = `<div style="color:var(--text-dim);">${escHtml(log.details)}</div>`;
    }

    return `
      <tr style="border-bottom:1px solid rgba(255,255,255,0.05); font-size:12px; transition:background 0.15s;" onmouseover="this.style.background='rgba(255,255,255,0.02)'" onmouseout="this.style.background='transparent'">
        <td style="padding:12px 14px; white-space:nowrap; vertical-align:top;">
          <div style="font-weight:700; color:var(--cream);">${escHtml(log.date_str)}</div>
          <div style="font-family:monospace; font-size:11px; color:var(--text-dim); margin-top:2px;">${escHtml(log.time_str || '—')}</div>
        </td>
        <td style="padding:12px 14px; white-space:nowrap; vertical-align:top;">
          <span style="font-weight:700; color:${log.badge_color}; font-size:12px;">${escHtml(log.modified_by)}</span>
        </td>
        <td style="padding:12px 14px; white-space:nowrap; vertical-align:top; font-weight:600; color:var(--cream);">
          ${escHtml(log.action)}
        </td>
        <td style="padding:12px 14px; vertical-align:top; line-height:1.45;">
          ${changeBreakdownHtml}
        </td>
      </tr>`;
  }).join('');

  container.innerHTML = `
    <div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:14px; flex-wrap:wrap; gap:10px;">
      <div style="font-size:13px; color:var(--text-dim);">
        Showing <strong style="color:var(--cream);">${startIdx + 1} - ${endIdx}</strong> of <strong style="color:var(--cream);">${totalLogs}</strong> logs
      </div>
      <div style="display:flex; align-items:center; gap:8px;">
        <button class="btn-outline" onclick="changeResdAdminLogsPage(-1)" ${currentPage <= 1 ? 'disabled style="opacity:0.4; cursor:not-allowed;"' : 'style="cursor:pointer;"'} style="padding:5px 12px; font-size:11.5px; font-weight:700; border-radius:6px; border:1px solid var(--border); background:var(--bg3); color:var(--cream);">
          Previous
        </button>
        <span style="font-size:12px; color:var(--text-dim); font-weight:600;">
          Page ${currentPage} of ${totalPages}
        </span>
        <button class="btn-outline" onclick="changeResdAdminLogsPage(1)" ${currentPage >= totalPages ? 'disabled style="opacity:0.4; cursor:not-allowed;"' : 'style="cursor:pointer;"'} style="padding:5px 12px; font-size:11.5px; font-weight:700; border-radius:6px; border:1px solid var(--border); background:var(--bg3); color:var(--cream);">
          Next
        </button>
      </div>
    </div>
    <div style="border:1px solid var(--border); border-radius:8px; overflow-x:auto;">
      <table style="width:100%; border-collapse:collapse; text-align:left;">
        <thead>
          <tr style="background:rgba(0,0,0,0.25); border-bottom:1px solid var(--border);">
            <th style="padding:10px 14px; font-size:11px; font-weight:700; color:var(--text-dim); text-transform:uppercase; letter-spacing:0.5px;">Date &amp; Time</th>
            <th style="padding:10px 14px; font-size:11px; font-weight:700; color:var(--text-dim); text-transform:uppercase; letter-spacing:0.5px;">Modified By</th>
            <th style="padding:10px 14px; font-size:11px; font-weight:700; color:var(--text-dim); text-transform:uppercase; letter-spacing:0.5px;">Activity / Action</th>
            <th style="padding:10px 14px; font-size:11px; font-weight:700; color:var(--text-dim); text-transform:uppercase; letter-spacing:0.5px;">Details of Changes</th>
          </tr>
        </thead>
        <tbody>
          ${rowsHtml}
        </tbody>
      </table>
    </div>
    <div style="display:flex; justify-content:space-between; align-items:center; margin-top:14px; font-size:12px; color:var(--text-dim);">
      <span>Paging limit: 20 rows per page</span>
      <span>Total: ${totalLogs} recorded logs</span>
    </div>`;
};

window.switchResdInnerTab = function(tab) {
  const isDashboard = tab !== 'logs';
  const dashBtn = document.getElementById('resd-inner-tab-dashboard');
  const logsBtn = document.getElementById('resd-inner-tab-logs');
  const dashContent = document.getElementById('resd-content');
  const logsContent = document.getElementById('resd-admin-logs-content');
  const modBtn = document.getElementById('resd-btn-modify-pkg');
  const cancelContainer = document.getElementById('resd-biz-cancel-amt-container');
  const saveModBtn = document.getElementById('resd-btn-save-mod');

  if (dashBtn) {
    dashBtn.classList.toggle('active', isDashboard);
    dashBtn.style.color = isDashboard ? 'var(--gold, #c49a3c)' : 'var(--text-dim, #999)';
    dashBtn.style.borderBottom = isDashboard ? '2px solid var(--gold, #c49a3c)' : '2px solid transparent';
  }
  if (logsBtn) {
    logsBtn.classList.toggle('active', !isDashboard);
    logsBtn.style.color = !isDashboard ? 'var(--gold, #c49a3c)' : 'var(--text-dim, #999)';
    logsBtn.style.borderBottom = !isDashboard ? '2px solid var(--gold, #c49a3c)' : '2px solid transparent';
  }

  if (dashContent) dashContent.style.display = isDashboard ? 'block' : 'none';
  if (logsContent) logsContent.style.display = !isDashboard ? 'block' : 'none';

  if (modBtn) modBtn.style.display = isDashboard ? 'inline-block' : 'none';
  if (cancelContainer) cancelContainer.style.display = (isDashboard && activeResDetailId) ? 'flex' : 'none';
  if (!isDashboard && saveModBtn) saveModBtn.style.display = 'none';

  if (!isDashboard && typeof renderResdLogsTab === 'function') {
    renderResdLogsTab();
  }
};
